namespace Vibranium.Self;

public readonly struct VarBinding
{
    public readonly int NameId;
    public readonly int LocalId;
    public readonly int ScopeDepth;
    public readonly int IsConst;
    public readonly int ConstTypeId;
    public readonly long ConstVal;

    public VarBinding(int nameId, int localId, int scopeDepth, int isConst, int constTypeId, long constVal)
    {
        NameId = nameId;
        LocalId = localId;
        ScopeDepth = scopeDepth;
        IsConst = isConst;
        ConstTypeId = constTypeId;
        ConstVal = constVal;
    }
}

// The natural type of one arm of a conditional or switch expression, and the
// bindings its inference had in scope for that arm (N106).
public readonly struct BranchArmFact
{
    public readonly int TypeId;
    public readonly int ScopeStart;
    public readonly int ScopeCount;
    public readonly int ScopeCap;

    public BranchArmFact(int typeId, int scopeStart, int scopeCount, int scopeCap)
    {
        TypeId = typeId;
        ScopeStart = scopeStart;
        ScopeCount = scopeCount;
        ScopeCap = scopeCap;
    }
}

public readonly struct ScopeEntry
{
    public readonly int ScopeDepth;
    public readonly int LocalId;
    public readonly int IsUsing;
    public readonly int DisposeInstId;
    public readonly int TokIdx;

    public ScopeEntry(int scopeDepth, int localId, int isUsing, int disposeInstId, int tokIdx)
    {
        ScopeDepth = scopeDepth;
        LocalId = localId;
        IsUsing = isUsing;
        DisposeInstId = disposeInstId;
        TokIdx = tokIdx;
    }
}

public readonly struct LoopFrame
{
    public readonly int BreakBlock;
    public readonly int ContinueBlock;
    public readonly int BreakScopeDepth;
    public readonly int ContinueScopeDepth;

    public LoopFrame(int breakBlock, int continueBlock, int breakScopeDepth, int continueScopeDepth)
    {
        BreakBlock = breakBlock;
        ContinueBlock = continueBlock;
        BreakScopeDepth = breakScopeDepth;
        ContinueScopeDepth = continueScopeDepth;
    }
}

public struct FuncLowerCtx
{
    public int FuncInstId;
    public int FuncDeclId;
    public int EnclosingOwnerDeclId;
    public int OwnerTypeId;
    public int ReturnTypeId;
    public bool IsCtor;
    public bool ReturnsByRef;
    public bool ReturnRefMut;
    public bool EnqueueUncalledLocalFuncs;
    public bool CheckSourcePatternWarnings;
    public bool HasGenericPatternCut;
    public int ThisLocalId;

    public Vec<int> TpNames;
    public Vec<int> TpVals;
    public Vec<int> CtorFieldLocals;
    public Vec<int> VisibleLocalFuncs;

    public Vec<MirLocal> Locals;
    // Source-only iteration-variable mutability; MIR loan/disposal identity is unchanged.
    public Vec<byte> SourceReadonlyLocals;
    public Vec<VarBinding> Vars;
    public Vec<VarBinding> EnclosingBindings;
    public Vec<int> HoistedConstantTokens;
    public Vec<int> SwitchLocalTokens;
    public Vec<int> SwitchLocalIds;
    public Vec<ScopeEntry> ScopeStack;
    public Vec<LoopFrame> Loops;
    public int ScopeDepth;
    public int StackSpanCounter;

    // Per-block instruction linked lists
    public Vec<int> BlockHead;
    public Vec<int> BlockTail;
    public Vec<MirTerm> BlockTerms;
    // Source reachability differs from optimized MIR (nonconstant conditions and noreturn calls).
    public Vec<MirTerm> SourceBlockTerms;
    public Vec<MirTerm> SourceAssignmentTerms;
    public int SourceConstantPatternPlace;
    public int SourcePatternInputToken;
    public ulong SourceConstantPatternValue;
    public bool SourceConstantPatternNaN;
    // C# source-only analysis metadata; never changes emitted runtime MIR.
    public Vec<int> PanicContinuations;
    public Vec<int> LocalScopeDepths;
    public Vec<int> LocalInitializerInsts;
    public Vec<int> SourceSwitchSectionEnds;
    public Vec<SourceSwitchFlow> SourceSwitchFlows;
    public Vec<SourceSwitchAssignmentEdge> SourceSwitchContinuations;
    public Vec<int> SourceSwitchTargets;
    public Vec<int> SourceSwitchBodies;
    public Vec<int> SourceStackSpanContexts;
    public Vec<MirInst> StagedInsts;
    public Vec<int> StagedNext;
    public int CurBlock;
    public int OutVarScopeOverride;
    // True while an instance field initializer is lowered: it has no `this` (CS0236, CS0027).
    public bool InFieldInitializer;
    public int UncheckedDepth;
    public int InferDepth;
    // > 0 while the conversion classifier types a collection-literal element
    // again for one candidate type: no operand is visited for its declarations
    // only (they are lost with the element, N115; a visit per candidate is N112).
    public int ElementRetypeDepth;
    // Arm facts of the last natural-type inference of each conditional and
    // switch expression; a conversion to a target type reads them (N106).
    public IntMap<int> BranchFactSlots;
    public Vec<BranchArmFact> BranchArmFacts;
    public Vec<VarBinding> BranchArmScopes;
    public bool ForbidDirectUtf8ArgEnumNew;
    public Vec<int> ChildDeclNameIds;
    public Vec<int> ChildDeclDepths;

    public FuncLowerCtx(int funcInstId, int funcDeclId, int ownerTypeId, int returnTypeId, bool isCtor, bool returnsByRef, bool returnRefMut)
    {
        FuncInstId = funcInstId;
        FuncDeclId = funcDeclId;
        EnclosingOwnerDeclId = -1;
        OwnerTypeId = ownerTypeId;
        ReturnTypeId = returnTypeId;
        IsCtor = isCtor;
        ReturnsByRef = returnsByRef;
        ReturnRefMut = returnRefMut;
        EnqueueUncalledLocalFuncs = false;
        ThisLocalId = -1;

        TpNames = new Vec<int>();
        TpVals = new Vec<int>();
        CtorFieldLocals = new Vec<int>();
        VisibleLocalFuncs = new Vec<int>();

        Locals = new Vec<MirLocal>(16);
        SourceReadonlyLocals = new Vec<byte>(16);
        Vars = new Vec<VarBinding>(16);
        EnclosingBindings = new Vec<VarBinding>();
        HoistedConstantTokens = new Vec<int>();
        SwitchLocalTokens = new Vec<int>();
        SwitchLocalIds = new Vec<int>();
        ScopeStack = new Vec<ScopeEntry>(16);
        Loops = new Vec<LoopFrame>(4);
        ScopeDepth = 0;
        StackSpanCounter = 0;

        BlockHead = new Vec<int>(8);
        BlockTail = new Vec<int>(8);
        BlockTerms = new Vec<MirTerm>(8);
        SourceBlockTerms = new Vec<MirTerm>(8);
        SourceAssignmentTerms = new Vec<MirTerm>(8);
        SourceConstantPatternPlace = -1;
        SourcePatternInputToken = -1;
        SourceConstantPatternValue = 0UL;
        SourceConstantPatternNaN = false;
        PanicContinuations = new Vec<int>(8);
        LocalScopeDepths = new Vec<int>(16);
        LocalInitializerInsts = new Vec<int>(16);
        SourceSwitchSectionEnds = new Vec<int>();
        SourceSwitchFlows = new Vec<SourceSwitchFlow>();
        SourceSwitchContinuations = new Vec<SourceSwitchAssignmentEdge>();
        SourceSwitchTargets = new Vec<int>();
        SourceSwitchBodies = new Vec<int>();
        SourceStackSpanContexts = new Vec<int>();
        StagedInsts = new Vec<MirInst>(64);
        StagedNext = new Vec<int>(64);
        CurBlock = -1;
        OutVarScopeOverride = -1;
        InFieldInitializer = false;
        UncheckedDepth = 0;
        InferDepth = 0;
        ElementRetypeDepth = 0;
        BranchFactSlots = new IntMap<int>(0);
        BranchArmFacts = new Vec<BranchArmFact>();
        BranchArmScopes = new Vec<VarBinding>();
        ForbidDirectUtf8ArgEnumNew = false;
        ChildDeclNameIds = new Vec<int>();
        ChildDeclDepths = new Vec<int>();
    }

    public void LeaveSpeculativeInfer()
    {
        InferDepth -= 1;
        if (InferDepth <= 0)
        {
            InferDepth = 0;
            int writeIdx = 0;
            for (int i = 0; i < Vars.Count; i++)
            {
                VarBinding vb = Vars[i];
                if (vb.LocalId != -2)
                {
                    Vars[writeIdx] = vb;
                    writeIdx += 1;
                }
            }
            Vars.Truncate(writeIdx);
        }
    }

    // The arm slots of a conditional (two) or a switch expression (one per arm).
    // Every inference of the same expression writes the same slots.
    public int BranchFactsFor(int exprId, int armCount)
    {
        int entry = BranchFactSlots.Find(exprId);
        if (entry >= 0) return BranchFactSlots.ValueAt(entry);
        int slot = BranchArmFacts.Count;
        for (int i = 0; i < armCount; i++) BranchArmFacts.Push(new BranchArmFact(TypeIds.Error, 0, 0, 0));
        _ = BranchFactSlots.Set(exprId, slot);
        return slot;
    }

    // Vars[scopeStart..scopeEnd) are the bindings the expression's inference had
    // pushed when it reached this arm.
    public void RecordBranchArm(int slot, int typeId, int scopeStart, int scopeEnd)
    {
        BranchArmFact old = BranchArmFacts[slot];
        int count = scopeEnd - scopeStart;
        int start = old.ScopeStart;
        int cap = old.ScopeCap;
        if (count > cap)
        {
            start = BranchArmScopes.Count;
            cap = count;
            for (int i = 0; i < count; i++) BranchArmScopes.Push(Vars[scopeStart + i]);
        }
        else
        {
            for (int i = 0; i < count; i++) BranchArmScopes[start + i] = Vars[scopeStart + i];
        }
        BranchArmFacts[slot] = new BranchArmFact(typeId, start, count, cap);
    }

    public int NewBlock()
    {
        int b = BlockHead.Count;
        BlockHead.Push(-1);
        BlockTail.Push(-1);
        BlockTerms.Push(new MirTerm(MirTermKind.Unset, 0, 0, 0, 0, 0, 0, 0));
        SourceBlockTerms.Push(new MirTerm(MirTermKind.Unset, 0, 0, 0, 0, 0, 0, 0));
        SourceAssignmentTerms.Push(new MirTerm(MirTermKind.Unset, 0, 0, 0, 0, 0, 0, 0));
        PanicContinuations.Push(-1);
        return b;
    }

    public readonly bool IsBlockTerminated(int blk) =>
        BlockTerms[blk].Kind != MirTermKind.Unset;

    public void Emit(MirInst inst)
    {
        if (IsBlockTerminated(CurBlock))
        {
            return;
        }
        int idx = StagedInsts.Count;
        StagedInsts.Push(inst);
        StagedNext.Push(-1);
        int tail = BlockTail[CurBlock];
        if (tail < 0)
        {
            BlockHead[CurBlock] = idx;
            BlockTail[CurBlock] = idx;
        }
        else
        {
            StagedNext[tail] = idx;
            BlockTail[CurBlock] = idx;
        }
    }

    public void EmitCall(MirInst inst, in MirModuleArena mir)
    {
        // Out declarations obtain their fixed C# safe-context from this call,
        // not from a nested call evaluated while lowering another argument.
        for (int a = 0; a < inst.C; a++)
        {
            MirCallArg arg = mir.CallArgs[inst.B + a];
            if (arg.Mode != PassMode.Out) continue;
            MirPlace place = mir.Places[arg.OperandOrPlaceId];
            if (place.ProjCount == 0 && LocalInitializerInsts[place.LocalId] == -2)
            {
                LocalInitializerInsts[place.LocalId] = StagedInsts.Count;
            }
        }
        Emit(inst);
    }

    public void Terminate(MirTerm term)
    {
        if (!IsBlockTerminated(CurBlock))
        {
            BlockTerms[CurBlock] = term;
        }
    }

    public int AddLocal(int nameId, int typeId, PassMode mode, int flags, int tokIdx)
    {
        int id = Locals.Count;
        Locals.Push(new MirLocal(nameId, typeId, mode, flags, tokIdx));
        SourceReadonlyLocals.Push(0);
        LocalScopeDepths.Push((flags & MirLocalFlags.IsParam) != 0 ? 0 : ScopeDepth);
        LocalInitializerInsts.Push(-1);
        return id;
    }

    public int NewTemp(int typeId, int tokIdx, ref MirModuleArena mir)
    {
        int lid = AddLocal(-1, typeId, PassMode.ByValue, MirLocalFlags.IsTemp, tokIdx);
        // Anonymous storage belongs to the method frame, including temporaries
        // created in conditional arms. Its loan may remain live after the arm's
        // lexical scope ends. Named locals still retain lexical storage lifetime.
        LocalScopeDepths[lid] = 1;
        int insertAt = ScopeStack.Count;
        while (insertAt > 0 && ScopeStack[insertAt - 1].ScopeDepth > 1) insertAt -= 1;
        var entry = new ScopeEntry(1, lid, 0, -1, tokIdx);
        ScopeStack.Push(entry);
        for (int i = ScopeStack.Count - 1; i > insertAt; i--) ScopeStack[i] = ScopeStack[i - 1];
        ScopeStack[insertAt] = entry;
        return lid;
    }

    // A hidden loop loan is a lexical guard, not an anonymous owner value.
    // Its cleanup must release the enumeration borrow when the loop exits.
    public int NewLexicalLoan(int typeId, int tokIdx)
    {
        int lid = AddLocal(-1, typeId, PassMode.ByValue, MirLocalFlags.IsTemp, tokIdx);
        ScopeStack.Push(new ScopeEntry(ScopeDepth, lid, 0, -1, tokIdx));
        return lid;
    }

    public int NewTempRef(int targetTypeId, bool isMut, int tokIdx)
    {
        int rFlags = MirLocalFlags.IsTemp | MirLocalFlags.IsRefLocal | (isMut ? MirLocalFlags.IsRefMut : 0);
        return AddLocal(-1, targetTypeId, PassMode.ByValue, rFlags, tokIdx);
    }

    public readonly int FindVar(int nameId, out bool isConst, out int constTypeId, out long constVal)
    {
        for (int i = Vars.Count - 1; i >= 0; i--)
        {
            VarBinding vb = Vars[i];
            if (vb.NameId == nameId)
            {
                isConst = vb.IsConst != 0;
                constTypeId = vb.ConstTypeId;
                constVal = vb.ConstVal;
                return vb.LocalId;
            }
        }
        for (int i = EnclosingBindings.Count - 1; i >= 0; i--)
        {
            VarBinding vb = EnclosingBindings[i];
            if (vb.NameId == nameId)
            {
                isConst = vb.IsConst != 0;
                constTypeId = vb.ConstTypeId;
                constVal = vb.ConstVal;
                return vb.LocalId;
            }
        }
        isConst = false;
        constTypeId = TypeIds.I32;
        constVal = 0;
        return -1;
    }
}

public static class FuncLowerer
{
    public static void LowerAllReachable(
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        var emptyConstTp = new Vec<int>();
        for (int t = 0; t < ast.Types.Count; t++)
        {
            TypeDecl td = ast.Types[t];
            if ((!bctx.CompilingStdItself && td.UnitKind == UnitKinds.Std) || td.Kind == TypeDeclKinds.Enum || td.TypeParamCount > 0) continue;
            for (int f = 0; f < td.FieldCount; f++)
            {
                FieldDecl fld = ast.Fields[td.FieldStart + f];
                if ((fld.Flags & DeclFlags.IsConst) != 0 && fld.InitExpr >= 0)
                {
                    int fType = DeclBinder.ResolveTypeNode(fld.TypeNode, emptyConstTp.AsReadOnlySpan(), emptyConstTp.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                    ValidateConstFieldInit(t, fType, fld.InitExpr, fld.TokIdx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                }
            }
        }

        // Source patterns on T must be checked before monomorphization can
        // turn implicit runtime type tests into invalid numeric comparisons.
        var genericPatternCuts = new Vec<int>();
        CheckUninstantiatedOpenGenerics(in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, ref genericPatternCuts);

        while (bctx.NextFuncWorkCursor < bctx.FuncWorkQueue.Count)
        {
            int instId = bctx.FuncWorkQueue[bctx.NextFuncWorkCursor];
            bctx.NextFuncWorkCursor += 1;

            if (mir.FuncInstances[instId].MirFuncIdx >= 0) continue;
            bool sourcePatternCut = false;
            for (int i = 0; i < genericPatternCuts.Count; i++)
            {
                if (genericPatternCuts[i] == mir.FuncInstances[instId].FuncDeclId) sourcePatternCut = true;
            }
            if (sourcePatternCut) continue;
            _ = LowerFunctionInstance(instId, emitToModule: true, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            DeclBinder.DrainConcreteTypeQueue(in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
        }

    }

    private static void CheckUninstantiatedOpenGenerics(
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        ref Vec<int> genericPatternCuts)
    {
        for (int t = 0; t < ast.Types.Count; t++)
        {
            TypeDecl td = ast.Types[t];
            if (!bctx.CompilingStdItself && td.UnitKind == UnitKinds.Std) continue;
            if (td.Kind == TypeDeclKinds.Enum) continue;

            for (int m = 0; m < td.FuncCount; m++)
            {
                int fId = td.FuncStart + m;
                FuncDecl fd = ast.Funcs[fId];
                if (fd.BodyNode < 0) continue;
                if (td.TypeParamCount == 0 && fd.TypeParamCount == 0) continue;



                var ownerArgs = new Vec<int>(td.TypeParamCount);
                for (int i = 0; i < td.TypeParamCount; i++)
                {
                    int tpName = ast.Extra[td.TypeParamStart + i];
                    ownerArgs.Push(types.MakeTypeParam(tpName, names.Text(tpName), ast.Extra[td.TypeParamFlagsStart + i]));
                }
                int ownerTid = -1;
                if ((td.Flags & DeclFlags.Static) == 0 || td.TypeParamCount > 0)
                {
                    int tk = td.Kind == TypeDeclKinds.Class ? TypeKinds.Class : TypeKinds.Struct;
                    ownerTid = types.MakeUserType(tk, t, names.Text(td.NameId), ownerArgs.AsReadOnlySpan());
                }

                var mArgs = new Vec<int>(fd.TypeParamCount);
                for (int i = 0; i < fd.TypeParamCount; i++)
                {
                    int tpName = ast.Extra[fd.TypeParamStart + i];
                    mArgs.Push(types.MakeTypeParam(tpName, names.Text(tpName), ast.Extra[fd.TypeParamFlagsStart + i]));
                }

                DeclBinder.DrainConcreteTypeQueue(in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                int openInstId = DeclBinder.EnsureFuncInstance(fId, ownerTid, mArgs.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                if (openInstId >= 0)
                {
                    if (LowerFunctionInstance(openInstId, emitToModule: false, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags))
                        genericPatternCuts.Push(fId);
                }
            }
        }

        for (int f = 0; f < ast.Funcs.Count; f++)
        {
            FuncDecl fd = ast.Funcs[f];
            if ((fd.Flags & DeclFlags.IsLocalFunc) == 0 || fd.BodyNode < 0 || fd.TypeParamCount == 0) continue;
            if (!bctx.CompilingStdItself && fd.OwnerDeclId >= 0 && ast.Types[fd.OwnerDeclId].UnitKind == UnitKinds.Std) continue;
            var mArgs = new Vec<int>(fd.TypeParamCount);
            for (int i = 0; i < fd.TypeParamCount; i++)
            {
                int mTpName = ast.Extra[fd.TypeParamStart + i];
                mArgs.Push(types.MakeTypeParam(mTpName, names.Text(mTpName), ast.Extra[fd.TypeParamFlagsStart + i]));
            }
            int openInstId = DeclBinder.EnsureFuncInstance(f, -1, mArgs.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
            if (openInstId >= 0)
            {
                if (LowerFunctionInstance(openInstId, emitToModule: false, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags))
                    genericPatternCuts.Push(f);
            }
        }
    }

    private static void CollectEnclosingLocalFuncsAndOwner(
        int targetLfId,
        in AstArena ast,
        ref Vec<int> outVisible,
        out int outOwnerDeclId,
        out int outUncheckedDepth)
    {
        outOwnerDeclId = -1;
        outUncheckedDepth = 0;
        for (int pFn = 0; pFn < ast.Funcs.Count; pFn++)
        {
            FuncDecl pfd = ast.Funcs[pFn];
            if ((pfd.Flags & DeclFlags.IsLocalFunc) != 0) continue;

            int mark = outVisible.Count;
            bool directHit = false;
            for (int k = 0; k < pfd.LocalFuncCount; k++)
            {
                int lfId = ast.Extra[pfd.LocalFuncExtraStart + k];
                outVisible.Push(lfId);
                if (lfId == targetLfId) directHit = true;
            }
            if (directHit)
            {
                outOwnerDeclId = pfd.OwnerDeclId;
                return;
            }
            for (int k = 0; k < pfd.LocalFuncCount; k++)
            {
                int lfId = ast.Extra[pfd.LocalFuncExtraStart + k];
                int uDepth = 0;
                if (TryCollectEnclosingLocalFuncChain(ast.Funcs[lfId].BodyNode, targetLfId, in ast, ref outVisible, ref uDepth))
                {
                    outOwnerDeclId = pfd.OwnerDeclId;
                    outUncheckedDepth = uDepth;
                    return;
                }
            }
            int bodyUDepth = 0;
            if (TryCollectEnclosingLocalFuncChain(pfd.BodyNode, targetLfId, in ast, ref outVisible, ref bodyUDepth))
            {
                outOwnerDeclId = pfd.OwnerDeclId;
                outUncheckedDepth = bodyUDepth;
                return;
            }
            outVisible.Truncate(mark);
        }
    }

    private static bool TryCollectEnclosingLocalFuncChain(
        int stmtId,
        int targetLfId,
        in AstArena ast,
        ref Vec<int> chain,
        ref int uncheckedDepth)
    {
        if (stmtId < 0) return false;
        AstNode n = ast.Nodes[stmtId];
        switch (n.Kind)
        {
            case AstKind.StmtUncheckedBlock:
            {
                uncheckedDepth += 1;
                if (TryCollectEnclosingLocalFuncChain(n.A, targetLfId, in ast, ref chain, ref uncheckedDepth))
                {
                    return true;
                }
                uncheckedDepth -= 1;
                return false;
            }
            case AstKind.StmtBlock:
            {
                int mark = chain.Count;
                bool foundHere = false;
                for (int i = 0; i < n.D; i++)
                {
                    int lfId = ast.Extra[n.C + i];
                    chain.Push(lfId);
                    if (lfId == targetLfId) foundHere = true;
                }
                if (foundHere) return true;
                for (int i = 0; i < n.D; i++)
                {
                    int lfId = ast.Extra[n.C + i];
                    if (TryCollectEnclosingLocalFuncChain(ast.Funcs[lfId].BodyNode, targetLfId, in ast, ref chain, ref uncheckedDepth))
                    {
                        return true;
                    }
                }
                for (int i = 0; i < n.B; i++)
                {
                    if (TryCollectEnclosingLocalFuncChain(ast.Extra[n.A + i], targetLfId, in ast, ref chain, ref uncheckedDepth))
                    {
                        return true;
                    }
                }
                chain.Truncate(mark);
                return false;
            }
            case AstKind.StmtMulti:
            {
                for (int i = 0; i < n.B; i++)
                {
                    if (TryCollectEnclosingLocalFuncChain(ast.Extra[n.A + i], targetLfId, in ast, ref chain, ref uncheckedDepth))
                    {
                        return true;
                    }
                }
                return false;
            }
            case AstKind.StmtIf:
                return TryCollectEnclosingLocalFuncChain(n.B, targetLfId, in ast, ref chain, ref uncheckedDepth) ||
                       TryCollectEnclosingLocalFuncChain(n.C, targetLfId, in ast, ref chain, ref uncheckedDepth);
            case AstKind.StmtWhile:
                return TryCollectEnclosingLocalFuncChain(n.B, targetLfId, in ast, ref chain, ref uncheckedDepth);
            case AstKind.StmtDoWhile:
                return TryCollectEnclosingLocalFuncChain(n.A, targetLfId, in ast, ref chain, ref uncheckedDepth);
            case AstKind.StmtFor:
                return TryCollectEnclosingLocalFuncChain(n.D, targetLfId, in ast, ref chain, ref uncheckedDepth);
            case AstKind.StmtForeach:
                return TryCollectEnclosingLocalFuncChain(n.D, targetLfId, in ast, ref chain, ref uncheckedDepth);
            case AstKind.StmtSwitch:
            {
                for (int s = 0; s < n.C; s++)
                {
                    AstNode sec = ast.Nodes[ast.Extra[n.B + s]];
                    for (int k = 0; k < sec.D; k++)
                    {
                        if (TryCollectEnclosingLocalFuncChain(ast.Extra[sec.C + k], targetLfId, in ast, ref chain, ref uncheckedDepth))
                        {
                            return true;
                        }
                    }
                }
                return false;
            }
            default:
                return false;
        }
    }

    private static void SeedEnclosingConstants(
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names,
        ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags)
    {
        if ((ast.Funcs[fctx.FuncDeclId].Flags & DeclFlags.IsLocalFunc) == 0) return;
        var bindings = new Vec<SourceLexicalBinding>();
        SourceLexicalScopeChecker.CollectEnclosingBindings(fctx.FuncDeclId, in ast, ref bindings);
        var constants = new FuncLowerCtx(fctx.FuncInstId, fctx.FuncDeclId, fctx.OwnerTypeId, TypeIds.Void, false, false, false);
        constants.EnclosingOwnerDeclId = fctx.EnclosingOwnerDeclId;
        constants.ScopeDepth = 1;
        constants.CurBlock = constants.NewBlock();
        for (int i = 0; i < fctx.TpNames.Count; i++)
        {
            constants.TpNames.Push(fctx.TpNames[i]);
            constants.TpVals.Push(fctx.TpVals[i]);
        }
        for (int i = 0; i < bindings.Count; i++)
        {
            SourceLexicalBinding binding = bindings[i];
            if (binding.Kind == 1 && binding.NodeId >= 0) continue;
            if (!SourceLexicalScopeChecker.IsConstant(in binding, in ast))
            {
                constants.EnclosingBindings.Push(new VarBinding(binding.NameId, -2, 0, 0, TypeIds.Void, 0));
                continue;
            }
            constants.FuncDeclId = binding.FunctionId;
            int mark = constants.Vars.Count;
            AstNode declaration = ast.Nodes[binding.NodeId];
            LowerVarDecl(in declaration, ref constants, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            if (constants.Vars.Count > mark)
            {
                VarBinding value = constants.Vars[constants.Vars.Count - 1];
                if (value.IsConst != 0) constants.EnclosingBindings.Push(new VarBinding(value.NameId, -1, 0, value.IsConst, value.ConstTypeId, value.ConstVal));
            }
            constants.Vars.Truncate(mark);
            constants.ChildDeclNameIds.Clear();
            constants.ChildDeclDepths.Clear();
        }
        for (int i = 0; i < constants.EnclosingBindings.Count; i++) fctx.EnclosingBindings.Push(constants.EnclosingBindings[i]);
    }

    private static bool LowerFunctionInstance(
        int instId,
        bool emitToModule,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        FuncInstance inst = mir.FuncInstances[instId];
        FuncDecl fd = ast.Funcs[inst.FuncDeclId];
        SourceLexicalScopeChecker.CheckFunction(inst.FuncDeclId, in ast, in ta, in names, ref diags);
        bool isCtor = (fd.Flags & DeclFlags.IsCtor) != 0;
        bool retByRef = !isCtor && (inst.Flags & DeclFlags.ReturnsByRef) != 0;
        bool retRefMut = !isCtor && (inst.Flags & DeclFlags.ReturnRefMut) != 0;

        var fctx = new FuncLowerCtx(instId, inst.FuncDeclId, inst.OwnerTypeId, inst.ReturnTypeId, isCtor, retByRef, retRefMut);

        // Populate type parameter substitution
        if (inst.OwnerTypeId >= 0)
        {
            TypeInfo oti = types.Items[inst.OwnerTypeId];
            TypeDecl otd = ast.Types[oti.A];
            for (int i = 0; i < otd.TypeParamCount; i++)
            {
                fctx.TpNames.Push(ast.Extra[otd.TypeParamStart + i]);
                fctx.TpVals.Push(types.TypeArgs[oti.B + i]);
            }
        }
        for (int i = 0; i < inst.MethodTypeArgCount; i++)
        {
            fctx.TpNames.Push(ast.Extra[fd.TypeParamStart + i]);
            fctx.TpVals.Push(mir.MethodTypeArgs[inst.MethodTypeArgStart + i]);
        }

        // Closed specializations cannot prove facts about an original source T.
        // The independently lowered open instance checks source diagnostics once.
        fctx.CheckSourcePatternWarnings = !emitToModule || fctx.TpNames.Count == 0;

        // Visible local functions (from current function, enclosing blocks, and top-level Main if applicable)
        fctx.EnclosingOwnerDeclId = fd.OwnerDeclId;
        if ((fd.Flags & DeclFlags.IsLocalFunc) != 0)
        {
            CollectEnclosingLocalFuncsAndOwner(inst.FuncDeclId, in ast, ref fctx.VisibleLocalFuncs, out int encOwnerDecl, out int encUncheckedDepth);
            if (fctx.EnclosingOwnerDeclId < 0)
            {
                fctx.EnclosingOwnerDeclId = encOwnerDecl;
            }
            fctx.UncheckedDepth = encUncheckedDepth;
        }
        bool enqueueUncalledLocalFuncs = emitToModule &&
            fctx.TpNames.Count == 0 &&
            (fctx.EnclosingOwnerDeclId < 0 || ast.Types[fctx.EnclosingOwnerDeclId].UnitKind == UnitKinds.App || bctx.CompilingStdItself);
        fctx.EnqueueUncalledLocalFuncs = enqueueUncalledLocalFuncs;
        int entryBlk = fctx.NewBlock();
        fctx.CurBlock = entryBlk;
        fctx.ScopeDepth = 1;
        SeedEnclosingConstants(ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);

        // Bind parameter locals first so local functions in the same body also check parameter collisions
        for (int p = 0; p < inst.ParamSigCount; p++)
        {
            MirParamSig psig = mir.ParamSigs[inst.ParamSigStart + p];
            int lFlags = MirLocalFlags.IsParam;
            if ((psig.Flags & 1) != 0) lFlags |= MirLocalFlags.IsScoped;
            if ((psig.Flags & 2) != 0) lFlags |= MirLocalFlags.IsUnscopedRefRecv;
            int lid = fctx.AddLocal(psig.NameId, psig.TypeId, psig.Mode, lFlags, fd.TokIdx);
            if (psig.Mode == PassMode.ThisShared || psig.Mode == PassMode.ThisMut)
            {
                fctx.ThisLocalId = lid;
            }
            else
            {
                RegisterScopedName(psig.NameId, 1, fd.TokIdx, ref fctx, in ast, in ta, in names, ref diags);
                fctx.Vars.Push(new VarBinding(psig.NameId, lid, 1, 0, TypeIds.Void, 0));
                if (psig.Mode == PassMode.ByValue)
                {
                    fctx.ScopeStack.Push(new ScopeEntry(1, lid, 0, -1, fd.TokIdx));
                }
            }
        }

        var emptyLfArgs = new Vec<int>();
        for (int i = 0; i < fd.LocalFuncCount; i++)
        {
            int lfId = ast.Extra[fd.LocalFuncExtraStart + i];
            int lfNameId = ast.Funcs[lfId].NameId;
            RegisterScopedName(lfNameId, 1, ast.Funcs[lfId].TokIdx, ref fctx, in ast, in ta, in names, ref diags);
            fctx.VisibleLocalFuncs.Push(lfId);
            if (enqueueUncalledLocalFuncs && ast.Funcs[lfId].TypeParamCount == 0)
            {
                _ = DeclBinder.EnsureFuncInstance(lfId, -1, emptyLfArgs.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
            }
        }

        // Constructor field slots
        if (isCtor && inst.OwnerTypeId >= 0)
        {
            TypeInfo oti = types.Items[inst.OwnerTypeId];
            TypeDecl otd = ast.Types[oti.A];
            for (int i = 0; i < oti.FieldCount; i++)
            {
                ConcreteField cf = types.Fields[oti.FieldStart + i];
                int flid = fctx.AddLocal(cf.NameId, cf.TypeId, PassMode.ByValue, MirLocalFlags.IsCtorFieldSlot, fd.TokIdx);
                fctx.CtorFieldLocals.Push(flid);
            }

            // Every constructor (implicit, explicit, primary) runs each instance field
            // initializer once, in declaration order, before its body. Like C#, each
            // initializer is its own scope: its out and pattern variables end with it.
            for (int f = 0; f < otd.FieldCount; f++)
            {
                FieldDecl fld = ast.Fields[otd.FieldStart + f];
                if ((fld.Flags & DeclFlags.Static) == 0 && fld.InitExpr >= 0)
                {
                    int slotIdx = FindInstanceFieldIndex(inst.OwnerTypeId, fld.NameId, in types);
                    if (slotIdx >= 0)
                    {
                        int flid = fctx.CtorFieldLocals[slotIdx];
                        int fType = fctx.Locals[flid].TypeId;
                        PushScope(ref fctx);
                        int initOp;
                        if ((fld.Flags & DeclFlags.InitializerCut) != 0)
                        {
                            // Like Stage-0, keep a C23-rejected field initialized without lowering any of it.
                            initOp = mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, fType, fld.TokIdx));
                        }
                        else
                        {
                            SourceLexicalScopeChecker.CheckFieldInitializer(fld.InitExpr, oti.A, in ast, in ta, in names, ref diags);
                            fctx.InFieldInitializer = true;
                            initOp = LowerExprAsOperand(fld.InitExpr, fType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                            fctx.InFieldInitializer = false;
                        }
                        int destPl = mir.AddPlaceLocal(flid, fType);
                        fctx.Emit(new MirInst(MirOp.AssignUse, destPl, -1, 0, fType, initOp, 0, 0, 0, fld.TokIdx));
                        PopScope(fld.TokIdx, ref fctx, ref mir);
                    }
                }
            }
        }

        if (fd.BodyNode >= 0)
        {
            LowerStatement(fd.BodyNode, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }

        // Fallthrough at end of function body
        if (!fctx.IsBlockTerminated(fctx.CurBlock))
        {
            EmitScopeExitsDownTo(1, fd.TokIdx, ref fctx, ref mir);
            if (isCtor && inst.OwnerTypeId >= 0)
            {
                EmitConstructorPackAndReturn(fd.TokIdx, ref fctx, in types, ref mir);
            }
            else if (inst.ReturnTypeId == TypeIds.Void && !retByRef)
            {
                fctx.Terminate(new MirTerm(MirTermKind.Return, -1, -1, 0, 0, 0, 0, fd.TokIdx));
            }
            else
            {
                if (fd.BodyNode >= 0 && IsSourceBlockReachableFromEntry(fctx.CurBlock, in fctx, in mir))
                {
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[fd.TokIdx], "Not all code paths return a value."u8);
                }
                fctx.Terminate(new MirTerm(MirTermKind.Unreachable, 0, 0, 0, 0, 0, 0, fd.TokIdx));
            }
        }

        // Give operand captures a structural activation identity before analysis.
        AssignCallActivationIdentities(ref fctx, in types, in mir);

        // Materialize MirFunc into MirModuleArena
        int locStart = mir.Locals.Count;
        for (int i = 0; i < fctx.Locals.Count; i++) mir.Locals.Push(fctx.Locals[i]);

        int blkStart = mir.Blocks.Count;
        for (int b = 0; b < fctx.BlockHead.Count; b++)
        {
            int iStart = mir.Insts.Count;
            int count = 0;
            int cur = fctx.BlockHead[b];
            while (cur >= 0)
            {
                mir.Insts.Push(fctx.StagedInsts[cur]);
                count += 1;
                cur = fctx.StagedNext[cur];
            }
            MirTerm term = fctx.BlockTerms[b];
            if (term.Kind == MirTermKind.Unset)
            {
                term = new MirTerm(MirTermKind.Unreachable, 0, 0, 0, 0, 0, 0, fd.TokIdx);
            }
            mir.Blocks.Push(new MirBlock(iStart, count, term));
        }

        var mirFn = new MirFunc(instId, locStart, fctx.Locals.Count, blkStart, fctx.BlockHead.Count, fctx.StackSpanCounter, fd.TokIdx);
        SourceValidityChecker.CheckFunction(in mirFn, in fctx, in ast, in ta, in types, in mir, ref diags);
        if (emitToModule)
        {
            int fnIdx = mir.Funcs.Count;
            mir.Funcs.Push(mirFn);
            FuncInstance updated = mir.FuncInstances[instId];
            updated.MirFuncIdx = fnIdx;
            mir.FuncInstances[instId] = updated;
        }
        else
        {
            // Check open-generic temporary function directly for VIB001..VIB008
            OwnershipChecker.CheckFunction(in mirFn, in ast, in ta, in names, in types, in mir, ref diags);
        }
        return fctx.HasGenericPatternCut;
    }

    private static void MarkCallActivationPlace(
        int placeId, int activationId, int preparationId,
        ref FuncLowerCtx fctx, in MirModuleArena mir)
    {
        if (placeId < 0) return;
        int localId = mir.Places[placeId].LocalId;
        MirLocal local = fctx.Locals[localId];
        if ((local.Flags & MirLocalFlags.IsTemp) == 0) return;
        if (preparationId >= 0 && local.CallActivationId >= 0 && local.CallActivationId != preparationId) return;
        fctx.Locals[localId] = new MirLocal(local.NameId, local.TypeId, local.Mode,
            local.Flags | MirLocalFlags.IsCallOperandLoan, local.TokIdx, activationId);
    }

    private static void MarkCallActivationOperand(
        int operandId, int activationId, int preparationId,
        ref FuncLowerCtx fctx, in TypeTable types, in MirModuleArena mir)
    {
        if (operandId < 0) return;
        MirOperand operand = mir.Operands[operandId];
        if (operand.Kind != MirOpKinds.CopyOrMove) return;
        MirLocal local = fctx.Locals[mir.Places[operand.PlaceOrLitIdx].LocalId];
        if (!types.IsView(operand.TypeId) && (local.Flags & MirLocalFlags.IsRefLocal) == 0) return;
        MarkCallActivationPlace(operand.PlaceOrLitIdx, activationId, preparationId, ref fctx, in mir);
    }

    private static void AssignCallActivationIdentities(
        ref FuncLowerCtx fctx, in TypeTable types, in MirModuleArena mir)
    {
        // Seed the terminal instruction, not source ranges or formal parameter
        // positions. Every evaluated argument, receiver and store target uses the
        // same invariant, including named arguments and nested expressions.
        for (int i = 0; i < fctx.StagedInsts.Count; i++)
        {
            MirInst instruction = fctx.StagedInsts[i];
            if (instruction.DestPlaceId >= 0 && mir.Places[instruction.DestPlaceId].ProjCount > 0)
                MarkCallActivationPlace(instruction.DestPlaceId, i, -1, ref fctx, in mir);
            if (instruction.Op == MirOp.Call)
            {
                FuncInstance callee = mir.FuncInstances[instruction.A];
                bool classReceiver = callee.OwnerTypeId >= 0 && types.Items[callee.OwnerTypeId].Kind == TypeKinds.Class;
                for (int a = 0; a < instruction.C; a++)
                {
                    MirCallArg argument = mir.CallArgs[instruction.B + a];
                    if (argument.Mode == PassMode.ByValue ||
                        ((argument.Mode == PassMode.ThisShared || argument.Mode == PassMode.ThisMut) && classReceiver))
                        MarkCallActivationOperand(argument.OperandOrPlaceId, i, -1, ref fctx, in types, in mir);
                    else
                        MarkCallActivationPlace(argument.OperandOrPlaceId, i, -1, ref fctx, in mir);
                }
            }
            else if (instruction.Op == MirOp.Intrinsic)
            {
                for (int v = 0; v < instruction.C; v++)
                    MarkCallActivationOperand(mir.ExtraLists[instruction.B + v], i, -1, ref fctx, in types, in mir);
                int placeCount = instruction.D >>> 20;
                int placeStart = instruction.D & 0xFFFFF;
                for (int p = 0; p < placeCount; p++)
                    MarkCallActivationPlace(mir.ExtraLists[placeStart + p], i, -1, ref fctx, in mir);
            }
        }

        // Walk pure preparation backward into its temporaries. Actual user calls
        // and mutations keep their own identity: an outer live operand must still
        // conflict with a nested invocation, even if that invocation returns a view.
        for (int i = fctx.StagedInsts.Count - 1; i >= 0; i--)
        {
            MirInst instruction = fctx.StagedInsts[i];
            int destination = instruction.RefDestLocalId;
            if (destination < 0 && instruction.DestPlaceId >= 0 && mir.Places[instruction.DestPlaceId].ProjCount == 0)
                destination = mir.Places[instruction.DestPlaceId].LocalId;
            if (destination < 0) continue;
            int activation = fctx.Locals[destination].CallActivationId;
            if (activation < 0) continue;
            if (instruction.Op == MirOp.BindRef)
            {
                MarkCallActivationPlace(instruction.B, activation, i, ref fctx, in mir);
            }
            else if (instruction.Op == MirOp.AssignUse && types.IsView(instruction.TypeId))
            {
                MarkCallActivationOperand(instruction.A, activation, i, ref fctx, in types, in mir);
            }
            else if (instruction.Op == MirOp.Intrinsic &&
                (MirBorrowProjections.FromPlace((MirIntrinsic)instruction.A) || MirBorrowProjections.FromValue((MirIntrinsic)instruction.A)))
            {
                for (int v = 0; v < instruction.C; v++)
                    MarkCallActivationOperand(mir.ExtraLists[instruction.B + v], activation, i, ref fctx, in types, in mir);
                int placeCount = instruction.D >>> 20;
                int placeStart = instruction.D & 0xFFFFF;
                for (int p = 0; p < placeCount; p++)
                    MarkCallActivationPlace(mir.ExtraLists[placeStart + p], activation, i, ref fctx, in mir);
            }
        }
    }

    private static bool IsSourceBlockReachableFromEntry(int targetBlk, in FuncLowerCtx fctx, in MirModuleArena mir)
    {
        int bc = fctx.BlockHead.Count;
        if (bc <= 0 || targetBlk < 0 || targetBlk >= bc) return false;
        if (targetBlk == 0) return true;

        var visited = new Vec<byte>(bc);
        visited.Resize(bc, 0);
        var queue = new Vec<int>(bc);
        visited[0] = 1;
        queue.Push(0);

        int head = 0;
        while (head < queue.Count)
        {
            int b = queue[head];
            head += 1;
            if (b == targetBlk) return true;
            for (int i = 0; i < fctx.SourceSwitchContinuations.Count; i++)
            {
                SourceSwitchAssignmentEdge edge = fctx.SourceSwitchContinuations[i];
                if (edge.Block == b) EnqueueReachableBlock(edge.Target, bc, ref visited, ref queue);
            }

            MirTerm sourceTerm = fctx.SourceBlockTerms[b];
            MirTerm term = sourceTerm.Kind == MirTermKind.Unset ? fctx.BlockTerms[b] : sourceTerm;
            switch (term.Kind)
            {
                case MirTermKind.Goto:
                    EnqueueReachableBlock(term.A, bc, ref visited, ref queue);
                    break;
                case MirTermKind.Branch:
                {
                    if (term.A >= 0 && term.A < mir.Operands.Count && mir.Operands[term.A].Kind == MirOpKinds.BoolConst)
                    {
                        int taken = mir.Operands[term.A].IntVal != 0 ? term.B : term.C;
                        EnqueueReachableBlock(taken, bc, ref visited, ref queue);
                    }
                    else
                    {
                        EnqueueReachableBlock(term.B, bc, ref visited, ref queue);
                        EnqueueReachableBlock(term.C, bc, ref visited, ref queue);
                    }
                    break;
                }
                case MirTermKind.MatchOption:
                    EnqueueReachableBlock(term.C, bc, ref visited, ref queue);
                    EnqueueReachableBlock(term.D, bc, ref visited, ref queue);
                    break;
                case MirTermKind.MatchResult:
                    EnqueueReachableBlock(term.C, bc, ref visited, ref queue);
                    EnqueueReachableBlock(term.E, bc, ref visited, ref queue);
                    break;
                case MirTermKind.GuardResultIsErr:
                    EnqueueReachableBlock(term.D, bc, ref visited, ref queue);
                    EnqueueReachableBlock(term.E, bc, ref visited, ref queue);
                    break;
                case MirTermKind.GuardOptionIsNone:
                    EnqueueReachableBlock(term.C, bc, ref visited, ref queue);
                    EnqueueReachableBlock(term.D, bc, ref visited, ref queue);
                    break;
            }
        }
        return false;
    }

    private static void EnqueueReachableBlock(int blk, int bc, ref Vec<byte> visited, ref Vec<int> queue)
    {
        if (blk >= 0 && blk < bc && visited[blk] == 0)
        {
            visited[blk] = 1;
            queue.Push(blk);
        }
    }

    private static void EmitConstructorPackAndReturn(int tokIdx, ref FuncLowerCtx fctx, in TypeTable types, ref MirModuleArena mir)
    {
        var fieldOps = new Vec<int>(fctx.CtorFieldLocals.Count);
        for (int i = 0; i < fctx.CtorFieldLocals.Count; i++)
        {
            int flid = fctx.CtorFieldLocals[i];
            int fType = fctx.Locals[flid].TypeId;
            int pl = mir.AddPlaceLocal(flid, fType);
            fieldOps.Push(mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, fType, tokIdx)));
        }
        int opListStart = mir.PushIdList(fieldOps.AsReadOnlySpan());
        int resTmp = fctx.AddLocal(-1, fctx.OwnerTypeId, PassMode.ByValue, MirLocalFlags.IsTemp, tokIdx);
        int resPlace = mir.AddPlaceLocal(resTmp, fctx.OwnerTypeId);
        MirOp packOp = types.Items[fctx.OwnerTypeId].Kind == TypeKinds.Class ? MirOp.AllocClass : MirOp.ConstructStruct;
        fctx.Emit(new MirInst(packOp, resPlace, -1, 0, fctx.OwnerTypeId, opListStart, fieldOps.Count, 0, 0, tokIdx));
        int retOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, resPlace, 0, fctx.OwnerTypeId, tokIdx));
        fctx.Terminate(new MirTerm(MirTermKind.Return, retOp, -1, 0, 0, 0, 0, tokIdx));
    }

    private static void ClampChildDeclDepths(ref FuncLowerCtx fctx, int exitingDepth)
    {
        for (int i = 0; i < fctx.ChildDeclDepths.Count; i++)
        {
            if (fctx.ChildDeclDepths[i] > exitingDepth)
            {
                fctx.ChildDeclDepths[i] = exitingDepth;
            }
        }
    }

    private static void RegisterScopedName(
        int nameId,
        int targetDepth,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref DiagnosticBag diags)
    {
        if (nameId < 0 || fctx.InferDepth > 0 || Bytes.Eq(names.Text(nameId), "_"u8))
        {
            return;
        }
        bool conflict = false;
        for (int i = 0; i < fctx.Vars.Count; i++)
        {
            if (fctx.Vars[i].NameId == nameId && fctx.Vars[i].LocalId != -2)
            {
                conflict = true;
                break;
            }
        }
        if (!conflict)
        {
            for (int i = 0; i < fctx.VisibleLocalFuncs.Count; i++)
            {
                if (ast.Funcs[fctx.VisibleLocalFuncs[i]].NameId == nameId)
                {
                    conflict = true;
                    break;
                }
            }
        }
        int existingIdx = -1;
        for (int i = 0; i < fctx.ChildDeclNameIds.Count; i++)
        {
            if (fctx.ChildDeclNameIds[i] == nameId)
            {
                existingIdx = i;
                if (fctx.ChildDeclDepths[i] > targetDepth)
                {
                    conflict = true;
                }
                break;
            }
        }
        if (conflict)
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A local, parameter, pattern variable, or local function with this name is already declared in this or an enclosing/nested local scope."u8);
        }
        if (existingIdx >= 0)
        {
            if (targetDepth > fctx.ChildDeclDepths[existingIdx])
            {
                fctx.ChildDeclDepths[existingIdx] = targetDepth;
            }
        }
        else
        {
            fctx.ChildDeclNameIds.Push(nameId);
            fctx.ChildDeclDepths.Push(targetDepth);
        }
    }

    private static void CheckNoPatternDeclarations(
        int patNodeId,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref DiagnosticBag diags)
    {
        if (patNodeId < 0) return;
        AstNode p = ast.Nodes[patNodeId];
        switch (p.Kind)
        {
            case AstKind.PatDecl:
                if (p.B >= 0 && !Bytes.Eq(names.Text(p.B), "_"u8))
                {
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[p.TokIdx], "A pattern variable may not be declared within a 'not' or 'or' pattern."u8);
                }
                return;
            case AstKind.PatUnion:
                if (p.B >= 0 && !Bytes.Eq(names.Text(p.B), "_"u8))
                {
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[p.TokIdx], "A pattern variable may not be declared within a 'not' or 'or' pattern."u8);
                }
                if (p.D >= 0)
                {
                    CheckNoPatternDeclarations(p.D, in ast, in ta, in names, ref diags);
                }
                return;
            case AstKind.PatNot:
                CheckNoPatternDeclarations(p.A, in ast, in ta, in names, ref diags);
                return;
            case AstKind.PatLogic:
                CheckNoPatternDeclarations(p.B, in ast, in ta, in names, ref diags);
                CheckNoPatternDeclarations(p.C, in ast, in ta, in names, ref diags);
                return;
        }
    }

    private static void PushScope(ref FuncLowerCtx fctx)
    {
        fctx.ScopeDepth += 1;
    }

    private static void PopScope(int tokIdx, ref FuncLowerCtx fctx, ref MirModuleArena mir)
    {
        int d = fctx.ScopeDepth;
        EmitScopeExitsDownTo(d, tokIdx, ref fctx, ref mir);
        while (fctx.ScopeStack.Count > 0 && fctx.ScopeStack[fctx.ScopeStack.Count - 1].ScopeDepth >= d)
        {
            fctx.ScopeStack.Pop();
        }
        while (fctx.Vars.Count > 0 && fctx.Vars[fctx.Vars.Count - 1].ScopeDepth >= d)
        {
            fctx.Vars.Pop();
        }
        ClampChildDeclDepths(ref fctx, d);
        fctx.ScopeDepth -= 1;
    }

    private static void EmitScopeExitsDownTo(int minDepthInclusive, int tokIdx, ref FuncLowerCtx fctx, ref MirModuleArena mir)
    {
        if (fctx.IsBlockTerminated(fctx.CurBlock)) return;

        var exiting = new Vec<int>();
        for (int i = fctx.ScopeStack.Count - 1; i >= 0; i--)
        {
            ScopeEntry se = fctx.ScopeStack[i];
            if (se.ScopeDepth < minDepthInclusive) break;
            if (se.IsUsing != 0)
            {
                if (exiting.Count > 0)
                {
                    int s = mir.PushIdList(exiting.AsReadOnlySpan());
                    fctx.Emit(new MirInst(MirOp.ScopeExit, -1, -1, 0, TypeIds.Void, s, exiting.Count, 0, 0, tokIdx));
                    exiting.Clear();
                }
                fctx.Emit(new MirInst(MirOp.DisposeResource, -1, -1, 0, TypeIds.Void, se.LocalId, se.DisposeInstId, 0, 0, se.TokIdx));
            }
            exiting.Push(se.LocalId);
        }
        if (exiting.Count > 0)
        {
            int s = mir.PushIdList(exiting.AsReadOnlySpan());
            fctx.Emit(new MirInst(MirOp.ScopeExit, -1, -1, 0, TypeIds.Void, s, exiting.Count, 0, 0, tokIdx));
        }
    }

    private static int FindInstanceFieldIndex(int ownerTypeId, int fieldNameId, in TypeTable types)
    {
        TypeInfo ti = types.Items[ownerTypeId];
        for (int i = 0; i < ti.FieldCount; i++)
        {
            ConcreteField cf = types.Fields[ti.FieldStart + i];
            if (cf.NameId == fieldNameId || cf.CapturedParamNameId == fieldNameId)
            {
                return i;
            }
        }
        return -1;
    }

    private static void CheckNotDirectCapturedPrimaryParamWrite(
        int exprId,
        ReadOnlySpan<byte> msg,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in TypeTable types,
        ref DiagnosticBag diags)
    {
        if (exprId < 0 || fctx.ThisLocalId < 0 || fctx.IsCtor || fctx.OwnerTypeId < 0)
        {
            return;
        }
        AstNode n = ast.Nodes[exprId];
        if (n.Kind != AstKind.ExprIdent)
        {
            return;
        }
        int lid = fctx.FindVar(n.A, out bool isConst, out _, out _);
        if (lid >= 0 || isConst)
        {
            return;
        }
        int fIdx = FindInstanceFieldIndex(fctx.OwnerTypeId, n.A, in types);
        if (fIdx >= 0)
        {
            ConcreteField cf = types.Fields[types.Items[fctx.OwnerTypeId].FieldStart + fIdx];
            if ((cf.Flags & DeclFlags.IsCapturedPrimaryParam) != 0 && cf.CapturedParamNameId == n.A)
            {
                diags.ReportTok(VibCodes.MutateSharedBorrow, ta.Tokens[n.TokIdx], msg);
            }
        }
    }

    private static int MakePatternBindFlags(int bindTypeId, int bindNameId, bool isBorrowed, bool isShared, in AstArena ast, in TypeTable types)
    {
        int flags = MirLocalFlags.IsPatternBind | (bindNameId < 0 ? MirLocalFlags.IsTemp : 0);
        if (!types.IsCopy(bindTypeId, in ast))
        {
            if (isBorrowed) flags |= MirLocalFlags.IsBorrowedBind;
            if (isShared) flags |= MirLocalFlags.IsSharedBind;
        }
        return flags;
    }

    private static void LowerStatement(
        int stmtId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        if (stmtId < 0) return;
        // C# binds and type-checks unreachable statements too; CS0162 is only a
        // warning. Lower them into a fresh block without predecessors: source
        // reachability, definite assignment, ownership and emission follow edges
        // from the entry block, so the statement adds no runtime path.
        if (fctx.IsBlockTerminated(fctx.CurBlock)) fctx.CurBlock = fctx.NewBlock();

        AstNode n = ast.Nodes[stmtId];
        int tokIdx = n.TokIdx;

        switch (n.Kind)
        {
            case AstKind.StmtEmpty:
                return;

            case AstKind.StmtMulti:
            {
                for (int i = 0; i < n.B; i++)
                {
                    LowerStatement(ast.Extra[n.A + i], ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                }
                return;
            }

            case AstKind.StmtUncheckedBlock:
            {
                fctx.UncheckedDepth += 1;
                LowerStatement(n.A, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                fctx.UncheckedDepth -= 1;
                return;
            }

            case AstKind.StmtBlock:
            {
                PushScope(ref fctx);
                int savedLfCount = fctx.VisibleLocalFuncs.Count;
                if (n.D > 0)
                {
                    var emptyBlkLfArgs = new Vec<int>();
                    for (int i = 0; i < n.D; i++)
                    {
                        int lfId = ast.Extra[n.C + i];
                        int lfNameId = ast.Funcs[lfId].NameId;
                        RegisterScopedName(lfNameId, fctx.ScopeDepth, ast.Funcs[lfId].TokIdx, ref fctx, in ast, in ta, in names, ref diags);
                        fctx.VisibleLocalFuncs.Push(lfId);
                        if (fctx.EnqueueUncalledLocalFuncs && ast.Funcs[lfId].TypeParamCount == 0)
                        {
                            _ = DeclBinder.EnsureFuncInstance(lfId, -1, emptyBlkLfArgs.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                        }
                    }
                }
                for (int i = 0; i < n.B; i++)
                {
                    LowerStatement(ast.Extra[n.A + i], ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                }
                fctx.VisibleLocalFuncs.Truncate(savedLfCount);
                PopScope(tokIdx, ref fctx, ref mir);
                return;
            }

            case AstKind.StmtVarDecl:
                LowerVarDecl(in n, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                return;

            case AstKind.StmtIf:
            {
                int thenBlk = fctx.NewBlock();
                int elseBlk = fctx.NewBlock();
                int mergeBlk = fctx.NewBlock();

                // Push condition scope so temporary borrows in `cond` end at `thenBlk`/`elseBlk` exit,
                // while hoisting `out var` and pattern bindings to the enclosing block scope (`OutVarScopeOverride`).
                PushScope(ref fctx);
                int condDepth = fctx.ScopeDepth;
                LowerCondBranch(n.A, thenBlk, elseBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope: true, allowTopLevelIfGuard: true);

                fctx.CurBlock = thenBlk;
                PushScope(ref fctx);
                LowerStatement(n.B, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                PopScope(tokIdx, ref fctx, ref mir);
                if (!fctx.IsBlockTerminated(fctx.CurBlock))
                {
                    EmitScopeExitsDownTo(condDepth, tokIdx, ref fctx, ref mir);
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, tokIdx));
                }

                fctx.CurBlock = elseBlk;
                if (n.C >= 0)
                {
                    PushScope(ref fctx);
                    LowerStatement(n.C, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    PopScope(tokIdx, ref fctx, ref mir);
                }
                if (!fctx.IsBlockTerminated(fctx.CurBlock))
                {
                    EmitScopeExitsDownTo(condDepth, tokIdx, ref fctx, ref mir);
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, tokIdx));
                }

                PopScopeWithoutEmit(ref fctx);
                fctx.CurBlock = mergeBlk;
                return;
            }

            case AstKind.StmtWhile:
            {
                int condBlk = fctx.NewBlock();
                int bodyBlk = fctx.NewBlock();
                int exitBlk = fctx.NewBlock();

                fctx.Terminate(new MirTerm(MirTermKind.Goto, condBlk, 0, 0, 0, 0, 0, tokIdx));

                fctx.CurBlock = condBlk;
                PushScope(ref fctx);
                LowerCondBranch(n.A, bodyBlk, exitBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope: false);

                fctx.CurBlock = bodyBlk;
                fctx.Loops.Push(new LoopFrame(exitBlk, condBlk, fctx.ScopeDepth, fctx.ScopeDepth));
                LowerStatement(n.B, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                fctx.Loops.Pop();

                if (!fctx.IsBlockTerminated(fctx.CurBlock))
                {
                    EmitScopeExitsDownTo(fctx.ScopeDepth, tokIdx, ref fctx, ref mir);
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, condBlk, 0, 0, 0, 0, 0, tokIdx));
                }
                PopScopeWithoutEmit(ref fctx);

                fctx.CurBlock = exitBlk;
                return;
            }

            case AstKind.StmtDoWhile:
            {
                int bodyBlk = fctx.NewBlock();
                int condBlk = fctx.NewBlock();
                int exitBlk = fctx.NewBlock();

                fctx.Terminate(new MirTerm(MirTermKind.Goto, bodyBlk, 0, 0, 0, 0, 0, tokIdx));

                fctx.CurBlock = bodyBlk;
                PushScope(ref fctx);
                fctx.Loops.Push(new LoopFrame(exitBlk, condBlk, fctx.ScopeDepth, fctx.ScopeDepth));
                LowerStatement(n.A, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                fctx.Loops.Pop();
                PopScope(tokIdx, ref fctx, ref mir);

                if (!fctx.IsBlockTerminated(fctx.CurBlock))
                {
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, condBlk, 0, 0, 0, 0, 0, tokIdx));
                }

                fctx.CurBlock = condBlk;
                PushScope(ref fctx);
                LowerCondBranch(n.B, bodyBlk, exitBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope: false);
                PopScopeWithoutEmit(ref fctx);

                fctx.CurBlock = exitBlk;
                return;
            }

            case AstKind.StmtFor:
            {
                PushScope(ref fctx);
                if (n.A >= 0)
                {
                    if (ast.Nodes[n.A].Kind == AstKind.StmtBlock)
                    {
                        AstNode ib = ast.Nodes[n.A];
                        for (int i = 0; i < ib.B; i++)
                        {
                            LowerStatement(ast.Extra[ib.A + i], ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                        }
                    }
                    else
                    {
                        LowerStatement(n.A, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    }
                }

                int condBlk = fctx.NewBlock();
                int bodyBlk = fctx.NewBlock();
                int stepBlk = fctx.NewBlock();
                int exitBlk = fctx.NewBlock();

                fctx.Terminate(new MirTerm(MirTermKind.Goto, condBlk, 0, 0, 0, 0, 0, tokIdx));

                fctx.CurBlock = condBlk;
                PushScope(ref fctx);
                int condScopeDepth = fctx.ScopeDepth;
                if (n.B >= 0)
                {
                    LowerCondBranch(n.B, bodyBlk, exitBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope: false);
                }
                else
                {
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, bodyBlk, 0, 0, 0, 0, 0, tokIdx));
                }

                fctx.CurBlock = bodyBlk;
                PushScope(ref fctx);
                fctx.Loops.Push(new LoopFrame(exitBlk, stepBlk, condScopeDepth, fctx.ScopeDepth));
                LowerStatement(n.D, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                fctx.Loops.Pop();
                PopScope(tokIdx, ref fctx, ref mir);

                if (!fctx.IsBlockTerminated(fctx.CurBlock))
                {
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, stepBlk, 0, 0, 0, 0, 0, tokIdx));
                }

                fctx.CurBlock = stepBlk;
                if (n.C >= 0)
                {
                    AstNode sb = ast.Nodes[n.C];
                    for (int i = 0; i < sb.B; i++)
                    {
                        LowerStatement(ast.Extra[sb.A + i], ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    }
                }
                if (!fctx.IsBlockTerminated(fctx.CurBlock))
                {
                    EmitScopeExitsDownTo(condScopeDepth, tokIdx, ref fctx, ref mir);
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, condBlk, 0, 0, 0, 0, 0, tokIdx));
                }
                PopScopeWithoutEmit(ref fctx);

                fctx.CurBlock = exitBlk;
                PopScope(tokIdx, ref fctx, ref mir);
                return;
            }

            case AstKind.StmtForeach:
            {
                LowerForeach(in n, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                return;
            }

            case AstKind.StmtSwitch:
            {
                LowerSwitchStatement(in n, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                return;
            }

            case AstKind.StmtReturn:
            {
                if (fctx.IsCtor && fctx.OwnerTypeId >= 0)
                {
                    if (n.A >= 0)
                    {
                        if (ta.Tokens[tokIdx].Kind == TokKind.KwReturn)
                            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A constructor cannot return a value."u8);
                        else CheckSourceStatementExpression(n.A, in ast, in ta, ref diags);
                        _ = LowerExprAsOperand(n.A, TypeIds.Void, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    }
                    EmitScopeExitsDownTo(1, tokIdx, ref fctx, ref mir);
                    EmitConstructorPackAndReturn(tokIdx, ref fctx, in types, ref mir);
                    return;
                }

                if (n.A < 0)
                {
                    EmitScopeExitsDownTo(1, tokIdx, ref fctx, ref mir);
                    if (fctx.ReturnsByRef)
                    {
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "An object of a type convertible to the return type is required for 'return'."u8);
                        int dummyTmp = fctx.NewTemp(fctx.ReturnTypeId, tokIdx, ref mir);
                        int dummyPl = mir.AddPlaceLocal(dummyTmp, fctx.ReturnTypeId);
                        fctx.Terminate(new MirTerm(MirTermKind.Return, -1, dummyPl, 0, 0, 0, 0, tokIdx));
                        return;
                    }
                    if (fctx.ReturnTypeId != TypeIds.Void)
                    {
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "An object of a type convertible to the return type is required for 'return'."u8);
                        int dummyOp = mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, fctx.ReturnTypeId, tokIdx));
                        fctx.Terminate(new MirTerm(MirTermKind.Return, dummyOp, -1, 0, 0, 0, 0, tokIdx));
                        return;
                    }
                    fctx.Terminate(new MirTerm(MirTermKind.Return, -1, -1, 0, 0, 0, 0, tokIdx));
                    return;
                }

                if (n.B != 0 || fctx.ReturnsByRef)
                {
                    if ((n.B != 0) != fctx.ReturnsByRef)
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "The return expression must agree with the method's ref return kind."u8);
                    if (fctx.ReturnRefMut)
                    {
                        int retInnerExpr = (ast.Nodes[n.A].Kind == AstKind.ExprUnary && (TokKind)ast.Nodes[n.A].A == TokKind.KwRef) ? ast.Nodes[n.A].B : n.A;
                        CheckNotDirectCapturedPrimaryParamWrite(retInnerExpr, "Cannot return mutable reference to a captured primary-constructor parameter."u8, in fctx, in ast, in ta, in types, ref diags);
                    }
                    int retPl = LowerPlace(n.A, fctx.ReturnRefMut, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    CheckSourceReferencePlace(retPl, fctx.ReturnTypeId, fctx.ReturnRefMut, tokIdx, in fctx, in ta, in types, in mir, ref diags);
                    EmitScopeExitsDownTo(1, tokIdx, ref fctx, ref mir);
                    fctx.Terminate(new MirTerm(MirTermKind.Return, -1, retPl, 0, 0, 0, 0, tokIdx));
                    return;
                }

                if (fctx.ReturnTypeId == TypeIds.Void)
                {
                    if (ta.Tokens[tokIdx].Kind == TokKind.KwReturn)
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A void method cannot return a value."u8);
                    else CheckSourceStatementExpression(n.A, in ast, in ta, ref diags);
                    _ = LowerExprAsOperand(n.A, TypeIds.Void, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    EmitScopeExitsDownTo(1, tokIdx, ref fctx, ref mir);
                    fctx.Terminate(new MirTerm(MirTermKind.Return, -1, -1, 0, 0, 0, 0, tokIdx));
                    return;
                }

                int retOp = LowerExprAsOperand(n.A, fctx.ReturnTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                // Materialize into dedicated return temp before ScopeExits so cleanup of other locals runs safely before return!
                int retTmp = fctx.AddLocal(-1, fctx.ReturnTypeId, PassMode.ByValue, MirLocalFlags.IsTemp, tokIdx);
                int retTmpPlace = mir.AddPlaceLocal(retTmp, fctx.ReturnTypeId);
                fctx.Emit(new MirInst(MirOp.AssignUse, retTmpPlace, -1, 0, fctx.ReturnTypeId, retOp, 0, 0, 0, tokIdx));
                EmitScopeExitsDownTo(1, tokIdx, ref fctx, ref mir);
                int finalRetOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, retTmpPlace, 0, fctx.ReturnTypeId, tokIdx));
                fctx.Terminate(new MirTerm(MirTermKind.Return, finalRetOp, -1, 0, 0, 0, 0, tokIdx));
                return;
            }

            case AstKind.StmtBreak:
            {
                if (fctx.Loops.Count > 0)
                {
                    LoopFrame lf = fctx.Loops[fctx.Loops.Count - 1];
                    EmitScopeExitsDownTo(lf.BreakScopeDepth, tokIdx, ref fctx, ref mir);
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, lf.BreakBlock, 0, 0, 0, 0, 0, tokIdx));
                }
                else diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A break statement requires an enclosing loop or switch."u8);
                return;
            }

            case AstKind.StmtContinue:
            {
                if (fctx.Loops.Count > 0 && fctx.Loops[fctx.Loops.Count - 1].ContinueBlock >= 0)
                {
                    LoopFrame lf = fctx.Loops[fctx.Loops.Count - 1];
                    EmitScopeExitsDownTo(lf.ContinueScopeDepth, tokIdx, ref fctx, ref mir);
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, lf.ContinueBlock, 0, 0, 0, 0, 0, tokIdx));
                }
                else diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A continue statement requires an enclosing loop."u8);
                return;
            }

            case AstKind.StmtExpr:
            {
                CheckSourceStatementExpression(n.A, in ast, in ta, ref diags);
                int opId = LowerExprAsOperand(n.A, TypeIds.Void, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                int exprTid = mir.Operands[opId].TypeId;
                if ((exprTid == TypeIds.Utf8Lines || exprTid == TypeIds.Utf8ArgEnum) &&
                    !(ast.Nodes[n.A].Kind == AstKind.ExprAssign && IsDiscardExpression(ast.Nodes[n.A].B, in fctx, in ast, in names)))
                {
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[n.TokIdx], "'Utf8Lines' and 'Utf8ArgEnumerator' can only be used directly in 'foreach' or returned from a method."u8);
                }
                // If expression produced a linear value that was ignored (`File.OpenRead(...)`), keep temp in scope so VIB006 fires!
                return;
            }
        }
    }

    private static void CheckSourceStatementExpression(int exprId, in AstArena ast, in TokenArena ta, ref DiagnosticBag diags)
    {
        AstNode expression = ast.Nodes[exprId];
        if (expression.Kind == AstKind.ExprAssign || expression.Kind == AstKind.ExprCall || expression.Kind == AstKind.ExprNew) return;
        if (expression.Kind == AstKind.ExprUnary && ((TokKind)expression.A == TokKind.PlusPlus || (TokKind)expression.A == TokKind.MinusMinus)) return;
        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[expression.TokIdx], "Only assignment, invocation, object creation, increment, and decrement expressions can be used as statements."u8);
    }

    private static void PopScopeWithoutEmit(ref FuncLowerCtx fctx)
    {
        int d = fctx.ScopeDepth;
        while (fctx.ScopeStack.Count > 0 && fctx.ScopeStack[fctx.ScopeStack.Count - 1].ScopeDepth >= d)
        {
            fctx.ScopeStack.Pop();
        }
        while (fctx.Vars.Count > 0 && fctx.Vars[fctx.Vars.Count - 1].ScopeDepth >= d)
        {
            fctx.Vars.Pop();
        }
        ClampChildDeclDepths(ref fctx, d);
        fctx.ScopeDepth -= 1;
    }

    private static bool IsZeroFloatLitText(ReadOnlySpan<byte> lit)
    {
        if (lit.Length == 0) return false;
        bool seenZero = false;
        for (int i = 0; i < lit.Length; i++)
        {
            byte b = lit[i];
            if (b == (byte)'e' || b == (byte)'E') break;
            if (b == (byte)'.' || b == (byte)'_') continue;
            if (b == (byte)'0')
            {
                seenZero = true;
                continue;
            }
            return false;
        }
        return seenZero;
    }

    private static bool IsZeroNumericConstExpr(
        int exprId,
        int ownerDeclId,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types)
    {
        if (exprId < 0) return false;
        AstNode n = ast.Nodes[exprId];
        if (n.Kind == AstKind.ExprFloatLit)
        {
            return IsZeroFloatLitText(ta.GetLit(ta.Tokens[n.A].AuxId));
        }
        if (n.Kind == AstKind.ExprIdent)
        {
            int lid = fctx.FindVar(n.A, out bool isC, out int cTid, out long cVal);
            if (isC && types.IsInteger(cTid) && cTid != TypeIds.Char && types.Items[cTid].Kind != TypeKinds.Enum)
            {
                return cVal == 0;
            }
            if (isC && types.IsFloat(cTid))
            {
                return cTid == TypeIds.F32 ? (cVal & 0x7FFFFFFFL) == 0 : (cVal & 0x7FFFFFFFFFFFFFFFL) == 0;
            }
            if (lid >= 0 && types.IsFloat(cTid) && cVal == 1)
            {
                return true;
            }
        }
        if (n.Kind == AstKind.ExprUnary && n.C == 0)
        {
            TokKind uk = (TokKind)n.A;
            if (uk == TokKind.Plus || uk == TokKind.Minus || uk == TokKind.KwUnchecked)
            {
                return IsZeroNumericConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types);
            }
        }
        if (TryEvalTypedIntConstExpr(exprId, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int iTid, out long iv))
        {
            return iTid != TypeIds.Char && types.Items[iTid].Kind != TypeKinds.Enum && iv == 0;
        }
        if (TryEvalFloatConstExpr(exprId, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out _, out double dz))
        {
            return dz == 0.0;
        }
        return false;
    }

    private static int PromoteConstIntTypes(int lt, long lv, int rt, long rv, in TypeTable types)
    {
        if (lt == TypeIds.U64 || rt == TypeIds.U64)
        {
            if (lt == TypeIds.U64 && types.IsSignedInteger(rt) && !((rt == TypeIds.I32 || rt == TypeIds.I64) && rv >= 0)) return -1;
            if (rt == TypeIds.U64 && types.IsSignedInteger(lt) && !((lt == TypeIds.I32 || lt == TypeIds.I64) && lv >= 0)) return -1;
            return TypeIds.U64;
        }
        if (lt == TypeIds.NUInt || rt == TypeIds.NUInt)
        {
            if (lt == TypeIds.I64 || rt == TypeIds.I64) return -1;
            if (lt == TypeIds.NUInt && types.IsSignedInteger(rt) && !(rt == TypeIds.I32 && rv >= 0)) return -1;
            if (rt == TypeIds.NUInt && types.IsSignedInteger(lt) && !(lt == TypeIds.I32 && lv >= 0)) return -1;
            return TypeIds.NUInt;
        }
        if (lt == TypeIds.I64 || rt == TypeIds.I64) return TypeIds.I64;
        if (lt == TypeIds.NInt || rt == TypeIds.NInt)
        {
            if (lt == TypeIds.U32 || rt == TypeIds.U32) return -1;
            return TypeIds.NInt;
        }
        if (lt == TypeIds.U32 || rt == TypeIds.U32)
        {
            if (lt == TypeIds.U32 && types.IsSignedInteger(rt)) return (rt == TypeIds.I32 && rv >= 0) ? TypeIds.U32 : TypeIds.I64;
            if (rt == TypeIds.U32 && types.IsSignedInteger(lt)) return (lt == TypeIds.I32 && lv >= 0) ? TypeIds.U32 : TypeIds.I64;
            return TypeIds.U32;
        }
        return TypeIds.I32;
    }

    private static bool TryResolveConstCondIntCommonType(int t1, long v1, int t2, long v2, in TypeTable types, out int commonTypeId)
    {
        commonTypeId = -1;
        if (t1 == t2)
        {
            commonTypeId = t1;
            return true;
        }
        bool e1 = types.Items[t1].Kind == TypeKinds.Enum;
        bool e2 = types.Items[t2].Kind == TypeKinds.Enum;
        if (e1 || e2)
        {
            if (e1 && !e2 && t2 != TypeIds.Char && v2 == 0) { commonTypeId = t1; return true; }
            if (e2 && !e1 && t1 != TypeIds.Char && v1 == 0) { commonTypeId = t2; return true; }
            return false;
        }
        bool t1FitsT2 = CanImplicitNumericWiden(t1, t2) ||
                        (t1 == TypeIds.I32 && FitsInt32ValueInTarget(v1, t2)) ||
                        (t1 == TypeIds.I64 && (t2 == TypeIds.U64 || t2 == TypeIds.NUInt) && v1 >= 0);
        bool t2FitsT1 = CanImplicitNumericWiden(t2, t1) ||
                        (t2 == TypeIds.I32 && FitsInt32ValueInTarget(v2, t1)) ||
                        (t2 == TypeIds.I64 && (t1 == TypeIds.U64 || t1 == TypeIds.NUInt) && v2 >= 0);
        if (t1FitsT2 && !t2FitsT1)
        {
            commonTypeId = t2;
            return true;
        }
        if (t2FitsT1 && !t1FitsT2)
        {
            commonTypeId = t1;
            return true;
        }
        return false;
    }

    private static bool CanConstImplicitConvertToInt32(int t, long v, in TypeTable types) =>
        types.Items[t].Kind != TypeKinds.Enum &&
        (t == TypeIds.I32 || CanImplicitNumericWiden(t, TypeIds.I32));

    private static bool TryEvalTypedIntConstExpr(
        int exprId,
        int ownerDeclId,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types,
        out int constTypeId,
        out long val)
    {
        constTypeId = TypeIds.I32;
        val = 0;
        if (exprId < 0) return false;

        AstNode n = ast.Nodes[exprId];
        switch (n.Kind)
        {
            case AstKind.ExprIntLit:
            {
                Token tok = ta.Tokens[n.A];
                if ((tok.AuxId & 4) != 0) return false;
                if (tok.Kind == TokKind.LongLit) constTypeId = TypeIds.I64;
                else if (tok.Kind == TokKind.UIntLit) constTypeId = TypeIds.U32;
                else if (tok.Kind == TokKind.ULongLit) constTypeId = TypeIds.U64;
                else constTypeId = TypeIds.I32;
                val = TruncateConstToType(tok.IntVal, constTypeId);
                return true;
            }
            case AstKind.ExprCharLit:
                constTypeId = TypeIds.Char;
                val = n.A & 0xFFFFL;
                return true;

            case AstKind.ExprDefault:
            {
                if (n.A < 0) return false;
                int defT = TryResolveConstTargetType(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types);
                if (defT > 0 && types.IsInteger(defT))
                {
                    constTypeId = defT;
                    val = 0;
                    return true;
                }
                return false;
            }

            case AstKind.ExprIdent:
            {
                int localId = fctx.FindVar(n.A, out bool isC, out int cTid, out long cv);
                if (isC && types.IsInteger(cTid))
                {
                    constTypeId = cTid;
                    val = TruncateConstToType(cv, cTid);
                    return true;
                }
                // A nearer runtime (or differently typed const) binding hides fields and imports.
                if (localId != -1 || isC) return false;
                for (int d = ownerDeclId; d >= 0; d = ast.Types[d].OwnerDeclId)
                {
                    TypeDecl otd = ast.Types[d];
                    for (int f = 0; f < otd.FieldCount; f++)
                    {
                        FieldDecl fd = ast.Fields[otd.FieldStart + f];
                        if (fd.NameId == n.A && (fd.Flags & DeclFlags.IsConst) != 0)
                        {
                            int ft = TryResolveConstTargetType(fd.TypeNode, d, in fctx, in ast, in ta, in names, in bctx, in types);
                            if (ft > 0 && types.IsInteger(ft))
                            {
                                if (fd.HasConstVal != 0)
                                {
                                    constTypeId = ft;
                                    val = TruncateConstToType(fd.ConstVal, UnderlyingIntOrSelf(ft, in types));
                                    return true;
                                }
                                if (fd.InitExpr >= 0 && fd.InitExpr != exprId &&
                                    TryEvalTypedIntConstExpr(fd.InitExpr, d, in fctx, in ast, in ta, in names, in bctx, in types, out _, out long initV))
                                {
                                    constTypeId = ft;
                                    val = TruncateConstToType(initV, UnderlyingIntOrSelf(ft, in types));
                                    return true;
                                }
                            }
                        }
                    }
                }
                if (LookupImportedStaticConstReadOnly(n.A, ownerDeclId, n.TokIdx, in fctx, in ast, in ta, in names, in bctx, out int impK, out int impPrim, out int impEnumDecl, out long impBits, out _) && impK == 1)
                {
                    constTypeId = impEnumDecl >= 0 ? FindExistingEnumTypeId(impEnumDecl, in types) : impPrim;
                    val = TruncateConstToType(impBits, UnderlyingIntOrSelf(constTypeId, in types));
                    return true;
                }
                return false;
            }

            case AstKind.ExprMember:
            {
                if (TryResolveConstOwnerDeclFromMemberTarget(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int earlyDecl, n.B) && earlyDecl >= 0)
                {
                    TypeDecl etd = ast.Types[earlyDecl];
                    for (int f = 0; f < etd.FieldCount; f++)
                    {
                        FieldDecl fd = ast.Fields[etd.FieldStart + f];
                        if (fd.NameId == n.B && (fd.Flags & DeclFlags.IsConst) != 0)
                        {
                            int ft = etd.Kind == TypeDeclKinds.Enum
                                ? FindExistingEnumTypeId(earlyDecl, in types)
                                : TryResolveConstTargetType(fd.TypeNode, earlyDecl, in fctx, in ast, in ta, in names, in bctx, in types);
                            if (ft <= 0) ft = TypeIds.I32;
                            if (!types.IsInteger(ft)) return false;
                            if (fd.HasConstVal != 0)
                            {
                                constTypeId = ft;
                                val = TruncateConstToType(fd.ConstVal, UnderlyingIntOrSelf(ft, in types));
                                return true;
                            }
                            if (fd.InitExpr >= 0 && fd.InitExpr != exprId &&
                                TryEvalTypedIntConstExpr(fd.InitExpr, earlyDecl, in fctx, in ast, in ta, in names, in bctx, in types, out _, out long initV))
                            {
                                constTypeId = ft;
                                val = TruncateConstToType(initV, UnderlyingIntOrSelf(ft, in types));
                                return true;
                            }
                        }
                    }
                    return false;
                }
                AstNode target = ast.Nodes[n.A];
                if (target.Kind == AstKind.ExprIdent)
                {
                    int fv = fctx.FindVar(target.A, out bool isVarC, out _, out _);
                    if (fv >= 0 || fv == -2 || isVarC) return false;
                    int callerUnit = ownerDeclId >= 0 ? ast.Types[ownerDeclId].UnitKind : UnitKinds.App;
                    int callerNs = ownerDeclId >= 0 ? ast.Types[ownerDeclId].NsId : -1;
                    int shadowDecl = -1;
                    if (target.D == 0 && callerUnit == UnitKinds.App)
                    {
                        shadowDecl = DeclBinder.FindAppTypeInLexicalScope(target.A, 0, callerNs, ownerDeclId, in ast, in names, in bctx);
                        if (shadowDecl < 0)
                        {
                            Option<int> gOpt = bctx.AppGlobalTypeByNameArity.Get(DeclBinder.PackNameArity(target.A, 0));
                            if (gOpt.IsSome) shadowDecl = gOpt.Unwrap();
                        }
                    }
                    else if (target.D == 1 && callerUnit == UnitKinds.App)
                    {
                        Option<int> gOpt = bctx.AppGlobalTypeByNameArity.Get(DeclBinder.PackNameArity(target.A, 0));
                        if (gOpt.IsSome) shadowDecl = gOpt.Unwrap();
                    }

                    if (shadowDecl >= 0)
                    {
                        TypeDecl std = ast.Types[shadowDecl];
                        for (int f = 0; f < std.FieldCount; f++)
                        {
                            FieldDecl fd = ast.Fields[std.FieldStart + f];
                            if (fd.NameId == n.B && (fd.Flags & DeclFlags.IsConst) != 0)
                            {
                                int ft = std.Kind == TypeDeclKinds.Enum
                                    ? FindExistingEnumTypeId(shadowDecl, in types)
                                    : TryResolveConstTargetType(fd.TypeNode, shadowDecl, in fctx, in ast, in ta, in names, in bctx, in types);
                                if (ft <= 0) ft = TypeIds.I32;
                                if (!types.IsInteger(ft)) return false;
                                if (fd.HasConstVal != 0)
                                {
                                    constTypeId = ft;
                                    val = TruncateConstToType(fd.ConstVal, UnderlyingIntOrSelf(ft, in types));
                                    return true;
                                }
                                if (fd.InitExpr >= 0 && fd.InitExpr != exprId &&
                                    TryEvalTypedIntConstExpr(fd.InitExpr, shadowDecl, in fctx, in ast, in ta, in names, in bctx, in types, out _, out long initV))
                                {
                                    constTypeId = ft;
                                    val = TruncateConstToType(initV, UnderlyingIntOrSelf(ft, in types));
                                    return true;
                                }
                            }
                        }
                        return false;
                    }

                    if (target.D != 1)
                    {
                        if (DeclBinder.TryEvalBuiltinNumericConstMember(names.Text(target.A), names.Text(n.B), out int bTid, out long bVal, out bool bFloat) && !bFloat)
                        {
                            constTypeId = bTid;
                            val = TruncateConstToType(bVal, bTid);
                            return true;
                        }
                    }
                }
                if (TryResolveConstOwnerDeclFromMemberTarget(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int mOwnerDecl) && mOwnerDecl >= 0)
                {
                    TypeDecl mtd = ast.Types[mOwnerDecl];
                    for (int f = 0; f < mtd.FieldCount; f++)
                    {
                        FieldDecl fd = ast.Fields[mtd.FieldStart + f];
                        if (fd.NameId == n.B && (fd.Flags & DeclFlags.IsConst) != 0)
                        {
                            int ft = mtd.Kind == TypeDeclKinds.Enum
                                ? FindExistingEnumTypeId(mOwnerDecl, in types)
                                : TryResolveConstTargetType(fd.TypeNode, mOwnerDecl, in fctx, in ast, in ta, in names, in bctx, in types);
                            if (ft <= 0) ft = TypeIds.I32;
                            if (!types.IsInteger(ft)) return false;
                            if (fd.HasConstVal != 0)
                            {
                                constTypeId = ft;
                                val = TruncateConstToType(fd.ConstVal, UnderlyingIntOrSelf(ft, in types));
                                return true;
                            }
                            if (fd.InitExpr >= 0 && fd.InitExpr != exprId &&
                                TryEvalTypedIntConstExpr(fd.InitExpr, mOwnerDecl, in fctx, in ast, in ta, in names, in bctx, in types, out _, out long initV))
                            {
                                constTypeId = ft;
                                val = TruncateConstToType(initV, UnderlyingIntOrSelf(ft, in types));
                                return true;
                            }
                        }
                    }
                    return false;
                }
                if (DeclBinder.TryEvalConstExpr(in ast, in ta, in names, in bctx, ownerDeclId, exprId, out long fallbackMv))
                {
                    constTypeId = TypeIds.I32;
                    val = fallbackMv;
                    return true;
                }
                return false;
            }

            case AstKind.ExprUnary:
            {
                if (n.C != 0) return false;
                TokKind uk = (TokKind)n.A;
                if (uk == TokKind.KwUnchecked)
                {
                    return TryEvalTypedIntConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out constTypeId, out val);
                }
                if (uk == TokKind.Minus && ast.Nodes[n.B].Kind == AstKind.ExprIntLit)
                {
                    Token lit = ta.Tokens[ast.Nodes[n.B].A];
                    if ((lit.AuxId & 4) != 0) return false;
                    if (lit.AuxId == 0 && (ulong)lit.IntVal == 2147483648UL && lit.Kind != TokKind.LongLit)
                    {
                        constTypeId = TypeIds.I32;
                        val = -2147483648L;
                        return true;
                    }
                    if ((lit.AuxId & 5) == 0 && (ulong)lit.IntVal == 9223372036854775808UL)
                    {
                        constTypeId = TypeIds.I64;
                        val = unchecked((long)9223372036854775808UL);
                        return true;
                    }
                }
                if (!TryEvalTypedIntConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int subT, out long sv))
                {
                    return false;
                }
                if (types.Items[subT].Kind == TypeKinds.Enum)
                {
                    if (uk != TokKind.Tilde) return false;
                    constTypeId = subT;
                    val = TruncateConstToType(~sv, TypeIds.I32);
                    return true;
                }
                int resT = subT;
                if (uk == TokKind.Minus)
                {
                    if (subT == TypeIds.U64 || subT == TypeIds.NUInt) return false;
                    if (subT == TypeIds.U32) resT = TypeIds.I64;
                    else if (types.IntBitWidth(subT) < 32) resT = TypeIds.I32;
                    constTypeId = resT;
                    val = TruncateConstToType(unchecked(-sv), resT);
                    return true;
                }
                if (uk == TokKind.Plus)
                {
                    if (types.IntBitWidth(subT) < 32) resT = TypeIds.I32;
                    constTypeId = resT;
                    val = TruncateConstToType(sv, resT);
                    return true;
                }
                if (uk == TokKind.Tilde)
                {
                    if (types.IntBitWidth(subT) < 32) resT = TypeIds.I32;
                    constTypeId = resT;
                    val = TruncateConstToType(~sv, resT);
                    return true;
                }
                return false;
            }

            case AstKind.ExprCond:
            {
                if (!TryEvalBoolConstExpr(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out bool condB))
                {
                    return false;
                }
                if (!TryEvalTypedIntConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int bt, out long bv) ||
                    !TryEvalTypedIntConstExpr(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int ct, out long cv))
                {
                    return false;
                }
                if (!TryResolveConstCondIntCommonType(bt, bv, ct, cv, in types, out int commonCondT))
                {
                    return false;
                }
                constTypeId = commonCondT;
                val = TruncateConstToType(condB ? bv : cv, UnderlyingIntOrSelf(commonCondT, in types));
                return true;
            }

            case AstKind.ExprCast:
            {
                int dstT = TryResolveConstTargetType(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types);
                if (dstT <= 0 || !types.IsInteger(dstT)) return false;
                int effDst = UnderlyingIntOrSelf(dstT, in types);
                if (TryEvalTypedIntConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int nativeSourceType, out long subV))
                {
                    if ((effDst == TypeIds.NInt || effDst == TypeIds.NUInt) &&
                        !ConstantFitsInExplicitIntTarget(UnderlyingIntOrSelf(nativeSourceType, in types), subV,
                            effDst == TypeIds.NInt ? TypeIds.I32 : TypeIds.U32, in types)) return false;
                    constTypeId = dstT;
                    val = TruncateConstToType(subV, effDst);
                    return true;
                }
                if (TryEvalFloatConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out _, out double subD))
                {
                    if (!TryTruncateFloatConstToIntTarget(subD, effDst, out long fIntVal))
                    {
                        // Native constants must be portable to 32-bit targets. Roslyn
                        // leaves other native casts nonconstant, even in unchecked code.
                        if (effDst == TypeIds.NInt || effDst == TypeIds.NUInt) return false;
                        fIntVal = 0;
                    }
                    constTypeId = dstT;
                    val = fIntVal;
                    return true;
                }
                return false;
            }

            case AstKind.ExprBinary:
            {
                TokKind bk = (TokKind)n.A;
                bool lInt = TryEvalTypedIntConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int lt, out long lv);
                bool rInt = TryEvalTypedIntConstExpr(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int rt, out long rv);
                if (!lInt || !rInt)
                {
                    // Preserve the enum conversion, not an implicit conversion to its
                    // underlying int: float zero works for E - E, but not for E + int.
                    if ((bk == TokKind.Minus || bk == TokKind.Amp || bk == TokKind.Pipe || bk == TokKind.Caret) &&
                        lInt && types.Items[lt].Kind == TypeKinds.Enum &&
                        IsZeroNumericConstExpr(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types))
                    {
                        rt = lt;
                        rv = 0L;
                    }
                    else if ((bk == TokKind.Minus || bk == TokKind.Amp || bk == TokKind.Pipe || bk == TokKind.Caret) &&
                             rInt && types.Items[rt].Kind == TypeKinds.Enum &&
                             IsZeroNumericConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types))
                    {
                        lt = rt;
                        lv = 0L;
                    }
                    else return false;
                }
                if (bk == TokKind.LtLt || bk == TokKind.GtGt || bk == TokKind.GtGtGt)
                {
                    int resT = types.IntBitWidth(lt) < 32 ? TypeIds.I32 : lt;
                    int mask = (resT == TypeIds.I32 || resT == TypeIds.U32) ? 31 : 63;
                    int sh = (int)rv & mask;
                    constTypeId = resT;
                    if (bk == TokKind.LtLt)
                    {
                        val = TruncateConstToType(unchecked(lv << sh), resT);
                        return true;
                    }
                    if (bk == TokKind.GtGt)
                    {
                        if (resT == TypeIds.U32) val = (long)((uint)lv >> sh);
                        else if (resT == TypeIds.U64 || resT == TypeIds.NUInt) val = unchecked((long)((ulong)lv >> sh));
                        else val = TruncateConstToType(lv >> sh, resT);
                        return true;
                    }
                    if (resT == TypeIds.I32 || resT == TypeIds.U32) val = TruncateConstToType((long)((uint)lv >> sh), resT);
                    else val = unchecked((long)((ulong)lv >> sh));
                    return true;
                }

                bool lEnum = types.Items[lt].Kind == TypeKinds.Enum;
                bool rEnum = types.Items[rt].Kind == TypeKinds.Enum;
                if (lEnum || rEnum)
                {
                    if (lEnum && rEnum)
                    {
                        if (lt != rt) return false;
                        int a32 = unchecked((int)lv);
                        int b32 = unchecked((int)rv);
                        if (bk == TokKind.Minus)
                        {
                            constTypeId = TypeIds.I32;
                            val = unchecked(a32 - b32);
                            return true;
                        }
                        if (bk == TokKind.Amp) { constTypeId = lt; val = a32 & b32; return true; }
                        if (bk == TokKind.Pipe) { constTypeId = lt; val = a32 | b32; return true; }
                        if (bk == TokKind.Caret) { constTypeId = lt; val = a32 ^ b32; return true; }
                        return false;
                    }
                    if (lEnum && (bk == TokKind.Plus || bk == TokKind.Minus) && CanConstImplicitConvertToInt32(rt, rv, in types))
                    {
                        constTypeId = lt;
                        int a32 = unchecked((int)lv);
                        int b32 = unchecked((int)rv);
                        val = bk == TokKind.Plus ? unchecked(a32 + b32) : unchecked(a32 - b32);
                        return true;
                    }
                    // An integral, non-char constant zero converts to the enum. Roslyn binds
                    // '0 - e' (and 'e - 0L') as E - E -> int, and other 'k - e' as U - E -> E.
                    bool zeroAsEnum = (lEnum && rt != TypeIds.Char && rv == 0) || (rEnum && lt != TypeIds.Char && lv == 0);
                    if (bk == TokKind.Minus && zeroAsEnum && !(lEnum && CanConstImplicitConvertToInt32(rt, rv, in types)))
                    {
                        constTypeId = TypeIds.I32;
                        val = unchecked((int)lv - (int)rv);
                        return true;
                    }
                    if (rEnum && (bk == TokKind.Plus || bk == TokKind.Minus) && CanConstImplicitConvertToInt32(lt, lv, in types))
                    {
                        constTypeId = rt;
                        val = bk == TokKind.Plus ? unchecked((int)lv + (int)rv) : unchecked((int)lv - (int)rv);
                        return true;
                    }
                    if ((bk == TokKind.Amp || bk == TokKind.Pipe || bk == TokKind.Caret) &&
                        ((lEnum && rt != TypeIds.Char && rv == 0) || (rEnum && lt != TypeIds.Char && lv == 0)))
                    {
                        int eT = lEnum ? lt : rt;
                        int a32 = unchecked((int)lv);
                        int b32 = unchecked((int)rv);
                        constTypeId = eT;
                        val = bk == TokKind.Amp ? (a32 & b32) : (bk == TokKind.Pipe ? (a32 | b32) : (a32 ^ b32));
                        return true;
                    }
                    return false;
                }

                int commonT = PromoteConstIntTypes(lt, lv, rt, rv, in types);
                if (commonT < 0) return false;
                constTypeId = commonT;
                bool isUns = types.IsUnsignedInteger(commonT);
                long a = TruncateConstToType(lv, commonT);
                long b = TruncateConstToType(rv, commonT);
                switch (bk)
                {
                    case TokKind.Plus:
                        val = TruncateConstToType(unchecked(a + b), commonT);
                        return true;
                    case TokKind.Minus:
                        val = TruncateConstToType(unchecked(a - b), commonT);
                        return true;
                    case TokKind.Star:
                        val = TruncateConstToType(unchecked(a * b), commonT);
                        return true;
                    case TokKind.Slash:
                        if (b == 0) return false;
                        if (isUns) val = TruncateConstToType(unchecked((long)((ulong)a / (ulong)b)), commonT);
                        else if (a == long.MinValue && b == -1) val = long.MinValue;
                        else val = TruncateConstToType(a / b, commonT);
                        return true;
                    case TokKind.Percent:
                        if (b == 0) return false;
                        if (isUns) val = TruncateConstToType(unchecked((long)((ulong)a % (ulong)b)), commonT);
                        else if (a == long.MinValue && b == -1) val = 0;
                        else val = TruncateConstToType(a % b, commonT);
                        return true;
                    case TokKind.Amp:
                        val = TruncateConstToType(a & b, commonT);
                        return true;
                    case TokKind.Pipe:
                        val = TruncateConstToType(a | b, commonT);
                        return true;
                    case TokKind.Caret:
                        val = TruncateConstToType(a ^ b, commonT);
                        return true;
                    default:
                        return false;
                }
            }
        }
        return false;
    }

    private static int FindExistingEnumTypeId(int declId, in TypeTable types)
    {
        for (int i = 0; i < types.Items.Count; i++)
        {
            if (types.Items[i].Kind == TypeKinds.Enum && types.Items[i].A == declId)
            {
                return i;
            }
        }
        return TypeIds.I32;
    }

    private static int TryGuessConstFieldPrimType(int typeNodeId, in AstArena ast, in Interner names, in BinderCtx bctx)
    {
        if (typeNodeId < 0) return TypeIds.I32;
        AstNode tn = ast.Nodes[typeNodeId];
        if (tn.Kind == AstKind.TypePrim)
        {
            switch ((TokKind)tn.A)
            {
                case TokKind.KwSByte: return TypeIds.I8;
                case TokKind.KwByte: return TypeIds.U8;
                case TokKind.KwShort: return TypeIds.I16;
                case TokKind.KwUShort: return TypeIds.U16;
                case TokKind.KwChar: return TypeIds.Char;
                case TokKind.KwInt: return TypeIds.I32;
                case TokKind.KwUInt: return TypeIds.U32;
                case TokKind.KwLong: return TypeIds.I64;
                case TokKind.KwULong: return TypeIds.U64;
                case TokKind.KwNInt: return TypeIds.NInt;
                case TokKind.KwNUInt: return TypeIds.NUInt;
                default: return -1;
            }
        }
        if (tn.Kind == AstKind.TypeNamed && tn.C == 0)
        {
            ReadOnlySpan<byte> nm = names.Text(tn.A);
            if (Bytes.Eq(nm, "Int32"u8)) return TypeIds.I32;
            if (Bytes.Eq(nm, "UInt32"u8)) return TypeIds.U32;
            if (Bytes.Eq(nm, "Int64"u8)) return TypeIds.I64;
            if (Bytes.Eq(nm, "UInt64"u8)) return TypeIds.U64;
            if (Bytes.Eq(nm, "Byte"u8)) return TypeIds.U8;
            if (Bytes.Eq(nm, "SByte"u8)) return TypeIds.I8;
            if (Bytes.Eq(nm, "Int16"u8)) return TypeIds.I16;
            if (Bytes.Eq(nm, "UInt16"u8)) return TypeIds.U16;
            if (Bytes.Eq(nm, "Char"u8)) return TypeIds.Char;
            if (Bytes.Eq(nm, "IntPtr"u8)) return TypeIds.NInt;
            if (Bytes.Eq(nm, "UIntPtr"u8)) return TypeIds.NUInt;
        }
        return -1;
    }

    public static void ValidateConstFieldInit(
        int ownerDeclId,
        int fieldTypeId,
        int initExprId,
        int tokIdx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        if (initExprId < 0 || fieldTypeId == TypeIds.Error || ast.Types[ownerDeclId].FuncCount == 0 && ast.Funcs.Count == 0)
        {
            return;
        }
        int dummyFnDecl = ast.Types[ownerDeclId].FuncCount > 0 ? ast.Types[ownerDeclId].FuncStart : 0;
        var fctx = new FuncLowerCtx(-1, dummyFnDecl, -1, TypeIds.Void, isCtor: false, returnsByRef: false, returnRefMut: false);
        fctx.EnclosingOwnerDeclId = ownerDeclId;
        fctx.CurBlock = fctx.NewBlock();
        _ = LowerExprAsOperand(initExprId, fieldTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
    }

    private static int UnderlyingIntOrSelf(int typeId, in TypeTable types)
    {
        if (typeId >= 0 && typeId < types.Items.Count && types.Items[typeId].Kind == TypeKinds.Enum)
        {
            return types.Items[typeId].B > 0 ? types.Items[typeId].B : TypeIds.I32;
        }
        return typeId;
    }

    private static int TryResolveConstTargetType(
        int typeNodeId,
        int ownerDeclId,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types)
    {
        if (typeNodeId < 0) return -1;
        AstNode tn = ast.Nodes[typeNodeId];
        if (tn.Kind == AstKind.TypePrim)
        {
            switch ((TokKind)tn.A)
            {
                case TokKind.KwBool: return TypeIds.Bool;
                case TokKind.KwFloat: return TypeIds.F32;
                case TokKind.KwDouble: return TypeIds.F64;
                case TokKind.KwString: return TypeIds.Str;
            }
        }
        int prim = TryGuessConstFieldPrimType(typeNodeId, in ast, in names, in bctx);
        if (prim > 0) return prim;
        if (tn.Kind == AstKind.TypeNamed && tn.C == 0)
        {
            ReadOnlySpan<byte> nm = names.Text(tn.A);
            if (tn.D >= 0 && tn.D < ast.TypeRefs.Count && ast.TypeRefs[tn.D].PrefixNsId >= 0)
            {
                TypeRefContext trc = ast.TypeRefs[tn.D];
                if (trc.PrefixNsId == bctx.IdSystem || trc.PrefixNsId == bctx.IdGlobalSystem)
                {
                    if (DeclBinder.TryMapSystemPrimTypeName(nm, out int sPrim)) return sPrim;
                    return -1;
                }
                if (DeclBinder.TryResolvePrefixViaAlias(trc.PrefixNsId, tn.A, 0, trc.UnitKind, trc.CurrentNsId, trc.EnclosingOwnerDeclId, trc.UsingExtraStart, trc.UsingCount, in ast, in names, in bctx, out bool pIsNs, out int pNs, out int aNested, out bool pAmb))
                {
                    if (pAmb) return -1;
                    if (pIsNs)
                    {
                        if (pNs == bctx.IdSystem && DeclBinder.TryMapSystemPrimTypeName(nm, out int sp2)) return sp2;
                        int qd = DeclBinder.FindDeclaredTypeInExactNamespace(tn.A, 0, pNs, trc.UnitKind, in ast, in bctx);
                        if (qd >= 0 && ast.Types[qd].Kind == TypeDeclKinds.Enum) return FindExistingEnumTypeId(qd, in types);
                    }
                    else if (aNested >= 0 && ast.Types[aNested].Kind == TypeDeclKinds.Enum)
                    {
                        return FindExistingEnumTypeId(aNested, in types);
                    }
                    return -1;
                }
                int qDecl = DeclBinder.LookupQualifiedTypeDecl(tn.A, 0, trc.PrefixNsId, trc.UnitKind, trc.CurrentNsId, trc.EnclosingOwnerDeclId, trc.UsingExtraStart, trc.UsingCount, in ast, in names, in bctx);
                if (qDecl >= 0 && ast.Types[qDecl].Kind == TypeDeclKinds.Enum)
                {
                    return FindExistingEnumTypeId(qDecl, in types);
                }
                return -1;
            }

            GetActiveUsingSlice(ownerDeclId, tn.TokIdx, in fctx, in ast, in ta, out int callerUnit, out int curNs, out int effOwner, out int uStart, out int uCount);
            if (callerUnit == UnitKinds.App)
            {
                int rk = DeclBinder.ResolveAppUnqualifiedName(tn.A, 0, curNs, effOwner, uStart, uCount, in ast, in names, in bctx, out int fDecl, out int fAliasIdx, out bool mSys, out _);
                if (rk == 1 && fDecl >= 0 && ast.Types[fDecl].Kind == TypeDeclKinds.Enum)
                {
                    return FindExistingEnumTypeId(fDecl, in types);
                }
                if (rk == 2 && fAliasIdx >= 0 && fAliasIdx < bctx.UsingBoundKind.Count)
                {
                    int bk = bctx.UsingBoundKind[fAliasIdx];
                    if (bk == 3 && bctx.UsingBoundId[fAliasIdx] == 0 && bctx.UsingBoundTypeId[fAliasIdx] > 0)
                    {
                        return bctx.UsingBoundTypeId[fAliasIdx];
                    }
                    if (bk == 2)
                    {
                        int ad = bctx.UsingBoundId[fAliasIdx];
                        if (ad >= 0 && ast.Types[ad].Kind == TypeDeclKinds.Enum)
                        {
                            return FindExistingEnumTypeId(ad, in types);
                        }
                    }
                    return -1;
                }
                if (rk == 3)
                {
                    if (mSys && DeclBinder.TryMapSystemPrimTypeName(nm, out int sPrim2))
                    {
                        return sPrim2;
                    }
                    if (!mSys && fDecl >= 0 && ast.Types[fDecl].Kind == TypeDeclKinds.Enum)
                    {
                        return FindExistingEnumTypeId(fDecl, in types);
                    }
                }
                return -1;
            }

            if (DeclBinder.TryMapSystemPrimTypeName(nm, out int stdSysPrim))
            {
                return stdSysPrim;
            }
            int d = DeclBinder.LookupUnqualifiedTypeDecl(tn.A, 0, callerUnit, curNs, effOwner, uStart, uCount, in ast, in names, in bctx);
            if (d >= 0 && ast.Types[d].Kind == TypeDeclKinds.Enum)
            {
                return FindExistingEnumTypeId(d, in types);
            }
        }
        return -1;
    }

    private static bool LookupImportedStaticConstReadOnly(
        int memberNameId,
        int ownerDeclId,
        int tokIdx,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        out int outKind,
        out int outTypeId,
        out int outEnumDeclId,
        out long outIntVal,
        out double outFltVal)
    {
        GetActiveUsingSlice(ownerDeclId, tokIdx, in fctx, in ast, in ta, out int callerUnit, out int curNs, out int effOwner, out int uStart, out int uCount);
        if (callerUnit != UnitKinds.App || uCount <= 0)
        {
            outKind = 0;
            outTypeId = TypeIds.Error;
            outEnumDeclId = -1;
            outIntVal = 0;
            outFltVal = 0.0;
            return false;
        }
        var dummyDiags = new DiagnosticBag(0);
        bool hadDiag = false;
        Token tok = tokIdx >= 0 ? ta.Tokens[tokIdx] : default;
        return DeclBinder.TryLookupImportedStaticConst(memberNameId, effOwner, curNs, uStart, uCount, tok, emitDiags: false, in ast, in names, in bctx, ref dummyDiags, ref hadDiag, out outKind, out outTypeId, out outEnumDeclId, out outIntVal, out outFltVal);
    }

    private static void GetActiveUsingSlice(
        int ownerDeclId,
        int tokIdx,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        out int callerUnit,
        out int curNs,
        out int curOwner,
        out int uStart,
        out int uCount)
    {
        int funcOwner = fctx.FuncDeclId >= 0 ? ast.Funcs[fctx.FuncDeclId].OwnerDeclId : fctx.EnclosingOwnerDeclId;
        if (ownerDeclId >= 0 && ownerDeclId != funcOwner)
        {
            TypeDecl otd = ast.Types[ownerDeclId];
            curOwner = ownerDeclId;
            callerUnit = otd.UnitKind;
            curNs = otd.NsId;
            uStart = otd.UsingExtraStart;
            uCount = otd.UsingCount;
            return;
        }
        if (fctx.FuncDeclId >= 0)
        {
            FuncDecl fd = ast.Funcs[fctx.FuncDeclId];
            curOwner = fd.OwnerDeclId >= 0 ? fd.OwnerDeclId : fctx.EnclosingOwnerDeclId;
            callerUnit = curOwner >= 0
                ? ast.Types[curOwner].UnitKind
                : (fd.SourceId >= 0 && fd.SourceId < ast.SourceUnitKinds.Count ? ast.SourceUnitKinds[fd.SourceId] : UnitKinds.App);
            curNs = curOwner >= 0 ? ast.Types[curOwner].NsId : -1;
            uStart = fd.UsingExtraStart;
            uCount = fd.UsingCount;
            return;
        }
        if (funcOwner >= 0)
        {
            TypeDecl td = ast.Types[funcOwner];
            curOwner = funcOwner;
            callerUnit = td.UnitKind;
            curNs = td.NsId;
            uStart = td.UsingExtraStart;
            uCount = td.UsingCount;
            return;
        }
        int srcId = tokIdx >= 0 ? ta.Tokens[tokIdx].SourceId : -1;
        curOwner = -1;
        callerUnit = srcId >= 0 && srcId < ast.SourceUnitKinds.Count ? ast.SourceUnitKinds[srcId] : UnitKinds.App;
        curNs = -1;
        uStart = srcId >= 0 && srcId < ast.SourceUsingStarts.Count ? ast.SourceUsingStarts[srcId] : 0;
        uCount = srcId >= 0 && srcId < ast.SourceUsingCounts.Count ? ast.SourceUsingCounts[srcId] : 0;
    }

    private static bool TryResolveConstOwnerDeclFromMemberTarget(int targetExprId, int ownerDeclId, in FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, in BinderCtx bctx, in TypeTable types, out int resolvedDeclId) => TryResolveConstOwnerDeclFromMemberTarget(targetExprId, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out resolvedDeclId, -1);

    private static bool TryResolveConstOwnerDeclFromMemberTarget(
        int targetExprId,
        int ownerDeclId,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types,
        out int resolvedDeclId,
        int memberHintNameId)
    {
        resolvedDeclId = -1;
        AstNode t = ast.Nodes[targetExprId];
        GetActiveUsingSlice(ownerDeclId, t.TokIdx, in fctx, in ast, in ta, out int callerUnit, out int curNs, out int effOwner, out int uStart, out int uCount);

        if (t.Kind == AstKind.ExprIdent)
        {
            if (t.C > 0 || t.D == 2) return false;
            if (t.D == 1)
            {
                if (callerUnit == UnitKinds.App)
                {
                    Option<int> gOpt = bctx.AppGlobalTypeByNameArity.Get(DeclBinder.PackNameArity(t.A, 0));
                    if (gOpt.IsSome) { resolvedDeclId = gOpt.Unwrap(); return true; }
                }
                return false;
            }
            int d = DeclBinder.LookupUnqualifiedTypeDecl(t.A, 0, callerUnit, curNs, effOwner, uStart, uCount, in ast, in names, in bctx);
            int fv = fctx.FindVar(t.A, out bool isC, out int cTid, out _);
            if (fv >= 0 || fv == -2 || isC)
            {
                if (d >= 0 && memberHintNameId >= 0)
                {
                    int vTid = isC || fv == -2 ? cTid : fctx.Locals[fv].TypeId;
                    if (vTid >= 0 && (types.Items[vTid].Kind == TypeKinds.Ref || types.Items[vTid].Kind == TypeKinds.RefReadOnly))
                    {
                        vTid = types.Items[vTid].A;
                    }
                    if (vTid >= 0 &&
                        (types.Items[vTid].Kind == TypeKinds.Enum || types.Items[vTid].Kind == TypeKinds.Struct || types.Items[vTid].Kind == TypeKinds.Class) &&
                        types.Items[vTid].A == d && types.Items[vTid].C == 0 &&
                        FindInstanceFieldIndex(vTid, memberHintNameId, in types) < 0 &&
                        FindMethodInType(d, MakePropGetterLookup(memberHintNameId, in ast, in names), 0, isStatic: false, in ast) < 0)
                    {
                        resolvedDeclId = d;
                        return true;
                    }
                }
                return false;
            }
            if (d >= 0) { resolvedDeclId = d; return true; }
            return false;
        }
        if (t.Kind == AstKind.ExprMember && t.D == 0)
        {
            if (TryResolveConstOwnerDeclFromMemberTarget(t.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int parentDecl) && parentDecl >= 0)
            {
                for (int ci = 0; ci < ast.Types.Count; ci++)
                {
                    TypeDecl ctd = ast.Types[ci];
                    if (ctd.OwnerDeclId == parentDecl && ctd.NameId == t.B && ctd.TypeParamCount == 0)
                    {
                        resolvedDeclId = ci;
                        return true;
                    }
                }
                return false;
            }
            var nsPath = new StringBuf(48);
            if (TryBuildNamespaceExprPath(t.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, ref nsPath, out bool rootedGlobal))
            {
                int nsId = FindInternedText(nsPath.AsUtf8(), in names);
                if (nsId >= 0)
                {
                    int qd = rootedGlobal
                        ? DeclBinder.FindDeclaredTypeInExactNamespace(t.B, 0, nsId, callerUnit, in ast, in bctx)
                        : DeclBinder.LookupQualifiedTypeDecl(t.B, 0, nsId, callerUnit, curNs, effOwner, uStart, uCount, in ast, in names, in bctx);
                    if (qd >= 0) { resolvedDeclId = qd; return true; }
                }
            }
        }
        return false;
    }

    private static double ScalePow2Double(double v, int p)
    {
        while (p >= 60) { v *= (double)(1UL << 60); p -= 60; }
        while (p > 0) { int s = p > 60 ? 60 : p; v *= (double)(1UL << s); p -= s; }
        while (p <= -60) { v /= (double)(1UL << 60); p += 60; }
        while (p < 0) { int s = -p > 60 ? 60 : -p; v /= (double)(1UL << s); p += s; }
        return v;
    }

    private static double BitsToDouble(long bits)
    {
        ulong u = (ulong)bits;
        bool neg = (u >> 63) != 0;
        int exp = (int)((u >> 52) & 0x7FFUL);
        ulong frac = u & 0xFFFFFFFFFFFFFUL;
        if (exp == 0x7FF)
        {
            double z = 0.0;
            double one = 1.0;
            if (frac != 0) return z / z;
            return neg ? (-one / z) : (one / z);
        }
        if (exp == 0)
        {
            if (frac == 0)
            {
                double z = 0.0;
                return neg ? -z : z;
            }
            double sub = ScalePow2Double((double)frac, -1074);
            return neg ? -sub : sub;
        }
        ulong mant = (1UL << 52) | frac;
        double val = ScalePow2Double((double)mant, exp - 1075);
        return neg ? -val : val;
    }

    private static long DoubleToBits(double d)
    {
        double dCmp = d;
        if (d != dCmp) return unchecked((long)0xFFF8000000000000UL);
        if (d == 0.0)
        {
            double inv = 1.0 / d;
            return inv < 0.0 ? unchecked((long)0x8000000000000000UL) : 0L;
        }
        ulong sign = 0;
        if (d < 0.0) { sign = 1UL << 63; d = -d; }
        if (d - d != 0.0) return unchecked((long)(sign | (0x7FFUL << 52)));

        int e = 0;
        double m = d;
        double two52 = (double)(1UL << 52);
        while (m >= two52) { m /= two52; e += 52; }
        while (m >= 2.0) { m *= 0.5; e += 1; }
        double invTwo52 = 1.0 / two52;
        while (m < invTwo52 && e > -1022)
        {
            int rem = e + 1022;
            int step = rem > 52 ? 52 : rem;
            m *= (double)(1UL << step);
            e -= step;
        }
        while (m < 1.0 && e > -1022) { m *= 2.0; e -= 1; }
        if (m < 1.0)
        {
            ulong sub = (ulong)(m * two52);
            return unchecked((long)(sign | sub));
        }
        ulong full = (ulong)(m * two52);
        ulong frac = full & 0xFFFFFFFFFFFFFUL;
        ulong biased = (ulong)(e + 1023) & 0x7FFUL;
        return unchecked((long)(sign | (biased << 52) | frac));
    }

    private static float BitsToFloat(long bits)
    {
        uint u = (uint)bits;
        bool neg = (u >> 31) != 0;
        int exp = (int)((u >> 23) & 0xFFU);
        uint frac = u & 0x7FFFFFU;
        if (exp == 0xFF)
        {
            float z = 0.0f;
            float one = 1.0f;
            if (frac != 0) return z / z;
            return neg ? (-one / z) : (one / z);
        }
        if (exp == 0)
        {
            if (frac == 0)
            {
                float z = 0.0f;
                return neg ? -z : z;
            }
            float sub = (float)ScalePow2Double((double)frac, -149);
            return neg ? -sub : sub;
        }
        uint mant = (1U << 23) | frac;
        float val = (float)ScalePow2Double((double)mant, exp - 150);
        return neg ? -val : val;
    }

    private static int FloatToBits(float f)
    {
        float fCmp = f;
        if (f != fCmp) return unchecked((int)0xFFC00000U);
        if (f == 0.0f)
        {
            float inv = 1.0f / f;
            return inv < 0.0f ? unchecked((int)0x80000000U) : 0;
        }
        uint sign = 0;
        double d = (double)f;
        if (d < 0.0) { sign = 1U << 31; d = -d; }
        if (d - d != 0.0) return unchecked((int)(sign | (0xFFU << 23)));

        int e = 0;
        double m = d;
        while (m >= 2.0) { m *= 0.5; e += 1; }
        while (m < 1.0 && e > -126) { m *= 2.0; e -= 1; }
        double two23 = (double)(1U << 23);
        if (m < 1.0)
        {
            uint sub = (uint)(m * two23);
            return unchecked((int)(sign | sub));
        }
        uint full = (uint)(m * two23);
        uint frac = full & 0x7FFFFFU;
        uint biased = (uint)(e + 127) & 0xFFU;
        return unchecked((int)(sign | (biased << 23) | frac));
    }

    private static bool TryParseDecFloat(ReadOnlySpan<byte> s, out double result)
    {
        result = 0.0;
        if (s.Length == 0) return false;
        int i = 0;
        bool neg = false;
        if (s[i] == (byte)'-' || s[i] == (byte)'+')
        {
            neg = s[i] == (byte)'-';
            i += 1;
        }
        ulong mant = 0;
        int sigDigits = 0;
        int decExp = 0;
        bool seenDot = false;
        bool anyDigit = false;
        while (i < s.Length)
        {
            byte b = s[i];
            if (b == (byte)'_') { i += 1; continue; }
            if (b == (byte)'.')
            {
                if (seenDot) return false;
                seenDot = true;
                i += 1;
                continue;
            }
            if (b == (byte)'e' || b == (byte)'E') break;
            if (b < (byte)'0' || b > (byte)'9') return false;
            anyDigit = true;
            int d = b - (byte)'0';
            if (mant == 0 && d == 0)
            {
                if (seenDot) decExp -= 1;
            }
            else if (sigDigits < 19)
            {
                mant = mant * 10UL + (ulong)d;
                sigDigits += 1;
                if (seenDot) decExp -= 1;
            }
            else
            {
                if (!seenDot) decExp += 1;
            }
            i += 1;
        }
        if (!anyDigit) return false;
        if (i < s.Length && (s[i] == (byte)'e' || s[i] == (byte)'E'))
        {
            i += 1;
            bool expNeg = false;
            if (i < s.Length && (s[i] == (byte)'+' || s[i] == (byte)'-'))
            {
                expNeg = s[i] == (byte)'-';
                i += 1;
            }
            int eVal = 0;
            bool anyExp = false;
            while (i < s.Length)
            {
                byte b = s[i];
                if (b == (byte)'_') { i += 1; continue; }
                if (b < (byte)'0' || b > (byte)'9') return false;
                anyExp = true;
                if (eVal < 10000) eVal = eVal * 10 + (b - (byte)'0');
                i += 1;
            }
            if (!anyExp) return false;
            decExp += expNeg ? -eVal : eVal;
        }
        if (mant == 0)
        {
            double z = 0.0;
            result = neg ? -z : z;
            return true;
        }
        double v = (double)mant;
        while (decExp >= 10) { v *= 10000000000.0; decExp -= 10; }
        while (decExp > 0) { v *= 10.0; decExp -= 1; }
        while (decExp <= -10) { v /= 10000000000.0; decExp += 10; }
        while (decExp < 0) { v /= 10.0; decExp += 1; }
        result = neg ? -v : v;
        return true;
    }

    private static bool TryTruncateFloatConstToIntTarget(double d, int effDstTid, out long truncated)
    {
        truncated = 0;
        double dCmp = d;
        if (d != dCmp || (d - dCmp) != 0.0) return false;

        switch (effDstTid)
        {
            case TypeIds.I8:
                if (d <= -129.0 || d >= 128.0) return false;
                truncated = (sbyte)(long)d;
                return true;
            case TypeIds.U8:
                if (d <= -1.0 || d >= 256.0) return false;
                truncated = (byte)(long)d;
                return true;
            case TypeIds.I16:
                if (d <= -32769.0 || d >= 32768.0) return false;
                truncated = (short)(long)d;
                return true;
            case TypeIds.U16:
            case TypeIds.Char:
                if (d <= -1.0 || d >= 65536.0) return false;
                truncated = (ushort)(long)d;
                return true;
            case TypeIds.I32:
            case TypeIds.NInt:
                if (d <= -2147483649.0 || d >= 2147483648.0) return false;
                truncated = (int)(long)d;
                return true;
            case TypeIds.U32:
            case TypeIds.NUInt:
                if (d <= -1.0 || d >= 4294967296.0) return false;
                truncated = (long)(uint)(ulong)d;
                return true;
            case TypeIds.I64:
                if (d < -9223372036854775808.0 || d >= 9223372036854775808.0) return false;
                if (d == -9223372036854775808.0)
                {
                    truncated = long.MinValue;
                    return true;
                }
                truncated = (long)d;
                return true;
            case TypeIds.U64:
                if (d <= -1.0 || d >= 18446744073709551616.0) return false;
                if (d <= 0.0)
                {
                    truncated = 0;
                    return true;
                }
                truncated = unchecked((long)(ulong)d);
                return true;
            default:
                return false;
        }
    }

    private static bool TryEvalFloatConstExpr(
        int exprId,
        int ownerDeclId,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types,
        out int floatTypeId,
        out double val)
    {
        floatTypeId = TypeIds.F64;
        val = 0.0;
        if (exprId < 0) return false;
        AstNode n = ast.Nodes[exprId];
        switch (n.Kind)
        {
            case AstKind.ExprFloatLit:
            {
                Token fTok = ta.Tokens[n.A];
                bool isSingle = fTok.Kind == TokKind.FloatLit;
                if (!DeclBinder.TryParseExactDecimalFloat(ta.GetLit(fTok.AuxId), isSingle, out long exactBits))
                {
                    return false;
                }
                if (isSingle)
                {
                    floatTypeId = TypeIds.F32;
                    val = (double)BitsToFloat(exactBits);
                }
                else
                {
                    floatTypeId = TypeIds.F64;
                    val = BitsToDouble(exactBits);
                }
                return true;
            }
            case AstKind.ExprDefault:
            {
                if (n.A < 0) return false;
                int defT = TryResolveConstTargetType(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types);
                if (types.IsFloat(defT))
                {
                    floatTypeId = defT;
                    val = 0.0;
                    return true;
                }
                return false;
            }
            case AstKind.ExprIdent:
            {
                int localId = fctx.FindVar(n.A, out bool isC, out int cTid, out long cv);
                if (isC && types.IsFloat(cTid))
                {
                    floatTypeId = cTid;
                    val = cTid == TypeIds.F32 ? (double)BitsToFloat(cv) : BitsToDouble(cv);
                    return true;
                }
                // A nearer runtime (or differently typed const) binding hides fields and imports.
                if (localId != -1 || isC) return false;
                for (int d = ownerDeclId; d >= 0; d = ast.Types[d].OwnerDeclId)
                {
                    TypeDecl otd = ast.Types[d];
                    for (int f = 0; f < otd.FieldCount; f++)
                    {
                        FieldDecl fd = ast.Fields[otd.FieldStart + f];
                        if (fd.NameId == n.A && (fd.Flags & DeclFlags.IsConst) != 0)
                        {
                            int ft = TryResolveConstTargetType(fd.TypeNode, d, in fctx, in ast, in ta, in names, in bctx, in types);
                            if (types.IsFloat(ft))
                            {
                                if (fd.HasConstVal != 0)
                                {
                                    floatTypeId = ft;
                                    val = ft == TypeIds.F32 ? (double)BitsToFloat(fd.ConstVal) : BitsToDouble(fd.ConstVal);
                                    return true;
                                }
                                if (fd.InitExpr >= 0 && fd.InitExpr != exprId &&
                                    TryEvalFloatConstOrIntAsFloat(fd.InitExpr, d, in fctx, in ast, in ta, in names, in bctx, in types, out _, out double initD))
                                {
                                    floatTypeId = ft;
                                    val = ft == TypeIds.F32 ? (double)(float)initD : initD;
                                    return true;
                                }
                            }
                        }
                    }
                }
                if (LookupImportedStaticConstReadOnly(n.A, ownerDeclId, n.TokIdx, in fctx, in ast, in ta, in names, in bctx, out int fImpK, out int fImpPrim, out _, out _, out double fImpVal) && (fImpK == 3 || fImpK == 4))
                {
                    floatTypeId = fImpPrim;
                    val = fImpVal;
                    return true;
                }
                return false;
            }
            case AstKind.ExprMember:
            {
                AstNode target = ast.Nodes[n.A];
                if (target.Kind == AstKind.ExprIdent && target.D != 1)
                {
                    int fv = fctx.FindVar(target.A, out bool isVC, out _, out _);
                    if (fv < 0 && fv != -2 && !isVC)
                    {
                        int callerUnit = ownerDeclId >= 0 ? ast.Types[ownerDeclId].UnitKind : UnitKinds.App;
                        int callerNs = ownerDeclId >= 0 ? ast.Types[ownerDeclId].NsId : -1;
                        int shadow = callerUnit == UnitKinds.App
                            ? DeclBinder.FindAppTypeInLexicalScope(target.A, 0, callerNs, ownerDeclId, in ast, in names, in bctx)
                            : -1;
                        if (shadow < 0 && DeclBinder.TryEvalBuiltinNumericConstMember(names.Text(target.A), names.Text(n.B), out int bTid, out long bBits, out bool bFloat) && bFloat)
                        {
                            floatTypeId = bTid;
                            val = bTid == TypeIds.F32 ? (double)BitsToFloat(bBits) : BitsToDouble(bBits);
                            return true;
                        }
                    }
                }
                if (TryResolveConstOwnerDeclFromMemberTarget(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int mDecl, n.B) && mDecl >= 0)
                {
                    TypeDecl mtd = ast.Types[mDecl];
                    for (int f = 0; f < mtd.FieldCount; f++)
                    {
                        FieldDecl fd = ast.Fields[mtd.FieldStart + f];
                        if (fd.NameId == n.B && (fd.Flags & DeclFlags.IsConst) != 0)
                        {
                            int ft = TryResolveConstTargetType(fd.TypeNode, mDecl, in fctx, in ast, in ta, in names, in bctx, in types);
                            if (types.IsFloat(ft))
                            {
                                if (fd.HasConstVal != 0)
                                {
                                    floatTypeId = ft;
                                    val = ft == TypeIds.F32 ? (double)BitsToFloat(fd.ConstVal) : BitsToDouble(fd.ConstVal);
                                    return true;
                                }
                                if (fd.InitExpr >= 0 && fd.InitExpr != exprId &&
                                    TryEvalFloatConstOrIntAsFloat(fd.InitExpr, mDecl, in fctx, in ast, in ta, in names, in bctx, in types, out _, out double initD))
                                {
                                    floatTypeId = ft;
                                    val = ft == TypeIds.F32 ? (double)(float)initD : initD;
                                    return true;
                                }
                            }
                        }
                    }
                }
                return false;
            }
            case AstKind.ExprUnary:
            {
                if (n.C != 0) return false;
                TokKind uk = (TokKind)n.A;
                if (uk == TokKind.KwUnchecked || uk == TokKind.Plus)
                {
                    return TryEvalFloatConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out floatTypeId, out val);
                }
                if (uk == TokKind.Minus)
                {
                    if (!TryEvalFloatConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out floatTypeId, out double sv))
                    {
                        return false;
                    }
                    val = floatTypeId == TypeIds.F32 ? (double)(-(float)sv) : -sv;
                    return true;
                }
                return false;
            }
            case AstKind.ExprCast:
            {
                int dstT = TryResolveConstTargetType(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types);
                if (!types.IsFloat(dstT)) return false;
                if (dstT == TypeIds.F32)
                {
                    if (!TryEvalConstToSingle(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out float f32, allowEnumSource: true))
                    {
                        return false;
                    }
                    floatTypeId = TypeIds.F32;
                    val = (double)f32;
                    return true;
                }
                if (TryEvalTypedIntConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int itCast, out long ivCast))
                {
                    floatTypeId = TypeIds.F64;
                    val = types.IsUnsignedInteger(itCast) ? (double)(ulong)ivCast : (double)ivCast;
                    return true;
                }
                if (!TryEvalFloatConstOrIntAsFloat(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out _, out double sv))
                {
                    return false;
                }
                floatTypeId = dstT;
                val = sv;
                return true;
            }
            case AstKind.ExprCond:
            {
                if (!TryEvalBoolConstExpr(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out bool condB))
                {
                    return false;
                }
                bool bIsFloat = TryEvalFloatConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int ftB, out double valB);
                bool cIsFloat = TryEvalFloatConstExpr(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int ftC, out double valC);
                if (!bIsFloat && !cIsFloat) return false;
                if (!bIsFloat && !TryEvalFloatConstOrIntAsFloat(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out ftB, out valB))
                {
                    return false;
                }
                if (!cIsFloat && !TryEvalFloatConstOrIntAsFloat(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out ftC, out valC))
                {
                    return false;
                }
                floatTypeId = (bIsFloat && ftB == TypeIds.F64) || (cIsFloat && ftC == TypeIds.F64) ? TypeIds.F64 : TypeIds.F32;
                int selExpr = condB ? n.B : n.C;
                if (floatTypeId == TypeIds.F32)
                {
                    if (!TryEvalConstToSingle(selExpr, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out float selF32, allowEnumSource: false))
                    {
                        return false;
                    }
                    val = (double)selF32;
                    return true;
                }
                val = condB ? valB : valC;
                return true;
            }
            case AstKind.ExprBinary:
            {
                TokKind bk = (TokKind)n.A;
                if (bk != TokKind.Plus && bk != TokKind.Minus && bk != TokKind.Star && bk != TokKind.Slash && bk != TokKind.Percent)
                {
                    return false;
                }
                bool lFloat = TryEvalFloatConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int lft, out double lv);
                bool rFloat = TryEvalFloatConstExpr(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int rft, out double rv);
                if (!lFloat && !rFloat) return false;
                if (!lFloat && !TryEvalFloatConstOrIntAsFloat(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out lft, out lv)) return false;
                if (!rFloat && !TryEvalFloatConstOrIntAsFloat(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out rft, out rv)) return false;

                bool useF32 = (lFloat ? lft == TypeIds.F32 : true) && (rFloat ? rft == TypeIds.F32 : true);
                floatTypeId = useF32 ? TypeIds.F32 : TypeIds.F64;
                if (useF32)
                {
                    if (!TryEvalConstToSingle(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out float a, allowEnumSource: false) ||
                        !TryEvalConstToSingle(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out float b, allowEnumSource: false))
                    {
                        return false;
                    }
                    switch (bk)
                    {
                        case TokKind.Plus: val = (double)(a + b); return true;
                        case TokKind.Minus: val = (double)(a - b); return true;
                        case TokKind.Star: val = (double)(a * b); return true;
                        case TokKind.Slash: val = (double)(a / b); return true;
                        case TokKind.Percent: val = (double)(float)DeclBinder.FModDouble((double)a, (double)b); return true;
                    }
                }
                else
                {
                    switch (bk)
                    {
                        case TokKind.Plus: val = lv + rv; return true;
                        case TokKind.Minus: val = lv - rv; return true;
                        case TokKind.Star: val = lv * rv; return true;
                        case TokKind.Slash: val = lv / rv; return true;
                        case TokKind.Percent: val = DeclBinder.FModDouble(lv, rv); return true;
                    }
                }
                return false;
            }
        }
        return false;
    }

    private static bool TryEvalConstToSingle(
        int exprId,
        int ownerDeclId,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types,
        out float val,
        bool allowEnumSource)
    {
        if (TryEvalFloatConstExpr(exprId, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out _, out double dv))
        {
            val = (float)dv;
            return true;
        }
        if (TryEvalTypedIntConstExpr(exprId, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int it, out long iv) &&
            (allowEnumSource || types.Items[it].Kind != TypeKinds.Enum))
        {
            uint fBits = types.IsUnsignedInteger(it)
                ? (uint)DeclBinder.ULongToSingleBits((ulong)iv)
                : (uint)DeclBinder.LongToSingleBits(iv);
            val = BitsToFloat((long)fBits);
            return true;
        }
        val = 0.0f;
        return false;
    }

    private static bool TryEvalFloatConstOrIntAsFloat(
        int exprId,
        int ownerDeclId,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types,
        out int floatTypeId,
        out double val)
    {
        if (TryEvalFloatConstExpr(exprId, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out floatTypeId, out val))
        {
            return true;
        }
        if (TryEvalTypedIntConstExpr(exprId, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int it, out long iv) &&
            types.Items[it].Kind != TypeKinds.Enum)
        {
            floatTypeId = TypeIds.Error;
            val = types.IsUnsignedInteger(it) ? (double)(ulong)iv : (double)iv;
            return true;
        }
        floatTypeId = TypeIds.Error;
        val = 0.0;
        return false;
    }

    private static void CollectConstStrSlices(long strCode, in BinderCtx bctx, ref Vec<int> outSlices)
    {
        if (strCode == -1) return;
        if (strCode >= 0)
        {
            outSlices.Push((int)strCode);
            return;
        }
        int off = (int)(-(strCode + 2));
        if (off >= 0 && off < bctx.ConstStrChunks.Count)
        {
            int cnt = bctx.ConstStrChunks[off];
            for (int i = 0; i < cnt && off + 1 + i < bctx.ConstStrChunks.Count; i++)
            {
                outSlices.Push(bctx.ConstStrChunks[off + 1 + i]);
            }
        }
    }

    private static void AppendConstStrSlicesToBuf(in Vec<int> slices, in TokenArena ta, ref StringBuf sb)
    {
        for (int i = 0; i < slices.Count; i++)
        {
            int idx = slices[i];
            if (idx >= 0)
            {
                sb.Append(ta.GetLit(idx));
            }
        }
    }

    private static int MakeConstStringOperand(long strCode, int tokIdx, ref MirModuleArena mir)
    {
        int litIdx = strCode >= 0 ? (int)strCode : -1;
        return mir.AddOperand(new MirOperand(MirOpKinds.StrConst, litIdx, strCode, TypeIds.Str, tokIdx));
    }

    private static int EmitMultiChunkStrCodeAsReadOnlySpan(
        long strCode,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in TokenArena ta,
        in BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir)
    {
        int roSpanU8 = types.MakeSpan(TypeIds.U8, isReadOnly: true);
        var slices = new Vec<int>(4);
        CollectConstStrSlices(strCode, in bctx, ref slices);
        var sb = new StringBuf(32);
        AppendConstStrSlicesToBuf(in slices, in ta, ref sb);
        ReadOnlySpan<byte> bytes = sb.AsUtf8();
        var elemOps = new Vec<int>(bytes.Length);
        for (int i = 0; i < bytes.Length; i++)
        {
            elemOps.Push(mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, bytes[i], TypeIds.U8, tokIdx)));
        }
        int ssId = fctx.StackSpanCounter;
        fctx.StackSpanCounter += 1;
        fctx.SourceStackSpanContexts.Push(0);
        int dstTmp = fctx.AddLocal(-1, roSpanU8, PassMode.ByValue, MirLocalFlags.IsTemp, tokIdx);
        int dstPl = mir.AddPlaceLocal(dstTmp, roSpanU8);
        fctx.Emit(new MirInst(MirOp.StackSpan, dstPl, -1, 0, roSpanU8, mir.PushIdList(elemOps.AsReadOnlySpan()), elemOps.Count, ssId, 0, tokIdx));
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, roSpanU8, tokIdx));
    }

    private static bool TryEvalStringConstSlicesReadOnly(
        int exprId,
        int ownerDeclId,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types,
        ref Vec<int> outSlices)
    {
        if (exprId < 0) return false;
        AstNode n = ast.Nodes[exprId];
        switch (n.Kind)
        {
            case AstKind.ExprStrLit:
                if (n.A >= 0 && ta.GetLit(n.A).Length > 0) outSlices.Push(n.A);
                return true;
            case AstKind.ExprIdent:
            {
                int localId = fctx.FindVar(n.A, out bool isC, out int cTid, out long cv);
                if (isC && cTid == TypeIds.Str)
                {
                    CollectConstStrSlices(cv, in bctx, ref outSlices);
                    return true;
                }
                // A nearer runtime (or differently typed const) binding hides fields and imports.
                if (localId != -1 || isC) return false;
                for (int d = ownerDeclId; d >= 0; d = ast.Types[d].OwnerDeclId)
                {
                    TypeDecl otd = ast.Types[d];
                    for (int f = 0; f < otd.FieldCount; f++)
                    {
                        FieldDecl fd = ast.Fields[otd.FieldStart + f];
                        if (fd.NameId == n.A && (fd.Flags & DeclFlags.IsConst) != 0)
                        {
                            int ft = TryResolveConstTargetType(fd.TypeNode, d, in fctx, in ast, in ta, in names, in bctx, in types);
                            if (ft == TypeIds.Str)
                            {
                                if (fd.HasConstVal != 0)
                                {
                                    CollectConstStrSlices(fd.ConstVal, in bctx, ref outSlices);
                                    return true;
                                }
                                if (fd.InitExpr >= 0 && fd.InitExpr != exprId)
                                {
                                    return TryEvalStringConstSlicesReadOnly(fd.InitExpr, d, in fctx, in ast, in ta, in names, in bctx, in types, ref outSlices);
                                }
                            }
                        }
                    }
                }
                if (LookupImportedStaticConstReadOnly(n.A, ownerDeclId, n.TokIdx, in fctx, in ast, in ta, in names, in bctx, out int sImpK, out _, out _, out long sImpCode, out _) && sImpK == 5)
                {
                    CollectConstStrSlices(sImpCode, in bctx, ref outSlices);
                    return true;
                }
                return false;
            }
            case AstKind.ExprMember:
            {

                if (TryResolveConstOwnerDeclFromMemberTarget(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int mDecl, n.B) && mDecl >= 0)
                {
                    TypeDecl mtd = ast.Types[mDecl];
                    for (int f = 0; f < mtd.FieldCount; f++)
                    {
                        FieldDecl fd = ast.Fields[mtd.FieldStart + f];
                        if (fd.NameId == n.B && (fd.Flags & DeclFlags.IsConst) != 0)
                        {
                            int ft = TryResolveConstTargetType(fd.TypeNode, mDecl, in fctx, in ast, in ta, in names, in bctx, in types);
                            if (ft == TypeIds.Str)
                            {
                                if (fd.HasConstVal != 0)
                                {
                                    CollectConstStrSlices(fd.ConstVal, in bctx, ref outSlices);
                                    return true;
                                }
                                if (fd.InitExpr >= 0 && fd.InitExpr != exprId)
                                {
                                    return TryEvalStringConstSlicesReadOnly(fd.InitExpr, mDecl, in fctx, in ast, in ta, in names, in bctx, in types, ref outSlices);
                                }
                            }
                        }
                    }
                }
                return false;
            }
            case AstKind.ExprUnary:
                if (n.C == 0 && (TokKind)n.A == TokKind.KwUnchecked)
                {
                    return TryEvalStringConstSlicesReadOnly(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, ref outSlices);
                }
                return false;
            case AstKind.ExprCast:
                if (TryResolveConstTargetType(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types) == TypeIds.Str)
                {
                    return TryEvalStringConstSlicesReadOnly(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, ref outSlices);
                }
                return false;
            case AstKind.ExprBinary:
                return false;
            case AstKind.ExprCond:
            {
                if (!TryEvalBoolConstExpr(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out bool condB))
                {
                    return false;
                }
                var bs = new Vec<int>(2);
                var cs = new Vec<int>(2);
                if (!TryEvalStringConstSlicesReadOnly(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, ref bs) ||
                    !TryEvalStringConstSlicesReadOnly(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, ref cs))
                {
                    return false;
                }
                if (condB)
                {
                    for (int i = 0; i < bs.Count; i++) outSlices.Push(bs[i]);
                }
                else
                {
                    for (int i = 0; i < cs.Count; i++) outSlices.Push(cs[i]);
                }
                return true;
            }
        }
        return false;
    }

    private static bool TryEvalStringConstCode(
        int exprId,
        int ownerDeclId,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        in TypeTable types,
        out long strCode)
    {
        strCode = -1;
        var slices = new Vec<int>(4);
        if (!TryEvalStringConstSlicesReadOnly(exprId, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, ref slices))
        {
            return false;
        }
        if (slices.Count == 0)
        {
            strCode = -1;
            return true;
        }
        if (slices.Count == 1)
        {
            strCode = slices[0];
            return true;
        }
        long curCode = slices[0];
        for (int i = 1; i < slices.Count; i++)
        {
            curCode = DeclBinder.ConcatConstStrings(in ta, ref bctx.ConstStrChunks, curCode, slices[i]);
        }
        strCode = curCode;
        return true;
    }

    private static bool TryCompareConstEnum(TokKind op, long left, long right, out bool value)
    {
        value = false;
        switch (op)
        {
            case TokKind.LAngle: value = left < right; return true;
            case TokKind.LtEq: value = left <= right; return true;
            case TokKind.RAngle: value = left > right; return true;
            case TokKind.GtEq: value = left >= right; return true;
            case TokKind.EqEq: value = left == right; return true;
            case TokKind.BangEq: value = left != right; return true;
            default: return false;
        }
    }

    private static bool TryEvalBoolConstExpr(
        int exprId,
        int ownerDeclId,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types,
        out bool val)
    {
        val = false;
        if (exprId < 0) return false;
        AstNode n = ast.Nodes[exprId];
        switch (n.Kind)
        {
            case AstKind.ExprBoolLit:
                val = n.A != 0;
                return true;
            case AstKind.ExprDefault:
            {
                if (n.A < 0) return false;
                if (TryResolveConstTargetType(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types) == TypeIds.Bool)
                {
                    val = false;
                    return true;
                }
                return false;
            }
            case AstKind.ExprIdent:
            {
                int localId = fctx.FindVar(n.A, out bool isC, out int cTid, out long cv);
                if (isC && cTid == TypeIds.Bool)
                {
                    val = cv != 0;
                    return true;
                }
                // A nearer runtime (or differently typed const) binding hides fields and imports.
                if (localId != -1 || isC) return false;
                for (int d = ownerDeclId; d >= 0; d = ast.Types[d].OwnerDeclId)
                {
                    TypeDecl otd = ast.Types[d];
                    for (int f = 0; f < otd.FieldCount; f++)
                    {
                        FieldDecl fd = ast.Fields[otd.FieldStart + f];
                        if (fd.NameId == n.A && (fd.Flags & DeclFlags.IsConst) != 0)
                        {
                            int ft = TryResolveConstTargetType(fd.TypeNode, d, in fctx, in ast, in ta, in names, in bctx, in types);
                            if (ft == TypeIds.Bool)
                            {
                                if (fd.HasConstVal != 0) { val = fd.ConstVal != 0; return true; }
                                if (fd.InitExpr >= 0 && fd.InitExpr != exprId)
                                {
                                    return TryEvalBoolConstExpr(fd.InitExpr, d, in fctx, in ast, in ta, in names, in bctx, in types, out val);
                                }
                            }
                        }
                    }
                }
                if (LookupImportedStaticConstReadOnly(n.A, ownerDeclId, n.TokIdx, in fctx, in ast, in ta, in names, in bctx, out int bImpK, out _, out _, out long bImpBits, out _) && bImpK == 2)
                {
                    val = bImpBits != 0;
                    return true;
                }
                return false;
            }
            case AstKind.ExprMember:
            {
                if (TryResolveConstOwnerDeclFromMemberTarget(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int mDecl, n.B) && mDecl >= 0)
                {
                    TypeDecl mtd = ast.Types[mDecl];
                    for (int f = 0; f < mtd.FieldCount; f++)
                    {
                        FieldDecl fd = ast.Fields[mtd.FieldStart + f];
                        if (fd.NameId == n.B && (fd.Flags & DeclFlags.IsConst) != 0)
                        {
                            int ft = TryResolveConstTargetType(fd.TypeNode, mDecl, in fctx, in ast, in ta, in names, in bctx, in types);
                            if (ft == TypeIds.Bool)
                            {
                                if (fd.HasConstVal != 0) { val = fd.ConstVal != 0; return true; }
                                if (fd.InitExpr >= 0 && fd.InitExpr != exprId)
                                {
                                    return TryEvalBoolConstExpr(fd.InitExpr, mDecl, in fctx, in ast, in ta, in names, in bctx, in types, out val);
                                }
                            }
                        }
                    }
                }
                return false;
            }
            case AstKind.ExprUnary:
            {
                if (n.C != 0) return false;
                TokKind uk = (TokKind)n.A;
                if (uk == TokKind.KwUnchecked)
                {
                    return TryEvalBoolConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out val);
                }
                if (uk == TokKind.Bang)
                {
                    if (!TryEvalBoolConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out bool sub)) return false;
                    val = !sub;
                    return true;
                }
                return false;
            }
            case AstKind.ExprCast:
                if (TryResolveConstTargetType(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types) == TypeIds.Bool)
                {
                    return TryEvalBoolConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out val);
                }
                return false;
            case AstKind.ExprCond:
            {
                if (!TryEvalBoolConstExpr(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out bool condB)) return false;
                if (!TryEvalBoolConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out bool bArm) ||
                    !TryEvalBoolConstExpr(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out bool cArm))
                {
                    return false;
                }
                val = condB ? bArm : cArm;
                return true;
            }
            case AstKind.ExprBinary:
            {
                TokKind bk = (TokKind)n.A;
                if (bk == TokKind.AmpAmp)
                {
                    if (!TryEvalBoolConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out bool lb) ||
                        !TryEvalBoolConstExpr(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out bool rb))
                    {
                        return false;
                    }
                    val = lb && rb;
                    return true;
                }
                if (bk == TokKind.PipePipe)
                {
                    if (!TryEvalBoolConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out bool lb) ||
                        !TryEvalBoolConstExpr(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out bool rb))
                    {
                        return false;
                    }
                    val = lb || rb;
                    return true;
                }
                if ((bk == TokKind.Amp || bk == TokKind.Pipe || bk == TokKind.Caret || bk == TokKind.EqEq || bk == TokKind.BangEq) &&
                    TryEvalBoolConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out bool bl) &&
                    TryEvalBoolConstExpr(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out bool br))
                {
                    switch (bk)
                    {
                        case TokKind.Amp: val = bl & br; return true;
                        case TokKind.Pipe: val = bl | br; return true;
                        case TokKind.Caret: val = bl ^ br; return true;
                        case TokKind.EqEq: val = bl == br; return true;
                        case TokKind.BangEq: val = bl != br; return true;
                    }
                }
                if (bk == TokKind.LAngle || bk == TokKind.LtEq || bk == TokKind.RAngle || bk == TokKind.GtEq || bk == TokKind.EqEq || bk == TokKind.BangEq)
                {
                    bool lFlt = TryEvalFloatConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int lft, out double ldv);
                    bool rFlt = TryEvalFloatConstExpr(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int rft, out double rdv);
                    // C# implicitly converts a floating constant zero to the
                    // int-based enum, not the enum to float (which can round).
                    if (lFlt && ldv == 0.0 && !rFlt &&
                        TryEvalTypedIntConstExpr(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int rEnum, out long rEnumValue) &&
                        types.Items[rEnum].Kind == TypeKinds.Enum)
                    {
                        return TryCompareConstEnum(bk, 0L, rEnumValue, out val);
                    }
                    if (rFlt && rdv == 0.0 && !lFlt &&
                        TryEvalTypedIntConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int lEnum, out long lEnumValue) &&
                        types.Items[lEnum].Kind == TypeKinds.Enum)
                    {
                        return TryCompareConstEnum(bk, lEnumValue, 0L, out val);
                    }
                    if (lFlt || rFlt)
                    {
                        bool useF32Cmp = (!lFlt || lft == TypeIds.F32) && (!rFlt || rft == TypeIds.F32);
                        if (useF32Cmp)
                        {
                            if (!TryEvalConstToSingle(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out float lf32, allowEnumSource: false) ||
                                !TryEvalConstToSingle(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out float rf32, allowEnumSource: false))
                            {
                                return false;
                            }
                            switch (bk)
                            {
                                case TokKind.LAngle: val = lf32 < rf32; return true;
                                case TokKind.LtEq: val = lf32 <= rf32; return true;
                                case TokKind.RAngle: val = lf32 > rf32; return true;
                                case TokKind.GtEq: val = lf32 >= rf32; return true;
                                case TokKind.EqEq: val = lf32 == rf32; return true;
                                case TokKind.BangEq: val = lf32 != rf32; return true;
                            }
                        }
                        if (!lFlt && !TryEvalFloatConstOrIntAsFloat(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out lft, out ldv)) return false;
                        if (!rFlt && !TryEvalFloatConstOrIntAsFloat(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out rft, out rdv)) return false;
                        switch (bk)
                        {
                            case TokKind.LAngle: val = ldv < rdv; return true;
                            case TokKind.LtEq: val = ldv <= rdv; return true;
                            case TokKind.RAngle: val = ldv > rdv; return true;
                            case TokKind.GtEq: val = ldv >= rdv; return true;
                            case TokKind.EqEq: val = ldv == rdv; return true;
                            case TokKind.BangEq: val = ldv != rdv; return true;
                        }
                    }
                    if (TryEvalTypedIntConstExpr(n.B, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int lit, out long liv) &&
                        TryEvalTypedIntConstExpr(n.C, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out int rit, out long riv))
                    {
                        int el = UnderlyingIntOrSelf(lit, in types);
                        int er = UnderlyingIntOrSelf(rit, in types);
                        int commonT = PromoteConstIntTypes(el, liv, er, riv, in types);
                        if (commonT < 0) return false;
                        bool isUns = types.IsUnsignedInteger(commonT);
                        long a = TruncateConstToType(liv, commonT);
                        long b = TruncateConstToType(riv, commonT);
                        switch (bk)
                        {
                            case TokKind.LAngle: val = isUns ? (ulong)a < (ulong)b : a < b; return true;
                            case TokKind.LtEq: val = isUns ? (ulong)a <= (ulong)b : a <= b; return true;
                            case TokKind.RAngle: val = isUns ? (ulong)a > (ulong)b : a > b; return true;
                            case TokKind.GtEq: val = isUns ? (ulong)a >= (ulong)b : a >= b; return true;
                            case TokKind.EqEq: val = a == b; return true;
                            case TokKind.BangEq: val = a != b; return true;
                        }
                    }

                }
                return false;
            }
        }
        return false;
    }

    private static void LowerVarDecl(
        in AstNode n,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        if ((n.D & 8) != 0)
        {
            for (int i = 0; i < fctx.HoistedConstantTokens.Count; i++)
            {
                if (fctx.HoistedConstantTokens[i] == n.TokIdx) return;
            }
        }
        int nameId = n.A;
        int typeNode = n.B;
        int initExpr = n.C;
        int varFlags = n.D;
        int tokIdx = n.TokIdx;
        Token tok = ta.Tokens[tokIdx];
        int reservedLocal = -1;
        for (int i = 0; i < fctx.SwitchLocalTokens.Count; i++)
        {
            if (fctx.SwitchLocalTokens[i] == tokIdx) reservedLocal = fctx.SwitchLocalIds[i];
        }
        if (reservedLocal < 0) RegisterScopedName(nameId, fctx.ScopeDepth, tokIdx, ref fctx, in ast, in ta, in names, ref diags);

        // Local const
        if ((varFlags & 8) != 0)
        {
            int diagBeforeConst = diags.Items.Count;
            int cType = typeNode >= 0
                ? DeclBinder.ResolveTypeNode(typeNode, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags)
                : InferExprType(initExpr, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            int curOwner = fctx.EnclosingOwnerDeclId;
            bool validConstType = cType == TypeIds.Error || types.IsInteger(cType) || cType == TypeIds.Bool || types.IsFloat(cType) || cType == TypeIds.Str;
            if (!validConstType)
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "Type cannot be declared 'const' in Vibranium."u8);
            }
            if (initExpr < 0 && diags.Items.Count == diagBeforeConst)
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "Constant declaration requires a compile-time constant initializer."u8);
            }

            if (cType == TypeIds.Str)
            {
                long strCode = -1;
                bool strOk = initExpr >= 0 && TryEvalStringConstCode(initExpr, curOwner, in fctx, in ast, in ta, in names, ref bctx, in types, out strCode);
                if (!strOk && initExpr >= 0)
                {
                    _ = LowerExprAsOperand(initExpr, cType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                }
                if (!strOk && diags.Items.Count == diagBeforeConst)
                {
                    diags.ReportTok(VibCodes.Unsupported, tok, "Constant initializer must be a compile-time constant expression."u8);
                }
                fctx.Vars.Push(new VarBinding(nameId, -1, fctx.ScopeDepth, 1, TypeIds.Str, strOk ? strCode : -1L));
                return;
            }

            int cInitOp = initExpr >= 0
                ? LowerExprAsOperand(initExpr, cType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                : mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, cType, tokIdx));
            bool isTargetDefault = initExpr >= 0 && ast.Nodes[initExpr].Kind == AstKind.ExprDefault && ast.Nodes[initExpr].A < 0 && types.IsZeroSafe(cType, in ast);

            if (cType == TypeIds.Bool)
            {
                bool bVal = false;
                if (initExpr >= 0 && !isTargetDefault && !TryEvalBoolConstExpr(initExpr, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out bVal))
                {
                    if (diags.Items.Count == diagBeforeConst)
                    {
                        diags.ReportTok(VibCodes.Unsupported, tok, "Constant initializer must be a compile-time constant expression."u8);
                    }
                }
                fctx.Vars.Push(new VarBinding(nameId, -1, fctx.ScopeDepth, 1, TypeIds.Bool, bVal ? 1 : 0));
                return;
            }
            if (types.IsInteger(cType))
            {
                long cVal = 0;
                bool okConst = isTargetDefault || (initExpr >= 0 && TryEvalTypedIntConstExpr(initExpr, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out _, out cVal));
                if (!okConst && diags.Items.Count == diagBeforeConst)
                {
                    diags.ReportTok(VibCodes.Unsupported, tok, "Constant initializer must be a compile-time constant expression."u8);
                }
                long masked = TruncateConstToType(cVal, UnderlyingIntOrSelf(cType, in types));
                fctx.Vars.Push(new VarBinding(nameId, -1, fctx.ScopeDepth, 1, cType, masked));
                return;
            }
            if (types.IsFloat(cType))
            {
                long bits = 0;
                if (cType == TypeIds.F32)
                {
                    float fVal = 0.0f;
                    if (!isTargetDefault && (initExpr < 0 || !TryEvalConstToSingle(initExpr, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out fVal, allowEnumSource: false)))
                    {
                        if (diags.Items.Count == diagBeforeConst)
                        {
                            diags.ReportTok(VibCodes.Unsupported, tok, "Constant initializer must be a compile-time constant expression."u8);
                        }
                    }
                    else if (!isTargetDefault)
                    {
                        bits = (long)(uint)FloatToBits(fVal);
                    }
                }
                else
                {
                    double dVal = 0.0;
                    if (!isTargetDefault && (initExpr < 0 || !TryEvalFloatConstOrIntAsFloat(initExpr, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out _, out dVal)))
                    {
                        if (diags.Items.Count == diagBeforeConst)
                        {
                            diags.ReportTok(VibCodes.Unsupported, tok, "Constant initializer must be a compile-time constant expression."u8);
                        }
                    }
                    bits = DoubleToBits(dVal);
                }
                fctx.Vars.Push(new VarBinding(nameId, -1, fctx.ScopeDepth, 1, cType, bits));
                return;
            }
            int cLid = fctx.AddLocal(nameId, cType, PassMode.ByValue, 0, tokIdx);
            fctx.Vars.Push(new VarBinding(nameId, cLid, fctx.ScopeDepth, 0, cType, 0));
            fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, cLid, 0, -1, tokIdx));
            int cDestPl = mir.AddPlaceLocal(cLid, cType);
            fctx.LocalInitializerInsts[cLid] = fctx.StagedInsts.Count;
            fctx.Emit(new MirInst(MirOp.AssignUse, cDestPl, -1, 0, cType, cInitOp, 0, 0, 0, tokIdx));
            return;
        }

        // `ref var x = ref place` / `ref readonly var x = ref place`
        if ((varFlags & 6) != 0)
        {
            bool isMut = (varFlags & 2) != 0;
            int declaredRefType = typeNode >= 0
                ? DeclBinder.ResolveTypeNode(typeNode, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags)
                : -1;
            if (initExpr < 0)
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "A ref local requires a ref initializer."u8);
                int recoveryType = declaredRefType >= 0 ? declaredRefType : TypeIds.I32;
                int recoveryLocal = fctx.AddLocal(nameId, recoveryType, PassMode.ByValue, 0, tokIdx);
                fctx.Vars.Push(new VarBinding(nameId, recoveryLocal, fctx.ScopeDepth, 0, TypeIds.Void, 0));
                fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, recoveryLocal, 0, -1, tokIdx));
                return;
            }
            if (ast.Nodes[initExpr].Kind != AstKind.ExprUnary || (TokKind)ast.Nodes[initExpr].A != TokKind.KwRef)
                diags.ReportTok(VibCodes.Unsupported, tok, "A ref local initializer must use 'ref'."u8);
            if (isMut && initExpr >= 0)
            {
                int refInner = (ast.Nodes[initExpr].Kind == AstKind.ExprUnary && (TokKind)ast.Nodes[initExpr].A == TokKind.KwRef) ? ast.Nodes[initExpr].B : initExpr;
                CheckNotDirectCapturedPrimaryParamWrite(refInner, "Cannot take mutable reference to a captured primary-constructor parameter."u8, in fctx, in ast, in ta, in types, ref diags);
            }
            int targetPl = LowerPlace(initExpr, isMut, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int targetType = mir.Places[targetPl].TypeId;
            CheckSourceReferencePlace(targetPl, declaredRefType, isMut, tokIdx, in fctx, in ta, in types, in mir, ref diags);
            if (types.IsView(targetType))
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "Ref local cannot alias borrowed view in Vibranium."u8);
            }
            else if (types.IsLinear(targetType, in ast))
            {
                diags.ReportTok(VibCodes.LinearViolation, tok, "Ref local cannot alias linear IDisposable resource."u8);
            }
            int lFlags = MirLocalFlags.IsRefLocal | (isMut ? MirLocalFlags.IsRefMut : 0);
            if ((varFlags & 16) != 0) lFlags |= MirLocalFlags.IsScoped;
            int refLid = reservedLocal;
            if (refLid < 0)
            {
                refLid = fctx.AddLocal(nameId, targetType, PassMode.ByValue, lFlags, tokIdx);
                fctx.Vars.Push(new VarBinding(nameId, refLid, fctx.ScopeDepth, 0, TypeIds.Void, 0));
                fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, refLid, 0, -1, tokIdx));
            }
            fctx.LocalInitializerInsts[refLid] = fctx.StagedInsts.Count;
            fctx.Emit(new MirInst(MirOp.BindRef, -1, refLid, isMut ? 1 : 0, targetType, refLid, targetPl, 0, 0, tokIdx));
            return;
        }

        if (initExpr >= 0 && ast.Nodes[initExpr].Kind == AstKind.ExprUnary && (TokKind)ast.Nodes[initExpr].A == TokKind.KwRef)
            diags.ReportTok(VibCodes.Unsupported, tok, "A value local cannot have a ref initializer."u8);
        int declaredType = typeNode >= 0
            ? DeclBinder.ResolveTypeNode(typeNode, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags)
            : -1;
        if (declaredType < 0 && initExpr >= 0 && IsDirectCollectionRvalue(initExpr, in ast) && ast.Nodes[initExpr].Kind != AstKind.ExprCollLit)
            declaredType = InferExprType(initExpr, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        DeclBinder.DrainConcreteTypeQueue(in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);

        bool isUsing = (varFlags & 1) != 0;
        int localFlags = 0;
        int disposeInstId = -1;
        if ((varFlags & 16) != 0) localFlags |= MirLocalFlags.IsScoped;
        if ((varFlags & 16) != 0 && declaredType >= 0 && !DeclBinder.IsRefStructType(declaredType, in types))
            diags.ReportTok(VibCodes.Unsupported, tok, "The 'scoped' modifier can be used for refs and ref struct values only (CS9048)."u8);

        // Establish an explicitly typed local at its declarator, before its
        // initializer. This preserves self-writes and diagnoses self-reads as
        // uninitialized locals rather than resolving a same-named field.
        int lid = reservedLocal;
        if (declaredType >= 0 && lid < 0)
        {
            lid = fctx.AddLocal(nameId, declaredType, PassMode.ByValue, localFlags | (isUsing ? MirLocalFlags.IsUsingVar : 0), tokIdx);
            fctx.Vars.Push(new VarBinding(nameId, lid, fctx.ScopeDepth, 0, TypeIds.Void, 0));
        }

        int initOp = -1;
        int initializationPlace = lid >= 0 ? mir.AddPlaceLocal(lid, fctx.Locals[lid].TypeId) : -1;
        if (initExpr >= 0)
        {
            initOp = LowerExprAsOperand(initExpr, declaredType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, initializationPlace);
            if (declaredType < 0)
            {
                declaredType = mir.Operands[initOp].TypeId;
            }
        }
        if (declaredType < 0) declaredType = TypeIds.I32;
        if (declaredType == TypeIds.Utf8Lines || declaredType == TypeIds.Utf8ArgEnum)
        {
            diags.ReportTok(VibCodes.Unsupported, tok, "'Utf8Lines' and 'Utf8ArgEnumerator' can only be used directly in 'foreach' or returned from a method."u8);
        }

        if (isUsing)
        {
            localFlags |= MirLocalFlags.IsUsingVar;
            TypeInfo ti = types.Items[declaredType];
            if (ti.Kind == TypeKinds.Class && (ast.Types[ti.A].Flags & DeclFlags.IsDisposable) != 0)
            {
                disposeInstId = ti.DisposeFuncInstId;
            }
            else if (!types.ContainsTypeParam(declaredType))
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "'using var' requires an IDisposable class in Vibranium."u8);
            }
        }

        if (lid < 0)
        {
            lid = fctx.AddLocal(nameId, declaredType, PassMode.ByValue, localFlags, tokIdx);
            fctx.Vars.Push(new VarBinding(nameId, lid, fctx.ScopeDepth, 0, TypeIds.Void, 0));
        }
        if (reservedLocal < 0) fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, lid, isUsing ? 1 : 0, disposeInstId, tokIdx));

        if (initOp >= 0)
        {
            int destPl = mir.AddPlaceLocal(lid, declaredType);
            bool directStorage = initializationPlace >= 0 && mir.Operands[initOp].Kind == MirOpKinds.CopyOrMove && mir.Operands[initOp].PlaceOrLitIdx == initializationPlace;
            fctx.LocalInitializerInsts[lid] = directStorage ? fctx.StagedInsts.Count - 1 : fctx.StagedInsts.Count;
            if (!directStorage) fctx.Emit(new MirInst(MirOp.AssignUse, destPl, -1, 0, declaredType, initOp, 0, 0, 0, tokIdx));
        }
    }

    private static void LowerForeach(
        in AstNode n,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int itemNameId = n.A;
        int feFlags = n.B & 7; // 0=val, 2=ref, 4=ref readonly
        int itemTypeNode = (n.B >> 4) - 1;
        int collExpr = n.C;
        int bodyStmt = n.D;
        int tokIdx = n.TokIdx;

        PushScope(ref fctx);

        bool wantsMutRef = feFlags == 2;
        int collType = InferExprType(collExpr, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        TypeInfo cti = types.Items[collType];

        if (cti.Kind == TypeKinds.Utf8Lines || cti.Kind == TypeKinds.Utf8ArgEnum ||
            ((cti.Kind == TypeKinds.Struct || cti.Kind == TypeKinds.Class) &&
             TryFindClosedForeachEnumerator(collType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out _)))
        {
            LowerUtf8ViewForeach(itemNameId, feFlags, itemTypeNode, collExpr, collType, bodyStmt, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            return;
        }

        int elemType = TypeIds.I32;
        int spanType;
        int spanLocal;

        if (cti.Kind == TypeKinds.Vec)
        {
            elemType = cti.A;
            bool ro = !wantsMutRef;
            spanType = types.MakeSpan(elemType, isReadOnly: ro);
            int vecPlace = LowerPlaceOrTemp(collExpr, collType, !ro, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            spanLocal = fctx.NewLexicalLoan(spanType, tokIdx);
            int spanDest = mir.AddPlaceLocal(spanLocal, spanType);
            var plOne = new Vec<int>(1);
            plOne.Push(vecPlace);
            MirIntrinsic intr = ro ? MirIntrinsic.VecAsReadOnlySpan : MirIntrinsic.VecAsSpan;
            fctx.Emit(new MirInst(MirOp.Intrinsic, spanDest, -1, 0, spanType, (int)intr, 0, 0, mir.PushIdList(plOne.AsReadOnlySpan()) | (1 << 20), tokIdx));
        }
        else if (cti.Kind == TypeKinds.Span || cti.Kind == TypeKinds.ReadOnlySpan)
        {
            elemType = cti.A;
            if (wantsMutRef && cti.Kind == TypeKinds.ReadOnlySpan)
            {
                diags.ReportTok(VibCodes.MutateSharedBorrow, ta.Tokens[tokIdx], "Cannot take mutable 'ref' element from ReadOnlySpan<T>."u8);
            }
            spanType = types.MakeSpan(elemType, isReadOnly: !wantsMutRef);
            int spOp = LowerExprAsOperand(collExpr, collType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            if (!IsPlaceExpression(collExpr, in ast, in fctx, in types))
            {
                // A value-producing collection (notably explicit Move(s))
                // must be consumed before making the shared enumeration view.
                int collectionValue = fctx.NewTemp(collType, tokIdx, ref mir);
                int collectionPlace = mir.AddPlaceLocal(collectionValue, collType);
                fctx.Emit(new MirInst(MirOp.AssignUse, collectionPlace, -1, 0, collType, spOp, 0, 0, 0, tokIdx));
                spOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, collectionPlace, 0, collType, tokIdx));
            }
            spanLocal = fctx.NewLexicalLoan(spanType, tokIdx);
            int spanDest = mir.AddPlaceLocal(spanLocal, spanType);
            MirOperand spOperand = mir.Operands[spOp];
            if (spOperand.Kind == MirOpKinds.CopyOrMove && mir.Places[spOperand.PlaceOrLitIdx].ProjCount == 0)
            {
                // Reborrow Span local via SpanSlice(sp, 0, sp.Length) so `s` is borrowed rather than moved!
                int srcLenTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
                int srcLenPl = mir.AddPlaceLocal(srcLenTmp, TypeIds.I32);
                var lenOne = new Vec<int>(1);
                lenOne.Push(spOp);
                fctx.Emit(new MirInst(MirOp.Intrinsic, srcLenPl, -1, 0, TypeIds.I32, (int)MirIntrinsic.SpanLength, mir.PushIdList(lenOne.AsReadOnlySpan()), 1, 0, tokIdx));
                int zStart = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
                int fullLen = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, srcLenPl, 0, TypeIds.I32, tokIdx));
                int spOpClone = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, spOperand.PlaceOrLitIdx, 0, collType, tokIdx));
                var slOps = new Vec<int>(3);
                slOps.Push(spOpClone);
                slOps.Push(zStart);
                slOps.Push(fullLen);
                fctx.Emit(new MirInst(MirOp.Intrinsic, spanDest, -1, 0, spanType, (int)MirIntrinsic.SpanSlice, mir.PushIdList(slOps.AsReadOnlySpan()), 3, 0, tokIdx));
            }
            else
            {
                fctx.Emit(new MirInst(MirOp.AssignUse, spanDest, -1, 0, spanType, spOp, 0, 0, 0, tokIdx));
            }
        }
        else
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "'foreach' is only supported on Vec<T>, Span<T>, and ReadOnlySpan<T>."u8);
            PopScope(tokIdx, ref fctx, ref mir);
            return;
        }

        int itemType = itemTypeNode >= 0
            ? DeclBinder.ResolveTypeNode(itemTypeNode, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags)
            : elemType;
        if (feFlags != 0)
        {
            if (itemType != TypeIds.Error && itemType != elemType)
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A ref foreach variable requires the exact element type."u8);
            if (types.IsView(elemType))
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Ref foreach local cannot alias borrowed view."u8);
            }
            else if (types.IsLinear(elemType, in ast))
            {
                diags.ReportTok(VibCodes.LinearViolation, ta.Tokens[tokIdx], "Ref foreach local cannot alias linear IDisposable resource."u8);
            }
        }

        MirLocal enumerationView = fctx.Locals[spanLocal];
        fctx.Locals[spanLocal] = new MirLocal(enumerationView.NameId, enumerationView.TypeId, enumerationView.Mode,
            enumerationView.Flags | MirLocalFlags.IsForeachLoan, enumerationView.TokIdx);

        int idxLocal = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
        int idxPlace = mir.AddPlaceLocal(idxLocal, TypeIds.I32);
        int zeroOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
        fctx.Emit(new MirInst(MirOp.AssignUse, idxPlace, -1, 0, TypeIds.I32, zeroOp, 0, 0, 0, tokIdx));

        int condBlk = fctx.NewBlock();
        int bodyBlk = fctx.NewBlock();
        int stepBlk = fctx.NewBlock();
        int exitBlk = fctx.NewBlock();

        fctx.Terminate(new MirTerm(MirTermKind.Goto, condBlk, 0, 0, 0, 0, 0, tokIdx));

        // condBlk: idx < span.Length
        fctx.CurBlock = condBlk;
        int lenTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
        int lenPlace = mir.AddPlaceLocal(lenTmp, TypeIds.I32);
        int spReadPlace = mir.AddPlaceLocal(spanLocal, spanType);
        int spReadOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, spReadPlace, 0, spanType, tokIdx));
        var lenArgs = new Vec<int>(1);
        lenArgs.Push(spReadOp);
        fctx.Emit(new MirInst(MirOp.Intrinsic, lenPlace, -1, 0, TypeIds.I32, (int)MirIntrinsic.SpanLength, mir.PushIdList(lenArgs.AsReadOnlySpan()), 1, 0, tokIdx));

        int cmpTmp = fctx.NewTemp(TypeIds.Bool, tokIdx, ref mir);
        int cmpPlace = mir.AddPlaceLocal(cmpTmp, TypeIds.Bool);
        int idxOp1 = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, idxPlace, 0, TypeIds.I32, tokIdx));
        int lenOp1 = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, lenPlace, 0, TypeIds.I32, tokIdx));
        fctx.Emit(new MirInst(MirOp.AssignBin, cmpPlace, -1, 0, TypeIds.Bool, (int)MirBinOp.Lt, idxOp1, lenOp1, 0, tokIdx));
        int cmpCondOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, cmpPlace, 0, TypeIds.Bool, tokIdx));
        fctx.Terminate(new MirTerm(MirTermKind.Branch, cmpCondOp, bodyBlk, exitBlk, 0, 0, 0, tokIdx));

        // bodyBlk: bind item
        fctx.CurBlock = bodyBlk;
        PushScope(ref fctx);
        bool elemRefMut = types.Items[spanType].Kind == TypeKinds.Span && (feFlags == 2);
        int elemRefLocal = fctx.NewTempRef(elemType, elemRefMut, tokIdx);
        int spPl2 = mir.AddPlaceLocal(spanLocal, spanType);
        int spOp2 = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, spPl2, 0, spanType, tokIdx));
        int idxOp2 = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, idxPlace, 0, TypeIds.I32, tokIdx));
        var idxArgs = new Vec<int>(2);
        idxArgs.Push(spOp2);
        idxArgs.Push(idxOp2);
        fctx.Emit(new MirInst(MirOp.Intrinsic, -1, elemRefLocal, elemRefMut ? 1 : 0, elemType, (int)MirIntrinsic.SpanIndexRef, mir.PushIdList(idxArgs.AsReadOnlySpan()), 2, 0, tokIdx));

        RegisterScopedName(itemNameId, fctx.ScopeDepth, tokIdx, ref fctx, in ast, in ta, in names, ref diags);
        if (feFlags != 0)
        {
            int itemRefLid = fctx.AddLocal(itemNameId, elemType, PassMode.ByValue, MirLocalFlags.IsRefLocal | MirLocalFlags.IsForeachRef | (wantsMutRef ? MirLocalFlags.IsRefMut : 0), tokIdx);
            fctx.Vars.Push(new VarBinding(itemNameId, itemRefLid, fctx.ScopeDepth, 0, TypeIds.Void, 0));
            fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, itemRefLid, 0, -1, tokIdx));
            var derefProj = new Vec<MirProj>(1);
            derefProj.Push(new MirProj(MirProjKinds.Deref, 0, elemType, -1, 0));
            int derefPl = mir.AddPlace(elemRefLocal, derefProj.AsReadOnlySpan(), elemType);
            fctx.LocalInitializerInsts[itemRefLid] = fctx.StagedInsts.Count;
            fctx.Emit(new MirInst(MirOp.BindRef, -1, itemRefLid, wantsMutRef ? 1 : 0, elemType, itemRefLid, derefPl, 0, 0, tokIdx));
        }
        else
        {
            int itemValLid = fctx.AddLocal(itemNameId, itemType, PassMode.ByValue, 0, tokIdx);
            fctx.SourceReadonlyLocals[itemValLid] = 1;
            fctx.Vars.Push(new VarBinding(itemNameId, itemValLid, fctx.ScopeDepth, 0, TypeIds.Void, 0));
            fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, itemValLid, 0, -1, tokIdx));
            var derefProj = new Vec<MirProj>(1);
            derefProj.Push(new MirProj(MirProjKinds.Deref, 0, elemType, -1, 0));
            int derefPl = mir.AddPlace(elemRefLocal, derefProj.AsReadOnlySpan(), elemType);
            int valOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, derefPl, 0, elemType, tokIdx));
            // C# foreach uses an explicit element conversion, including
            // numeric narrowing, whereas ref foreach requires identity.
            if (elemType != itemType && (types.IsInteger(elemType) || types.IsFloat(elemType)) &&
                (types.IsInteger(itemType) || types.IsFloat(itemType)))
                valOp = EmitCastToTemp(valOp, itemType, tokIdx, ref fctx, ref mir);
            else
                valOp = ConvertOperandIfNeeded(valOp, itemType, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags);
            int itemPl = mir.AddPlaceLocal(itemValLid, itemType);
            fctx.LocalInitializerInsts[itemValLid] = fctx.StagedInsts.Count;
            fctx.Emit(new MirInst(MirOp.AssignUse, itemPl, -1, 0, itemType, valOp, 0, 0, 0, tokIdx));
        }

        fctx.Loops.Push(new LoopFrame(exitBlk, stepBlk, fctx.ScopeDepth, fctx.ScopeDepth));
        LowerStatement(bodyStmt, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        fctx.Loops.Pop();
        PopScope(tokIdx, ref fctx, ref mir);

        if (!fctx.IsBlockTerminated(fctx.CurBlock))
        {
            fctx.Terminate(new MirTerm(MirTermKind.Goto, stepBlk, 0, 0, 0, 0, 0, tokIdx));
        }

        // stepBlk: idx += 1
        fctx.CurBlock = stepBlk;
        int idxOp3 = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, idxPlace, 0, TypeIds.I32, tokIdx));
        int oneOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 1, TypeIds.I32, tokIdx));
        fctx.Emit(new MirInst(MirOp.AssignBin, idxPlace, -1, 0, TypeIds.I32, (int)MirBinOp.Add, idxOp3, oneOp, 0, tokIdx));
        fctx.Terminate(new MirTerm(MirTermKind.Goto, condBlk, 0, 0, 0, 0, 0, tokIdx));

        fctx.CurBlock = exitBlk;
        PopScope(tokIdx, ref fctx, ref mir);
    }

    private static bool TryFindClosedForeachEnumerator(
        int ownerTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        out int getEnumFuncDeclId,
        out int enumViewTypeId)
    {
        getEnumFuncDeclId = -1;
        enumViewTypeId = TypeIds.Error;
        TypeInfo ti = types.Items[ownerTypeId];
        if (ti.Kind != TypeKinds.Struct && ti.Kind != TypeKinds.Class) return false;
        TypeDecl td = ast.Types[ti.A];
        for (int m = 0; m < td.FuncCount; m++)
        {
            int fId = td.FuncStart + m;
            FuncDecl fd = ast.Funcs[fId];
            if (fd.NameId == bctx.IdGetEnumerator &&
                (fd.Flags & DeclFlags.Static) == 0 &&
                fd.TypeParamCount == 0 &&
                fd.ParamCount == 0 &&
                IsAccessibleFuncFromCaller(fId, ref fctx, in ast, in bctx))
            {
                var subNames = new Vec<int>();
                var subVals = new Vec<int>();
                BuildOwnerTypeSubst(ownerTypeId, in ast, in types, ref subNames, ref subVals);
                int retT = DeclBinder.ResolveTypeNode(fd.RetTypeNode, subNames.AsReadOnlySpan(), subVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                if (retT == TypeIds.Utf8Lines || retT == TypeIds.Utf8ArgEnum)
                {
                    getEnumFuncDeclId = fId;
                    enumViewTypeId = retT;
                    return true;
                }
            }
        }
        return false;
    }

    private static void LowerUtf8ViewForeach(
        int itemNameId,
        int feFlags,
        int itemTypeNode,
        int collExpr,
        int collType,
        int bodyStmt,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        Token tok = ta.Tokens[tokIdx];
        int roSpanU8 = types.MakeSpan(TypeIds.U8, isReadOnly: true);

        if (feFlags == 2)
        {
            diags.ReportTok(VibCodes.MutateSharedBorrow, tok, "Cannot take mutable 'ref' element from shared UTF-8 foreach view."u8);
        }
        else if (feFlags != 0)
        {
            diags.ReportTok(VibCodes.Unsupported, tok, "Ref foreach local cannot alias borrowed view."u8);
        }

        if (itemTypeNode >= 0)
        {
            int explicitItemT = DeclBinder.ResolveTypeNode(itemTypeNode, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags);
            if (explicitItemT != roSpanU8)
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "Loop variable of UTF-8 foreach view must have type 'ReadOnlySpan<byte>'."u8);
            }
        }

        int viewTypeId = collType;
        int viewPl;
        TypeInfo cti = types.Items[collType];
        if (cti.Kind == TypeKinds.Utf8Lines || cti.Kind == TypeKinds.Utf8ArgEnum)
        {
            bool savedForbid = fctx.ForbidDirectUtf8ArgEnumNew;
            fctx.ForbidDirectUtf8ArgEnumNew = true;
            int viewOp = LowerExprAsOperand(collExpr, collType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            fctx.ForbidDirectUtf8ArgEnumNew = savedForbid;
            int viewTmp = fctx.NewTemp(collType, tokIdx, ref mir);
            viewPl = mir.AddPlaceLocal(viewTmp, collType);
            fctx.Emit(new MirInst(MirOp.AssignUse, viewPl, -1, 0, collType, viewOp, 0, 0, 0, tokIdx));
        }
        else
        {
            _ = TryFindClosedForeachEnumerator(collType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int getEnumFId, out viewTypeId);
            var emptyM = new Vec<int>();
            int gInst = DeclBinder.EnsureFuncInstance(getEnumFId, collType, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
            PassMode recvMode = mir.ParamSigs[mir.FuncInstances[gInst].ParamSigStart].Mode;
            int recvPl = LowerPlaceOrTemp(collExpr, collType, recvMode == PassMode.ThisMut, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int viewOp = EmitZeroArgInstanceCall(gInst, recvPl, collType, tokIdx, ref fctx, in types, ref mir);
            int viewTmp = fctx.NewTemp(viewTypeId, tokIdx, ref mir);
            viewPl = mir.AddPlaceLocal(viewTmp, viewTypeId);
            fctx.Emit(new MirInst(MirOp.AssignUse, viewPl, -1, 0, viewTypeId, viewOp, 0, 0, 0, tokIdx));
        }

        // Hidden `__src : ReadOnlySpan<byte>` holds ONLY the source owner's shared loan across the whole loop (including back-edges)
        int srcLocal = fctx.NewTemp(roSpanU8, tokIdx, ref mir);
        int srcPlace = mir.AddPlaceLocal(srcLocal, roSpanU8);
        var plOne = new Vec<int>(1);
        plOne.Push(viewPl);
        fctx.Emit(new MirInst(MirOp.Intrinsic, srcPlace, -1, 0, roSpanU8, (int)MirIntrinsic.Utf8ViewBytes, 0, 0, mir.PushIdList(plOne.AsReadOnlySpan()) | (1 << 20), tokIdx));

        int posLocal = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
        int posPlace = mir.AddPlaceLocal(posLocal, TypeIds.I32);
        int zeroOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
        fctx.Emit(new MirInst(MirOp.AssignUse, posPlace, -1, 0, TypeIds.I32, zeroOp, 0, 0, 0, tokIdx));

        int scanMode = viewTypeId == TypeIds.Utf8Lines ? 0 : 1;
        int packedLocal = fctx.NewTemp(TypeIds.I64, tokIdx, ref mir);
        int packedPlace = mir.AddPlaceLocal(packedLocal, TypeIds.I64);

        int condBlk = fctx.NewBlock();
        int bodyBlk = fctx.NewBlock();
        int exitBlk = fctx.NewBlock();
        fctx.Terminate(new MirTerm(MirTermKind.Goto, condBlk, 0, 0, 0, 0, 0, tokIdx));

        // condBlk: packed = __vib_utf8_scan(__src, __pos, mode); if (packed >= 0) goto bodyBlk else exitBlk
        fctx.CurBlock = condBlk;
        int srcOpCond = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, srcPlace, 0, roSpanU8, tokIdx));
        int posOpCond = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, posPlace, 0, TypeIds.I32, tokIdx));
        int modeOpCond = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, scanMode, TypeIds.I32, tokIdx));
        var scanArgs = new Vec<int>(3);
        scanArgs.Push(srcOpCond);
        scanArgs.Push(posOpCond);
        scanArgs.Push(modeOpCond);
        fctx.Emit(new MirInst(MirOp.Intrinsic, packedPlace, -1, 0, TypeIds.I64, (int)MirIntrinsic.Utf8Scan, mir.PushIdList(scanArgs.AsReadOnlySpan()), 3, 0, tokIdx));

        int hasMoreTmp = fctx.NewTemp(TypeIds.Bool, tokIdx, ref mir);
        int hasMorePl = mir.AddPlaceLocal(hasMoreTmp, TypeIds.Bool);
        int packedRead1 = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, packedPlace, 0, TypeIds.I64, tokIdx));
        int zeroI64 = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I64, tokIdx));
        fctx.Emit(new MirInst(MirOp.AssignBin, hasMorePl, -1, 0, TypeIds.Bool, (int)MirBinOp.Ge, packedRead1, zeroI64, 0, tokIdx));
        int hasMoreOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, hasMorePl, 0, TypeIds.Bool, tokIdx));
        fctx.Terminate(new MirTerm(MirTermKind.Branch, hasMoreOp, bodyBlk, exitBlk, 0, 0, 0, tokIdx));

        // bodyBlk: slice = __src.Slice(__pos, (int)packed - __pos); __pos = (int)(packed >>> 32); body; goto condBlk
        fctx.CurBlock = bodyBlk;
        PushScope(ref fctx);

        int packedRead2 = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, packedPlace, 0, TypeIds.I64, tokIdx));
        int endOp = EmitCastToTemp(packedRead2, TypeIds.I32, tokIdx, ref fctx, ref mir);
        int posReadSlice = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, posPlace, 0, TypeIds.I32, tokIdx));
        int lenTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
        int lenPl = mir.AddPlaceLocal(lenTmp, TypeIds.I32);
        fctx.Emit(new MirInst(MirOp.AssignBin, lenPl, -1, 0, TypeIds.I32, (int)MirBinOp.Sub, endOp, posReadSlice, 0, tokIdx));
        int lenOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, lenPl, 0, TypeIds.I32, tokIdx));

        int itemLid = fctx.AddLocal(itemNameId, roSpanU8, PassMode.ByValue, 0, tokIdx);
        fctx.SourceReadonlyLocals[itemLid] = 1;
        if (!Bytes.Eq(names.Text(itemNameId), "_"u8))
        {
            RegisterScopedName(itemNameId, fctx.ScopeDepth, tokIdx, ref fctx, in ast, in ta, in names, ref diags);
            fctx.Vars.Push(new VarBinding(itemNameId, itemLid, fctx.ScopeDepth, 0, TypeIds.Void, 0));
        }
        fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, itemLid, 0, -1, tokIdx));
        int itemPl = mir.AddPlaceLocal(itemLid, roSpanU8);

        int srcOpSlice = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, srcPlace, 0, roSpanU8, tokIdx));
        int posReadStart = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, posPlace, 0, TypeIds.I32, tokIdx));
        var sliceOps = new Vec<int>(3);
        sliceOps.Push(srcOpSlice);
        sliceOps.Push(posReadStart);
        sliceOps.Push(lenOp);
        fctx.LocalInitializerInsts[itemLid] = fctx.StagedInsts.Count;
        fctx.Emit(new MirInst(MirOp.Intrinsic, itemPl, -1, 0, roSpanU8, (int)MirIntrinsic.SpanSlice, mir.PushIdList(sliceOps.AsReadOnlySpan()), 3, 0, tokIdx));

        int packedRead3 = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, packedPlace, 0, TypeIds.I64, tokIdx));
        int shift32 = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 32, TypeIds.I32, tokIdx));
        int shiftedTmp = fctx.NewTemp(TypeIds.I64, tokIdx, ref mir);
        int shiftedPl = mir.AddPlaceLocal(shiftedTmp, TypeIds.I64);
        fctx.Emit(new MirInst(MirOp.AssignBin, shiftedPl, -1, 0, TypeIds.I64, (int)MirBinOp.UShr, packedRead3, shift32, 0, tokIdx));
        int shiftedOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, shiftedPl, 0, TypeIds.I64, tokIdx));
        int nextPosOp = EmitCastToTemp(shiftedOp, TypeIds.I32, tokIdx, ref fctx, ref mir);
        fctx.Emit(new MirInst(MirOp.AssignUse, posPlace, -1, 0, TypeIds.I32, nextPosOp, 0, 0, 0, tokIdx));

        fctx.Loops.Push(new LoopFrame(exitBlk, condBlk, fctx.ScopeDepth, fctx.ScopeDepth));
        LowerStatement(bodyStmt, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        fctx.Loops.Pop();
        PopScope(tokIdx, ref fctx, ref mir);

        if (!fctx.IsBlockTerminated(fctx.CurBlock))
        {
            fctx.Terminate(new MirTerm(MirTermKind.Goto, condBlk, 0, 0, 0, 0, 0, tokIdx));
        }

        fctx.CurBlock = exitBlk;
        PopScope(tokIdx, ref fctx, ref mir);
    }

    private static bool TryGetSourceSwitchConstant(
        int exprId,
        int scrutType,
        int owner,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types,
        out ulong value,
        out bool isNaN)
    {
        value = 0UL;
        isNaN = false;
        if (scrutType == TypeIds.Bool && TryEvalBoolConstExpr(exprId, owner, in fctx, in ast, in ta, in names, in bctx, in types, out bool bv))
        {
            value = bv ? 1UL : 0UL;
            return true;
        }
        if (types.IsInteger(scrutType) && TryEvalTypedIntConstExpr(exprId, owner, in fctx, in ast, in ta, in names, in bctx, in types, out _, out long iv))
        {
            int effIntTid = UnderlyingIntOrSelf(scrutType, in types);
            value = IntValToOrd(TruncateConstToType(iv, effIntTid), types.IsUnsignedInteger(effIntTid));
            return true;
        }
        if (types.IsFloat(scrutType))
        {
            bool isSingle = scrutType == TypeIds.F32;
            ulong zeroOrd = isSingle ? 0x7F800000UL : 0x7FF0000000000000UL;
            return TryEvalFloatPatternConstBits(exprId, isSingle, owner, in fctx, in ast, in ta, in names, in bctx, in types, out isNaN, out value, zeroOrd);
        }
        return false;
    }

    private static bool TryMatchSourceSwitchConstant(
        int patId,
        int scrutType,
        ulong value,
        bool isNaN,
        int owner,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        out bool matches)
    {
        matches = false;
        if (scrutType == TypeIds.Bool)
        {
            EvaluateBoolPatternMustMay(patId, owner, ref fctx, in ast, in ta, in names, ref bctx, ref types, out bool mustT, out bool mustF, out bool mayT, out bool mayF);
            matches = value != 0UL ? mustT : mustF;
            return matches || !(value != 0UL ? mayT : mayF);
        }
        var mustSet = new Vec<UInterval>();
        var maySet = new Vec<UInterval>();
        if (types.IsInteger(scrutType))
        {
            int effIntTid = UnderlyingIntOrSelf(scrutType, in types);
            GetIntTypeOrdDomain(effIntTid, out bool isUnsigned, out ulong domLo, out ulong domHi);
            EvaluateIntPatternMustMay(patId, scrutType, effIntTid, isUnsigned, domLo, domHi, owner, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref mustSet, ref maySet);
        }
        else if (types.IsFloat(scrutType))
        {
            bool isSingle = scrutType == TypeIds.F32;
            ulong zeroOrd = isSingle ? 0x7F800000UL : 0x7FF0000000000000UL;
            EvaluateFloatPatternMustMay(patId, scrutType, isSingle, zeroOrd, 0UL, zeroOrd * 2UL, owner, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref mustSet, ref maySet, out bool mustNaN, out bool mayNaN);
            if (isNaN)
            {
                matches = mustNaN;
                return mustNaN || !mayNaN;
            }
        }
        else return false;
        for (int i = 0; i < mustSet.Count; i++)
        {
            if (value >= mustSet[i].Lo && value <= mustSet[i].Hi)
            {
                matches = true;
                return true;
            }
        }
        for (int i = 0; i < maySet.Count; i++)
        {
            if (value >= maySet[i].Lo && value <= maySet[i].Hi) return false;
        }
        return true;
    }

    private static void RecordSourceSwitchFlow(int entryBlock, int afterInst,
        in Vec<int> targets, in Vec<int> bodies, ref FuncLowerCtx fctx)
    {
        int targetStart = fctx.SourceSwitchTargets.Count;
        int bodyStart = fctx.SourceSwitchBodies.Count;
        for (int i = 0; i < targets.Count; i++) fctx.SourceSwitchTargets.Push(targets[i]);
        for (int i = 0; i < bodies.Count; i++) fctx.SourceSwitchBodies.Push(bodies[i]);
        fctx.SourceSwitchFlows.Push(new SourceSwitchFlow(entryBlock, afterInst, targetStart, targets.Count, bodyStart, bodies.Count));
    }

    private static void LowerSwitchStatement(
        in AstNode n,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int hoistedMark = fctx.HoistedConstantTokens.Count;
        int localMark = fctx.SwitchLocalTokens.Count;
        int previousDepth = fctx.ScopeDepth;
        LowerSwitchStatementCore(in n, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        fctx.HoistedConstantTokens.Truncate(hoistedMark);
        fctx.SwitchLocalTokens.Truncate(localMark);
        fctx.SwitchLocalIds.Truncate(localMark);
        if (fctx.ScopeDepth > previousDepth) PopScope(n.TokIdx, ref fctx, ref mir);
    }

    private static void BindSwitchDeclarations(
        in AstNode n, int selectorType, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta,
        ref Interner names, ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags)
    {
        // The selector has already run. Reserve only identities and types in the
        // same declaration space checked by the source lexical pass, never values.
        PushScope(ref fctx);
        var declarations = new SourceLexicalScopes();
        int blockScope = SourceLexicalScopeChecker.CollectSwitchBody(in n, 0, ref declarations, in ast);
        for (int sectionIndex = 0; sectionIndex < n.C; sectionIndex++)
        {
            AstNode section = ast.Nodes[ast.Extra[n.B + sectionIndex]];
            int nextToken = sectionIndex + 1 < n.C ? ast.Nodes[ast.Extra[n.B + sectionIndex + 1]].TokIdx : int.MaxValue;
            int variableMark = fctx.Vars.Count;
            fctx.InferDepth += 1;
            // Initializer types may depend on a case-label pattern or when out-var.
            // Those bindings remain speculative and never become switch-block locals.
            for (int j = 0; j < section.B; j++)
            {
                AstNode label = ast.Nodes[ast.Extra[section.A + j]];
                var labelBindings = new Vec<VarBinding>();
                CollectSpeculativePatternBindings(label.A, selectorType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref labelBindings);
                for (int k = 0; k < labelBindings.Count; k++) fctx.Vars.Push(labelBindings[k]);
                if (label.B >= 0) _ = InferExprType(label.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            }
            for (int i = 0; i < declarations.Bindings.Count; i++)
            {
                SourceLexicalBinding binding = declarations.Bindings[i];
                if (binding.Scope != blockScope || binding.Kind == 1 || binding.TokIdx < section.TokIdx || binding.TokIdx >= nextToken) continue;
                AstNode declaration = ast.Nodes[binding.NodeId];
                if (declaration.Kind == AstKind.StmtVarDecl && (declaration.D & 8) != 0)
                {
                    LowerVarDecl(in declaration, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    fctx.HoistedConstantTokens.Push(declaration.TokIdx);
                    continue;
                }
                int localType = TypeIds.Error;
                int flags = 0;
                if (declaration.Kind == AstKind.StmtVarDecl)
                {
                    localType = declaration.B >= 0
                        ? DeclBinder.ResolveTypeNode(declaration.B, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags)
                        : InferExprType(declaration.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    flags = (declaration.D & 16) != 0 ? MirLocalFlags.IsScoped : 0;
                    if ((declaration.D & 6) != 0)
                    {
                        localType = InferExprType(declaration.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                        flags |= MirLocalFlags.IsRefLocal | ((declaration.D & 2) != 0 ? MirLocalFlags.IsRefMut : 0);
                    }
                    if ((declaration.D & 1) != 0)
                    {
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[declaration.TokIdx], "A using declaration cannot appear directly in a switch section; enclose it in a block."u8);
                    }
                }
                else if (binding.ExpressionNodeId >= 0)
                {
                    _ = InferExprType(binding.ExpressionNodeId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    int inferred = fctx.FindVar(binding.NameId, out _, out int inferredType, out _);
                    localType = inferred == -2 ? inferredType : (inferred >= 0 ? fctx.Locals[inferred].TypeId : TypeIds.Error);
                }
                // Register a real declaration while retaining the temporary type
                // environment for later declarators in this section.
                fctx.InferDepth -= 1;
                RegisterScopedName(binding.NameId, fctx.ScopeDepth, binding.TokIdx, ref fctx, in ast, in ta, in names, ref diags);
                fctx.InferDepth += 1;
                int localId = fctx.AddLocal(binding.NameId, localType, PassMode.ByValue, flags, binding.TokIdx);
                fctx.Vars.Push(new VarBinding(binding.NameId, localId, fctx.ScopeDepth, 0, TypeIds.Void, 0));
                fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, localId, 0, -1, binding.TokIdx));
                fctx.SwitchLocalTokens.Push(binding.TokIdx);
                fctx.SwitchLocalIds.Push(localId);
            }
            RemoveSpeculativeBindingsSince(variableMark, ref fctx);
            fctx.LeaveSpeculativeInfer();
        }
    }

    private static void RemoveSpeculativeBindingsSince(int start, ref FuncLowerCtx fctx)
    {
        int write = start;
        for (int i = start; i < fctx.Vars.Count; i++)
        {
            VarBinding binding = fctx.Vars[i];
            if (binding.LocalId != -2) { fctx.Vars[write] = binding; write += 1; }
        }
        fctx.Vars.Truncate(write);
    }

    private static int BindExpressionLocal(int nameId, int typeId, int flags, int depth, int tokIdx,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, ref DiagnosticBag diags)
    {
        if (nameId >= 0)
        {
            for (int i = fctx.SwitchLocalIds.Count - 1; i >= 0; i--)
            {
                int reserved = fctx.SwitchLocalIds[i];
                MirLocal local = fctx.Locals[reserved];
                if (local.NameId != nameId) continue;
                // Pattern payload syntax and its match instruction have different
                // tokens; lexical identity is the name in the reserved block space.
                fctx.Locals[reserved] = new MirLocal(nameId, typeId, PassMode.ByValue, flags, local.TokIdx);
                return reserved;
            }
        }
        RegisterScopedName(nameId, depth, tokIdx, ref fctx, in ast, in ta, in names, ref diags);
        int id = fctx.AddLocal(nameId, typeId, PassMode.ByValue, flags, tokIdx);
        InsertScopeEntryAtDepth(ref fctx, depth, id, tokIdx);
        if (nameId >= 0) InsertVarBindingAtDepth(ref fctx, depth, nameId, id);
        return id;
    }

    private static int BorrowWindowSourcePlace(int expression, int operand, in FuncLowerCtx fctx, in AstArena ast, in MirModuleArena mir)
    {
        MirOperand op = mir.Operands[operand];
        if (op.Kind != MirOpKinds.CopyOrMove || IsSourceValuePlace(op.PlaceOrLitIdx, in fctx, in mir)) return -1;
        AstNode node = ast.Nodes[expression];
        if (node.Kind == AstKind.ExprIdent || node.Kind == AstKind.ExprThis || node.Kind == AstKind.ExprMember || node.Kind == AstKind.ExprIndex)
            return op.PlaceOrLitIdx;
        // A ref assignment is itself a variable. Its operand dereferences
        // the newly bound carrier; normal value assignments are not places.
        if (node.Kind == AstKind.ExprAssign && node.D != 0) return op.PlaceOrLitIdx;
        // An arbitrary value call or cast can also lower to an existing
        // operand. Only a ref-returning call provides storage to borrow.
        MirPlace place = mir.Places[op.PlaceOrLitIdx];
        if (node.Kind == AstKind.ExprCall && place.ProjCount > 0 && mir.Projs[place.ProjStart].Kind == MirProjKinds.Deref &&
            (fctx.Locals[place.LocalId].Flags & (MirLocalFlags.IsRefLocal | MirLocalFlags.IsTemp)) == (MirLocalFlags.IsRefLocal | MirLocalFlags.IsTemp))
            return op.PlaceOrLitIdx;
        return -1;
    }

    private static bool HasSwitchGuard(in AstNode node, bool expression, in AstArena ast)
    {
        for (int i = 0; i < node.C; i++)
        {
            AstNode arm = ast.Nodes[ast.Extra[node.B + i]];
            if (expression)
            {
                if (arm.C >= 0) return true;
            }
            else
            {
                for (int j = 0; j < arm.B; j++) if (ast.Nodes[ast.Extra[arm.A + j]].B >= 0) return true;
            }
        }
        return false;
    }

    // Evaluate a selector/receiver exactly once. A ref indexer is loaded
    // into a value temporary by ordinary lowering, but its address still
    // supplies the owner of the source evaluation loan.
    private static int LowerBorrowWindowInput(int expression, int expectedTypeId, bool snapshotIndex, ref FuncLowerCtx fctx,
        in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx, ref TypeTable types,
        ref MirModuleArena mir, ref DiagnosticBag diags, out int sourcePlace)
    {
        AstNode node = ast.Nodes[expression];
        if (node.Kind == AstKind.ExprIndex && (node.D < 0 || ast.Nodes[node.D].Kind != AstKind.ExprRange))
        {
            int before = diags.Items.Count;
            int place;
            int op;
            if (snapshotIndex)
                op = LowerIndexValue(expression, node.TokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out place);
            else
            {
                place = LowerPlace(expression, isMut: false, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                op = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, place, 0, mir.Places[place].TypeId, node.TokIdx,
                    SourceExpressionStartToken(expression, in ast)));
            }
            int converted = ConvertOperandIfNeeded(op, expectedTypeId, node.TokIdx, ref fctx, in ast, in ta,
                in names, in bctx, in types, ref mir, ref diags, expression, diags.Items.Count > before);
            sourcePlace = converted != op || IsSourceValuePlace(place, in fctx, in mir) ? -1 : place;
            return converted;
        }
        int operand = LowerExprAsOperand(expression, expectedTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        sourcePlace = BorrowWindowSourcePlace(expression, operand, in fctx, in ast, in mir);
        return operand;
    }

    private static int LowerGenericSwitchInput(in AstNode node, bool isExpr, ref FuncLowerCtx fctx,
        in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx, ref TypeTable types,
        ref MirModuleArena mir, ref DiagnosticBag diags, out int type, out int sourcePlace)
    {
        int scrutOp;
        if (HasSwitchGuard(in node, isExpr, in ast))
            scrutOp = LowerBorrowWindowInput(node.A, -1, snapshotIndex: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out sourcePlace);
        else
        {
            sourcePlace = -1;
            scrutOp = LowerExprAsOperand(node.A, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }
        type = mir.Operands[scrutOp].TypeId;
        // Merely testing a non-Copy place must not implicitly move it. A
        // declaration pattern can still move it at the actual binding.
        if (sourcePlace >= 0 && !types.IsCopy(type, in ast)) return sourcePlace;
        int tmp = fctx.NewTemp(type, node.TokIdx, ref mir);
        int place = mir.AddPlaceLocal(tmp, type);
        fctx.Emit(new MirInst(MirOp.AssignUse, place, -1, 0, type, scrutOp, 0, 0, 0, node.TokIdx));
        return place;
    }

    // Analysis-only shared borrow over a source evaluation window. Liveness
    // is use-based as with other BindRef loans, but LLVM has no pointer slot
    // or load/store for the synthetic carrier.
    private static int BeginBorrowWindow(int place, int tokIdx, int windowFlag, ref FuncLowerCtx fctx, in MirModuleArena mir)
    {
        if (place < 0) return -1;
        int type = mir.Places[place].TypeId;
        int flags = MirLocalFlags.IsTemp | MirLocalFlags.IsRefLocal | MirLocalFlags.IsAnalysisBorrow | windowFlag;
        int loan = fctx.AddLocal(-1, type, PassMode.ByValue, flags, tokIdx);
        fctx.Emit(new MirInst(MirOp.BindRef, -1, loan, 0, type, loan, place, 0, 0, tokIdx));
        return loan;
    }

    private static void EndBorrowWindow(int loan, int tokIdx, ref FuncLowerCtx fctx)
    {
        if (loan >= 0) fctx.Emit(new MirInst(MirOp.KeepBorrowAlive, -1, -1, 0, TypeIds.Void, loan, 0, 0, 0, tokIdx));
    }

    private static void CheckGuardedCursorPayloadBinding(int pat, int guard, TypeInfo scrutType,
        in AstArena ast, in TokenArena ta, ref DiagnosticBag diags)
    {
        if (scrutType.Kind != TypeKinds.OptionMut || pat < 0 || guard < 0) return;
        // The binding takes an exclusive payload borrow during matching,
        // regardless of whether its name is used later in the arm.
        AstNode pattern = ast.Nodes[pat];
        if (pattern.Kind == AstKind.PatUnion && PatternHasDeclBind(pattern.D, in ast))
            diags.ReportTok(VibCodes.ConflictActiveBorrow, ta.Tokens[pattern.TokIdx],
                "Cannot bind a mutable cursor payload while the switch guard borrows the cursor."u8);
    }

    private static int BeginRvalueViewBorrowWindow(int scrutOp, int unionKind, int payloadLid, int tokIdx, ref FuncLowerCtx fctx, in MirModuleArena mir)
    {
        if (unionKind != TypeKinds.OptionRef && unionKind != TypeKinds.OptionMut) return -1;
        MirOperand op = mir.Operands[scrutOp];
        if (op.Kind != MirOpKinds.CopyOrMove) return -1;
        int place = op.PlaceOrLitIdx;
        int type = mir.Places[place].TypeId;
        int flags = MirLocalFlags.IsTemp | MirLocalFlags.IsRefLocal | MirLocalFlags.IsAnalysisBorrow | MirLocalFlags.IsSwitchGuardBorrow;
        if (payloadLid >= 0) flags |= MirLocalFlags.IsRepointLoanSnapshot;
        int loan = fctx.AddLocal(-1, type, PassMode.ByValue, flags, tokIdx);
        fctx.Emit(new MirInst(MirOp.BindRef, -1, loan, 4, type, loan, place, payloadLid + 1, 0, tokIdx));
        return loan;
    }

    private static void LowerSwitchGuard(int guard, int scrutPlace, int yes, int no,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx,
        ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags, bool keepRefLive, int keepLoan)
    {
        // All patterns protect the original access path through their guard.
        // A ref scrutinee's own loan (or an rvalue view's referent loan) stays
        // alive across the guard iff a later arm still tests or binds it.
        if (scrutPlace < 0 && keepLoan < 0)
        {
            LowerCondBranch(guard, yes, no, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope: false);
            return;
        }
        int tokIdx = ast.Nodes[guard].TokIdx;
        int loan = scrutPlace >= 0 ? BeginBorrowWindow(scrutPlace, tokIdx, MirLocalFlags.IsSwitchGuardBorrow, ref fctx, in mir) : keepLoan;
        int sourceRef = -1;
        if (scrutPlace >= 0 && keepRefLive)
        {
            int root = mir.Places[scrutPlace].LocalId;
            if ((fctx.Locals[root].Flags & MirLocalFlags.IsRefLocal) != 0) sourceRef = root;
        }
        int yesEnd = fctx.NewBlock();
        int noEnd = fctx.NewBlock();
        LowerCondBranch(guard, yesEnd, noEnd, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope: false);
        fctx.CurBlock = yesEnd;
        EndBorrowWindow(loan, tokIdx, ref fctx);
        EndBorrowWindow(sourceRef, tokIdx, ref fctx);
        fctx.Terminate(new MirTerm(MirTermKind.Goto, yes, 0, 0, 0, 0, 0, tokIdx));
        fctx.CurBlock = noEnd;
        EndBorrowWindow(loan, tokIdx, ref fctx);
        EndBorrowWindow(sourceRef, tokIdx, ref fctx);
        fctx.Terminate(new MirTerm(MirTermKind.Goto, no, 0, 0, 0, 0, 0, tokIdx));
    }

    private static void LowerSwitchStatementCore(
        in AstNode n,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int tokIdx = n.TokIdx;
        int secCount = n.C;
        int scrutType = InferExprType(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        if (scrutType == TypeIds.Str)
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[n.A].TokIdx], "Switch on 'string' is banned in Vibranium; match UTF-8 bytes via '.AsUtf8()' instead."u8);
        }
        TypeInfo sti = types.Items[scrutType];
        if (!types.IsInteger(scrutType) && scrutType != TypeIds.Bool && !types.IsFloat(scrutType))
        {
            CheckSourceScalarPatternCoverage(in n, scrutType, false, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        }
        for (int i = 0; i < secCount; i++)
        {
            AstNode secT = ast.Nodes[ast.Extra[n.B + i]];
            for (int l = 0; l < secT.B; l++)
                CheckUnionTypePatterns(ast.Nodes[ast.Extra[secT.A + l]].A, scrutType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        }

        bool hasUnionCase = false;
        for (int i = 0; i < secCount; i++)
        {
            AstNode sec = ast.Nodes[ast.Extra[n.B + i]];
            for (int l = 0; l < sec.B; l++)
            {
                AstNode lbl = ast.Nodes[ast.Extra[sec.A + l]];
                // A variant test nested in `not`/`or`/`and` (`case not NoneType:`)
                // is still a union switch: route it to the place-based union
                // lowering instead of the generic path, which would move a
                // non-Copy scrutinee place into a temporary.
                if (lbl.A >= 0 && (ast.Nodes[lbl.A].Kind == AstKind.PatUnion ||
                    (IsUnionScrutineeKind(sti.Kind) && ContainsUnionPattern(lbl.A, in ast))))
                {
                    hasUnionCase = true;
                    break;
                }
            }
        }

        int exitBlk = fctx.NewBlock();
        int outerContinue = fctx.Loops.Count > 0 ? fctx.Loops[fctx.Loops.Count - 1].ContinueBlock : -1;
        int outerContinueDepth = fctx.Loops.Count > 0 ? fctx.Loops[fctx.Loops.Count - 1].ContinueScopeDepth : -1;

        // Union switch statement (`switch (r) { case Ok<T>(var x): ... case Err<E>(var e): ... }`)
        if (hasUnionCase && sti.Kind == TypeKinds.SomeWrap)
        {
            scrutType = types.MakeOption(sti.A);
            sti = types.Items[scrutType];
        }
        if (hasUnionCase && (sti.Kind == TypeKinds.Option || sti.Kind == TypeKinds.OptionRef || sti.Kind == TypeKinds.OptionMut || sti.Kind == TypeKinds.Result))
        {
            LowerUnionSwitchStatement(in n, scrutType, sti, exitBlk, outerContinue, outerContinueDepth, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            return;
        }

        CheckLinearUnionSwitchArms(in n, false, scrutType, sti, IsPlaceExpression(n.A, in ast, in fctx, in types), in ast, in ta, in bctx, in types, ref diags);
        int curOwnerSwStmt = fctx.EnclosingOwnerDeclId;
        bool hasSourceConstant = TryGetSourceSwitchConstant(n.A, scrutType, curOwnerSwStmt, in fctx, in ast, in ta, in names, in bctx, in types, out ulong sourceValue, out bool sourceNaN);
        int scrutPl = LowerGenericSwitchInput(in n, false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out scrutType, out int sourcePlace);

        int sourceEntry = fctx.CurBlock;
        int sourceAfterInst = fctx.BlockTail[sourceEntry];
        var sourceTargets = new Vec<int>();
        var sourceBodies = new Vec<int>();
        BindSwitchDeclarations(in n, scrutType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        CheckSourceScalarPatternCoverage(in n, scrutType, false, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);

        int defaultSecIdx = -1;
        for (int i = 0; i < secCount; i++)
        {
            AstNode sec = ast.Nodes[ast.Extra[n.B + i]];
            for (int l = 0; l < sec.B; l++)
            {
                AstNode lbl = ast.Nodes[ast.Extra[sec.A + l]];
                if (lbl.A < 0 && lbl.B < 0)
                {
                    defaultSecIdx = i;
                }
            }
        }

        var secBlocks = new Vec<int>(secCount);
        for (int i = 0; i < secCount; i++) secBlocks.Push(-1);
        var unguardedCasePats = new Vec<int>(secCount);
        for (int i = 0; i < secCount; i++)
        {
            AstNode secU = ast.Nodes[ast.Extra[n.B + i]];
            for (int l = 0; l < secU.B; l++)
            {
                AstNode lblU = ast.Nodes[ast.Extra[secU.A + l]];
                if (lblU.A >= 0 && IsSourceUnguardedPattern(lblU.A, lblU.B, ref fctx, in ast, in ta, in names, in bctx, in types)) unguardedCasePats.Push(lblU.A);
            }
        }
        bool coversSourceDomain = IsPatternSetExhaustive(unguardedCasePats.AsReadOnlySpan(), scrutType, curOwnerSwStmt, ref fctx, in ast, in ta, in names, ref bctx, ref types);
        bool isExhaustiveNoDefault = defaultSecIdx < 0 && coversSourceDomain;
        bool unreachableScalarDefault = defaultSecIdx >= 0 && coversSourceDomain &&
            (types.IsInteger(scrutType) || scrutType == TypeIds.Bool || types.IsFloat(scrutType));
        int defaultBlk = (defaultSecIdx >= 0 || isExhaustiveNoDefault) ? fctx.NewBlock() : exitBlk;
        if (defaultSecIdx >= 0) secBlocks[defaultSecIdx] = defaultBlk;
        if (!unreachableScalarDefault)
        {
            sourceTargets.Push(defaultBlk);
            sourceBodies.Push(defaultBlk);
        }

        for (int i = 0; i < secCount; i++)
        {
            AstNode sec = ast.Nodes[ast.Extra[n.B + i]];
            bool hasNonDefaultLabel = false;
            for (int l = 0; l < sec.B; l++)
            {
                AstNode lbl = ast.Nodes[ast.Extra[sec.A + l]];
                if (lbl.A >= 0 || lbl.B >= 0) hasNonDefaultLabel = true;
            }
            if (!hasNonDefaultLabel) continue;

            PushScope(ref fctx);
            int bodyBlk = secBlocks[i] >= 0 ? secBlocks[i] : fctx.NewBlock();
            secBlocks[i] = bodyBlk;
            sourceBodies.Push(bodyBlk);

            for (int l = 0; l < sec.B; l++)
            {
                AstNode lbl = ast.Nodes[ast.Extra[sec.A + l]];
                if (lbl.A < 0 && lbl.B < 0) continue;
                sourceTargets.Push(fctx.CurBlock);
                int nextLblBlk = fctx.NewBlock();
                int patMatchBlk = lbl.B >= 0 ? fctx.NewBlock() : bodyBlk;
                if (lbl.A >= 0)
                {
                    int savedConstantPlace = fctx.SourceConstantPatternPlace;
                    ulong savedConstantValue = fctx.SourceConstantPatternValue;
                    bool savedConstantNaN = fctx.SourceConstantPatternNaN;
                    fctx.SourceConstantPatternPlace = hasSourceConstant ? scrutPl : -1;
                    fctx.SourceConstantPatternValue = sourceValue;
                    fctx.SourceConstantPatternNaN = sourceNaN;
                    int savedInputToken = fctx.SourcePatternInputToken;
                    fctx.SourcePatternInputToken = ast.Nodes[n.A].TokIdx;
                    LowerNonUnionPatternBranch(scrutPl, scrutType, lbl.A, lbl.TokIdx, patMatchBlk, nextLblBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    fctx.SourcePatternInputToken = savedInputToken;
                    fctx.SourceConstantPatternPlace = savedConstantPlace;
                    fctx.SourceConstantPatternValue = savedConstantValue;
                    fctx.SourceConstantPatternNaN = savedConstantNaN;
                }
                else
                {
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, patMatchBlk, 0, 0, 0, 0, 0, lbl.TokIdx));
                }
                if (lbl.B >= 0)
                {
                    fctx.CurBlock = patMatchBlk;
                    LowerSwitchGuard(lbl.B, sourcePlace, bodyBlk, nextLblBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, HasLaterScrutineeLabel(in n, i, l, in ast), -1);
                }
                fctx.CurBlock = nextLblBlk;
            }

            int afterSecTestsBlk = fctx.NewBlock();
            fctx.Terminate(new MirTerm(MirTermKind.Goto, afterSecTestsBlk, 0, 0, 0, 0, 0, sec.TokIdx));

            fctx.CurBlock = bodyBlk;
            int contDepth = outerContinueDepth >= 0 ? outerContinueDepth : fctx.ScopeDepth;
            fctx.Loops.Push(new LoopFrame(exitBlk, outerContinue, fctx.ScopeDepth, contDepth));
            for (int st = 0; st < sec.D; st++)
            {
                LowerStatement(ast.Extra[sec.C + st], ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }
            fctx.Loops.Pop();
            PopScope(sec.TokIdx, ref fctx, ref mir);
            if (!fctx.IsBlockTerminated(fctx.CurBlock))
            {
                fctx.SourceSwitchSectionEnds.Push(fctx.CurBlock);
                fctx.Terminate(new MirTerm(MirTermKind.Goto, exitBlk, 0, 0, 0, 0, 0, sec.TokIdx));
            }

            fctx.CurBlock = afterSecTestsBlk;
        }

        // An unreachable default contributes neither source endpoint/DA paths
        // nor runtime ownership obligations. Keep syntax diagnostics, but do
        // not invent a fallback after full-domain coverage (including NaN).
        fctx.Terminate(unreachableScalarDefault
            ? new MirTerm(MirTermKind.Unreachable, 0, 0, 0, 0, 0, 0, tokIdx)
            : new MirTerm(MirTermKind.Goto, defaultBlk, 0, 0, 0, 0, 0, tokIdx));

        if (defaultSecIdx >= 0)
        {
            AstNode dSec = ast.Nodes[ast.Extra[n.B + defaultSecIdx]];
            fctx.CurBlock = defaultBlk;
            PushScope(ref fctx);
            int contDepth = outerContinueDepth >= 0 ? outerContinueDepth : fctx.ScopeDepth;
            fctx.Loops.Push(new LoopFrame(exitBlk, outerContinue, fctx.ScopeDepth, contDepth));
            for (int st = 0; st < dSec.D; st++)
            {
                LowerStatement(ast.Extra[dSec.C + st], ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }
            fctx.Loops.Pop();
            PopScope(dSec.TokIdx, ref fctx, ref mir);
            if (!fctx.IsBlockTerminated(fctx.CurBlock))
            {
                fctx.SourceSwitchSectionEnds.Push(fctx.CurBlock);
                fctx.Terminate(new MirTerm(MirTermKind.Goto, exitBlk, 0, 0, 0, 0, 0, dSec.TokIdx));
            }
        }
        else if (isExhaustiveNoDefault)
        {
            fctx.CurBlock = defaultBlk;
            fctx.Terminate(new MirTerm(MirTermKind.Unreachable, 0, 0, 0, 0, 0, 0, tokIdx));
            if (IsUnionType(scrutType, in types) && SourceUnionSwitchHasRemainder(in n, ref fctx, in ast, in ta, in names, in bctx, in types))
            {
                MirTerm sourceExit = new MirTerm(MirTermKind.Goto, exitBlk, 0, 0, 0, 0, 0, tokIdx);
                fctx.SourceBlockTerms[defaultBlk] = sourceExit;
                fctx.SourceAssignmentTerms[defaultBlk] = sourceExit;
            }
        }

        RecordSourceSwitchFlow(sourceEntry, sourceAfterInst, in sourceTargets, in sourceBodies, ref fctx);
        fctx.CurBlock = exitBlk;
    }

    private static bool IsUnionType(int typeId, in TypeTable types)
    {
        int kind = types.Items[typeId].Kind;
        return kind == TypeKinds.Option || kind == TypeKinds.OptionRef || kind == TypeKinds.OptionMut || kind == TypeKinds.Result;
    }

    // C# statement flow retains the union protocol's no-matching-member outcome.
    // Positive variant patterns do not cover it; ordinary catchalls and logical
    // complements can. This is independent of the closed native representation.
    private static bool SourceUnionRemainderMatches(int patternId, in AstArena ast)
    {
        if (patternId < 0) return true;
        AstNode pattern = ast.Nodes[patternId];
        if (pattern.Kind == AstKind.PatWildcard) return true;
        if (pattern.Kind == AstKind.PatDecl) return pattern.A < 0;
        if (pattern.Kind == AstKind.PatNot) return !SourceUnionRemainderMatches(pattern.A, in ast);
        if (pattern.Kind == AstKind.PatLogic)
        {
            bool left = SourceUnionRemainderMatches(pattern.B, in ast);
            bool right = SourceUnionRemainderMatches(pattern.C, in ast);
            return pattern.A == 0 ? left && right : left || right;
        }
        return false;
    }

    private static void PushSourcePatternShadows(int patternId, ref FuncLowerCtx fctx, in AstArena ast)
    {
        if (patternId < 0) return;
        AstNode pattern = ast.Nodes[patternId];
        if (pattern.Kind == AstKind.PatDecl || pattern.Kind == AstKind.PatUnion)
        {
            if (pattern.B >= 0) fctx.Vars.Push(new VarBinding(pattern.B, -2, fctx.ScopeDepth, 0, TypeIds.Error, 0));
            if (pattern.Kind == AstKind.PatUnion) PushSourcePatternShadows(pattern.D, ref fctx, in ast);
        }
        else if (pattern.Kind == AstKind.PatNot) PushSourcePatternShadows(pattern.A, ref fctx, in ast);
        else if (pattern.Kind == AstKind.PatLogic)
        {
            PushSourcePatternShadows(pattern.B, ref fctx, in ast);
            PushSourcePatternShadows(pattern.C, ref fctx, in ast);
        }
    }

    private static bool IsSourceUnguardedPattern(int patternId, int guardId, ref FuncLowerCtx fctx,
        in AstArena ast, in TokenArena ta, in Interner names, in BinderCtx bctx, in TypeTable types)
    {
        if (guardId < 0) return true;
        // Source coverage runs before runtime pattern bindings exist. Their names
        // must still hide enclosing constants; reserving lexical shadows emits nothing.
        int variableMark = fctx.Vars.Count;
        PushSourcePatternShadows(patternId, ref fctx, in ast);
        bool unguarded = TryEvalBoolConstExpr(guardId, fctx.EnclosingOwnerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out bool value) && value;
        fctx.Vars.Truncate(variableMark);
        return unguarded;
    }

    private static bool SourceUnionSwitchHasRemainder(in AstNode statement, ref FuncLowerCtx fctx,
        in AstArena ast, in TokenArena ta, in Interner names, in BinderCtx bctx, in TypeTable types)
    {
        for (int s = 0; s < statement.C; s++)
        {
            AstNode section = ast.Nodes[ast.Extra[statement.B + s]];
            for (int l = 0; l < section.B; l++)
            {
                AstNode label = ast.Nodes[ast.Extra[section.A + l]];
                // A default is the source remainder's destination, not proof it is absent.
                if (label.A < 0) continue;
                if (SourceUnionRemainderMatches(label.A, in ast) &&
                    IsSourceUnguardedPattern(label.A, label.B, ref fctx, in ast, in ta, in names, in bctx, in types)) return false;
            }
        }
        return true;
    }

    private static int LowerUnionSwitchInput(in AstNode node, bool isExpr, int scrutType, int unionKind,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx,
        ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags, out int termFlags)
    {
        termFlags = unionKind == TypeKinds.OptionMut ? 6 : unionKind == TypeKinds.OptionRef ? 4 : 0;
        if (HasSwitchGuard(in node, isExpr, in ast))
        {
            // The actual lowering identifies ref-returning selectors without
            // evaluating the selector twice. The same place drives dispatch,
            // payload binding, and guard borrow provenance.
            int operand = LowerBorrowWindowInput(node.A, scrutType, snapshotIndex: false, ref fctx,
                in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int place);
            if (place < 0) return operand;
            termFlags |= 1;
            return place;
        }
        if (IsPlaceExpression(node.A, in ast, in fctx, in types))
        {
            termFlags |= 1;
            return LowerPlace(node.A, isMut: isExpr && unionKind == TypeKinds.OptionMut, isTwoPhase: false,
                ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }
        return LowerExprAsOperand(node.A, scrutType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
    }

    private static void LowerUnionSwitchStatement(
        in AstNode n,
        int scrutType,
        TypeInfo sti,
        int exitBlk,
        int outerContinue,
        int outerContinueDepth,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int tokIdx = n.TokIdx;
        int secCount = n.C;
        int scrutPlaceOrOp = LowerUnionSwitchInput(in n, false, scrutType, sti.Kind, ref fctx, in ast, in ta,
            ref names, ref bctx, ref types, ref mir, ref diags, out int termFlags);
        bool isPlaceExpr = (termFlags & 1) != 0;
        CheckLinearUnionSwitchArms(in n, false, scrutType, sti, isPlaceExpr, in ast, in ta, in bctx, in types, ref diags);
        bool isLinear = types.IsLinear(scrutType, in ast);

        int firstSecIdx = -1; // Some or Ok
        int firstBind = -1;
        int firstWhen = -1;
        int firstPatTok = tokIdx;
        int firstCount = 0;
        int secondSecIdx = -1; // None or Err
        int secondBind = -1;
        int secondWhen = -1;
        int secondPatTok = tokIdx;
        int secondCount = 0;
        int defaultSecIdx = -1;
        bool hasComplexUnionPat = false;

        for (int i = 0; i < secCount; i++)
        {
            AstNode sec = ast.Nodes[ast.Extra[n.B + i]];
            for (int l = 0; l < sec.B; l++)
            {
                AstNode lbl = ast.Nodes[ast.Extra[sec.A + l]];
                if (lbl.A < 0)
                {
                    defaultSecIdx = i;
                    continue;
                }
                AstNode pat = ast.Nodes[lbl.A];
                if (isPlaceExpr) CheckGuardedCursorPayloadBinding(lbl.A, lbl.B, sti, in ast, in ta, ref diags);
                if (pat.Kind == AstKind.PatWildcard)
                {
                    defaultSecIdx = i;
                    continue;
                }
                if (pat.Kind == AstKind.PatUnion)
                {
                    int head = ast.Nodes[pat.A].A;
                    bool isFirst = (sti.Kind == TypeKinds.Result) ? (head == bctx.IdOk) : (head == bctx.IdSome);
                    int varPayloadT = isFirst ? sti.A : (sti.Kind == TypeKinds.Result ? sti.B : TypeIds.NoneUnit);
                    UnpackPatUnion(in pat, varPayloadT, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int directBind, out int wrapBind, out int extraSubPat);
                    if (isPlaceExpr && isLinear)
                    {
                        diags.ReportTok(VibCodes.LinearViolation, ta.Tokens[pat.TokIdx], "Pattern matching on a linear union place without moving it is banned in Vibranium."u8);
                    }
                    if ((pat.C != 0 || extraSubPat >= 0) && isLinear)
                    {
                        diags.ReportTok(VibCodes.LinearViolation, ta.Tokens[pat.TokIdx], "Nested subpatterns on linear union resources are banned in Vibranium."u8);
                    }
                    if (extraSubPat >= 0 || wrapBind >= 0) hasComplexUnionPat = true;
                    if (isFirst)
                    {
                        firstCount += 1;
                        if (firstSecIdx < 0)
                        {
                            firstSecIdx = i;
                            firstBind = directBind;
                            firstWhen = lbl.B;
                            firstPatTok = pat.TokIdx;
                        }
                    }
                    else
                    {
                        secondCount += 1;
                        if (secondSecIdx < 0)
                        {
                            secondSecIdx = i;
                            secondBind = directBind;
                            secondWhen = lbl.B;
                            secondPatTok = pat.TokIdx;
                        }
                    }
                }
                else
                {
                    hasComplexUnionPat = true;
                }
            }
        }
        if (firstCount > 1 || secondCount > 1 || firstWhen >= 0 || secondWhen >= 0) hasComplexUnionPat = true;

        BindSwitchDeclarations(in n, scrutType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);

        bool isBorrowed = isPlaceExpr || sti.Kind == TypeKinds.OptionRef || sti.Kind == TypeKinds.OptionMut;
        bool isShared = (isPlaceExpr && sti.Kind != TypeKinds.OptionMut) || sti.Kind == TypeKinds.OptionRef;

        if (hasComplexUnionPat)
        {
            LowerComplexUnionSwitchStatement(in n, scrutType, sti, scrutPlaceOrOp, termFlags, isBorrowed, isShared, defaultSecIdx, exitBlk, outerContinue, outerContinueDepth, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            fctx.CurBlock = exitBlk;
            return;
        }

        if (firstSecIdx < 0) firstSecIdx = defaultSecIdx;
        if (secondSecIdx < 0) secondSecIdx = defaultSecIdx;

        int defaultBlk = defaultSecIdx >= 0 && defaultSecIdx != firstSecIdx && defaultSecIdx != secondSecIdx ? fctx.NewBlock() : exitBlk;
        int arm1Blk = firstSecIdx >= 0 ? fctx.NewBlock() : defaultBlk;
        int arm2Blk = secondSecIdx >= 0 ? (secondSecIdx == firstSecIdx ? arm1Blk : fctx.NewBlock()) : defaultBlk;
        int sourceFallback = defaultSecIdx == firstSecIdx && defaultSecIdx >= 0 ? arm1Blk :
            (defaultSecIdx == secondSecIdx && defaultSecIdx >= 0 ? arm2Blk : defaultBlk);
        fctx.SourceSwitchContinuations.Push(new SourceSwitchAssignmentEdge(fctx.CurBlock, fctx.BlockTail[fctx.CurBlock], sourceFallback));

        if (sti.Kind == TypeKinds.Result)
        {
            int okFlags = MakePatternBindFlags(sti.A, firstBind, isBorrowed, isShared, in ast, in types);
            int errFlags = MakePatternBindFlags(sti.B, secondBind, isBorrowed, isShared, in ast, in types);
            int okLid = fctx.AddLocal(firstBind, sti.A, PassMode.ByValue, okFlags, firstPatTok);
            int errLid = fctx.AddLocal(secondBind, sti.B, PassMode.ByValue, errFlags, secondPatTok);
            fctx.Terminate(new MirTerm(MirTermKind.MatchResult, scrutPlaceOrOp, okLid, arm1Blk, errLid, arm2Blk, termFlags, tokIdx));

            if (firstSecIdx >= 0)
            {
                EmitUnionSwitchArmBody(n.B, firstSecIdx, scrutType, okLid, firstBind, firstWhen, defaultBlk, exitBlk, outerContinue, outerContinueDepth, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, arm1Blk);
            }
            if (secondSecIdx >= 0 && secondSecIdx != firstSecIdx)
            {
                EmitUnionSwitchArmBody(n.B, secondSecIdx, scrutType, errLid, secondBind, secondWhen, defaultBlk, exitBlk, outerContinue, outerContinueDepth, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, arm2Blk);
            }
        }
        else
        {
            int someFlags = MakePatternBindFlags(sti.A, firstBind, isBorrowed, isShared, in ast, in types);
            int someLid = fctx.AddLocal(firstBind, sti.A, PassMode.ByValue, someFlags, firstPatTok);
            fctx.Terminate(new MirTerm(MirTermKind.MatchOption, scrutPlaceOrOp, someLid, arm1Blk, arm2Blk, 0, termFlags, tokIdx));

            if (firstSecIdx >= 0)
            {
                EmitUnionSwitchArmBody(n.B, firstSecIdx, scrutType, someLid, firstBind, firstWhen, defaultBlk, exitBlk, outerContinue, outerContinueDepth, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, arm1Blk);
            }
            if (secondSecIdx >= 0 && secondSecIdx != firstSecIdx)
            {
                EmitUnionSwitchArmBody(n.B, secondSecIdx, scrutType, -1, -1, secondWhen, defaultBlk, exitBlk, outerContinue, outerContinueDepth, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, arm2Blk);
            }
        }

        if (defaultBlk != exitBlk && defaultSecIdx >= 0)
        {
            EmitUnionSwitchArmBody(n.B, defaultSecIdx, scrutType, -1, -1, -1, exitBlk, exitBlk, outerContinue, outerContinueDepth, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, defaultBlk);
        }

        fctx.CurBlock = exitBlk;
    }

    private static void BindUnionSectionSiblingPatterns(
        in AstNode section, int scrutType,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names,
        ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        if (section.B < 2) return;
        // Union dispatch clones a section for each label/variant. C# gives all
        // sibling pattern names section scope, even in a when-false clone.
        // Reserve only lexical identities and types: a sibling's declaration
        // does not initialize its value on this label's path.
        var bindings = new Vec<VarBinding>();
        for (int i = 0; i < section.B; i++)
        {
            AstNode label = ast.Nodes[ast.Extra[section.A + i]];
            bindings.Clear();
            CollectSpeculativePatternBindings(label.A, scrutType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref bindings);
            for (int b = 0; b < bindings.Count; b++)
            {
                VarBinding binding = bindings[b];
                bool boundHere = false;
                for (int v = fctx.Vars.Count - 1; v >= 0; v--)
                {
                    VarBinding existing = fctx.Vars[v];
                    if (existing.ScopeDepth == fctx.ScopeDepth && existing.NameId == binding.NameId)
                    {
                        boundHere = true;
                        break;
                    }
                }
                if (!boundHere)
                    _ = BindExpressionLocal(binding.NameId, binding.ConstTypeId, 0, fctx.ScopeDepth, label.TokIdx, ref fctx, in ast, in ta, in names, ref diags);
            }
        }
    }

    private static void EmitUnionSwitchArmBody(
        int secExtraBase,
        int secIdx,
        int scrutType,
        int boundLid,
        int boundNameId,
        int whenExprId,
        int guardFailBlk,
        int exitBlk,
        int outerContinue,
        int outerContinueDepth,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        int entryBlk)
    {
        AstNode sec = ast.Nodes[ast.Extra[secExtraBase + secIdx]];
        fctx.CurBlock = entryBlk;
        PushScope(ref fctx);
        if (boundLid >= 0)
        {
            fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, boundLid, 0, -1, sec.TokIdx));
            if (boundNameId >= 0)
            {
                RegisterScopedName(boundNameId, fctx.ScopeDepth, sec.TokIdx, ref fctx, in ast, in ta, in names, ref diags);
                fctx.Vars.Push(new VarBinding(boundNameId, boundLid, fctx.ScopeDepth, 0, TypeIds.Void, 0));
            }
        }
        BindUnionSectionSiblingPatterns(in sec, scrutType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        if (whenExprId >= 0)
        {
            int bodyAfterGuard = fctx.NewBlock();
            int failCleanBlk = fctx.NewBlock();
            LowerCondBranch(whenExprId, bodyAfterGuard, failCleanBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope: false);
            fctx.CurBlock = failCleanBlk;
            EmitScopeExitsDownTo(fctx.ScopeDepth, sec.TokIdx, ref fctx, ref mir);
            fctx.Terminate(new MirTerm(MirTermKind.Goto, guardFailBlk, 0, 0, 0, 0, 0, sec.TokIdx));
            fctx.CurBlock = bodyAfterGuard;
        }
        int contDepth = outerContinueDepth >= 0 ? outerContinueDepth : fctx.ScopeDepth;
        fctx.Loops.Push(new LoopFrame(exitBlk, outerContinue, fctx.ScopeDepth, contDepth));
        for (int st = 0; st < sec.D; st++)
        {
            LowerStatement(ast.Extra[sec.C + st], ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }
        fctx.Loops.Pop();
        PopScope(sec.TokIdx, ref fctx, ref mir);
        if (!fctx.IsBlockTerminated(fctx.CurBlock))
        {
            fctx.SourceSwitchSectionEnds.Push(fctx.CurBlock);
            fctx.Terminate(new MirTerm(MirTermKind.Goto, exitBlk, 0, 0, 0, 0, 0, sec.TokIdx));
        }
    }

    private static void LowerComplexUnionSwitchStatement(
        in AstNode n,
        int scrutType,
        TypeInfo sti,
        int scrutPlaceOrOp,
        int termFlags,
        bool isBorrowed,
        bool isShared,
        int defaultSecIdx,
        int exitBlk,
        int outerContinue,
        int outerContinueDepth,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int tokIdx = n.TokIdx;
        int secCount = n.C;
        int sourceEntry = fctx.CurBlock;
        int sourceAfterInst = fctx.BlockTail[sourceEntry];
        int curOwnerU = fctx.EnclosingOwnerDeclId;
        var unguardedUnionPats = new Vec<int>(secCount);
        for (int i = 0; i < secCount; i++)
        {
            AstNode secU = ast.Nodes[ast.Extra[n.B + i]];
            for (int l = 0; l < secU.B; l++)
            {
                AstNode lblU = ast.Nodes[ast.Extra[secU.A + l]];
                if (lblU.A >= 0 && IsSourceUnguardedPattern(lblU.A, lblU.B, ref fctx, in ast, in ta, in names, in bctx, in types)) unguardedUnionPats.Push(lblU.A);
            }
        }
        bool isExhaustiveUnion = defaultSecIdx < 0 &&
            IsPatternSetExhaustive(unguardedUnionPats.AsReadOnlySpan(), scrutType, curOwnerU, ref fctx, in ast, in ta, in names, ref bctx, ref types);
        int defaultBlk = (defaultSecIdx >= 0 || isExhaustiveUnion) ? fctx.NewBlock() : exitBlk;
        bool hasSourceRemainder = SourceUnionSwitchHasRemainder(in n, ref fctx, in ast, in ta, in names, in bctx, in types);
        if (hasSourceRemainder)
        {
            fctx.SourceSwitchContinuations.Push(new SourceSwitchAssignmentEdge(sourceEntry, sourceAfterInst, defaultBlk));
        }
        int v1Entry = fctx.NewBlock();
        int v2Entry = fctx.NewBlock();

        bool hasGuard = HasSwitchGuard(in n, false, in ast);
        bool deferCursorPayload = sti.Kind == TypeKinds.OptionMut && (termFlags & 1) != 0 && hasGuard;
        int v1Lid = deferCursorPayload ? -1 : fctx.AddLocal(-1, sti.A, PassMode.ByValue, MakePatternBindFlags(sti.A, -1, isBorrowed, isShared, in ast, in types), tokIdx);
        int rvalueViewLoan = (termFlags & 1) == 0 && hasGuard ? BeginRvalueViewBorrowWindow(scrutPlaceOrOp, sti.Kind, sti.Kind == TypeKinds.OptionMut ? v1Lid : -1, tokIdx, ref fctx, in mir) : -1;
        int v2Lid = -1;
        if (sti.Kind == TypeKinds.Result)
        {
            v2Lid = fctx.AddLocal(-1, sti.B, PassMode.ByValue, MakePatternBindFlags(sti.B, -1, isBorrowed, isShared, in ast, in types), tokIdx);
            fctx.Terminate(new MirTerm(MirTermKind.MatchResult, scrutPlaceOrOp, v1Lid, v1Entry, v2Lid, v2Entry, termFlags, tokIdx));
        }
        else if (deferCursorPayload)
        {
            int tag = EmitUnionTagRead(scrutPlaceOrOp, sti, tokIdx, ref fctx, ref mir);
            fctx.Terminate(new MirTerm(MirTermKind.Branch, tag, v1Entry, v2Entry, 0, 0, 0, tokIdx));
        }
        else
        {
            fctx.Terminate(new MirTerm(MirTermKind.MatchOption, scrutPlaceOrOp, v1Lid, v1Entry, v2Entry, 0, termFlags, tokIdx));
        }

        // A shared, in-place match of an owned union keeps its scrutinee place
        // intact, so whole-union labels can test that place directly.
        int scrutPlace = (termFlags & 1) != 0 && isShared && (sti.Kind == TypeKinds.Option || sti.Kind == TypeKinds.Result) ? scrutPlaceOrOp : -1;
        int guardPlace = (termFlags & 1) != 0 ? scrutPlaceOrOp : -1;
        EmitUnionVariantSwitchChain(in n, scrutType, sti, isFirstVariant: true, v1Lid, sti.A, isBorrowed, isShared, scrutPlace, guardPlace, rvalueViewLoan, v1Entry, defaultBlk, exitBlk, outerContinue, outerContinueDepth, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        EmitUnionVariantSwitchChain(in n, scrutType, sti, isFirstVariant: false, v2Lid, sti.Kind == TypeKinds.Result ? sti.B : TypeIds.Void, isBorrowed, isShared, scrutPlace, guardPlace, rvalueViewLoan, v2Entry, defaultBlk, exitBlk, outerContinue, outerContinueDepth, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);

        if (defaultSecIdx >= 0)
        {
            EmitUnionSwitchArmBody(n.B, defaultSecIdx, scrutType, -1, -1, -1, exitBlk, exitBlk, outerContinue, outerContinueDepth, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, defaultBlk);
        }
        else if (isExhaustiveUnion)
        {
            fctx.CurBlock = defaultBlk;
            fctx.Terminate(new MirTerm(MirTermKind.Unreachable, 0, 0, 0, 0, 0, 0, tokIdx));
            // As on the generic path: only the CLR union's nominal remainder,
            // when no unguarded label matches it, leaves an exhaustive union
            // switch in source terms (`case not NoneType:` matches it).
            if (hasSourceRemainder)
            {
                MirTerm sourceExit = new MirTerm(MirTermKind.Goto, exitBlk, 0, 0, 0, 0, 0, tokIdx);
                fctx.SourceBlockTerms[defaultBlk] = sourceExit;
                fctx.SourceAssignmentTerms[defaultBlk] = sourceExit;
            }
        }
    }

    private static void EmitUnionVariantSwitchChain(
        in AstNode n,
        int scrutType,
        TypeInfo sti,
        bool isFirstVariant,
        int payloadLid,
        int payloadType,
        bool isBorrowed,
        bool isShared,
        int scrutPlace,
        int guardPlace,
        int rvalueViewLoan,
        int entryBlk,
        int defaultBlk,
        int exitBlk,
        int outerContinue,
        int outerContinueDepth,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        fctx.CurBlock = entryBlk;
        var sourceTargets = new Vec<int>();
        var sourceBodies = new Vec<int>();
        sourceTargets.Push(defaultBlk);
        sourceBodies.Push(defaultBlk);
        PushScope(ref fctx);
        if (payloadLid >= 0)
        {
            fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, payloadLid, 0, -1, n.TokIdx));
        }

        bool sourceRemainder = true;
        int secCount = n.C;
        int matchingPayloadUses = 0;
        for (int i = 0; i < secCount; i++)
        {
            AstNode sec = ast.Nodes[ast.Extra[n.B + i]];
            for (int l = 0; l < sec.B; l++)
            {
                AstNode lbl = ast.Nodes[ast.Extra[sec.A + l]];
                if (lbl.A < 0) continue;
                AstNode pat = ast.Nodes[lbl.A];
                if (pat.Kind == AstKind.PatWildcard && lbl.B < 0) continue;
                if (pat.Kind == AstKind.PatUnion)
                {
                    int head = ast.Nodes[pat.A].A;
                    bool patIsFirst = (sti.Kind == TypeKinds.Result) ? (head == bctx.IdOk) : (head == bctx.IdSome);
                    if (patIsFirst == isFirstVariant) matchingPayloadUses += 1;
                }
                else
                {
                    matchingPayloadUses += 1;
                }
            }
        }
        bool subBorrow = isBorrowed || matchingPayloadUses > 1;
        bool subShared = subBorrow ? (isBorrowed ? isShared : true) : false;

        bool wholePlaceMayHaveMoved = false;
        for (int i = 0; i < secCount; i++)
        {
            AstNode sec = ast.Nodes[ast.Extra[n.B + i]];
            for (int l = 0; l < sec.B; l++)
            {
                AstNode lbl = ast.Nodes[ast.Extra[sec.A + l]];
                if (lbl.A < 0) continue;
                AstNode pat = ast.Nodes[lbl.A];
                if (pat.Kind == AstKind.PatWildcard && lbl.B < 0) continue;

                int armPayloadLid = payloadLid;
                int retestEntry = -1;
                bool canMatchVariant = false;
                int bindNameId = -1;
                int wrapNameId = -1;
                int headNameId = -1;
                int innerSubPat = -1;
                bool useWholeUnionFallback = false;
                if (pat.Kind == AstKind.PatUnion)
                {
                    headNameId = ast.Nodes[pat.A].A;
                    bool patIsFirst = (sti.Kind == TypeKinds.Result) ? (headNameId == bctx.IdOk) : (headNameId == bctx.IdSome);
                    if (patIsFirst != isFirstVariant)
                    {
                        if (wholePlaceMayHaveMoved) EmitUnionTagRead(scrutPlace, sti, pat.TokIdx, ref fctx, ref mir);
                        continue;
                    }
                    if (wholePlaceMayHaveMoved)
                    {
                        retestEntry = fctx.CurBlock;
                        armPayloadLid = EmitUnionVariantRetest(scrutPlace, sti, isFirstVariant, payloadType, pat.TokIdx, ref fctx, in ast, in types);
                    }
                    canMatchVariant = true;
                    UnpackPatUnion(in pat, payloadType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out bindNameId, out wrapNameId, out innerSubPat);
                }
                else if (pat.Kind == AstKind.PatWildcard || (pat.Kind == AstKind.PatDecl && pat.C == 0 && pat.B < 0))
                {
                    canMatchVariant = true;
                }
                else
                {
                    // `not NoneType`, `A or B`, `var o`, ...: test the whole union.
                    canMatchVariant = true;
                    useWholeUnionFallback = true;
                }
                if (!canMatchVariant) continue;
                if (payloadLid < 0 && isFirstVariant && (sti.Kind == TypeKinds.OptionMut || sti.Kind == TypeKinds.OptionRef) && guardPlace >= 0 &&
                    (bindNameId >= 0 || wrapNameId >= 0 || innerSubPat >= 0 || (useWholeUnionFallback && CursorTagPatternMask(lbl.A, in ast, in bctx) < 0)))
                {
                    retestEntry = fctx.CurBlock;
                    armPayloadLid = EmitUnionVariantRetest(guardPlace, sti, true, payloadType, pat.TokIdx, ref fctx, in ast, in types);
                }
                int labelStartBlk = fctx.CurBlock;
                // A nominal source edge must not bypass the Match that
                // initializes the hidden binding for a retested payload.
                sourceTargets.Push(retestEntry >= 0 ? retestEntry : labelStartBlk);

                int nextLblBlk = fctx.NewBlock();
                int bodyBlk = fctx.NewBlock();
                sourceBodies.Push(bodyBlk);
                PushScope(ref fctx);
                bool laterTest = lbl.B >= 0 && HasLaterScrutineeLabel(in n, i, l, in ast);
                bool sharedRetry = !isBorrowed && laterTest;
                BindSwitchPayload(bindNameId, armPayloadLid, payloadType, pat.TokIdx, sharedRetry,
                    ref fctx, in ast, in ta, in names, in types, ref mir, ref diags);

                int wrapStageBlk = wrapNameId >= 0 ? fctx.NewBlock() : (lbl.B >= 0 ? fctx.NewBlock() : bodyBlk);
                int afterInnerBlk = wrapNameId >= 0 ? (lbl.B >= 0 ? fctx.NewBlock() : bodyBlk) : wrapStageBlk;
                bool restorePayload = false;
                int rebuildPl = -1;
                int failLblBlk = nextLblBlk;
                if (useWholeUnionFallback)
                {
                    restorePayload = WholeUnionArmRestoresPayload(sti, isFirstVariant, armPayloadLid, payloadType, isBorrowed, lbl.A, in ast, in types);
                    if (restorePayload) failLblBlk = fctx.NewBlock();
                    rebuildPl = EmitWholeUnionArmTest(sti, isFirstVariant, armPayloadLid, payloadType, scrutPlace, lbl.A, lbl.TokIdx, wrapStageBlk, failLblBlk, subBorrow, subShared, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                }
                else if (innerSubPat >= 0 && armPayloadLid >= 0)
                {
                    int subPl = mir.AddPlaceLocal(armPayloadLid, payloadType);
                    LowerPatternOnPlaceBranch(subPl, payloadType, innerSubPat, pat.TokIdx, wrapStageBlk, nextLblBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, subBorrow || sharedRetry, subShared || sharedRetry);
                }
                else
                {
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, wrapStageBlk, 0, 0, 0, 0, 0, lbl.TokIdx));
                }
                if (wrapNameId >= 0)
                {
                    fctx.CurBlock = wrapStageBlk;
                    if (IsRejectedGuardedWrapperMove(wrapNameId, headNameId, lbl.B, armPayloadLid, payloadType, isBorrowed,
                            laterTest, in ast, in bctx, in types))
                        EmitRejectedGuardedWrapperBind(wrapNameId, headNameId, payloadType, sti, pat.TokIdx, ref fctx, in ast, in ta, in names, in bctx, ref types, ref mir, ref diags);
                    else
                        EmitUnionWrapperBind(wrapNameId, headNameId, armPayloadLid, payloadType, pat.TokIdx, ref fctx, in ast, in ta, in names, in bctx, ref types, ref mir, ref diags);
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, afterInnerBlk, 0, 0, 0, 0, 0, pat.TokIdx));
                }

                BindUnionSectionSiblingPatterns(in sec, scrutType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (sourceRemainder && SourceUnionRemainderMatches(lbl.A, in ast))
                {
                    // The nominal remainder enters from the variant's dispatch,
                    // where the hidden payload is extracted: a remainder path
                    // whose guard fails reaches later labels only nominally. A
                    // label that declares pattern variables is entered before
                    // its test, so the remainder also binds them.
                    int remainderTarget = retestEntry >= 0 ? retestEntry :
                        (useWholeUnionFallback && PatternHasDeclBind(lbl.A, in ast) ? labelStartBlk : wrapStageBlk);
                    fctx.SourceSwitchContinuations.Push(new SourceSwitchAssignmentEdge(entryBlk, -1, remainderTarget));
                    if (IsSourceUnguardedPattern(lbl.A, lbl.B, ref fctx, in ast, in ta, in names, in bctx, in types))
                    {
                        sourceRemainder = false;
                    }
                }
                if (lbl.B >= 0)
                {
                    fctx.CurBlock = afterInnerBlk;
                    LowerSwitchGuard(lbl.B, guardPlace, bodyBlk, failLblBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, laterTest, laterTest ? rvalueViewLoan : -1);
                }
                if (restorePayload)
                {
                    EmitWholeUnionPayloadRestore(sti, isFirstVariant, payloadLid, rebuildPl, failLblBlk, nextLblBlk, lbl.TokIdx, ref fctx, in ast, ref types, ref mir);
                    // The restore moves a hidden payload back; in source terms a
                    // failed test or guard simply continues with the next label.
                    MirTerm sourceNext = new MirTerm(MirTermKind.Goto, nextLblBlk, 0, 0, 0, 0, 0, lbl.TokIdx);
                    fctx.SourceBlockTerms[failLblBlk] = sourceNext;
                    fctx.SourceAssignmentTerms[failLblBlk] = sourceNext;
                }

                fctx.CurBlock = bodyBlk;
                int contDepth = outerContinueDepth >= 0 ? outerContinueDepth : fctx.ScopeDepth;
                fctx.Loops.Push(new LoopFrame(exitBlk, outerContinue, fctx.ScopeDepth, contDepth));
                for (int st = 0; st < sec.D; st++)
                {
                    LowerStatement(ast.Extra[sec.C + st], ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                }
                fctx.Loops.Pop();
                if (!fctx.IsBlockTerminated(fctx.CurBlock))
                {
                    EmitScopeExitsDownTo(fctx.ScopeDepth - 1, sec.TokIdx, ref fctx, ref mir);
                    fctx.SourceSwitchSectionEnds.Push(fctx.CurBlock);
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, exitBlk, 0, 0, 0, 0, 0, sec.TokIdx));
                }
                PopScopeWithoutEmit(ref fctx);

                if (scrutPlace >= 0 && lbl.B >= 0 && IsWholeUnionValueBinding(in pat) && !types.IsCopy(scrutType, in ast)) wholePlaceMayHaveMoved = true;
                fctx.CurBlock = nextLblBlk;
            }
        }

        EmitScopeExitsDownTo(fctx.ScopeDepth, n.TokIdx, ref fctx, ref mir);
        fctx.Terminate(new MirTerm(MirTermKind.Goto, defaultBlk, 0, 0, 0, 0, 0, n.TokIdx));
        PopScopeWithoutEmit(ref fctx);
        RecordSourceSwitchFlow(entryBlk, -1, in sourceTargets, in sourceBodies, ref fctx);
    }

    private static void LowerCondBranch(int condExprId, int trueBlk, int falseBlk, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags, bool hoistOutVarsToParentScope) => LowerCondBranch(condExprId, trueBlk, falseBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope, false);

    private static void LowerCondBranch(
        int condExprId,
        int trueBlk,
        int falseBlk,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        bool hoistOutVarsToParentScope,
        bool allowTopLevelIfGuard)
    {
        int sourceBlock = fctx.CurBlock;
        int owner = fctx.EnclosingOwnerDeclId;
        bool isConstant = TryEvalBoolConstExpr(condExprId, owner, in fctx, in ast, in ta, in names, in bctx, in types, out bool constantValue);
        int prevOverride = fctx.OutVarScopeOverride;
        if (hoistOutVarsToParentScope && fctx.ScopeDepth > 1 && fctx.OutVarScopeOverride < 0)
        {
            fctx.OutVarScopeOverride = fctx.ScopeDepth - 1;
        }
        LowerCondBranchCore(condExprId, trueBlk, falseBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope, allowTopLevelIfGuard);
        fctx.OutVarScopeOverride = prevOverride;
        // Do not use optimized short-circuit edges to establish C# return completeness.
        // Only a constant expression makes a source condition's untaken arm unreachable.
        fctx.SourceBlockTerms[sourceBlock] = isConstant
            ? new MirTerm(MirTermKind.Goto, constantValue ? trueBlk : falseBlk, 0, 0, 0, 0, 0, ast.Nodes[condExprId].TokIdx)
            : new MirTerm(MirTermKind.Branch, -1, trueBlk, falseBlk, 0, 0, 0, ast.Nodes[condExprId].TokIdx);
    }

    private static void LowerCondBranchCore(
        int condExprId,
        int trueBlk,
        int falseBlk,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        bool hoistOutVarsToParentScope,
        bool allowTopLevelIfGuard)
    {
        AstNode n = ast.Nodes[condExprId];

        // `!sub`
        if (n.Kind == AstKind.ExprUnary && n.C == 0 && (TokKind)n.A == TokKind.Bang)
        {
            LowerCondBranch(n.B, falseBlk, trueBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope, allowTopLevelIfGuard);
            return;
        }

        // `a && b`
        if (n.Kind == AstKind.ExprBinary && (TokKind)n.A == TokKind.AmpAmp)
        {
            int midBlk = fctx.NewBlock();
            LowerCondBranch(n.B, midBlk, falseBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope, allowTopLevelIfGuard: false);
            fctx.CurBlock = midBlk;
            LowerCondBranch(n.C, trueBlk, falseBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope, allowTopLevelIfGuard: false);
            return;
        }

        // `a || b`
        if (n.Kind == AstKind.ExprBinary && (TokKind)n.A == TokKind.PipePipe)
        {
            int midBlk = fctx.NewBlock();
            LowerCondBranch(n.B, trueBlk, midBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope, allowTopLevelIfGuard: false);
            fctx.CurBlock = midBlk;
            LowerCondBranch(n.C, trueBlk, falseBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope, allowTopLevelIfGuard: false);
            return;
        }

        // Guard: `res.IsErr(out ok, out err)` or `opt.IsNone(out val)`
        if (n.Kind == AstKind.ExprCall)
        {
            AstNode callee = ast.Nodes[n.A];
            if (callee.Kind == AstKind.ExprMember)
            {
                bool isErrGuard = Bytes.Eq(names.Text(callee.B), "IsErr"u8);
                bool isNoneGuard = Bytes.Eq(names.Text(callee.B), "IsNone"u8);
                if (isErrGuard && n.C == 2)
                {
                    AstNode raw0 = ast.Nodes[ast.Extra[n.B + 0]];
                    AstNode raw1 = ast.Nodes[ast.Extra[n.B + 1]];
                    if (TryMapTwoNamedArgs(in raw0, in raw1, "ok"u8, "err"u8, in names, out int okIdx, out int errIdx))
                    {
                        int resOp = LowerExprAsOperand(callee.A, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                        int resType = mir.Operands[resOp].TypeId;
                        TypeInfo rti = types.Items[resType];
                        if (rti.Kind == TypeKinds.Result)
                        {
                            if (!allowTopLevelIfGuard)
                            {
                                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[n.TokIdx], "'Result.IsErr(out ...)' is only permitted as the direct top-level condition of 'if ([!]...)'."u8);
                            }
                            int okT = rti.A;
                            int errWrapT = types.MakeErrWrap(rti.B);
                            int outScope = hoistOutVarsToParentScope && fctx.ScopeDepth > 1 ? fctx.ScopeDepth - 1 : fctx.ScopeDepth;
                            int okLid;
                            int errLid;
                            if (okIdx == 0)
                            {
                                okLid = BindGuardOutArg(ast.Extra[n.B + okIdx], okT, outScope, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                                errLid = BindGuardOutArg(ast.Extra[n.B + errIdx], errWrapT, outScope, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                            }
                            else
                            {
                                errLid = BindGuardOutArg(ast.Extra[n.B + errIdx], errWrapT, outScope, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                                okLid = BindGuardOutArg(ast.Extra[n.B + okIdx], okT, outScope, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                            }
                            fctx.Terminate(new MirTerm(MirTermKind.GuardResultIsErr, resOp, okLid, errLid, trueBlk, falseBlk, 0, n.TokIdx));
                            return;
                        }
                    }
                }
                if (isNoneGuard && n.C == 1 && CheckSingleNamedArg(ast.Nodes[ast.Extra[n.B + 0]], "value"u8, in names))
                {
                    int optOp = LowerExprAsOperand(callee.A, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    int optType = mir.Operands[optOp].TypeId;
                    TypeInfo oti = types.Items[optType];
                    if (oti.Kind == TypeKinds.Option)
                    {
                        if (!allowTopLevelIfGuard)
                        {
                            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[n.TokIdx], "'Option.IsNone(out ...)' is only permitted as the direct top-level condition of 'if ([!]...)'."u8);
                        }
                        int innerT = oti.A;
                        int outScope = hoistOutVarsToParentScope && fctx.ScopeDepth > 1 ? fctx.ScopeDepth - 1 : fctx.ScopeDepth;
                        int valLid = BindGuardOutArg(ast.Extra[n.B + 0], innerT, outScope, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                        fctx.Terminate(new MirTerm(MirTermKind.GuardOptionIsNone, optOp, valLid, trueBlk, falseBlk, 0, 0, n.TokIdx));
                        return;
                    }
                }
            }
        }

        // Conditional `c ? e1 : e2` in boolean condition context
        if (n.Kind == AstKind.ExprCond)
        {
            int armTrueBlk = fctx.NewBlock();
            int armFalseBlk = fctx.NewBlock();
            LowerCondBranch(n.A, armTrueBlk, armFalseBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope, allowTopLevelIfGuard: false);
            fctx.CurBlock = armTrueBlk;
            LowerCondBranch(n.B, trueBlk, falseBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope, allowTopLevelIfGuard: false);
            fctx.CurBlock = armFalseBlk;
            LowerCondBranch(n.C, trueBlk, falseBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope, allowTopLevelIfGuard: false);
            return;
        }

        // Pattern: `scrutinee is Some<T>(var x)` / `NoneType` / `Ok<T>(var x)` / `Err<E>(var e)`
        if (n.Kind == AstKind.ExprIsPattern)
        {
            LowerIsPatternBranch(n.A, n.B, n.TokIdx, trueBlk, falseBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            return;
        }

        int condOp = LowerExprAsOperand(condExprId, TypeIds.Bool, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        int condCurOwner = fctx.EnclosingOwnerDeclId;
        if (mir.Operands[condOp].Kind != MirOpKinds.BoolConst &&
            TryEvalBoolConstExpr(condExprId, condCurOwner, in fctx, in ast, in ta, in names, in bctx, in types, out bool foldedCondB))
        {
            condOp = mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, foldedCondB ? 1 : 0, TypeIds.Bool, n.TokIdx));
        }
        if (mir.Operands[condOp].Kind == MirOpKinds.BoolConst)
        {
            int target = mir.Operands[condOp].IntVal != 0 ? trueBlk : falseBlk;
            fctx.Terminate(new MirTerm(MirTermKind.Goto, target, 0, 0, 0, 0, 0, n.TokIdx));
            return;
        }
        fctx.Terminate(new MirTerm(MirTermKind.Branch, condOp, trueBlk, falseBlk, 0, 0, 0, n.TokIdx));
    }

    private static int BindGuardOutArg(
        int callArgNodeId,
        int expectedTypeId,
        int targetScopeDepth,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags)
    {
        AstNode arg = ast.Nodes[callArgNodeId];
        if (CallArgBits.Mode(in arg) != PassMode.Out)
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[arg.TokIdx], "Union guard arguments require an explicit 'out' modifier."u8);
        CheckDeclaredOutArgumentType(in arg, expectedTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);

        // `out _` discard
        if (IsDiscardOutArgument(in arg, in fctx, in ast, in names))
        {
            int dLid = fctx.AddLocal(-1, expectedTypeId, PassMode.ByValue, MirLocalFlags.IsTemp, arg.TokIdx);
            InsertScopeEntryAtDepth(ref fctx, targetScopeDepth, dLid, arg.TokIdx);
            return dLid;
        }

        // `out var x` or `out T x`
        if (arg.C == -1 || arg.C >= 0)
        {
            int lid = BindExpressionLocal(arg.D, expectedTypeId, 0, targetScopeDepth, arg.TokIdx, ref fctx, in ast, in ta, in names, ref diags);
            return lid;
        }

        // SPEC §3.5: existing locals or fields/places are banned in `IsErr`/`IsNone` out-guards (`VIB000`)
        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[arg.TokIdx], "Every 'out' argument of 'IsErr'/'IsNone' must be a fresh inline declaration ('out var x') or discard ('out _')."u8);
        int tmp = fctx.AddLocal(-1, expectedTypeId, PassMode.ByValue, MirLocalFlags.IsTemp, arg.TokIdx);
        InsertScopeEntryAtDepth(ref fctx, targetScopeDepth, tmp, arg.TokIdx);
        return tmp;
    }

    private static void InsertVarBindingAtDepth(ref FuncLowerCtx fctx, int depth, int nameId, int localId)
    {
        fctx.LocalScopeDepths[localId] = depth;
        int insertAt = fctx.Vars.Count;
        while (insertAt > 0 && fctx.Vars[insertAt - 1].ScopeDepth > depth)
        {
            insertAt -= 1;
        }
        fctx.Vars.Push(new VarBinding(nameId, localId, depth, 0, TypeIds.Void, 0));
        for (int i = fctx.Vars.Count - 1; i > insertAt; i--)
        {
            fctx.Vars[i] = fctx.Vars[i - 1];
        }
        fctx.Vars[insertAt] = new VarBinding(nameId, localId, depth, 0, TypeIds.Void, 0);
    }

    private static void InsertScopeEntryAtDepth(ref FuncLowerCtx fctx, int depth, int localId, int tokIdx)
    {
        int insertAt = fctx.ScopeStack.Count;
        while (insertAt > 0 && fctx.ScopeStack[insertAt - 1].ScopeDepth > depth)
        {
            insertAt -= 1;
        }
        var entry = new ScopeEntry(depth, localId, 0, -1, tokIdx);
        fctx.ScopeStack.Push(entry);
        for (int i = fctx.ScopeStack.Count - 1; i > insertAt; i--)
        {
            fctx.ScopeStack[i] = fctx.ScopeStack[i - 1];
        }
        fctx.ScopeStack[insertAt] = entry;
    }

    private static void LowerNonUnionPatternBranch(
        int scrutPl,
        int scrutType,
        int patNodeId,
        int tokIdx,
        int matchBlk,
        int failBlk,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        AstNode pattern = ast.Nodes[patNodeId];
        if (types.Items[scrutType].Kind == TypeKinds.TypeParam &&
            pattern.Kind != AstKind.PatWildcard && !(pattern.Kind == AstKind.PatDecl && pattern.A < 0))
        {
            int inputToken = fctx.SourcePatternInputToken >= 0 ? fctx.SourcePatternInputToken : tokIdx;
            RejectGenericPattern(patNodeId, scrutType, inputToken, matchBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            return;
        }
        bool matches = false;
        bool known = fctx.SourceConstantPatternPlace == scrutPl &&
            pattern.Kind != AstKind.PatLogic && pattern.Kind != AstKind.PatNot &&
            TryMatchSourceSwitchConstant(patNodeId, scrutType, fctx.SourceConstantPatternValue, fctx.SourceConstantPatternNaN,
                fctx.EnclosingOwnerDeclId, ref fctx, in ast, in ta, in names, ref bctx, ref types, out matches);
        LowerNonUnionPatternBranchCore(scrutPl, scrutType, patNodeId, tokIdx, matchBlk, failBlk,
            ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        if (known)
        {
            // Override only this atomic test, never a composite entry: pattern
            // bindings in intermediate blocks remain on both source graphs.
            var selected = new MirTerm(MirTermKind.Goto, matches ? matchBlk : failBlk, 0, 0, 0, 0, 0, tokIdx);
            // A strict constant selector and pure atomic test also justify
            // exact runtime folding, so runtime DA sees the same real paths.
            fctx.BlockTerms[fctx.CurBlock] = selected;
            fctx.SourceBlockTerms[fctx.CurBlock] = selected;
            fctx.SourceAssignmentTerms[fctx.CurBlock] = selected;
        }
    }

    private static void LowerNonUnionPatternBranchCore(
        int scrutPl,
        int scrutType,
        int patNodeId,
        int tokIdx,
        int matchBlk,
        int failBlk,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        AstNode pat = ast.Nodes[patNodeId];
        switch (pat.Kind)
        {
            case AstKind.PatWildcard:
                fctx.Terminate(new MirTerm(MirTermKind.Goto, matchBlk, 0, 0, 0, 0, 0, tokIdx));
                return;

            case AstKind.PatDecl:
            {
                if (pat.C != 0)
                {
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[pat.TokIdx], "Type-testing 'is T' expressions are not supported in Vibranium; use pattern matching instead."u8);
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, failBlk, 0, 0, 0, 0, 0, tokIdx));
                    return;
                }
                if (pat.A >= 0)
                {
                    int declType = DeclBinder.ResolveTypeNode(pat.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags);
                    if (declType != TypeIds.Error && scrutType != TypeIds.Error && declType != scrutType)
                    {
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[pat.TokIdx], "Runtime type-testing pattern ('is T') where pattern type differs from scrutinee type is not supported in Vibranium."u8);
                    }
                }
                if (pat.A >= 0 && (scrutType == TypeIds.Str || types.Items[scrutType].Kind == TypeKinds.Class || types.Items[scrutType].Kind == TypeKinds.TypeParam))
                {
                    // Native class values are non-null, but C# source DA must
                    // retain the failed type test before the declaration bind.
                    int bindingBlock = fctx.NewBlock();
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, bindingBlock, 0, 0, 0, 0, 0, tokIdx));
                    fctx.SourceAssignmentTerms[fctx.CurBlock] = new MirTerm(MirTermKind.Branch, -1, bindingBlock, failBlk, 0, 0, 0, tokIdx);
                    fctx.CurBlock = bindingBlock;
                }
                if (pat.B >= 0)
                {
                    int patScope = fctx.OutVarScopeOverride > 0 ? fctx.OutVarScopeOverride : fctx.ScopeDepth;
                    int bindLid = BindExpressionLocal(pat.B, scrutType, 0, patScope, pat.TokIdx, ref fctx, in ast, in ta, in names, ref diags);
                    int sOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, scrutPl, 0, scrutType, pat.TokIdx));
                    fctx.LocalInitializerInsts[bindLid] = fctx.StagedInsts.Count;
                    fctx.Emit(new MirInst(MirOp.AssignUse, mir.AddPlaceLocal(bindLid, scrutType), -1, 0, scrutType, sOp, 0, 0, 0, pat.TokIdx));
                }
                fctx.Terminate(new MirTerm(MirTermKind.Goto, matchBlk, 0, 0, 0, 0, 0, tokIdx));
                return;
            }

            case AstKind.PatConst:
            {
                int diagBeforePatConst = diags.Items.Count;
                if (TryResolveStaticTypeTarget(pat.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out int barePatTid))
                {
                    if (diags.Items.Count > diagBeforePatConst)
                    {
                        fctx.Terminate(new MirTerm(MirTermKind.Goto, failBlk, 0, 0, 0, 0, 0, tokIdx));
                        return;
                    }
                    if (pat.B != 0)
                    {
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[pat.TokIdx], "Type-testing 'is T' expressions are not supported in Vibranium; use pattern matching instead."u8);
                        fctx.Terminate(new MirTerm(MirTermKind.Goto, failBlk, 0, 0, 0, 0, 0, tokIdx));
                        return;
                    }
                    if (barePatTid >= 0 && barePatTid == scrutType)
                    {
                        fctx.Terminate(new MirTerm(MirTermKind.Goto, matchBlk, 0, 0, 0, 0, 0, tokIdx));
                        if (scrutType == TypeIds.Str || types.Items[scrutType].Kind == TypeKinds.Class || types.Items[scrutType].Kind == TypeKinds.TypeParam)
                            fctx.SourceAssignmentTerms[fctx.CurBlock] = new MirTerm(MirTermKind.Branch, -1, matchBlk, failBlk, 0, 0, 0, tokIdx);
                        return;
                    }
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[pat.TokIdx], "Runtime type-testing pattern ('is T') where pattern type differs from scrutinee type is not supported in Vibranium."u8);
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, failBlk, 0, 0, 0, 0, 0, tokIdx));
                    return;
                }
                int patConstT = InferExprType(pat.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (scrutType == TypeIds.Str || patConstT == TypeIds.Str)
                {
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[pat.TokIdx], "Constant 'string' pattern matching is banned in Vibranium; compare UTF-8 bytes via '.AsUtf8()' instead."u8);
                    int falseOp = mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, 0, TypeIds.Bool, pat.TokIdx));
                    fctx.Terminate(new MirTerm(MirTermKind.Branch, falseOp, matchBlk, failBlk, 0, 0, 0, pat.TokIdx));
                    return;
                }
                CheckSourcePatternConstant(pat.A, pat.TokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref diags);
                int sOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, scrutPl, 0, scrutType, pat.TokIdx));
                int diagBeforeConstOp = diags.Items.Count;
                int cOp = LowerExprAsOperand(pat.A, scrutType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                bool isNaNConst = false;
                if (scrutType == TypeIds.F64 || scrutType == TypeIds.F32)
                {
                    MirOperand cOperand = mir.Operands[cOp];
                    if (cOperand.Kind == MirOpKinds.FloatConst && cOperand.PlaceOrLitIdx < 0)
                    {
                        if (scrutType == TypeIds.F64)
                        {
                            ulong bits = (ulong)cOperand.IntVal;
                            isNaNConst = (bits & 0x7FF0000000000000UL) == 0x7FF0000000000000UL &&
                                         (bits & 0x000FFFFFFFFFFFFFUL) != 0UL;
                        }
                        else
                        {
                            uint fbits = (uint)cOperand.IntVal;
                            isNaNConst = (fbits & 0x7F800000U) == 0x7F800000U &&
                                         (fbits & 0x007FFFFFU) != 0U;
                        }
                    }
                    else if (diags.Items.Count == diagBeforeConstOp)
                    {
                        int curOwnerPat = fctx.EnclosingOwnerDeclId;
                        if (TryEvalFloatConstOrIntAsFloat(pat.A, curOwnerPat, in fctx, in ast, in ta, in names, in bctx, in types, out _, out double patD))
                        {
                            double copyD = patD;
                            isNaNConst = patD != copyD;
                        }
                    }
                }
                if (isNaNConst)
                {
                    int tTmp = fctx.NewTemp(scrutType, pat.TokIdx, ref mir);
                    int tPl = mir.AddPlaceLocal(tTmp, scrutType);
                    fctx.Emit(new MirInst(MirOp.AssignUse, tPl, -1, 0, scrutType, sOp, 0, 0, 0, pat.TokIdx));
                    int tOp1 = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, tPl, 0, scrutType, pat.TokIdx));
                    int tOp2 = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, tPl, 0, scrutType, pat.TokIdx));
                    int eqTmp = fctx.NewTemp(TypeIds.Bool, pat.TokIdx, ref mir);
                    int eqPl = mir.AddPlaceLocal(eqTmp, TypeIds.Bool);
                    fctx.Emit(new MirInst(MirOp.AssignBin, eqPl, -1, 0, TypeIds.Bool, (int)MirBinOp.Eq, tOp1, tOp2, 0, pat.TokIdx));
                    int eqOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, eqPl, 0, TypeIds.Bool, pat.TokIdx));
                    int notTmp = fctx.NewTemp(TypeIds.Bool, pat.TokIdx, ref mir);
                    int notPl = mir.AddPlaceLocal(notTmp, TypeIds.Bool);
                    fctx.Emit(new MirInst(MirOp.AssignUn, notPl, -1, 0, TypeIds.Bool, (int)MirUnOp.Not, eqOp, 0, 0, pat.TokIdx));
                    int notOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, notPl, 0, TypeIds.Bool, pat.TokIdx));
                    fctx.Terminate(new MirTerm(MirTermKind.Branch, notOp, matchBlk, failBlk, 0, 0, 0, pat.TokIdx));
                    return;
                }
                int cmpTmp = fctx.NewTemp(TypeIds.Bool, pat.TokIdx, ref mir);
                int cmpPl = mir.AddPlaceLocal(cmpTmp, TypeIds.Bool);
                fctx.Emit(new MirInst(MirOp.AssignBin, cmpPl, -1, 0, TypeIds.Bool, (int)MirBinOp.Eq, sOp, cOp, 0, pat.TokIdx));
                int cmpOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, cmpPl, 0, TypeIds.Bool, pat.TokIdx));
                fctx.Terminate(new MirTerm(MirTermKind.Branch, cmpOp, matchBlk, failBlk, 0, 0, 0, pat.TokIdx));
                return;
            }

            case AstKind.PatRel:
            {
                CheckSourcePatternConstant(pat.B, pat.TokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref diags);
                int sOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, scrutPl, 0, scrutType, pat.TokIdx));
                int bOp = LowerExprAsOperand(pat.B, scrutType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                MirBinOp relOp = MapBinOp((TokKind)pat.A);
                int cmpTmp = fctx.NewTemp(TypeIds.Bool, pat.TokIdx, ref mir);
                int cmpPl = mir.AddPlaceLocal(cmpTmp, TypeIds.Bool);
                fctx.Emit(new MirInst(MirOp.AssignBin, cmpPl, -1, 0, TypeIds.Bool, (int)relOp, sOp, bOp, 0, pat.TokIdx));
                int cmpOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, cmpPl, 0, TypeIds.Bool, pat.TokIdx));
                fctx.Terminate(new MirTerm(MirTermKind.Branch, cmpOp, matchBlk, failBlk, 0, 0, 0, pat.TokIdx));
                return;
            }

            case AstKind.PatNot:
            {
                CheckNoPatternDeclarations(pat.A, in ast, in ta, in names, ref diags);
                AstNode innerNot = ast.Nodes[pat.A];
                if (innerNot.Kind == AstKind.PatWildcard || (innerNot.Kind == AstKind.PatDecl && innerNot.C == 0))
                {
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[pat.TokIdx], "An expression can never match a negated irrefutable pattern (CS8518)."u8);
                }
                int savedVars = fctx.Vars.Count;
                LowerPatternOnPlaceBranch(scrutPl, scrutType, pat.A, pat.TokIdx, failBlk, matchBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, parentIsBorrowed: true, parentIsShared: true);
                fctx.Vars.Truncate(savedVars);
                return;
            }

            case AstKind.PatLogic:
            {
                int midBlk = fctx.NewBlock();
                if (pat.A == 0) // `and`
                {
                    LowerPatternOnPlaceBranch(scrutPl, scrutType, pat.B, pat.TokIdx, midBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, parentIsBorrowed: true, parentIsShared: true);
                    fctx.CurBlock = midBlk;
                    LowerPatternOnPlaceBranch(scrutPl, scrutType, pat.C, pat.TokIdx, matchBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, parentIsBorrowed: true, parentIsShared: true);
                }
                else // `or`
                {
                    CheckNoPatternDeclarations(pat.B, in ast, in ta, in names, ref diags);
                    CheckNoPatternDeclarations(pat.C, in ast, in ta, in names, ref diags);
                    int savedOrVars = fctx.Vars.Count;
                    LowerPatternOnPlaceBranch(scrutPl, scrutType, pat.B, pat.TokIdx, matchBlk, midBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, parentIsBorrowed: true, parentIsShared: true);
                    fctx.Vars.Truncate(savedOrVars);
                    fctx.CurBlock = midBlk;
                    LowerPatternOnPlaceBranch(scrutPl, scrutType, pat.C, pat.TokIdx, matchBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, parentIsBorrowed: true, parentIsShared: true);
                    fctx.Vars.Truncate(savedOrVars);
                }
                return;
            }

            default:
                diags.ReportTok(types.IsLinear(scrutType, in ast) ? VibCodes.LinearViolation : VibCodes.Unsupported, ta.Tokens[pat.TokIdx], "Unsupported pattern in Vibranium."u8);
                fctx.Terminate(new MirTerm(MirTermKind.Goto, failBlk, 0, 0, 0, 0, 0, tokIdx));
                return;
        }
    }

    private static bool ContainsUnionPattern(int patNodeId, in AstArena ast)
    {
        if (patNodeId < 0) return false;
        AstNode p = ast.Nodes[patNodeId];
        if (p.Kind == AstKind.PatUnion) return true;
        if (p.Kind == AstKind.PatNot) return ContainsUnionPattern(p.A, in ast);
        if (p.Kind == AstKind.PatLogic) return ContainsUnionPattern(p.B, in ast) || ContainsUnionPattern(p.C, in ast);
        return false;
    }

    // C# 15 applies a pattern on a union value (Option/OptionRef/OptionMut/
    // Result) to its case types (Some<T>/NoneType, Ok<T>/Err<E>). A type or
    // declaration pattern of any other type, the union's own type included
    // (`case Option<T> o:`, `x is int i`), is CS8121, also on a payload that is
    // itself a union (`Some<Option<int>>(Option<int> inner)`). `var`, `_` and
    // variant patterns are fine. Types resolve into a scratch bag, so lowering
    // still reports their own diagnostics once.
    private static void CheckUnionTypePatterns(int patId, int inputType,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        if (patId < 0 || inputType < 0 || !IsUnionType(inputType, in types)) return;
        AstNode pat = ast.Nodes[patId];
        int patternType = -1;
        if (pat.Kind == AstKind.PatDecl && pat.A >= 0)
        {
            var scratch = new DiagnosticBag(0);
            patternType = DeclBinder.ResolveTypeNode(pat.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref scratch);
        }
        else if (pat.Kind == AstKind.PatConst)
        {
            var scratch = new DiagnosticBag(0);
            if (!TryResolveStaticTypeTarget(pat.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref scratch, out _, out patternType)) patternType = -1;
        }
        else if (pat.Kind == AstKind.PatNot)
        {
            CheckUnionTypePatterns(pat.A, inputType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            return;
        }
        else if (pat.Kind == AstKind.PatLogic)
        {
            CheckUnionTypePatterns(pat.B, inputType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            CheckUnionTypePatterns(pat.C, inputType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            return;
        }
        else if (pat.Kind == AstKind.PatUnion)
        {
            if (pat.D < 0) return;
            TypeInfo ui = types.Items[inputType];
            int head = ast.Nodes[pat.A].A;
            int payloadType = -1;
            if (head == bctx.IdSome && ui.Kind != TypeKinds.Result) payloadType = ui.A;
            else if (head == bctx.IdOk && ui.Kind == TypeKinds.Result) payloadType = ui.A;
            else if (head == bctx.IdErr && ui.Kind == TypeKinds.Result) payloadType = ui.B;
            if (payloadType >= 0) CheckUnionTypePatterns(pat.D, payloadType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            return;
        }
        if (patternType < 0 || patternType == TypeIds.Error || patternType == TypeIds.NoneUnit) return;
        int patternKind = types.Items[patternType].Kind;
        if (patternKind == TypeKinds.SomeWrap || patternKind == TypeKinds.OkWrap || patternKind == TypeKinds.ErrWrap) return;
        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[pat.TokIdx], "A union value is matched by its case types (Some<T>/NoneType, Ok<T>/Err<E>); a type pattern of another type, the union type included, cannot handle it (CS8121)."u8);
    }

    private static bool IsUnionScrutineeKind(int kind)
    {
        return kind == TypeKinds.Option || kind == TypeKinds.OptionRef || kind == TypeKinds.OptionMut || kind == TypeKinds.Result;
    }

    // A switch statement or expression over a linear Option<R>/Result<R, E>
    // whose scrutinee is a value (a call, Move(o), ...), not a place, may test
    // each variant in at most one arm, without a `when` guard, and may not use
    // `not` or `or` patterns. Each offending arm gets one VIB006 at the first
    // token of its pattern: a guarded variant arm; a variant arm whose variant
    // an earlier arm already tested (every variant arm records its variant,
    // guarded or not); a `not`/`or` arm. `var`, `_` (guarded or not),
    // `default` and other patterns keep their existing rules. A variant arm
    // with a nested subpattern keeps only its nested-subpattern VIB006. Place
    // scrutinees keep the in-place VIB006 instead.
    private static void CheckLinearUnionSwitchArms(in AstNode n, bool isExpr, int scrutType, TypeInfo sti,
        bool isPlace, in AstArena ast, in TokenArena ta, in BinderCtx bctx, in TypeTable types, ref DiagnosticBag diags)
    {
        if (sti.Kind != TypeKinds.Option && sti.Kind != TypeKinds.Result) return;
        if (!types.IsLinear(scrutType, in ast)) return;
        if (isPlace) return;
        int firstSeen = 0;
        int secondSeen = 0;
        if (isExpr)
        {
            for (int i = 0; i < n.C; i++)
            {
                AstNode arm = ast.Nodes[ast.Extra[n.B + i]];
                CheckLinearUnionSwitchArm(arm.A, arm.C, arm.TokIdx, sti, in ast, in ta, in bctx, ref firstSeen, ref secondSeen, ref diags);
            }
            return;
        }
        for (int i = 0; i < n.C; i++)
        {
            AstNode sec = ast.Nodes[ast.Extra[n.B + i]];
            for (int l = 0; l < sec.B; l++)
            {
                AstNode lbl = ast.Nodes[ast.Extra[sec.A + l]];
                if (lbl.A < 0) continue; // default:
                CheckLinearUnionSwitchArm(lbl.A, lbl.B, lbl.TokIdx, sti, in ast, in ta, in bctx, ref firstSeen, ref secondSeen, ref diags);
            }
        }
    }

    private static void CheckLinearUnionSwitchArm(int patId, int whenId, int anchorTok, TypeInfo sti,
        in AstArena ast, in TokenArena ta, in BinderCtx bctx, ref int firstSeen, ref int secondSeen, ref DiagnosticBag diags)
    {
        if (patId < 0) return;
        AstNode pat = ast.Nodes[patId];
        bool offending = false;
        if (pat.Kind == AstKind.PatUnion)
        {
            offending = whenId >= 0;
            int head = ast.Nodes[pat.A].A;
            bool isFirst = (sti.Kind == TypeKinds.Result) ? (head == bctx.IdOk) : (head == bctx.IdSome);
            if (isFirst)
            {
                firstSeen += 1;
                if (firstSeen > 1) offending = true;
            }
            else
            {
                secondSeen += 1;
                if (secondSeen > 1) offending = true;
            }
            if (pat.C != 0) return;
            if (pat.D >= 0)
            {
                AstKind subKind = ast.Nodes[pat.D].Kind;
                if (subKind != AstKind.PatWildcard && subKind != AstKind.PatDecl) return;
            }
        }
        else if (pat.Kind == AstKind.PatNot || (pat.Kind == AstKind.PatLogic && pat.A == 1))
        {
            offending = true;
        }
        if (offending)
        {
            diags.ReportTok(VibCodes.LinearViolation, ta.Tokens[anchorTok], "A switch over a linear union value may test each variant in at most one arm, without a 'when' guard, and may not use 'not' or 'or' patterns; branch inside the arm instead."u8);
        }
    }

    private static void RejectGenericPattern(int patId, int inputType, int inputToken, int matchBlock,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names,
        ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags)
    {
        fctx.HasGenericPatternCut = true;
        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[inputToken], "Patterns other than var and discard on a value of generic type parameter type are not supported in Vibranium v0.2."u8);
        // This source construct has no MIR semantics in v0.2. Seed only its
        // lexical declarations for recovery, instead of converting/moving T or
        // hiding canonical diagnostics with a post-lowering diagnostic filter.
        BindRejectedGenericPattern(patId, inputType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        fctx.Terminate(new MirTerm(MirTermKind.Goto, matchBlock, 0, 0, 0, 0, 0, inputToken));
    }

    private static void BindRejectedGenericPattern(int patId, int inputType,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names,
        ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags)
    {
        if (patId < 0) return;
        AstNode pat = ast.Nodes[patId];
        if (pat.Kind == AstKind.PatDecl && pat.B >= 0)
        {
            int bindType = pat.A >= 0
                ? DeclBinder.ResolveTypeNode(pat.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags)
                : inputType;
            int scope = fctx.OutVarScopeOverride > 0 ? fctx.OutVarScopeOverride : fctx.ScopeDepth;
            int local = BindExpressionLocal(pat.B, bindType, 0, scope, pat.TokIdx, ref fctx, in ast, in ta, in names, ref diags);
            int operand = mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, bindType, pat.TokIdx));
            fctx.LocalInitializerInsts[local] = fctx.StagedInsts.Count;
            fctx.Emit(new MirInst(MirOp.AssignUse, mir.AddPlaceLocal(local, bindType), -1, 0, bindType, operand, 0, 0, 0, pat.TokIdx));
        }
        else if (pat.Kind == AstKind.PatLogic)
        {
            BindRejectedGenericPattern(pat.B, inputType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            BindRejectedGenericPattern(pat.C, inputType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }
        else if (pat.Kind == AstKind.PatNot)
            BindRejectedGenericPattern(pat.A, inputType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        else if (pat.Kind == AstKind.PatUnion && pat.D >= 0)
        {
            int unionType = DeclBinder.ResolveTypeNode(pat.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags);
            TypeInfo union = types.Items[unionType];
            int payload = union.Kind == TypeKinds.SomeWrap || union.Kind == TypeKinds.OkWrap || union.Kind == TypeKinds.ErrWrap ? union.A : inputType;
            BindRejectedGenericPattern(pat.D, payload, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }
    }

    private static void CheckSourcePatternConstant(int exprId, int tokIdx, ref FuncLowerCtx fctx,
        in AstArena ast, in TokenArena ta, in Interner names, in BinderCtx bctx, in TypeTable types, ref DiagnosticBag diags)
    {
        int owner = fctx.EnclosingOwnerDeclId;
        if (TryEvalBoolConstExpr(exprId, owner, in fctx, in ast, in ta, in names, in bctx, in types, out _) ||
            TryEvalTypedIntConstExpr(exprId, owner, in fctx, in ast, in ta, in names, in bctx, in types, out _, out _) ||
            TryEvalFloatConstOrIntAsFloat(exprId, owner, in fctx, in ast, in ta, in names, in bctx, in types, out _, out _)) return;
        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A constant value is expected in a pattern (CS9135)."u8);
    }

    private static void EvaluateNominalPatternMustMay(int patId, int scrutType, bool nonNull,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names,
        ref BinderCtx bctx, ref TypeTable types, out bool must, out bool may)
    {
        must = false;
        may = true;
        if (patId < 0) return;
        AstNode pat = ast.Nodes[patId];
        if (pat.Kind == AstKind.PatWildcard || (pat.Kind == AstKind.PatDecl && pat.A < 0))
        {
            must = true;
            return;
        }
        if (pat.Kind == AstKind.PatNot)
        {
            EvaluateNominalPatternMustMay(pat.A, scrutType, nonNull, ref fctx, in ast, in ta, in names, ref bctx, ref types, out bool sm, out bool sy);
            must = !sy;
            may = !sm;
            return;
        }
        if (pat.Kind == AstKind.PatLogic)
        {
            EvaluateNominalPatternMustMay(pat.B, scrutType, nonNull, ref fctx, in ast, in ta, in names, ref bctx, ref types, out bool lm, out bool ly);
            EvaluateNominalPatternMustMay(pat.C, scrutType, nonNull, ref fctx, in ast, in ta, in names, ref bctx, ref types, out bool rm, out bool ry);
            bool and = pat.A == 0;
            must = and ? lm && rm : lm || rm;
            may = and ? ly && ry : ly || ry;
            return;
        }
        var discarded = new DiagnosticBag(0);
        int target = -1;
        if (pat.Kind == AstKind.PatDecl && pat.A >= 0)
            target = DeclBinder.ResolveTypeNode(pat.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref discarded, reportLinearErrors: false);
        else if (pat.Kind == AstKind.PatConst)
            _ = TryResolveStaticTypeTarget(pat.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref discarded, out _, out target);
        if (discarded.Items.Count != 0 || target < 0 || target == TypeIds.Error) return;
        if (types.Items[scrutType].Kind == TypeKinds.TypeParam || types.Items[target].Kind == TypeKinds.TypeParam) return;
        must = nonNull && target == scrutType;
        may = must;
    }

    private static void LowerIsPatternBranch(
        int scrutExprId, int patNodeId, int tokIdx, int matchBlk, int failBlk,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names,
        ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags)
    {
        int scrutType = InferExprType(scrutExprId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        CheckUnionTypePatterns(patNodeId, scrutType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        AstNode pat = ast.Nodes[patNodeId];
        if (types.Items[scrutType].Kind == TypeKinds.TypeParam &&
            pat.Kind != AstKind.PatWildcard && !(pat.Kind == AstKind.PatDecl && pat.A < 0))
        {
            RejectGenericPattern(patNodeId, scrutType, ast.Nodes[scrutExprId].TokIdx, matchBlk,
                ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            return;
        }
        bool scalar = scrutType == TypeIds.Bool || types.IsInteger(scrutType) || types.IsFloat(scrutType);
        bool impossible = false;
        bool full = false;
        if (scalar)
        {
            var covered = new Vec<UInterval>();
            int flags = 0;
            impossible = AccumulateSourcePayloadCoverage(patNodeId, scrutType, true, ref covered, ref flags,
                ref fctx, in ast, in ta, in names, ref bctx, ref types);
            full = (flags & 8) != 0;
        }
        else if (!ContainsUnionPattern(patNodeId, in ast))
        {
            EvaluateNominalPatternMustMay(patNodeId, scrutType, true, ref fctx, in ast, in ta, in names, ref bctx, ref types, out bool mustNonNull, out bool mayNonNull);
            bool nullable = scrutType == TypeIds.Str || types.Items[scrutType].Kind == TypeKinds.Class || types.Items[scrutType].Kind == TypeKinds.TypeParam;
            EvaluateNominalPatternMustMay(patNodeId, scrutType, !nullable, ref fctx, in ast, in ta, in names, ref bctx, ref types, out bool mustNull, out bool mayNull);
            impossible = !mayNonNull && !mayNull;
            full = mustNonNull && mustNull;
        }
        bool constantMatches = false;
        bool constantKnown = false;
        if (TryGetSourceSwitchConstant(scrutExprId, scrutType, fctx.EnclosingOwnerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out ulong value, out bool isNaN))
            constantKnown = TryMatchSourceSwitchConstant(patNodeId, scrutType, value, isNaN, fctx.EnclosingOwnerDeclId, ref fctx, in ast, in ta, in names, ref bctx, ref types, out constantMatches);
        bool classic = pat.Kind == AstKind.PatDecl && pat.C != 0;
        if (pat.Kind == AstKind.PatConst && pat.B != 0)
        {
            // The parser marks identifiers/member access provisionally: a
            // named constant (including float.NaN) is not a classic type test.
            var discarded = new DiagnosticBag(0);
            classic = TryResolveStaticTypeTarget(pat.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref discarded, out _, out _);
        }
        bool declaration = pat.Kind == AstKind.PatDecl && (pat.A < 0 || pat.B >= 0 || pat.D != 0);
        if (fctx.CheckSourcePatternWarnings)
        {
            if (classic)
            {
                var discarded = new DiagnosticBag(0);
                int target = -1;
                if (pat.Kind == AstKind.PatDecl) target = DeclBinder.ResolveTypeNode(pat.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref discarded, reportLinearErrors: false);
                else _ = TryResolveStaticTypeTarget(pat.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref discarded, out _, out target);
                if (discarded.Items.Count == 0 && target >= 0 && target != TypeIds.Error &&
                    types.Items[scrutType].Kind != TypeKinds.TypeParam && types.Items[target].Kind != TypeKinds.TypeParam)
                {
                    if (target != scrutType)
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[scrutExprId].TokIdx], "C# warning CS0184 is not permitted in Vibranium: The given expression is never of the provided type."u8);
                    else if ((scrutType != TypeIds.Str && types.Items[scrutType].Kind != TypeKinds.Class) || ast.Nodes[scrutExprId].Kind == AstKind.ExprStrLit)
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[scrutExprId].TokIdx], "C# warning CS0183 is not permitted in Vibranium: The given expression is always of the provided type."u8);
                }
            }
            else if (impossible)
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[scrutExprId].TokIdx], "An expression of this type can never match the provided pattern (CS8518)."u8);
            else if (full && !declaration && pat.Kind != AstKind.PatWildcard)
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[scrutExprId].TokIdx], "C# warning CS8794 is not permitted in Vibranium: An expression of this type always matches the provided pattern."u8);
            else if (!full && constantKnown)
            {
                if (!constantMatches)
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[scrutExprId].TokIdx], "C# warning CS8519 is not permitted in Vibranium: The given expression never matches the provided pattern."u8);
                else if (pat.Kind == AstKind.PatConst)
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[scrutExprId].TokIdx], "C# warning CS8520 is not permitted in Vibranium: The given expression always matches the provided constant."u8);
                else if (!declaration)
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[scrutExprId].TokIdx], "C# warning CS8793 is not permitted in Vibranium: The given expression always matches the provided pattern."u8);
            }
        }
        int sourceBlock = fctx.CurBlock;
        bool known = !classic && (impossible || full || constantKnown);
        bool matches = !impossible && (full || constantMatches);
        int dead = known ? fctx.NewBlock() : -1;
        if (known) fctx.BlockTerms[dead] = new MirTerm(MirTermKind.Unreachable, 0, 0, 0, 0, 0, 0, tokIdx);
        int savedInputToken = fctx.SourcePatternInputToken;
        fctx.SourcePatternInputToken = ast.Nodes[scrutExprId].TokIdx;
        LowerIsPatternBranchCore(scrutExprId, patNodeId, tokIdx, known && !matches ? dead : matchBlk, known && matches ? dead : failBlk,
            ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        fctx.SourcePatternInputToken = savedInputToken;
        // The source endpoint graph must retain both edges: `is` is not a C#
        // constant expression. DA/runtime keep intermediate pattern bindings.
        fctx.SourceBlockTerms[sourceBlock] = new MirTerm(MirTermKind.Branch, -1, matchBlk, failBlk, 0, 0, 0, tokIdx);
    }

    private static void LowerIsPatternBranchCore(
        int scrutExprId,
        int patNodeId,
        int tokIdx,
        int matchBlk,
        int failBlk,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        bool invertTopNot = false;
        int outerNotTokIdx = tokIdx;
        while (ast.Nodes[patNodeId].Kind == AstKind.PatNot)
        {
            if (!invertTopNot) outerNotTokIdx = ast.Nodes[patNodeId].TokIdx;
            invertTopNot = !invertTopNot;
            patNodeId = ast.Nodes[patNodeId].A;
        }
        if (invertTopNot)
        {
            int tmpBlk = matchBlk;
            matchBlk = failBlk;
            failBlk = tmpBlk;
        }
        AstNode pat = ast.Nodes[patNodeId];
        if (invertTopNot && (pat.Kind == AstKind.PatWildcard || (pat.Kind == AstKind.PatDecl && pat.C == 0)))
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[outerNotTokIdx], "An expression can never match a negated irrefutable pattern (CS8518)."u8);
        }
        if (pat.Kind != AstKind.PatUnion)
        {
            if (ContainsUnionPattern(patNodeId, in ast))
            {
                int uScrutType = InferExprType(scrutExprId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                TypeInfo uSti = types.Items[uScrutType];
                if (IsPlaceExpression(scrutExprId, in ast, in fctx, in types) &&
                    (uSti.Kind == TypeKinds.Option || uSti.Kind == TypeKinds.OptionRef || uSti.Kind == TypeKinds.OptionMut || uSti.Kind == TypeKinds.Result))
                {
                    if (types.IsLinear(uScrutType, in ast))
                    {
                        diags.ReportTok(VibCodes.LinearViolation, ta.Tokens[pat.TokIdx], "Pattern matching on a linear union place without moving it is banned in Vibranium."u8);
                    }
                    int uPl = LowerPlace(scrutExprId, isMut: false, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    LowerPatternOnPlaceBranch(uPl, uScrutType, patNodeId, tokIdx, matchBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    return;
                }
            }
            int sOp = LowerExprAsOperand(scrutExprId, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int sType = mir.Operands[sOp].TypeId;
            int sTmp = fctx.NewTemp(sType, tokIdx, ref mir);
            int sPl = mir.AddPlaceLocal(sTmp, sType);
            fctx.Emit(new MirInst(MirOp.AssignUse, sPl, -1, 0, sType, sOp, 0, 0, 0, tokIdx));
            LowerNonUnionPatternBranch(sPl, sType, patNodeId, tokIdx, matchBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            return;
        }

        // PatUnion
        AstNode uTypeNode = ast.Nodes[pat.A];
        int headNameId = uTypeNode.A;

        int scrutType = InferExprType(scrutExprId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        TypeInfo sti = types.Items[scrutType];

        bool isPlaceExpr = IsPlaceExpression(scrutExprId, in ast, in fctx, in types);
        int termFlags = 0;
        int scrutPlaceOrOp;

        if (isPlaceExpr && (sti.Kind == TypeKinds.Option || sti.Kind == TypeKinds.OptionRef || sti.Kind == TypeKinds.OptionMut || sti.Kind == TypeKinds.Result))
        {
            if (types.IsLinear(scrutType, in ast))
            {
                diags.ReportTok(VibCodes.LinearViolation, ta.Tokens[pat.TokIdx], "Pattern matching on a linear union place without moving it is banned in Vibranium."u8);
            }
            bool mutCur = sti.Kind == TypeKinds.OptionMut;
            scrutPlaceOrOp = LowerPlace(scrutExprId, isMut: false, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            termFlags = 1 | (mutCur ? 2 : 0) | ((sti.Kind == TypeKinds.OptionRef || sti.Kind == TypeKinds.OptionMut) ? 4 : 0);
        }
        else
        {
            scrutPlaceOrOp = LowerExprAsOperand(scrutExprId, scrutType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            if (sti.Kind == TypeKinds.OptionRef || sti.Kind == TypeKinds.OptionMut)
            {
                termFlags = 4 | (sti.Kind == TypeKinds.OptionMut ? 2 : 0);
            }
        }

        bool isBorrowed = isPlaceExpr || sti.Kind == TypeKinds.OptionRef || sti.Kind == TypeKinds.OptionMut;
        bool isShared = (isPlaceExpr && sti.Kind != TypeKinds.OptionMut) || sti.Kind == TypeKinds.OptionRef;
        EmitUnionPatternMatchCore(scrutPlaceOrOp, scrutType, sti, termFlags, isBorrowed, isShared, in pat, headNameId, tokIdx, matchBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
    }

    private static void UnpackPatUnion(
        in AstNode pat,
        int payloadTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        out int directPayloadBindNameId,
        out int wrapperBindNameId,
        out int extraSubPatId)
    {
        // The pattern's written generic type is source semantics, not merely
        // a variant tag. Resolve all arguments before inspecting the payload.
        int patternType = DeclBinder.ResolveTypeNode(pat.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags);
        TypeInfo patternInfo = types.Items[patternType];
        if ((patternInfo.Kind == TypeKinds.SomeWrap || patternInfo.Kind == TypeKinds.OkWrap || patternInfo.Kind == TypeKinds.ErrWrap) &&
            patternInfo.A != TypeIds.Error && payloadTypeId != TypeIds.Error && patternInfo.A != payloadTypeId)
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[pat.TokIdx], "Union pattern type arguments must match the scrutinee payload type."u8);
        wrapperBindNameId = pat.B;
        directPayloadBindNameId = -1;
        extraSubPatId = -1;
        if (pat.D < 0) return;

        AstNode sub = ast.Nodes[pat.D];
        if (sub.Kind == AstKind.PatWildcard)
        {
            return;
        }
        if (sub.Kind == AstKind.PatDecl)
        {
            if (sub.A >= 0)
            {
                int declT = DeclBinder.ResolveTypeNode(sub.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (declT != TypeIds.Error && payloadTypeId > 0 && payloadTypeId != TypeIds.Error && declT != payloadTypeId)
                {
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[sub.TokIdx], "Runtime type-testing pattern ('is T') where pattern type differs from scrutinee type is not supported in Vibranium."u8);
                }
            }
            directPayloadBindNameId = sub.B;
            return;
        }
        extraSubPatId = pat.D;
    }

    private static void EmitUnionWrapperBind(
        int wrapperNameId,
        int headNameId,
        int payloadLid,
        int payloadTypeId,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        if (wrapperNameId < 0) return;
        int patScope = fctx.OutVarScopeOverride > 0 ? fctx.OutVarScopeOverride : fctx.ScopeDepth;
        int wrapType;
        MirOp wrapOp;
        if (headNameId == bctx.IdSome)
        {
            wrapType = types.MakeSomeWrap(payloadTypeId);
            wrapOp = MirOp.MakeSomeWrap;
        }
        else if (headNameId == bctx.IdOk)
        {
            wrapType = types.MakeOkWrap(payloadTypeId);
            wrapOp = MirOp.MakeOkWrap;
        }
        else if (headNameId == bctx.IdErr)
        {
            wrapType = types.MakeErrWrap(payloadTypeId);
            wrapOp = MirOp.MakeErrWrap;
        }
        else
        {
            wrapType = TypeIds.NoneUnit;
            wrapOp = MirOp.AssignUse;
        }
        int wLid = BindExpressionLocal(wrapperNameId, wrapType, MirLocalFlags.IsPatternBind, patScope, tokIdx, ref fctx, in ast, in ta, in names, ref diags);
        int wPl = mir.AddPlaceLocal(wLid, wrapType);
        if (wrapOp == MirOp.AssignUse)
        {
            int zOp = mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, wrapType, tokIdx));
            fctx.Emit(new MirInst(MirOp.AssignUse, wPl, -1, 0, wrapType, zOp, 0, 0, 0, tokIdx));
        }
        else
        {
            int pPl = mir.AddPlaceLocal(payloadLid, payloadTypeId);
            int pOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pPl, 0, payloadTypeId, tokIdx));
            fctx.Emit(new MirInst(wrapOp, wPl, -1, 0, payloadTypeId, pOp, 0, 0, 0, tokIdx));
        }
    }

    // A guarded wrapper-designation arm (`Some<T> s when g`, `Ok<T> s when g`,
    // `Err<E> s when g`) over a value scrutinee would move a non-Copy payload
    // into its wrapper before the guard runs, while a later arm still tests the
    // scrutinee. Stage-0 rejects that move out of the shared match temporary
    // (VIB005 at the arm's pattern); over a linear union the N20 ban already
    // rejects the guarded arm. The arm is rejected either way, so its wrapper
    // is bound from a placeholder instead of the payload, and later arms report
    // no use-after-move cascade.
    private static bool IsRejectedGuardedWrapperMove(int wrapNameId, int headNameId, int guardId, int payloadLid, int payloadType,
        bool isBorrowed, bool laterTest, in AstArena ast, in BinderCtx bctx, in TypeTable types)
    {
        if (wrapNameId < 0 || guardId < 0 || payloadLid < 0 || isBorrowed || !laterTest) return false;
        if (headNameId != bctx.IdSome && headNameId != bctx.IdOk && headNameId != bctx.IdErr) return false;
        return !types.IsCopy(payloadType, in ast);
    }

    private static void EmitRejectedGuardedWrapperBind(int wrapperNameId, int headNameId, int payloadTypeId, TypeInfo sti, int tokIdx,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, in BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags)
    {
        int outerUnionT = sti.Kind == TypeKinds.Result ? types.MakeResult(sti.A, sti.B) : types.MakeOption(sti.A);
        if (!types.IsLinear(outerUnionT, in ast))
        {
            diags.ReportTok(VibCodes.IllegalFieldMove, ta.Tokens[tokIdx], "Cannot move non-Copy value out of a field, indexed element, or borrowed place."u8);
        }
        int wrapType = headNameId == bctx.IdSome ? types.MakeSomeWrap(payloadTypeId) :
            (headNameId == bctx.IdOk ? types.MakeOkWrap(payloadTypeId) : types.MakeErrWrap(payloadTypeId));
        int patScope = fctx.OutVarScopeOverride > 0 ? fctx.OutVarScopeOverride : fctx.ScopeDepth;
        int wLid = BindExpressionLocal(wrapperNameId, wrapType, MirLocalFlags.IsPatternBind, patScope, tokIdx, ref fctx, in ast, in ta, in names, ref diags);
        int wPl = mir.AddPlaceLocal(wLid, wrapType);
        int zOp = mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, wrapType, tokIdx));
        fctx.Emit(new MirInst(MirOp.AssignUse, wPl, -1, 0, wrapType, zOp, 0, 0, 0, tokIdx));
    }

    private static bool IsDiscardPattern(in AstNode pat) =>
        pat.Kind == AstKind.PatWildcard || (pat.Kind == AstKind.PatDecl && pat.A < 0 && pat.B < 0 && pat.C == 0);

    // Whether a case label after (secIdx, lblIdx) tests the scrutinee again:
    // any label other than `default:` and a discard (`_` or `var _`).
    private static bool HasLaterScrutineeLabel(in AstNode n, int secIdx, int lblIdx, in AstArena ast)
    {
        for (int i = secIdx; i < n.C; i++)
        {
            AstNode sec = ast.Nodes[ast.Extra[n.B + i]];
            int first = i == secIdx ? lblIdx + 1 : 0;
            for (int l = first; l < sec.B; l++)
            {
                AstNode lbl = ast.Nodes[ast.Extra[sec.A + l]];
                if (lbl.A < 0) continue;
                if (IsDiscardPattern(in ast.Nodes[lbl.A])) continue;
                return true;
            }
        }
        return false;
    }

    private static bool HasLaterScrutineeArm(in AstNode n, int armIdx, in AstArena ast)
    {
        for (int i = armIdx + 1; i < n.C; i++)
        {
            AstNode arm = ast.Nodes[ast.Extra[n.B + i]];
            if (IsDiscardPattern(in ast.Nodes[arm.A])) continue;
            return true;
        }
        return false;
    }

    private static void LowerPatternOnPlaceBranch(int scrutPl, int scrutType, int patNodeId, int tokIdx, int matchBlk, int failBlk, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags) => LowerPatternOnPlaceBranch(scrutPl, scrutType, patNodeId, tokIdx, matchBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, true, true);

    private static void LowerPatternOnPlaceBranch(int scrutPl, int scrutType, int patNodeId, int tokIdx, int matchBlk, int failBlk, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags, bool parentIsBorrowed) => LowerPatternOnPlaceBranch(scrutPl, scrutType, patNodeId, tokIdx, matchBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, parentIsBorrowed, true);

    private static void LowerPatternOnPlaceBranch(
        int scrutPl,
        int scrutType,
        int patNodeId,
        int tokIdx,
        int matchBlk,
        int failBlk,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        bool parentIsBorrowed,
        bool parentIsShared)
    {
        AstNode pat = ast.Nodes[patNodeId];
        if (pat.Kind != AstKind.PatUnion)
        {
            LowerNonUnionPatternBranch(scrutPl, scrutType, patNodeId, tokIdx, matchBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            return;
        }
        TypeInfo sti = types.Items[scrutType];
        bool isView = sti.Kind == TypeKinds.OptionRef || sti.Kind == TypeKinds.OptionMut;
        bool mutCur = sti.Kind == TypeKinds.OptionMut;
        int headNameId = ast.Nodes[pat.A].A;

        if (!parentIsBorrowed)
        {
            int valOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, scrutPl, 0, scrutType, pat.TokIdx));
            int valFlags = isView ? (4 | (mutCur ? 2 : 0)) : 0;
            bool subBorrow = isView;
            bool subShared = sti.Kind == TypeKinds.OptionRef;
            EmitUnionPatternMatchCore(valOp, scrutType, sti, valFlags, subBorrow, subShared, in pat, headNameId, tokIdx, matchBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            return;
        }

        if (types.IsLinear(scrutType, in ast))
        {
            diags.ReportTok(VibCodes.LinearViolation, ta.Tokens[pat.TokIdx], "Pattern matching on a linear union place without moving it is banned in Vibranium."u8);
        }
        int termFlags = 1 | (mutCur ? 2 : 0) | (isView ? 4 : 0);
        bool isShared = isView ? !mutCur : parentIsShared;
        EmitUnionPatternMatchCore(scrutPl, scrutType, sti, termFlags, isBorrowed: true, isShared, in pat, headNameId, tokIdx, matchBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
    }

    private static void EmitUnionPatternMatchCore(
        int scrutPlaceOrOp,
        int scrutType,
        TypeInfo sti,
        int termFlags,
        bool isBorrowed,
        bool isShared,
        in AstNode pat,
        int headNameId,
        int tokIdx,
        int matchBlk,
        int failBlk,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        if (sti.Kind == TypeKinds.Option || sti.Kind == TypeKinds.OptionRef || sti.Kind == TypeKinds.OptionMut)
        {
            int innerT = sti.A;
            bool matchSome = headNameId == bctx.IdSome;
            UnpackPatUnion(in pat, matchSome ? innerT : TypeIds.NoneUnit, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int directBind, out int wrapBind, out int extraSubPat);
            if ((pat.C != 0 || extraSubPat >= 0) && types.IsLinear(scrutType, in ast))
            {
                diags.ReportTok(VibCodes.LinearViolation, ta.Tokens[pat.TokIdx], "Nested subpatterns on linear union resources are banned in Vibranium."u8);
            }
            int bName = matchSome ? directBind : -1;
            bool hasInner = matchSome && extraSubPat >= 0;
            int patScope = fctx.OutVarScopeOverride > 0 ? fctx.OutVarScopeOverride : fctx.ScopeDepth;
            int bindTargetScope = (bName >= 0 || hasInner) ? patScope : fctx.ScopeDepth;
            int bFlags = MakePatternBindFlags(innerT, bName, isBorrowed, isShared, in ast, in types);
            int bindLid = BindExpressionLocal(bName, innerT, bFlags, bindTargetScope, pat.TokIdx, ref fctx, in ast, in ta, in names, ref diags);
            int wrapTargetBlk = wrapBind >= 0 ? fctx.NewBlock() : matchBlk;
            int sBlk = matchSome ? (hasInner ? fctx.NewBlock() : wrapTargetBlk) : failBlk;
            int nBlk = matchSome ? failBlk : wrapTargetBlk;
            fctx.Terminate(new MirTerm(MirTermKind.MatchOption, scrutPlaceOrOp, bindLid, sBlk, nBlk, 0, termFlags, tokIdx));
            if (hasInner)
            {
                fctx.CurBlock = sBlk;
                int subPl = mir.AddPlaceLocal(bindLid, innerT);
                LowerPatternOnPlaceBranch(subPl, innerT, extraSubPat, pat.TokIdx, wrapTargetBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, isBorrowed, isShared);
            }
            if (wrapBind >= 0)
            {
                fctx.CurBlock = wrapTargetBlk;
                EmitUnionWrapperBind(wrapBind, headNameId, matchSome ? bindLid : -1, matchSome ? innerT : TypeIds.NoneUnit, pat.TokIdx, ref fctx, in ast, in ta, in names, in bctx, ref types, ref mir, ref diags);
                fctx.Terminate(new MirTerm(MirTermKind.Goto, matchBlk, 0, 0, 0, 0, 0, pat.TokIdx));
            }
            return;
        }

        if (sti.Kind == TypeKinds.Result)
        {
            int okT = sti.A;
            int errT = sti.B;
            bool matchOk = headNameId == bctx.IdOk;
            int payloadT = matchOk ? okT : errT;
            UnpackPatUnion(in pat, payloadT, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int directBind, out int wrapBind, out int extraSubPat);
            if ((pat.C != 0 || extraSubPat >= 0) && types.IsLinear(scrutType, in ast))
            {
                diags.ReportTok(VibCodes.LinearViolation, ta.Tokens[pat.TokIdx], "Nested subpatterns on linear union resources are banned in Vibranium."u8);
            }
            int okName = matchOk ? directBind : -1;
            int errName = !matchOk ? directBind : -1;
            bool hasInner = extraSubPat >= 0;
            int patScope = fctx.OutVarScopeOverride > 0 ? fctx.OutVarScopeOverride : fctx.ScopeDepth;
            int okTargetScope = (okName >= 0 || (matchOk && hasInner)) ? patScope : fctx.ScopeDepth;
            int errTargetScope = (errName >= 0 || (!matchOk && hasInner)) ? patScope : fctx.ScopeDepth;
            int okLid = BindExpressionLocal(okName, okT, MakePatternBindFlags(okT, okName, isBorrowed, isShared, in ast, in types), okTargetScope, pat.TokIdx, ref fctx, in ast, in ta, in names, ref diags);
            int errLid = BindExpressionLocal(errName, errT, MakePatternBindFlags(errT, errName, isBorrowed, isShared, in ast, in types), errTargetScope, pat.TokIdx, ref fctx, in ast, in ta, in names, ref diags);
            int payloadLid = matchOk ? okLid : errLid;
            int wrapTargetBlk = wrapBind >= 0 ? fctx.NewBlock() : matchBlk;
            int targetMatchBlk = hasInner ? fctx.NewBlock() : wrapTargetBlk;
            int okBlk = matchOk ? targetMatchBlk : failBlk;
            int errBlk = matchOk ? failBlk : targetMatchBlk;
            fctx.Terminate(new MirTerm(MirTermKind.MatchResult, scrutPlaceOrOp, okLid, okBlk, errLid, errBlk, termFlags, tokIdx));
            if (hasInner)
            {
                fctx.CurBlock = targetMatchBlk;
                int subPl = mir.AddPlaceLocal(payloadLid, payloadT);
                LowerPatternOnPlaceBranch(subPl, payloadT, extraSubPat, pat.TokIdx, wrapTargetBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, isBorrowed, isShared);
            }
            if (wrapBind >= 0)
            {
                fctx.CurBlock = wrapTargetBlk;
                EmitUnionWrapperBind(wrapBind, headNameId, payloadLid, payloadT, pat.TokIdx, ref fctx, in ast, in ta, in names, in bctx, ref types, ref mir, ref diags);
                fctx.Terminate(new MirTerm(MirTermKind.Goto, matchBlk, 0, 0, 0, 0, 0, pat.TokIdx));
            }
            return;
        }

        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[pat.TokIdx], "Union pattern requires Option<T> or Result<T, E> scrutinee."u8);
        fctx.Terminate(new MirTerm(MirTermKind.Goto, failBlk, 0, 0, 0, 0, 0, tokIdx));
    }

    private static bool IsPlaceExpression(int exprId, in AstArena ast, in FuncLowerCtx fctx, in TypeTable types)
    {
        if (exprId < 0) return false;
        AstNode n = ast.Nodes[exprId];
        switch (n.Kind)
        {
            case AstKind.ExprThis:
                return true;
            case AstKind.ExprIdent:
            {
                int lid = fctx.FindVar(n.A, out bool isConst, out _, out _);
                if (isConst) return false;
                if (lid >= 0) return true;
                if ((fctx.ThisLocalId >= 0 || fctx.IsCtor) && fctx.OwnerTypeId >= 0 && FindInstanceFieldIndex(fctx.OwnerTypeId, n.A, in types) >= 0)
                {
                    return true;
                }
                return false;
            }
            case AstKind.ExprMember:
            {
                if (fctx.IsCtor && ast.Nodes[n.A].Kind == AstKind.ExprThis) return true;
                return IsPlaceExpression(n.A, in ast, in fctx, in types);
            }
            case AstKind.ExprIndex:
                return !(n.D >= 0 && ast.Nodes[n.D].Kind == AstKind.ExprRange);
            default:
                return false;
        }
    }

    private static bool IsObviouslySharedExpr(int exprId, in FuncLowerCtx fctx, in AstArena ast)
    {
        AstNode n = ast.Nodes[exprId];
        if (n.Kind == AstKind.ExprThis && fctx.ThisLocalId >= 0)
        {
            return fctx.Locals[fctx.ThisLocalId].Mode == PassMode.ThisShared;
        }
        if (n.Kind == AstKind.ExprIdent)
        {
            int lid = fctx.FindVar(n.A, out _, out _, out _);
            if (lid >= 0)
            {
                MirLocal loc = fctx.Locals[lid];
                if (loc.Mode == PassMode.In) return true;
                if ((loc.Flags & MirLocalFlags.IsRefLocal) != 0 && (loc.Flags & MirLocalFlags.IsRefMut) == 0) return true;
            }
        }
        if (n.Kind == AstKind.ExprMember)
        {
            return IsObviouslySharedExpr(n.A, in fctx, in ast);
        }
        return false;
    }

    private static void PushSpeculativeOutArg(in AstNode cArg, int outTypeId, ref FuncLowerCtx fctx)
    {
        if (fctx.InferDepth <= 0 || outTypeId <= 0 || outTypeId == TypeIds.Void) return;
        if ((cArg.C == -1 || cArg.C >= 0) && cArg.D >= 0)
        {
            fctx.Vars.Push(new VarBinding(cArg.D, -2, fctx.ScopeDepth, 0, outTypeId, 0));
        }
    }

    private static void CollectSpeculativePatternBindings(
        int patNodeId,
        int scrutTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        ref Vec<VarBinding> outBinds)
    {
        if (patNodeId < 0 || scrutTypeId <= 0) return;
        AstNode pat = ast.Nodes[patNodeId];
        switch (pat.Kind)
        {
            case AstKind.PatDecl:
            {
                if (pat.B >= 0)
                {
                    int bType = pat.A >= 0
                        ? DeclBinder.ResolveTypeNode(pat.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false)
                        : scrutTypeId;
                    outBinds.Push(new VarBinding(pat.B, -2, fctx.ScopeDepth, 0, bType, 0));
                }
                return;
            }
            case AstKind.PatUnion:
            {
                TypeInfo sti = types.Items[scrutTypeId];
                int headNameId = ast.Nodes[pat.A].A;
                int payloadT = TypeIds.Error;
                if (sti.Kind == TypeKinds.Option || sti.Kind == TypeKinds.OptionRef || sti.Kind == TypeKinds.OptionMut || sti.Kind == TypeKinds.SomeWrap)
                {
                    if (headNameId == bctx.IdSome) payloadT = sti.A;
                }
                else if (sti.Kind == TypeKinds.Result)
                {
                    if (headNameId == bctx.IdOk) payloadT = sti.A;
                    else if (headNameId == bctx.IdErr) payloadT = sti.B;
                }
                else if (sti.Kind == TypeKinds.OkWrap && headNameId == bctx.IdOk) payloadT = sti.A;
                else if (sti.Kind == TypeKinds.ErrWrap && headNameId == bctx.IdErr) payloadT = sti.A;

                if (pat.B >= 0)
                {
                    int wType = TypeIds.NoneUnit;
                    if (headNameId == bctx.IdSome && payloadT > 0) wType = types.MakeSomeWrap(payloadT);
                    else if (headNameId == bctx.IdOk && payloadT > 0) wType = types.MakeOkWrap(payloadT);
                    else if (headNameId == bctx.IdErr && payloadT > 0) wType = types.MakeErrWrap(payloadT);
                    outBinds.Push(new VarBinding(pat.B, -2, fctx.ScopeDepth, 0, wType, 0));
                }
                if (pat.D >= 0 && payloadT > 0)
                {
                    CollectSpeculativePatternBindings(pat.D, payloadT, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref outBinds);
                }
                return;
            }
            case AstKind.PatNot:
            {
                // `not P` declares what P declares; only the outcome that
                // assigns it is the other one (C# scope).
                CollectSpeculativePatternBindings(pat.A, scrutTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref outBinds);
                return;
            }
            case AstKind.PatLogic:
            {
                if (pat.A == 0) // `and`
                {
                    CollectSpeculativePatternBindings(pat.B, scrutTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref outBinds);
                    CollectSpeculativePatternBindings(pat.C, scrutTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref outBinds);
                }
                return;
            }
        }
    }

    private static void InferCondBranchSpeculative(
        int condExprId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        ref Vec<VarBinding> truePats,
        ref Vec<VarBinding> falsePats)
    {
        if (condExprId < 0) return;
        AstNode n = ast.Nodes[condExprId];
        if (n.Kind == AstKind.ExprUnary && n.C == 0 && (TokKind)n.A == TokKind.Bang)
        {
            InferCondBranchSpeculative(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref falsePats, ref truePats);
            return;
        }
        if (n.Kind == AstKind.ExprBinary && ((TokKind)n.A == TokKind.AmpAmp || (TokKind)n.A == TokKind.PipePipe))
        {
            // The right operand is in the scope of every pattern variable the
            // left one declares, whichever outcome assigns it (C# scope).
            int beforeT = truePats.Count;
            int beforeF = falsePats.Count;
            InferCondBranchSpeculative(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref truePats, ref falsePats);
            int endT = truePats.Count;
            int endF = falsePats.Count;
            for (int i = beforeT; i < endT; i++) fctx.Vars.Push(truePats[i]);
            for (int i = beforeF; i < endF; i++) fctx.Vars.Push(falsePats[i]);
            int pushedForR = (endT - beforeT) + (endF - beforeF);
            InferCondBranchSpeculative(n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref truePats, ref falsePats);
            if (pushedForR > 0)
            {
                // Keep any out-vars pushed after them, remove only the temporary pattern bindings we injected
                var keptOuts = new Vec<VarBinding>();
                while (fctx.Vars.Count > 0 && pushedForR > 0)
                {
                    VarBinding top = fctx.Vars[fctx.Vars.Count - 1];
                    fctx.Vars.Pop();
                    bool matchPat = false;
                    for (int k = beforeT; k < endT && !matchPat; k++) matchPat = top.NameId == truePats[k].NameId && top.LocalId == -2;
                    for (int k = beforeF; k < endF && !matchPat; k++) matchPat = top.NameId == falsePats[k].NameId && top.LocalId == -2;
                    if (matchPat) pushedForR -= 1;
                    else keptOuts.Push(top);
                }
                for (int k = keptOuts.Count - 1; k >= 0; k--) fctx.Vars.Push(keptOuts[k]);
            }
            return;
        }
        if (n.Kind == AstKind.ExprIsPattern)
        {
            int st = InferExprType(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            AstNode pat = ast.Nodes[n.B];
            if (pat.Kind == AstKind.PatNot)
            {
                CollectSpeculativePatternBindings(pat.A, st, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref falsePats);
            }
            else
            {
                CollectSpeculativePatternBindings(n.B, st, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref truePats);
            }
            return;
        }
        _ = InferExprType(condExprId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
    }

    private static int InferExprType(
        int exprId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags)
    {
        if (exprId < 0) return TypeIds.Void;
        fctx.InferDepth += 1;
        int res = InferExprTypeCore(exprId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        fctx.LeaveSpeculativeInfer();
        return res;
    }

    private static int InferExprTypeCore(
        int exprId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags)
    {
        AstNode n = ast.Nodes[exprId];
        switch (n.Kind)
        {
            case AstKind.ExprIntLit:
            {
                TokKind tk = ta.Tokens[n.A].Kind;
                if (tk == TokKind.LongLit) return TypeIds.I64;
                if (tk == TokKind.UIntLit) return TypeIds.U32;
                if (tk == TokKind.ULongLit) return TypeIds.U64;
                return TypeIds.I32;
            }
            case AstKind.ExprFloatLit:
                return ta.Tokens[n.A].Kind == TokKind.FloatLit ? TypeIds.F32 : TypeIds.F64;
            case AstKind.ExprBoolLit:
                return TypeIds.Bool;
            case AstKind.ExprIsPattern:
            {
                int isScrutT = InferExprType(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                var isBinds = new Vec<VarBinding>();
                CollectSpeculativePatternBindings(n.B, isScrutT, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref isBinds);
                for (int i = 0; i < isBinds.Count; i++) fctx.Vars.Push(isBinds[i]);
                return TypeIds.Bool;
            }
            case AstKind.ExprCharLit:
                return TypeIds.Char;
            case AstKind.ExprStrLit:
                return TypeIds.Str;
            case AstKind.ExprUtf8Lit:
                return types.MakeSpan(TypeIds.U8, isReadOnly: true);
            case AstKind.ExprThis:
                return fctx.OwnerTypeId >= 0 ? fctx.OwnerTypeId : TypeIds.Error;
            case AstKind.ExprCast:
                InferOperandDeclarations(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                return DeclBinder.ResolveTypeNode(n.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
            case AstKind.ExprDefault:
                return n.A >= 0
                    ? DeclBinder.ResolveTypeNode(n.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false)
                    : TypeIds.Error;
            case AstKind.ExprNew:
            {
                int newType = n.A >= 0
                    ? DeclBinder.ResolveTypeNode(n.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false)
                    : TypeIds.Error;
                // The arguments do not change the type, but the constructor's
                // resolution types them and declares its out variables (N111).
                TypeInfo newInfo = types.Items[newType];
                var ctorCands = new Vec<int>();
                if (fctx.ElementRetypeDepth == 0 && n.C > 0 && (newInfo.Kind == TypeKinds.Class || newInfo.Kind == TypeKinds.Struct))
                    CollectTypeMethodCandidates(newInfo.A, -1, allowInstance: true, allowStatic: false, isCtor: true, ref fctx, in ast, in bctx, ref ctorCands);
                if (ctorCands.Count > 0)
                    _ = ResolveBestOverload(ctorCands.AsReadOnlySpan(), newType, -1, 0, 0, n.B, n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out _);
                else InferArgumentDeclarations(n.B, n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                return newType;
            }
            case AstKind.ExprIdent:
            {
                int lid = fctx.FindVar(n.A, out bool isConst, out int constTypeId, out _);
                if (isConst || lid == -2) return constTypeId;
                if (lid >= 0) return fctx.Locals[lid].TypeId;
                int curOwnerDecl = fctx.EnclosingOwnerDeclId;
                for (int d = curOwnerDecl; d >= 0; d = ast.Types[d].OwnerDeclId)
                {
                    TypeDecl otd = ast.Types[d];
                    for (int f = 0; f < otd.FieldCount; f++)
                    {
                        FieldDecl fd = ast.Fields[otd.FieldStart + f];
                        if (fd.NameId == n.A && (fd.Flags & DeclFlags.IsConst) != 0)
                        {
                            var empty = new Vec<int>();
                            return DeclBinder.ResolveTypeNode(fd.TypeNode, empty.AsReadOnlySpan(), empty.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                        }
                    }
                }
                if ((fctx.ThisLocalId >= 0 || fctx.IsCtor) && fctx.OwnerTypeId >= 0)
                {
                    int fIdx = FindInstanceFieldIndex(fctx.OwnerTypeId, n.A, in types);
                    if (fIdx >= 0) return types.Fields[types.Items[fctx.OwnerTypeId].FieldStart + fIdx].TypeId;
                    int ownerDecl = types.Items[fctx.OwnerTypeId].A;
                    int propGet = FindMethodInType(ownerDecl, MakePropGetterLookup(n.A, in ast, in names), 0, isStatic: false, in ast);
                    if (propGet >= 0)
                    {
                        return DeclBinder.ResolveTypeNode(ast.Funcs[propGet].RetTypeNode, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                    }
                }
                for (int d = curOwnerDecl; d >= 0; d = ast.Types[d].OwnerDeclId)
                {
                    if (d != curOwnerDecl && ast.Types[d].TypeParamCount > 0) continue;
                    int sPropGet = FindMethodInType(d, MakePropGetterLookup(n.A, in ast, in names), 0, isStatic: true, in ast);
                    if (sPropGet >= 0)
                    {
                        var empty = new Vec<int>();
                        return DeclBinder.ResolveTypeNode(ast.Funcs[sPropGet].RetTypeNode, empty.AsReadOnlySpan(), empty.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                    }
                }
                if (TryResolveUsingStaticValueMember(n.A, n.TokIdx, reportAmbiguity: false, ref fctx, in ast, in ta, in names, in bctx, ref diags, out int usKind, out int usOwnerDecl, out int usOwnerTid, out int usFieldIdx, out int usPropGet, out _, out _, out int usBTypeId, out _, out _))
                {
                    var usTpN = new Vec<int>();
                    var usTpV = new Vec<int>();
                    if (usOwnerTid >= 0) BuildOwnerTypeSubst(usOwnerTid, in ast, in types, ref usTpN, ref usTpV);
                    if (usKind == 1 && usOwnerDecl >= 0)
                    {
                        TypeDecl ustd = ast.Types[usOwnerDecl];
                        if (ustd.Kind == TypeDeclKinds.Enum)
                        {
                            return types.MakeEnum(usOwnerDecl, names.Text(ustd.NameId));
                        }
                        return DeclBinder.ResolveTypeNode(ast.Fields[ustd.FieldStart + usFieldIdx].TypeNode, usTpN.AsReadOnlySpan(), usTpV.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                    }
                    if (usKind == 2 && usPropGet >= 0)
                    {
                        return DeclBinder.ResolveTypeNode(ast.Funcs[usPropGet].RetTypeNode, usTpN.AsReadOnlySpan(), usTpV.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                    }
                    if (usKind == 3 && usBTypeId > 0)
                    {
                        return usBTypeId;
                    }
                }
                if (n.A == bctx.IdNone) return TypeIds.NoneUnit;
                return TypeIds.Error;
            }
            case AstKind.ExprIndex:
            {
                int t = InferExprType(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                TypeInfo ti = types.Items[t];
                bool isRangeIndex = n.D >= 0 && ast.Nodes[n.D].Kind == AstKind.ExprRange;
                // Only a user indexer's resolution types the index arguments.
                if (isRangeIndex || (ti.Kind != TypeKinds.Struct && ti.Kind != TypeKinds.Class))
                    InferArgumentDeclarations(n.B, n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (isRangeIndex)
                {
                    if (ti.Kind == TypeKinds.Vec) return types.MakeSpan(ti.A, isReadOnly: false);
                    if (ti.Kind == TypeKinds.Span || ti.Kind == TypeKinds.ReadOnlySpan) return t;
                    if (ti.Kind == TypeKinds.Struct || ti.Kind == TypeKinds.Class)
                    {
                        int slMethod = FindUserSliceTwoIntMethod(t, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                        if (slMethod >= 0)
                        {
                            var subNames = new Vec<int>();
                            var subVals = new Vec<int>();
                            BuildOwnerTypeSubst(t, in ast, in types, ref subNames, ref subVals);
                            return DeclBinder.ResolveTypeNode(ast.Funcs[slMethod].RetTypeNode, subNames.AsReadOnlySpan(), subVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                        }
                    }
                    return TypeIds.I32;
                }
                if (ti.Kind == TypeKinds.Vec || ti.Kind == TypeKinds.Span || ti.Kind == TypeKinds.ReadOnlySpan)
                {
                    return ti.A;
                }
                if (ti.Kind == TypeKinds.Struct || ti.Kind == TypeKinds.Class)
                {
                    if (TryResolveUserIndexer(t, in n, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out _, out int elemTid, out _, out _))
                    {
                        return elemTid;
                    }
                }
                return TypeIds.I32;
            }
            case AstKind.ExprMember:
            {
                if (TryResolveStaticTypeTarget(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int staticDeclId, out int staticTid, memberHintNameId: n.B, isMethodCallHint: false))
                {
                    ReadOnlySpan<byte> stTargetName = GetStaticTargetEffectiveLeafName(n.A, in fctx, in ast, in ta, in names, in bctx, out _);
                    if (staticDeclId < 0 &&
                        DeclBinder.TryEvalBuiltinNumericConstMember(stTargetName, names.Text(n.B), out int bConstTid, out _, out _))
                    {
                        return bConstTid;
                    }
                    if (staticDeclId < 0 && (Bytes.Eq(stTargetName, "string"u8) || Bytes.Eq(stTargetName, "String"u8)) && Bytes.Eq(names.Text(n.B), "Empty"u8))
                    {
                        return TypeIds.Str;
                    }
                    if (staticDeclId < 0 && Bytes.Eq(stTargetName, "Prelude"u8) && n.B == bctx.IdNone)
                    {
                        return TypeIds.NoneUnit;
                    }
                    if (staticDeclId >= 0 && ast.Types[staticDeclId].Kind == TypeDeclKinds.Enum)
                    {
                        return staticTid;
                    }
                    if (staticDeclId >= 0)
                    {
                        TypeDecl std = ast.Types[staticDeclId];
                        for (int f = 0; f < std.FieldCount; f++)
                        {
                            FieldDecl fd = ast.Fields[std.FieldStart + f];
                            if (fd.NameId == n.B && (fd.Flags & DeclFlags.IsConst) != 0)
                            {
                                var empty = new Vec<int>();
                                return DeclBinder.ResolveTypeNode(fd.TypeNode, empty.AsReadOnlySpan(), empty.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                            }
                        }
                        int sProp = FindMethodInType(staticDeclId, MakePropGetterLookup(n.B, in ast, in names), 0, isStatic: true, in ast);
                        if (sProp >= 0)
                        {
                            var subNames = new Vec<int>();
                            var subVals = new Vec<int>();
                            if (staticTid >= 0) BuildOwnerTypeSubst(staticTid, in ast, in types, ref subNames, ref subVals);
                            return DeclBinder.ResolveTypeNode(ast.Funcs[sProp].RetTypeNode, subNames.AsReadOnlySpan(), subVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                        }
                    }
                    return TypeIds.I32;
                }
                int recvT = InferExprType(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                TypeInfo rti = types.Items[recvT];
                ReadOnlySpan<byte> mName = names.Text(n.B);
                if (rti.Kind == TypeKinds.Vec)
                {
                    if (Bytes.Eq(mName, "Count"u8) || Bytes.Eq(mName, "Capacity"u8)) return TypeIds.I32;
                }
                if (rti.Kind == TypeKinds.Span || rti.Kind == TypeKinds.ReadOnlySpan)
                {
                    if (Bytes.Eq(mName, "Length"u8)) return TypeIds.I32;
                    if (Bytes.Eq(mName, "IsEmpty"u8)) return TypeIds.Bool;
                }
                if (rti.Kind == TypeKinds.Option || rti.Kind == TypeKinds.OptionRef || rti.Kind == TypeKinds.OptionMut)
                {
                    if (Bytes.Eq(mName, "IsSome"u8) || Bytes.Eq(mName, "IsEmpty"u8)) return TypeIds.Bool;
                }
                if (rti.Kind == TypeKinds.Result && Bytes.Eq(mName, "IsOk"u8)) return TypeIds.Bool;
                if ((rti.Kind == TypeKinds.SomeWrap || rti.Kind == TypeKinds.OkWrap) && n.B == bctx.IdValue) return rti.A;
                if (rti.Kind == TypeKinds.ErrWrap && n.B == bctx.IdError) return rti.A;
                if (rti.Kind == TypeKinds.Class || rti.Kind == TypeKinds.Struct)
                {
                    int fIdx = FindInstanceFieldIndex(recvT, n.B, in types);
                    if (fIdx >= 0) return types.Fields[rti.FieldStart + fIdx].TypeId;
                    int propGet = FindMethodInType(rti.A, MakePropGetterLookup(n.B, in ast, in names), 0, isStatic: false, in ast);
                    if (propGet >= 0)
                    {
                        var subNames = new Vec<int>();
                        var subVals = new Vec<int>();
                        BuildOwnerTypeSubst(recvT, in ast, in types, ref subNames, ref subVals);
                        return DeclBinder.ResolveTypeNode(ast.Funcs[propGet].RetTypeNode, subNames.AsReadOnlySpan(), subVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                    }
                }
                return TypeIds.I32;
            }
            case AstKind.ExprCall:
            {
                return InferCallReturnType(in n, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            }
            case AstKind.ExprUnary:
            {
                TokKind uk = (TokKind)n.A;
                if (uk == TokKind.Bang)
                {
                    _ = InferExprType(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    return TypeIds.Bool;
                }
                if (uk == TokKind.PlusPlus || uk == TokKind.MinusMinus || uk == TokKind.KwRef || uk == TokKind.KwUnchecked)
                {
                    return InferExprType(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                }
                if (uk == TokKind.Minus && ast.Nodes[n.B].Kind == AstKind.ExprIntLit)
                {
                    Token litTok = ta.Tokens[ast.Nodes[n.B].A];
                    if ((litTok.AuxId & 4) != 0)
                    {
                        return TypeIds.Error;
                    }
                    if (litTok.AuxId == 0 && (ulong)litTok.IntVal == 2147483648UL && litTok.Kind != TokKind.LongLit)
                    {
                        return TypeIds.I32;
                    }
                    if (litTok.Kind == TokKind.ULongLit)
                    {
                        return ((litTok.AuxId & 5) == 0 && (ulong)litTok.IntVal == 9223372036854775808UL) ? TypeIds.I64 : TypeIds.Error;
                    }
                    if (litTok.Kind == TokKind.LongLit || litTok.Kind == TokKind.UIntLit || (ulong)litTok.IntVal > 2147483648UL)
                    {
                        return TypeIds.I64;
                    }
                    return TypeIds.I32;
                }
                int subT = InferExprType(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (uk == TokKind.Minus && subT == TypeIds.U32) return TypeIds.I64;
                if (types.IsInteger(subT) && types.IntBitWidth(subT) < 32) return TypeIds.I32;
                return subT;
            }
            case AstKind.ExprBinary:
            {
                TokKind bk = (TokKind)n.A;
                if (bk == TokKind.EqEq || bk == TokKind.BangEq || bk == TokKind.LAngle ||
                    bk == TokKind.RAngle || bk == TokKind.LtEq || bk == TokKind.GtEq ||
                    bk == TokKind.AmpAmp || bk == TokKind.PipePipe)
                {
                    _ = InferExprType(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    _ = InferExprType(n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    return TypeIds.Bool;
                }
                int lt = InferExprType(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (bk == TokKind.LtLt || bk == TokKind.GtGt || bk == TokKind.GtGtGt)
                {
                    InferOperandDeclarations(n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    return (types.IsInteger(lt) && types.IntBitWidth(lt) < 32) ? TypeIds.I32 : lt;
                }
                int rt = InferExprType(n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (bk == TokKind.Plus && lt == TypeIds.Str && rt == TypeIds.Str)
                {
                    return TypeIds.Str;
                }
                bool lEnum = types.Items[lt].Kind == TypeKinds.Enum;
                bool rEnum = types.Items[rt].Kind == TypeKinds.Enum;
                if (lEnum || rEnum)
                {
                    int enumType = lEnum ? lt : rt;
                    if (bk == TokKind.Pipe || bk == TokKind.Amp || bk == TokKind.Caret) return enumType;
                    if (bk == TokKind.Minus)
                    {
                        if (lt == rt) return TypeIds.I32;
                        // E - U wins over E - E only when the right operand
                        // implicitly converts to int (e.g. 'e - 0', not 'e - 0f').
                        int otherType = lEnum ? rt : lt;
                        int otherExpr = lEnum ? n.C : n.B;
                        if (!(lEnum && ClassifyByValueConversionWithCtx(otherExpr, otherType, TypeIds.I32, in fctx, in names, in bctx, in ast, in ta, in types) >= 0) &&
                            ClassifyByValueConversionWithCtx(otherExpr, otherType, enumType, in fctx, in names, in bctx, in ast, in ta, in types) >= 0)
                        {
                            return TypeIds.I32;
                        }
                    }
                    if (bk == TokKind.Plus || bk == TokKind.Minus) return enumType;
                }
                return PromoteBinaryNumericTypeWithCtx(n.B, lt, n.C, rt, in fctx, in names, in bctx, in ast, in ta, in types);
            }
            case AstKind.ExprCond:
            {
                int scopeStart = fctx.Vars.Count;
                var truePats = new Vec<VarBinding>();
                var falsePats = new Vec<VarBinding>();
                InferCondBranchSpeculative(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref truePats, ref falsePats);

                // Both arms are in the scope of every variable the condition
                // declares, whichever outcome assigns it (C# scope).
                for (int i = 0; i < truePats.Count; i++) fctx.Vars.Push(truePats[i]);
                for (int i = 0; i < falsePats.Count; i++) fctx.Vars.Push(falsePats[i]);
                int trueScopeEnd = fctx.Vars.Count;
                int t1 = InferExprType(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);

                int falseScopeEnd = fctx.Vars.Count;
                int t2 = InferExprType(n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);

                int slot = fctx.BranchFactsFor(exprId, 2);
                fctx.RecordBranchArm(slot, t1, scopeStart, trueScopeEnd);
                fctx.RecordBranchArm(slot + 1, t2, scopeStart, falseScopeEnd);
                int natural = NaturalConditionalType(t1, n.B, t2, n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                return natural >= 0 ? natural : TypeIds.Error;
            }
            case AstKind.ExprSwitch:
            {
                int natural = InferSwitchNaturalType(exprId, in n, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                return natural >= 0 ? natural : TypeIds.Error;
            }
            case AstKind.ExprAssign:
            {
                if (n.D != 0)
                {
                    int refTargetT = InferExprType(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    InferOperandDeclarations(n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    return refTargetT;
                }
                if (IsDiscardExpression(n.B, in fctx, in ast, in names))
                {
                    return InferExprType(n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                }
                int lhsT = InferExprType(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                InferOperandDeclarations(n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                if ((TokKind)n.A == TokKind.PlusEq)
                {
                    TypeInfo lti = types.Items[lhsT];
                    if (lti.Kind == TypeKinds.Vec) return TypeIds.Void;
                    if ((lti.Kind == TypeKinds.Struct || lti.Kind == TypeKinds.Class) &&
                        HasAccessibleOpAddAssign(lti.A, ref fctx, in ast, in bctx))
                    {
                        return TypeIds.Void;
                    }
                }
                return lhsT;
            }
            default:
                return TypeIds.Error;
        }
    }

    private static int InferCallReturnType(
        in AstNode callNode,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags)
    {
        AstNode callee = ast.Nodes[callNode.A];
        int argCount = callNode.C;

        if (callee.Kind == AstKind.ExprIdent)
        {
            // 1. Visible local functions (method group hides outer scopes)
            var lfCands = new Vec<int>();
            for (int i = 0; i < fctx.VisibleLocalFuncs.Count; i++)
            {
                int lfId = fctx.VisibleLocalFuncs[i];
                if (ast.Funcs[lfId].NameId == callee.A) lfCands.Push(lfId);
            }
            if (lfCands.Count > 0)
            {
                int bestLf = ResolveBestOverload(lfCands.AsReadOnlySpan(), -1, -1, callee.B, callee.C, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out int lfRetT);
                return bestLf >= 0 ? lfRetT : TypeIds.Error;
            }

            // 2. Enclosing type methods (walk innermost outward; any accessible method group hides outer scopes & using static)
            for (int d = fctx.EnclosingOwnerDeclId; d >= 0; d = ast.Types[d].OwnerDeclId)
            {
                bool hasAnyByName = HasAccessibleMethodNamed(d, callee.A, ref fctx, in ast, in bctx);
                if (!hasAnyByName) continue;

                bool isInnermost = d == fctx.EnclosingOwnerDeclId;
                bool canResolveOnD = isInnermost ? (fctx.OwnerTypeId >= 0 || ast.Types[d].TypeParamCount == 0) : (ast.Types[d].TypeParamCount == 0);
                if (!canResolveOnD) return TypeIds.Error;

                var encCands = new Vec<int>();
                CollectTypeMethodCandidates(d, callee.A, allowInstance: isInnermost && (fctx.ThisLocalId >= 0 || fctx.IsCtor), allowStatic: true, isCtor: false, ref fctx, in ast, in bctx, ref encCands);
                int encOwnerTid = isInnermost ? fctx.OwnerTypeId : -1;
                int bestEnc = ResolveBestOverload(encCands.AsReadOnlySpan(), encOwnerTid, -1, callee.B, callee.C, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out int encRetT);
                return bestEnc >= 0 ? encRetT : TypeIds.Error;
            }

            // 3. Imported `using static` tiers (inner namespaces outward, then compilation-unit + ConsoleIo + Prelude)
            if (TryResolveUsingStaticMethodCall(callee.A, callee.B, callee.C, callNode.B, argCount, callNode.TokIdx, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int usBestFunc, out _, out bool usAmb, out int usRetT))
            {
                return usAmb ? TypeIds.Error : usRetT;
            }
            return TypeIds.Void;
        }

        if (callee.Kind == AstKind.ExprMember)
        {
            if (TryResolveStaticTypeTarget(callee.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int stDecl, out int stTid, memberHintNameId: callee.B, isMethodCallHint: true))
            {
                if (stDecl >= 0)
                {
                    var stCands = new Vec<int>();
                    CollectTypeMethodCandidates(stDecl, callee.B, allowInstance: false, allowStatic: true, isCtor: false, ref fctx, in ast, in bctx, ref stCands);
                    int bestSt = ResolveBestOverload(stCands.AsReadOnlySpan(), stTid, -1, callee.C, callee.D, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out int stRetT);
                    if (bestSt >= 0) return stRetT;
                    return TypeIds.Void;
                }
                _ = GetStaticTargetEffectiveLeafName(callee.A, in fctx, in ast, in ta, in names, in bctx, out int stNameId);
                if (stNameId == bctx.IdOptionExtensions && Bytes.Eq(names.Text(callee.B), "AsRef"u8) && argCount == 1 && callee.D <= 1)
                {
                    // Preserve the signature's result type on a converted argument,
                    // so lowering diagnoses the missing storage at the argument
                    // rather than reporting an unrelated member error on the result.
                    if (callee.D == 1)
                    {
                        int payload = DeclBinder.ResolveTypeNode(ast.Extra[callee.C], fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                        InferArgumentDeclarations(callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                        return types.MakeOptionRef(payload);
                    }
                    AstNode slot = ast.Nodes[ast.Extra[callNode.B]];
                    int slotType = InferExprType(slot.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    TypeInfo slotInfo = types.Items[slotType];
                    if (slotInfo.Kind == TypeKinds.Option) return types.MakeOptionRef(slotInfo.A);
                }
                if (stNameId == bctx.IdPrelude)
                {
                    if (callee.B == bctx.IdSome && argCount == 1)
                    {
                        int inner;
                        if (callee.D == 1)
                        {
                            InferOperandDeclarations(ast.Nodes[ast.Extra[callNode.B]].B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                            inner = DeclBinder.ResolveTypeNode(ast.Extra[callee.C], fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                        }
                        else inner = InferExprType(ast.Nodes[ast.Extra[callNode.B]].B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                        return types.MakeSomeWrap(inner);
                    }
                    if (callee.B == bctx.IdOk)
                    {
                        if (argCount == 0 && callee.D == 0) return types.MakeOkWrap(TypeIds.NoneUnit);
                        if (argCount == 1)
                        {
                            int okInner;
                            if (callee.D == 1)
                            {
                                InferOperandDeclarations(ast.Nodes[ast.Extra[callNode.B]].B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                                okInner = DeclBinder.ResolveTypeNode(ast.Extra[callee.C], fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                            }
                            else okInner = InferExprType(ast.Nodes[ast.Extra[callNode.B]].B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                            return types.MakeOkWrap(okInner);
                        }
                    }
                    if (callee.B == bctx.IdErr && argCount == 1)
                    {
                        int errInner;
                        if (callee.D == 1)
                        {
                            InferOperandDeclarations(ast.Nodes[ast.Extra[callNode.B]].B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                            errInner = DeclBinder.ResolveTypeNode(ast.Extra[callee.C], fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                        }
                        else errInner = InferExprType(ast.Nodes[ast.Extra[callNode.B]].B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                        return types.MakeErrWrap(errInner);
                    }
                    if (callee.B == bctx.IdMove && argCount == 1)
                    {
                        return InferExprType(ast.Nodes[ast.Extra[callNode.B]].B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    }
                }
                if (stNameId == bctx.IdStringUtf8Extensions && callee.B == bctx.IdAsUtf8 && argCount == 1)
                {
                    InferArgumentDeclarations(callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    return types.MakeSpan(TypeIds.U8, isReadOnly: true);
                }
                if ((stNameId == bctx.IdUtf8SpanExtensions || stNameId == bctx.IdStringUtf8Extensions) && callee.B == bctx.IdLines && argCount == 1)
                {
                    InferArgumentDeclarations(callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    return TypeIds.Utf8Lines;
                }
                if (bctx.HasStdUnit && callee.B == bctx.IdTryParse && argCount == 2 &&
                    (stNameId == bctx.IdInt || stNameId == bctx.IdInt32 || stNameId == bctx.IdLong || stNameId == bctx.IdInt64))
                {
                    int tpOutT = (stNameId == bctx.IdLong || stNameId == bctx.IdInt64) ? TypeIds.I64 : TypeIds.I32;
                    for (int ai = 0; ai < 2; ai++)
                    {
                        AstNode tpa = ast.Nodes[ast.Extra[callNode.B + ai]];
                        if (CallArgBits.Mode(in tpa) == PassMode.Out) PushSpeculativeOutArg(in tpa, tpOutT, ref fctx);
                        else _ = InferExprType(tpa.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    }
                    return TypeIds.Bool;
                }
                if (bctx.HasStdUnit && stNameId == bctx.IdMemoryExtensions)
                {
                    if (IsMemoryExtensionsCallAllowed(callee.B, callee.C, callee.D, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags))
                    {
                        Option<int> bseOpt = bctx.StdTypeByNameArity.Get(DeclBinder.PackNameArity(bctx.IdByteSpanExtensions, 0));
                        if (bseOpt.IsSome)
                        {
                            var meCands = new Vec<int>();
                            CollectMemoryExtensionsCandidates(bseOpt.Unwrap(), callee.B, ref fctx, in ast, in bctx, ref meCands);
                            int bestMe = ResolveBestOverload(meCands.AsReadOnlySpan(), -1, -1, 0, 0, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out int meRetT);
                            if (bestMe >= 0) return meRetT;
                        }
                    }
                    return TypeIds.Void;
                }
                return TypeIds.Void;
            }

            int recvT = InferExprType(callee.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            TypeInfo rti = types.Items[recvT];
            ReadOnlySpan<byte> mName = names.Text(callee.B);

            if (recvT == TypeIds.Str && callee.B == bctx.IdAsUtf8 && argCount == 0)
            {
                return types.MakeSpan(TypeIds.U8, isReadOnly: true);
            }
            if (recvT == TypeIds.Str && callee.B == bctx.IdLines && argCount == 0)
            {
                return TypeIds.Utf8Lines;
            }
            if ((rti.Kind == TypeKinds.Span || rti.Kind == TypeKinds.ReadOnlySpan) &&
                rti.A == TypeIds.U8 && callee.B == bctx.IdLines && argCount == 0)
            {
                return TypeIds.Utf8Lines;
            }
            if (rti.Kind == TypeKinds.Option)
            {
                if (Bytes.Eq(mName, "AsRef"u8)) return types.MakeOptionRef(rti.A);
                if (Bytes.Eq(mName, "AsMut"u8)) return types.MakeOptionMut(rti.A);
                if (Bytes.Eq(mName, "Take"u8) || Bytes.Eq(mName, "Replace"u8))
                {
                    InferArgumentDeclarations(callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    return recvT;
                }
                if (Bytes.Eq(mName, "Unwrap"u8) || Bytes.Eq(mName, "UnwrapOr"u8) || Bytes.Eq(mName, "UnwrapMut"u8) ||
                    Bytes.Eq(mName, "Expect"u8) || Bytes.Eq(mName, "UnwrapOrDefault"u8))
                {
                    InferArgumentDeclarations(callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    return rti.A;
                }
                if (Bytes.Eq(mName, "IsNone"u8))
                {
                    if (argCount == 1)
                    {
                        AstNode na0 = ast.Nodes[ast.Extra[callNode.B]];
                        if (CallArgBits.Mode(in na0) == PassMode.Out) PushSpeculativeOutArg(in na0, rti.A, ref fctx);
                    }
                    return TypeIds.Bool;
                }
            }
            if (rti.Kind == TypeKinds.OptionMut)
            {
                if (Bytes.Eq(mName, "AsRef"u8)) return types.MakeOptionRef(rti.A);
                if (Bytes.Eq(mName, "Take"u8) || Bytes.Eq(mName, "Replace"u8))
                {
                    InferArgumentDeclarations(callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    return types.MakeOption(rti.A);
                }
                if (Bytes.Eq(mName, "Set"u8))
                {
                    InferArgumentDeclarations(callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    return TypeIds.Void;
                }
            }
            if (rti.Kind == TypeKinds.Result)
            {
                if (Bytes.Eq(mName, "Unwrap"u8) || Bytes.Eq(mName, "UnwrapOr"u8) ||
                    Bytes.Eq(mName, "Expect"u8) || Bytes.Eq(mName, "UnwrapOrDefault"u8))
                {
                    InferArgumentDeclarations(callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    return rti.A;
                }
                if (Bytes.Eq(mName, "IsErr"u8))
                {
                    if (argCount == 2)
                    {
                        AstNode ra0 = ast.Nodes[ast.Extra[callNode.B + 0]];
                        AstNode ra1 = ast.Nodes[ast.Extra[callNode.B + 1]];
                        if (TryMapTwoNamedArgs(in ra0, in ra1, "ok"u8, "err"u8, in names, out int okIdx, out int errIdx))
                        {
                            AstNode okArg = okIdx == 0 ? ra0 : ra1;
                            AstNode errArg = errIdx == 0 ? ra0 : ra1;
                            if (CallArgBits.Mode(in okArg) == PassMode.Out) PushSpeculativeOutArg(in okArg, rti.A, ref fctx);
                            if (CallArgBits.Mode(in errArg) == PassMode.Out) PushSpeculativeOutArg(in errArg, types.MakeErrWrap(rti.B), ref fctx);
                        }
                    }
                    return TypeIds.Bool;
                }
            }
            if (rti.Kind == TypeKinds.Vec)
            {
                if (Bytes.Eq(mName, "Pop"u8)) return types.MakeOption(rti.A);
                if (Bytes.Eq(mName, "Slice"u8) || Bytes.Eq(mName, "AsSpan"u8))
                {
                    InferArgumentDeclarations(callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    return types.MakeSpan(rti.A, isReadOnly: false);
                }
                if (Bytes.Eq(mName, "ReadOnlySlice"u8) || Bytes.Eq(mName, "AsReadOnlySpan"u8))
                {
                    InferArgumentDeclarations(callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    return types.MakeSpan(rti.A, isReadOnly: true);
                }
                if (Bytes.Eq(mName, "Push"u8) || Bytes.Eq(mName, "Add"u8) || Bytes.Eq(mName, "Clear"u8) ||
                    Bytes.Eq(mName, "Truncate"u8) || Bytes.Eq(mName, "Reserve"u8) || Bytes.Eq(mName, "Extend"u8) ||
                    Bytes.Eq(mName, "Resize"u8))
                {
                    InferArgumentDeclarations(callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    return TypeIds.Void;
                }
            }
            if ((rti.Kind == TypeKinds.Span || rti.Kind == TypeKinds.ReadOnlySpan) && Bytes.Eq(mName, "Slice"u8) && (argCount == 1 || argCount == 2))
            {
                InferArgumentDeclarations(callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                return recvT;
            }
            if (rti.Kind == TypeKinds.Class || rti.Kind == TypeKinds.Struct)
            {
                var imCands = new Vec<int>();
                CollectTypeMethodCandidates(rti.A, callee.B, allowInstance: true, allowStatic: false, isCtor: false, ref fctx, in ast, in bctx, ref imCands);
                int bestIm = ResolveBestOverload(imCands.AsReadOnlySpan(), recvT, -1, callee.C, callee.D, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out int imRetT);
                if (bestIm >= 0) return imRetT;
            }

            // Extension method fallback
            var extCands = new Vec<int>();
            CollectExtensionCandidates(callee.B, ref fctx, in ast, in bctx, ref extCands);
            int bestExt = ResolveBestOverload(extCands.AsReadOnlySpan(), -1, recvT, callee.C, callee.D, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out int extRetT);
            if (bestExt >= 0) return extRetT;
        }
        return TypeIds.Void;
    }

    private static void BuildOwnerTypeSubst(int ownerTid, in AstArena ast, in TypeTable types, ref Vec<int> tpNames, ref Vec<int> tpVals)
    {
        TypeInfo ti = types.Items[ownerTid];
        if (ti.Kind != TypeKinds.Class && ti.Kind != TypeKinds.Struct) return;
        TypeDecl td = ast.Types[ti.A];
        for (int i = 0; i < td.TypeParamCount; i++)
        {
            tpNames.Push(ast.Extra[td.TypeParamStart + i]);
            tpVals.Push(types.TypeArgs[ti.B + i]);
        }
    }

    private static int MakePropGetterLookup(int propNameId, in AstArena ast, in Interner names)
    {
        var sb = new StringBuf(32);
        sb.Append("get_"u8);
        sb.Append(names.Text(propNameId));
        for (int i = 0; i < names.Count; i++)
        {
            if (Bytes.Eq(names.Text(i), sb.AsUtf8()))
            {
                return i;
            }
        }
        return -1;
    }

    // At lowering time the receiver is typed again, so that the variables it
    // declares are in scope in the index arguments, and one argument's are in
    // scope in the next (C# scope, N110).
    private static bool TryResolveUserIndexer(
        int ownerTypeId,
        in AstNode idxNode,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        out int getterDeclId,
        out int setterDeclId,
        out int elemTypeId,
        out bool isFromEndImplicit,
        out bool isAmbiguous)
    {
        bool atRoot = fctx.InferDepth == 0;
        fctx.InferDepth += 1;
        if (atRoot) _ = InferExprType(idxNode.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        bool found = TryResolveUserIndexerCore(ownerTypeId, in idxNode, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags,
            out getterDeclId, out setterDeclId, out elemTypeId, out isFromEndImplicit, out isAmbiguous);
        fctx.LeaveSpeculativeInfer();
        return found;
    }

    private static bool TryResolveUserIndexerCore(
        int ownerTypeId,
        in AstNode idxNode,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        out int getterDeclId,
        out int setterDeclId,
        out int elemTypeId,
        out bool isFromEndImplicit,
        out bool isAmbiguous)
    {
        getterDeclId = -1;
        setterDeclId = -1;
        elemTypeId = TypeIds.I32;
        isFromEndImplicit = false;
        isAmbiguous = false;

        TypeInfo ti = types.Items[ownerTypeId];
        if (ti.Kind != TypeKinds.Struct && ti.Kind != TypeKinds.Class) return false;
        TypeDecl td = ast.Types[ti.A];

        var declGetIds = new Vec<int>();
        var declSetIds = new Vec<int>();
        var declTokIdxs = new Vec<int>();

        for (int m = 0; m < td.FuncCount; m++)
        {
            int fId = td.FuncStart + m;
            FuncDecl fd = ast.Funcs[fId];
            if ((fd.Flags & DeclFlags.IsIndexer) == 0) continue;
            bool isGet = (fd.Flags & DeclFlags.IsPropGet) != 0;
            bool isSet = (fd.Flags & DeclFlags.IsPropSet) != 0;
            if (!isGet && !isSet) continue;

            int slot = -1;
            for (int s = 0; s < declTokIdxs.Count; s++)
            {
                if (declTokIdxs[s] == fd.TokIdx)
                {
                    slot = s;
                    break;
                }
            }
            if (slot < 0)
            {
                slot = declTokIdxs.Count;
                declTokIdxs.Push(fd.TokIdx);
                declGetIds.Push(-1);
                declSetIds.Push(-1);
            }
            if (isGet) declGetIds[slot] = fId;
            if (isSet) declSetIds[slot] = fId;
        }

        if (declTokIdxs.Count == 0) return false;

        bool fromEndSyntax = idxNode.D >= 0 && ast.Nodes[idxNode.D].Kind == AstKind.ExprFromEnd;
        int callArgCount = idxNode.C;
        if (callArgCount <= 0) return false;

        var actualArgModes = new Vec<int>(callArgCount);
        var actualArgTypes = new Vec<int>(callArgCount);
        if (fromEndSyntax)
        {
            InferOperandDeclarations(idxNode.D, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            actualArgModes.Push((int)PassMode.ByValue);
            actualArgTypes.Push(TypeIds.I32);
        }
        else
        {
            for (int a = 0; a < callArgCount; a++)
            {
                AstNode cArg = ast.Nodes[ast.Extra[idxNode.B + a]];
                actualArgModes.Push((int)CallArgBits.Mode(in cArg));
                actualArgTypes.Push(InferCallArgActualType(in cArg, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags));
            }
        }

        int stride = callArgCount + 1;
        var appSlots = new Vec<int>(declTokIdxs.Count);
        var appRepIds = new Vec<int>(declTokIdxs.Count);
        var appRetTypes = new Vec<int>(declTokIdxs.Count);
        var appUsesDefaults = new Vec<int>(declTokIdxs.Count);
        var appParamTypes = new Vec<int>(declTokIdxs.Count * stride);
        var appParamModes = new Vec<int>(declTokIdxs.Count * stride);

        for (int s = 0; s < declTokIdxs.Count; s++)
        {
            int gId = declGetIds[s];
            int setId = declSetIds[s];
            bool gAcc = gId >= 0 && IsAccessibleFuncFromCaller(gId, ref fctx, in ast, in bctx);
            bool sAcc = setId >= 0 && IsAccessibleFuncFromCaller(setId, ref fctx, in ast, in bctx);
            if (!gAcc && !sAcc) continue;

            int repId = gId >= 0 ? gId : setId;
            int exclTrailing = gId >= 0 ? 0 : 1;
            var candPTypes = new Vec<int>(stride);
            var candPModes = new Vec<int>(stride);

            bool okCand;
            int candRetT;
            bool candUsesDef;
            if (fromEndSyntax)
            {
                okCand = TryEvaluateFromEndIndexerCandidate(repId, exclTrailing, ownerTypeId, in ast, in ta, in names, ref bctx, ref types, ref diags, ref candPTypes, ref candPModes, out candRetT, out candUsesDef);
            }
            else
            {
                okCand = TryEvaluateCandidate(
                    repId,
                    ownerTypeId,
                    -1,
                    0,
                    0,
                    idxNode.B,
                    callArgCount,
                    actualArgTypes.AsReadOnlySpan(),
                    ref fctx,
                    in ast,
                    in ta,
                    in names,
                    ref bctx,
                    ref types,
                    ref diags,
                    ref candPTypes,
                    ref candPModes,
                    out candRetT,
                    out candUsesDef,
                    exclTrailing);
            }

            if (okCand)
            {
                appSlots.Push(s);
                appRepIds.Push(repId);
                appRetTypes.Push(candRetT);
                appUsesDefaults.Push(candUsesDef ? 1 : 0);
                for (int k = 0; k < stride; k++)
                {
                    appParamTypes.Push(candPTypes[k]);
                    appParamModes.Push(candPModes[k]);
                }
            }
        }

        if (appSlots.Count == 0) return false;

        int winIdx = -1;
        if (appSlots.Count == 1)
        {
            winIdx = 0;
        }
        else
        {
            for (int i = 0; i < appSlots.Count; i++)
            {
                bool beatsAll = true;
                for (int j = 0; j < appSlots.Count; j++)
                {
                    if (i == j) continue;
                    if (!IsBetterCandidate(
                        appRepIds[i],
                        appUsesDefaults[i] != 0,
                        appParamTypes.AsReadOnlySpan().Slice(i * stride, stride),
                        appParamModes.AsReadOnlySpan().Slice(i * stride, stride),
                        appRepIds[j],
                        appUsesDefaults[j] != 0,
                        appParamTypes.AsReadOnlySpan().Slice(j * stride, stride),
                        appParamModes.AsReadOnlySpan().Slice(j * stride, stride),
                        -1,
                        actualArgTypes.AsReadOnlySpan(),
                        actualArgModes.AsReadOnlySpan(),
                        in ast,
                        in types))
                    {
                        beatsAll = false;
                        break;
                    }
                }
                if (beatsAll)
                {
                    winIdx = i;
                    break;
                }
            }
        }

        if (winIdx < 0)
        {
            isAmbiguous = true;
            return false;
        }

        int winSlot = appSlots[winIdx];
        int rawG = declGetIds[winSlot];
        int rawS = declSetIds[winSlot];
        getterDeclId = (rawG >= 0 && IsAccessibleFuncFromCaller(rawG, ref fctx, in ast, in bctx)) ? rawG : -1;
        setterDeclId = (rawS >= 0 && IsAccessibleFuncFromCaller(rawS, ref fctx, in ast, in bctx)) ? rawS : -1;
        elemTypeId = appRetTypes[winIdx];
        isFromEndImplicit = fromEndSyntax;
        return true;
    }

    private static bool TryEvaluateFromEndIndexerCandidate(
        int repFuncDeclId,
        int excludeTrailing,
        int ownerTypeId,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        ref Vec<int> outParamTypes,
        ref Vec<int> outParamModes,
        out int resolvedRetType,
        out bool usesDefaults)
    {
        resolvedRetType = TypeIds.I32;
        usesDefaults = false;
        FuncDecl fd = ast.Funcs[repFuncDeclId];
        int formalCount = fd.ParamCount - excludeTrailing;
        if (formalCount < 1) return false;
        for (int p = 1; p < formalCount; p++)
        {
            if (ast.Params[fd.ParamStart + p].DefaultExpr < 0) return false;
            usesDefaults = true;
        }
        var tpNames = new Vec<int>();
        var tpVals = new Vec<int>();
        BuildOwnerTypeSubst(ownerTypeId, in ast, in types, ref tpNames, ref tpVals);

        ParamDecl p0 = ast.Params[fd.ParamStart];
        if (p0.Mode != PassMode.ByValue && p0.Mode != PassMode.In) return false;
        int p0Type = DeclBinder.ResolveTypeNode(p0.TypeNode, tpNames.AsReadOnlySpan(), tpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
        if (p0.Mode == PassMode.In)
        {
            if (p0Type != TypeIds.I32) return false;
        }
        else if (p0Type != TypeIds.I32 && !CanImplicitNumericWiden(TypeIds.I32, p0Type))
        {
            return false;
        }

        outParamTypes.Push(-1);
        outParamModes.Push((int)PassMode.ByValue);
        outParamTypes.Push(p0Type);
        outParamModes.Push((int)p0.Mode);

        int elemNode = excludeTrailing > 0
            ? ast.Params[fd.ParamStart + fd.ParamCount - 1].TypeNode
            : fd.RetTypeNode;
        resolvedRetType = DeclBinder.ResolveTypeNode(elemNode, tpNames.AsReadOnlySpan(), tpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
        return true;
    }

    private static bool IsSameOrNestedInsideType(int innerDeclId, int outerDeclId, in AstArena ast)
    {
        for (int d = innerDeclId; d >= 0; d = ast.Types[d].OwnerDeclId)
        {
            if (d == outerDeclId) return true;
        }
        return false;
    }

    private static bool HasAccessibleMethodNamed(int declId, int nameId, ref FuncLowerCtx fctx, in AstArena ast, in BinderCtx bctx)
    {
        if (declId < 0 || nameId < 0) return false;
        TypeDecl td = ast.Types[declId];
        for (int m = 0; m < td.FuncCount; m++)
        {
            int fId = td.FuncStart + m;
            FuncDecl fd = ast.Funcs[fId];
            if ((fd.Flags & DeclFlags.IsCtor) != 0 || fd.NameId != nameId) continue;
            if (IsAccessibleFuncFromCaller(fId, ref fctx, in ast, in bctx)) return true;
        }
        return false;
    }

    private static bool HasAccessibleOpAddAssign(int declId, ref FuncLowerCtx fctx, in AstArena ast, in BinderCtx bctx)
    {
        if (declId < 0) return false;
        TypeDecl td = ast.Types[declId];
        for (int m = 0; m < td.FuncCount; m++)
        {
            int fId = td.FuncStart + m;
            FuncDecl fd = ast.Funcs[fId];
            if ((fd.Flags & DeclFlags.IsOpAddAssign) != 0 && fd.ParamCount == 1 && IsAccessibleFuncFromCaller(fId, ref fctx, in ast, in bctx))
            {
                return true;
            }
        }
        return false;
    }

    private static int FindMethodInType(int declId, int nameId, int paramCount, bool isStatic, in AstArena ast)
    {
        if (nameId < 0 || declId < 0) return -1;
        TypeDecl td = ast.Types[declId];
        for (int m = 0; m < td.FuncCount; m++)
        {
            int fId = td.FuncStart + m;
            FuncDecl fd = ast.Funcs[fId];
            bool fdStatic = (fd.Flags & DeclFlags.Static) != 0;
            if (fd.NameId == nameId && fdStatic == isStatic && fd.ParamCount == paramCount)
            {
                return fId;
            }
        }
        // Fallback for default-value optional parameter (e.g. `reportLinearErrors = true`)
        for (int m = 0; m < td.FuncCount; m++)
        {
            int fId = td.FuncStart + m;
            FuncDecl fd = ast.Funcs[fId];
            bool fdStatic = (fd.Flags & DeclFlags.Static) != 0;
            if (fd.NameId == nameId && fdStatic == isStatic && fd.ParamCount > paramCount)
            {
                return fId;
            }
        }
        return -1;
    }

    private static int FindMethodAnyStaticness(int declId, int nameId, int paramCount, in AstArena ast)
    {
        int inst = FindMethodInType(declId, nameId, paramCount, isStatic: false, in ast);
        if (inst >= 0) return inst;
        return FindMethodInType(declId, nameId, paramCount, isStatic: true, in ast);
    }

    private static void InstantiateResolvedStaticTarget(
        int resolvedDeclId,
        int taExtraStart,
        int taCount,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        out int concreteTypeId)
    {
        concreteTypeId = -1;
        TypeDecl td = ast.Types[resolvedDeclId];
        if (td.Kind == TypeDeclKinds.Enum)
        {
            concreteTypeId = types.MakeEnum(resolvedDeclId, names.Text(td.NameId));
        }
        else if (((td.Flags & DeclFlags.Static) == 0 || td.TypeParamCount > 0) && (td.TypeParamCount == 0 || taCount > 0))
        {
            var targs = new Vec<int>(taCount);
            for (int i = 0; i < taCount; i++)
            {
                targs.Push(DeclBinder.ResolveTypeNode(ast.Extra[taExtraStart + i], fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags));
            }
            int tk = td.Kind == TypeDeclKinds.Class ? TypeKinds.Class : TypeKinds.Struct;
            concreteTypeId = types.MakeUserType(tk, resolvedDeclId, names.Text(td.NameId), targs.AsReadOnlySpan());
            DeclBinder.PopulateTypeFieldsOnly(concreteTypeId, in ast, in ta, in names, ref bctx, ref types, ref diags);
        }
    }

    private static bool IsBuiltinSystemStaticTargetName(ReadOnlySpan<byte> nm, int nameId, in BinderCtx bctx)
    {
        return Bytes.Eq(nm, "Console"u8) || Bytes.Eq(nm, "Array"u8) || nameId == bctx.IdMemoryExtensions ||
               Bytes.Eq(nm, "Boolean"u8) || Bytes.Eq(nm, "Byte"u8) || Bytes.Eq(nm, "SByte"u8) ||
               Bytes.Eq(nm, "Int16"u8) || Bytes.Eq(nm, "UInt16"u8) || Bytes.Eq(nm, "Char"u8) ||
               Bytes.Eq(nm, "Int32"u8) || Bytes.Eq(nm, "UInt32"u8) || Bytes.Eq(nm, "Int64"u8) ||
               Bytes.Eq(nm, "UInt64"u8) || Bytes.Eq(nm, "IntPtr"u8) || Bytes.Eq(nm, "UIntPtr"u8) ||
               Bytes.Eq(nm, "Single"u8) || Bytes.Eq(nm, "Double"u8) || Bytes.Eq(nm, "String"u8);
    }

    private static bool IsBuiltinVibraniumStaticTargetName(int nameId, in BinderCtx bctx)
    {
        return nameId == bctx.IdPrelude || nameId == bctx.IdIo || nameId == bctx.IdStdio ||
               nameId == bctx.IdVibraniumRuntime || nameId == bctx.IdStringUtf8Extensions ||
               nameId == bctx.IdUtf8SpanExtensions || nameId == bctx.IdOptionExtensions;
    }

    private static bool TryBuildNamespaceExprPath(
        int exprId,
        int ownerDeclId,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types,
        ref StringBuf path,
        out bool rootedGlobal)
    {
        rootedGlobal = false;
        AstNode n = ast.Nodes[exprId];
        if (n.Kind == AstKind.ExprIdent)
        {
            if (n.C > 0 || n.D == 2) return false;
            if (n.D == 0)
            {
                int fv = fctx.FindVar(n.A, out bool isC, out _, out _);
                if (fv >= 0 || fv == -2 || isC) return false;
                if (fctx.OwnerTypeId >= 0 && FindInstanceFieldIndex(fctx.OwnerTypeId, n.A, in types) >= 0) return false;
                for (int tp = 0; tp < fctx.TpNames.Count; tp++)
                {
                    if (fctx.TpNames[tp] == n.A) return false;
                }
                GetActiveUsingSlice(ownerDeclId, n.TokIdx, in fctx, in ast, in ta, out int callerUnit, out int curNs, out int effOwner, out int uStart, out int uCount);
                if (callerUnit == UnitKinds.App && uCount > 0)
                {
                    for (int d = effOwner; d >= 0; d = ast.Types[d].OwnerDeclId)
                    {
                        for (int ti = 0; ti < ast.Types.Count; ti++)
                        {
                            TypeDecl td = ast.Types[ti];
                            if (td.OwnerDeclId == d && td.NameId == n.A && td.TypeParamCount == 0)
                            {
                                return false;
                            }
                        }
                    }
                    ReadOnlySpan<byte> segTxt = names.Text(n.A);
                    int step = 0;
                    while (DeclBinder.TryStepEnclosingNamespace(curNs, ref step, in ast, in names, out int nsCur))
                    {
                        bool shadowedByNsOrType = false;
                        if (nsCur >= 0)
                        {
                            if (DeclBinder.FindDeclaredTypeInExactNamespace(n.A, 0, nsCur, UnitKinds.App, in ast, in bctx) >= 0)
                            {
                                shadowedByNsOrType = true;
                            }
                            else
                            {
                                ReadOnlySpan<byte> curTxt = names.Text(nsCur);
                                var subNs = new StringBuf(curTxt.Length + 1 + segTxt.Length);
                                subNs.Append(curTxt);
                                subNs.AppendAscii((byte)'.');
                                subNs.Append(segTxt);
                                ReadOnlySpan<byte> subSpan = subNs.AsUtf8();
                                for (int dni = 0; dni < ast.DeclaredNamespaces.Count; dni++)
                                {
                                    int dnId = ast.DeclaredNamespaces[dni];
                                    if (Bytes.Eq(names.Text(dnId), subSpan) ||
                                        (names.Text(dnId).Length > subSpan.Length && names.Text(dnId).StartsWith(subSpan) && names.Text(dnId)[subSpan.Length] == (byte)'.'))
                                    {
                                        shadowedByNsOrType = true;
                                        break;
                                    }
                                }
                            }
                        }
                        else
                        {
                            if (bctx.AppGlobalTypeByNameArity.Get(DeclBinder.PackNameArity(n.A, 0)).IsSome ||
                                n.A == bctx.IdSystem || n.A == bctx.IdVibranium)
                            {
                                shadowedByNsOrType = true;
                            }
                            else
                            {
                                for (int dni = 0; dni < ast.DeclaredNamespaces.Count; dni++)
                                {
                                    ReadOnlySpan<byte> dnTxt = names.Text(ast.DeclaredNamespaces[dni]);
                                    if (Bytes.Eq(dnTxt, segTxt) ||
                                        (dnTxt.Length > segTxt.Length && dnTxt.StartsWith(segTxt) && dnTxt[segTxt.Length] == (byte)'.'))
                                    {
                                        shadowedByNsOrType = true;
                                        break;
                                    }
                                }
                            }
                        }
                        if (shadowedByNsOrType) break;

                        for (int scopePass = 0; scopePass < 2; scopePass++)
                        {
                            if (nsCur >= 0 && scopePass == 1) break;
                            for (int u = 0; u < uCount; u++)
                            {
                                int uIdx = ast.Extra[uStart + u];
                                if (uIdx < 0 || uIdx >= bctx.UsingBoundKind.Count) continue;
                                UsingEntry ue = ast.Usings[uIdx];
                                if (ue.EnclosingNsId != nsCur || ue.Kind != UsingKinds.Alias) continue;
                                if (nsCur < 0 && ((scopePass == 0 && ue.ScopeLevel != 1) || (scopePass == 1 && ue.ScopeLevel != 0))) continue;
                                if (ue.AliasOrNsId == n.A)
                                {
                                    if (bctx.UsingBoundKind[uIdx] == 1 && bctx.UsingBoundId[uIdx] >= 0)
                                    {
                                        rootedGlobal = true;
                                        path.Append(names.Text(bctx.UsingBoundId[uIdx]));
                                        return true;
                                    }
                                    return false;
                                }
                            }
                        }
                    }
                }
            }
            else if (n.D == 1)
            {
                rootedGlobal = true;
            }
            path.Append(names.Text(n.A));
            return true;
        }
        if (n.Kind == AstKind.ExprMember && n.D == 0)
        {
            if (!TryBuildNamespaceExprPath(n.A, ownerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, ref path, out rootedGlobal))
            {
                return false;
            }
            path.AppendAscii((byte)'.');
            path.Append(names.Text(n.B));
            return true;
        }
        return false;
    }

    private static int FindInternedText(ReadOnlySpan<byte> text, in Interner names)
    {
        for (int i = 0; i < names.Count; i++)
        {
            if (Bytes.Eq(names.Text(i), text)) return i;
        }
        return -1;
    }

    [return: LifetimeOf("names")]
    private static ReadOnlySpan<byte> GetStaticTargetEffectiveLeafName(
        int exprId,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        out int leafNameId)
    {
        AstNode n = ast.Nodes[exprId];
        if (n.Kind == AstKind.ExprMember)
        {
            leafNameId = n.B;
            return n.B >= 0 ? names.Text(n.B) : ""u8;
        }
        if (n.Kind == AstKind.ExprIdent)
        {
            if (n.D == 0 && n.C == 0)
            {
                GetActiveUsingSlice(-1, n.TokIdx, in fctx, in ast, in ta, out int callerUnit, out int curNs, out int curOwner, out int uStart, out int uCount);
                if (callerUnit == UnitKinds.App && uCount > 0)
                {
                    int rk = DeclBinder.ResolveAppUnqualifiedName(n.A, 0, curNs, curOwner, uStart, uCount, in ast, in names, in bctx, out _, out int fAliasIdx, out _, out _);
                    if (rk == 2 && fAliasIdx >= 0 && fAliasIdx < bctx.UsingBoundKind.Count)
                    {
                        int bk = bctx.UsingBoundKind[fAliasIdx];
                        int bid = bctx.UsingBoundId[fAliasIdx];
                        int btid = bctx.UsingBoundTypeId[fAliasIdx];
                        if (bk == 2 && bid >= 0)
                        {
                            leafNameId = ast.Types[bid].NameId;
                            return names.Text(leafNameId);
                        }
                        if (bk == 3)
                        {
                            if (bid < 0)
                            {
                                ReadOnlySpan<byte> bName = DeclBinder.BuiltinStaticName(bid);
                                leafNameId = FindInternedText(bName, in names);
                                return bName;
                            }
                            if (btid > 0)
                            {
                                ReadOnlySpan<byte> pName = DeclBinder.PrimTypeIdBuiltinName(btid);
                                if (pName.Length > 0)
                                {
                                    leafNameId = FindInternedText(pName, in names);
                                    return pName;
                                }
                            }
                            int tgtNode = ast.Usings[fAliasIdx].TargetNode;
                            if (tgtNode >= 0)
                            {
                                leafNameId = ast.Nodes[tgtNode].A;
                                return leafNameId >= 0 ? names.Text(leafNameId) : ""u8;
                            }
                        }
                    }
                }
            }
            leafNameId = n.A;
            return n.A >= 0 ? names.Text(n.A) : ""u8;
        }
        leafNameId = -1;
        return ""u8;
    }

    private static bool TypeHasInstanceMemberNamed(
        int varTypeId,
        int declId,
        int memberNameId,
        bool isMethodCall,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types)
    {
        if (declId < 0 || memberNameId < 0) return false;
        TypeDecl td = ast.Types[declId];
        if (td.Kind == TypeDeclKinds.Enum) return false;
        if (isMethodCall)
        {
            for (int m = 0; m < td.FuncCount; m++)
            {
                int fId = td.FuncStart + m;
                FuncDecl fd = ast.Funcs[fId];
                if ((fd.Flags & DeclFlags.IsCtor) == 0 && (fd.Flags & DeclFlags.Static) == 0 &&
                    fd.NameId == memberNameId && IsAccessibleFuncFromCaller(fId, ref fctx, in ast, in bctx))
                {
                    return true;
                }
            }
            return false;
        }
        if (varTypeId >= 0 && FindInstanceFieldIndex(varTypeId, memberNameId, in types) >= 0) return true;
        int propGet = FindMethodInType(declId, MakePropGetterLookup(memberNameId, in ast, in names), 0, isStatic: false, in ast);
        if (propGet >= 0 && IsAccessibleFuncFromCaller(propGet, ref fctx, in ast, in bctx)) return true;
        var setBuf = new StringBuf(32);
        setBuf.Append("set_"u8);
        setBuf.Append(names.Text(memberNameId));
        int setId = FindInternedText(setBuf.AsUtf8(), in names);
        if (setId >= 0)
        {
            int propSet = FindMethodInType(declId, setId, 1, isStatic: false, in ast);
            if (propSet >= 0 && IsAccessibleFuncFromCaller(propSet, ref fctx, in ast, in bctx)) return true;
        }
        return false;
    }

    private static bool TryResolveStaticTypeTarget(int exprId, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags, out int declId, out int concreteTypeId) => TryResolveStaticTypeTarget(exprId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out declId, out concreteTypeId, -1, false);

    private static bool TryResolveStaticTypeTarget(int exprId, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags, out int declId, out int concreteTypeId, int memberHintNameId) => TryResolveStaticTypeTarget(exprId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out declId, out concreteTypeId, memberHintNameId, false);

    private static bool TryResolveStaticTypeTarget(
        int exprId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        out int declId,
        out int concreteTypeId,
        int memberHintNameId,
        bool isMethodCallHint)
    {
        declId = -1;
        concreteTypeId = -1;
        AstNode n = ast.Nodes[exprId];

        GetActiveUsingSlice(-1, n.TokIdx, in fctx, in ast, in ta, out int callerUnit, out int curNs, out int curOwner, out int uStart, out int uCount);

        if (n.Kind == AstKind.ExprMember)
        {
            // 1. Nested type on a resolved outer type (`Outer.Inner<...>`)
            int diagSave = diags.Items.Count;
            if (TryResolveStaticTypeTarget(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int parentDeclId, out _, memberHintNameId: n.B, isMethodCallHint: false) && parentDeclId >= 0)
            {
                for (int ci = 0; ci < ast.Types.Count; ci++)
                {
                    TypeDecl ctd = ast.Types[ci];
                    if (ctd.OwnerDeclId == parentDeclId && ctd.NameId == n.B && ctd.TypeParamCount == n.D)
                    {
                        declId = ci;
                        InstantiateResolvedStaticTarget(declId, n.C, n.D, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out concreteTypeId);
                        return true;
                    }
                }
                return false;
            }
            if (diags.Items.Count > diagSave) return false;

            // 2. Namespace-qualified type (`System.Console`, `global::System.Console`, `Vibranium.Prelude`, `Vibranium.Std.Bytes`, `Alias.MyType`)
            var nsPath = new StringBuf(48);
            if (TryBuildNamespaceExprPath(n.A, -1, in fctx, in ast, in ta, in names, in bctx, in types, ref nsPath, out bool rootedGlobal))
            {
                ReadOnlySpan<byte> nsSpan = nsPath.AsUtf8();
                int nsId = FindInternedText(nsSpan, in names);
                if (nsId >= 0)
                {
                    int qDecl = rootedGlobal
                        ? DeclBinder.FindDeclaredTypeInExactNamespace(n.B, n.D, nsId, callerUnit, in ast, in bctx)
                        : DeclBinder.LookupQualifiedTypeDecl(n.B, n.D, nsId, callerUnit, curNs, curOwner, uStart, uCount, in ast, in names, in bctx);
                    if (qDecl >= 0)
                    {
                        declId = qDecl;
                        InstantiateResolvedStaticTarget(declId, n.C, n.D, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out concreteTypeId);
                        return true;
                    }
                }
                if (n.D == 0 && Bytes.Eq(nsSpan, "System"u8))
                {
                    ReadOnlySpan<byte> rnm = names.Text(n.B);
                    if (n.B == bctx.IdObject || Bytes.Eq(rnm, "Object"u8))
                    {
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[n.TokIdx], "'System.Object' type is banned in Vibranium."u8);
                        return true;
                    }
                    if (IsBuiltinSystemStaticTargetName(rnm, n.B, in bctx))
                    {
                        return true;
                    }
                }
                if (n.D == 0 && Bytes.Eq(nsSpan, "Vibranium"u8) && IsBuiltinVibraniumStaticTargetName(n.B, in bctx))
                {
                    return true;
                }
            }
            return false;
        }

        if (n.Kind != AstKind.ExprIdent) return false;

        // Lowercase C# primitive type keyword before `.` (`int.TryParse`, `int.MaxValue`, `string.Empty`, `object.Equals`)
        if (n.D == 2)
        {
            if (n.A == bctx.IdObject)
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[n.TokIdx], "'object' type is banned in Vibranium."u8);
            }
            return true;
        }

        // `global::TypeName`
        if (n.D == 1)
        {
            if (callerUnit == UnitKinds.App)
            {
                Option<int> gOpt = bctx.AppGlobalTypeByNameArity.Get(DeclBinder.PackNameArity(n.A, n.C));
                if (gOpt.IsSome)
                {
                    declId = gOpt.Unwrap();
                    InstantiateResolvedStaticTarget(declId, n.B, n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out concreteTypeId);
                    return true;
                }
            }
            return false;
        }

        if (n.C == 0)
        {
            for (int tp = 0; tp < fctx.TpNames.Count; tp++)
            {
                if (fctx.TpNames[tp] == n.A) return false;
            }
        }

        // Unqualified identifier: locals, parameters, consts, and instance fields shadow types EXCEPT C# §12.8.7.2 (`Color.Red` when variable `Color` has type `Color`)!
        int foundVar = fctx.FindVar(n.A, out bool isConstVar, out int constVarTid, out _);
        int instFieldIdx = (foundVar < 0 && foundVar != -2 && !isConstVar && fctx.OwnerTypeId >= 0)
            ? FindInstanceFieldIndex(fctx.OwnerTypeId, n.A, in types)
            : -1;
        if (foundVar >= 0 || foundVar == -2 || isConstVar || instFieldIdx >= 0)
        {
            if (n.C != 0 || memberHintNameId < 0) return false;
            int shadowVarTid;
            if (isConstVar || foundVar == -2)
            {
                shadowVarTid = constVarTid;
            }
            else if (foundVar >= 0)
            {
                shadowVarTid = fctx.Locals[foundVar].TypeId;
                if (shadowVarTid >= 0 && (types.Items[shadowVarTid].Kind == TypeKinds.Ref || types.Items[shadowVarTid].Kind == TypeKinds.RefReadOnly))
                {
                    shadowVarTid = types.Items[shadowVarTid].A;
                }
            }
            else
            {
                shadowVarTid = types.Fields[types.Items[fctx.OwnerTypeId].FieldStart + instFieldIdx].TypeId;
            }
            if (shadowVarTid < 0) return false;

            TypeInfo svti = types.Items[shadowVarTid];
            if ((svti.Kind == TypeKinds.Enum || svti.Kind == TypeKinds.Struct || svti.Kind == TypeKinds.Class) && svti.C == 0)
            {
                int candDecl = DeclBinder.LookupUnqualifiedTypeDecl(n.A, 0, callerUnit, curNs, curOwner, uStart, uCount, in ast, in names, in bctx);
                if (candDecl >= 0 && candDecl == svti.A &&
                    !TypeHasInstanceMemberNamed(shadowVarTid, candDecl, memberHintNameId, isMethodCallHint, ref fctx, in ast, in names, in bctx, in types))
                {
                    declId = candDecl;
                    concreteTypeId = shadowVarTid;
                    return true;
                }
            }
            if (DeclBinder.TryMapSystemPrimTypeName(names.Text(n.A), out int sysPrimTid) && sysPrimTid == shadowVarTid)
            {
                if (!(shadowVarTid == TypeIds.Str && (memberHintNameId == bctx.IdAsUtf8 || memberHintNameId == bctx.IdLines || Bytes.Eq(names.Text(memberHintNameId), "Length"u8))))
                {
                    declId = -1;
                    concreteTypeId = shadowVarTid;
                    return true;
                }
            }
            return false;
        }

        // Nested types on enclosing owner chain first
        for (int od = curOwner; od >= 0; od = ast.Types[od].OwnerDeclId)
        {
            for (int ti = 0; ti < ast.Types.Count; ti++)
            {
                TypeDecl td = ast.Types[ti];
                if (td.OwnerDeclId == od && td.NameId == n.A && td.TypeParamCount == n.C)
                {
                    declId = ti;
                    InstantiateResolvedStaticTarget(declId, n.B, n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out concreteTypeId);
                    return true;
                }
            }
        }

        ReadOnlySpan<byte> nm = names.Text(n.A);
        if (callerUnit == UnitKinds.App)
        {
            int rk = DeclBinder.ResolveAppUnqualifiedName(n.A, n.C, curNs, curOwner, uStart, uCount, in ast, in names, in bctx, out int fDecl, out int fAliasIdx, out bool mSys, out bool mVib);
            if (rk == -2)
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[n.TokIdx], "Ambiguous reference between imported namespaces."u8);
                concreteTypeId = TypeIds.Error;
                return true;
            }
            if (rk == 1 && fDecl >= 0)
            {
                declId = fDecl;
                InstantiateResolvedStaticTarget(declId, n.B, n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out concreteTypeId);
                return true;
            }
            if (rk == 2 && fAliasIdx >= 0 && fAliasIdx < bctx.UsingBoundKind.Count)
            {
                int bk = bctx.UsingBoundKind[fAliasIdx];
                int bid = bctx.UsingBoundId[fAliasIdx];
                int btid = bctx.UsingBoundTypeId[fAliasIdx];
                if (bk == 2 && bid >= 0)
                {
                    declId = bid;
                    if (btid >= 0)
                    {
                        concreteTypeId = btid;
                    }
                    else
                    {
                        InstantiateResolvedStaticTarget(declId, n.B, 0, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out concreteTypeId);
                    }
                    return true;
                }
                if (bk == 3)
                {
                    declId = -1;
                    concreteTypeId = btid > 0 ? btid : -1;
                    return true;
                }
                return false;
            }
            if (rk == 3)
            {
                if (!mSys && !mVib && fDecl >= 0)
                {
                    declId = fDecl;
                    InstantiateResolvedStaticTarget(declId, n.B, n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out concreteTypeId);
                    return true;
                }
                if (mSys)
                {
                    if (n.C == 0 && (n.A == bctx.IdObject || Bytes.Eq(nm, "Object"u8)))
                    {
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[n.TokIdx], "'System.Object' type is banned in Vibranium."u8);
                        return true;
                    }
                    if ((n.C == 0 && (IsBuiltinSystemStaticTargetName(nm, n.A, in bctx) || n.A == bctx.IdIDisposable)) ||
                        (n.C == 1 && (n.A == bctx.IdSpan || n.A == bctx.IdReadOnlySpan || n.A == bctx.IdNullable)))
                    {
                        if (n.C == 0 && DeclBinder.TryMapSystemPrimTypeName(nm, out int sPrim))
                        {
                            concreteTypeId = sPrim;
                        }
                        return true;
                    }
                    return false;
                }
                if (mVib)
                {
                    if ((n.C == 0 && IsBuiltinVibraniumStaticTargetName(n.A, in bctx)) ||
                        (n.C == 1 && (n.A == bctx.IdOption || n.A == bctx.IdOptionRef || n.A == bctx.IdOptionMut || n.A == bctx.IdVec || n.A == bctx.IdSome || n.A == bctx.IdOk || n.A == bctx.IdErr)) ||
                        (n.C == 2 && n.A == bctx.IdResult))
                    {
                        return true;
                    }
                    return false;
                }
            }
            return false;
        }

        int stdDecl = DeclBinder.LookupUnqualifiedTypeDecl(n.A, n.C, callerUnit, curNs, curOwner, uStart, uCount, in ast, in names, in bctx);
        if (stdDecl >= 0)
        {
            declId = stdDecl;
            InstantiateResolvedStaticTarget(declId, n.B, n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out concreteTypeId);
            return true;
        }
        if (n.C == 0 && (n.A == bctx.IdObject || Bytes.Eq(nm, "Object"u8)))
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[n.TokIdx], "'System.Object' type is banned in Vibranium."u8);
            return true;
        }
        if ((n.C == 0 && (IsBuiltinSystemStaticTargetName(nm, n.A, in bctx) || IsBuiltinVibraniumStaticTargetName(n.A, in bctx) || n.A == bctx.IdIDisposable)) ||
            (n.C == 1 && (n.A == bctx.IdSpan || n.A == bctx.IdReadOnlySpan || n.A == bctx.IdNullable || n.A == bctx.IdOption || n.A == bctx.IdOptionRef || n.A == bctx.IdOptionMut || n.A == bctx.IdVec || n.A == bctx.IdSome || n.A == bctx.IdOk || n.A == bctx.IdErr)) ||
            (n.C == 2 && n.A == bctx.IdResult))
        {
            return true;
        }
        return false;
    }

    private static bool TryResolveUsingStaticValueMember(
        int memberNameId,
        int tokIdx,
        bool reportAmbiguity,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        ref DiagnosticBag diags,
        out int resolvedKind,
        out int resolvedOwnerDeclId,
        out int resolvedOwnerTypeId,
        out int resolvedFieldOffset,
        out int resolvedPropGetId,
        out int resolvedPropSetId,
        out bool wasAmbiguous,
        out int resolvedBuiltinTypeId,
        out long resolvedBuiltinBits,
        out bool resolvedBuiltinIsFloat)
    {
        resolvedKind = 0; // 1 = const/enum field, 2 = static property, 3 = builtin const/property
        resolvedOwnerDeclId = -1;
        resolvedOwnerTypeId = -1;
        resolvedFieldOffset = -1;
        resolvedPropGetId = -1;
        resolvedPropSetId = -1;
        wasAmbiguous = false;
        resolvedBuiltinTypeId = TypeIds.Error;
        resolvedBuiltinBits = 0;
        resolvedBuiltinIsFloat = false;

        GetActiveUsingSlice(-1, tokIdx, in fctx, in ast, in ta, out int callerUnit, out int curNs, out int callerOwner, out int uStart, out int uCount);
        if (callerUnit != UnitKinds.App || uCount <= 0) return false;

        int propGetLookup = MakePropGetterLookup(memberNameId, in ast, in names);
        var setBuf = new StringBuf(32);
        setBuf.Append("set_"u8);
        setBuf.Append(names.Text(memberNameId));
        int propSetLookup = FindInternedText(setBuf.AsUtf8(), in names);
        ReadOnlySpan<byte> memText = names.Text(memberNameId);

        int step = 0;
        while (DeclBinder.TryStepEnclosingNamespace(curNs, ref step, in ast, in names, out int nsCursor))
        {
            var seenKeys = new Vec<long>(4);
            int matchCount = 0;
            bool seenExplicitPrelude = false;

            for (int u = 0; u < uCount; u++)
            {
                int uIdx = ast.Extra[uStart + u];
                if (uIdx < 0 || uIdx >= bctx.UsingBoundKind.Count) continue;
                UsingEntry ue = ast.Usings[uIdx];
                if (ue.Kind != UsingKinds.Static || ue.EnclosingNsId != nsCursor) continue;

                int bk = bctx.UsingBoundKind[uIdx];
                if (bk == 2)
                {
                    int stDeclId = bctx.UsingBoundId[uIdx];
                    int stTid = bctx.UsingBoundTypeId[uIdx];
                    if (stDeclId < 0) continue;
                    long key = ((long)stDeclId << 32) | (uint)(stTid + 1);
                    bool dup = false;
                    for (int s = 0; s < seenKeys.Count; s++)
                    {
                        if (seenKeys[s] == key) { dup = true; break; }
                    }
                    if (dup) continue;
                    seenKeys.Push(key);

                    TypeDecl td = ast.Types[stDeclId];
                    bool sameOrNested = IsSameOrNestedInsideType(callerOwner, stDeclId, in ast);
                    bool foundOnType = false;
                    for (int f = 0; f < td.FieldCount; f++)
                    {
                        FieldDecl fd = ast.Fields[td.FieldStart + f];
                        if (fd.NameId == memberNameId && (fd.Flags & DeclFlags.IsConst) != 0)
                        {
                            bool vis = td.Kind == TypeDeclKinds.Enum || sameOrNested ||
                                ((fd.Flags & DeclFlags.Private) == 0 && ((fd.Flags & DeclFlags.Public) != 0 || ((fd.Flags & DeclFlags.Internal) != 0 && (bctx.CompilingStdItself || td.UnitKind == callerUnit))));
                            if (vis)
                            {
                                foundOnType = true;
                                matchCount += 1;
                                if (matchCount == 1)
                                {
                                    resolvedKind = 1;
                                    resolvedOwnerDeclId = stDeclId;
                                    resolvedOwnerTypeId = stTid;
                                    resolvedFieldOffset = f;
                                }
                                break;
                            }
                        }
                    }
                    if (!foundOnType && (td.TypeParamCount == 0 || stTid >= 0))
                    {
                        int pGet = propGetLookup >= 0 ? FindMethodInType(stDeclId, propGetLookup, 0, isStatic: true, in ast) : -1;
                        int pSet = propSetLookup >= 0 ? FindMethodInType(stDeclId, propSetLookup, 1, isStatic: true, in ast) : -1;
                        bool getVis = pGet >= 0 && IsAccessibleFuncFromCaller(pGet, ref fctx, in ast, in bctx);
                        bool setVis = pSet >= 0 && IsAccessibleFuncFromCaller(pSet, ref fctx, in ast, in bctx);
                        if (getVis || setVis)
                        {
                            matchCount += 1;
                            if (matchCount == 1)
                            {
                                resolvedKind = 2;
                                resolvedOwnerDeclId = stDeclId;
                                resolvedOwnerTypeId = stTid;
                                resolvedPropGetId = getVis ? pGet : -1;
                                resolvedPropSetId = setVis ? pSet : -1;
                            }
                        }
                    }
                }
                else if (bk == 3)
                {
                    int bId = bctx.UsingBoundId[uIdx];
                    int bTid = bctx.UsingBoundTypeId[uIdx];
                    long key = -1000000L + ((long)bId << 16) + bTid;
                    bool dup = false;
                    for (int s = 0; s < seenKeys.Count; s++)
                    {
                        if (seenKeys[s] == key) { dup = true; break; }
                    }
                    if (dup) continue;
                    seenKeys.Push(key);

                    if (bId == BuiltinStaticIds.Prelude)
                    {
                        seenExplicitPrelude = true;
                        if (memberNameId == bctx.IdNone)
                        {
                            matchCount += 1;
                            if (matchCount == 1)
                            {
                                resolvedKind = 3;
                                resolvedBuiltinTypeId = TypeIds.NoneUnit;
                                resolvedBuiltinBits = 0;
                                resolvedBuiltinIsFloat = false;
                            }
                        }
                    }
                    else if (bTid == TypeIds.Str && Bytes.Eq(memText, "Empty"u8))
                    {
                        matchCount += 1;
                        if (matchCount == 1)
                        {
                            resolvedKind = 3;
                            resolvedBuiltinTypeId = TypeIds.Str;
                            resolvedBuiltinBits = 0;
                            resolvedBuiltinIsFloat = false;
                        }
                    }
                    else if (bTid > 0 && DeclBinder.TryEvalBuiltinNumericConstMember(DeclBinder.PrimTypeIdBuiltinName(bTid), memText, out int pTid, out long pBits, out bool pIsFloat))
                    {
                        matchCount += 1;
                        if (matchCount == 1)
                        {
                            resolvedKind = 3;
                            resolvedBuiltinTypeId = pTid;
                            resolvedBuiltinBits = pBits;
                            resolvedBuiltinIsFloat = pIsFloat;
                        }
                    }
                }
            }

            if (nsCursor == -1 && memberNameId == bctx.IdNone && matchCount > 0 && !seenExplicitPrelude)
            {
                // `Prelude.None` is also imported at compilation-unit level
                matchCount += 1;
            }

            if (matchCount > 1)
            {
                wasAmbiguous = true;
                if (reportAmbiguity && fctx.InferDepth == 0)
                {
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Ambiguous member reference across 'using static' imports."u8);
                }
                return true;
            }
            if (matchCount == 1)
            {
                return true;
            }
        }

        return false;
    }

    private static bool TryResolveUsingStaticMethodCall(
        int calleeNameId,
        int explicitTaStart,
        int explicitTaCount,
        int callArgStart,
        int callArgCount,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        out int bestFuncDeclOrIntrinsic,
        out int bestOwnerTypeId,
        out bool isAmbiguous,
        out int resolvedRetTypeId)
    {
        bestFuncDeclOrIntrinsic = -1;
        bestOwnerTypeId = -1;
        isAmbiguous = false;
        resolvedRetTypeId = TypeIds.Void;

        GetActiveUsingSlice(-1, tokIdx, in fctx, in ast, in ta, out int callerUnit, out int curNs, out _, out int uStart, out int uCount);
        if (callerUnit != UnitKinds.App) return false;

        int step = 0;
        while (DeclBinder.TryStepEnclosingNamespace(curNs, ref step, in ast, in names, out int nsCursor))
        {
            var seenKeys = new Vec<long>(4);
            var tierCands = new Vec<int>(8);
            var tierOwnerTids = new Vec<int>(8);
            bool hasUsingStaticAtTier = false;
            bool tierHasPrelude = false;

            for (int u = 0; u < uCount; u++)
            {
                int uIdx = ast.Extra[uStart + u];
                if (uIdx < 0 || uIdx >= bctx.UsingBoundKind.Count) continue;
                UsingEntry ue = ast.Usings[uIdx];
                if (ue.Kind != UsingKinds.Static || ue.EnclosingNsId != nsCursor) continue;

                int bk = bctx.UsingBoundKind[uIdx];
                if (bk == 2)
                {
                    int stDeclId = bctx.UsingBoundId[uIdx];
                    int stTid = bctx.UsingBoundTypeId[uIdx];
                    if (stDeclId < 0 || (ast.Types[stDeclId].TypeParamCount > 0 && stTid < 0)) continue;
                    long key = ((long)stDeclId << 32) | (uint)(stTid + 1);
                    bool dup = false;
                    for (int s = 0; s < seenKeys.Count; s++)
                    {
                        if (seenKeys[s] == key) { dup = true; break; }
                    }
                    if (dup) continue;
                    seenKeys.Push(key);
                    hasUsingStaticAtTier = true;
                    int prevCount = tierCands.Count;
                    CollectTypeMethodCandidates(stDeclId, calleeNameId, allowInstance: false, allowStatic: true, isCtor: false, ref fctx, in ast, in bctx, ref tierCands);
                    for (int c = prevCount; c < tierCands.Count; c++)
                    {
                        tierOwnerTids.Push(ast.Types[stDeclId].TypeParamCount > 0 ? stTid : -1);
                    }
                }
                else if (bk == 3 && bctx.UsingBoundId[uIdx] == BuiltinStaticIds.Prelude)
                {
                    hasUsingStaticAtTier = true;
                    tierHasPrelude = true;
                }
            }

            if (nsCursor == -1)
            {
                if (bctx.HasStdUnit)
                {
                    Option<int> cioOpt = bctx.StdTypeByNameArity.Get(DeclBinder.PackNameArity(bctx.IdConsoleIo, 0));
                    if (cioOpt.IsSome)
                    {
                        int cioDecl = cioOpt.Unwrap();
                        long cioKey = ((long)cioDecl << 32) | (uint)0;
                        bool dupCio = false;
                        for (int s = 0; s < seenKeys.Count; s++)
                        {
                            if (seenKeys[s] == cioKey) { dupCio = true; break; }
                        }
                        if (!dupCio)
                        {
                            int prevCio = tierCands.Count;
                            CollectTypeMethodCandidates(cioDecl, calleeNameId, allowInstance: false, allowStatic: true, isCtor: false, ref fctx, in ast, in bctx, ref tierCands);
                            for (int c = prevCio; c < tierCands.Count; c++) tierOwnerTids.Push(-1);
                        }
                    }
                }
                int bestCu = ResolveBestOverloadWithOwners(tierCands.AsReadOnlySpan(), tierOwnerTids.AsReadOnlySpan(), -1, explicitTaStart, explicitTaCount, callArgStart, callArgCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out isAmbiguous, out resolvedRetTypeId, out bestOwnerTypeId, includePreludeCompetitors: true, preludeCalleeNameId: calleeNameId);
                if (isAmbiguous || bestCu != -1)
                {
                    bestFuncDeclOrIntrinsic = bestCu;
                    return true;
                }
                return false;
            }

            if (hasUsingStaticAtTier && (tierCands.Count > 0 || tierHasPrelude))
            {
                int bestInner = ResolveBestOverloadWithOwners(tierCands.AsReadOnlySpan(), tierOwnerTids.AsReadOnlySpan(), -1, explicitTaStart, explicitTaCount, callArgStart, callArgCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out isAmbiguous, out resolvedRetTypeId, out bestOwnerTypeId, includePreludeCompetitors: tierHasPrelude, preludeCalleeNameId: calleeNameId);
                if (isAmbiguous || bestInner != -1)
                {
                    bestFuncDeclOrIntrinsic = bestInner;
                    return true;
                }
            }
        }

        return false;
    }

    // C# natural type of `c ? e1 : e2` (§12.18, as Roslyn computes it): a
    // branch type is a candidate when the other branch expression converts to
    // it implicitly (constant conversions included); of two candidates the
    // better one is the type the other candidate converts to. A typeless or
    // erroneous branch defers to the other type. -1 means no natural type: the
    // conditional is then only valid where a target type converts both branches.
    private static int NaturalConditionalType(
        int t1,
        int expr1,
        int t2,
        int expr2,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags)
    {
        bool typed1 = t1 >= 0 && t1 != TypeIds.Error && t1 != TypeIds.Void;
        bool typed2 = t2 >= 0 && t2 != TypeIds.Error && t2 != TypeIds.Void;
        if (!typed1 && !typed2) return TypeIds.Error;
        if (!typed1)
            return ClassifyImplicitExpressionConversion(expr1, t1, t2, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) >= 0 ? t2 : -1;
        if (!typed2)
            return ClassifyImplicitExpressionConversion(expr2, t2, t1, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) >= 0 ? t1 : -1;
        if (t1 == t2) return t1;
        bool candidate1 = ClassifyByValueConversionWithCtx(expr2, t2, t1, in fctx, in names, in bctx, in ast, in ta, in types) >= 0;
        bool candidate2 = ClassifyByValueConversionWithCtx(expr1, t1, t2, in fctx, in names, in bctx, in ast, in ta, in types) >= 0;
        if (candidate1 && candidate2)
        {
            bool oneToTwo = ClassifyByValueConversion(-1, t1, t2, in ast, in ta, in types) >= 0;
            bool twoToOne = ClassifyByValueConversion(-1, t2, t1, in ast, in ta, in types) >= 0;
            if (oneToTwo && !twoToOne) return t2;
            if (twoToOne && !oneToTwo) return t1;
            return -1;
        }
        if (candidate1) return t1;
        if (candidate2) return t2;
        return -1;
    }

    private static void PushSpeculativeSwitchArmBindings(in AstNode arm, int swScrutT, ref FuncLowerCtx fctx,
        in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        var armPats = new Vec<VarBinding>();
        CollectSpeculativePatternBindings(arm.A, swScrutT, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref armPats);
        for (int p = 0; p < armPats.Count; p++) fctx.Vars.Push(armPats[p]);
        if (arm.C >= 0)
        {
            var wgT = new Vec<VarBinding>();
            var wgF = new Vec<VarBinding>();
            InferCondBranchSpeculative(arm.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref wgT, ref wgF);
            for (int p = 0; p < wgT.Count; p++) fctx.Vars.Push(wgT[p]);
            for (int p = 0; p < wgF.Count; p++) fctx.Vars.Push(wgF[p]);
        }
    }

    // Best common type is one of the typed arm expressions, not an invented
    // Option/Result lift or the enclosing assignment's target. Compare each
    // viable candidate against the others by standard implicit conversion.
    private static int InferSwitchNaturalType(int exprId, in AstNode n, ref FuncLowerCtx fctx, in AstArena ast,
        in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        fctx.InferDepth += 1;
        int scopeStart = fctx.Vars.Count;
        int swScrutT = InferExprType(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        int slot = fctx.BranchFactsFor(exprId, n.C);
        var candidates = new Vec<int>();
        for (int i = 0; i < n.C; i++)
        {
            AstNode arm = ast.Nodes[ast.Extra[n.B + i]];
            int savedArmVars = fctx.Vars.Count;
            PushSpeculativeSwitchArmBindings(in arm, swScrutT, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            int armScopeEnd = fctx.Vars.Count;
            int at = InferExprType(arm.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            fctx.RecordBranchArm(slot + i, at, scopeStart, armScopeEnd);
            fctx.Vars.Truncate(savedArmVars);
            if (at < 0 || at == TypeIds.Error || at == TypeIds.Void) continue;
            bool seen = false;
            for (int j = 0; j < candidates.Count; j++) if (candidates[j] == at) seen = true;
            if (!seen) candidates.Push(at);
        }
        int best = -1;
        bool ambiguous = false;
        for (int i = 0; i < candidates.Count; i++)
        {
            int candidate = candidates[i];
            if (ClassifyBranchArmConversions(exprId, in n, candidate, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) < 0) continue;
            if (best < 0 || ClassifyByValueConversion(-1, best, candidate, in ast, in ta, in types) >= 0)
            {
                best = candidate;
                ambiguous = false;
            }
            else if (ClassifyByValueConversion(-1, candidate, best, in ast, in ta, in types) < 0) ambiguous = true;
        }
        fctx.LeaveSpeculativeInfer();
        return ambiguous ? -1 : best;
    }

    // Types an operand whose type the caller does not need, so that the
    // variables it declares are on the binding stack for the rest of the
    // expression (C# scope, N111).
    private static void InferOperandDeclarations(int exprId, ref FuncLowerCtx fctx, in AstArena ast,
        in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        if (exprId < 0 || fctx.ElementRetypeDepth > 0) return;
        AstNode n = ast.Nodes[exprId];
        if (n.Kind == AstKind.ExprRange)
        {
            InferOperandDeclarations(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            InferOperandDeclarations(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        }
        else if (n.Kind == AstKind.ExprFromEnd) InferOperandDeclarations(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        else _ = InferExprType(exprId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
    }

    // The same for an argument list that no overload resolution types. An out
    // argument declares its variable with the type it names.
    private static void InferArgumentDeclarations(int argStart, int argCount, ref FuncLowerCtx fctx, in AstArena ast,
        in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        if (fctx.ElementRetypeDepth > 0) return;
        for (int a = 0; a < argCount; a++)
        {
            AstNode arg = ast.Nodes[ast.Extra[argStart + a]];
            if (CallArgBits.Mode(in arg) != PassMode.Out) InferOperandDeclarations(arg.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            else if (arg.C >= 0)
            {
                int declared = DeclBinder.ResolveTypeNode(arg.C, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                PushSpeculativeOutArg(in arg, declared, ref fctx);
            }
        }
    }

    // Types a receiver at lowering time. `declares` says that it declares out or
    // pattern variables: C# keeps them in scope in the member's argument list,
    // so the caller resolves the member inside EnterReceiverScope (N110).
    private static int InferReceiverType(int recvExprId, out bool declares, ref FuncLowerCtx fctx, in AstArena ast,
        in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        fctx.InferDepth += 1;
        int mark = fctx.Vars.Count;
        int type = InferExprType(recvExprId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        declares = fctx.Vars.Count > mark;
        fctx.LeaveSpeculativeInfer();
        return type;
    }

    // Types the receiver again when it declares variables, which leaves them on
    // the binding stack; the caller ends the scope with LeaveSpeculativeInfer.
    private static void EnterReceiverScope(int recvExprId, bool declares, ref FuncLowerCtx fctx, in AstArena ast,
        in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        fctx.InferDepth += 1;
        if (declares) _ = InferExprType(recvExprId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
    }

    // Whether every arm of a conditional or switch expression converts
    // implicitly to targetType, from the arm types and scopes that the last
    // natural-type inference of the expression recorded. It infers nothing.
    private static int ClassifyBranchArmConversions(int exprId, in AstNode n, int targetType, ref FuncLowerCtx fctx,
        in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        bool isCond = n.Kind == AstKind.ExprCond;
        int armCount = isCond ? 2 : n.C;
        int entry = fctx.BranchFactSlots.Find(exprId);
        if (entry < 0)
        {
            // Every caller infers the natural type first; this keeps the answer right if one does not.
            _ = InferExprType(exprId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            entry = fctx.BranchFactSlots.Find(exprId);
        }
        int slot = fctx.BranchFactSlots.ValueAt(entry);
        for (int i = 0; i < armCount; i++)
        {
            int armExpr = isCond ? (i == 0 ? n.B : n.C) : ast.Nodes[ast.Extra[n.B + i]].B;
            BranchArmFact arm = fctx.BranchArmFacts[slot + i];
            int mark = fctx.Vars.Count;
            for (int p = 0; p < arm.ScopeCount; p++) fctx.Vars.Push(fctx.BranchArmScopes[arm.ScopeStart + p]);
            int conversion = ClassifyImplicitExpressionConversionCore(armExpr, arm.TypeId, targetType,
                ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            fctx.Vars.Truncate(mark);
            if (conversion < 0) return -1;
        }
        return armCount > 0 ? 1 : -1;
    }

    private static int MergeCommonBranchType(
        int t1,
        int expr1,
        int t2,
        int expr2,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        ref TypeTable types)
    {
        if (t1 < 0 || t1 == TypeIds.Error) return t2;
        if (t2 < 0 || t2 == TypeIds.Error) return t1;
        if (t1 == t2) return t1;

        TypeInfo i1 = types.Items[t1];
        TypeInfo i2 = types.Items[t2];

        if (t1 == TypeIds.NoneUnit)
        {
            if (i2.Kind == TypeKinds.SomeWrap) return types.MakeOption(i2.A);
            if (i2.Kind == TypeKinds.Option) return t2;
            return t2;
        }
        if (t2 == TypeIds.NoneUnit)
        {
            if (i1.Kind == TypeKinds.SomeWrap) return types.MakeOption(i1.A);
            if (i1.Kind == TypeKinds.Option) return t1;
            return t1;
        }
        if (i1.Kind == TypeKinds.Option && i2.Kind == TypeKinds.SomeWrap && i1.A == i2.A) return t1;
        if (i2.Kind == TypeKinds.Option && i1.Kind == TypeKinds.SomeWrap && i1.A == i2.A) return t2;

        if (i1.Kind == TypeKinds.OkWrap && i2.Kind == TypeKinds.ErrWrap) return types.MakeResult(i1.A, i2.A);
        if (i1.Kind == TypeKinds.ErrWrap && i2.Kind == TypeKinds.OkWrap) return types.MakeResult(i2.A, i1.A);
        if (i1.Kind == TypeKinds.Result && ((i2.Kind == TypeKinds.OkWrap && i2.A == i1.A) || (i2.Kind == TypeKinds.ErrWrap && i2.A == i1.B))) return t1;
        if (i2.Kind == TypeKinds.Result && ((i1.Kind == TypeKinds.OkWrap && i1.A == i2.A) || (i1.Kind == TypeKinds.ErrWrap && i1.A == i2.B))) return t2;

        if (i1.Kind == TypeKinds.Span && i2.Kind == TypeKinds.ReadOnlySpan && i1.A == i2.A) return t2;
        if (i1.Kind == TypeKinds.ReadOnlySpan && i2.Kind == TypeKinds.Span && i1.A == i2.A) return t1;

        int curOwner = fctx.EnclosingOwnerDeclId;
        if (i1.Kind == TypeKinds.Enum && expr2 >= 0 && IsZeroNumericConstExpr(expr2, curOwner, in fctx, in ast, in ta, in names, in bctx, in types)) return t1;
        if (i2.Kind == TypeKinds.Enum && expr1 >= 0 && IsZeroNumericConstExpr(expr1, curOwner, in fctx, in ast, in ta, in names, in bctx, in types)) return t2;

        if (CanImplicitNumericWiden(t1, t2)) return t2;
        if (CanImplicitNumericWiden(t2, t1)) return t1;

        if (expr2 >= 0 && ClassifyByValueConversionWithCtx(expr2, t2, t1, in fctx, in names, in bctx, in ast, in ta, in types) >= 0) return t1;
        if (expr1 >= 0 && ClassifyByValueConversionWithCtx(expr1, t1, t2, in fctx, in names, in bctx, in ast, in ta, in types) >= 0) return t2;

        return t1;
    }

    private static int ReserveReceiverPlace(int recvPlaceId, int recvTypeId, bool isMut, bool isTwoPhase, int tokIdx, ref FuncLowerCtx fctx, ref MirModuleArena mir) => ReserveReceiverPlace(recvPlaceId, recvTypeId, isMut, isTwoPhase, tokIdx, ref fctx, ref mir, false);

    private static int ReserveReceiverPlace(
        int recvPlaceId,
        int recvTypeId,
        bool isMut,
        bool isTwoPhase,
        int tokIdx,
        ref FuncLowerCtx fctx,
        ref MirModuleArena mir,
        bool isAssignmentTargetSnapshot)
    {
        int resRefTmp = fctx.NewTempRef(recvTypeId, isMut, tokIdx);
        int flags = (isMut ? 1 : 0) | (isTwoPhase ? 2 : 0) | (isAssignmentTargetSnapshot ? 4 : 0);
        fctx.Emit(new MirInst(MirOp.BindRef, -1, resRefTmp, flags, recvTypeId, resRefTmp, recvPlaceId, 0, 0, tokIdx));
        var deref = new Vec<MirProj>(1);
        deref.Push(new MirProj(MirProjKinds.Deref, 0, recvTypeId, -1, 0));
        return mir.AddPlace(resRefTmp, deref.AsReadOnlySpan(), recvTypeId);
    }

    private static bool IsNamespaceChainExpr(
        int exprId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types)
    {
        AstNode n = ast.Nodes[exprId];
        if (n.Kind == AstKind.ExprIdent)
        {
            int fv = fctx.FindVar(n.A, out bool isC, out _, out _);
            if (fv >= 0 || isC) return false;
            if (fctx.OwnerTypeId >= 0 && FindInstanceFieldIndex(fctx.OwnerTypeId, n.A, in types) >= 0) return false;
            ReadOnlySpan<byte> txt = names.Text(n.A);
            return Bytes.Eq(txt, "Vibranium"u8) || Bytes.Eq(txt, "System"u8);
        }
        if (n.Kind == AstKind.ExprMember)
        {
            return IsNamespaceChainExpr(n.A, ref fctx, in ast, in names, in bctx, in types);
        }
        return false;
    }


    private static bool HasUserIntLengthOrCount(
        int ownerTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        out int getterFuncDeclId,
        out int fieldIdx)
    {
        getterFuncDeclId = -1;
        fieldIdx = -1;
        TypeInfo ti = types.Items[ownerTypeId];
        if (ti.Kind != TypeKinds.Struct && ti.Kind != TypeKinds.Class) return false;

        var subNames = new Vec<int>();
        var subVals = new Vec<int>();
        BuildOwnerTypeSubst(ownerTypeId, in ast, in types, ref subNames, ref subVals);

        // Prefer `Length`, then `Count`
        for (int pass = 0; pass < 2; pass++)
        {
            int propGetId = pass == 0 ? bctx.IdGetLength : bctx.IdGetCount;
            int fldNameId = pass == 0 ? bctx.IdLength : bctx.IdCount;

            int gId = FindMethodInType(ti.A, propGetId, 0, isStatic: false, in ast);
            if (gId >= 0 && IsAccessibleFuncFromCaller(gId, ref fctx, in ast, in bctx))
            {
                int retT = DeclBinder.ResolveTypeNode(ast.Funcs[gId].RetTypeNode, subNames.AsReadOnlySpan(), subVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                if (retT == TypeIds.I32)
                {
                    getterFuncDeclId = gId;
                    return true;
                }
            }

            int fIdx = FindInstanceFieldIndex(ownerTypeId, fldNameId, in types);
            if (fIdx >= 0 && types.Fields[ti.FieldStart + fIdx].TypeId == TypeIds.I32)
            {
                int fFlags = types.Fields[ti.FieldStart + fIdx].Flags;
                int callerOwner = ast.Funcs[fctx.FuncDeclId].OwnerDeclId;
                bool sameType = IsSameOrNestedInsideType(callerOwner, ti.A, in ast);
                if (sameType || (fFlags & (DeclFlags.Public | DeclFlags.Internal)) != 0)
                {
                    fieldIdx = fIdx;
                    return true;
                }
            }
        }
        return false;
    }

    private static int LowerUserLengthOrCountOnce(
        int recvPlaceId,
        int ownerTypeId,
        ref int cachedTotalOp,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        if (cachedTotalOp >= 0) return cachedTotalOp;
        if (!HasUserIntLengthOrCount(ownerTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int getterId, out int fieldIdx))
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Implicit Index ('^') / Range ('..') requires an accessible 'int Length' or 'int Count' member."u8);
            cachedTotalOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
            return cachedTotalOp;
        }
        if (getterId >= 0)
        {
            var emptyM = new Vec<int>();
            int gInst = DeclBinder.EnsureFuncInstance(getterId, ownerTypeId, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
            int callRecvPl = mir.ParamSigs[mir.FuncInstances[gInst].ParamSigStart].Mode == PassMode.ThisMut
                ? ReserveReceiverPlace(recvPlaceId, ownerTypeId, isMut: true, isTwoPhase: true, tokIdx, ref fctx, ref mir)
                : recvPlaceId;
            cachedTotalOp = EmitZeroArgInstanceCall(gInst, callRecvPl, ownerTypeId, tokIdx, ref fctx, in types, ref mir);
            return cachedTotalOp;
        }
        TypeInfo ti = types.Items[ownerTypeId];
        MirPlace basePl = mir.Places[recvPlaceId];
        var projs = new Vec<MirProj>(basePl.ProjCount + 1);
        for (int i = 0; i < basePl.ProjCount; i++) projs.Push(mir.Projs[basePl.ProjStart + i]);
        int pFlags = ti.Kind == TypeKinds.Class ? 1 : 0;
        if ((types.Fields[ti.FieldStart + fieldIdx].Flags & DeclFlags.Readonly) != 0) pFlags |= 2;
        projs.Push(new MirProj(MirProjKinds.Field, fieldIdx, TypeIds.I32, -1, pFlags));
        int fldPl = mir.AddPlace(basePl.LocalId, projs.AsReadOnlySpan(), TypeIds.I32);
        int totTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
        int totPl = mir.AddPlaceLocal(totTmp, TypeIds.I32);
        int fldOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, fldPl, 0, TypeIds.I32, tokIdx));
        fctx.Emit(new MirInst(MirOp.AssignUse, totPl, -1, 0, TypeIds.I32, fldOp, 0, 0, 0, tokIdx));
        cachedTotalOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, totPl, 0, TypeIds.I32, tokIdx));
        return cachedTotalOp;
    }

    private static int LowerUserIndexOrFromEndAsOperand(
        int idxExprId,
        int expectedIdxTypeId,
        int recvPlaceId,
        int ownerTypeId,
        ref int cachedTotalOp,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        AstNode idxNode = ast.Nodes[idxExprId];
        if (idxNode.Kind == AstKind.ExprFromEnd)
        {
            int offOp = LowerExprAsOperand(idxNode.A, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int totOp = LowerUserLengthOrCountOnce(recvPlaceId, ownerTypeId, ref cachedTotalOp, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int subTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
            int subPl = mir.AddPlaceLocal(subTmp, TypeIds.I32);
            fctx.Emit(new MirInst(MirOp.AssignBin, subPl, -1, 0, TypeIds.I32, (int)MirBinOp.Sub, totOp, offOp, 0, tokIdx));
            int resOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, subPl, 0, TypeIds.I32, tokIdx));
            return ConvertOperandIfNeeded(resOp, expectedIdxTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags);
        }
        return LowerExprAsOperand(idxExprId, expectedIdxTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
    }

    private static int FindUserSliceTwoIntMethod(
        int ownerTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags)
    {
        TypeInfo ti = types.Items[ownerTypeId];
        if (ti.Kind != TypeKinds.Struct && ti.Kind != TypeKinds.Class) return -1;
        var subNames = new Vec<int>();
        var subVals = new Vec<int>();
        BuildOwnerTypeSubst(ownerTypeId, in ast, in types, ref subNames, ref subVals);

        TypeDecl td = ast.Types[ti.A];
        for (int m = 0; m < td.FuncCount; m++)
        {
            int fId = td.FuncStart + m;
            FuncDecl fd = ast.Funcs[fId];
            if (fd.NameId == bctx.IdSlice &&
                (fd.Flags & DeclFlags.Static) == 0 &&
                fd.TypeParamCount == 0 &&
                fd.ParamCount == 2 &&
                IsAccessibleFuncFromCaller(fId, ref fctx, in ast, in bctx))
            {
                ParamDecl p0 = ast.Params[fd.ParamStart];
                ParamDecl p1 = ast.Params[fd.ParamStart + 1];
                if (p0.Mode == PassMode.ByValue && p1.Mode == PassMode.ByValue)
                {
                    int t0 = DeclBinder.ResolveTypeNode(p0.TypeNode, subNames.AsReadOnlySpan(), subVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                    int t1 = DeclBinder.ResolveTypeNode(p1.TypeNode, subNames.AsReadOnlySpan(), subVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                    if (t0 == TypeIds.I32 && t1 == TypeIds.I32)
                    {
                        return fId;
                    }
                }
            }
        }
        return -1;
    }

    private static bool CanCallWithArgCount(in FuncDecl fd, int callArgCount, in AstArena ast)
    {
        if (callArgCount > fd.ParamCount) return false;
        for (int p = callArgCount; p < fd.ParamCount; p++)
        {
            if (ast.Params[fd.ParamStart + p].DefaultExpr < 0) return false;
        }
        return true;
    }

    private static bool IsAccessibleFieldFromCaller(int ownerDeclId, int flags, in FuncLowerCtx fctx, in AstArena ast, in BinderCtx bctx)
    {
        int callerOwner = fctx.EnclosingOwnerDeclId;
        if (IsSameOrNestedInsideType(callerOwner, ownerDeclId, in ast)) return true;
        if ((flags & DeclFlags.Private) != 0 || (flags & (DeclFlags.Public | DeclFlags.Internal)) == 0) return false;
        TypeDecl owner = ast.Types[ownerDeclId];
        int callerUnit = callerOwner >= 0 ? ast.Types[callerOwner].UnitKind : UnitKinds.App;
        return bctx.CompilingStdItself || owner.UnitKind == callerUnit ||
            ((flags & DeclFlags.Public) != 0 && (owner.Flags & DeclFlags.Public) != 0);
    }

    private static bool IsAccessibleFuncFromCaller(int calleeFuncDeclId, ref FuncLowerCtx fctx, in AstArena ast, in BinderCtx bctx)
    {
        FuncDecl callee = ast.Funcs[calleeFuncDeclId];
        if ((callee.Flags & DeclFlags.IsLocalFunc) != 0 || callee.OwnerDeclId < 0) return true;
        int callerOwner = ast.Funcs[fctx.FuncDeclId].OwnerDeclId;
        if (IsSameOrNestedInsideType(callerOwner, callee.OwnerDeclId, in ast)) return true;

        bool isExplicitPublicOrInternal = (callee.Flags & (DeclFlags.Public | DeclFlags.Internal)) != 0;
        if (!isExplicitPublicOrInternal || (callee.Flags & DeclFlags.Private) != 0)
        {
            return false;
        }

        TypeDecl calleeType = ast.Types[callee.OwnerDeclId];
        int callerUnit = callerOwner >= 0 ? ast.Types[callerOwner].UnitKind : UnitKinds.App;
        if (!bctx.CompilingStdItself && calleeType.UnitKind != callerUnit)
        {
            if ((callee.Flags & DeclFlags.Public) == 0 || (calleeType.Flags & DeclFlags.Public) == 0)
            {
                return false;
            }
        }
        return true;
    }

    private static int LowerCollectionLengthOp(
        int collPlaceOrOp,
        bool isVecPlace,
        int spanTypeId,
        int tokIdx,
        ref FuncLowerCtx fctx,
        ref MirModuleArena mir)
    {
        int lenTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
        int lenPl = mir.AddPlaceLocal(lenTmp, TypeIds.I32);
        if (isVecPlace)
        {
            var pls = new Vec<int>(1);
            pls.Push(collPlaceOrOp);
            fctx.Emit(new MirInst(MirOp.Intrinsic, lenPl, -1, 0, TypeIds.I32, (int)MirIntrinsic.VecCount, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
        }
        else
        {
            int spRead = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, collPlaceOrOp, 0, spanTypeId, tokIdx));
            var ops = new Vec<int>(1);
            ops.Push(spRead);
            fctx.Emit(new MirInst(MirOp.Intrinsic, lenPl, -1, 0, TypeIds.I32, (int)MirIntrinsic.SpanLength, mir.PushIdList(ops.AsReadOnlySpan()), 1, 0, tokIdx));
        }
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, lenPl, 0, TypeIds.I32, tokIdx));
    }

    private static int LowerIndexOrFromEndAsOperand(
        int idxExprId,
        int collPlaceId,
        bool isVecPlace,
        int spanTypeId,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        AstNode idxNode = ast.Nodes[idxExprId];
        if (idxNode.Kind == AstKind.ExprFromEnd)
        {
            int offOp = LowerExprAsOperand(idxNode.A, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int totOp = LowerCollectionLengthOp(collPlaceId, isVecPlace, spanTypeId, tokIdx, ref fctx, ref mir);
            int subTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
            int subPl = mir.AddPlaceLocal(subTmp, TypeIds.I32);
            fctx.Emit(new MirInst(MirOp.AssignBin, subPl, -1, 0, TypeIds.I32, (int)MirBinOp.Sub, totOp, offOp, 0, tokIdx));
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, subPl, 0, TypeIds.I32, tokIdx));
        }
        return LowerExprAsOperand(idxExprId, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
    }

    private static int LowerPlace(
        int exprId,
        bool isMut,
        bool isTwoPhase,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        AstNode n = ast.Nodes[exprId];
        int tokIdx = n.TokIdx;

        switch (n.Kind)
        {
            case AstKind.ExprDiscard:
            {
                int dTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
                return mir.AddPlaceLocal(dTmp, TypeIds.I32);
            }

            case AstKind.ExprThis:
            {
                if (fctx.ThisLocalId >= 0)
                {
                    return mir.AddPlaceLocal(fctx.ThisLocalId, fctx.OwnerTypeId);
                }
                diags.ReportTok(VibCodes.NullOrZeroUnsafe, ta.Tokens[tokIdx], "Cannot access, capture, or call members on 'this' before constructor finishes initializing all fields."u8);
                int dummyType = fctx.OwnerTypeId >= 0 ? fctx.OwnerTypeId : TypeIds.I32;
                int dummy = fctx.NewTemp(dummyType, tokIdx, ref mir);
                int dummyPlace = mir.AddPlaceLocal(dummy, dummyType);
                // This source value is already rejected. Keep its typed recovery
                // carrier initialized so later receiver/alias use cannot invent
                // an unrelated source definite-assignment diagnostic.
                int recovery = mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, dummyType, tokIdx));
                fctx.Emit(new MirInst(MirOp.AssignUse, dummyPlace, -1, 0, dummyType, recovery, 0, 0, 0, tokIdx));
                return dummyPlace;
            }

            case AstKind.ExprIdent:
            {
                int lid = fctx.FindVar(n.A, out bool isConst, out int constTypeId, out long constVal);
                if (isConst)
                {
                    if (isMut)
                    {
                        diags.ReportTok(VibCodes.MutateSharedBorrow, ta.Tokens[tokIdx], "Cannot mutate or take mutable reference to a constant."u8);
                    }
                    int cType = constTypeId > 0 ? constTypeId : TypeIds.I32;
                    int cTmp = fctx.NewTemp(cType, tokIdx, ref mir);
                    int cPl = mir.AddPlaceLocal(cTmp, cType);
                    int cOp = mir.AddOperand(new MirOperand(types.IsFloat(cType) ? MirOpKinds.FloatConst : MirOpKinds.IntConst, -1, constVal, cType, tokIdx));
                    fctx.Emit(new MirInst(MirOp.AssignUse, cPl, -1, 0, cType, cOp, 0, 0, 0, tokIdx));
                    return cPl;
                }
                if (lid >= 0)
                {
                    MirLocal loc = fctx.Locals[lid];
                    if ((loc.Flags & MirLocalFlags.IsRefLocal) != 0)
                    {
                        var deref = new Vec<MirProj>(1);
                        deref.Push(new MirProj(MirProjKinds.Deref, 0, loc.TypeId, -1, 0));
                        return mir.AddPlace(lid, deref.AsReadOnlySpan(), loc.TypeId);
                    }
                    return mir.AddPlaceLocal(lid, loc.TypeId);
                }

                // Implicit `this.Field` or constructor field slot
                if (fctx.OwnerTypeId >= 0)
                {
                    int fIdx = FindInstanceFieldIndex(fctx.OwnerTypeId, n.A, in types);
                    if (fIdx >= 0)
                    {
                        if (fctx.IsCtor && fIdx < fctx.CtorFieldLocals.Count)
                        {
                            if (fctx.InFieldInitializer)
                                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A field initializer cannot reference the non-static field, method, or property (CS0236)."u8);
                            int flid = fctx.CtorFieldLocals[fIdx];
                            return mir.AddPlaceLocal(flid, fctx.Locals[flid].TypeId);
                        }
                        if (fctx.ThisLocalId >= 0)
                        {
                            TypeInfo oti = types.Items[fctx.OwnerTypeId];
                            ConcreteField cf = types.Fields[oti.FieldStart + fIdx];
                            int pFlags = (oti.Kind == TypeKinds.Class ? 1 : 0) | ((cf.Flags & DeclFlags.Readonly) != 0 ? 2 : 0);
                            var projs = new Vec<MirProj>(1);
                            projs.Push(new MirProj(MirProjKinds.Field, fIdx, cf.TypeId, -1, pFlags));
                            return mir.AddPlace(fctx.ThisLocalId, projs.AsReadOnlySpan(), cf.TypeId);
                        }
                    }
                    int ownerDecl = types.Items[fctx.OwnerTypeId].A;
                    int propGet = FindMethodInType(ownerDecl, MakePropGetterLookup(n.A, in ast, in names), 0, isStatic: false, in ast);
                    if (propGet >= 0 && fctx.ThisLocalId >= 0 && (ast.Funcs[propGet].Flags & DeclFlags.ReturnsByRef) != 0)
                    {
                        var emptyM = new Vec<int>();
                        int gInst = DeclBinder.EnsureFuncInstance(propGet, fctx.OwnerTypeId, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                        FuncInstance fnInst = mir.FuncInstances[gInst];
                        bool rMut = (fnInst.Flags & DeclFlags.ReturnRefMut) != 0;
                        if (isMut && !rMut)
                        {
                            diags.ReportTok(VibCodes.MutateSharedBorrow, ta.Tokens[tokIdx], "Cannot mutate through a readonly ref property."u8);
                        }
                        PassMode recvMode = mir.ParamSigs[fnInst.ParamSigStart].Mode;
                        int recvPl = mir.AddPlaceLocal(fctx.ThisLocalId, fctx.OwnerTypeId);
                        int caStart = mir.CallArgs.Count;
                        if (types.Items[fctx.OwnerTypeId].Kind == TypeKinds.Class)
                        {
                            int recvOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, recvPl, 0, fctx.OwnerTypeId, tokIdx));
                            mir.CallArgs.Push(new MirCallArg(recvMode, recvOp, tokIdx));
                        }
                        else
                        {
                            mir.CallArgs.Push(new MirCallArg(recvMode, recvPl, tokIdx));
                        }
                        int refTmp = fctx.NewTempRef(fnInst.ReturnTypeId, rMut, tokIdx);
                        fctx.EmitCall(new MirInst(MirOp.Call, -1, refTmp, rMut ? 1 : 0, fnInst.ReturnTypeId, gInst, caStart, 1, 0, tokIdx), in mir);
                        var deref = new Vec<MirProj>(1);
                        deref.Push(new MirProj(MirProjKinds.Deref, 0, fnInst.ReturnTypeId, -1, 0));
                        return mir.AddPlace(refTmp, deref.AsReadOnlySpan(), fnInst.ReturnTypeId);
                    }
                }

                if (TryResolveUsingStaticValueMember(n.A, tokIdx, reportAmbiguity: true, ref fctx, in ast, in ta, in names, in bctx, ref diags, out int usPlKind, out _, out int usPlOwnerTid, out _, out int usPlPropGet, out _, out bool usPlAmb, out _, out _, out _))
                {
                    if (!usPlAmb && usPlKind == 2 && usPlPropGet >= 0 && (ast.Funcs[usPlPropGet].Flags & DeclFlags.ReturnsByRef) != 0)
                    {
                        var emptyM = new Vec<int>();
                        int gInst = DeclBinder.EnsureFuncInstance(usPlPropGet, usPlOwnerTid, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                        FuncInstance fnInst = mir.FuncInstances[gInst];
                        bool rMut = (fnInst.Flags & DeclFlags.ReturnRefMut) != 0;
                        if (isMut && !rMut)
                        {
                            diags.ReportTok(VibCodes.MutateSharedBorrow, ta.Tokens[tokIdx], "Cannot mutate through a readonly ref property."u8);
                        }
                        int refTmp = fctx.NewTempRef(fnInst.ReturnTypeId, rMut, tokIdx);
                        fctx.EmitCall(new MirInst(MirOp.Call, -1, refTmp, rMut ? 1 : 0, fnInst.ReturnTypeId, gInst, mir.CallArgs.Count, 0, 0, tokIdx), in mir);
                        var deref = new Vec<MirProj>(1);
                        deref.Push(new MirProj(MirProjKinds.Deref, 0, fnInst.ReturnTypeId, -1, 0));
                        return mir.AddPlace(refTmp, deref.AsReadOnlySpan(), fnInst.ReturnTypeId);
                    }
                }

                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Unresolved or captured identifier in Vibranium."u8);
                int fallback = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
                return mir.AddPlaceLocal(fallback, TypeIds.I32);
            }

            case AstKind.ExprMember:
            {
                if (TryResolveStaticTypeTarget(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int stPlDecl, out int stPlTid, memberHintNameId: n.B, isMethodCallHint: false) && stPlDecl >= 0)
                {
                    int sPropGet = FindMethodInType(stPlDecl, MakePropGetterLookup(n.B, in ast, in names), 0, isStatic: true, in ast);
                    if (sPropGet >= 0 && IsAccessibleFuncFromCaller(sPropGet, ref fctx, in ast, in bctx) &&
                        (ast.Funcs[sPropGet].Flags & DeclFlags.ReturnsByRef) != 0)
                    {
                        var emptyM = new Vec<int>();
                        int gInst = DeclBinder.EnsureFuncInstance(sPropGet, stPlTid, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                        FuncInstance fnInst = mir.FuncInstances[gInst];
                        bool rMut = (fnInst.Flags & DeclFlags.ReturnRefMut) != 0;
                        if (isMut && !rMut)
                        {
                            diags.ReportTok(VibCodes.MutateSharedBorrow, ta.Tokens[tokIdx], "Cannot mutate through a readonly ref property."u8);
                        }
                        int refTmp = fctx.NewTempRef(fnInst.ReturnTypeId, rMut, tokIdx);
                        fctx.EmitCall(new MirInst(MirOp.Call, -1, refTmp, rMut ? 1 : 0, fnInst.ReturnTypeId, gInst, mir.CallArgs.Count, 0, 0, tokIdx), in mir);
                        var deref = new Vec<MirProj>(1);
                        deref.Push(new MirProj(MirProjKinds.Deref, 0, fnInst.ReturnTypeId, -1, 0));
                        return mir.AddPlace(refTmp, deref.AsReadOnlySpan(), fnInst.ReturnTypeId);
                    }
                }
                // Constructor `this.Field`
                if (fctx.IsCtor && ast.Nodes[n.A].Kind == AstKind.ExprThis && fctx.OwnerTypeId >= 0)
                {
                    int fIdx = FindInstanceFieldIndex(fctx.OwnerTypeId, n.B, in types);
                    if (fIdx >= 0 && fIdx < fctx.CtorFieldLocals.Count)
                    {
                        if (fctx.InFieldInitializer)
                            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[n.A].TokIdx], "Keyword 'this' is not available in the current context (CS0027)."u8);
                        int flid = fctx.CtorFieldLocals[fIdx];
                        return mir.AddPlaceLocal(flid, fctx.Locals[flid].TypeId);
                    }
                }

                int baseType = InferExprType(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                TypeInfo bti = types.Items[baseType];
                if (bti.Kind == TypeKinds.Class || bti.Kind == TypeKinds.Struct)
                {
                    int fIdx = FindInstanceFieldIndex(baseType, n.B, in types);
                    if (fIdx >= 0)
                    {
                        int basePl = LowerPlaceOrTemp(n.A, baseType, isMut, isTwoPhase, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                        MirPlace bp = mir.Places[basePl];
                        ConcreteField cf = types.Fields[bti.FieldStart + fIdx];
                        if (!IsAccessibleFieldFromCaller(bti.A, cf.Flags, in fctx, in ast, in bctx))
                            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "The field is inaccessible from this context."u8);
                        int pFlags = (bti.Kind == TypeKinds.Class ? 1 : 0) | ((cf.Flags & DeclFlags.Readonly) != 0 ? 2 : 0);
                        var projs = new Vec<MirProj>(bp.ProjCount + 1);
                        for (int i = 0; i < bp.ProjCount; i++) projs.Push(mir.Projs[bp.ProjStart + i]);
                        projs.Push(new MirProj(MirProjKinds.Field, fIdx, cf.TypeId, -1, pFlags));
                        return mir.AddPlace(bp.LocalId, projs.AsReadOnlySpan(), cf.TypeId);
                    }
                    int propGet = FindMethodInType(bti.A, MakePropGetterLookup(n.B, in ast, in names), 0, isStatic: false, in ast);
                    if (propGet >= 0 && IsAccessibleFuncFromCaller(propGet, ref fctx, in ast, in bctx) &&
                        (ast.Funcs[propGet].Flags & DeclFlags.ReturnsByRef) != 0)
                    {
                        var emptyM = new Vec<int>();
                        int gInst = DeclBinder.EnsureFuncInstance(propGet, baseType, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                        FuncInstance fnInst = mir.FuncInstances[gInst];
                        bool rMut = (fnInst.Flags & DeclFlags.ReturnRefMut) != 0;
                        if (isMut && !rMut)
                        {
                            diags.ReportTok(VibCodes.MutateSharedBorrow, ta.Tokens[tokIdx], "Cannot mutate through a readonly ref property."u8);
                        }
                        PassMode recvMode = mir.ParamSigs[fnInst.ParamSigStart].Mode;
                        bool mutRecv = recvMode == PassMode.ThisMut;
                        int recvPl = LowerPlaceOrTemp(n.A, baseType, mutRecv, mutRecv && isTwoPhase, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                        int caStart = mir.CallArgs.Count;
                        if (bti.Kind == TypeKinds.Class)
                        {
                            int recvOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, recvPl, 0, baseType, tokIdx));
                            mir.CallArgs.Push(new MirCallArg(recvMode, recvOp, tokIdx));
                        }
                        else
                        {
                            mir.CallArgs.Push(new MirCallArg(recvMode, recvPl, tokIdx));
                        }
                        int refTmp = fctx.NewTempRef(fnInst.ReturnTypeId, rMut, tokIdx);
                        fctx.EmitCall(new MirInst(MirOp.Call, -1, refTmp, (rMut ? 1 : 0) | ((mutRecv && isTwoPhase) ? 2 : 0), fnInst.ReturnTypeId, gInst, caStart, 1, 0, tokIdx), in mir);
                        var deref = new Vec<MirProj>(1);
                        deref.Push(new MirProj(MirProjKinds.Deref, 0, fnInst.ReturnTypeId, -1, 0));
                        return mir.AddPlace(refTmp, deref.AsReadOnlySpan(), fnInst.ReturnTypeId);
                    }
                }

                if (isMut)
                {
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Expression is not an assignable or mutable-borrowable place in Vibranium."u8);
                }
                // Otherwise evaluate member rvalue into temp place
                int valOp = LowerExprAsOperand(exprId, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                int vType = mir.Operands[valOp].TypeId;
                int vTmp = fctx.NewTemp(vType, tokIdx, ref mir);
                int vPl = mir.AddPlaceLocal(vTmp, vType);
                fctx.Emit(new MirInst(MirOp.AssignUse, vPl, -1, 0, vType, valOp, 0, 0, 0, tokIdx));
                return vPl;
            }

            case AstKind.ExprIndex:
            {
                int targetType = InferExprType(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (targetType == TypeIds.Str)
                {
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "String character indexing is banned in Vibranium."u8);
                    int dummy = fctx.NewTemp(TypeIds.Char, tokIdx, ref mir);
                    return mir.AddPlaceLocal(dummy, TypeIds.Char);
                }

                TypeInfo tti = types.Items[targetType];
                if (tti.Kind == TypeKinds.Vec)
                {
                    int elemT = tti.A;
                    int idxArgExpr = ExtractSingleBuiltInIndexArg(in n, tokIdx, in ast, in ta, in names, ref diags);
                    int vecPl = LowerPlaceOrTemp(n.A, targetType, isMut, isTwoPhase: isMut, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    vecPl = ReserveReceiverPlace(vecPl, targetType, isMut, isTwoPhase: isMut, tokIdx, ref fctx, ref mir);
                    int idxOp = idxArgExpr >= 0
                        ? LowerIndexOrFromEndAsOperand(idxArgExpr, vecPl, isVecPlace: true, -1, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                        : mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
                    int refTmp = fctx.NewTempRef(elemT, isMut, tokIdx);
                    var valOps = new Vec<int>(1);
                    valOps.Push(idxOp);
                    var plOps = new Vec<int>(1);
                    plOps.Push(vecPl);
                    int iFlags = (isMut ? 1 : 0) | (isTwoPhase ? 2 : 0);
                    fctx.Emit(new MirInst(MirOp.Intrinsic, -1, refTmp, iFlags, elemT, (int)MirIntrinsic.VecIndexRef, mir.PushIdList(valOps.AsReadOnlySpan()), 1, mir.PushIdList(plOps.AsReadOnlySpan()) | (1 << 20), tokIdx));
                    var deref = new Vec<MirProj>(1);
                    deref.Push(new MirProj(MirProjKinds.Deref, 0, elemT, -1, 0));
                    return mir.AddPlace(refTmp, deref.AsReadOnlySpan(), elemT);
                }

                if (tti.Kind == TypeKinds.Span || tti.Kind == TypeKinds.ReadOnlySpan)
                {
                    int elemT = tti.A;
                    int idxArgExpr = ExtractSingleBuiltInIndexArg(in n, tokIdx, in ast, in ta, in names, ref diags);
                    bool spanMut = tti.Kind == TypeKinds.Span && isMut;
                    if (isMut && tti.Kind == TypeKinds.ReadOnlySpan)
                    {
                        diags.ReportTok(VibCodes.MutateSharedBorrow, ta.Tokens[tokIdx], "Cannot mutate through ReadOnlySpan<T>."u8);
                    }
                    int spPl = LowerPlaceOrTemp(n.A, targetType, spanMut, isTwoPhase: spanMut, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    spPl = ReserveReceiverPlace(spPl, targetType, isMut: spanMut, isTwoPhase: spanMut, tokIdx, ref fctx, ref mir);
                    int idxOp = idxArgExpr >= 0
                        ? LowerIndexOrFromEndAsOperand(idxArgExpr, spPl, isVecPlace: false, targetType, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                        : mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
                    int spOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, spPl, 0, targetType, tokIdx));
                    int refTmp = fctx.NewTempRef(elemT, spanMut, tokIdx);
                    var valOps = new Vec<int>(2);
                    valOps.Push(spOp);
                    valOps.Push(idxOp);
                    int iFlags = (spanMut ? 1 : 0) | (isTwoPhase ? 2 : 0);
                    fctx.Emit(new MirInst(MirOp.Intrinsic, -1, refTmp, iFlags, elemT, (int)MirIntrinsic.SpanIndexRef, mir.PushIdList(valOps.AsReadOnlySpan()), 2, 0, tokIdx));
                    var deref = new Vec<MirProj>(1);
                    deref.Push(new MirProj(MirProjKinds.Deref, 0, elemT, -1, 0));
                    return mir.AddPlace(refTmp, deref.AsReadOnlySpan(), elemT);
                }

                // User indexer (`this[...]`, overloaded, multi-param, named-arg, and `x[^k]`)
                if (tti.Kind == TypeKinds.Struct || tti.Kind == TypeKinds.Class)
                {
                    if (TryResolveUserIndexer(targetType, in n, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int idxMethod, out _, out int elemTid, out bool isFromEnd, out bool idxAmb))
                    {
                        if (idxMethod < 0)
                        {
                            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Indexer has no accessible getter in Vibranium."u8);
                            int dummy = fctx.NewTemp(elemTid, tokIdx, ref mir);
                            return mir.AddPlaceLocal(dummy, elemTid);
                        }
                        FuncDecl idxFd = ast.Funcs[idxMethod];
                        var emptyMArgs = new Vec<int>();
                        int instId = DeclBinder.EnsureFuncInstance(idxMethod, targetType, emptyMArgs.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                        FuncInstance idxInst = mir.FuncInstances[instId];
                        PassMode recvMode = mir.ParamSigs[idxInst.ParamSigStart].Mode;
                        bool mutRecv = recvMode == PassMode.ThisMut;
                        bool lenNeedsMut = false;
                        if (isFromEnd && HasUserIntLengthOrCount(targetType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int lenGetId, out _) && lenGetId >= 0)
                        {
                            lenNeedsMut = DeclBinder.GetReceiverPassMode(ast.Funcs[lenGetId], targetType, in ast, in types, bctx.IdDispose) == PassMode.ThisMut;
                        }
                        bool needMut = mutRecv || lenNeedsMut;
                        int recvPl = LowerPlaceOrTemp(n.A, targetType, needMut, needMut || isTwoPhase, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                        recvPl = ReserveReceiverPlace(recvPl, targetType, isMut: needMut, isTwoPhase: needMut, tokIdx, ref fctx, ref mir);

                        var loweredArgs = new Vec<MirCallArg>(idxInst.ParamSigCount);
                        if (tti.Kind == TypeKinds.Class)
                        {
                            int recvOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, recvPl, 0, targetType, tokIdx));
                            loweredArgs.Push(new MirCallArg(recvMode, recvOp, tokIdx));
                        }
                        else
                        {
                            loweredArgs.Push(new MirCallArg(recvMode, recvPl, tokIdx));
                        }

                        bool hasTwoPhaseArg = needMut;
                        if (isFromEnd)
                        {
                            int cachedTotOp = -1;
                            MirParamSig p0Sig = mir.ParamSigs[idxInst.ParamSigStart + 1];
                            int idxOp = LowerUserIndexOrFromEndAsOperand(n.D, p0Sig.TypeId, recvPl, targetType, ref cachedTotOp, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                            if (p0Sig.Mode == PassMode.In)
                            {
                                int inTmp = fctx.NewTemp(p0Sig.TypeId, tokIdx, ref mir);
                                int inPl = mir.AddPlaceLocal(inTmp, p0Sig.TypeId);
                                fctx.Emit(new MirInst(MirOp.AssignUse, inPl, -1, 0, p0Sig.TypeId, idxOp, 0, 0, 0, tokIdx));
                                loweredArgs.Push(new MirCallArg(PassMode.In, inPl, tokIdx));
                            }
                            else
                            {
                                loweredArgs.Push(new MirCallArg(PassMode.ByValue, idxOp, tokIdx));
                            }
                            for (int p = 1; p < idxFd.ParamCount; p++)
                            {
                                MirParamSig psig = mir.ParamSigs[idxInst.ParamSigStart + 1 + p];
                                int defExpr = ast.Params[idxFd.ParamStart + p].DefaultExpr;
                                int defOp = defExpr >= 0
                                    ? LowerExprAsOperand(defExpr, psig.TypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                                    : mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, psig.TypeId, tokIdx));
                                loweredArgs.Push(new MirCallArg(PassMode.ByValue, defOp, tokIdx));
                            }
                        }
                        else
                        {
                            LowerExplicitAndDefaultCallArgs(in idxFd, in idxInst, 1, 0, n.B, n.C, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, ref loweredArgs, ref hasTwoPhaseArg);
                        }

                        int caStart = mir.CallArgs.Count;
                        for (int i = 0; i < loweredArgs.Count; i++) mir.CallArgs.Push(loweredArgs[i]);

                        int callFlags = hasTwoPhaseArg ? 2 : 0;
                        if ((idxInst.Flags & DeclFlags.ReturnsByRef) != 0)
                        {
                            bool rMut = (idxInst.Flags & DeclFlags.ReturnRefMut) != 0;
                            if (isMut && !rMut)
                            {
                                diags.ReportTok(VibCodes.MutateSharedBorrow, ta.Tokens[tokIdx], "Cannot mutate through a readonly ref indexer."u8);
                            }
                            int refTmp = fctx.NewTempRef(idxInst.ReturnTypeId, rMut, tokIdx);
                            fctx.EmitCall(new MirInst(MirOp.Call, -1, refTmp, (rMut ? 1 : 0) | callFlags, idxInst.ReturnTypeId, instId, caStart, loweredArgs.Count, 0, tokIdx), in mir);
                            var deref = new Vec<MirProj>(1);
                            deref.Push(new MirProj(MirProjKinds.Deref, 0, idxInst.ReturnTypeId, -1, 0));
                            return mir.AddPlace(refTmp, deref.AsReadOnlySpan(), idxInst.ReturnTypeId);
                        }
                        if (isMut)
                        {
                            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Value-returning indexer is not a mutable ref-borrowable place in Vibranium."u8);
                        }
                        int valTmp = fctx.NewTemp(idxInst.ReturnTypeId, tokIdx, ref mir);
                        int valPl = mir.AddPlaceLocal(valTmp, idxInst.ReturnTypeId);
                        fctx.EmitCall(new MirInst(MirOp.Call, valPl, -1, callFlags, idxInst.ReturnTypeId, instId, caStart, loweredArgs.Count, 0, tokIdx), in mir);
                        return valPl;
                    }

                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], idxAmb ? "Ambiguous indexer access in Vibranium."u8 : "No applicable or accessible indexer overload in Vibranium."u8);
                    int errTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
                    return mir.AddPlaceLocal(errTmp, TypeIds.I32);
                }
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Cannot apply indexing with '[]' to this expression type in Vibranium."u8);
                int badIdxTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
                return mir.AddPlaceLocal(badIdxTmp, TypeIds.I32);
            }

            case AstKind.ExprCall:
            {
                int refLid = TryLowerRefReturningCall(in n, isTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int elemType);
                if (refLid >= 0)
                {
                    var deref = new Vec<MirProj>(1);
                    deref.Push(new MirProj(MirProjKinds.Deref, 0, elemType, -1, 0));
                    return mir.AddPlace(refLid, deref.AsReadOnlySpan(), elemType);
                }
                break;
            }

            case AstKind.ExprUnary:
            {
                if (n.C == 0 && (TokKind)n.A == TokKind.KwRef)
                {
                    return LowerPlace(n.B, isMut, isTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                }
                break;
            }

            case AstKind.ExprAssign:
            {
                if (n.D != 0)
                {
                    int refPl = LowerRefAssignPlace(in n, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out bool lhsMut);
                    if (isMut && !lhsMut)
                    {
                        diags.ReportTok(VibCodes.MutateSharedBorrow, ta.Tokens[tokIdx], "Cannot mutate through a readonly reference."u8);
                    }
                    return refPl;
                }
                break;
            }

            case AstKind.ExprCond:
            {
                if (ast.Nodes[n.B].Kind == AstKind.ExprUnary && (TokKind)ast.Nodes[n.B].A == TokKind.KwRef &&
                    ast.Nodes[n.C].Kind == AstKind.ExprUnary && (TokKind)ast.Nodes[n.C].A == TokKind.KwRef)
                {
                    int elemT = InferExprType(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    int refTmp = fctx.NewTempRef(elemT, isMut, tokIdx);
                    int tBlk = fctx.NewBlock();
                    int fBlk = fctx.NewBlock();
                    int mBlk = fctx.NewBlock();
                    int prevRefCondOverride = fctx.OutVarScopeOverride;
                    if (fctx.OutVarScopeOverride <= 0) fctx.OutVarScopeOverride = fctx.ScopeDepth;
                    PushScope(ref fctx);
                    LowerCondBranch(n.A, tBlk, fBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope: false);
                    fctx.CurBlock = tBlk;
                    int tPl = LowerPlace(ast.Nodes[n.B].B, isMut, isTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    fctx.Emit(new MirInst(MirOp.BindRef, -1, refTmp, isMut ? 1 : 0, elemT, refTmp, tPl, 0, 0, tokIdx));
                    if (!fctx.IsBlockTerminated(fctx.CurBlock))
                    {
                        EmitScopeExitsDownTo(fctx.ScopeDepth, tokIdx, ref fctx, ref mir);
                        fctx.Terminate(new MirTerm(MirTermKind.Goto, mBlk, 0, 0, 0, 0, 0, tokIdx));
                    }
                    fctx.CurBlock = fBlk;
                    int fPl = LowerPlace(ast.Nodes[n.C].B, isMut, isTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    fctx.Emit(new MirInst(MirOp.BindRef, -1, refTmp, isMut ? 1 : 0, elemT, refTmp, fPl, 0, 0, tokIdx));
                    if (!fctx.IsBlockTerminated(fctx.CurBlock))
                    {
                        EmitScopeExitsDownTo(fctx.ScopeDepth, tokIdx, ref fctx, ref mir);
                        fctx.Terminate(new MirTerm(MirTermKind.Goto, mBlk, 0, 0, 0, 0, 0, tokIdx));
                    }
                    PopScopeWithoutEmit(ref fctx);
                    fctx.OutVarScopeOverride = prevRefCondOverride;
                    fctx.CurBlock = mBlk;
                    var deref = new Vec<MirProj>(1);
                    deref.Push(new MirProj(MirProjKinds.Deref, 0, elemT, -1, 0));
                    return mir.AddPlace(refTmp, deref.AsReadOnlySpan(), elemT);
                }
                break;
            }
        }

        if (isMut)
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Expression is not an assignable or mutable-borrowable place in Vibranium."u8);
        }
        int opId = LowerExprAsOperand(exprId, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        int t = mir.Operands[opId].TypeId;
        int tmp = fctx.NewTemp(t, tokIdx, ref mir);
        int pl = mir.AddPlaceLocal(tmp, t);
        fctx.Emit(new MirInst(MirOp.AssignUse, pl, -1, 0, t, opId, 0, 0, 0, tokIdx));
        return pl;
    }

    private static int LowerPlaceOrTemp(int exprId, int expectedTypeId, bool isMut, bool isTwoPhase, int tokIdx, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags) => LowerPlaceOrTemp(exprId, expectedTypeId, isMut, isTwoPhase, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, false);

    private static int LowerPlaceOrTemp(
        int exprId,
        int expectedTypeId,
        bool isMut,
        bool isTwoPhase,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        bool requireVariable)
    {
        AstNode n = ast.Nodes[exprId];
        if (requireVariable && n.Kind == AstKind.ExprThis && fctx.OwnerTypeId >= 0 && types.Items[fctx.OwnerTypeId].Kind == TypeKinds.Class)
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A readonly reference argument cannot refer to the class this value."u8);
        if (requireVariable && n.Kind == AstKind.ExprIndex)
        {
            int receiverType = InferExprType(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            TypeInfo receiver = types.Items[receiverType];
            bool referenceIndex = receiver.Kind == TypeKinds.Span || receiver.Kind == TypeKinds.ReadOnlySpan || receiver.Kind == TypeKinds.Vec;
            if (!referenceIndex && TryResolveUserIndexer(receiverType, in n, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags,
                out int getter, out _, out _, out _, out _) && getter >= 0)
            {
                referenceIndex = (ast.Funcs[getter].Flags & DeclFlags.ReturnsByRef) != 0;
            }
            if (!referenceIndex) diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A readonly reference argument requires a source variable, not a value-returning indexer."u8);
        }
        if (n.Kind == AstKind.ExprThis ||
            (n.Kind == AstKind.ExprAssign && n.D != 0) ||
            (n.Kind == AstKind.ExprIndex && !(n.D >= 0 && ast.Nodes[n.D].Kind == AstKind.ExprRange)) ||
            (n.Kind == AstKind.ExprCond && ast.Nodes[n.B].Kind == AstKind.ExprUnary && (TokKind)ast.Nodes[n.B].A == TokKind.KwRef && ast.Nodes[n.C].Kind == AstKind.ExprUnary && (TokKind)ast.Nodes[n.C].A == TokKind.KwRef))
        {
            return LowerPlace(exprId, isMut, isTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }
        if (n.Kind == AstKind.ExprIdent)
        {
            int vLid = fctx.FindVar(n.A, out bool isC, out _, out _);
            if (!isC && vLid >= 0)
            {
                return LowerPlace(exprId, isMut, isTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }
            if (!isC && fctx.OwnerTypeId >= 0)
            {
                if (FindInstanceFieldIndex(fctx.OwnerTypeId, n.A, in types) >= 0)
                {
                    return LowerPlace(exprId, isMut, isTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                }
                int ownerDecl = types.Items[fctx.OwnerTypeId].A;
                int propGet = FindMethodInType(ownerDecl, MakePropGetterLookup(n.A, in ast, in names), 0, isStatic: false, in ast);
                if (propGet >= 0 && (ast.Funcs[propGet].Flags & DeclFlags.ReturnsByRef) != 0)
                {
                    return LowerPlace(exprId, isMut, isTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                }
            }
            if (TryResolveUsingStaticValueMember(n.A, tokIdx, reportAmbiguity: false, ref fctx, in ast, in ta, in names, in bctx, ref diags, out int usLpKind, out _, out _, out _, out int usLpPropGet, out _, out bool usLpAmb, out _, out _, out _) &&
                !usLpAmb && usLpKind == 2 && usLpPropGet >= 0 && (ast.Funcs[usLpPropGet].Flags & DeclFlags.ReturnsByRef) != 0)
            {
                return LowerPlace(exprId, isMut, isTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }
        }
        if (n.Kind == AstKind.ExprMember)
        {
            if (TryResolveStaticTypeTarget(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int stLpDecl, out _, memberHintNameId: n.B, isMethodCallHint: false) && stLpDecl >= 0)
            {
                int sPropGet = FindMethodInType(stLpDecl, MakePropGetterLookup(n.B, in ast, in names), 0, isStatic: true, in ast);
                if (sPropGet >= 0 && IsAccessibleFuncFromCaller(sPropGet, ref fctx, in ast, in bctx) &&
                    (ast.Funcs[sPropGet].Flags & DeclFlags.ReturnsByRef) != 0)
                {
                    return LowerPlace(exprId, isMut, isTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                }
            }
            int bt = InferExprType(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            TypeInfo bti = types.Items[bt];
            if (bti.Kind == TypeKinds.Class || bti.Kind == TypeKinds.Struct)
            {
                if (FindInstanceFieldIndex(bt, n.B, in types) >= 0)
                {
                    int fieldPlace = LowerPlace(exprId, isMut, isTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    MirPlace place = mir.Places[fieldPlace];
                    if (requireVariable && bti.Kind == TypeKinds.Struct && place.LocalId >= 0)
                    {
                        MirLocal root = fctx.Locals[place.LocalId];
                        if (types.Items[root.TypeId].Kind == TypeKinds.Struct && (root.Flags & MirLocalFlags.IsTemp) != 0 && (root.Flags & MirLocalFlags.IsRefLocal) == 0)
                            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A readonly reference argument cannot refer to a field of a temporary struct value."u8);
                    }
                    return fieldPlace;
                }
                int propGet = FindMethodInType(bti.A, MakePropGetterLookup(n.B, in ast, in names), 0, isStatic: false, in ast);
                if (propGet >= 0 && IsAccessibleFuncFromCaller(propGet, ref fctx, in ast, in bctx) &&
                    (ast.Funcs[propGet].Flags & DeclFlags.ReturnsByRef) != 0)
                {
                    return LowerPlace(exprId, isMut, isTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                }
            }
        }
        if (n.Kind == AstKind.ExprCall)
        {
            int refLid = TryLowerRefReturningCall(in n, isTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int elemType);
            if (refLid >= 0)
            {
                if (isMut && (fctx.Locals[refLid].Flags & MirLocalFlags.IsRefMut) == 0)
                    diags.ReportTok(VibCodes.MutateSharedBorrow, ta.Tokens[tokIdx], "Cannot pass a readonly reference return with an explicit ref modifier."u8);
                var deref = new Vec<MirProj>(1);
                deref.Push(new MirProj(MirProjKinds.Deref, 0, elemType, -1, 0));
                return mir.AddPlace(refLid, deref.AsReadOnlySpan(), elemType);
            }
        }
        if (requireVariable) diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A readonly reference argument requires a source variable, not a constant or temporary value."u8);
        int opId = LowerExprAsOperand(exprId, expectedTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        int t = mir.Operands[opId].TypeId;
        int tmp = fctx.NewTemp(t, tokIdx, ref mir);
        int pl = mir.AddPlaceLocal(tmp, t);
        fctx.Emit(new MirInst(MirOp.AssignUse, pl, -1, 0, t, opId, 0, 0, 0, tokIdx));
        return pl;
    }

    private static int TryLowerRefReturningCall(
        in AstNode callNode,
        bool isTwoPhase,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        out int targetTypeId)
    {
        targetTypeId = TypeIds.I32;
        int tokIdx = callNode.TokIdx;
        int argCount = callNode.C;
        AstNode callee = ast.Nodes[callNode.A];

        if (callee.Kind == AstKind.ExprIdent)
        {
            var lfCands = new Vec<int>();
            for (int i = 0; i < fctx.VisibleLocalFuncs.Count; i++)
            {
                int lfId = fctx.VisibleLocalFuncs[i];
                if (ast.Funcs[lfId].NameId == callee.A) lfCands.Push(lfId);
            }
            if (lfCands.Count > 0)
            {
                int bestLf = ResolveBestOverload(lfCands.AsReadOnlySpan(), -1, -1, callee.B, callee.C, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out _);
                if (bestLf >= 0 && (ast.Funcs[bestLf].Flags & DeclFlags.ReturnsByRef) != 0)
                {
                    return EmitResolvedRefUserCall(bestLf, -1, -1, callee.B, callee.C, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, isTwoPhase, out targetTypeId);
                }
                return -1;
            }

            for (int d = fctx.EnclosingOwnerDeclId; d >= 0; d = ast.Types[d].OwnerDeclId)
            {
                if (!HasAccessibleMethodNamed(d, callee.A, ref fctx, in ast, in bctx)) continue;

                bool isInnermost = d == fctx.EnclosingOwnerDeclId;
                bool canResolveOnD = isInnermost ? (fctx.OwnerTypeId >= 0 || ast.Types[d].TypeParamCount == 0) : (ast.Types[d].TypeParamCount == 0);
                if (!canResolveOnD) return -1;

                var encCands = new Vec<int>();
                CollectTypeMethodCandidates(d, callee.A, allowInstance: isInnermost && fctx.ThisLocalId >= 0, allowStatic: true, isCtor: false, ref fctx, in ast, in bctx, ref encCands);
                int encOwnerTid = isInnermost ? fctx.OwnerTypeId : -1;
                int mId = ResolveBestOverload(encCands.AsReadOnlySpan(), encOwnerTid, -1, callee.B, callee.C, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out _);
                if (mId >= 0 && (ast.Funcs[mId].Flags & DeclFlags.ReturnsByRef) != 0)
                {
                    bool isInst = (ast.Funcs[mId].Flags & DeclFlags.Static) == 0;
                    int recvPl = -1;
                    int ownerTid = -1;
                    bool useTwoPhase = false;
                    if (isInst)
                    {
                        ownerTid = fctx.OwnerTypeId;
                        PassMode recvMode = DeclBinder.GetReceiverPassMode(ast.Funcs[mId], ownerTid, in ast, in types, bctx.IdDispose);
                        recvPl = mir.AddPlaceLocal(fctx.ThisLocalId, ownerTid);
                        useTwoPhase = recvMode == PassMode.ThisMut && (argCount > 0 || isTwoPhase);
                        if (argCount > 0)
                        {
                            recvPl = ReserveReceiverPlace(recvPl, ownerTid, recvMode == PassMode.ThisMut, useTwoPhase, tokIdx, ref fctx, ref mir);
                        }
                    }
                    return EmitResolvedRefUserCall(mId, ownerTid, recvPl, callee.B, callee.C, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, useTwoPhase, out targetTypeId);
                }
                return -1;
            }
            if (TryResolveUsingStaticMethodCall(callee.A, callee.B, callee.C, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int usRefId, out int usRefOwnerTid, out bool usRefAmb, out _) &&
                !usRefAmb && usRefId >= 0 && (ast.Funcs[usRefId].Flags & DeclFlags.ReturnsByRef) != 0)
            {
                return EmitResolvedRefUserCall(usRefId, usRefOwnerTid, -1, callee.B, callee.C, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, isTwoPhase, out targetTypeId);
            }
            return -1;
        }

        if (callee.Kind == AstKind.ExprMember)
        {
            if (argCount == 0 && Bytes.Eq(names.Text(callee.B), "UnwrapMut"u8))
            {
                int recvT = InferExprType(callee.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                TypeInfo rti = types.Items[recvT];
                if (rti.Kind == TypeKinds.Option)
                {
                    if (types.IsLinear(rti.A, in ast))
                    {
                        diags.ReportTok(VibCodes.LinearViolation, ta.Tokens[tokIdx], "Option.UnwrapMut() is banned on linear resources."u8);
                    }
                    int optPl = LowerPlaceOrTemp(callee.A, recvT, isMut: true, isTwoPhase, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    targetTypeId = rti.A;
                    int refTmp = fctx.NewTempRef(targetTypeId, isMut: true, tokIdx);
                    var plOne = new Vec<int>(1);
                    plOne.Push(optPl);
                    fctx.Emit(new MirInst(MirOp.Intrinsic, -1, refTmp, 1 | (isTwoPhase ? 2 : 0), targetTypeId, (int)MirIntrinsic.OptionUnwrapMut, 0, 0, mir.PushIdList(plOne.AsReadOnlySpan()) | (1 << 20), tokIdx));
                    return refTmp;
                }
            }

            if (TryResolveStaticTypeTarget(callee.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int stDeclId, out int stTid, memberHintNameId: callee.B, isMethodCallHint: true))
            {
                if (stDeclId >= 0)
                {
                    var stCands = new Vec<int>();
                    CollectTypeMethodCandidates(stDeclId, callee.B, allowInstance: false, allowStatic: true, isCtor: false, ref fctx, in ast, in bctx, ref stCands);
                    int smId = ResolveBestOverload(stCands.AsReadOnlySpan(), stTid, -1, callee.C, callee.D, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out _);
                    if (smId >= 0 && (ast.Funcs[smId].Flags & DeclFlags.ReturnsByRef) != 0)
                    {
                        return EmitResolvedRefUserCall(smId, stTid, -1, callee.C, callee.D, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, isTwoPhase, out targetTypeId);
                    }
                }
                return -1;
            }

            int instRecvT = InferReceiverType(callee.A, out bool instRecvDeclares, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            TypeInfo irti = types.Items[instRecvT];
            if (irti.Kind == TypeKinds.Class || irti.Kind == TypeKinds.Struct)
            {
                var imCands = new Vec<int>();
                CollectTypeMethodCandidates(irti.A, callee.B, allowInstance: true, allowStatic: false, isCtor: false, ref fctx, in ast, in bctx, ref imCands);
                EnterReceiverScope(callee.A, instRecvDeclares, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                int imId = ResolveBestOverload(imCands.AsReadOnlySpan(), instRecvT, -1, callee.C, callee.D, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out bool imAmb, out _);
                fctx.LeaveSpeculativeInfer();
                if (imId >= 0 && (ast.Funcs[imId].Flags & DeclFlags.ReturnsByRef) != 0)
                {
                    PassMode recvMode = DeclBinder.GetReceiverPassMode(ast.Funcs[imId], instRecvT, in ast, in types, bctx.IdDispose);
                    bool useTwoPhase = recvMode == PassMode.ThisMut && (argCount > 0 || isTwoPhase);
                    int recvPl = LowerPlaceOrTemp(callee.A, instRecvT, recvMode == PassMode.ThisMut, useTwoPhase, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    if (argCount > 0)
                    {
                        recvPl = ReserveReceiverPlace(recvPl, instRecvT, recvMode == PassMode.ThisMut, useTwoPhase, tokIdx, ref fctx, ref mir);
                    }
                    return EmitResolvedRefUserCall(imId, instRecvT, recvPl, callee.C, callee.D, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, useTwoPhase, out targetTypeId);
                }
                if (imId >= 0 || imAmb) return -1;
            }

            var extCands = new Vec<int>();
            CollectExtensionCandidates(callee.B, ref fctx, in ast, in bctx, ref extCands);
            EnterReceiverScope(callee.A, instRecvDeclares, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            int extId = ResolveBestOverload(extCands.AsReadOnlySpan(), -1, instRecvT, callee.C, callee.D, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out _);
            fctx.LeaveSpeculativeInfer();
            if (extId >= 0 && (ast.Funcs[extId].Flags & DeclFlags.ReturnsByRef) != 0)
            {
                return EmitResolvedRefExtensionCall(extId, callee.A, instRecvT, callee.C, callee.D, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, isTwoPhase, out targetTypeId);
            }
        }
        return -1;
    }

    private static int LowerExprAsOperand(int exprId, int expectedTypeId, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags) => LowerExprAsOperand(exprId, expectedTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, -1);

    private static int LowerExprAsOperand(
        int exprId,
        int expectedTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        int collectionDestinationPlace)
    {
        AstNode n = ast.Nodes[exprId];
        int tokIdx = n.TokIdx;
        Token tok = ta.Tokens[tokIdx];
        int diagCountBefore = diags.Items.Count;



        switch (n.Kind)
        {
            case AstKind.ExprIntLit:
            {
                Token litTok = ta.Tokens[n.A];
                if ((litTok.AuxId & 4) != 0)
                {
                    diags.ReportTok(VibCodes.Unsupported, litTok, "Integral constant is too large."u8);
                    return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, expectedTypeId > 0 ? expectedTypeId : TypeIds.I32, tokIdx));
                }
                int litType = InferExprType(exprId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (expectedTypeId >= 0 && types.IsInteger(expectedTypeId) && CanNarrowIntConstant(litTok.IntVal, litTok.Kind, expectedTypeId, in types))
                {
                    return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, TruncateConstToType(litTok.IntVal, expectedTypeId), expectedTypeId, tokIdx));
                }
                if (expectedTypeId == TypeIds.F32)
                {
                    uint fBits = types.IsUnsignedInteger(litType)
                        ? (uint)DeclBinder.ULongToSingleBits((ulong)litTok.IntVal)
                        : (uint)DeclBinder.LongToSingleBits(litTok.IntVal);
                    return mir.AddOperand(new MirOperand(MirOpKinds.FloatConst, -1, (long)fBits, TypeIds.F32, tokIdx));
                }
                if (expectedTypeId >= 0 && types.IsFloat(expectedTypeId))
                {
                    int intOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, litTok.IntVal, litType, tokIdx));
                    return EmitCastToTemp(intOp, expectedTypeId, tokIdx, ref fctx, ref mir);
                }
                int op = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, litTok.IntVal, litType, tokIdx));
                return ConvertOperandIfNeeded(op, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprFloatLit:
            {
                Token fTok = ta.Tokens[n.A];
                bool isSingle = fTok.Kind == TokKind.FloatLit;
                int fType = isSingle ? TypeIds.F32 : TypeIds.F64;
                if (!DeclBinder.TryParseExactDecimalFloat(ta.GetLit(fTok.AuxId), isSingle, out long exactBits))
                {
                    diags.ReportTok(VibCodes.Unsupported, fTok, "Floating-point constant is outside the range of the target type."u8);
                    exactBits = 0;
                }
                int op = mir.AddOperand(new MirOperand(MirOpKinds.FloatConst, -1, exactBits, fType, tokIdx));
                return ConvertOperandIfNeeded(op, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprBoolLit:
            {
                int op = mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, n.A, TypeIds.Bool, tokIdx));
                return ConvertOperandIfNeeded(op, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprCharLit:
            {
                int op = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, n.A, TypeIds.Char, tokIdx));
                return ConvertOperandIfNeeded(op, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprStrLit:
            {
                int op = mir.AddOperand(new MirOperand(MirOpKinds.StrConst, n.A, 0, TypeIds.Str, tokIdx));
                return ConvertOperandIfNeeded(op, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprUtf8Lit:
            {
                int roSpanU8 = types.MakeSpan(TypeIds.U8, isReadOnly: true);
                int op = mir.AddOperand(new MirOperand(MirOpKinds.Utf8Const, n.A, 0, roSpanU8, tokIdx));
                return ConvertOperandIfNeeded(op, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprNull:
            {
                int t = expectedTypeId >= 0 ? expectedTypeId : TypeIds.I32;
                return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, t, tokIdx));
            }

            case AstKind.ExprDefault:
            {
                int defType = n.A >= 0
                    ? DeclBinder.ResolveTypeNode(n.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags)
                    : (expectedTypeId >= 0 ? expectedTypeId : TypeIds.I32);
                DeclBinder.DrainConcreteTypeQueue(in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                if (defType == TypeIds.Utf8Lines || defType == TypeIds.Utf8ArgEnum)
                {
                    diags.ReportTok(VibCodes.Unsupported, tok, "Closed foreach view enumerator cannot be created with 'default'."u8);
                }
                else if (!types.IsZeroSafe(defType, in ast))
                {
                    diags.ReportTok(VibCodes.NullOrZeroUnsafe, tok, "'default' initialization of non-zero-safe type is banned in Vibranium."u8);
                }
                return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, defType, tokIdx));
            }

            case AstKind.ExprThis:
            {
                int pl = LowerPlace(exprId, isMut: false, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                int op = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, mir.Places[pl].TypeId, tokIdx));
                return ConvertOperandIfNeeded(op, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprIdent:
            {
                int lid = fctx.FindVar(n.A, out bool isConst, out int constTypeId, out long constVal);
                if (isConst)
                {
                    int cType = constTypeId > 0 ? constTypeId : TypeIds.I32;
                    if (cType == TypeIds.Str)
                    {
                        int sOp = MakeConstStringOperand(constVal, tokIdx, ref mir);
                        return ConvertOperandIfNeeded(sOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                    }
                    if (types.IsFloat(cType))
                    {
                        int fOp = mir.AddOperand(new MirOperand(MirOpKinds.FloatConst, -1, constVal, cType, tokIdx));
                        return ConvertOperandIfNeeded(fOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                    }
                    if (cType == TypeIds.Bool)
                    {
                        int bConstOp = mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, constVal != 0 ? 1 : 0, TypeIds.Bool, tokIdx));
                        return ConvertOperandIfNeeded(bConstOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                    }
                    int iOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, constVal, cType, tokIdx));
                    return ConvertOperandIfNeeded(iOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                }
                if (lid >= 0)
                {
                    int pl = LowerPlace(exprId, isMut: false, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    int op = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, mir.Places[pl].TypeId, tokIdx));
                    return ConvertOperandIfNeeded(op, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                }

                // Check const field on enclosing types (innermost outward)
                int curOwnerDecl = fctx.EnclosingOwnerDeclId;
                for (int d = curOwnerDecl; d >= 0; d = ast.Types[d].OwnerDeclId)
                {
                    TypeDecl otd = ast.Types[d];
                    for (int f = 0; f < otd.FieldCount; f++)
                    {
                        FieldDecl fd = ast.Fields[otd.FieldStart + f];
                        if (fd.NameId == n.A && (fd.Flags & DeclFlags.IsConst) != 0)
                        {
                            var empty = new Vec<int>();
                            int cType = DeclBinder.ResolveTypeNode(fd.TypeNode, empty.AsReadOnlySpan(), empty.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                            if (fd.HasConstVal != 0)
                            {
                                int cOp;
                                if (cType == TypeIds.Str)
                                {
                                    cOp = MakeConstStringOperand(fd.ConstVal, tokIdx, ref mir);
                                }
                                else
                                {
                                    int opK = types.IsFloat(cType) ? MirOpKinds.FloatConst : (cType == TypeIds.Bool ? MirOpKinds.BoolConst : MirOpKinds.IntConst);
                                    cOp = mir.AddOperand(new MirOperand(opK, -1, fd.ConstVal, cType, tokIdx));
                                }
                                return ConvertOperandIfNeeded(cOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                            }
                            if (fd.InitExpr >= 0 && fd.InitExpr != exprId)
                            {
                                int fOp = LowerExprAsOperand(fd.InitExpr, cType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                                return ConvertOperandIfNeeded(fOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                            }
                        }
                    }
                }

                // Check instance field / property on `this`
                if (fctx.OwnerTypeId >= 0)
                {
                    int fIdx = FindInstanceFieldIndex(fctx.OwnerTypeId, n.A, in types);
                    if (fIdx >= 0)
                    {
                        int pl = LowerPlace(exprId, isMut: false, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                        int op = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, mir.Places[pl].TypeId, tokIdx));
                        return ConvertOperandIfNeeded(op, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                    }
                    int ownerDecl = types.Items[fctx.OwnerTypeId].A;
                    int propGet = FindMethodInType(ownerDecl, MakePropGetterLookup(n.A, in ast, in names), 0, isStatic: false, in ast);
                    if (propGet >= 0 && fctx.IsCtor)
                    {
                        diags.ReportTok(VibCodes.NullOrZeroUnsafe, tok, "Cannot access, capture, or call members on 'this' before constructor finishes initializing all fields."u8);
                        return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.I32, tokIdx));
                    }
                    if (propGet >= 0 && fctx.ThisLocalId >= 0)
                    {
                        var emptyM = new Vec<int>();
                        int gInstId = DeclBinder.EnsureFuncInstance(propGet, fctx.OwnerTypeId, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                        int gOp = EmitZeroArgInstanceCall(gInstId, mir.AddPlaceLocal(fctx.ThisLocalId, fctx.OwnerTypeId), fctx.OwnerTypeId, tokIdx, ref fctx, in types, ref mir);
                        return ConvertOperandIfNeeded(gOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                    }
                }

                for (int d = curOwnerDecl; d >= 0; d = ast.Types[d].OwnerDeclId)
                {
                    if (d != curOwnerDecl && ast.Types[d].TypeParamCount > 0) continue;
                    int sPropGet = FindMethodInType(d, MakePropGetterLookup(n.A, in ast, in names), 0, isStatic: true, in ast);
                    if (sPropGet >= 0)
                    {
                        var emptyM = new Vec<int>();
                        int sOwnerTid = d == curOwnerDecl ? fctx.OwnerTypeId : -1;
                        int gInst = DeclBinder.EnsureFuncInstance(sPropGet, sOwnerTid, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                        FuncInstance fnInst = mir.FuncInstances[gInst];
                        if ((fnInst.Flags & DeclFlags.ReturnsByRef) != 0)
                        {
                            bool rMut = (fnInst.Flags & DeclFlags.ReturnRefMut) != 0;
                            int refTmp = fctx.NewTempRef(fnInst.ReturnTypeId, rMut, tokIdx);
                            fctx.EmitCall(new MirInst(MirOp.Call, -1, refTmp, rMut ? 1 : 0, fnInst.ReturnTypeId, gInst, mir.CallArgs.Count, 0, 0, tokIdx), in mir);
                            var deref = new Vec<MirProj>(1);
                            deref.Push(new MirProj(MirProjKinds.Deref, 0, fnInst.ReturnTypeId, -1, 0));
                            int dPl = mir.AddPlace(refTmp, deref.AsReadOnlySpan(), fnInst.ReturnTypeId);
                            int rOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dPl, 0, fnInst.ReturnTypeId, tokIdx));
                            return ConvertOperandIfNeeded(rOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                        }
                        int dstTmp = fctx.NewTemp(fnInst.ReturnTypeId, tokIdx, ref mir);
                        int dstPl = mir.AddPlaceLocal(dstTmp, fnInst.ReturnTypeId);
                        fctx.EmitCall(new MirInst(MirOp.Call, dstPl, -1, 0, fnInst.ReturnTypeId, gInst, mir.CallArgs.Count, 0, 0, tokIdx), in mir);
                        int gOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, fnInst.ReturnTypeId, tokIdx));
                        return ConvertOperandIfNeeded(gOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                    }
                }

                if (TryResolveUsingStaticValueMember(n.A, tokIdx, reportAmbiguity: true, ref fctx, in ast, in ta, in names, in bctx, ref diags, out int usOpKind, out int usOpOwner, out int usOpOwnerTid, out int usOpFldIdx, out int usOpPropGet, out _, out bool usOpAmb, out int usOpBTid, out long usOpBBits, out bool usOpBFlt))
                {
                    if (usOpAmb)
                    {
                        return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.I32, tokIdx));
                    }
                    if (usOpKind == 1 && usOpOwner >= 0)
                    {
                        TypeDecl ustd = ast.Types[usOpOwner];
                        FieldDecl usfd = ast.Fields[ustd.FieldStart + usOpFldIdx];
                        var usOpTpN = new Vec<int>();
                        var usOpTpV = new Vec<int>();
                        if (usOpOwnerTid >= 0) BuildOwnerTypeSubst(usOpOwnerTid, in ast, in types, ref usOpTpN, ref usOpTpV);
                        int resT = ustd.Kind == TypeDeclKinds.Enum
                            ? types.MakeEnum(usOpOwner, names.Text(ustd.NameId))
                            : DeclBinder.ResolveTypeNode(usfd.TypeNode, usOpTpN.AsReadOnlySpan(), usOpTpV.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                        int usConstOp;
                        if (usfd.HasConstVal != 0 || ustd.Kind == TypeDeclKinds.Enum)
                        {
                            if (resT == TypeIds.Str)
                            {
                                usConstOp = MakeConstStringOperand(usfd.ConstVal, tokIdx, ref mir);
                            }
                            else
                            {
                                int opK = types.IsFloat(resT) ? MirOpKinds.FloatConst : (resT == TypeIds.Bool ? MirOpKinds.BoolConst : MirOpKinds.IntConst);
                                usConstOp = mir.AddOperand(new MirOperand(opK, -1, usfd.ConstVal, resT, tokIdx));
                            }
                        }
                        else if (usfd.InitExpr >= 0 && usfd.InitExpr != exprId)
                        {
                            usConstOp = LowerExprAsOperand(usfd.InitExpr, resT, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                        }
                        else
                        {
                            usConstOp = mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, resT, tokIdx));
                        }
                        return ConvertOperandIfNeeded(usConstOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                    }
                    if (usOpKind == 3 && usOpBTid > 0)
                    {
                        int bOp;
                        if (usOpBTid == TypeIds.NoneUnit)
                        {
                            bOp = mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, TypeIds.NoneUnit, tokIdx));
                        }
                        else if (usOpBTid == TypeIds.Str)
                        {
                            bOp = mir.AddOperand(new MirOperand(MirOpKinds.StrConst, -1, 0, TypeIds.Str, tokIdx));
                        }
                        else
                        {
                            bOp = mir.AddOperand(new MirOperand(usOpBFlt ? MirOpKinds.FloatConst : MirOpKinds.IntConst, -1, usOpBBits, usOpBTid, tokIdx));
                        }
                        return ConvertOperandIfNeeded(bOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                    }
                    if (usOpKind == 2 && usOpPropGet >= 0)
                    {
                        var emptyM = new Vec<int>();
                        int gInst = DeclBinder.EnsureFuncInstance(usOpPropGet, usOpOwnerTid, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                        FuncInstance fnInst = mir.FuncInstances[gInst];
                        if ((fnInst.Flags & DeclFlags.ReturnsByRef) != 0)
                        {
                            bool rMut = (fnInst.Flags & DeclFlags.ReturnRefMut) != 0;
                            int refTmp = fctx.NewTempRef(fnInst.ReturnTypeId, rMut, tokIdx);
                            fctx.EmitCall(new MirInst(MirOp.Call, -1, refTmp, rMut ? 1 : 0, fnInst.ReturnTypeId, gInst, mir.CallArgs.Count, 0, 0, tokIdx), in mir);
                            var deref = new Vec<MirProj>(1);
                            deref.Push(new MirProj(MirProjKinds.Deref, 0, fnInst.ReturnTypeId, -1, 0));
                            int dPl = mir.AddPlace(refTmp, deref.AsReadOnlySpan(), fnInst.ReturnTypeId);
                            int rOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dPl, 0, fnInst.ReturnTypeId, tokIdx));
                            return ConvertOperandIfNeeded(rOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                        }
                        int dstTmp = fctx.NewTemp(fnInst.ReturnTypeId, tokIdx, ref mir);
                        int dstPl = mir.AddPlaceLocal(dstTmp, fnInst.ReturnTypeId);
                        fctx.EmitCall(new MirInst(MirOp.Call, dstPl, -1, 0, fnInst.ReturnTypeId, gInst, mir.CallArgs.Count, 0, 0, tokIdx), in mir);
                        int gOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, fnInst.ReturnTypeId, tokIdx));
                        return ConvertOperandIfNeeded(gOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                    }
                }

                if (n.A == bctx.IdNone)
                {
                    int noneOp = mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, TypeIds.NoneUnit, tokIdx));
                    return ConvertOperandIfNeeded(noneOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                }

                diags.ReportTok(VibCodes.Unsupported, tok, "Unresolved or captured identifier in Vibranium."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.I32, tokIdx));
            }

            case AstKind.ExprMember:
            {
                int mOp = LowerMemberAccessAsOperand(exprId, in n, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                return ConvertOperandIfNeeded(mOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprIndex:
            {
                if (n.D >= 0 && ast.Nodes[n.D].Kind == AstKind.ExprRange)
                {
                    int slOp = LowerRangeSliceAsOperand(in n, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    return ConvertOperandIfNeeded(slOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                }
                int op = LowerIndexValue(exprId, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out _);
                return ConvertOperandIfNeeded(op, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprFromEnd:
            case AstKind.ExprRange:
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "Standalone System.Index ('^k') and System.Range ('a..b') values are not supported outside Vec/Span indexing in Vibranium."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.I32, tokIdx));
            }

            case AstKind.ExprCall:
            {
                int cOp = LowerCallAsOperand(in n, expectedTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                return ConvertOperandIfNeeded(cOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprNew:
            {
                int newOp = LowerNewAsOperand(in n, expectedTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                return ConvertOperandIfNeeded(newOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprNewArray:
            {
                if (n.A >= 0)
                {
                    int elemT = DeclBinder.ResolveTypeNode(n.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                    DeclBinder.DrainConcreteTypeQueue(in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                    if (types.IsLinear(elemT, in ast))
                    {
                        diags.ReportTok(VibCodes.LinearViolation, tok, "Linear IDisposable resource cannot be stored in an array."u8);
                        return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
                    }
                    if (!types.IsZeroSafe(elemT, in ast))
                    {
                        diags.ReportTok(VibCodes.NullOrZeroUnsafe, tok, "Array allocation zero-initializes non-zero-safe element type."u8);
                        return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
                    }
                }
                diags.ReportTok(VibCodes.Unsupported, tok, "Managed arrays 'T[]' are not supported in Vibranium; use Vec<T> or Span<T>."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
            }

            case AstKind.ExprStackAlloc:
            {
                if (n.A >= 0)
                {
                    int elemT = DeclBinder.ResolveTypeNode(n.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                    if (types.IsLinear(elemT, in ast))
                    {
                        diags.ReportTok(VibCodes.LinearViolation, tok, "Linear IDisposable resource cannot be stack-allocated in an array."u8);
                        return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
                    }
                }
                diags.ReportTok(VibCodes.Unsupported, tok, "User 'stackalloc' expressions are banned in Vibranium; use Span<T> collection expressions '[...]' or Vec<T>."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
            }

            case AstKind.ExprCollLit:
                return LowerCollectionLiteral(in n, expectedTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, collectionDestinationPlace);

            case AstKind.ExprUnary:
            {
                int uOp = LowerUnaryAsOperand(in n, expectedTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, collectionDestinationPlace);
                return ConvertOperandIfNeeded(uOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprCast:
            {
                int dstType = DeclBinder.ResolveTypeNode(n.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags);
                DeclBinder.DrainConcreteTypeQueue(in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                if (dstType == TypeIds.Error || dstType == TypeIds.Void)
                {
                    if (dstType == TypeIds.Void)
                    {
                        diags.ReportTok(VibCodes.Unsupported, tok, "Cannot cast to 'void' in Vibranium."u8);
                    }
                    return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.I32, tokIdx));
                }

                AstNode subNode = ast.Nodes[n.B];
                if (subNode.Kind == AstKind.ExprCollLit || (subNode.Kind == AstKind.ExprDefault && subNode.A < 0) ||
                    (collectionDestinationPlace >= 0 && dstType == expectedTypeId && IsDirectCollectionRvalue(n.B, in ast)))
                {
                    int targetOp = LowerExprAsOperand(n.B, dstType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags,
                        dstType == expectedTypeId ? collectionDestinationPlace : -1);
                    return ConvertOperandIfNeeded(targetOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                }
                if (subNode.Kind == AstKind.ExprNull)
                {
                    if (types.Items[dstType].Kind != TypeKinds.Class)
                    {
                        diags.ReportTok(VibCodes.Unsupported, tok, "Cannot convert 'null' to non-reference type in Vibranium."u8);
                    }
                    int nullOp = LowerExprAsOperand(n.B, dstType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    return ConvertOperandIfNeeded(nullOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, true);
                }

                // An untyped conditional or switch can use the cast target,
                // but only when every arm implicitly converts to it. A typed
                // operand still uses the existing explicit conversion of the result.
                if (subNode.Kind == AstKind.ExprCond || subNode.Kind == AstKind.ExprSwitch)
                {
                    int naturalType = InferExprType(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    if (naturalType == TypeIds.Error &&
                        ClassifyImplicitExpressionConversion(n.B, naturalType, dstType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) >= 0)
                    {
                        int targetOp = LowerExprAsOperand(n.B, dstType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                        return ConvertOperandIfNeeded(targetOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                    }
                }

                int srcOp = LowerExprAsOperand(n.B, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                int srcType = mir.Operands[srcOp].TypeId;
                if (srcType == TypeIds.Error || diags.Items.Count > diagCountBefore)
                {
                    return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, dstType, tokIdx));
                }

                TypeInfo srcInfo = types.Items[srcType];
                TypeInfo dstInfo = types.Items[dstType];

                // 1. Identity cast `(T)x`
                if (srcType == dstType)
                {
                    return ConvertOperandIfNeeded(srcOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                }

                // 2. Valid implicit union lift or shared `Span<T> -> ReadOnlySpan<T>` reborrow
                bool isValidSpanCast = dstInfo.Kind == TypeKinds.ReadOnlySpan && srcInfo.Kind == TypeKinds.Span && dstInfo.A == srcInfo.A;
                bool isValidOptionLift = dstInfo.Kind == TypeKinds.Option &&
                    (srcType == TypeIds.NoneUnit || (srcInfo.Kind == TypeKinds.SomeWrap && srcInfo.A == dstInfo.A));
                bool isValidResultLift = dstInfo.Kind == TypeKinds.Result &&
                    ((srcInfo.Kind == TypeKinds.OkWrap && srcInfo.A == dstInfo.A) || (srcInfo.Kind == TypeKinds.ErrWrap && srcInfo.A == dstInfo.B));
                if (isValidSpanCast || isValidOptionLift || isValidResultLift)
                {
                    int routed = ConvertOperandIfNeeded(srcOp, dstType, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, n.B, diags.Items.Count > diagCountBefore);
                    return ConvertOperandIfNeeded(routed, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                }

                // 3. Explicit numeric & enum casts (C# §10.3)
                bool srcNumCharEnum = types.IsInteger(srcType) || types.IsFloat(srcType);
                bool dstNumCharEnum = types.IsInteger(dstType) || types.IsFloat(dstType);
                if (!srcNumCharEnum || !dstNumCharEnum)
                {
                    if (srcType == TypeIds.Str && (dstInfo.Kind == TypeKinds.Span || dstInfo.Kind == TypeKinds.ReadOnlySpan))
                    {
                        diags.ReportTok(VibCodes.Unsupported, tok, "Conversion from 'string' to 'ReadOnlySpan<char>' is banned in Vibranium; use '.AsUtf8()' for UTF-8 bytes."u8);
                    }
                    else
                    {
                        diags.ReportTok(VibCodes.Unsupported, tok, "Invalid explicit cast between incompatible types in Vibranium."u8);
                    }
                    return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, dstType, tokIdx));
                }

                int curOwner = fctx.EnclosingOwnerDeclId;
                if (types.IsInteger(dstType) && types.IsFloat(srcType) &&
                    TryEvalFloatConstExpr(n.B, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out _, out double fConstVal))
                {
                    int effDstF = UnderlyingIntOrSelf(dstType, in types);
                    if (TryTruncateFloatConstToIntTarget(fConstVal, effDstF, out long fIntConst))
                    {
                        int fOkOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, fIntConst, dstType, tokIdx));
                        return ConvertOperandIfNeeded(fOkOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                    }
                    if (fctx.UncheckedDepth == 0)
                    {
                        diags.ReportTok(VibCodes.Unsupported, tok, "Constant floating-point value cannot be converted to target integer/char/enum type in checked mode; wrap in 'unchecked(...)' if intended."u8);
                    }
                    if (effDstF != TypeIds.NInt && effDstF != TypeIds.NUInt)
                    {
                        int fZeroOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, dstType, tokIdx));
                        return ConvertOperandIfNeeded(fZeroOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                    }
                    // Nonconstant native casts use the ordinary saturating runtime
                    // conversion, not the fixed-width unchecked constant-zero rule.
                }
                if (dstType == TypeIds.F32 && TryEvalTypedIntConstExpr(n.B, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out int fSrcITid, out long fSrcIVal))
                {
                    uint fBits = types.IsUnsignedInteger(fSrcITid)
                        ? (uint)DeclBinder.ULongToSingleBits((ulong)fSrcIVal)
                        : (uint)DeclBinder.LongToSingleBits(fSrcIVal);
                    int fConstOp = mir.AddOperand(new MirOperand(MirOpKinds.FloatConst, -1, (long)fBits, TypeIds.F32, tokIdx));
                    return ConvertOperandIfNeeded(fConstOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                }
                if (types.IsInteger(dstType) && TryEvalTypedIntConstExpr(n.B, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out int cSrcTid, out long cVal))
                {
                    int effSrcI = UnderlyingIntOrSelf(cSrcTid, in types);
                    int effDstI = UnderlyingIntOrSelf(dstType, in types);
                    if (fctx.UncheckedDepth == 0 &&
                        !ConstantFitsInExplicitIntTarget(effSrcI, cVal, effDstI, in types))
                    {
                        diags.ReportTok(VibCodes.Unsupported, tok, "Constant value cannot be converted to target integer/enum type in checked mode; wrap in 'unchecked(...)' if truncation is intended."u8);
                    }
                    else if (fctx.UncheckedDepth == 0 && (effDstI == TypeIds.NInt || effDstI == TypeIds.NUInt) &&
                        !ConstantFitsInExplicitIntTarget(effSrcI, cVal, effDstI == TypeIds.NInt ? TypeIds.I32 : TypeIds.U32, in types))
                    {
                        diags.ReportTok(VibCodes.Unsupported, tok,
                            "C# warning CS8778 is not permitted in Vibranium: Constant value may overflow the native integer type at runtime; use 'unchecked(...)' if intended."u8);
                    }
                    long masked = TruncateConstToType(cVal, effDstI);
                    int cOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, masked, dstType, tokIdx));
                    return ConvertOperandIfNeeded(cOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
                }

                int casted = EmitCastToTemp(srcOp, dstType, tokIdx, ref fctx, ref mir);
                return ConvertOperandIfNeeded(casted, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprBinary:
            {
                int bOp = LowerBinaryAsOperand(exprId, in n, expectedTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                return ConvertOperandIfNeeded(bOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprAssign:
            {
                int aOp = LowerAssignAsOperand(in n, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags,
                    valueUsed: expectedTypeId != TypeIds.Void);
                return ConvertOperandIfNeeded(aOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprCond:
                return LowerConditionalExpr(exprId, in n, expectedTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);

            case AstKind.ExprIsPattern:
            {
                // One pattern path owns source warnings, generic cuts and DA;
                // declaration/type patterns must not bypass those checks.
                int resTmp = fctx.NewTemp(TypeIds.Bool, tokIdx, ref mir);
                int resPl = mir.AddPlaceLocal(resTmp, TypeIds.Bool);
                int tBlk = fctx.NewBlock();
                int fBlk = fctx.NewBlock();
                int mBlk = fctx.NewBlock();
                LowerIsPatternBranch(n.A, n.B, tokIdx, tBlk, fBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                fctx.CurBlock = tBlk;
                fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, TypeIds.Bool, mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, 1, TypeIds.Bool, tokIdx)), 0, 0, 0, tokIdx));
                fctx.Terminate(new MirTerm(MirTermKind.Goto, mBlk, 0, 0, 0, 0, 0, tokIdx));
                fctx.CurBlock = fBlk;
                fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, TypeIds.Bool, mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, 0, TypeIds.Bool, tokIdx)), 0, 0, 0, tokIdx));
                fctx.Terminate(new MirTerm(MirTermKind.Goto, mBlk, 0, 0, 0, 0, 0, tokIdx));
                fctx.CurBlock = mBlk;
                int isOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, resPl, 0, TypeIds.Bool, tokIdx));
                return ConvertOperandIfNeeded(isOp, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, exprId, diags.Items.Count > diagCountBefore);
            }

            case AstKind.ExprSwitch:
                return LowerSwitchExprAsOperand(exprId, in n, expectedTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }

        diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported expression in Vibranium."u8);
        return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
    }

    private static int LowerIndexValue(int exprId, int tokIdx, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta,
        ref Interner names, ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags, out int pl)
    {
        pl = LowerPlace(exprId, isMut: false, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        int elemT = mir.Places[pl].TypeId;
        int derefOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, elemT, tokIdx,
            SourceExpressionStartToken(exprId, in ast)));
        int valTmp = fctx.NewTemp(elemT, tokIdx, ref mir);
        int valPl = mir.AddPlaceLocal(valTmp, elemT);
        fctx.Emit(new MirInst(MirOp.AssignUse, valPl, -1, 0, elemT, derefOp, 0, 0, 0, tokIdx));
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, valPl, 0, elemT, tokIdx));
    }

    private static int LowerRangeSliceAsOperand(
        in AstNode idxExpr,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        Token tok = ta.Tokens[tokIdx];
        AstNode rangeNode = ast.Nodes[idxExpr.D];
        int collType = InferExprType(idxExpr.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        TypeInfo cti = types.Items[collType];

        if (cti.Kind == TypeKinds.Struct || cti.Kind == TypeKinds.Class)
        {
            int slMethod = FindUserSliceTwoIntMethod(collType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            bool hasLen = HasUserIntLengthOrCount(collType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int rngLenFuncId, out _);
            if (slMethod < 0 || !hasLen)
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "Implicit Range ('a..b') requires an accessible 'int Length'/'int Count' and 'Slice(int, int)' method."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
            }
            var emptyM = new Vec<int>();
            int slInstId = DeclBinder.EnsureFuncInstance(slMethod, collType, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
            FuncInstance slInst = mir.FuncInstances[slInstId];
            PassMode recvMode = mir.ParamSigs[slInst.ParamSigStart].Mode;
            bool mutRecv = recvMode == PassMode.ThisMut;
            bool startFromEnd = rangeNode.A >= 0 && ast.Nodes[rangeNode.A].Kind == AstKind.ExprFromEnd;
            bool endFromEnd = rangeNode.B >= 0 && ast.Nodes[rangeNode.B].Kind == AstKind.ExprFromEnd;
            bool readsLen = rangeNode.B < 0 || startFromEnd || endFromEnd;
            bool lenNeedsMut = readsLen && rngLenFuncId >= 0 &&
                DeclBinder.GetReceiverPassMode(ast.Funcs[rngLenFuncId], collType, in ast, in types, bctx.IdDispose) == PassMode.ThisMut;
            bool needMut = mutRecv || lenNeedsMut;
            int recvPl = LowerPlaceOrTemp(idxExpr.A, collType, needMut, needMut, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            recvPl = ReserveReceiverPlace(recvPl, collType, isMut: needMut, isTwoPhase: needMut, tokIdx, ref fctx, ref mir);

            // Evaluate BOTH Range Start and End bound expressions left-to-right into temps BEFORE reading Length/Count once.
            int rawStartOp;
            if (rangeNode.A >= 0)
            {
                int sExpr = startFromEnd ? ast.Nodes[rangeNode.A].A : rangeNode.A;
                int sVal = LowerExprAsOperand(sExpr, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                int stTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
                int stPl = mir.AddPlaceLocal(stTmp, TypeIds.I32);
                fctx.Emit(new MirInst(MirOp.AssignUse, stPl, -1, 0, TypeIds.I32, sVal, 0, 0, 0, tokIdx));
                rawStartOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, stPl, 0, TypeIds.I32, tokIdx));
            }
            else
            {
                rawStartOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
            }

            int rawEndOp = -1;
            if (rangeNode.B >= 0)
            {
                int eExpr = endFromEnd ? ast.Nodes[rangeNode.B].A : rangeNode.B;
                int eVal = LowerExprAsOperand(eExpr, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                int edTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
                int edPl = mir.AddPlaceLocal(edTmp, TypeIds.I32);
                fctx.Emit(new MirInst(MirOp.AssignUse, edPl, -1, 0, TypeIds.I32, eVal, 0, 0, 0, tokIdx));
                rawEndOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, edPl, 0, TypeIds.I32, tokIdx));
            }

            int cachedTot = -1;
            int totOp = readsLen
                ? LowerUserLengthOrCountOnce(recvPl, collType, ref cachedTot, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                : -1;

            int uStartOp = rawStartOp;
            if (startFromEnd)
            {
                int sSubTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
                int sSubPl = mir.AddPlaceLocal(sSubTmp, TypeIds.I32);
                fctx.Emit(new MirInst(MirOp.AssignBin, sSubPl, -1, 0, TypeIds.I32, (int)MirBinOp.Sub, totOp, rawStartOp, 0, tokIdx));
                uStartOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, sSubPl, 0, TypeIds.I32, tokIdx));
            }

            int uEndOp;
            if (rangeNode.B < 0)
            {
                uEndOp = totOp;
            }
            else if (endFromEnd)
            {
                int eSubTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
                int eSubPl = mir.AddPlaceLocal(eSubTmp, TypeIds.I32);
                fctx.Emit(new MirInst(MirOp.AssignBin, eSubPl, -1, 0, TypeIds.I32, (int)MirBinOp.Sub, totOp, rawEndOp, 0, tokIdx));
                uEndOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, eSubPl, 0, TypeIds.I32, tokIdx));
            }
            else
            {
                uEndOp = rawEndOp;
            }

            int uLenTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
            int uLenPl = mir.AddPlaceLocal(uLenTmp, TypeIds.I32);
            fctx.Emit(new MirInst(MirOp.AssignBin, uLenPl, -1, 0, TypeIds.I32, (int)MirBinOp.Sub, uEndOp, uStartOp, 0, tokIdx));
            int uLenOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, uLenPl, 0, TypeIds.I32, tokIdx));

            int caStart = mir.CallArgs.Count;
            if (cti.Kind == TypeKinds.Class)
            {
                int recvOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, recvPl, 0, collType, tokIdx));
                mir.CallArgs.Push(new MirCallArg(recvMode, recvOp, tokIdx));
            }
            else
            {
                mir.CallArgs.Push(new MirCallArg(recvMode, recvPl, tokIdx));
            }
            mir.CallArgs.Push(new MirCallArg(PassMode.ByValue, uStartOp, tokIdx));
            mir.CallArgs.Push(new MirCallArg(PassMode.ByValue, uLenOp, tokIdx));

            int callFlags = needMut ? 2 : 0;
            if ((slInst.Flags & DeclFlags.ReturnsByRef) != 0)
            {
                bool rMut = (slInst.Flags & DeclFlags.ReturnRefMut) != 0;
                int refTmp = fctx.NewTempRef(slInst.ReturnTypeId, rMut, tokIdx);
                fctx.EmitCall(new MirInst(MirOp.Call, -1, refTmp, (rMut ? 1 : 0) | callFlags, slInst.ReturnTypeId, slInstId, caStart, 3, 0, tokIdx), in mir);
                var deref = new Vec<MirProj>(1);
                deref.Push(new MirProj(MirProjKinds.Deref, 0, slInst.ReturnTypeId, -1, 0));
                int dPl = mir.AddPlace(refTmp, deref.AsReadOnlySpan(), slInst.ReturnTypeId);
                return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dPl, 0, slInst.ReturnTypeId, tokIdx));
            }

            int uDstTmp = fctx.NewTemp(slInst.ReturnTypeId, tokIdx, ref mir);
            int uDstPl = mir.AddPlaceLocal(uDstTmp, slInst.ReturnTypeId);
            fctx.EmitCall(new MirInst(MirOp.Call, uDstPl, -1, callFlags, slInst.ReturnTypeId, slInstId, caStart, 3, 0, tokIdx), in mir);
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, uDstPl, 0, slInst.ReturnTypeId, tokIdx));
        }

        if (cti.Kind != TypeKinds.Vec && cti.Kind != TypeKinds.Span && cti.Kind != TypeKinds.ReadOnlySpan)
        {
            diags.ReportTok(VibCodes.Unsupported, tok, "Range slicing requires Vec<T>, Span<T>, ReadOnlySpan<T>, or a type with Length/Count and Slice(int, int)."u8);
            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
        }

        bool isVec = cti.Kind == TypeKinds.Vec;
        bool isExcl = cti.Kind == TypeKinds.Vec || cti.Kind == TypeKinds.Span;
        int outSpanType = isVec ? types.MakeSpan(cti.A, isReadOnly: false) : collType;

        int collPl = LowerPlaceOrTemp(idxExpr.A, collType, isMut: isExcl, isTwoPhase: isExcl, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        collPl = ReserveReceiverPlace(collPl, collType, isMut: isExcl, isTwoPhase: isExcl, tokIdx, ref fctx, ref mir);

        bool cStartFromEnd = rangeNode.A >= 0 && ast.Nodes[rangeNode.A].Kind == AstKind.ExprFromEnd;
        bool cEndFromEnd = rangeNode.B >= 0 && ast.Nodes[rangeNode.B].Kind == AstKind.ExprFromEnd;
        bool cReadsLen = rangeNode.B < 0 || cStartFromEnd || cEndFromEnd;

        int cRawStartOp;
        if (rangeNode.A >= 0)
        {
            int sExpr = cStartFromEnd ? ast.Nodes[rangeNode.A].A : rangeNode.A;
            int sVal = LowerExprAsOperand(sExpr, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int stTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
            int stPl = mir.AddPlaceLocal(stTmp, TypeIds.I32);
            fctx.Emit(new MirInst(MirOp.AssignUse, stPl, -1, 0, TypeIds.I32, sVal, 0, 0, 0, tokIdx));
            cRawStartOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, stPl, 0, TypeIds.I32, tokIdx));
        }
        else
        {
            cRawStartOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
        }

        int cRawEndOp = -1;
        if (rangeNode.B >= 0)
        {
            int eExpr = cEndFromEnd ? ast.Nodes[rangeNode.B].A : rangeNode.B;
            int eVal = LowerExprAsOperand(eExpr, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int edTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
            int edPl = mir.AddPlaceLocal(edTmp, TypeIds.I32);
            fctx.Emit(new MirInst(MirOp.AssignUse, edPl, -1, 0, TypeIds.I32, eVal, 0, 0, 0, tokIdx));
            cRawEndOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, edPl, 0, TypeIds.I32, tokIdx));
        }

        int cTotOp = cReadsLen
            ? LowerCollectionLengthOp(collPl, isVec, collType, tokIdx, ref fctx, ref mir)
            : -1;

        int startOp = cRawStartOp;
        if (cStartFromEnd)
        {
            int sSubTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
            int sSubPl = mir.AddPlaceLocal(sSubTmp, TypeIds.I32);
            fctx.Emit(new MirInst(MirOp.AssignBin, sSubPl, -1, 0, TypeIds.I32, (int)MirBinOp.Sub, cTotOp, cRawStartOp, 0, tokIdx));
            startOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, sSubPl, 0, TypeIds.I32, tokIdx));
        }

        int endOp;
        if (rangeNode.B < 0)
        {
            endOp = cTotOp;
        }
        else if (cEndFromEnd)
        {
            int eSubTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
            int eSubPl = mir.AddPlaceLocal(eSubTmp, TypeIds.I32);
            fctx.Emit(new MirInst(MirOp.AssignBin, eSubPl, -1, 0, TypeIds.I32, (int)MirBinOp.Sub, cTotOp, cRawEndOp, 0, tokIdx));
            endOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, eSubPl, 0, TypeIds.I32, tokIdx));
        }
        else
        {
            endOp = cRawEndOp;
        }

        int lenTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
        int lenPl = mir.AddPlaceLocal(lenTmp, TypeIds.I32);
        fctx.Emit(new MirInst(MirOp.AssignBin, lenPl, -1, 0, TypeIds.I32, (int)MirBinOp.Sub, endOp, startOp, 0, tokIdx));
        int lenOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, lenPl, 0, TypeIds.I32, tokIdx));

        int dstTmp = fctx.NewTemp(outSpanType, tokIdx, ref mir);
        int dstPl = mir.AddPlaceLocal(dstTmp, outSpanType);
        if (isVec)
        {
            var ops = new Vec<int>(2);
            ops.Push(startOp);
            ops.Push(lenOp);
            var pls = new Vec<int>(1);
            pls.Push(collPl);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 2, outSpanType, (int)MirIntrinsic.VecSliceMut, mir.PushIdList(ops.AsReadOnlySpan()), 2, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
        }
        else
        {
            int spRead = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, collPl, 0, collType, tokIdx));
            var ops = new Vec<int>(3);
            ops.Push(spRead);
            ops.Push(startOp);
            ops.Push(lenOp);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, isExcl ? 2 : 0, outSpanType, (int)MirIntrinsic.SpanSlice, mir.PushIdList(ops.AsReadOnlySpan()), 3, 0, tokIdx));
        }
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, outSpanType, tokIdx));
    }

    private static bool CanNarrowIntConstant(long val, TokKind litKind, int targetTypeId, in TypeTable types)
    {
        if (types.Items[targetTypeId].Kind == TypeKinds.Enum)
        {
            return val == 0;
        }
        bool isInt32Lit = litKind == TokKind.IntLit && (ulong)val <= 2147483647UL;
        bool isInt64Lit = litKind == TokKind.LongLit || (litKind == TokKind.IntLit && (ulong)val > 2147483647UL && (ulong)val <= 9223372036854775807UL);
        bool isUInt32Lit = litKind == TokKind.UIntLit && (ulong)val <= 4294967295UL;
        switch (targetTypeId)
        {
            case TypeIds.I8: return isInt32Lit && val >= -128 && val <= 127;
            case TypeIds.U8: return isInt32Lit && val >= 0 && val <= 255;
            case TypeIds.I16: return isInt32Lit && val >= -32768 && val <= 32767;
            // C# permits constant int-to-ushort, but not int-to-char.
            // Character values require a char literal or an explicit cast.
            case TypeIds.U16: return isInt32Lit && val >= 0 && val <= 65535;
            case TypeIds.I32: return isInt32Lit;
            case TypeIds.U32: return isInt32Lit && val >= 0;
            case TypeIds.I64: return isInt32Lit || isInt64Lit || isUInt32Lit;
            case TypeIds.NInt: return isInt32Lit;
            case TypeIds.U64: return (isInt32Lit && val >= 0) || (isInt64Lit && val >= 0) || isUInt32Lit || litKind == TokKind.ULongLit;
            case TypeIds.NUInt: return (isInt32Lit && val >= 0) || isUInt32Lit;
            default: return false;
        }
    }

    private static long TruncateConstToType(long val, int targetTypeId)
    {
        switch (targetTypeId)
        {
            case TypeIds.I8: return (sbyte)val;
            case TypeIds.U8: return (byte)val;
            case TypeIds.I16: return (short)val;
            case TypeIds.U16:
            case TypeIds.Char: return (ushort)val;
            case TypeIds.I32: return (int)val;
            case TypeIds.U32: return (uint)val;
            default: return val;
        }
    }

    private static int EmitCastToTemp(int srcOpId, int dstTypeId, int tokIdx, ref FuncLowerCtx fctx, ref MirModuleArena mir)
    {
        if (mir.Operands[srcOpId].TypeId == dstTypeId) return srcOpId;
        int tmp = fctx.NewTemp(dstTypeId, tokIdx, ref mir);
        int pl = mir.AddPlaceLocal(tmp, dstTypeId);
        fctx.Emit(new MirInst(MirOp.AssignCast, pl, -1, 0, dstTypeId, srcOpId, 0, 0, 0, tokIdx));
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, dstTypeId, tokIdx));
    }

    private static int ExtractSingleBuiltInIndexArg(
        in AstNode idxNode,
        int tokIdx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref DiagnosticBag diags)
    {
        if (idxNode.C != 1)
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Built-in Vec<T>/Span<T> indexer takes exactly one argument."u8);
            return -1;
        }
        AstNode a0 = ast.Nodes[ast.Extra[idxNode.B]];
        if (CallArgBits.Mode(in a0) != PassMode.ByValue || !CheckSingleNamedArg(in a0, "index"u8, in names))
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[a0.TokIdx], "Invalid argument modifier or parameter name for Vec<T>/Span<T> indexer."u8);
            return -1;
        }
        return a0.B;
    }

    private static int ConvertOperandIfNeeded(int opId, int expectedTypeId, int tokIdx, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, in BinderCtx bctx, in TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags) => ConvertOperandIfNeeded(opId, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, -1, false);

    private static int ConvertOperandIfNeeded(int opId, int expectedTypeId, int tokIdx, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, in BinderCtx bctx, in TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags, int srcExprId) => ConvertOperandIfNeeded(opId, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, srcExprId, false);

    private static int ConvertOperandIfNeeded(
        int opId,
        int expectedTypeId,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        int srcExprId,
        bool suppressDiag)
    {
        if (expectedTypeId < 0 || expectedTypeId == TypeIds.Void || expectedTypeId == TypeIds.Error)
        {
            return opId;
        }
        MirOperand op = mir.Operands[opId];
        int srcType = op.TypeId;
        if (srcType == expectedTypeId || srcType == TypeIds.Error)
        {
            return opId;
        }

        TypeInfo dstInfo = types.Items[expectedTypeId];
        TypeInfo srcInfo = types.Items[srcType];

        // Lift Some<T> or NoneType -> Option<T>
        if (dstInfo.Kind == TypeKinds.Option)
        {
            int innerT = dstInfo.A;
            if (srcType == TypeIds.NoneUnit)
            {
                int tmp = fctx.NewTemp(expectedTypeId, tokIdx, ref mir);
                int pl = mir.AddPlaceLocal(tmp, expectedTypeId);
                fctx.Emit(new MirInst(MirOp.LiftOptionNone, pl, -1, 0, innerT, 0, 0, 0, 0, tokIdx));
                return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, expectedTypeId, tokIdx));
            }
            if (srcInfo.Kind == TypeKinds.SomeWrap && srcInfo.A == innerT)
            {
                int uTmp = fctx.NewTemp(srcInfo.A, tokIdx, ref mir);
                int uPl = mir.AddPlaceLocal(uTmp, srcInfo.A);
                fctx.Emit(new MirInst(MirOp.UnwrapWrap, uPl, -1, 0, srcInfo.A, opId, 0, 0, 0, tokIdx));
                int uOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, uPl, 0, srcInfo.A, tokIdx));
                int oTmp = fctx.NewTemp(expectedTypeId, tokIdx, ref mir);
                int oPl = mir.AddPlaceLocal(oTmp, expectedTypeId);
                fctx.Emit(new MirInst(MirOp.LiftOptionSome, oPl, -1, 0, innerT, uOp, 0, 0, 0, tokIdx));
                return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, oPl, 0, expectedTypeId, tokIdx));
            }
        }

        // Lift Ok<T> or Err<E> -> Result<T, E>
        if (dstInfo.Kind == TypeKinds.Result)
        {
            if (srcInfo.Kind == TypeKinds.OkWrap && srcInfo.A == dstInfo.A)
            {
                int uTmp = fctx.NewTemp(srcInfo.A, tokIdx, ref mir);
                int uPl = mir.AddPlaceLocal(uTmp, srcInfo.A);
                fctx.Emit(new MirInst(MirOp.UnwrapWrap, uPl, -1, 0, srcInfo.A, opId, 0, 0, 0, tokIdx));
                int uOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, uPl, 0, srcInfo.A, tokIdx));
                int rTmp = fctx.NewTemp(expectedTypeId, tokIdx, ref mir);
                int rPl = mir.AddPlaceLocal(rTmp, expectedTypeId);
                fctx.Emit(new MirInst(MirOp.LiftResultOk, rPl, -1, 0, expectedTypeId, uOp, 0, 0, 0, tokIdx));
                return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, rPl, 0, expectedTypeId, tokIdx));
            }
            if (srcInfo.Kind == TypeKinds.ErrWrap && srcInfo.A == dstInfo.B)
            {
                int uTmp = fctx.NewTemp(srcInfo.A, tokIdx, ref mir);
                int uPl = mir.AddPlaceLocal(uTmp, srcInfo.A);
                fctx.Emit(new MirInst(MirOp.UnwrapWrap, uPl, -1, 0, srcInfo.A, opId, 0, 0, 0, tokIdx));
                int uOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, uPl, 0, srcInfo.A, tokIdx));
                int rTmp = fctx.NewTemp(expectedTypeId, tokIdx, ref mir);
                int rPl = mir.AddPlaceLocal(rTmp, expectedTypeId);
                fctx.Emit(new MirInst(MirOp.LiftResultErr, rPl, -1, 0, expectedTypeId, uOp, 0, 0, 0, tokIdx));
                return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, rPl, 0, expectedTypeId, tokIdx));
            }
        }

        // Implicit Span<T> -> ReadOnlySpan<T>
        if (dstInfo.Kind == TypeKinds.ReadOnlySpan && srcInfo.Kind == TypeKinds.Span && dstInfo.A == srcInfo.A)
        {
            int roTmp = fctx.NewTemp(expectedTypeId, tokIdx, ref mir);
            int roPl = mir.AddPlaceLocal(roTmp, expectedTypeId);
            var args = new Vec<int>(1);
            args.Push(opId);
            fctx.Emit(new MirInst(MirOp.Intrinsic, roPl, -1, 0, expectedTypeId, (int)MirIntrinsic.SpanToReadOnly, mir.PushIdList(args.AsReadOnlySpan()), 1, 0, tokIdx));
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, roPl, 0, expectedTypeId, tokIdx));
        }

        // C# constant 0 / 0.0 -> Enum
        if (dstInfo.Kind == TypeKinds.Enum)
        {
            bool isZeroConst = (op.Kind == MirOpKinds.IntConst && op.IntVal == 0 && srcType != TypeIds.Char && srcInfo.Kind != TypeKinds.Enum) ||
                               (op.Kind == MirOpKinds.FloatConst && op.PlaceOrLitIdx < 0 && (srcType == TypeIds.F32 ? ((uint)op.IntVal & 0x7FFFFFFFu) == 0u : ((ulong)op.IntVal & 0x7FFFFFFFFFFFFFFFUL) == 0UL)) ||
                               (op.Kind == MirOpKinds.FloatConst && op.PlaceOrLitIdx >= 0 && IsZeroFloatLitText(ta.GetLit(op.PlaceOrLitIdx))) ||
                               (srcExprId >= 0 && ClassifyByValueConversionWithCtx(srcExprId, srcType, expectedTypeId, in fctx, in names, in bctx, in ast, in ta, in types) >= 0);
            if (isZeroConst)
            {
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, expectedTypeId, tokIdx));
            }
            if (!suppressDiag)
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Cannot implicitly convert expression to enum type in Vibranium."u8);
            }
            return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId, tokIdx));
        }

        // Numeric implicit widening / constant narrowing
        if (srcInfo.Kind != TypeKinds.Enum && dstInfo.Kind != TypeKinds.Enum &&
            (types.IsInteger(srcType) || types.IsFloat(srcType)) &&
            (types.IsInteger(expectedTypeId) || types.IsFloat(expectedTypeId)))
        {
            bool validNumConv = CanImplicitNumericWiden(srcType, expectedTypeId) ||
                (srcExprId >= 0 && ClassifyByValueConversionWithCtx(srcExprId, srcType, expectedTypeId, in fctx, in names, in bctx, in ast, in ta, in types) >= 0) ||
                (srcExprId < 0 && op.Kind == MirOpKinds.IntConst && srcType == TypeIds.I32 && FitsInt32ValueInTarget(op.IntVal, expectedTypeId)) ||
                (srcExprId < 0 && op.Kind == MirOpKinds.IntConst && srcType == TypeIds.I64 && expectedTypeId == TypeIds.U64 && op.IntVal >= 0);

            if (!validNumConv && !suppressDiag)
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Cannot implicitly convert numeric expression to target type in Vibranium."u8);
            }
            if (op.Kind == MirOpKinds.IntConst && types.IsInteger(expectedTypeId))
            {
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, TruncateConstToType(op.IntVal, expectedTypeId), expectedTypeId, tokIdx));
            }
            if (op.Kind == MirOpKinds.IntConst && expectedTypeId == TypeIds.F32)
            {
                uint fBits = types.IsUnsignedInteger(srcType)
                    ? (uint)DeclBinder.ULongToSingleBits((ulong)op.IntVal)
                    : (uint)DeclBinder.LongToSingleBits(op.IntVal);
                return mir.AddOperand(new MirOperand(MirOpKinds.FloatConst, -1, (long)fBits, TypeIds.F32, tokIdx));
            }
            return EmitCastToTemp(opId, expectedTypeId, tokIdx, ref fctx, ref mir);
        }

        if (!suppressDiag)
        {
            if (srcType == TypeIds.Str && (dstInfo.Kind == TypeKinds.Span || dstInfo.Kind == TypeKinds.ReadOnlySpan))
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Conversion from 'string' to 'ReadOnlySpan<char>' is banned in Vibranium; use '.AsUtf8()' for UTF-8 bytes."u8);
            }
            else
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Cannot implicitly convert expression to target type in Vibranium."u8);
            }
        }
        return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId, tokIdx));
    }

    private static int EmitZeroArgInstanceCall(int instId, int recvPlaceId, int recvTypeId, int tokIdx, ref FuncLowerCtx fctx, in TypeTable types, ref MirModuleArena mir)
    {
        FuncInstance fnInst = mir.FuncInstances[instId];
        PassMode recvMode = mir.ParamSigs[fnInst.ParamSigStart].Mode;
        int caStart = mir.CallArgs.Count;
        if (types.Items[recvTypeId].Kind == TypeKinds.Class)
        {
            int recvOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, recvPlaceId, 0, recvTypeId, tokIdx));
            mir.CallArgs.Push(new MirCallArg(recvMode, recvOp, tokIdx));
        }
        else
        {
            mir.CallArgs.Push(new MirCallArg(recvMode, recvPlaceId, tokIdx));
        }

        if ((fnInst.Flags & DeclFlags.ReturnsByRef) != 0)
        {
            bool rMut = (fnInst.Flags & DeclFlags.ReturnRefMut) != 0;
            int refTmp = fctx.NewTempRef(fnInst.ReturnTypeId, rMut, tokIdx);
            fctx.EmitCall(new MirInst(MirOp.Call, -1, refTmp, rMut ? 1 : 0, fnInst.ReturnTypeId, instId, caStart, 1, 0, tokIdx), in mir);
            var deref = new Vec<MirProj>(1);
            deref.Push(new MirProj(MirProjKinds.Deref, 0, fnInst.ReturnTypeId, -1, 0));
            int dPl = mir.AddPlace(refTmp, deref.AsReadOnlySpan(), fnInst.ReturnTypeId);
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dPl, 0, fnInst.ReturnTypeId, tokIdx));
        }

        int dstTmp = fctx.NewTemp(fnInst.ReturnTypeId, tokIdx, ref mir);
        int dstPl = mir.AddPlaceLocal(dstTmp, fnInst.ReturnTypeId);
        fctx.EmitCall(new MirInst(MirOp.Call, dstPl, -1, 0, fnInst.ReturnTypeId, instId, caStart, 1, 0, tokIdx), in mir);
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, fnInst.ReturnTypeId, tokIdx));
    }

    private static int SourceExpressionStartToken(int expressionId, in AstArena ast)
    {
        AstNode expression = ast.Nodes[expressionId];
        while (expression.Kind == AstKind.ExprMember || expression.Kind == AstKind.ExprIndex || expression.Kind == AstKind.ExprCall)
        {
            expression = ast.Nodes[expression.A];
        }
        return expression.TokIdx;
    }

    private static int LowerMemberAccessAsOperand(
        int exprId,
        in AstNode n,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int tokIdx = n.TokIdx;
        Token tok = ta.Tokens[tokIdx];
        if (Bytes.Eq(names.Text(n.B), "Deconstruct"u8))
        {
            int bt = InferExprType(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            if (types.IsLinear(bt, in ast))
            {
                diags.ReportTok(VibCodes.LinearViolation, tok, "Direct access to '.Deconstruct' on linear union wrappers is banned in Vibranium."u8);
            }
            else
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "Direct access to '.Deconstruct' is banned in Vibranium."u8);
            }
            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
        }

        // Static member (`Prelude.None`, `Array.MaxLength`, `Enum.Member`, `PathText.MaxLength`, numeric/float MinValue/MaxValue/NaN/..., etc.)
        if (TryResolveStaticTypeTarget(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int stDeclId, out int stTid, memberHintNameId: n.B, isMethodCallHint: false))
        {
            if (stDeclId >= 0)
            {
                TypeDecl td = ast.Types[stDeclId];
                int callerOwner = ast.Funcs[fctx.FuncDeclId].OwnerDeclId;
                int callerUnit = callerOwner >= 0 ? ast.Types[callerOwner].UnitKind : UnitKinds.App;
                bool sameOrNested = IsSameOrNestedInsideType(callerOwner, stDeclId, in ast);
                bool typeVisible = sameOrNested || bctx.CompilingStdItself || td.UnitKind == callerUnit || (td.Flags & DeclFlags.Public) != 0;
                if (typeVisible)
                {
                    for (int f = 0; f < td.FieldCount; f++)
                    {
                        FieldDecl fd = ast.Fields[td.FieldStart + f];
                        if (fd.NameId == n.B && (fd.Flags & DeclFlags.IsConst) != 0)
                        {
                            bool fieldVisible = td.Kind == TypeDeclKinds.Enum || sameOrNested ||
                                ((fd.Flags & DeclFlags.Private) == 0 && ((fd.Flags & DeclFlags.Public) != 0 || ((fd.Flags & DeclFlags.Internal) != 0 && (bctx.CompilingStdItself || td.UnitKind == callerUnit))));
                            if (!fieldVisible) break;
                            int resT = td.Kind == TypeDeclKinds.Enum
                                ? stTid
                                : DeclBinder.ResolveTypeNode(fd.TypeNode, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                            if (fd.HasConstVal != 0 || td.Kind == TypeDeclKinds.Enum)
                            {
                                if (resT == TypeIds.Str)
                                {
                                    return MakeConstStringOperand(fd.ConstVal, tokIdx, ref mir);
                                }
                                int opK = types.IsFloat(resT) ? MirOpKinds.FloatConst : (resT == TypeIds.Bool ? MirOpKinds.BoolConst : MirOpKinds.IntConst);
                                return mir.AddOperand(new MirOperand(opK, -1, fd.ConstVal, resT, tokIdx));
                            }
                            if (fd.InitExpr >= 0 && fd.InitExpr != exprId)
                            {
                                return LowerExprAsOperand(fd.InitExpr, resT, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                            }
                            return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, resT, tokIdx));
                        }
                    }
                    int sPropGet = FindMethodInType(stDeclId, MakePropGetterLookup(n.B, in ast, in names), 0, isStatic: true, in ast);
                    if (sPropGet >= 0 && IsAccessibleFuncFromCaller(sPropGet, ref fctx, in ast, in bctx))
                    {
                        var emptyM = new Vec<int>();
                        int gInst = DeclBinder.EnsureFuncInstance(sPropGet, stTid, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                        FuncInstance fnInst = mir.FuncInstances[gInst];
                        if ((fnInst.Flags & DeclFlags.ReturnsByRef) != 0)
                        {
                            bool rMut = (fnInst.Flags & DeclFlags.ReturnRefMut) != 0;
                            int refTmp = fctx.NewTempRef(fnInst.ReturnTypeId, rMut, tokIdx);
                            fctx.EmitCall(new MirInst(MirOp.Call, -1, refTmp, rMut ? 1 : 0, fnInst.ReturnTypeId, gInst, mir.CallArgs.Count, 0, 0, tokIdx), in mir);
                            var deref = new Vec<MirProj>(1);
                            deref.Push(new MirProj(MirProjKinds.Deref, 0, fnInst.ReturnTypeId, -1, 0));
                            int dPl = mir.AddPlace(refTmp, deref.AsReadOnlySpan(), fnInst.ReturnTypeId);
                            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dPl, 0, fnInst.ReturnTypeId, tokIdx));
                        }
                        int dstTmp = fctx.NewTemp(fnInst.ReturnTypeId, tokIdx, ref mir);
                        int dstPl = mir.AddPlaceLocal(dstTmp, fnInst.ReturnTypeId);
                        fctx.EmitCall(new MirInst(MirOp.Call, dstPl, -1, 0, fnInst.ReturnTypeId, gInst, mir.CallArgs.Count, 0, 0, tokIdx), in mir);
                        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, fnInst.ReturnTypeId, tokIdx));
                    }
                }
            }

            if (stDeclId < 0)
            {
                ReadOnlySpan<byte> lhsName = GetStaticTargetEffectiveLeafName(n.A, in fctx, in ast, in ta, in names, in bctx, out int lhsLeafId);
                ReadOnlySpan<byte> memName = names.Text(n.B);
                if (lhsLeafId == bctx.IdPrelude && n.B == bctx.IdNone)
                {
                    return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, TypeIds.NoneUnit, tokIdx));
                }
                if (DeclBinder.TryEvalBuiltinNumericConstMember(lhsName, memName, out int numTypeId, out long numBits, out bool isFloatBits))
                {
                    return mir.AddOperand(new MirOperand(isFloatBits ? MirOpKinds.FloatConst : MirOpKinds.IntConst, -1, numBits, numTypeId, tokIdx));
                }
                if ((Bytes.Eq(lhsName, "string"u8) || Bytes.Eq(lhsName, "String"u8)) && Bytes.Eq(memName, "Empty"u8))
                {
                    return mir.AddOperand(new MirOperand(MirOpKinds.StrConst, -1, 0, TypeIds.Str, tokIdx));
                }
            }

            diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported, unresolved, or inaccessible static member access in Vibranium."u8);
            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
        }

        int recvType = InferExprType(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        if (recvType == TypeIds.Str && Bytes.Eq(names.Text(n.B), "Length"u8))
        {
            diags.ReportTok(VibCodes.Unsupported, tok, "'string.Length' is banned in Vibranium."u8);
            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
        }

        TypeInfo rti = types.Items[recvType];

        // Some<T>.Value, Ok<T>.Value, Err<E>.Error
        if ((rti.Kind == TypeKinds.SomeWrap || rti.Kind == TypeKinds.OkWrap) && n.B == bctx.IdValue)
        {
            int wOp = LowerExprAsOperand(n.A, recvType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int uTmp = fctx.NewTemp(rti.A, tokIdx, ref mir);
            int uPl = mir.AddPlaceLocal(uTmp, rti.A);
            fctx.Emit(new MirInst(MirOp.UnwrapWrap, uPl, -1, 0, rti.A, wOp, 0, 0, 0, tokIdx));
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, uPl, 0, rti.A, tokIdx));
        }
        if (rti.Kind == TypeKinds.ErrWrap && n.B == bctx.IdError)
        {
            int wOp = LowerExprAsOperand(n.A, recvType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int uTmp = fctx.NewTemp(rti.A, tokIdx, ref mir);
            int uPl = mir.AddPlaceLocal(uTmp, rti.A);
            fctx.Emit(new MirInst(MirOp.UnwrapWrap, uPl, -1, 0, rti.A, wOp, 0, 0, 0, tokIdx));
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, uPl, 0, rti.A, tokIdx));
        }

        // Banned internal union protocol members (`HasValue`, `Option.Value`, `Result.Value`)
        if (rti.Kind == TypeKinds.Option || rti.Kind == TypeKinds.OptionRef || rti.Kind == TypeKinds.OptionMut || rti.Kind == TypeKinds.Result)
        {
            if (Bytes.Eq(names.Text(n.B), "HasValue"u8) || Bytes.Eq(names.Text(n.B), "Value"u8))
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "Direct access to internal union protocol member is banned in Vibranium."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, 0, TypeIds.Bool, tokIdx));
            }
        }

        // Option / OptionRef / OptionMut properties (`IsSome`, `IsEmpty`)
        if (rti.Kind == TypeKinds.Option || rti.Kind == TypeKinds.OptionRef || rti.Kind == TypeKinds.OptionMut)
        {
            if (Bytes.Eq(names.Text(n.B), "IsSome"u8) || Bytes.Eq(names.Text(n.B), "IsEmpty"u8))
            {
                int dstTmp = fctx.NewTemp(TypeIds.Bool, tokIdx, ref mir);
                int dstPl = mir.AddPlaceLocal(dstTmp, TypeIds.Bool);
                if (rti.Kind == TypeKinds.Option)
                {
                    int oPl = LowerPlaceOrTemp(n.A, recvType, isMut: false, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    var pls = new Vec<int>(1);
                    pls.Push(oPl);
                    fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, TypeIds.Bool, (int)MirIntrinsic.OptionIsSome, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
                }
                else
                {
                    int curOp = LowerExprAsOperand(n.A, recvType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    var ops = new Vec<int>(1);
                    ops.Push(curOp);
                    fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, TypeIds.Bool, (int)MirIntrinsic.OptionIsSome, mir.PushIdList(ops.AsReadOnlySpan()), 1, 0, tokIdx));
                }
                int resOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, TypeIds.Bool, tokIdx));
                if (Bytes.Eq(names.Text(n.B), "IsEmpty"u8))
                {
                    int notTmp = fctx.NewTemp(TypeIds.Bool, tokIdx, ref mir);
                    int notPl = mir.AddPlaceLocal(notTmp, TypeIds.Bool);
                    fctx.Emit(new MirInst(MirOp.AssignUn, notPl, -1, 0, TypeIds.Bool, (int)MirUnOp.Not, resOp, 0, 0, tokIdx));
                    return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, notPl, 0, TypeIds.Bool, tokIdx));
                }
                return resOp;
            }
        }

        // Result.IsOk
        if (rti.Kind == TypeKinds.Result && Bytes.Eq(names.Text(n.B), "IsOk"u8))
        {
            int rPl = LowerPlaceOrTemp(n.A, recvType, isMut: false, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var pls = new Vec<int>(1);
            pls.Push(rPl);
            int dstTmp = fctx.NewTemp(TypeIds.Bool, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, TypeIds.Bool);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, TypeIds.Bool, (int)MirIntrinsic.ResultIsOk, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, TypeIds.Bool, tokIdx));
        }

        // Vec.Count / Vec.Capacity
        if (rti.Kind == TypeKinds.Vec && (Bytes.Eq(names.Text(n.B), "Count"u8) || Bytes.Eq(names.Text(n.B), "Capacity"u8)))
        {
            int vPl = LowerPlaceOrTemp(n.A, recvType, isMut: false, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var pls = new Vec<int>(1);
            pls.Push(vPl);
            int dstTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, TypeIds.I32);
            MirIntrinsic intr = Bytes.Eq(names.Text(n.B), "Count"u8) ? MirIntrinsic.VecCount : MirIntrinsic.VecCapacity;
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, TypeIds.I32, (int)intr, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, TypeIds.I32, tokIdx));
        }

        // Span.Length / Span.IsEmpty
        if (rti.Kind == TypeKinds.Span || rti.Kind == TypeKinds.ReadOnlySpan)
        {
            if (Bytes.Eq(names.Text(n.B), "Length"u8) || Bytes.Eq(names.Text(n.B), "IsEmpty"u8))
            {
                int spOp = LowerExprAsOperand(n.A, recvType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                var ops = new Vec<int>(1);
                ops.Push(spOp);
                int lenTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
                int lenPl = mir.AddPlaceLocal(lenTmp, TypeIds.I32);
                fctx.Emit(new MirInst(MirOp.Intrinsic, lenPl, -1, 0, TypeIds.I32, (int)MirIntrinsic.SpanLength, mir.PushIdList(ops.AsReadOnlySpan()), 1, 0, tokIdx));
                int lenOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, lenPl, 0, TypeIds.I32, tokIdx));
                if (Bytes.Eq(names.Text(n.B), "IsEmpty"u8))
                {
                    int zOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
                    int bTmp = fctx.NewTemp(TypeIds.Bool, tokIdx, ref mir);
                    int bPl = mir.AddPlaceLocal(bTmp, TypeIds.Bool);
                    fctx.Emit(new MirInst(MirOp.AssignBin, bPl, -1, 0, TypeIds.Bool, (int)MirBinOp.Eq, lenOp, zOp, 0, tokIdx));
                    return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, bPl, 0, TypeIds.Bool, tokIdx));
                }
                return lenOp;
            }
        }

        if (rti.Kind == TypeKinds.Utf8Lines || rti.Kind == TypeKinds.Utf8ArgEnum)
        {
            diags.ReportTok(VibCodes.Unsupported, tok, "Direct member access on closed foreach view is banned outside 'foreach' in Vibranium."u8);
            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
        }

        // User struct/class field or property getter
        if (rti.Kind == TypeKinds.Class || rti.Kind == TypeKinds.Struct)
        {
            int fIdx = FindInstanceFieldIndex(recvType, n.B, in types);
            if (fIdx >= 0)
            {
                int fPl = LowerPlace(exprId, isMut: false, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, fPl, 0, mir.Places[fPl].TypeId, tokIdx,
                    SourceExpressionStartToken(exprId, in ast)));
            }
            int propGet = FindMethodInType(rti.A, MakePropGetterLookup(n.B, in ast, in names), 0, isStatic: false, in ast);
            if (propGet >= 0 && IsAccessibleFuncFromCaller(propGet, ref fctx, in ast, in bctx))
            {
                var emptyM = new Vec<int>();
                int gInst = DeclBinder.EnsureFuncInstance(propGet, recvType, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                PassMode recvMode = mir.ParamSigs[mir.FuncInstances[gInst].ParamSigStart].Mode;
                int recvPl = LowerPlaceOrTemp(n.A, recvType, recvMode == PassMode.ThisMut, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                return EmitZeroArgInstanceCall(gInst, recvPl, recvType, tokIdx, ref fctx, in types, ref mir);
            }
        }

        diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported, unresolved, or inaccessible member access in Vibranium."u8);
        return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
    }

    private static int LowerCallAsOperand(
        in AstNode callNode,
        int expectedTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int tokIdx = callNode.TokIdx;
        Token tok = ta.Tokens[tokIdx];
        AstNode callee = ast.Nodes[callNode.A];
        int argCount = callNode.C;

        // 1. Bare identifier calls: C# lexical order (1) visible local functions, (2) enclosing type methods, (3) `using static` (Prelude + ConsoleIo)
        if (callee.Kind == AstKind.ExprIdent)
        {
            var lfCands = new Vec<int>();
            for (int i = 0; i < fctx.VisibleLocalFuncs.Count; i++)
            {
                int lfId = fctx.VisibleLocalFuncs[i];
                if (ast.Funcs[lfId].NameId == callee.A) lfCands.Push(lfId);
            }
            if (lfCands.Count > 0)
            {
                int bestLf = ResolveBestOverload(lfCands.AsReadOnlySpan(), -1, -1, callee.B, callee.C, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out bool lfAmb, out _);
                if (bestLf >= 0)
                {
                    return EmitResolvedUserCall(bestLf, -1, -1, callee.B, callee.C, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                }
                diags.ReportTok(VibCodes.Unsupported, tok, lfAmb
                    ? "Ambiguous local function invocation in Vibranium."u8
                    : "No applicable local function overload in Vibranium."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.Void, tokIdx));
            }

            for (int d = fctx.EnclosingOwnerDeclId; d >= 0; d = ast.Types[d].OwnerDeclId)
            {
                if (!HasAccessibleMethodNamed(d, callee.A, ref fctx, in ast, in bctx)) continue;

                bool isInnermost = d == fctx.EnclosingOwnerDeclId;
                bool canResolveOnD = isInnermost ? (fctx.OwnerTypeId >= 0 || ast.Types[d].TypeParamCount == 0) : (ast.Types[d].TypeParamCount == 0);
                if (!canResolveOnD)
                {
                    diags.ReportTok(VibCodes.Unsupported, tok, "Cannot invoke method on uninstantiated outer generic type without explicit type arguments."u8);
                    return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.Void, tokIdx));
                }

                var encCands = new Vec<int>();
                CollectTypeMethodCandidates(d, callee.A, allowInstance: isInnermost && (fctx.ThisLocalId >= 0 || fctx.IsCtor), allowStatic: true, isCtor: false, ref fctx, in ast, in bctx, ref encCands);
                int encOwnerTid = isInnermost ? fctx.OwnerTypeId : -1;
                int mId = ResolveBestOverload(encCands.AsReadOnlySpan(), encOwnerTid, -1, callee.B, callee.C, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out bool encAmb, out _);
                if (encAmb)
                {
                    diags.ReportTok(VibCodes.Unsupported, tok, "Ambiguous method invocation on enclosing type in Vibranium."u8);
                    return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.Void, tokIdx));
                }
                if (mId >= 0)
                {
                    bool isInst = (ast.Funcs[mId].Flags & DeclFlags.Static) == 0;
                    if (isInst && fctx.IsCtor)
                    {
                        diags.ReportTok(VibCodes.NullOrZeroUnsafe, tok, "Cannot access, capture, or call members on 'this' before constructor finishes initializing all fields."u8);
                        return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.I32, tokIdx));
                    }
                    int recvPl = -1;
                    int ownerTid = -1;
                    bool useTwoPhase = false;
                    if (isInst)
                    {
                        ownerTid = fctx.OwnerTypeId;
                        PassMode recvMode = DeclBinder.GetReceiverPassMode(ast.Funcs[mId], ownerTid, in ast, in types, bctx.IdDispose);
                        recvPl = mir.AddPlaceLocal(fctx.ThisLocalId, ownerTid);
                        useTwoPhase = recvMode == PassMode.ThisMut && argCount > 0;
                        if (argCount > 0)
                        {
                            recvPl = ReserveReceiverPlace(recvPl, ownerTid, recvMode == PassMode.ThisMut, useTwoPhase, tokIdx, ref fctx, ref mir);
                        }
                    }
                    return EmitResolvedUserCall(mId, ownerTid, recvPl, callee.B, callee.C, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, useTwoPhase);
                }

                // C# method-group hiding: an accessible method group on an enclosing type hides outer scopes and `using static` imports!
                diags.ReportTok(VibCodes.Unsupported, tok, "No applicable method overload on enclosing type in Vibranium."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.Void, tokIdx));
            }

            // Imported `using static` tiers (inner namespaces outward, then compilation-unit + ConsoleIo + Prelude)
            if (TryResolveUsingStaticMethodCall(callee.A, callee.B, callee.C, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int bestUsId, out int bestUsOwnerTid, out bool usCallAmb, out _))
            {
                if (usCallAmb)
                {
                    diags.ReportTok(VibCodes.Unsupported, tok, "Ambiguous static method invocation across 'using static' imports."u8);
                    return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.Void, tokIdx));
                }
                if (bestUsId >= 0)
                {
                    int usCallOp = EmitResolvedUserCall(bestUsId, bestUsOwnerTid, -1, callee.B, callee.C, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    CheckViewReturnAllowedContext(mir.Operands[usCallOp].TypeId, expectedTypeId, tok, ref diags);
                    return usCallOp;
                }
                if (bestUsId < -1 && TryLowerPreludeCall(callee.A, callee.B, callee.C, callNode.B, argCount, allowReadOnlySpanBytes: true, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int prelWinOp))
                {
                    return prelWinOp;
                }
            }

            diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported, unresolved, or inapplicable method call in Vibranium."u8);
            return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.Void, tokIdx));
        }

        // 2. Member calls (`Type.StaticMethod(...)`, `recv.InstanceMethod(...)`, or `recv.ExtensionMethod(...)`)
        if (callee.Kind == AstKind.ExprMember)
        {
            // Ban manual `.Dispose()` (`VIB006`), `.Deconstruct(...)` (`VIB000`/`VIB006`), `.TryGetValue(...)`, and direct `.GetEnumerator()` / `.MoveNext()` (`VIB000`)
            if (callee.B == bctx.IdDispose && argCount == 0 && !TryResolveStaticTypeTarget(callee.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out _, memberHintNameId: callee.B, isMethodCallHint: true))
            {
                int rt = InferExprType(callee.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (types.IsLinear(rt, in ast))
                {
                    diags.ReportTok(VibCodes.LinearViolation, tok, "Manual '.Dispose()' calls are banned in Vibranium; dispose linear IDisposable resources deterministically via 'using var' or move them by value."u8);
                    return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
                }
            }
            if (Bytes.Eq(names.Text(callee.B), "Deconstruct"u8))
            {
                int rt = InferExprType(callee.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                diags.ReportTok(types.IsLinear(rt, in ast) ? VibCodes.LinearViolation : VibCodes.Unsupported, tok, "Direct '.Deconstruct(...)' calls are banned in Vibranium."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
            }
            if (Bytes.Eq(names.Text(callee.B), "TryGetValue"u8))
            {
                int rt = InferExprType(callee.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                TypeInfo rti0 = types.Items[rt];
                if (rti0.Kind == TypeKinds.Option || rti0.Kind == TypeKinds.OptionRef || rti0.Kind == TypeKinds.OptionMut || rti0.Kind == TypeKinds.Result)
                {
                    diags.ReportTok(VibCodes.Unsupported, tok, "Direct call to internal union protocol member 'TryGetValue' is banned in Vibranium."u8);
                    return mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, 0, TypeIds.Bool, tokIdx));
                }
            }
            if (Bytes.Eq(names.Text(callee.B), "GetEnumerator"u8) && !TryResolveStaticTypeTarget(callee.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out _, memberHintNameId: callee.B, isMethodCallHint: true))
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "Direct '.GetEnumerator()' calls are banned in Vibranium; iterate with 'foreach'."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
            }

            // Static calls (`UserType.*`, `Prelude.*`, `Io.*`, `Stdio.*`, `Console.*`, `StringUtf8Extensions.*`, `Utf8SpanExtensions.*`, `int/long.TryParse`, `MemoryExtensions.*`)
            if (TryResolveStaticTypeTarget(callee.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int stDeclId, out int stTid, memberHintNameId: callee.B, isMethodCallHint: true))
            {
                if (stDeclId >= 0)
                {
                    var stCands = new Vec<int>();
                    CollectTypeMethodCandidates(stDeclId, callee.B, allowInstance: false, allowStatic: true, isCtor: false, ref fctx, in ast, in bctx, ref stCands);
                    int smId = ResolveBestOverload(stCands.AsReadOnlySpan(), stTid, -1, callee.C, callee.D, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out bool stAmb, out _);
                    if (stAmb)
                    {
                        diags.ReportTok(VibCodes.Unsupported, tok, "Ambiguous static method invocation in Vibranium."u8);
                        return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.Void, tokIdx));
                    }
                    if (smId >= 0)
                    {
                        int stCallOp = EmitResolvedUserCall(smId, stTid, -1, callee.C, callee.D, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                        CheckViewReturnAllowedContext(mir.Operands[stCallOp].TypeId, expectedTypeId, tok, ref diags);
                        return stCallOp;
                    }
                    diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported, unresolved, or inaccessible static method call in Vibranium."u8);
                    return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
                }

                ReadOnlySpan<byte> stLeafText = GetStaticTargetEffectiveLeafName(callee.A, in fctx, in ast, in ta, in names, in bctx, out int stNameId);
                bool isConsoleTarget = Bytes.Eq(stLeafText, "Console"u8);
                if (isConsoleTarget)
                {
                    if ((callee.B == bctx.IdWrite || callee.B == bctx.IdWriteLine) &&
                        TryLowerPreludeCall(callee.B, callee.C, callee.D, callNode.B, argCount, allowReadOnlySpanBytes: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int cOp))
                    {
                        return cOp;
                    }
                    diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported 'Console' member or overload in Vibranium."u8);
                    return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
                }

                // This is the resolved Core static helper (ordinary declared
                // types and their overloads were handled above). The static
                // spelling borrows exactly the same place as the extension.
                if (stNameId == bctx.IdOptionExtensions)
                {
                    if (Bytes.Eq(names.Text(callee.B), "AsRef"u8) && argCount == 1 && callee.D <= 1)
                    {
                        AstNode arg = ast.Nodes[ast.Extra[callNode.B]];
                        PassMode mode = CallArgBits.Mode(in arg);
                        int slotType = InferExprType(arg.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                        TypeInfo slot = types.Items[slotType];
                        int payload = callee.D == 1 ? DeclBinder.ResolveTypeNode(ast.Extra[callee.C], fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false) : slot.A;
                        if ((mode == PassMode.ByValue || mode == PassMode.In) && CheckSingleNamedArg(in arg, "slot"u8, in names))
                        {
                            if (slot.Kind == TypeKinds.Option && payload == slot.A)
                                return LowerOptionAsRef(arg.B, slotType, payload, ast.Nodes[arg.B].TokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[arg.B].TokIdx], "Option.AsRef requires storage of the expected Option<T> type, not a converted value."u8);
                            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
                        }
                    }
                    diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported OptionExtensions member or overload in Vibranium."u8);
                    return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
                }

                if (stNameId == bctx.IdPrelude || stNameId == bctx.IdIo)
                {
                    bool isIoOnly = stNameId == bctx.IdIo;
                    if ((!isIoOnly || callee.B == bctx.IdWrite || callee.B == bctx.IdWriteLine) &&
                        TryLowerPreludeCall(callee.B, callee.C, callee.D, callNode.B, argCount, allowReadOnlySpanBytes: true, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int pOp))
                    {
                        return pOp;
                    }
                    diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported 'Prelude'/'Io' member or overload in Vibranium."u8);
                    return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
                }

                if (stNameId == bctx.IdStdio && (callee.B == bctx.IdWriteOut || callee.B == bctx.IdWriteErr) && argCount == 1 && callee.D == 0)
                {
                    AstNode a0 = ast.Nodes[ast.Extra[callNode.B]];
                    if (CallArgBits.Mode(in a0) == PassMode.ByValue)
                    {
                        int roSpanU8 = types.MakeSpan(TypeIds.U8, isReadOnly: true);
                        int a0Type = InferExprType(a0.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                        int bytesOp;
                        if (a0Type == TypeIds.Str && CheckSingleNamedArg(in a0, "text"u8, in names))
                        {
                            bytesOp = EmitStringAsUtf8Intrinsic(a0.B, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                        }
                        else if (ClassifyImplicitExpressionConversion(a0.B, a0Type, roSpanU8, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) >= 0 && CheckSingleNamedArg(in a0, "bytes"u8, in names))
                        {
                            bytesOp = LowerExprAsOperand(a0.B, roSpanU8, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                        }
                        else
                        {
                            diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported argument type or parameter name for 'Stdio.WriteOut'/'Stdio.WriteErr'."u8);
                            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
                        }
                        var ops = new Vec<int>(1);
                        ops.Push(bytesOp);
                        MirIntrinsic intr = callee.B == bctx.IdWriteOut ? MirIntrinsic.StdioWriteOut : MirIntrinsic.StdioWriteErr;
                        fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 0, TypeIds.Void, (int)intr, mir.PushIdList(ops.AsReadOnlySpan()), 1, 0, tokIdx));
                        return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
                    }
                }

                if (stNameId == bctx.IdVibraniumRuntime && callee.B == bctx.IdPanic && argCount == 1 && callee.D == 0)
                {
                    AstNode a0 = ast.Nodes[ast.Extra[callNode.B]];
                    if (CallArgBits.Mode(in a0) == PassMode.ByValue && CheckSingleNamedArg(in a0, "message"u8, in names) &&
                        InferExprType(a0.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) == TypeIds.Str)
                    {
                        int msgOp = LowerExprAsOperand(a0.B, TypeIds.Str, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                        var ops = new Vec<int>(1);
                        ops.Push(msgOp);
                        fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 0, TypeIds.Void, (int)MirIntrinsic.Panic, mir.PushIdList(ops.AsReadOnlySpan()), 1, 0, tokIdx));
                        int panicBlock = fctx.CurBlock;
                        fctx.Terminate(new MirTerm(MirTermKind.Unreachable, 0, 0, 0, 0, 0, 0, tokIdx));
                        int continuation = fctx.NewBlock();
                        // C# does not treat a call to Panic as a source-level return/throw.
                        fctx.SourceBlockTerms[panicBlock] = new MirTerm(MirTermKind.Goto, continuation, 0, 0, 0, 0, 0, tokIdx);
                        fctx.PanicContinuations[panicBlock] = continuation;
                        fctx.CurBlock = continuation;
                        return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.Void, tokIdx));
                    }
                }

                if (stNameId == bctx.IdStringUtf8Extensions && callee.B == bctx.IdAsUtf8 && argCount == 1 && callee.D == 0)
                {
                    AstNode a0 = ast.Nodes[ast.Extra[callNode.B]];
                    if (CallArgBits.Mode(in a0) == PassMode.ByValue && CheckSingleNamedArg(in a0, "text"u8, in names) &&
                        InferExprType(a0.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) == TypeIds.Str)
                    {
                        return EmitStringAsUtf8Intrinsic(a0.B, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    }
                }

                if (stNameId == bctx.IdStringUtf8Extensions && callee.B == bctx.IdLines && argCount == 1 && callee.D == 0)
                {
                    AstNode a0 = ast.Nodes[ast.Extra[callNode.B]];
                    if (CallArgBits.Mode(in a0) == PassMode.ByValue && CheckSingleNamedArg(in a0, "text"u8, in names) &&
                        InferExprType(a0.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) == TypeIds.Str)
                    {
                        if (expectedTypeId != TypeIds.Utf8Lines)
                        {
                            diags.ReportTok(VibCodes.Unsupported, tok, "'Lines()' view can only be iterated directly in 'foreach' or returned from a view helper."u8);
                        }
                        return EmitUtf8LinesFromStringExpr(a0.B, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    }
                }

                if (stNameId == bctx.IdUtf8SpanExtensions && callee.B == bctx.IdLines && argCount == 1 && callee.D == 0)
                {
                    AstNode a0 = ast.Nodes[ast.Extra[callNode.B]];
                    int roSpanU8 = types.MakeSpan(TypeIds.U8, isReadOnly: true);
                    int a0T = InferExprType(a0.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    if (CallArgBits.Mode(in a0) == PassMode.ByValue && CheckSingleNamedArg(in a0, "text"u8, in names) &&
                        ClassifyImplicitExpressionConversion(a0.B, a0T, roSpanU8, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) >= 0)
                    {
                        if (expectedTypeId != TypeIds.Utf8Lines)
                        {
                            diags.ReportTok(VibCodes.Unsupported, tok, "'Lines()' view can only be iterated directly in 'foreach' or returned from a view helper."u8);
                        }
                        return EmitUtf8LinesFromSpanExpr(a0.B, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    }
                }

                // BCL `int.TryParse` / `Int32.TryParse` / `long.TryParse` / `Int64.TryParse` (requires Vibranium.Std)
                if (stNameId == bctx.IdInt || stNameId == bctx.IdInt32 || stNameId == bctx.IdLong || stNameId == bctx.IdInt64)
                {
                    if (bctx.HasStdUnit && callee.B == bctx.IdTryParse && argCount == 2 && callee.D == 0 &&
                        TryLowerBclIntTryParse(stNameId == bctx.IdLong || stNameId == bctx.IdInt64, callNode.B, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int tpOp))
                    {
                        return tpOp;
                    }
                    diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported or unresolved BCL integer static call (or missing Vibranium.Std)."u8);
                    return mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, 0, TypeIds.Bool, tokIdx));
                }

                // BCL `System.MemoryExtensions.{SequenceEqual, StartsWith, EndsWith, IndexOf, LastIndexOf, Contains}<byte>` (requires Vibranium.Std)
                if (stNameId == bctx.IdMemoryExtensions)
                {
                    if (bctx.HasStdUnit && IsMemoryExtensionsCallAllowed(callee.B, callee.C, callee.D, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags))
                    {
                        Option<int> bseOpt = bctx.StdTypeByNameArity.Get(DeclBinder.PackNameArity(bctx.IdByteSpanExtensions, 0));
                        if (bseOpt.IsSome)
                        {
                            var meCands = new Vec<int>();
                            CollectMemoryExtensionsCandidates(bseOpt.Unwrap(), callee.B, ref fctx, in ast, in bctx, ref meCands);
                            int bestMe = ResolveBestOverload(meCands.AsReadOnlySpan(), -1, -1, 0, 0, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out bool meAmb, out _);
                            if (bestMe >= 0 && !meAmb)
                            {
                                return EmitResolvedUserCall(bestMe, -1, -1, 0, 0, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                            }
                        }
                    }
                    diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported 'System.MemoryExtensions' overload in Vibranium."u8);
                    return mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, 0, TypeIds.Bool, tokIdx));
                }

                diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported, unresolved, or inaccessible static method call in Vibranium."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
            }

            // Instance intrinsic / user instance / extension method calls
            int recvType = InferReceiverType(callee.A, out bool recvDeclares, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            TypeInfo rti = types.Items[recvType];

            if (rti.Kind == TypeKinds.Utf8Lines || rti.Kind == TypeKinds.Utf8ArgEnum)
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "Closed foreach view enumerator members cannot be invoked directly; use 'foreach'."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
            }

            if (recvType == TypeIds.Str && callee.B == bctx.IdAsUtf8 && argCount == 0 && callee.D == 0)
            {
                return EmitStringAsUtf8Intrinsic(callee.A, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }

            if (recvType == TypeIds.Str && callee.B == bctx.IdLines && argCount == 0 && callee.D == 0)
            {
                if (expectedTypeId != TypeIds.Utf8Lines)
                {
                    diags.ReportTok(VibCodes.Unsupported, tok, "'Lines()' view can only be iterated directly in 'foreach' or returned from a view helper."u8);
                }
                return EmitUtf8LinesFromStringExpr(callee.A, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }

            if ((rti.Kind == TypeKinds.Span || rti.Kind == TypeKinds.ReadOnlySpan) &&
                rti.A == TypeIds.U8 && callee.B == bctx.IdLines && argCount == 0 && callee.D == 0)
            {
                if (expectedTypeId != TypeIds.Utf8Lines)
                {
                    diags.ReportTok(VibCodes.Unsupported, tok, "'Lines()' view can only be iterated directly in 'foreach' or returned from a view helper."u8);
                }
                return EmitUtf8LinesFromSpanExpr(callee.A, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }

            if (rti.Kind == TypeKinds.Option &&
                TryLowerOptionIntrinsicCall(callee.A, recvDeclares, recvType, rti.A, callee.B, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int optIntrOp))
            {
                return optIntrOp;
            }
            if (rti.Kind == TypeKinds.OptionMut &&
                TryLowerOptionMutIntrinsicCall(callee.A, recvType, rti.A, callee.B, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int optMutIntrOp))
            {
                return optMutIntrOp;
            }
            if (rti.Kind == TypeKinds.Result &&
                TryLowerResultIntrinsicCall(callee.A, recvDeclares, recvType, rti.A, rti.B, callee.B, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int resIntrOp))
            {
                return resIntrOp;
            }
            if (rti.Kind == TypeKinds.Vec &&
                TryLowerVecIntrinsicCall(callee.A, recvType, rti.A, callee.B, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int vecIntrOp))
            {
                return vecIntrOp;
            }
            if ((rti.Kind == TypeKinds.Span || rti.Kind == TypeKinds.ReadOnlySpan) &&
                TryLowerSpanIntrinsicCall(callee.A, recvDeclares, recvType, callee.B, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int spanIntrOp))
            {
                return spanIntrOp;
            }

            // User instance method call (with two-phase borrow reservation before evaluating arguments)
            if (rti.Kind == TypeKinds.Class || rti.Kind == TypeKinds.Struct)
            {
                var imCands = new Vec<int>();
                CollectTypeMethodCandidates(rti.A, callee.B, allowInstance: true, allowStatic: false, isCtor: false, ref fctx, in ast, in bctx, ref imCands);
                EnterReceiverScope(callee.A, recvDeclares, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                int imId = ResolveBestOverload(imCands.AsReadOnlySpan(), recvType, -1, callee.C, callee.D, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out bool imAmb, out _);
                fctx.LeaveSpeculativeInfer();
                if (imAmb)
                {
                    diags.ReportTok(VibCodes.Unsupported, tok, "Ambiguous instance method invocation in Vibranium."u8);
                    return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.Void, tokIdx));
                }
                if (imId >= 0)
                {
                    PassMode recvMode = DeclBinder.GetReceiverPassMode(ast.Funcs[imId], recvType, in ast, in types, bctx.IdDispose);
                    bool useTwoPhase = recvMode == PassMode.ThisMut && argCount > 0;
                    int recvPl = LowerPlaceOrTemp(callee.A, recvType, recvMode == PassMode.ThisMut, useTwoPhase, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    if (argCount > 0)
                    {
                        recvPl = ReserveReceiverPlace(recvPl, recvType, recvMode == PassMode.ThisMut, useTwoPhase, tokIdx, ref fctx, ref mir);
                    }
                    int imCallOp = EmitResolvedUserCall(imId, recvType, recvPl, callee.C, callee.D, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, useTwoPhase);
                    CheckViewReturnAllowedContext(mir.Operands[imCallOp].TypeId, expectedTypeId, tok, ref diags);
                    return imCallOp;
                }
            }

            // Static extension method fallback when no intrinsic or applicable instance method matched
            var extCands = new Vec<int>();
            CollectExtensionCandidates(callee.B, ref fctx, in ast, in bctx, ref extCands);
            if (extCands.Count > 0)
            {
                EnterReceiverScope(callee.A, recvDeclares, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                int extId = ResolveBestOverload(extCands.AsReadOnlySpan(), -1, recvType, callee.C, callee.D, callNode.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out bool extAmb, out _);
                fctx.LeaveSpeculativeInfer();
                if (extAmb)
                {
                    diags.ReportTok(VibCodes.Unsupported, tok, "Ambiguous extension method invocation in Vibranium."u8);
                    return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId >= 0 ? expectedTypeId : TypeIds.Void, tokIdx));
                }
                if (extId >= 0)
                {
                    int extCallOp = EmitResolvedExtensionCall(extId, callee.A, recvType, callee.C, callee.D, callNode.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    CheckViewReturnAllowedContext(mir.Operands[extCallOp].TypeId, expectedTypeId, tok, ref diags);
                    return extCallOp;
                }
            }
        }

        diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported, unresolved, or inaccessible method call in Vibranium."u8);
        return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
    }

    private static void CheckViewReturnAllowedContext(int retTypeId, int expectedTypeId, Token tok, ref DiagnosticBag diags)
    {
        if ((retTypeId == TypeIds.Utf8Lines || retTypeId == TypeIds.Utf8ArgEnum) && expectedTypeId != retTypeId)
        {
            diags.ReportTok(VibCodes.Unsupported, tok, "Closed foreach view enumerator values can only be iterated in 'foreach' or returned directly from a view helper."u8);
        }
    }

    private static int EmitStringAsUtf8Intrinsic(
        int strExprId,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int roSpanU8 = types.MakeSpan(TypeIds.U8, isReadOnly: true);
        int strOp = LowerExprAsOperand(strExprId, TypeIds.Str, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        MirOperand strOperand = mir.Operands[strOp];
        if (strOperand.Kind == MirOpKinds.StrConst && strOperand.IntVal <= -2)
        {
            return EmitMultiChunkStrCodeAsReadOnlySpan(strOperand.IntVal, tokIdx, ref fctx, in ta, in bctx, ref types, ref mir);
        }
        var ops = new Vec<int>(1);
        ops.Push(strOp);
        int dstTmp = fctx.NewTemp(roSpanU8, tokIdx, ref mir);
        int dstPl = mir.AddPlaceLocal(dstTmp, roSpanU8);
        fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, roSpanU8, (int)MirIntrinsic.StringAsUtf8, mir.PushIdList(ops.AsReadOnlySpan()), 1, 0, tokIdx));
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, roSpanU8, tokIdx));
    }

    private static bool CheckSingleNamedArg(in AstNode argNode, ReadOnlySpan<byte> expectedName, in Interner names)
    {
        int nmId = CallArgBits.NameId(in argNode);
        return nmId < 0 || Bytes.Eq(names.Text(nmId), expectedName);
    }

    private static bool TryMapTwoNamedArgs(
        in AstNode a0,
        in AstNode a1,
        ReadOnlySpan<byte> p0Name,
        ReadOnlySpan<byte> p1Name,
        in Interner names,
        out int p0ArgIdx,
        out int p1ArgIdx)
    {
        p0ArgIdx = -1;
        p1ArgIdx = -1;
        int n0 = CallArgBits.NameId(in a0);
        int n1 = CallArgBits.NameId(in a1);
        bool seenOutOfPosNamed = false;

        if (n0 >= 0)
        {
            ReadOnlySpan<byte> t0 = names.Text(n0);
            if (Bytes.Eq(t0, p0Name)) p0ArgIdx = 0;
            else if (Bytes.Eq(t0, p1Name)) { p1ArgIdx = 0; seenOutOfPosNamed = true; }
            else return false;
        }
        else
        {
            p0ArgIdx = 0;
        }

        if (n1 >= 0)
        {
            ReadOnlySpan<byte> t1 = names.Text(n1);
            if (Bytes.Eq(t1, p0Name))
            {
                if (p0ArgIdx >= 0) return false;
                p0ArgIdx = 1;
            }
            else if (Bytes.Eq(t1, p1Name))
            {
                if (p1ArgIdx >= 0) return false;
                p1ArgIdx = 1;
            }
            else
            {
                return false;
            }
        }
        else
        {
            if (seenOutOfPosNamed || p1ArgIdx >= 0) return false;
            p1ArgIdx = 1;
        }

        return p0ArgIdx >= 0 && p1ArgIdx >= 0;
    }

    private static int EmitUtf8LinesFromStringExpr(
        int strExprId,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int spOp = EmitStringAsUtf8Intrinsic(strExprId, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        int spPl = mir.Operands[spOp].PlaceOrLitIdx;
        var pls = new Vec<int>(1);
        pls.Push(spPl);
        int dstTmp = fctx.NewTemp(TypeIds.Utf8Lines, tokIdx, ref mir);
        int dstPl = mir.AddPlaceLocal(dstTmp, TypeIds.Utf8Lines);
        fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, TypeIds.Utf8Lines, (int)MirIntrinsic.Utf8ViewFromSpan, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, TypeIds.Utf8Lines, tokIdx));
    }

    private static int EmitUtf8LinesFromSpanExpr(
        int spanExprId,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int roSpanU8 = types.MakeSpan(TypeIds.U8, isReadOnly: true);
        int spPl = LowerPlaceOrTemp(spanExprId, roSpanU8, isMut: false, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        var pls = new Vec<int>(1);
        pls.Push(spPl);
        int dstTmp = fctx.NewTemp(TypeIds.Utf8Lines, tokIdx, ref mir);
        int dstPl = mir.AddPlaceLocal(dstTmp, TypeIds.Utf8Lines);
        fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, TypeIds.Utf8Lines, (int)MirIntrinsic.Utf8ViewFromSpan, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, TypeIds.Utf8Lines, tokIdx));
    }

    private static bool TryLowerBclIntTryParse(
        bool isInt64,
        int argExtraStart,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        out int resultOp)
    {
        resultOp = -1;
        AstNode raw0 = ast.Nodes[ast.Extra[argExtraStart + 0]];
        AstNode raw1 = ast.Nodes[ast.Extra[argExtraStart + 1]];
        if (!TryMapTwoNamedArgs(in raw0, in raw1, "s"u8, "result"u8, in names, out int sIdx, out int resIdx))
        {
            return false;
        }

        AstNode sArg = sIdx == 0 ? raw0 : raw1;
        AstNode resArg = resIdx == 0 ? raw0 : raw1;
        if (CallArgBits.Mode(in sArg) != PassMode.ByValue || CallArgBits.Mode(in resArg) != PassMode.Out) return false;

        int roSpanU8 = types.MakeSpan(TypeIds.U8, isReadOnly: true);
        int sArgT = InferExprType(sArg.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        if (sArgT != TypeIds.Str && ClassifyImplicitExpressionConversion(sArg.B, sArgT, roSpanU8, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) < 0)
        {
            return false;
        }

        int expectedOutT = isInt64 ? TypeIds.I64 : TypeIds.I32;
        if (!IsOutArgCompatibleWithType(in resArg, expectedOutT, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags))
        {
            return false;
        }

        Option<int> bytesDeclOpt = bctx.StdTypeByNameArity.Get(DeclBinder.PackNameArity(bctx.IdBytes, 0));
        if (!bytesDeclOpt.IsSome) return false;
        int targetFnName = isInt64 ? bctx.IdTryParseInt64 : bctx.IdTryParseInt32;
        TypeDecl bytesTd = ast.Types[bytesDeclOpt.Unwrap()];
        int fnDeclId = -1;
        for (int m = 0; m < bytesTd.FuncCount; m++)
        {
            int candFId = bytesTd.FuncStart + m;
            FuncDecl candFd = ast.Funcs[candFId];
            if (candFd.NameId == targetFnName && (candFd.Flags & DeclFlags.Static) != 0 && candFd.ParamCount == 2)
            {
                AstNode p0Tn = ast.Nodes[ast.Params[candFd.ParamStart].TypeNode];
                if (!(p0Tn.Kind == AstKind.TypePrim && (TokKind)p0Tn.A == TokKind.KwString))
                {
                    fnDeclId = candFId;
                    break;
                }
            }
        }
        if (fnDeclId < 0) return false;

        var emptyTa = new Vec<int>();
        int instId = DeclBinder.EnsureFuncInstance(fnDeclId, -1, emptyTa.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
        if (instId < 0) return false;

        int bytesOp;
        int outPl;
        bool callFlagsTwoPhase = false;
        if (sIdx == 0)
        {
            bytesOp = sArgT == TypeIds.Str
                ? EmitStringAsUtf8Intrinsic(sArg.B, sArg.TokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                : LowerExprAsOperand(sArg.B, roSpanU8, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            outPl = LowerOutCallArgPlace(in resArg, expectedOutT, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }
        else
        {
            outPl = LowerOutCallArgPlace(in resArg, expectedOutT, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            if (resArg.C == -2 && mir.Places[outPl].ProjCount > 0)
            {
                outPl = ReserveReceiverPlace(outPl, expectedOutT, isMut: true, isTwoPhase: true, resArg.TokIdx, ref fctx, ref mir, isAssignmentTargetSnapshot: true);
                callFlagsTwoPhase = true;
            }
            bytesOp = sArgT == TypeIds.Str
                ? EmitStringAsUtf8Intrinsic(sArg.B, sArg.TokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                : LowerExprAsOperand(sArg.B, roSpanU8, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }

        int caStart = mir.CallArgs.Count;
        mir.CallArgs.Push(new MirCallArg(PassMode.ByValue, bytesOp, sArg.TokIdx));
        mir.CallArgs.Push(new MirCallArg(PassMode.Out, outPl, resArg.TokIdx));

        int dstTmp = fctx.NewTemp(TypeIds.Bool, tokIdx, ref mir);
        int dstPl = mir.AddPlaceLocal(dstTmp, TypeIds.Bool);
        fctx.EmitCall(new MirInst(MirOp.Call, dstPl, -1, callFlagsTwoPhase ? 2 : 0, TypeIds.Bool, instId, caStart, 2, 0, tokIdx), in mir);
        resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, TypeIds.Bool, tokIdx));
        return true;
    }

    private static bool TryLowerPreludeCall(
        int fnNameId,
        int explicitTaStart,
        int explicitTaCount,
        int argExtraStart,
        int argCount,
        bool allowReadOnlySpanBytes,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        out int resultOp)
    {
        resultOp = -1;
        Token tok = ta.Tokens[tokIdx];

        if (fnNameId == bctx.IdSome && argCount == 1 && explicitTaCount <= 1)
        {
            AstNode a0 = ast.Nodes[ast.Extra[argExtraStart]];
            if (CallArgBits.Mode(in a0) != PassMode.ByValue || !CheckSingleNamedArg(in a0, "value"u8, in names)) return false;
            int expInner = explicitTaCount == 1
                ? DeclBinder.ResolveTypeNode(ast.Extra[explicitTaStart], fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags)
                : -1;
            int valOp = LowerExprAsOperand(a0.B, expInner, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int innerT = expInner >= 0 ? expInner : mir.Operands[valOp].TypeId;
            int wrapT = types.MakeSomeWrap(innerT);
            int tmp = fctx.NewTemp(wrapT, tokIdx, ref mir);
            int pl = mir.AddPlaceLocal(tmp, wrapT);
            fctx.Emit(new MirInst(MirOp.MakeSomeWrap, pl, -1, 0, innerT, valOp, 0, 0, 0, tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, wrapT, tokIdx));
            return true;
        }

        if (fnNameId == bctx.IdOk)
        {
            if (argCount == 0 && explicitTaCount == 0)
            {
                int unitOp = mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, TypeIds.NoneUnit, tokIdx));
                int wrapT = types.MakeOkWrap(TypeIds.NoneUnit);
                int tmp = fctx.NewTemp(wrapT, tokIdx, ref mir);
                int pl = mir.AddPlaceLocal(tmp, wrapT);
                fctx.Emit(new MirInst(MirOp.MakeOkWrap, pl, -1, 0, TypeIds.NoneUnit, unitOp, 0, 0, 0, tokIdx));
                resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, wrapT, tokIdx));
                return true;
            }
            if (argCount == 1 && explicitTaCount <= 1)
            {
                AstNode a0 = ast.Nodes[ast.Extra[argExtraStart]];
                if (CallArgBits.Mode(in a0) != PassMode.ByValue || !CheckSingleNamedArg(in a0, "value"u8, in names)) return false;
                int expOk = explicitTaCount == 1
                    ? DeclBinder.ResolveTypeNode(ast.Extra[explicitTaStart], fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags)
                    : -1;
                int valOp = LowerExprAsOperand(a0.B, expOk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                int okT = expOk >= 0 ? expOk : mir.Operands[valOp].TypeId;
                int wrapT = types.MakeOkWrap(okT);
                int tmp = fctx.NewTemp(wrapT, tokIdx, ref mir);
                int pl = mir.AddPlaceLocal(tmp, wrapT);
                fctx.Emit(new MirInst(MirOp.MakeOkWrap, pl, -1, 0, okT, valOp, 0, 0, 0, tokIdx));
                resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, wrapT, tokIdx));
                return true;
            }
        }

        if (fnNameId == bctx.IdErr && argCount == 1 && explicitTaCount <= 1)
        {
            AstNode a0 = ast.Nodes[ast.Extra[argExtraStart]];
            if (CallArgBits.Mode(in a0) != PassMode.ByValue || !CheckSingleNamedArg(in a0, "error"u8, in names)) return false;
            int expErr = explicitTaCount == 1
                ? DeclBinder.ResolveTypeNode(ast.Extra[explicitTaStart], fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags)
                : -1;
            int errOp = LowerExprAsOperand(a0.B, expErr, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int errT = expErr >= 0 ? expErr : mir.Operands[errOp].TypeId;
            if (types.IsLinear(errT, in ast))
            {
                diags.ReportTok(VibCodes.LinearViolation, tok, "Linear IDisposable resource cannot be wrapped in 'Err<E>'."u8);
            }
            int wrapT = types.MakeErrWrap(errT);
            int tmp = fctx.NewTemp(wrapT, tokIdx, ref mir);
            int pl = mir.AddPlaceLocal(tmp, wrapT);
            fctx.Emit(new MirInst(MirOp.MakeErrWrap, pl, -1, 0, errT, errOp, 0, 0, 0, tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, wrapT, tokIdx));
            return true;
        }

        if (fnNameId == bctx.IdMove && argCount == 1 && explicitTaCount <= 1)
        {
            AstNode a0 = ast.Nodes[ast.Extra[argExtraStart]];
            if (CallArgBits.Mode(in a0) != PassMode.ByValue || !CheckSingleNamedArg(in a0, "value"u8, in names)) return false;
            int expT = explicitTaCount == 1
                ? DeclBinder.ResolveTypeNode(ast.Extra[explicitTaStart], fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags)
                : -1;
            resultOp = LowerExprAsOperand(a0.B, expT, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int movedType = mir.Operands[resultOp].TypeId;
            if (types.Items[movedType].Kind == TypeKinds.Span)
            {
                // Explicit Move consumes the descriptor before its result can be
                // treated as an ordinary reborrowing Span call argument.
                int movedLocal = fctx.NewTemp(movedType, tokIdx, ref mir);
                int movedPlace = mir.AddPlaceLocal(movedLocal, movedType);
                fctx.Emit(new MirInst(MirOp.AssignUse, movedPlace, -1, 0, movedType, resultOp, 0, 0, 0, tokIdx));
                resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, movedPlace, 0, movedType, tokIdx));
            }
            return true;
        }

        if (fnNameId == bctx.IdWriteLine && argCount == 0 && explicitTaCount == 0)
        {
            fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 0, TypeIds.Void, (int)MirIntrinsic.IoWriteLineEmpty, 0, 0, 0, tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
            return true;
        }

        if ((fnNameId == bctx.IdWrite || fnNameId == bctx.IdWriteLine) && argCount == 1 && explicitTaCount == 0)
        {
            AstNode a0 = ast.Nodes[ast.Extra[argExtraStart]];
            if (CallArgBits.Mode(in a0) != PassMode.ByValue) return false;
            bool nl = fnNameId == bctx.IdWriteLine;
            int roSpanU8 = types.MakeSpan(TypeIds.U8, isReadOnly: true);
            int inferredT = InferExprType(a0.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            int contextualT = inferredT == TypeIds.Error
                ? ChooseTargetTypedWriteParameter(in a0, allowReadOnlySpanBytes, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) : -1;
            if (contextualT >= 0) inferredT = contextualT;
            TypeInfo iti = types.Items[inferredT];

            if ((iti.Kind == TypeKinds.Span || iti.Kind == TypeKinds.ReadOnlySpan) && iti.A == TypeIds.U8)
            {
                if (!allowReadOnlySpanBytes || !CheckSingleNamedArg(in a0, "utf8"u8, in names)) return false;
                int bytesOp = LowerExprAsOperand(a0.B, roSpanU8, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                var bOps = new Vec<int>(1);
                bOps.Push(bytesOp);
                fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 0, TypeIds.Void, (int)MirIntrinsic.StdioWriteOut, mir.PushIdList(bOps.AsReadOnlySpan()), 1, 0, tokIdx));
                if (nl)
                {
                    fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 0, TypeIds.Void, (int)MirIntrinsic.IoWriteLineEmpty, 0, 0, 0, tokIdx));
                }
                resultOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
                return true;
            }

            if (!CheckSingleNamedArg(in a0, "value"u8, in names)) return false;
            bool isAllowedIntOrChar = types.IsInteger(inferredT) &&
                                      types.Items[inferredT].Kind != TypeKinds.Enum &&
                                      (inferredT != TypeIds.Char || allowReadOnlySpanBytes);
            if (inferredT != TypeIds.Bool &&
                inferredT != TypeIds.Str &&
                !isAllowedIntOrChar)
            {
                return false;
            }

            int vOp = LowerExprAsOperand(a0.B, contextualT, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int vType = mir.Operands[vOp].TypeId;
            MirIntrinsic intr;
            if (vType == TypeIds.Bool)
            {
                intr = nl ? MirIntrinsic.IoWriteLineBool : MirIntrinsic.IoWriteBool;
            }
            else if (vType == TypeIds.Str)
            {
                MirOperand vOperand = mir.Operands[vOp];
                if (vOperand.Kind == MirOpKinds.StrConst && vOperand.IntVal <= -2)
                {
                    var strSlices = new Vec<int>(4);
                    CollectConstStrSlices(vOperand.IntVal, in bctx, ref strSlices);
                    for (int si = 0; si < strSlices.Count; si++)
                    {
                        int slOp = mir.AddOperand(new MirOperand(MirOpKinds.StrConst, strSlices[si], strSlices[si], TypeIds.Str, tokIdx));
                        var slOps = new Vec<int>(1);
                        slOps.Push(slOp);
                        fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 0, TypeIds.Void, (int)MirIntrinsic.IoWriteStr, mir.PushIdList(slOps.AsReadOnlySpan()), 1, 0, tokIdx));
                    }
                    if (nl)
                    {
                        fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 0, TypeIds.Void, (int)MirIntrinsic.IoWriteLineEmpty, 0, 0, 0, tokIdx));
                    }
                    resultOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
                    return true;
                }
                intr = nl ? MirIntrinsic.IoWriteLineStr : MirIntrinsic.IoWriteStr;
            }
            else if (types.IsUnsignedInteger(vType))
            {
                vOp = EmitCastToTemp(vOp, TypeIds.U64, tokIdx, ref fctx, ref mir);
                intr = nl ? MirIntrinsic.IoWriteLineUInt64 : MirIntrinsic.IoWriteUInt64;
            }
            else
            {
                vOp = EmitCastToTemp(vOp, TypeIds.I64, tokIdx, ref fctx, ref mir);
                intr = nl ? MirIntrinsic.IoWriteLineInt64 : MirIntrinsic.IoWriteInt64;
            }
            var ops = new Vec<int>(1);
            ops.Push(vOp);
            fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 0, TypeIds.Void, (int)intr, mir.PushIdList(ops.AsReadOnlySpan()), 1, 0, tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
            return true;
        }

        return false;
    }

    private static void ResolveMethodTypeArgumentsForCall(
        in FuncDecl fd,
        int ownerTypeId,
        int extensionRecvTypeId,
        int explicitMethodTaStart,
        int explicitMethodTaCount,
        int callArgExtraStart,
        int callArgCount,
        Token tok,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        ref Vec<int> methodTypeArgs)
    {
        if (fd.TypeParamCount == 0) return;
        if (explicitMethodTaCount == fd.TypeParamCount)
        {
            for (int i = 0; i < explicitMethodTaCount; i++)
            {
                int tid = DeclBinder.ResolveTypeNode(ast.Extra[explicitMethodTaStart + i], fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (types.IsLinear(tid, in ast))
                {
                    diags.ReportTok(VibCodes.LinearViolation, tok, "Linear IDisposable resource cannot instantiate user generic method."u8);
                }
                methodTypeArgs.Push(tid);
            }
            return;
        }

        int extOffset = extensionRecvTypeId >= 0 ? 1 : 0;
        var argToParam = new Vec<int>(callArgCount);
        var paramToArg = new Vec<int>(fd.ParamCount - extOffset);
        if (!TryMapCallArgsToParams(in fd, extOffset, callArgExtraStart, callArgCount, in ast, ref argToParam, ref paramToArg, out _))
        {
            argToParam.Clear();
            for (int a = 0; a < callArgCount; a++) argToParam.Push(a);
        }

        for (int tp = 0; tp < fd.TypeParamCount; tp++)
        {
            int tpName = ast.Extra[fd.TypeParamStart + tp];
            int inferred = -1;
            if (extensionRecvTypeId >= 0 && fd.ParamCount > 0)
            {
                inferred = TryInferTypeParamFromNode(ast.Params[fd.ParamStart].TypeNode, extensionRecvTypeId, tpName, in ast, in bctx, in types);
            }
            fctx.InferDepth += 1;
            for (int a = 0; inferred < 0 && a < callArgCount; a++)
            {
                int mappedP = argToParam[a];
                if ((mappedP + extOffset) >= fd.ParamCount) continue;
                AstNode argNode = ast.Nodes[ast.Extra[callArgExtraStart + a]];
                if (CallArgBits.Mode(in argNode) == PassMode.Out && argNode.C < -1 && argNode.C != -2) continue;
                int actualT = InferCallArgActualType(in argNode, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (fctx.ElementRetypeDepth == 0 && argNode.C >= 0 && CallArgBits.Mode(in argNode) == PassMode.Out) PushSpeculativeOutArg(in argNode, actualT, ref fctx);
                inferred = TryInferTypeParamFromNode(ast.Params[fd.ParamStart + extOffset + mappedP].TypeNode, actualT, tpName, in ast, in bctx, in types);
            }
            fctx.LeaveSpeculativeInfer();
            if (inferred < 0) inferred = TypeIds.I32;
            if (types.IsLinear(inferred, in ast))
            {
                diags.ReportTok(VibCodes.LinearViolation, tok, "Linear IDisposable resource cannot instantiate user generic method."u8);
            }
            methodTypeArgs.Push(inferred);
        }
    }

    private static bool TryMapCallArgsToParams(in FuncDecl fd, int extOffset, int callArgExtraStart, int callArgCount, in AstArena ast, ref Vec<int> argToParam, ref Vec<int> paramToArg, out bool usesDefaults) => TryMapCallArgsToParams(in fd, extOffset, callArgExtraStart, callArgCount, in ast, ref argToParam, ref paramToArg, out usesDefaults, 0);

    private static bool TryMapCallArgsToParams(
        in FuncDecl fd,
        int extOffset,
        int callArgExtraStart,
        int callArgCount,
        in AstArena ast,
        ref Vec<int> argToParam,
        ref Vec<int> paramToArg,
        out bool usesDefaults,
        int excludeTrailingParams)
    {
        usesDefaults = false;
        int formalCount = fd.ParamCount - extOffset - excludeTrailingParams;
        if (formalCount < 0 || callArgCount > formalCount) return false;

        argToParam.Clear();
        paramToArg.Clear();
        paramToArg.Resize(formalCount, -1);

        bool seenOutOfPosNamed = false;
        for (int a = 0; a < callArgCount; a++)
        {
            AstNode cArg = ast.Nodes[ast.Extra[callArgExtraStart + a]];
            int nameId = CallArgBits.NameId(in cArg);
            if (nameId >= 0)
            {
                int foundP = -1;
                for (int p = 0; p < formalCount; p++)
                {
                    if (ast.Params[fd.ParamStart + extOffset + p].NameId == nameId)
                    {
                        foundP = p;
                        break;
                    }
                }
                if (foundP < 0 || paramToArg[foundP] >= 0) return false;
                if (foundP != a) seenOutOfPosNamed = true;
                argToParam.Push(foundP);
                paramToArg[foundP] = a;
            }
            else
            {
                if (seenOutOfPosNamed || a >= formalCount || paramToArg[a] >= 0) return false;
                argToParam.Push(a);
                paramToArg[a] = a;
            }
        }

        for (int p = 0; p < formalCount; p++)
        {
            if (paramToArg[p] < 0)
            {
                ParamDecl omPd = ast.Params[fd.ParamStart + extOffset + p];
                if (omPd.DefaultExpr < 0 || omPd.Mode != PassMode.ByValue) return false;
                usesDefaults = true;
            }
        }

        return true;
    }

    private static int MaterializeByValueCallArgIfNeeded(
        int opId,
        bool shouldMaterialize,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in TypeTable types,
        ref MirModuleArena mir)
    {
        if (!shouldMaterialize || opId < 0) return opId;
        MirOperand op = mir.Operands[opId];
        if (op.Kind != MirOpKinds.CopyOrMove)
        {
            return opId;
        }
        MirPlace pl = mir.Places[op.PlaceOrLitIdx];
        if (pl.ProjCount == 0 &&
            pl.LocalId >= 0 &&
            pl.LocalId < fctx.Locals.Count &&
            (fctx.Locals[pl.LocalId].Flags & MirLocalFlags.IsTemp) != 0 &&
            (fctx.Locals[pl.LocalId].Flags & MirLocalFlags.IsRefLocal) == 0)
        {
            return opId;
        }
        int snapTmp = fctx.NewTemp(op.TypeId, tokIdx, ref mir);
        int snapPl = mir.AddPlaceLocal(snapTmp, op.TypeId);
        // Span arguments reborrow, rather than consume, the source descriptor.
        // Snapshot its value now and retain the parent loan through activation.
        int flags = types.Items[op.TypeId].Kind == TypeKinds.Span ? 8 : 0;
        fctx.Emit(new MirInst(MirOp.AssignUse, snapPl, -1, flags, op.TypeId, opId, 0, 0, 0, tokIdx));
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, snapPl, 0, op.TypeId, tokIdx));
    }

    private static int LowerOutCallArgPlace(
        in AstNode cArg,
        int paramTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int argTok = cArg.TokIdx;
        CheckDeclaredOutArgumentType(in cArg, paramTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        if (IsDiscardOutArgument(in cArg, in fctx, in ast, in names))
        {
            int dTmp = fctx.NewTemp(paramTypeId, argTok, ref mir);
            return mir.AddPlaceLocal(dTmp, paramTypeId);
        }
        if (cArg.C == -1 || cArg.C >= 0)
        {
            int outScope = fctx.OutVarScopeOverride > 0 ? fctx.OutVarScopeOverride : fctx.ScopeDepth;
            int outLid = BindExpressionLocal(cArg.D, paramTypeId, 0, outScope, argTok, ref fctx, in ast, in ta, in names, ref diags);
            fctx.LocalInitializerInsts[outLid] = -2;
            return mir.AddPlaceLocal(outLid, paramTypeId);
        }
        CheckNotDirectCapturedPrimaryParamWrite(cArg.B, "Cannot pass captured primary-constructor parameter by 'out'."u8, in fctx, in ast, in ta, in types, ref diags);
        int place = LowerPlace(cArg.B, isMut: true, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        CheckSourceReferencePlace(place, paramTypeId, true, argTok, in fctx, in ta, in types, in mir, ref diags);
        return place;
    }

    // The type written in an out declaration (`out T x`, typed discard `out T _`)
    // must bind and be identical to the parameter type; only `var` infers it.
    // Callers keep binding the variable at the parameter type after reporting.
    private static void CheckDeclaredOutArgumentType(
        in AstNode cArg,
        int paramTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags)
    {
        int typeNode = DeclaredOutArgumentTypeNode(in cArg);
        if (typeNode < 0) return;
        int before = diags.Items.Count;
        int declared = DeclBinder.ResolveTypeNode(typeNode, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
        if (diags.Items.Count != before || declared == TypeIds.Error || paramTypeId < 0 || paramTypeId == TypeIds.Error) return;
        if (declared != paramTypeId)
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[typeNode].TokIdx], "The declared type of an out variable must be identical to the out parameter's type (CS1503)."u8);
    }

    private static int DeclaredOutArgumentTypeNode(in AstNode cArg)
    {
        if (CallArgBits.Mode(in cArg) != PassMode.Out) return -1;
        if (cArg.C >= 0) return cArg.C;
        return cArg.C == -3 ? cArg.D : -1;
    }

    private static void CheckSourceWritablePlace(int placeId, int tokIdx, in FuncLowerCtx fctx,
        in TokenArena ta, in TypeTable types, in MirModuleArena mir, ref DiagnosticBag diags)
    {
        MirPlace place = mir.Places[placeId];
        bool classThis = place.LocalId == fctx.ThisLocalId && place.ProjCount == 0 &&
            fctx.OwnerTypeId >= 0 && types.Items[fctx.OwnerTypeId].Kind == TypeKinds.Class;
        if (classThis || IsSourceReadonlyReferencePlace(placeId, in fctx, in mir))
            diags.ReportTok(VibCodes.MutateSharedBorrow, ta.Tokens[tokIdx], "Cannot assign to or take a mutable reference to a readonly source place."u8);
        if (place.ProjCount > 0) ReportIfSourceValuePlace(placeId, tokIdx, in fctx, in ta, in mir, ref diags);
    }

    // A C# variable is a local, parameter, `this` of a struct, an array/span/Vec
    // element, a ref return, or a field of a variable or of a class instance.
    // The value of a call, property, user indexer, conversion, conditional or
    // `new` is not; nor is a struct field reached from such a value. The lowerer
    // keeps such a value in an unnamed by-value temporary, so a place rooted in
    // one is a value until a class field or dereference reaches other storage.
    private static bool IsSourceValuePlace(int placeId, in FuncLowerCtx fctx, in MirModuleArena mir)
    {
        MirPlace place = mir.Places[placeId];
        if (place.LocalId < 0) return false;
        MirLocal root = fctx.Locals[place.LocalId];
        if ((root.Flags & MirLocalFlags.IsTemp) == 0 || (root.Flags & MirLocalFlags.IsRefLocal) != 0) return false;
        for (int i = 0; i < place.ProjCount; i++)
        {
            MirProj projection = mir.Projs[place.ProjStart + i];
            if (projection.Kind != MirProjKinds.Field || (projection.Flags & 1) != 0) return false;
        }
        return true;
    }

    private static void ReportIfSourceValuePlace(int placeId, int tokIdx, in FuncLowerCtx fctx,
        in TokenArena ta, in MirModuleArena mir, ref DiagnosticBag diags)
    {
        if (IsSourceValuePlace(placeId, in fctx, in mir))
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Cannot modify or reference a member of a struct value that is not a variable (a call, property, indexer, conversion or conditional result); copy it to a local first (CS1612)."u8);
    }

    // Setters, user indexers and compound operators on a struct receiver
    // modify that receiver, so it must be a variable as well.
    private static void ReportIfStructValueReceiver(int receiverPlaceId, int receiverTypeId, int tokIdx, in FuncLowerCtx fctx,
        in TokenArena ta, in TypeTable types, in MirModuleArena mir, ref DiagnosticBag diags)
    {
        if (receiverTypeId < 0 || types.Items[receiverTypeId].Kind == TypeKinds.Class) return;
        ReportIfSourceValuePlace(receiverPlaceId, tokIdx, in fctx, in ta, in mir, ref diags);
    }

    private static void CheckSourceReferencePlace(int placeId, int expectedType, bool isMut, int tokIdx, in FuncLowerCtx fctx,
        in TokenArena ta, in TypeTable types, in MirModuleArena mir, ref DiagnosticBag diags)
    {
        MirPlace place = mir.Places[placeId];
        if (isMut) CheckSourceWritablePlace(placeId, tokIdx, in fctx, in ta, in types, in mir, ref diags);
        else if (place.ProjCount > 0) ReportIfSourceValuePlace(placeId, tokIdx, in fctx, in ta, in mir, ref diags);
        if (expectedType >= 0 && expectedType != TypeIds.Error && place.TypeId != TypeIds.Error && expectedType != place.TypeId)
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A reference requires the exact referent type."u8);
        if (place.ProjCount == 0 && (fctx.Locals[place.LocalId].Flags & MirLocalFlags.IsTemp) != 0)
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A reference requires a source variable, not a temporary value."u8);
    }

    private static bool IsSourceReadonlyReferencePlace(int placeId, in FuncLowerCtx fctx, in MirModuleArena mir)
    {
        MirPlace place = mir.Places[placeId];
        MirLocal local = fctx.Locals[place.LocalId];
        bool readOnly = local.Mode == PassMode.In || local.Mode == PassMode.ThisShared ||
            (local.Flags & MirLocalFlags.IsUsingVar) != 0 || fctx.SourceReadonlyLocals[place.LocalId] != 0 ||
            ((local.Flags & MirLocalFlags.IsRefLocal) != 0 && (local.Flags & MirLocalFlags.IsRefMut) == 0);
        for (int i = 0; i < place.ProjCount; i++)
        {
            MirProj projection = mir.Projs[place.ProjStart + i];
            // A readonly class reference does not make its referent's fields
            // readonly; readonly value projections, in contrast, stay readonly.
            if ((projection.Flags & 1) != 0) readOnly = false;
            if ((projection.Flags & 2) != 0) readOnly = true;
        }
        return readOnly;
    }

    private static void LowerExplicitAndDefaultCallArgs(in FuncDecl fd, in FuncInstance fnInst, int paramSigOffset, int fdParamOffset, int callArgExtraStart, int callArgCount, int tokIdx, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags, ref Vec<MirCallArg> loweredArgs, ref bool hasTwoPhaseArg) => LowerExplicitAndDefaultCallArgs(in fd, in fnInst, paramSigOffset, fdParamOffset, callArgExtraStart, callArgCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, ref loweredArgs, ref hasTwoPhaseArg, 0);

    private static void LowerExplicitAndDefaultCallArgs(
        in FuncDecl fd,
        in FuncInstance fnInst,
        int paramSigOffset,
        int fdParamOffset,
        int callArgExtraStart,
        int callArgCount,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        ref Vec<MirCallArg> loweredArgs,
        ref bool hasTwoPhaseArg,
        int excludeTrailingParams)
    {
        int formalCount = fnInst.ParamSigCount - paramSigOffset - excludeTrailingParams;
        var argToParam = new Vec<int>(callArgCount);
        var paramToArg = new Vec<int>(formalCount);
        if (!TryMapCallArgsToParams(in fd, fdParamOffset, callArgExtraStart, callArgCount, in ast, ref argToParam, ref paramToArg, out _, excludeTrailingParams))
        {
            argToParam.Clear();
            paramToArg.Clear();
            paramToArg.Resize(formalCount, -1);
            for (int a = 0; a < callArgCount && a < formalCount; a++)
            {
                argToParam.Push(a);
                paramToArg[a] = a;
            }
        }

        var slotArgs = new Vec<MirCallArg>(formalCount);
        for (int p = 0; p < formalCount; p++)
        {
            slotArgs.Push(new MirCallArg(PassMode.ByValue, -1, tokIdx));
        }

        // Evaluate all explicit arguments strictly in left-to-right lexical call-site order!
        for (int a = 0; a < argToParam.Count; a++)
        {
            int p = argToParam[a];
            MirParamSig psig = mir.ParamSigs[fnInst.ParamSigStart + paramSigOffset + p];
            AstNode cArg = ast.Nodes[ast.Extra[callArgExtraStart + a]];
            int argTok = cArg.TokIdx;
            bool hasSubsequentExplicitArgs = a + 1 < argToParam.Count;

            if (psig.Mode == PassMode.ByValue)
            {
                int opId = LowerExprAsOperand(cArg.B, psig.TypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                opId = MaterializeByValueCallArgIfNeeded(opId, hasSubsequentExplicitArgs, argTok, ref fctx, in types, ref mir);
                slotArgs[p] = new MirCallArg(PassMode.ByValue, opId, argTok);
            }
            else if (psig.Mode == PassMode.In)
            {
                bool refReadonly = (ast.Params[fd.ParamStart + fdParamOffset + p].Flags & DeclFlags.Readonly) != 0;
                PassMode sourceMode = CallArgBits.Mode(in cArg);
                if (!refReadonly && sourceMode == PassMode.Ref)
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[cArg.B].TokIdx], "C# warning CS9191 is not permitted in Vibranium: The 'ref' modifier for an argument corresponding to an 'in' parameter is equivalent to 'in'. Consider using 'in' instead."u8);
                if (refReadonly && sourceMode == PassMode.ByValue)
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[argTok], "A direct 'ref readonly' argument must be a variable with an explicit 'in' or 'ref' modifier."u8);
                int inPl;
                if (!refReadonly && sourceMode == PassMode.ByValue &&
                    InArgumentNeedsConversion(cArg.B, psig.TypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags))
                {
                    // An implicitly converted argument is a new value: C# passes
                    // a temporary of the parameter type, never the source variable.
                    int convertedOp = LowerExprAsOperand(cArg.B, psig.TypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    int convertedType = mir.Operands[convertedOp].TypeId;
                    int convertedTmp = fctx.NewTemp(convertedType, argTok, ref mir);
                    inPl = mir.AddPlaceLocal(convertedTmp, convertedType);
                    fctx.Emit(new MirInst(MirOp.AssignUse, inPl, -1, 0, convertedType, convertedOp, 0, 0, 0, argTok));
                }
                else
                {
                    inPl = LowerPlaceOrTemp(cArg.B, psig.TypeId, isMut: sourceMode == PassMode.Ref, isTwoPhase: false, argTok, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags,
                        requireVariable: refReadonly || sourceMode == PassMode.In);
                }
                if (sourceMode == PassMode.Ref)
                {
                    CheckNotDirectCapturedPrimaryParamWrite(cArg.B, "Cannot pass captured primary-constructor parameter by 'ref'."u8, in fctx, in ast, in ta, in types, ref diags);
                    if (IsSourceReadonlyReferencePlace(inPl, in fctx, in mir))
                        diags.ReportTok(VibCodes.MutateSharedBorrow, ta.Tokens[ast.Nodes[cArg.B].TokIdx], "Cannot pass a readonly variable with an explicit 'ref' modifier (CS1510/CS8329)."u8);
                }
                if (hasSubsequentExplicitArgs)
                {
                    inPl = ReserveReceiverPlace(inPl, psig.TypeId, isMut: false, isTwoPhase: false, argTok, ref fctx, ref mir);
                }
                slotArgs[p] = new MirCallArg(PassMode.In, inPl, argTok);
            }
            else if (psig.Mode == PassMode.Ref)
            {
                CheckNotDirectCapturedPrimaryParamWrite(cArg.B, "Cannot pass captured primary-constructor parameter by 'ref'."u8, in fctx, in ast, in ta, in types, ref diags);
                int refPl = LowerPlace(cArg.B, isMut: true, isTwoPhase: hasSubsequentExplicitArgs, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                CheckSourceReferencePlace(refPl, psig.TypeId, true, argTok, in fctx, in ta, in types, in mir, ref diags);
                if (hasSubsequentExplicitArgs)
                {
                    refPl = ReserveReceiverPlace(refPl, psig.TypeId, isMut: true, isTwoPhase: true, argTok, ref fctx, ref mir);
                    hasTwoPhaseArg = true;
                }
                slotArgs[p] = new MirCallArg(PassMode.Ref, refPl, argTok);
            }
            else // PassMode.Out
            {
                int outPl = LowerOutCallArgPlace(in cArg, psig.TypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                if (hasSubsequentExplicitArgs)
                {
                    outPl = ReserveReceiverPlace(outPl, psig.TypeId, isMut: true, isTwoPhase: true, argTok, ref fctx, ref mir, isAssignmentTargetSnapshot: true);
                    hasTwoPhaseArg = true;
                }
                slotArgs[p] = new MirCallArg(PassMode.Out, outPl, argTok);
            }
        }

        // Fill omitted optional default parameters and push in formal parameter order.
        for (int p = 0; p < formalCount; p++)
        {
            if (paramToArg[p] < 0)
            {
                MirParamSig psig = mir.ParamSigs[fnInst.ParamSigStart + paramSigOffset + p];
                int defExpr = ast.Params[fd.ParamStart + fdParamOffset + p].DefaultExpr;
                int defOp = defExpr >= 0
                    ? LowerExprAsOperand(defExpr, psig.TypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                    : mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, psig.TypeId, tokIdx));
                loweredArgs.Push(new MirCallArg(PassMode.ByValue, defOp, tokIdx));
            }
            else
            {
                loweredArgs.Push(slotArgs[p]);
            }
        }
    }

    private static int EmitResolvedUserCall(int funcDeclId, int ownerTypeId, int preLoweredRecvPlace, int explicitMethodTaStart, int explicitMethodTaCount, int callArgExtraStart, int callArgCount, int tokIdx, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags) => EmitResolvedUserCall(funcDeclId, ownerTypeId, preLoweredRecvPlace, explicitMethodTaStart, explicitMethodTaCount, callArgExtraStart, callArgCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, false);

    private static int EmitResolvedUserCall(
        int funcDeclId,
        int ownerTypeId,
        int preLoweredRecvPlace,
        int explicitMethodTaStart,
        int explicitMethodTaCount,
        int callArgExtraStart,
        int callArgCount,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        bool isTwoPhaseRecv)
    {
        FuncDecl fd = ast.Funcs[funcDeclId];
        Token tok = ta.Tokens[tokIdx];

        var methodTypeArgs = new Vec<int>(fd.TypeParamCount);
        ResolveMethodTypeArgumentsForCall(in fd, ownerTypeId, -1, explicitMethodTaStart, explicitMethodTaCount, callArgExtraStart, callArgCount, tok, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref methodTypeArgs);

        int instId = DeclBinder.EnsureFuncInstance(funcDeclId, ownerTypeId, methodTypeArgs.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
        if (instId < 0)
        {
            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
        }
        FuncInstance fnInst = mir.FuncInstances[instId];

        bool hasImplicitThis = (fd.Flags & DeclFlags.Static) == 0 && (fd.Flags & DeclFlags.IsCtor) == 0 && ownerTypeId >= 0;
        int paramOffset = hasImplicitThis ? 1 : 0;

        var loweredArgs = new Vec<MirCallArg>(fnInst.ParamSigCount);
        if (hasImplicitThis)
        {
            PassMode recvMode = mir.ParamSigs[fnInst.ParamSigStart].Mode;
            if (types.Items[ownerTypeId].Kind == TypeKinds.Class)
            {
                int recvOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, preLoweredRecvPlace, 0, ownerTypeId, tokIdx));
                loweredArgs.Push(new MirCallArg(recvMode, recvOp, tokIdx));
            }
            else
            {
                loweredArgs.Push(new MirCallArg(recvMode, preLoweredRecvPlace, tokIdx));
            }
        }

        bool hasTwoPhaseArg = isTwoPhaseRecv;
        LowerExplicitAndDefaultCallArgs(in fd, in fnInst, paramOffset, 0, callArgExtraStart, callArgCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, ref loweredArgs, ref hasTwoPhaseArg);

        int caStart = mir.CallArgs.Count;
        for (int i = 0; i < loweredArgs.Count; i++) mir.CallArgs.Push(loweredArgs[i]);

        int callFlags = hasTwoPhaseArg ? 2 : 0;
        if ((fnInst.Flags & DeclFlags.ReturnsByRef) != 0 && (fd.Flags & DeclFlags.IsCtor) == 0)
        {
            bool rMut = (fnInst.Flags & DeclFlags.ReturnRefMut) != 0;
            int refTmp = fctx.NewTempRef(fnInst.ReturnTypeId, rMut, tokIdx);
            fctx.EmitCall(new MirInst(MirOp.Call, -1, refTmp, (rMut ? 1 : 0) | callFlags, fnInst.ReturnTypeId, instId, caStart, loweredArgs.Count, 0, tokIdx), in mir);
            var deref = new Vec<MirProj>(1);
            deref.Push(new MirProj(MirProjKinds.Deref, 0, fnInst.ReturnTypeId, -1, 0));
            int dPl = mir.AddPlace(refTmp, deref.AsReadOnlySpan(), fnInst.ReturnTypeId);
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dPl, 0, fnInst.ReturnTypeId, tokIdx));
        }

        if (fnInst.ReturnTypeId == TypeIds.Void)
        {
            fctx.EmitCall(new MirInst(MirOp.Call, -1, -1, callFlags, TypeIds.Void, instId, caStart, loweredArgs.Count, 0, tokIdx), in mir);
            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
        }

        int dstTmp = fctx.NewTemp(fnInst.ReturnTypeId, tokIdx, ref mir);
        int dstPl = mir.AddPlaceLocal(dstTmp, fnInst.ReturnTypeId);
        fctx.EmitCall(new MirInst(MirOp.Call, dstPl, -1, callFlags, fnInst.ReturnTypeId, instId, caStart, loweredArgs.Count, 0, tokIdx), in mir);
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, fnInst.ReturnTypeId, tokIdx));
    }

    private static int EmitResolvedRefUserCall(
        int funcDeclId,
        int ownerTypeId,
        int preLoweredRecvPlace,
        int explicitMethodTaStart,
        int explicitMethodTaCount,
        int callArgExtraStart,
        int callArgCount,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        bool isTwoPhaseRecv,
        out int targetTypeId)
    {
        FuncDecl fd = ast.Funcs[funcDeclId];
        Token tok = ta.Tokens[tokIdx];
        var methodTypeArgs = new Vec<int>(fd.TypeParamCount);
        ResolveMethodTypeArgumentsForCall(in fd, ownerTypeId, -1, explicitMethodTaStart, explicitMethodTaCount, callArgExtraStart, callArgCount, tok, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref methodTypeArgs);

        int instId = DeclBinder.EnsureFuncInstance(funcDeclId, ownerTypeId, methodTypeArgs.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
        if (instId < 0)
        {
            targetTypeId = TypeIds.I32;
            return fctx.NewTempRef(TypeIds.I32, isMut: false, tokIdx);
        }
        FuncInstance fnInst = mir.FuncInstances[instId];
        targetTypeId = fnInst.ReturnTypeId;

        bool hasImplicitThis = (fd.Flags & DeclFlags.Static) == 0 && (fd.Flags & DeclFlags.IsCtor) == 0 && ownerTypeId >= 0;
        int paramOffset = hasImplicitThis ? 1 : 0;
        var loweredArgs = new Vec<MirCallArg>(fnInst.ParamSigCount);
        if (hasImplicitThis)
        {
            PassMode recvMode = mir.ParamSigs[fnInst.ParamSigStart].Mode;
            if (types.Items[ownerTypeId].Kind == TypeKinds.Class)
            {
                int recvOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, preLoweredRecvPlace, 0, ownerTypeId, tokIdx));
                loweredArgs.Push(new MirCallArg(recvMode, recvOp, tokIdx));
            }
            else
            {
                loweredArgs.Push(new MirCallArg(recvMode, preLoweredRecvPlace, tokIdx));
            }
        }

        bool hasTwoPhaseArg = isTwoPhaseRecv;
        LowerExplicitAndDefaultCallArgs(in fd, in fnInst, paramOffset, 0, callArgExtraStart, callArgCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, ref loweredArgs, ref hasTwoPhaseArg);

        int caStart = mir.CallArgs.Count;
        for (int i = 0; i < loweredArgs.Count; i++) mir.CallArgs.Push(loweredArgs[i]);
        bool rMut = (fnInst.Flags & DeclFlags.ReturnRefMut) != 0;
        int refTmp = fctx.NewTempRef(fnInst.ReturnTypeId, rMut, tokIdx);
        fctx.EmitCall(new MirInst(MirOp.Call, -1, refTmp, (rMut ? 1 : 0) | (hasTwoPhaseArg ? 2 : 0), fnInst.ReturnTypeId, instId, caStart, loweredArgs.Count, 0, tokIdx), in mir);
        return refTmp;
    }

    private static bool InArgumentNeedsConversion(int exprId, int paramTypeId, ref FuncLowerCtx fctx, in AstArena ast,
        in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        if (paramTypeId < 0 || paramTypeId == TypeIds.Error) return false;
        if (ast.Nodes[exprId].Kind == AstKind.ExprCollLit) return true;
        int argType = InferExprType(exprId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        return argType >= 0 && argType != TypeIds.Error && argType != paramTypeId;
    }

    private static MirCallArg LowerExtensionReceiverCallArg(
        int recvExprId,
        MirParamSig psig0,
        bool hasLaterExplicitArgs,
        bool outerTwoPhase,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        ref bool hasTwoPhaseArg,
        bool requireVariable)
    {
        if (psig0.Mode == PassMode.ByValue)
        {
            int opId = LowerExprAsOperand(recvExprId, psig0.TypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            opId = MaterializeByValueCallArgIfNeeded(opId, hasLaterExplicitArgs, tokIdx, ref fctx, in types, ref mir);
            return new MirCallArg(PassMode.ByValue, opId, tokIdx);
        }
        if (psig0.Mode == PassMode.In)
        {
            int inPl = LowerPlaceOrTemp(recvExprId, psig0.TypeId, isMut: false, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, requireVariable);
            if (hasLaterExplicitArgs)
            {
                inPl = ReserveReceiverPlace(inPl, psig0.TypeId, isMut: false, isTwoPhase: false, tokIdx, ref fctx, ref mir);
            }
            return new MirCallArg(PassMode.In, inPl, tokIdx);
        }
        CheckNotDirectCapturedPrimaryParamWrite(recvExprId, "Cannot pass captured primary-constructor parameter by 'ref'."u8, in fctx, in ast, in ta, in types, ref diags);
        int refPl = LowerPlace(recvExprId, isMut: true, isTwoPhase: hasLaterExplicitArgs || outerTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        if (hasLaterExplicitArgs)
        {
            refPl = ReserveReceiverPlace(refPl, psig0.TypeId, isMut: true, isTwoPhase: true, tokIdx, ref fctx, ref mir);
            hasTwoPhaseArg = true;
        }
        return new MirCallArg(PassMode.Ref, refPl, tokIdx);
    }

    private static int EmitResolvedExtensionCall(
        int funcDeclId,
        int recvExprId,
        int recvTypeId,
        int explicitMethodTaStart,
        int explicitMethodTaCount,
        int callArgExtraStart,
        int callArgCount,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        FuncDecl fd = ast.Funcs[funcDeclId];
        Token tok = ta.Tokens[tokIdx];
        var methodTypeArgs = new Vec<int>(fd.TypeParamCount);
        // Type arguments are inferred from the arguments before the receiver is
        // lowered, so the receiver's declarations are put in scope for them.
        bool infersTypeArgs = fd.TypeParamCount > 0 && explicitMethodTaCount != fd.TypeParamCount;
        EnterReceiverScope(recvExprId, infersTypeArgs, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        ResolveMethodTypeArgumentsForCall(in fd, -1, recvTypeId, explicitMethodTaStart, explicitMethodTaCount, callArgExtraStart, callArgCount, tok, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref methodTypeArgs);
        fctx.LeaveSpeculativeInfer();

        int instId = DeclBinder.EnsureFuncInstance(funcDeclId, -1, methodTypeArgs.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
        if (instId < 0)
        {
            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
        }
        FuncInstance fnInst = mir.FuncInstances[instId];

        var loweredArgs = new Vec<MirCallArg>(fnInst.ParamSigCount);
        bool hasTwoPhaseArg = false;
        loweredArgs.Push(LowerExtensionReceiverCallArg(recvExprId, mir.ParamSigs[fnInst.ParamSigStart], callArgCount > 0, outerTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, ref hasTwoPhaseArg, (ast.Params[fd.ParamStart].Flags & DeclFlags.Readonly) != 0));
        LowerExplicitAndDefaultCallArgs(in fd, in fnInst, 1, 1, callArgExtraStart, callArgCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, ref loweredArgs, ref hasTwoPhaseArg);

        int caStart = mir.CallArgs.Count;
        for (int i = 0; i < loweredArgs.Count; i++) mir.CallArgs.Push(loweredArgs[i]);
        int callFlags = hasTwoPhaseArg ? 2 : 0;

        if ((fnInst.Flags & DeclFlags.ReturnsByRef) != 0)
        {
            bool rMut = (fnInst.Flags & DeclFlags.ReturnRefMut) != 0;
            int refTmp = fctx.NewTempRef(fnInst.ReturnTypeId, rMut, tokIdx);
            fctx.EmitCall(new MirInst(MirOp.Call, -1, refTmp, (rMut ? 1 : 0) | callFlags, fnInst.ReturnTypeId, instId, caStart, loweredArgs.Count, 0, tokIdx), in mir);
            var deref = new Vec<MirProj>(1);
            deref.Push(new MirProj(MirProjKinds.Deref, 0, fnInst.ReturnTypeId, -1, 0));
            int dPl = mir.AddPlace(refTmp, deref.AsReadOnlySpan(), fnInst.ReturnTypeId);
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dPl, 0, fnInst.ReturnTypeId, tokIdx));
        }

        if (fnInst.ReturnTypeId == TypeIds.Void)
        {
            fctx.EmitCall(new MirInst(MirOp.Call, -1, -1, callFlags, TypeIds.Void, instId, caStart, loweredArgs.Count, 0, tokIdx), in mir);
            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
        }

        int dstTmp = fctx.NewTemp(fnInst.ReturnTypeId, tokIdx, ref mir);
        int dstPl = mir.AddPlaceLocal(dstTmp, fnInst.ReturnTypeId);
        fctx.EmitCall(new MirInst(MirOp.Call, dstPl, -1, callFlags, fnInst.ReturnTypeId, instId, caStart, loweredArgs.Count, 0, tokIdx), in mir);
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, fnInst.ReturnTypeId, tokIdx));
    }

    private static int EmitResolvedRefExtensionCall(
        int funcDeclId,
        int recvExprId,
        int recvTypeId,
        int explicitMethodTaStart,
        int explicitMethodTaCount,
        int callArgExtraStart,
        int callArgCount,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        bool isTwoPhase,
        out int targetTypeId)
    {
        FuncDecl fd = ast.Funcs[funcDeclId];
        Token tok = ta.Tokens[tokIdx];
        var methodTypeArgs = new Vec<int>(fd.TypeParamCount);
        // Type arguments are inferred from the arguments before the receiver is
        // lowered, so the receiver's declarations are put in scope for them.
        bool infersTypeArgs = fd.TypeParamCount > 0 && explicitMethodTaCount != fd.TypeParamCount;
        EnterReceiverScope(recvExprId, infersTypeArgs, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        ResolveMethodTypeArgumentsForCall(in fd, -1, recvTypeId, explicitMethodTaStart, explicitMethodTaCount, callArgExtraStart, callArgCount, tok, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref methodTypeArgs);
        fctx.LeaveSpeculativeInfer();

        int instId = DeclBinder.EnsureFuncInstance(funcDeclId, -1, methodTypeArgs.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
        if (instId < 0)
        {
            targetTypeId = TypeIds.I32;
            return fctx.NewTempRef(TypeIds.I32, isMut: false, tokIdx);
        }
        FuncInstance fnInst = mir.FuncInstances[instId];
        targetTypeId = fnInst.ReturnTypeId;

        var loweredArgs = new Vec<MirCallArg>(fnInst.ParamSigCount);
        bool hasTwoPhaseArg = isTwoPhase;
        loweredArgs.Push(LowerExtensionReceiverCallArg(recvExprId, mir.ParamSigs[fnInst.ParamSigStart], callArgCount > 0, outerTwoPhase: isTwoPhase, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, ref hasTwoPhaseArg, (ast.Params[fd.ParamStart].Flags & DeclFlags.Readonly) != 0));
        LowerExplicitAndDefaultCallArgs(in fd, in fnInst, 1, 1, callArgExtraStart, callArgCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, ref loweredArgs, ref hasTwoPhaseArg);

        int caStart = mir.CallArgs.Count;
        for (int i = 0; i < loweredArgs.Count; i++) mir.CallArgs.Push(loweredArgs[i]);
        bool rMut = (fnInst.Flags & DeclFlags.ReturnRefMut) != 0;
        int refTmp = fctx.NewTempRef(fnInst.ReturnTypeId, rMut, tokIdx);
        fctx.EmitCall(new MirInst(MirOp.Call, -1, refTmp, (rMut ? 1 : 0) | (hasTwoPhaseArg ? 2 : 0), fnInst.ReturnTypeId, instId, caStart, loweredArgs.Count, 0, tokIdx), in mir);
        return refTmp;
    }

    private static void CollectTypeMethodCandidates(
        int declId,
        int nameId,
        bool allowInstance,
        bool allowStatic,
        bool isCtor,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in BinderCtx bctx,
        ref Vec<int> outCands)
    {
        if (declId < 0) return;
        TypeDecl td = ast.Types[declId];
        for (int m = 0; m < td.FuncCount; m++)
        {
            int fId = td.FuncStart + m;
            FuncDecl fd = ast.Funcs[fId];
            bool fdIsCtor = (fd.Flags & DeclFlags.IsCtor) != 0;
            if (isCtor)
            {
                if (!fdIsCtor) continue;
            }
            else
            {
                if (fdIsCtor || fd.NameId != nameId) continue;
                bool isStatic = (fd.Flags & DeclFlags.Static) != 0;
                if (isStatic && !allowStatic) continue;
                if (!isStatic && !allowInstance) continue;
            }
            if (IsAccessibleFuncFromCaller(fId, ref fctx, in ast, in bctx))
            {
                outCands.Push(fId);
            }
        }
    }

    private static void CollectExtensionCandidates(
        int nameId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in BinderCtx bctx,
        ref Vec<int> outCands)
    {
        for (int i = 0; i < bctx.ExtensionFuncs.Count; i++)
        {
            int fId = bctx.ExtensionFuncs[i];
            FuncDecl fd = ast.Funcs[fId];
            if (fd.NameId == nameId && fd.ParamCount >= 1 && IsAccessibleFuncFromCaller(fId, ref fctx, in ast, in bctx))
            {
                outCands.Push(fId);
            }
        }
    }

    private static bool IsMemoryExtensionsCallAllowed(
        int methodNameId,
        int explicitTaStart,
        int explicitTaCount,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags)
    {
        if (methodNameId != bctx.IdSequenceEqual &&
            methodNameId != bctx.IdStartsWith &&
            methodNameId != bctx.IdEndsWith &&
            methodNameId != bctx.IdIndexOf &&
            methodNameId != bctx.IdLastIndexOf &&
            methodNameId != bctx.IdContains)
        {
            return false;
        }
        if (explicitTaCount == 0) return true;
        if (explicitTaCount != 1) return false;
        int taTid = DeclBinder.ResolveTypeNode(ast.Extra[explicitTaStart], fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
        return taTid == TypeIds.U8;
    }

    private static void CollectMemoryExtensionsCandidates(
        int bseDeclId,
        int nameId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in BinderCtx bctx,
        ref Vec<int> outCands)
    {
        TypeDecl td = ast.Types[bseDeclId];
        for (int m = 0; m < td.FuncCount; m++)
        {
            int fId = td.FuncStart + m;
            FuncDecl fd = ast.Funcs[fId];
            if (fd.NameId != nameId || (fd.Flags & DeclFlags.Static) == 0) continue;
            // Exclude Vibranium-specific `string` overloads when called via BCL `System.MemoryExtensions`
            bool hasStrParam = false;
            for (int p = 0; p < fd.ParamCount; p++)
            {
                AstNode ptn = ast.Nodes[ast.Params[fd.ParamStart + p].TypeNode];
                if (ptn.Kind == AstKind.TypePrim && (TokKind)ptn.A == TokKind.KwString)
                {
                    hasStrParam = true;
                    break;
                }
            }
            if (!hasStrParam && IsAccessibleFuncFromCaller(fId, ref fctx, in ast, in bctx))
            {
                outCands.Push(fId);
            }
        }
    }

    private static void AppendApplicablePreludeCandidate(
        int calleeNameId,
        int explicitMethodTaStart,
        int explicitMethodTaCount,
        int callArgExtraStart,
        int callArgCount,
        ReadOnlySpan<int> actualArgTypes,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        ref Vec<int> appFuncIds,
        ref Vec<int> appRetTypes,
        ref Vec<int> appUsesDefaults,
        ref Vec<int> appParamTypes,
        ref Vec<int> appParamModes)
    {
        if (calleeNameId == bctx.IdWriteLine && explicitMethodTaCount == 0 && callArgCount == 0)
        {
            appFuncIds.Push(-10);
            appRetTypes.Push(TypeIds.Void);
            appUsesDefaults.Push(0);
            appParamTypes.Push(-1);
            appParamModes.Push((int)PassMode.ByValue);
            return;
        }

        if ((calleeNameId == bctx.IdWrite || calleeNameId == bctx.IdWriteLine) && explicitMethodTaCount == 0 && callArgCount == 1)
        {
            AstNode a0 = ast.Nodes[ast.Extra[callArgExtraStart]];
            if (CallArgBits.Mode(in a0) != PassMode.ByValue) return;
            int argT = actualArgTypes[0];
            int roSpanU8 = types.MakeSpan(TypeIds.U8, isReadOnly: true);
            int bestPrelParamT = -1;
            if (CheckSingleNamedArg(in a0, "utf8"u8, in names) &&
                ClassifyByValueConversionWithCtx(a0.B, argT, roSpanU8, in fctx, in names, in bctx, in ast, in ta, in types) >= 0 &&
                (CallArgBits.NameId(in a0) >= 0 || argT == roSpanU8 || types.Items[argT].Kind == TypeKinds.Span || ast.Nodes[a0.B].Kind == AstKind.ExprCollLit || ast.Nodes[a0.B].Kind == AstKind.ExprUtf8Lit))
            {
                bestPrelParamT = roSpanU8;
            }
            else if (CheckSingleNamedArg(in a0, "value"u8, in names))
            {
                if (argT == TypeIds.Char) bestPrelParamT = TypeIds.U16;
                else if (argT == TypeIds.Bool || argT == TypeIds.Str ||
                         (types.IsInteger(argT) && types.Items[argT].Kind != TypeKinds.Enum))
                {
                    bestPrelParamT = argT;
                }
            }
            if (bestPrelParamT < 0 && argT == TypeIds.Error)
                bestPrelParamT = ChooseTargetTypedWriteParameter(in a0, true, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            if (bestPrelParamT >= 0)
            {
                appFuncIds.Push(-10);
                appRetTypes.Push(TypeIds.Void);
                appUsesDefaults.Push(0);
                appParamTypes.Push(-1);
                appParamTypes.Push(bestPrelParamT);
                appParamModes.Push((int)PassMode.ByValue);
                appParamModes.Push((int)PassMode.ByValue);
            }
            return;
        }

        if (calleeNameId == bctx.IdOk && explicitMethodTaCount == 0 && callArgCount == 0)
        {
            appFuncIds.Push(-10);
            appRetTypes.Push(types.MakeOkWrap(TypeIds.NoneUnit));
            appUsesDefaults.Push(0);
            appParamTypes.Push(-1);
            appParamModes.Push((int)PassMode.ByValue);
            return;
        }

        if ((calleeNameId == bctx.IdSome || calleeNameId == bctx.IdOk || calleeNameId == bctx.IdErr || calleeNameId == bctx.IdMove) &&
            callArgCount == 1 && (explicitMethodTaCount == 0 || explicitMethodTaCount == 1))
        {
            AstNode a0 = ast.Nodes[ast.Extra[callArgExtraStart]];
            if (CallArgBits.Mode(in a0) != PassMode.ByValue) return;
            ReadOnlySpan<byte> expName = calleeNameId == bctx.IdErr ? "error"u8 : "value"u8;
            if (!CheckSingleNamedArg(in a0, expName, in names)) return;
            int argT = actualArgTypes[0];
            int tArg;
            if (explicitMethodTaCount == 1)
            {
                tArg = DeclBinder.ResolveTypeNode(ast.Extra[explicitMethodTaStart], fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                if (tArg <= 0 || tArg == TypeIds.Error || ClassifyImplicitExpressionConversion(a0.B, argT, tArg, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) < 0)
                {
                    return;
                }
            }
            else
            {
                if (argT <= 0 || argT == TypeIds.Void || argT == TypeIds.Error) return;
                if (calleeNameId != bctx.IdMove && types.IsView(argT)) return;
                tArg = argT;
            }
            int retT = calleeNameId == bctx.IdSome ? types.MakeSomeWrap(tArg) :
                       calleeNameId == bctx.IdOk ? types.MakeOkWrap(tArg) :
                       calleeNameId == bctx.IdErr ? types.MakeErrWrap(tArg) : tArg;
            appFuncIds.Push(-11);
            appRetTypes.Push(retT);
            appUsesDefaults.Push(0);
            appParamTypes.Push(-1);
            appParamTypes.Push(tArg);
            appParamModes.Push((int)PassMode.ByValue);
            appParamModes.Push((int)PassMode.ByValue);
        }
    }

    private static int ResolveBestOverload(ReadOnlySpan<int> candIds, int ownerTypeId, int extensionRecvTypeId, int explicitMethodTaStart, int explicitMethodTaCount, int callArgExtraStart, int callArgCount, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags, out bool isAmbiguous, out int resolvedReturnTypeId) => ResolveBestOverload(candIds, ownerTypeId, extensionRecvTypeId, explicitMethodTaStart, explicitMethodTaCount, callArgExtraStart, callArgCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out isAmbiguous, out resolvedReturnTypeId, false, -1);

    private static int ResolveBestOverload(ReadOnlySpan<int> candIds, int ownerTypeId, int extensionRecvTypeId, int explicitMethodTaStart, int explicitMethodTaCount, int callArgExtraStart, int callArgCount, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags, out bool isAmbiguous, out int resolvedReturnTypeId, bool includePreludeCompetitors) => ResolveBestOverload(candIds, ownerTypeId, extensionRecvTypeId, explicitMethodTaStart, explicitMethodTaCount, callArgExtraStart, callArgCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out isAmbiguous, out resolvedReturnTypeId, includePreludeCompetitors, -1);

    private static int ResolveBestOverload(
        ReadOnlySpan<int> candIds,
        int ownerTypeId,
        int extensionRecvTypeId,
        int explicitMethodTaStart,
        int explicitMethodTaCount,
        int callArgExtraStart,
        int callArgCount,
