        ref DiagnosticBag diags,
        out bool isAmbiguous,
        out int resolvedReturnTypeId,
        bool includePreludeCompetitors,
        int preludeCalleeNameId)
    {
        var emptyOwners = new Vec<int>();
        return ResolveBestOverloadWithOwners(
            candIds,
            emptyOwners.AsReadOnlySpan(),
            ownerTypeId,
            extensionRecvTypeId,
            explicitMethodTaStart,
            explicitMethodTaCount,
            callArgExtraStart,
            callArgCount,
            ref fctx,
            in ast,
            in ta,
            in names,
            ref bctx,
            ref types,
            ref diags,
            out isAmbiguous,
            out resolvedReturnTypeId,
            out _,
            includePreludeCompetitors,
            preludeCalleeNameId);
    }

