    private static int ResolveBestOverloadWithOwners(ReadOnlySpan<int> candIds, ReadOnlySpan<int> perCandOwnerTypeIds, int extensionRecvTypeId, int explicitMethodTaStart, int explicitMethodTaCount, int callArgExtraStart, int callArgCount, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags, out bool isAmbiguous, out int resolvedReturnTypeId, out int resolvedOwnerTypeId, bool includePreludeCompetitors) => ResolveBestOverloadWithOwners(candIds, perCandOwnerTypeIds, extensionRecvTypeId, explicitMethodTaStart, explicitMethodTaCount, callArgExtraStart, callArgCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out isAmbiguous, out resolvedReturnTypeId, out resolvedOwnerTypeId, includePreludeCompetitors, -1);

