    private static int ResolveBestOverloadWithOwners(ReadOnlySpan<int> candIds, ReadOnlySpan<int> perCandOwnerTypeIds, int defaultOwnerTypeId, int extensionRecvTypeId, int explicitMethodTaStart, int explicitMethodTaCount, int callArgExtraStart, int callArgCount, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags, out bool isAmbiguous, out int resolvedReturnTypeId, out int resolvedOwnerTypeId) => ResolveBestOverloadWithOwners(candIds, perCandOwnerTypeIds, defaultOwnerTypeId, extensionRecvTypeId, explicitMethodTaStart, explicitMethodTaCount, callArgExtraStart, callArgCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out isAmbiguous, out resolvedReturnTypeId, out resolvedOwnerTypeId, false, -1);

    private static int ResolveBestOverloadWithOwners(ReadOnlySpan<int> candIds, ReadOnlySpan<int> perCandOwnerTypeIds, int defaultOwnerTypeId, int extensionRecvTypeId, int explicitMethodTaStart, int explicitMethodTaCount, int callArgExtraStart, int callArgCount, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags, out bool isAmbiguous, out int resolvedReturnTypeId, out int resolvedOwnerTypeId, bool includePreludeCompetitors) => ResolveBestOverloadWithOwners(candIds, perCandOwnerTypeIds, defaultOwnerTypeId, extensionRecvTypeId, explicitMethodTaStart, explicitMethodTaCount, callArgExtraStart, callArgCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out isAmbiguous, out resolvedReturnTypeId, out resolvedOwnerTypeId, includePreludeCompetitors, -1);

    private static int ResolveBestOverloadWithOwners(
        ReadOnlySpan<int> candIds,
        ReadOnlySpan<int> perCandOwnerTypeIds,
        int defaultOwnerTypeId,
        int extensionRecvTypeId,
        int explicitMethodTaStart,
        int explicitMethodTaCount,
        int callArgExtraStart,
        int callArgCount,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        out bool isAmbiguous,
        out int resolvedReturnTypeId,
        out int resolvedOwnerTypeId,
        bool includePreludeCompetitors,
        int preludeCalleeNameId)
    {
        isAmbiguous = false;
        resolvedReturnTypeId = TypeIds.Void;
        resolvedOwnerTypeId = defaultOwnerTypeId;
        if (candIds.Length == 0 && !includePreludeCompetitors) return -1;

        fctx.InferDepth += 1;
        var actualArgTypes = new Vec<int>(callArgCount);
        var actualArgModes = new Vec<int>(callArgCount);
        var actualArgExprs = new Vec<int>(callArgCount);
        for (int a = 0; a < callArgCount; a++)
        {
            AstNode cArg = ast.Nodes[ast.Extra[callArgExtraStart + a]];
            actualArgModes.Push((int)CallArgBits.Mode(in cArg));
            actualArgExprs.Push(cArg.B);
            int actualT = InferCallArgActualType(in cArg, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            actualArgTypes.Push(actualT);
            // `out T name` declares its variable for the arguments after it.
            if (fctx.ElementRetypeDepth == 0 && cArg.C >= 0 && CallArgBits.Mode(in cArg) == PassMode.Out) PushSpeculativeOutArg(in cArg, actualT, ref fctx);
        }

        int stride = callArgCount + 1;
        var appFuncIds = new Vec<int>(candIds.Length);
        var appOwnerTypeIds = new Vec<int>(candIds.Length);
        var appRetTypes = new Vec<int>(candIds.Length);
        var appUsesDefaults = new Vec<int>(candIds.Length);
        var appParamTypes = new Vec<int>(candIds.Length * stride);
        var appParamModes = new Vec<int>(candIds.Length * stride);

        for (int c = 0; c < candIds.Length; c++)
        {
            int fId = candIds[c];
            int candOwnerTid = c < perCandOwnerTypeIds.Length ? perCandOwnerTypeIds[c] : defaultOwnerTypeId;
            var candPTypes = new Vec<int>(stride);
            var candPModes = new Vec<int>(stride);
            if (TryEvaluateCandidate(
                fId,
                candOwnerTid,
                extensionRecvTypeId,
                explicitMethodTaStart,
                explicitMethodTaCount,
                callArgExtraStart,
                callArgCount,
                actualArgTypes.AsReadOnlySpan(),
                ref fctx,
                in ast,
                in ta,
                in names,
                ref bctx,
                ref types,
                ref diags,
                ref candPTypes,
                ref candPModes,
                out int candRetT,
                out bool candUsesDef))
            {
                appFuncIds.Push(fId);
                appOwnerTypeIds.Push(candOwnerTid);
                appRetTypes.Push(candRetT);
                appUsesDefaults.Push(candUsesDef ? 1 : 0);
                for (int k = 0; k < stride; k++)
                {
                    appParamTypes.Push(candPTypes[k]);
                    appParamModes.Push(candPModes[k]);
                }
            }
        }

        int userAppCount = appFuncIds.Count;
        if (includePreludeCompetitors)
        {
            AppendApplicablePreludeCandidate(
                preludeCalleeNameId,
                explicitMethodTaStart,
                explicitMethodTaCount,
                callArgExtraStart,
                callArgCount,
                actualArgTypes.AsReadOnlySpan(),
                ref fctx,
                in ast,
                in ta,
                in names,
                ref bctx,
                ref types,
                ref diags,
                ref appFuncIds,
                ref appRetTypes,
                ref appUsesDefaults,
                ref appParamTypes,
                ref appParamModes);
        }

        int winIdx = -1;
        if (appFuncIds.Count == 1)
        {
            winIdx = 0;
        }
        else if (appFuncIds.Count > 1)
        {
            for (int i = 0; i < appFuncIds.Count; i++)
            {
                bool beatsAll = true;
                for (int j = 0; j < appFuncIds.Count; j++)
                {
                    if (i == j) continue;
                    if (!IsBetterCandidate(
                        appFuncIds[i],
                        appUsesDefaults[i] != 0,
                        appParamTypes.AsReadOnlySpan().Slice(i * stride, stride),
                        appParamModes.AsReadOnlySpan().Slice(i * stride, stride),
                        appFuncIds[j],
                        appUsesDefaults[j] != 0,
                        appParamTypes.AsReadOnlySpan().Slice(j * stride, stride),
                        appParamModes.AsReadOnlySpan().Slice(j * stride, stride),
                        extensionRecvTypeId,
                        actualArgTypes.AsReadOnlySpan(),
                        actualArgModes.AsReadOnlySpan(),
                        in ast,
                        in types))
                    {
                        beatsAll = false;
                        break;
                    }
                }
                if (beatsAll)
                {
                    winIdx = i;
                    break;
                }
            }
            if (winIdx < 0) isAmbiguous = true;
        }

        fctx.LeaveSpeculativeInfer();
        if (winIdx < 0) return -1;

        resolvedReturnTypeId = appRetTypes[winIdx];
        resolvedOwnerTypeId = winIdx < userAppCount ? appOwnerTypeIds[winIdx] : -1;
        if (fctx.InferDepth > 0)
        {
            ReadOnlySpan<int> winPTypes = appParamTypes.AsReadOnlySpan().Slice(winIdx * stride, stride);
            for (int a = 0; a < callArgCount; a++)
            {
                AstNode cArg = ast.Nodes[ast.Extra[callArgExtraStart + a]];
                // An `out var` gets the winner's parameter type; `out T name` is on the stack already.
                if (CallArgBits.Mode(in cArg) == PassMode.Out && (cArg.C == -1 || fctx.ElementRetypeDepth > 0))
                {
                    PushSpeculativeOutArg(in cArg, winPTypes[a + 1], ref fctx);
                }
            }
        }
        return appFuncIds[winIdx];
    }

    private static bool TryEvaluateCandidate(int funcDeclId, int ownerTypeId, int extensionRecvTypeId, int explicitMethodTaStart, int explicitMethodTaCount, int callArgExtraStart, int callArgCount, ReadOnlySpan<int> actualArgTypes, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags, ref Vec<int> outParamTypes, ref Vec<int> outParamModes, out int resolvedRetType, out bool usesDefaults) => TryEvaluateCandidate(funcDeclId, ownerTypeId, extensionRecvTypeId, explicitMethodTaStart, explicitMethodTaCount, callArgExtraStart, callArgCount, actualArgTypes, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, ref outParamTypes, ref outParamModes, out resolvedRetType, out usesDefaults, 0);

    private static bool TryEvaluateCandidate(
        int funcDeclId,
        int ownerTypeId,
        int extensionRecvTypeId,
        int explicitMethodTaStart,
        int explicitMethodTaCount,
        int callArgExtraStart,
        int callArgCount,
        ReadOnlySpan<int> actualArgTypes,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        ref Vec<int> outParamTypes,
        ref Vec<int> outParamModes,
        out int resolvedRetType,
        out bool usesDefaults,
        int excludeTrailingParams)
    {
        resolvedRetType = TypeIds.Void;
        usesDefaults = false;
        FuncDecl fd = ast.Funcs[funcDeclId];
        bool isExt = extensionRecvTypeId >= 0;
        int extOffset = isExt ? 1 : 0;
        int formalExplicitMax = fd.ParamCount - extOffset - excludeTrailingParams;

        var argToParam = new Vec<int>(callArgCount);
        var paramToArg = new Vec<int>(formalExplicitMax > 0 ? formalExplicitMax : 0);
        if (!TryMapCallArgsToParams(in fd, extOffset, callArgExtraStart, callArgCount, in ast, ref argToParam, ref paramToArg, out usesDefaults, excludeTrailingParams))
        {
            return false;
        }

        if (fd.TypeParamCount == 0 && explicitMethodTaCount > 0) return false;
        if (explicitMethodTaCount > 0 && explicitMethodTaCount != fd.TypeParamCount) return false;

        var tpNames = new Vec<int>();
        var tpVals = new Vec<int>();
        int resolvedOwnerTid = ownerTypeId;
        if (resolvedOwnerTid < 0 && fd.OwnerDeclId >= 0 && ast.Types[fd.OwnerDeclId].TypeParamCount == 0)
        {
            var emptyT = new Vec<int>();
            resolvedOwnerTid = types.MakeUserType(ast.Types[fd.OwnerDeclId].Kind == TypeDeclKinds.Class ? TypeKinds.Class : TypeKinds.Struct, fd.OwnerDeclId, names.Text(ast.Types[fd.OwnerDeclId].NameId), emptyT.AsReadOnlySpan());
        }
        if (resolvedOwnerTid >= 0)
        {
            BuildOwnerTypeSubst(resolvedOwnerTid, in ast, in types, ref tpNames, ref tpVals);
        }

        if (fd.TypeParamCount > 0)
        {
            if (explicitMethodTaCount == fd.TypeParamCount)
            {
                for (int i = 0; i < explicitMethodTaCount; i++)
                {
                    int tid = DeclBinder.ResolveTypeNode(ast.Extra[explicitMethodTaStart + i], fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                    if (tid < 0 || tid == TypeIds.Error || tid == TypeIds.Utf8Lines || tid == TypeIds.Utf8ArgEnum) return false;
                    tpNames.Push(ast.Extra[fd.TypeParamStart + i]);
                    tpVals.Push(tid);
                }
            }
            else
            {
                for (int tp = 0; tp < fd.TypeParamCount; tp++)
                {
                    int tpName = ast.Extra[fd.TypeParamStart + tp];
                    int inferred = -1;
                    if (isExt)
                    {
                        inferred = TryInferTypeParamFromNode(ast.Params[fd.ParamStart].TypeNode, extensionRecvTypeId, tpName, in ast, in bctx, in types);
                    }
                    for (int a = 0; inferred < 0 && a < callArgCount; a++)
                    {
                        AstNode argNode = ast.Nodes[ast.Extra[callArgExtraStart + a]];
                        if (CallArgBits.Mode(in argNode) == PassMode.Out && argNode.C < -1 && argNode.C != -2) continue;
                        int mappedP = argToParam[a];
                        inferred = TryInferTypeParamFromNode(ast.Params[fd.ParamStart + extOffset + mappedP].TypeNode, actualArgTypes[a], tpName, in ast, in bctx, in types);
                    }
                    if (inferred < 0 || inferred == TypeIds.Error || inferred == TypeIds.Void ||
                        inferred == TypeIds.Utf8Lines || inferred == TypeIds.Utf8ArgEnum)
                    {
                        return false;
                    }
                    tpNames.Push(tpName);
                    tpVals.Push(inferred);
                }
            }

            // Enforce `where T : unmanaged` (`TpFlags & 1 != 0` = unmanaged constraint in Parser) if present
            for (int tp = 0; tp < fd.TypeParamCount; tp++)
            {
                int tpFlags = ast.Extra[fd.TypeParamFlagsStart + tp];
                int substT = tpVals[tpVals.Count - fd.TypeParamCount + tp];
                if ((tpFlags & 1) != 0 && !types.IsCopy(substT, in ast))
                {
                    return false;
                }
                if ((tpFlags & 1) != 0 && types.IsView(substT))
                {
                    return false;
                }
            }
        }

        // Slot 0 in outParamTypes/outParamModes is the extension receiver (or -1 for non-extension)
        if (isExt)
        {
            ParamDecl p0 = ast.Params[fd.ParamStart];
            int p0Type = DeclBinder.ResolveTypeNode(p0.TypeNode, tpNames.AsReadOnlySpan(), tpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
            if (p0.Mode == PassMode.Out) return false;
            if (p0.Mode == PassMode.Ref || p0.Mode == PassMode.In)
            {
                if (extensionRecvTypeId != p0Type) return false;
            }
            else
            {
                // Extension receiver `this T`: identity or `Span<E> -> ReadOnlySpan<E>` shared reborrow
                if (extensionRecvTypeId != p0Type)
                {
                    TypeInfo rti = types.Items[extensionRecvTypeId];
                    TypeInfo p0ti = types.Items[p0Type];
                    if (!(rti.Kind == TypeKinds.Span && p0ti.Kind == TypeKinds.ReadOnlySpan && rti.A == p0ti.A))
                    {
                        return false;
                    }
                }
            }
            outParamTypes.Push(p0Type);
            outParamModes.Push((int)p0.Mode);
        }
        else
        {
            outParamTypes.Push(-1);
            outParamModes.Push((int)PassMode.ByValue);
        }

        for (int a = 0; a < callArgCount; a++)
        {
            ParamDecl pd = ast.Params[fd.ParamStart + extOffset + argToParam[a]];
            int pType = DeclBinder.ResolveTypeNode(pd.TypeNode, tpNames.AsReadOnlySpan(), tpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
            if (pType < 0 || pType == TypeIds.Error) return false;

            AstNode cArg = ast.Nodes[ast.Extra[callArgExtraStart + a]];
            PassMode argMode = CallArgBits.Mode(in cArg);

            if (pd.Mode == PassMode.ByValue)
            {
                if (argMode != PassMode.ByValue) return false;
                if (ClassifyImplicitExpressionConversion(cArg.B, actualArgTypes[a], pType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) < 0) return false;
            }
            else if (pd.Mode == PassMode.In)
            {
                if (argMode != PassMode.In && argMode != PassMode.ByValue && argMode != PassMode.Ref) return false;
                if (actualArgTypes[a] != pType)
                {
                    // C#: an argument without a modifier needs only an implicit
                    // conversion to an `in` parameter; the converted value is
                    // passed through a temporary. `in`/`ref` arguments need identity.
                    if (argMode != PassMode.ByValue) return false;
                    if (ClassifyImplicitExpressionConversion(cArg.B, actualArgTypes[a], pType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) < 0) return false;
                }
            }
            else if (pd.Mode == PassMode.Ref)
            {
                if (argMode != PassMode.Ref) return false;
                if (actualArgTypes[a] != pType) return false;
            }
            else // PassMode.Out
            {
                if (argMode != PassMode.Out) return false;
                if (!IsOutArgCompatibleWithType(in cArg, pType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags)) return false;
            }

            outParamTypes.Push(pType);
            outParamModes.Push((int)pd.Mode);
        }

        if ((fd.Flags & DeclFlags.IsCtor) != 0)
        {
            resolvedRetType = resolvedOwnerTid >= 0 ? resolvedOwnerTid : TypeIds.Void;
        }
        else if (excludeTrailingParams > 0 && fd.ParamCount > 0)
        {
            int valNode = ast.Params[fd.ParamStart + fd.ParamCount - 1].TypeNode;
            resolvedRetType = DeclBinder.ResolveTypeNode(valNode, tpNames.AsReadOnlySpan(), tpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
        }
        else
        {
            resolvedRetType = fd.RetTypeNode >= 0
                ? DeclBinder.ResolveTypeNode(fd.RetTypeNode, tpNames.AsReadOnlySpan(), tpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false)
                : TypeIds.Void;
        }
        return true;
    }

    private static bool IsBetterCandidate(
        int fId1,
        bool usesDef1,
        ReadOnlySpan<int> pTypes1,
        ReadOnlySpan<int> pModes1,
        int fId2,
        bool usesDef2,
        ReadOnlySpan<int> pTypes2,
        ReadOnlySpan<int> pModes2,
        int extensionRecvTypeId,
        ReadOnlySpan<int> actualArgTypes,
        ReadOnlySpan<int> actualArgModes,
        in AstArena ast,
        in TypeTable types)
    {
        int betterCount = 0;
        int worseCount = 0;

        if (extensionRecvTypeId >= 0)
        {
            int cmp0 = CompareSingleConversion(extensionRecvTypeId, (PassMode)PassMode.ByValue, pTypes1[0], (PassMode)pModes1[0], pTypes2[0], (PassMode)pModes2[0], in types);
            if (cmp0 > 0) betterCount += 1;
            else if (cmp0 < 0) worseCount += 1;
        }

        for (int p = 0; p < actualArgTypes.Length; p++)
        {
            int cmp = CompareSingleConversion(actualArgTypes[p], (PassMode)actualArgModes[p], pTypes1[p + 1], (PassMode)pModes1[p + 1], pTypes2[p + 1], (PassMode)pModes2[p + 1], in types);
            if (cmp > 0) betterCount += 1;
            else if (cmp < 0) worseCount += 1;
        }

        if (worseCount > 0) return false;
        if (betterCount > 0) return true;

        // Tie-breaker 1: non-generic beats generic
        int tpc1 = fId1 == -11 ? 1 : (fId1 < 0 ? 0 : ast.Funcs[fId1].TypeParamCount);
        int tpc2 = fId2 == -11 ? 1 : (fId2 < 0 ? 0 : ast.Funcs[fId2].TypeParamCount);
        if (tpc1 == 0 && tpc2 > 0) return true;
        if (tpc1 > 0 && tpc2 == 0) return false;

        // Tie-breaker 2: no default-arg substitution beats default-arg substitution (if BOTH use defaults -> ambiguous!)
        if (!usesDef1 && usesDef2) return true;
        return false;
    }

    private static int CompareSingleConversion(
        int argType,
        PassMode argMode,
        int t1,
        PassMode m1,
        int t2,
        PassMode m2,
        in TypeTable types)
    {
        if (t1 == t2)
        {
            if (argMode == PassMode.ByValue)
            {
                if (m1 == PassMode.ByValue && m2 == PassMode.In) return 1;
                if (m2 == PassMode.ByValue && m1 == PassMode.In) return -1;
            }
            return 0;
        }

        if (argType >= 0)
        {
            if (argType == t1 && argType != t2) return 1;
            if (argType == t2 && argType != t1) return -1;
        }

        // Specificity: T1 implicitly converts to T2 and T2 does not implicitly convert to T1
        bool t1ToT2 = CanSpecificityConvert(t1, t2, in types);
        bool t2ToT1 = CanSpecificityConvert(t2, t1, in types);
        if (t1ToT2 && !t2ToT1) return 1;
        if (t2ToT1 && !t1ToT2) return -1;

        // C# §12.6.4.5 signed integer better than unsigned integer of same/wider width
        if (IsBetterSignedOverUnsigned(t1, t2)) return 1;
        if (IsBetterSignedOverUnsigned(t2, t1)) return -1;

        return 0;
    }

    private static bool CanSpecificityConvert(int srcT, int dstT, in TypeTable types)
    {
        if (srcT == dstT) return true;
        if (CanImplicitNumericWiden(srcT, dstT)) return true;
        TypeInfo sti = types.Items[srcT];
        TypeInfo dti = types.Items[dstT];
        if (sti.Kind == TypeKinds.Span && dti.Kind == TypeKinds.ReadOnlySpan && sti.A == dti.A) return true;
        return false;
    }

    private static bool IsBetterSignedOverUnsigned(int t1, int t2)
    {
        if (t1 == TypeIds.I8 && (t2 == TypeIds.U8 || t2 == TypeIds.U16 || t2 == TypeIds.U32 || t2 == TypeIds.U64 || t2 == TypeIds.NUInt)) return true;
        if (t1 == TypeIds.I16 && (t2 == TypeIds.U16 || t2 == TypeIds.U32 || t2 == TypeIds.U64 || t2 == TypeIds.NUInt)) return true;
        if (t1 == TypeIds.I32 && (t2 == TypeIds.U32 || t2 == TypeIds.U64 || t2 == TypeIds.NUInt)) return true;
        if (t1 == TypeIds.I64 && (t2 == TypeIds.U64 || t2 == TypeIds.NUInt)) return true;
        if (t1 == TypeIds.NInt && (t2 == TypeIds.U32 || t2 == TypeIds.U64 || t2 == TypeIds.NUInt)) return true;
        return false;
    }

    // Prelude.Write/WriteLine are synthetic candidates. Give an expression
    // without a natural type the same applicability and better-target rules
    // as declared methods rather than guessing an arm's type.
    private static int ChooseTargetTypedWriteParameter(in AstNode arg, bool allowBytes, ref FuncLowerCtx fctx,
        in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        AstKind kind = ast.Nodes[arg.B].Kind;
        if (kind != AstKind.ExprCond && kind != AstKind.ExprSwitch) return -1;
        var candidates = new Vec<int>();
        if (CheckSingleNamedArg(in arg, "value"u8, in names))
        {
            for (int t = TypeIds.Bool; t <= TypeIds.U64; t++) if (t != TypeIds.Char) candidates.Push(t);
            candidates.Push(TypeIds.Str);
        }
        if (allowBytes && CheckSingleNamedArg(in arg, "utf8"u8, in names)) candidates.Push(types.MakeSpan(TypeIds.U8, isReadOnly: true));
        var applicable = new Vec<int>();
        for (int i = 0; i < candidates.Count; i++)
        {
            int t = candidates[i];
            if (ClassifyImplicitExpressionConversion(arg.B, TypeIds.Error, t, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) >= 0)
                applicable.Push(t);
        }
        if (applicable.Count == 1) return applicable[0];
        for (int i = 0; i < applicable.Count; i++)
        {
            bool best = true;
            for (int j = 0; j < applicable.Count; j++)
            {
                if (j == i) continue;
                if (CompareSingleConversion(TypeIds.Error, PassMode.ByValue, applicable[i], PassMode.ByValue,
                    applicable[j], PassMode.ByValue, in types) <= 0) { best = false; break; }
            }
            if (best) return applicable[i];
        }
        return -1;
    }

    private static int ClassifyImplicitExpressionConversion(int expressionId, int actualType, int targetType,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names,
        ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        int mark = fctx.Vars.Count;
        fctx.InferDepth += 1;
        int result = ClassifyImplicitExpressionConversionCore(expressionId, actualType, targetType,
            ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        fctx.Vars.Truncate(mark);
        fctx.LeaveSpeculativeInfer();
        return result;
    }

    private static int ClassifyImplicitExpressionConversionCore(int expressionId, int actualType, int targetType,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names,
        ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        if (expressionId < 0 || targetType < 0 || targetType == TypeIds.Error || targetType == TypeIds.Void) return -1;
        AstNode expression = ast.Nodes[expressionId];
        TypeInfo target = types.Items[targetType];
        bool collectionTarget = target.Kind == TypeKinds.Vec || target.Kind == TypeKinds.Span || target.Kind == TypeKinds.ReadOnlySpan;
        if (expression.Kind == AstKind.ExprCollLit)
        {
            if (!collectionTarget) return -1;
            for (int i = 0; i < expression.B; i++)
            {
                int element = ast.Extra[expression.A + i];
                fctx.ElementRetypeDepth += 1;
                int elementType = InferExprType(element, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                fctx.ElementRetypeDepth -= 1;
                if (ClassifyImplicitExpressionConversionCore(element, elementType, target.A,
                    ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) < 0) return -1;
            }
            return 1;
        }
        if (expression.Kind == AstKind.ExprCond || expression.Kind == AstKind.ExprSwitch)
        {
            // A naturally typed conditional needs a conversion from that
            // type. An untyped conditional or a switch can instead convert
            // each arm independently to the target.
            if (CanUseNaturalBranchType(actualType, targetType, in ast, in ta, in types))
                return actualType == targetType ? 0 : 1;
            if (expression.Kind == AstKind.ExprCond && actualType >= 0 && actualType != TypeIds.Error && actualType != TypeIds.Void)
                return -1;
        }
        if (expression.Kind == AstKind.ExprCond || expression.Kind == AstKind.ExprSwitch)
            return ClassifyBranchArmConversions(expressionId, in expression, targetType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        // Scalar call arguments retain their existing natural-type/ranking rules.
        return ClassifyByValueConversionWithCtx(expressionId, actualType, targetType, in fctx, in names, in bctx, in ast, in ta, in types);
    }

    private static int ClassifyByValueConversion(
        int argExprId,
        int argTypeId,
        int paramTypeId,
        in AstArena ast,
        in TokenArena ta,
        in TypeTable types)
    {
        if (paramTypeId < 0 || paramTypeId == TypeIds.Void || paramTypeId == TypeIds.Error ||
            paramTypeId == TypeIds.Utf8Lines || paramTypeId == TypeIds.Utf8ArgEnum)
        {
            return -1;
        }
        if (argTypeId == TypeIds.Utf8Lines || argTypeId == TypeIds.Utf8ArgEnum)
        {
            return -1;
        }
        if (argTypeId == paramTypeId && argTypeId >= 0 && argTypeId != TypeIds.Void && argTypeId != TypeIds.Error)
        {
            return 0;
        }

        TypeInfo pti = types.Items[paramTypeId];

        if (argExprId >= 0)
        {
            AstNode an = ast.Nodes[argExprId];
            if (an.Kind == AstKind.ExprDefault && an.A < 0)
            {
                return 1;
            }
            if (an.Kind == AstKind.ExprNull)
            {
                return 1;
            }
            if (an.Kind == AstKind.ExprNew && an.A < 0)
            {
                if (pti.Kind == TypeKinds.Vec || pti.Kind == TypeKinds.Struct || pti.Kind == TypeKinds.Class ||
                    pti.Kind == TypeKinds.Option || pti.Kind == TypeKinds.Result)
                {
                    return 1;
                }
            }
            if (an.Kind == AstKind.ExprCollLit)
            {
                if (pti.Kind == TypeKinds.Vec || pti.Kind == TypeKinds.Span || pti.Kind == TypeKinds.ReadOnlySpan)
                {
                    if (an.B == 0) return 1;
                    for (int i = 0; i < an.B; i++)
                    {
                        int elemExpr = ast.Extra[an.A + i];
                        AstNode en = ast.Nodes[elemExpr];
                        if (en.Kind == AstKind.ExprIntLit && !FitsConstantIntSimple(elemExpr, TypeIds.I32, pti.A, in ast, in ta, in types) && !CanImplicitNumericWiden(TypeIds.I32, pti.A) && pti.A != TypeIds.I32)
                        {
                            return -1;
                        }
                    }
                    return 1;
                }
                return -1;
            }
            if (FitsConstantIntSimple(argExprId, argTypeId, paramTypeId, in ast, in ta, in types))
            {
                return 1;
            }
        }

        if (CanImplicitNumericWiden(argTypeId, paramTypeId))
        {
            return 1;
        }

        TypeInfo ati = types.Items[argTypeId];
        if (ati.Kind == TypeKinds.Span && pti.Kind == TypeKinds.ReadOnlySpan && ati.A == pti.A)
        {
            return 1;
        }
        if (argTypeId == TypeIds.NoneUnit && pti.Kind == TypeKinds.Option)
        {
            return 1;
        }
        if (ati.Kind == TypeKinds.SomeWrap && pti.Kind == TypeKinds.Option && ati.A == pti.A)
        {
            return 1;
        }
        if (ati.Kind == TypeKinds.OkWrap && pti.Kind == TypeKinds.Result && ati.A == pti.A)
        {
            return 1;
        }
        if (ati.Kind == TypeKinds.ErrWrap && pti.Kind == TypeKinds.Result && ati.A == pti.B)
        {
            return 1;
        }

        return -1;
    }

    private static int ClassifyByValueConversionWithCtx(
        int argExprId,
        int argTypeId,
        int paramTypeId,
        in FuncLowerCtx fctx,
        in Interner names,
        in BinderCtx bctx,
        in AstArena ast,
        in TokenArena ta,
        in TypeTable types)
    {
        int basic = ClassifyByValueConversion(argExprId, argTypeId, paramTypeId, in ast, in ta, in types);
        if (basic >= 0 || argExprId < 0) return basic;

        int curOwner = fctx.EnclosingOwnerDeclId;
        if (types.Items[paramTypeId].Kind == TypeKinds.Enum &&
            argTypeId != TypeIds.Char && types.Items[argTypeId].Kind != TypeKinds.Enum &&
            (types.IsInteger(argTypeId) || types.IsFloat(argTypeId)) &&
            IsZeroNumericConstExpr(argExprId, curOwner, in fctx, in ast, in ta, in names, in bctx, in types))
        {
            return 1;
        }
        if (argTypeId == TypeIds.I32 &&
            TryEvalTypedIntConstExpr(argExprId, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out int cTid32, out long iv) &&
            cTid32 == TypeIds.I32 &&
            FitsInt32ValueInTarget(iv, paramTypeId))
        {
            return 1;
        }
        if (argTypeId == TypeIds.I64 && paramTypeId == TypeIds.U64 &&
            TryEvalTypedIntConstExpr(argExprId, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out int cTid64, out long lv) &&
            cTid64 == TypeIds.I64 &&
            lv >= 0)
        {
            return 1;
        }
        return -1;
    }

    private static bool FitsInt32ValueInTarget(long v, int targetTypeId)
    {
        switch (targetTypeId)
        {
            case TypeIds.I8: return v >= -128 && v <= 127;
            case TypeIds.U8: return v >= 0 && v <= 255;
            case TypeIds.I16: return v >= -32768 && v <= 32767;
            case TypeIds.U16: return v >= 0 && v <= 65535;
            case TypeIds.I32:
            case TypeIds.NInt: return true;
            case TypeIds.U32:
            case TypeIds.U64:
            case TypeIds.NUInt: return v >= 0;
            default: return false;
        }
    }

    private static bool CanImplicitNumericWiden(int src, int dst)
    {
        if (src == dst) return false;
        switch (src)
        {
            case TypeIds.I8:
                return dst == TypeIds.I16 || dst == TypeIds.I32 || dst == TypeIds.I64 || dst == TypeIds.NInt || dst == TypeIds.F32 || dst == TypeIds.F64;
            case TypeIds.U8:
                return dst == TypeIds.I16 || dst == TypeIds.U16 || dst == TypeIds.I32 || dst == TypeIds.U32 || dst == TypeIds.I64 || dst == TypeIds.U64 || dst == TypeIds.NInt || dst == TypeIds.NUInt || dst == TypeIds.F32 || dst == TypeIds.F64;
            case TypeIds.I16:
                return dst == TypeIds.I32 || dst == TypeIds.I64 || dst == TypeIds.NInt || dst == TypeIds.F32 || dst == TypeIds.F64;
            case TypeIds.U16:
            case TypeIds.Char:
                return dst == TypeIds.U16 || dst == TypeIds.I32 || dst == TypeIds.U32 || dst == TypeIds.I64 || dst == TypeIds.U64 || dst == TypeIds.NInt || dst == TypeIds.NUInt || dst == TypeIds.F32 || dst == TypeIds.F64;
            case TypeIds.I32:
                return dst == TypeIds.I64 || dst == TypeIds.NInt || dst == TypeIds.F32 || dst == TypeIds.F64;
            case TypeIds.U32:
                return dst == TypeIds.I64 || dst == TypeIds.U64 || dst == TypeIds.NUInt || dst == TypeIds.F32 || dst == TypeIds.F64;
            case TypeIds.I64:
            case TypeIds.U64:
                return dst == TypeIds.F32 || dst == TypeIds.F64;
            case TypeIds.NInt:
                return dst == TypeIds.I64 || dst == TypeIds.F32 || dst == TypeIds.F64;
            case TypeIds.NUInt:
                return dst == TypeIds.U64 || dst == TypeIds.F32 || dst == TypeIds.F64;
            case TypeIds.F32:
                return dst == TypeIds.F64;
            default:
                return false;
        }
    }

    private static bool FitsConstantIntSimple(int exprId, int argTypeId, int targetTypeId, in AstArena ast, in TokenArena ta, in TypeTable types)
    {
        if (types.Items[targetTypeId].Kind == TypeKinds.Enum)
        {
            AstNode en = ast.Nodes[exprId];
            if (en.Kind == AstKind.ExprIntLit) return ta.Tokens[en.A].IntVal == 0;
            if (en.Kind == AstKind.ExprFloatLit) return IsZeroFloatLitText(ta.GetLit(ta.Tokens[en.A].AuxId));
            return false;
        }

        if (argTypeId == TypeIds.I32)
        {
            AstNode n = ast.Nodes[exprId];
            if (n.Kind == AstKind.ExprIntLit)
            {
                Token lit = ta.Tokens[n.A];
                if (lit.Kind != TokKind.IntLit || (ulong)lit.IntVal > 2147483647UL) return false;
                return FitsInt32ValueInTarget(lit.IntVal, targetTypeId);
            }
            if (n.Kind == AstKind.ExprUnary && (TokKind)n.A == TokKind.Minus && ast.Nodes[n.B].Kind == AstKind.ExprIntLit)
            {
                Token lit = ta.Tokens[ast.Nodes[n.B].A];
                if (!((lit.Kind == TokKind.IntLit && (ulong)lit.IntVal <= 2147483647UL) || (lit.AuxId == 0 && (ulong)lit.IntVal == 2147483648UL))) return false;
                return FitsInt32ValueInTarget(-lit.IntVal, targetTypeId);
            }
            if (Parser.TryEvalSimpleIntExpr(in ast, in ta, exprId, out long v) && v >= -2147483648L && v <= 2147483647L)
            {
                return FitsInt32ValueInTarget(v, targetTypeId);
            }
            return false;
        }

        if (argTypeId == TypeIds.I64 && targetTypeId == TypeIds.U64)
        {
            AstNode ln = ast.Nodes[exprId];
            if (ln.Kind == AstKind.ExprIntLit)
            {
                Token lit = ta.Tokens[ln.A];
                return lit.Kind != TokKind.ULongLit && lit.IntVal >= 0;
            }
            return Parser.TryEvalSimpleIntExpr(in ast, in ta, exprId, out long lv) && lv >= 0;
        }

        return false;
    }

    private static int InferCallArgActualType(
        in AstNode cArg,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags)
    {
        if (CallArgBits.Mode(in cArg) == PassMode.Out)
        {
            if (IsDiscardOutArgument(in cArg, in fctx, in ast, in names) || cArg.C == -1) return -1;
            if (cArg.C >= 0)
            {
                return DeclBinder.ResolveTypeNode(cArg.C, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
            }
        }
        return InferExprType(cArg.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
    }

    private static bool IsOutArgCompatibleWithType(
        in AstNode cArg,
        int paramTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags)
    {
        int declaredNode = DeclaredOutArgumentTypeNode(in cArg);
        if (declaredNode < 0 && (IsDiscardOutArgument(in cArg, in fctx, in ast, in names) || cArg.C == -1)) return true;
        if (declaredNode >= 0)
        {
            int declTid = DeclBinder.ResolveTypeNode(declaredNode, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
            return declTid == paramTypeId;
        }
        int exprTid = InferExprType(cArg.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        return exprTid == paramTypeId;
    }

    private static int TryInferTypeParamFromNode(
        int typeNodeId,
        int actualTypeId,
        int tpNameId,
        in AstArena ast,
        in BinderCtx bctx,
        in TypeTable types)
    {
        if (typeNodeId < 0 || actualTypeId < 0 || actualTypeId == TypeIds.Void || actualTypeId == TypeIds.Error ||
            actualTypeId == TypeIds.Utf8Lines || actualTypeId == TypeIds.Utf8ArgEnum)
        {
            return -1;
        }

        AstNode n = ast.Nodes[typeNodeId];
        TypeInfo ati = types.Items[actualTypeId];

        if (n.Kind == AstKind.TypeNullable)
        {
            if (ati.Kind == TypeKinds.Option)
            {
                return TryInferTypeParamFromNode(n.A, ati.A, tpNameId, in ast, in bctx, in types);
            }
            return -1;
        }

        if (n.Kind == AstKind.TypeNamed)
        {
            bool isUnqualified = n.D < 0 || ast.TypeRefs[n.D].PrefixNsId < 0;
            if (n.C == 0 && isUnqualified && n.A == tpNameId)
            {
                return actualTypeId;
            }
            if (n.C == 1)
            {
                if (n.A == bctx.IdSpan && ati.Kind == TypeKinds.Span)
                {
                    return TryInferTypeParamFromNode(ast.Extra[n.B], ati.A, tpNameId, in ast, in bctx, in types);
                }
                if (n.A == bctx.IdReadOnlySpan && (ati.Kind == TypeKinds.ReadOnlySpan || ati.Kind == TypeKinds.Span))
                {
                    return TryInferTypeParamFromNode(ast.Extra[n.B], ati.A, tpNameId, in ast, in bctx, in types);
                }
                if (n.A == bctx.IdVec && ati.Kind == TypeKinds.Vec)
                {
                    return TryInferTypeParamFromNode(ast.Extra[n.B], ati.A, tpNameId, in ast, in bctx, in types);
                }
                if (n.A == bctx.IdOption && ati.Kind == TypeKinds.Option)
                {
                    return TryInferTypeParamFromNode(ast.Extra[n.B], ati.A, tpNameId, in ast, in bctx, in types);
                }
                if (n.A == bctx.IdSome && ati.Kind == TypeKinds.SomeWrap)
                {
                    return TryInferTypeParamFromNode(ast.Extra[n.B], ati.A, tpNameId, in ast, in bctx, in types);
                }
                if (n.A == bctx.IdOk && ati.Kind == TypeKinds.OkWrap)
                {
                    return TryInferTypeParamFromNode(ast.Extra[n.B], ati.A, tpNameId, in ast, in bctx, in types);
                }
                if (n.A == bctx.IdErr && ati.Kind == TypeKinds.ErrWrap)
                {
                    return TryInferTypeParamFromNode(ast.Extra[n.B], ati.A, tpNameId, in ast, in bctx, in types);
                }
                if (n.A == bctx.IdOptionRef && ati.Kind == TypeKinds.OptionRef)
                {
                    return TryInferTypeParamFromNode(ast.Extra[n.B], ati.A, tpNameId, in ast, in bctx, in types);
                }
                if (n.A == bctx.IdOptionMut && ati.Kind == TypeKinds.OptionMut)
                {
                    return TryInferTypeParamFromNode(ast.Extra[n.B], ati.A, tpNameId, in ast, in bctx, in types);
                }
            }
            if (n.C == 2 && n.A == bctx.IdResult && ati.Kind == TypeKinds.Result)
            {
                int r0 = TryInferTypeParamFromNode(ast.Extra[n.B + 0], ati.A, tpNameId, in ast, in bctx, in types);
                if (r0 >= 0) return r0;
                return TryInferTypeParamFromNode(ast.Extra[n.B + 1], ati.B, tpNameId, in ast, in bctx, in types);
            }
            if ((ati.Kind == TypeKinds.Class || ati.Kind == TypeKinds.Struct) &&
                ast.Types[ati.A].NameId == n.A &&
                ast.Types[ati.A].TypeParamCount == n.C)
            {
                for (int k = 0; k < n.C; k++)
                {
                    int rk = TryInferTypeParamFromNode(ast.Extra[n.B + k], types.TypeArgs[ati.B + k], tpNameId, in ast, in bctx, in types);
                    if (rk >= 0) return rk;
                }
            }
        }

        return -1;
    }

    // A built-in readonly struct member with value-based LLVM lowering still
    // borrows its source receiver while its arguments are being evaluated.
    // Capture once, retaining the original place only for ownership checking.
    private static int LowerBorrowedIntrinsicReceiver(int receiver, int receiverType, ref FuncLowerCtx fctx,
        in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx, ref TypeTable types,
        ref MirModuleArena mir, ref DiagnosticBag diags, out int receiverLoan)
    {
        int tokIdx = ast.Nodes[receiver].TokIdx;
        int input = LowerBorrowWindowInput(receiver, receiverType, snapshotIndex: true, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int place);
        int snapshot = MaterializeByValueCallArgIfNeeded(input, true, tokIdx, ref fctx, in types, ref mir);
        int windowFlag = 0;
        if (!types.IsCopy(receiverType, in ast) && place >= 0 && mir.Places[place].ProjCount == 0)
        {
            MirLocal loc = fctx.Locals[mir.Places[place].LocalId];
            if ((loc.Flags & MirLocalFlags.IsRefLocal) == 0 && loc.Mode == PassMode.ByValue)
                windowFlag = MirLocalFlags.IsMovedReceiverWindow;
        }
        receiverLoan = BeginBorrowWindow(place, tokIdx, windowFlag, ref fctx, in mir);
        return snapshot;
    }

    private static int LowerOptionAsRef(int recvExprId, int optTypeId, int innerTypeId, int tokIdx,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx,
        ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags)
    {
        if (types.IsLinear(optTypeId, in ast)) diags.ReportTok(VibCodes.LinearViolation, ta.Tokens[tokIdx], "Option.AsRef is banned on linear resources."u8);
        int oPl = LowerPlaceOrTemp(recvExprId, optTypeId, isMut: false, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, requireVariable: true);
        var pls = new Vec<int>(1);
        pls.Push(oPl);
        int refT = types.MakeOptionRef(innerTypeId);
        int dstTmp = fctx.NewTemp(refT, tokIdx, ref mir);
        int dstPl = mir.AddPlaceLocal(dstTmp, refT);
        fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, refT, (int)MirIntrinsic.OptionAsRef, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, refT, tokIdx));
    }

    private static bool TryLowerOptionIntrinsicCall(
        int recvExprId,
        bool recvDeclares,
        int optTypeId,
        int innerTypeId,
        int mNameId,
        int argStart,
        int argCount,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        out int resultOp)
    {
        resultOp = -1;
        Token tok = ta.Tokens[tokIdx];
        bool isLin = types.IsLinear(optTypeId, in ast);
        if (Bytes.Eq(names.Text(mNameId), "Unwrap"u8) && argCount == 0)
        {
            int oOp = LowerExprAsOperand(recvExprId, optTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var ops = new Vec<int>(1);
            ops.Push(oOp);
            int dstTmp = fctx.NewTemp(innerTypeId, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, innerTypeId);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, innerTypeId, (int)MirIntrinsic.OptionUnwrap, mir.PushIdList(ops.AsReadOnlySpan()), 1, 0, tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, innerTypeId, tokIdx));
            return true;
        }
        if (mNameId == bctx.IdExpect && argCount == 1)
        {
            AstNode cArg0 = ast.Nodes[ast.Extra[argStart]];
            if (CallArgBits.Mode(in cArg0) != PassMode.ByValue ||
                !CheckSingleNamedArg(in cArg0, "message"u8, in names))
            {
                return false;
            }
            // The receiver's out and pattern variables stay in scope in the message (N110).
            EnterReceiverScope(recvExprId, recvDeclares, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            int messageType = InferExprType(cArg0.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            fctx.LeaveSpeculativeInfer();
            if (messageType != TypeIds.Str) return false;
            int oOp = LowerBorrowedIntrinsicReceiver(recvExprId, optTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int receiverLoan);
            int msgOp = LowerExprAsOperand(cArg0.B, TypeIds.Str, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var ops = new Vec<int>(2);
            ops.Push(oOp);
            ops.Push(msgOp);
            int dstTmp = fctx.NewTemp(innerTypeId, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, innerTypeId);
            EndBorrowWindow(receiverLoan, tokIdx, ref fctx);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, innerTypeId, (int)MirIntrinsic.OptionExpect, mir.PushIdList(ops.AsReadOnlySpan()), 2, 0, tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, innerTypeId, tokIdx));
            return true;
        }
        if (mNameId == bctx.IdUnwrapOrDefault && argCount == 0)
        {
            if (isLin)
            {
                diags.ReportTok(VibCodes.LinearViolation, tok, "'Option.UnwrapOrDefault' is banned on linear IDisposable resources."u8);
            }
            else if (!types.IsZeroSafe(innerTypeId, in ast))
            {
                diags.ReportTok(VibCodes.NullOrZeroUnsafe, tok, "'Option.UnwrapOrDefault' requires a zero-safe payload type."u8);
            }
            int oOp = LowerExprAsOperand(recvExprId, optTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int fbOp = mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, innerTypeId, tokIdx));
            var ops = new Vec<int>(2);
            ops.Push(oOp);
            ops.Push(fbOp);
            int dstTmp = fctx.NewTemp(innerTypeId, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, innerTypeId);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, innerTypeId, (int)MirIntrinsic.OptionUnwrapOr, mir.PushIdList(ops.AsReadOnlySpan()), 2, 0, tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, innerTypeId, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "UnwrapOr"u8) && argCount == 1)
        {
            AstNode cArg0 = ast.Nodes[ast.Extra[argStart]];
            if (CallArgBits.Mode(in cArg0) != PassMode.ByValue || !CheckSingleNamedArg(in cArg0, "fallback"u8, in names)) return false;
            if (isLin) diags.ReportTok(VibCodes.LinearViolation, tok, "Option.UnwrapOr is banned on linear resources."u8);
            int oOp = LowerBorrowedIntrinsicReceiver(recvExprId, optTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int receiverLoan);
            int fbOp = LowerExprAsOperand(cArg0.B, innerTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var ops = new Vec<int>(2);
            ops.Push(oOp);
            ops.Push(fbOp);
            int dstTmp = fctx.NewTemp(innerTypeId, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, innerTypeId);
            EndBorrowWindow(receiverLoan, tokIdx, ref fctx);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, innerTypeId, (int)MirIntrinsic.OptionUnwrapOr, mir.PushIdList(ops.AsReadOnlySpan()), 2, 0, tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, innerTypeId, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "AsRef"u8) && argCount == 0)
        {
            resultOp = LowerOptionAsRef(recvExprId, optTypeId, innerTypeId, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "AsMut"u8) && argCount == 0)
        {
            if (!SatisfiesClassConstraint(innerTypeId, in fctx, in ast, in types))
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "'Option<T>.AsMut()' requires 'T' to satisfy the 'class' reference-type constraint."u8);
            }
            if (isLin) diags.ReportTok(VibCodes.LinearViolation, tok, "Option.AsMut is banned on linear resources."u8);
            int oPl = LowerPlace(recvExprId, isMut: true, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var pls = new Vec<int>(1);
            pls.Push(oPl);
            int mutT = types.MakeOptionMut(innerTypeId);
            int dstTmp = fctx.NewTemp(mutT, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, mutT);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, mutT, (int)MirIntrinsic.OptionAsMut, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, mutT, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "Take"u8) && argCount == 0)
        {
            if (isLin) diags.ReportTok(VibCodes.LinearViolation, tok, "Option.Take is banned on linear resources."u8);
            int oPl = LowerPlace(recvExprId, isMut: true, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var pls = new Vec<int>(1);
            pls.Push(oPl);
            int dstTmp = fctx.NewTemp(optTypeId, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, optTypeId);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, optTypeId, (int)MirIntrinsic.OptionTake, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, optTypeId, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "Replace"u8) && argCount == 1)
        {
            AstNode cArg0 = ast.Nodes[ast.Extra[argStart]];
            if (CallArgBits.Mode(in cArg0) != PassMode.ByValue || !CheckSingleNamedArg(in cArg0, "value"u8, in names)) return false;
            if (isLin) diags.ReportTok(VibCodes.LinearViolation, tok, "Option.Replace is banned on linear resources."u8);
            int oPl = LowerPlace(recvExprId, isMut: true, isTwoPhase: true, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            oPl = ReserveReceiverPlace(oPl, optTypeId, isMut: true, isTwoPhase: true, tokIdx, ref fctx, ref mir);
            int repOp = LowerExprAsOperand(cArg0.B, optTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var ops = new Vec<int>(1);
            ops.Push(repOp);
            var pls = new Vec<int>(1);
            pls.Push(oPl);
            int dstTmp = fctx.NewTemp(optTypeId, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, optTypeId);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 2, optTypeId, (int)MirIntrinsic.OptionReplace, mir.PushIdList(ops.AsReadOnlySpan()), 1, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, optTypeId, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "UnwrapMut"u8) && argCount == 0)
        {
            if (isLin) diags.ReportTok(VibCodes.LinearViolation, tok, "Option.UnwrapMut is banned on linear resources."u8);
            int oPl = LowerPlaceOrTemp(recvExprId, optTypeId, isMut: true, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int refTmp = fctx.NewTempRef(innerTypeId, isMut: true, tokIdx);
            var pls = new Vec<int>(1);
            pls.Push(oPl);
            fctx.Emit(new MirInst(MirOp.Intrinsic, -1, refTmp, 1, innerTypeId, (int)MirIntrinsic.OptionUnwrapMut, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            var deref = new Vec<MirProj>(1);
            deref.Push(new MirProj(MirProjKinds.Deref, 0, innerTypeId, -1, 0));
            int derefPl = mir.AddPlace(refTmp, deref.AsReadOnlySpan(), innerTypeId);
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, derefPl, 0, innerTypeId, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "IsNone"u8))
        {
            diags.ReportTok(VibCodes.Unsupported, tok, "'Option.IsNone(out ...)' must be used directly as an 'if' guard condition."u8);
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, 0, TypeIds.Bool, tokIdx));
            return true;
        }
        return false;
    }

    private static bool TryLowerOptionMutIntrinsicCall(
        int recvExprId,
        int optMutTypeId,
        int innerTypeId,
        int mNameId,
        int argStart,
        int argCount,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        out int resultOp)
    {
        resultOp = -1;
        int optT = types.MakeOption(innerTypeId);
        if (Bytes.Eq(names.Text(mNameId), "Set"u8) && argCount == 1)
        {
            AstNode cArg0 = ast.Nodes[ast.Extra[argStart]];
            if (CallArgBits.Mode(in cArg0) != PassMode.ByValue || !CheckSingleNamedArg(in cArg0, "value"u8, in names)) return false;
            int curPl = LowerPlaceOrTemp(recvExprId, optMutTypeId, isMut: true, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int valOp = LowerExprAsOperand(cArg0.B, optT, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var ops = new Vec<int>(1);
            ops.Push(valOp);
            var pls = new Vec<int>(1);
            pls.Push(curPl);
            fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 0, TypeIds.Void, (int)MirIntrinsic.OptionMutSet, mir.PushIdList(ops.AsReadOnlySpan()), 1, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "Take"u8) && argCount == 0)
        {
            int curPl = LowerPlaceOrTemp(recvExprId, optMutTypeId, isMut: true, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var pls = new Vec<int>(1);
            pls.Push(curPl);
            int dstTmp = fctx.NewTemp(optT, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, optT);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, optT, (int)MirIntrinsic.OptionMutTake, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, optT, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "Replace"u8) && argCount == 1)
        {
            AstNode cArg0 = ast.Nodes[ast.Extra[argStart]];
            if (CallArgBits.Mode(in cArg0) != PassMode.ByValue || !CheckSingleNamedArg(in cArg0, "value"u8, in names)) return false;
            int curPl = LowerPlaceOrTemp(recvExprId, optMutTypeId, isMut: true, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int valOp = LowerExprAsOperand(cArg0.B, optT, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var ops = new Vec<int>(1);
            ops.Push(valOp);
            var pls = new Vec<int>(1);
            pls.Push(curPl);
            int dstTmp = fctx.NewTemp(optT, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, optT);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, optT, (int)MirIntrinsic.OptionMutReplace, mir.PushIdList(ops.AsReadOnlySpan()), 1, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, optT, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "AsRef"u8) && argCount == 0)
        {
            int curPl = LowerPlaceOrTemp(recvExprId, optMutTypeId, isMut: false, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var pls = new Vec<int>(1);
            pls.Push(curPl);
            int refT = types.MakeOptionRef(innerTypeId);
            int dstTmp = fctx.NewTemp(refT, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, refT);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, refT, (int)MirIntrinsic.OptionMutAsRef, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, refT, tokIdx));
            return true;
        }
        return false;
    }

    private static bool TryLowerResultIntrinsicCall(
        int recvExprId,
        bool recvDeclares,
        int resTypeId,
        int okTypeId,
        int errTypeId,
        int mNameId,
        int argStart,
        int argCount,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        out int resultOp)
    {
        resultOp = -1;
        Token tok = ta.Tokens[tokIdx];
        if (Bytes.Eq(names.Text(mNameId), "Unwrap"u8) && argCount == 0)
        {
            int rOp = LowerExprAsOperand(recvExprId, resTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var ops = new Vec<int>(1);
            ops.Push(rOp);
            int dstTmp = fctx.NewTemp(okTypeId, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, okTypeId);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, okTypeId, (int)MirIntrinsic.ResultUnwrap, mir.PushIdList(ops.AsReadOnlySpan()), 1, 0, tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, okTypeId, tokIdx));
            return true;
        }
        if (mNameId == bctx.IdExpect && argCount == 1)
        {
            AstNode cArg0 = ast.Nodes[ast.Extra[argStart]];
            if (CallArgBits.Mode(in cArg0) != PassMode.ByValue ||
                !CheckSingleNamedArg(in cArg0, "message"u8, in names))
            {
                return false;
            }
            // The receiver's out and pattern variables stay in scope in the message (N110).
            EnterReceiverScope(recvExprId, recvDeclares, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            int messageType = InferExprType(cArg0.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            fctx.LeaveSpeculativeInfer();
            if (messageType != TypeIds.Str) return false;
            int rOp = LowerBorrowedIntrinsicReceiver(recvExprId, resTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int receiverLoan);
            int msgOp = LowerExprAsOperand(cArg0.B, TypeIds.Str, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var ops = new Vec<int>(2);
            ops.Push(rOp);
            ops.Push(msgOp);
            int dstTmp = fctx.NewTemp(okTypeId, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, okTypeId);
            EndBorrowWindow(receiverLoan, tokIdx, ref fctx);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, okTypeId, (int)MirIntrinsic.ResultExpect, mir.PushIdList(ops.AsReadOnlySpan()), 2, 0, tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, okTypeId, tokIdx));
            return true;
        }
        if (mNameId == bctx.IdUnwrapOrDefault && argCount == 0)
        {
            if (types.IsLinear(resTypeId, in ast) || types.IsLinear(okTypeId, in ast) || types.IsLinear(errTypeId, in ast))
            {
                diags.ReportTok(VibCodes.LinearViolation, tok, "'Result.UnwrapOrDefault' is banned on linear IDisposable resources."u8);
            }
            else if (!types.IsZeroSafe(okTypeId, in ast))
            {
                diags.ReportTok(VibCodes.NullOrZeroUnsafe, tok, "'Result.UnwrapOrDefault' requires a zero-safe Ok payload type."u8);
            }
            int rOp = LowerExprAsOperand(recvExprId, resTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int fbOp = mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, okTypeId, tokIdx));
            var ops = new Vec<int>(2);
            ops.Push(rOp);
            ops.Push(fbOp);
            int dstTmp = fctx.NewTemp(okTypeId, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, okTypeId);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, okTypeId, (int)MirIntrinsic.ResultUnwrapOr, mir.PushIdList(ops.AsReadOnlySpan()), 2, 0, tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, okTypeId, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "UnwrapOr"u8) && argCount == 1)
        {
            AstNode cArg0 = ast.Nodes[ast.Extra[argStart]];
            if (CallArgBits.Mode(in cArg0) != PassMode.ByValue || !CheckSingleNamedArg(in cArg0, "fallback"u8, in names)) return false;
            if (types.IsLinear(okTypeId, in ast) || types.IsLinear(errTypeId, in ast))
            {
                diags.ReportTok(VibCodes.LinearViolation, tok, "Result.UnwrapOr is banned on linear resources."u8);
            }
            int rOp = LowerBorrowedIntrinsicReceiver(recvExprId, resTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int receiverLoan);
            int fbOp = LowerExprAsOperand(cArg0.B, okTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var ops = new Vec<int>(2);
            ops.Push(rOp);
            ops.Push(fbOp);
            int dstTmp = fctx.NewTemp(okTypeId, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, okTypeId);
            EndBorrowWindow(receiverLoan, tokIdx, ref fctx);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, okTypeId, (int)MirIntrinsic.ResultUnwrapOr, mir.PushIdList(ops.AsReadOnlySpan()), 2, 0, tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, okTypeId, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "IsErr"u8))
        {
            diags.ReportTok(VibCodes.Unsupported, tok, "'Result.IsErr(out ...)' must be used directly as an 'if' guard condition."u8);
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, 0, TypeIds.Bool, tokIdx));
            return true;
        }
        return false;
    }

    private static bool TryLowerVecIntrinsicCall(
        int recvExprId,
        int vecTypeId,
        int elemTypeId,
        int mNameId,
        int argStart,
        int argCount,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        out int resultOp)
    {
        resultOp = -1;
        if ((Bytes.Eq(names.Text(mNameId), "Push"u8) || mNameId == bctx.IdAdd) && argCount == 1)
        {
            AstNode cArg0 = ast.Nodes[ast.Extra[argStart]];
            if (CallArgBits.Mode(in cArg0) != PassMode.ByValue || !CheckSingleNamedArg(in cArg0, "item"u8, in names)) return false;
            int vPl = LowerPlace(recvExprId, isMut: true, isTwoPhase: true, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            vPl = ReserveReceiverPlace(vPl, vecTypeId, isMut: true, isTwoPhase: true, tokIdx, ref fctx, ref mir);
            int itemOp = LowerExprAsOperand(cArg0.B, elemTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var ops = new Vec<int>(1);
            ops.Push(itemOp);
            var pls = new Vec<int>(1);
            pls.Push(vPl);
            fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 2, TypeIds.Void, (int)MirIntrinsic.VecPush, mir.PushIdList(ops.AsReadOnlySpan()), 1, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "Pop"u8) && argCount == 0)
        {
            int vPl = LowerPlace(recvExprId, isMut: true, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var pls = new Vec<int>(1);
            pls.Push(vPl);
            int optT = types.MakeOption(elemTypeId);
            int dstTmp = fctx.NewTemp(optT, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, optT);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, optT, (int)MirIntrinsic.VecPop, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, optT, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "Clear"u8) && argCount == 0)
        {
            int vPl = LowerPlace(recvExprId, isMut: true, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var pls = new Vec<int>(1);
            pls.Push(vPl);
            fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 0, TypeIds.Void, (int)MirIntrinsic.VecClear, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
            return true;
        }
        if ((Bytes.Eq(names.Text(mNameId), "Truncate"u8) || Bytes.Eq(names.Text(mNameId), "Reserve"u8)) && argCount == 1)
        {
            bool isTrunc = Bytes.Eq(names.Text(mNameId), "Truncate"u8);
            AstNode cArg0 = ast.Nodes[ast.Extra[argStart]];
            if (CallArgBits.Mode(in cArg0) != PassMode.ByValue ||
                !CheckSingleNamedArg(in cArg0, isTrunc ? "length"u8 : "additional"u8, in names))
            {
                return false;
            }
            int vPl = LowerPlace(recvExprId, isMut: true, isTwoPhase: true, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            vPl = ReserveReceiverPlace(vPl, vecTypeId, isMut: true, isTwoPhase: true, tokIdx, ref fctx, ref mir);
            int nOp = LowerExprAsOperand(cArg0.B, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var ops = new Vec<int>(1);
            ops.Push(nOp);
            var pls = new Vec<int>(1);
            pls.Push(vPl);
            MirIntrinsic intr = isTrunc ? MirIntrinsic.VecTruncate : MirIntrinsic.VecReserve;
            fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 2, TypeIds.Void, (int)intr, mir.PushIdList(ops.AsReadOnlySpan()), 1, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "Extend"u8) && argCount == 1)
        {
            AstNode cArg0 = ast.Nodes[ast.Extra[argStart]];
            if (CallArgBits.Mode(in cArg0) != PassMode.ByValue || !CheckSingleNamedArg(in cArg0, "items"u8, in names)) return false;
            int vPl = LowerPlace(recvExprId, isMut: true, isTwoPhase: true, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            vPl = ReserveReceiverPlace(vPl, vecTypeId, isMut: true, isTwoPhase: true, tokIdx, ref fctx, ref mir);
            int roSpanT = types.MakeSpan(elemTypeId, isReadOnly: true);
            int spOp = LowerExprAsOperand(cArg0.B, roSpanT, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var ops = new Vec<int>(1);
            ops.Push(spOp);
            var pls = new Vec<int>(1);
            pls.Push(vPl);
            fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 2, TypeIds.Void, (int)MirIntrinsic.VecExtend, mir.PushIdList(ops.AsReadOnlySpan()), 1, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
            return true;
        }
        if (Bytes.Eq(names.Text(mNameId), "Resize"u8) && argCount == 2)
        {
            AstNode raw0 = ast.Nodes[ast.Extra[argStart + 0]];
            AstNode raw1 = ast.Nodes[ast.Extra[argStart + 1]];
            if (CallArgBits.Mode(in raw0) != PassMode.ByValue || CallArgBits.Mode(in raw1) != PassMode.ByValue) return false;
            if (!TryMapTwoNamedArgs(in raw0, in raw1, "length"u8, "fill"u8, in names, out int lenIdx, out _)) return false;
            int vPl = LowerPlace(recvExprId, isMut: true, isTwoPhase: true, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            vPl = ReserveReceiverPlace(vPl, vecTypeId, isMut: true, isTwoPhase: true, tokIdx, ref fctx, ref mir);
            int lenOp;
            int fillOp;
            if (lenIdx == 0)
            {
                lenOp = LowerExprAsOperand(raw0.B, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                lenOp = MaterializeByValueCallArgIfNeeded(lenOp, true, raw0.TokIdx, ref fctx, in types, ref mir);
                fillOp = LowerExprAsOperand(raw1.B, elemTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }
            else
            {
                fillOp = LowerExprAsOperand(raw0.B, elemTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                fillOp = MaterializeByValueCallArgIfNeeded(fillOp, true, raw0.TokIdx, ref fctx, in types, ref mir);
                lenOp = LowerExprAsOperand(raw1.B, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }
            var ops = new Vec<int>(2);
            ops.Push(lenOp);
            ops.Push(fillOp);
            var pls = new Vec<int>(1);
            pls.Push(vPl);
            fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 2, TypeIds.Void, (int)MirIntrinsic.VecResize, mir.PushIdList(ops.AsReadOnlySpan()), 2, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
            return true;
        }
        if ((Bytes.Eq(names.Text(mNameId), "Slice"u8) || Bytes.Eq(names.Text(mNameId), "ReadOnlySlice"u8)) && argCount == 2)
        {
            AstNode raw0 = ast.Nodes[ast.Extra[argStart + 0]];
            AstNode raw1 = ast.Nodes[ast.Extra[argStart + 1]];
            if (CallArgBits.Mode(in raw0) != PassMode.ByValue || CallArgBits.Mode(in raw1) != PassMode.ByValue) return false;
            if (!TryMapTwoNamedArgs(in raw0, in raw1, "start"u8, "length"u8, in names, out int stIdx, out _)) return false;
            bool ro = Bytes.Eq(names.Text(mNameId), "ReadOnlySlice"u8);
            int vPl = LowerPlaceOrTemp(recvExprId, vecTypeId, isMut: !ro, isTwoPhase: !ro, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            vPl = ReserveReceiverPlace(vPl, vecTypeId, isMut: !ro, isTwoPhase: !ro, tokIdx, ref fctx, ref mir);
            int stOp;
            int lnOp;
            if (stIdx == 0)
            {
                stOp = LowerExprAsOperand(raw0.B, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                stOp = MaterializeByValueCallArgIfNeeded(stOp, true, raw0.TokIdx, ref fctx, in types, ref mir);
                lnOp = LowerExprAsOperand(raw1.B, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }
            else
            {
                lnOp = LowerExprAsOperand(raw0.B, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                lnOp = MaterializeByValueCallArgIfNeeded(lnOp, true, raw0.TokIdx, ref fctx, in types, ref mir);
                stOp = LowerExprAsOperand(raw1.B, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }
            var ops = new Vec<int>(2);
            ops.Push(stOp);
            ops.Push(lnOp);
            var pls = new Vec<int>(1);
            pls.Push(vPl);
            int spT = types.MakeSpan(elemTypeId, isReadOnly: ro);
            int dstTmp = fctx.NewTemp(spT, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, spT);
            MirIntrinsic intr = ro ? MirIntrinsic.VecReadOnlySlice : MirIntrinsic.VecSliceMut;
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, ro ? 0 : 2, spT, (int)intr, mir.PushIdList(ops.AsReadOnlySpan()), 2, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, spT, tokIdx));
            return true;
        }
        if ((Bytes.Eq(names.Text(mNameId), "AsSpan"u8) || Bytes.Eq(names.Text(mNameId), "AsReadOnlySpan"u8)) && argCount == 0)
        {
            bool ro = Bytes.Eq(names.Text(mNameId), "AsReadOnlySpan"u8);
            int vPl = LowerPlaceOrTemp(recvExprId, vecTypeId, isMut: !ro, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            var pls = new Vec<int>(1);
            pls.Push(vPl);
            int spT = types.MakeSpan(elemTypeId, isReadOnly: ro);
            int dstTmp = fctx.NewTemp(spT, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, spT);
            MirIntrinsic intr = ro ? MirIntrinsic.VecAsReadOnlySpan : MirIntrinsic.VecAsSpan;
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, spT, (int)intr, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, spT, tokIdx));
            return true;
        }
        return false;
    }

    private static bool TryLowerSpanIntrinsicCall(
        int recvExprId,
        bool recvDeclares,
        int spanTypeId,
        int mNameId,
        int argStart,
        int argCount,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        out int resultOp)
    {
        resultOp = -1;
        if (Bytes.Eq(names.Text(mNameId), "Slice"u8) && (argCount == 1 || argCount == 2))
        {
            int stIdx = 0;
            if (argCount == 1)
            {
                AstNode a0 = ast.Nodes[ast.Extra[argStart]];
                if (!CheckSingleNamedArg(in a0, "start"u8, in names)) return false;
            }
            else
            {
                AstNode raw0 = ast.Nodes[ast.Extra[argStart + 0]];
                AstNode raw1 = ast.Nodes[ast.Extra[argStart + 1]];
                if (!TryMapTwoNamedArgs(in raw0, in raw1, "start"u8, "length"u8, in names, out stIdx, out _)) return false;
            }

            // One scope for the receiver and both arguments: a variable that an
            // earlier one declares stays in scope in a later one (N110).
            bool argsConvert = true;
            EnterReceiverScope(recvExprId, recvDeclares, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            for (int a = 0; a < argCount && argsConvert; a++)
            {
                AstNode ca = ast.Nodes[ast.Extra[argStart + a]];
                if (CallArgBits.Mode(in ca) != PassMode.ByValue) { argsConvert = false; break; }
                int aT = InferExprType(ca.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (ClassifyImplicitExpressionConversion(ca.B, aT, TypeIds.I32, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) < 0) argsConvert = false;
            }
            fctx.LeaveSpeculativeInfer();
            if (!argsConvert) return false;

            bool isExcl = types.Items[spanTypeId].Kind == TypeKinds.Span;
            int spPl = LowerPlaceOrTemp(recvExprId, spanTypeId, isMut: isExcl, isTwoPhase: isExcl, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            spPl = ReserveReceiverPlace(spPl, spanTypeId, isMut: isExcl, isTwoPhase: isExcl, tokIdx, ref fctx, ref mir);

            int startOp;
            int lenOp;
            if (argCount == 2)
            {
                AstNode raw0 = ast.Nodes[ast.Extra[argStart + 0]];
                AstNode raw1 = ast.Nodes[ast.Extra[argStart + 1]];
                if (stIdx == 0)
                {
                    startOp = LowerExprAsOperand(raw0.B, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    startOp = MaterializeByValueCallArgIfNeeded(startOp, true, raw0.TokIdx, ref fctx, in types, ref mir);
                    lenOp = LowerExprAsOperand(raw1.B, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                }
                else
                {
                    lenOp = LowerExprAsOperand(raw0.B, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    lenOp = MaterializeByValueCallArgIfNeeded(lenOp, true, raw0.TokIdx, ref fctx, in types, ref mir);
                    startOp = LowerExprAsOperand(raw1.B, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                }
            }
            else
            {
                startOp = LowerExprAsOperand(ast.Nodes[ast.Extra[argStart + 0]].B, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                int spRead1 = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, spPl, 0, spanTypeId, tokIdx));
                var lenArgs = new Vec<int>(1);
                lenArgs.Push(spRead1);
                int totTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
                int totPl = mir.AddPlaceLocal(totTmp, TypeIds.I32);
                fctx.Emit(new MirInst(MirOp.Intrinsic, totPl, -1, 0, TypeIds.I32, (int)MirIntrinsic.SpanLength, mir.PushIdList(lenArgs.AsReadOnlySpan()), 1, 0, tokIdx));

                int stTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
                int stPl = mir.AddPlaceLocal(stTmp, TypeIds.I32);
                fctx.Emit(new MirInst(MirOp.AssignUse, stPl, -1, 0, TypeIds.I32, startOp, 0, 0, 0, tokIdx));
                startOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, stPl, 0, TypeIds.I32, tokIdx));

                int remTmp = fctx.NewTemp(TypeIds.I32, tokIdx, ref mir);
                int remPl = mir.AddPlaceLocal(remTmp, TypeIds.I32);
                int totOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, totPl, 0, TypeIds.I32, tokIdx));
                int stOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, stPl, 0, TypeIds.I32, tokIdx));
                fctx.Emit(new MirInst(MirOp.AssignBin, remPl, -1, 0, TypeIds.I32, (int)MirBinOp.Sub, totOp, stOp, 0, tokIdx));
                lenOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, remPl, 0, TypeIds.I32, tokIdx));
            }

            int spRead2 = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, spPl, 0, spanTypeId, tokIdx));
            var ops = new Vec<int>(3);
            ops.Push(spRead2);
            ops.Push(startOp);
            ops.Push(lenOp);
            int dstTmp = fctx.NewTemp(spanTypeId, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, spanTypeId);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, isExcl ? 2 : 0, spanTypeId, (int)MirIntrinsic.SpanSlice, mir.PushIdList(ops.AsReadOnlySpan()), 3, 0, tokIdx));
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, spanTypeId, tokIdx));
            return true;
        }
        return false;
    }

    private static int LowerNewAsOperand(
        in AstNode n,
        int expectedTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int tokIdx = n.TokIdx;
        Token tok = ta.Tokens[tokIdx];
        int targetType = n.A >= 0
            ? DeclBinder.ResolveTypeNode(n.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags)
            : expectedTypeId;
        DeclBinder.DrainConcreteTypeQueue(in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);

        if (targetType < 0 || targetType == TypeIds.Error)
        {
            if (n.A < 0)
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "Target-typed 'new(...)' requires a known target type in Vibranium."u8);
            }
            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
        }

        TypeInfo ti = types.Items[targetType];
        int argCount = n.C;

        // (Parity-B) `new T()` on unconstrained / non-zero-safe generic type parameter -> `VIB008`
        if (ti.Kind == TypeKinds.TypeParam && argCount == 0)
        {
            if (!types.IsZeroSafe(targetType, in ast))
            {
                diags.ReportTok(VibCodes.NullOrZeroUnsafe, tok, "Parameterless zero-initialization 'new T()' of non-zero-safe type parameter is banned in Vibranium."u8);
            }
            return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, targetType, tokIdx));
        }

        // Closed foreach view enumerators (`Utf8Lines`, `Utf8ArgEnumerator`)
        if (ti.Kind == TypeKinds.Utf8Lines)
        {
            diags.ReportTok(VibCodes.Unsupported, tok, "Direct construction of 'Utf8Lines' is banned; use '.Lines()'."u8);
            return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, targetType, tokIdx));
        }
        if (ti.Kind == TypeKinds.Utf8ArgEnum)
        {
            int curOwner = ast.Funcs[fctx.FuncDeclId].OwnerDeclId;
            bool inStdUnit = curOwner >= 0 && ast.Types[curOwner].UnitKind == UnitKinds.Std;
            bool allowedViewReturn = (inStdUnit || (fctx.ReturnTypeId == TypeIds.Utf8ArgEnum && !fctx.ForbidDirectUtf8ArgEnumNew)) &&
                                     expectedTypeId == TypeIds.Utf8ArgEnum;
            if (allowedViewReturn && argCount == 1)
            {
                int roSpanU8 = types.MakeSpan(TypeIds.U8, isReadOnly: true);
                AstNode a0 = ast.Nodes[ast.Extra[n.B]];
                int a0T = InferExprType(a0.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (CallArgBits.Mode(in a0) == PassMode.ByValue &&
                    CheckSingleNamedArg(in a0, "nulTerminatedItems"u8, in names) &&
                    ClassifyImplicitExpressionConversion(a0.B, a0T, roSpanU8, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) >= 0)
                {
                    int spPl = LowerPlaceOrTemp(a0.B, roSpanU8, isMut: false, isTwoPhase: false, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    var pls = new Vec<int>(1);
                    pls.Push(spPl);
                    int dstTmp = fctx.NewTemp(TypeIds.Utf8ArgEnum, tokIdx, ref mir);
                    int dstPl = mir.AddPlaceLocal(dstTmp, TypeIds.Utf8ArgEnum);
                    fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, TypeIds.Utf8ArgEnum, (int)MirIntrinsic.Utf8ViewFromSpan, 0, 0, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
                    return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, TypeIds.Utf8ArgEnum, tokIdx));
                }
            }
            diags.ReportTok(VibCodes.Unsupported, tok, "Direct construction of 'Utf8ArgEnumerator' is only allowed as the return value of a 'Utf8ArgEnumerator' helper method."u8);
            return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, targetType, tokIdx));
        }

        // `new Vec<T>()` or `new Vec<T>(cap)`
        if (ti.Kind == TypeKinds.Vec)
        {
            if (argCount == 0)
            {
                return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, targetType, tokIdx));
            }
            if (argCount == 1)
            {
                AstNode a0 = ast.Nodes[ast.Extra[n.B]];
                int a0T = InferExprType(a0.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                if (CallArgBits.Mode(in a0) == PassMode.ByValue &&
                    CheckSingleNamedArg(in a0, "capacity"u8, in names) &&
                    ClassifyImplicitExpressionConversion(a0.B, a0T, TypeIds.I32, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) >= 0)
                {
                    int capOp = LowerExprAsOperand(a0.B, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    var ops = new Vec<int>(1);
                    ops.Push(capOp);
                    int dstTmp = fctx.NewTemp(targetType, tokIdx, ref mir);
                    int dstPl = mir.AddPlaceLocal(dstTmp, targetType);
                    fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, targetType, (int)MirIntrinsic.VecNewWithCapacity, mir.PushIdList(ops.AsReadOnlySpan()), 1, 0, tokIdx));
                    return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, targetType, tokIdx));
                }
            }
            diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported Vec<T> constructor arguments in Vibranium."u8);
            return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, targetType, tokIdx));
        }

        // `new Some<T>(v)`, `new Ok<T>(v)`, `new Err<E>(e)`, `new Option<T>(...)`, `new Result<T, E>(...)`
        if (ti.Kind == TypeKinds.SomeWrap && argCount == 1)
        {
            AstNode a0 = ast.Nodes[ast.Extra[n.B]];
            if (CallArgBits.Mode(in a0) == PassMode.ByValue && CheckSingleNamedArg(in a0, "value"u8, in names))
            {
                int vOp = LowerExprAsOperand(a0.B, ti.A, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                int tmp = fctx.NewTemp(targetType, tokIdx, ref mir);
                int pl = mir.AddPlaceLocal(tmp, targetType);
                fctx.Emit(new MirInst(MirOp.MakeSomeWrap, pl, -1, 0, ti.A, vOp, 0, 0, 0, tokIdx));
                return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, targetType, tokIdx));
            }
        }
        if (ti.Kind == TypeKinds.OkWrap && argCount == 1)
        {
            AstNode a0 = ast.Nodes[ast.Extra[n.B]];
            if (CallArgBits.Mode(in a0) == PassMode.ByValue && CheckSingleNamedArg(in a0, "value"u8, in names))
            {
                int vOp = LowerExprAsOperand(a0.B, ti.A, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                int tmp = fctx.NewTemp(targetType, tokIdx, ref mir);
                int pl = mir.AddPlaceLocal(tmp, targetType);
                fctx.Emit(new MirInst(MirOp.MakeOkWrap, pl, -1, 0, ti.A, vOp, 0, 0, 0, tokIdx));
                return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, targetType, tokIdx));
            }
        }
        if (ti.Kind == TypeKinds.ErrWrap && argCount == 1)
        {
            AstNode a0 = ast.Nodes[ast.Extra[n.B]];
            if (CallArgBits.Mode(in a0) == PassMode.ByValue && CheckSingleNamedArg(in a0, "error"u8, in names))
            {
                if (types.IsLinear(ti.A, in ast))
                {
                    diags.ReportTok(VibCodes.LinearViolation, tok, "Linear IDisposable resource cannot be wrapped in 'Err<E>'."u8);
                }
                int eOp = LowerExprAsOperand(a0.B, ti.A, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                int tmp = fctx.NewTemp(targetType, tokIdx, ref mir);
                int pl = mir.AddPlaceLocal(tmp, targetType);
                fctx.Emit(new MirInst(MirOp.MakeErrWrap, pl, -1, 0, ti.A, eOp, 0, 0, 0, tokIdx));
                return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, targetType, tokIdx));
            }
        }
        if (ti.Kind == TypeKinds.Option)
        {
            if (argCount == 0)
            {
                if (!types.IsZeroSafe(targetType, in ast))
                {
                    diags.ReportTok(VibCodes.NullOrZeroUnsafe, tok, "Parameterless zero-initialization of non-zero-safe Option<T> is banned in Vibranium."u8);
                }
                return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, targetType, tokIdx));
            }
            if (argCount == 1)
            {
                AstNode a0 = ast.Nodes[ast.Extra[n.B]];
                if (CallArgBits.Mode(in a0) == PassMode.ByValue && CallArgBits.NameId(in a0) < 0)
                {
                    int dBefore = diags.Items.Count;
                    int innerOp = LowerExprAsOperand(a0.B, targetType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    return ConvertOperandIfNeeded(innerOp, targetType, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, a0.B, diags.Items.Count > dBefore);
                }
            }
        }
        if (ti.Kind == TypeKinds.Result && argCount == 1)
        {
            AstNode a0 = ast.Nodes[ast.Extra[n.B]];
            if (CallArgBits.Mode(in a0) == PassMode.ByValue && CallArgBits.NameId(in a0) < 0)
            {
                int dBefore = diags.Items.Count;
                int innerOp = LowerExprAsOperand(a0.B, targetType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                return ConvertOperandIfNeeded(innerOp, targetType, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, a0.B, diags.Items.Count > dBefore);
            }
        }
        if (ti.Kind == TypeKinds.OptionRef || ti.Kind == TypeKinds.OptionMut)
        {
            diags.ReportTok(VibCodes.Unsupported, tok, "Direct call to internal union protocol constructor on OptionRef/OptionMut is banned."u8);
            return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, targetType, tokIdx));
        }
        if (targetType == TypeIds.NoneUnit && argCount == 0)
        {
            return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, TypeIds.NoneUnit, tokIdx));
        }

        // User struct or class constructor with full C# type-directed overload resolution
        if (ti.Kind == TypeKinds.Class || ti.Kind == TypeKinds.Struct)
        {
            TypeDecl td = ast.Types[ti.A];
            var ctorCands = new Vec<int>();
            CollectTypeMethodCandidates(ti.A, -1, allowInstance: true, allowStatic: false, isCtor: true, ref fctx, in ast, in bctx, ref ctorCands);
            int ctorId = ResolveBestOverload(ctorCands.AsReadOnlySpan(), targetType, -1, 0, 0, n.B, argCount, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out bool ctorAmb, out _);
            if (ctorAmb)
            {
                diags.ReportTok(VibCodes.Unsupported, tok, "Ambiguous constructor invocation in Vibranium."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, targetType, tokIdx));
            }
            if (ctorId >= 0)
            {
                return EmitResolvedUserCall(ctorId, targetType, -1, 0, 0, n.B, argCount, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }

            if (ti.Kind == TypeKinds.Struct && argCount == 0 && !HasExplicitZeroArgCtor(in td, in ast))
            {
                if (!types.IsZeroSafe(targetType, in ast))
                {
                    diags.ReportTok(VibCodes.NullOrZeroUnsafe, tok, "Parameterless zero-initialization 'new S()' of non-zero-safe struct is banned in Vibranium."u8);
                }
                return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, targetType, tokIdx));
            }
        }

        diags.ReportTok(VibCodes.Unsupported, tok, "Unsupported, unresolved, or inaccessible constructor invocation in Vibranium."u8);
        return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, targetType, tokIdx));
    }

    private static bool HasExplicitZeroArgCtor(in TypeDecl td, in AstArena ast)
    {
        for (int m = 0; m < td.FuncCount; m++)
        {
            FuncDecl fd = ast.Funcs[td.FuncStart + m];
            if ((fd.Flags & DeclFlags.IsCtor) != 0 && fd.ParamCount == 0) return true;
        }
        return false;
    }

    private static bool IsDirectCollectionRvalue(int expressionId, in AstArena ast)
    {
        if (expressionId < 0) return false;
        AstNode expression = ast.Nodes[expressionId];
        if (expression.Kind == AstKind.ExprCollLit) return true;
        if (expression.Kind == AstKind.ExprCast ||
            (expression.Kind == AstKind.ExprUnary && expression.A == (int)TokKind.KwUnchecked && expression.C == 0))
            return IsDirectCollectionRvalue(expression.B, in ast);
        return false;
    }

    private static int LowerCollectionLiteral(in AstNode n, int expectedTypeId, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags) => LowerCollectionLiteral(in n, expectedTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, -1);

    private static int LowerCollectionLiteral(
        in AstNode n,
        int expectedTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        int collectionDestinationPlace)
    {
        int tokIdx = n.TokIdx;
        if (expectedTypeId < 0)
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Collection expression requires a target type (Vec<T>, Span<T>, or ReadOnlySpan<T>) in Vibranium."u8);
            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
        }
        TypeInfo ti = types.Items[expectedTypeId];
        int elemCount = n.B;

        if (ti.Kind == TypeKinds.Vec)
        {
            int elemT = ti.A;
            if (elemCount == 0)
            {
                return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId, tokIdx));
            }
            var elemOps = new Vec<int>(elemCount);
            for (int i = 0; i < elemCount; i++)
            {
                int elemExprId = ast.Extra[n.A + i];
                int elemOp = LowerExprAsOperand(elemExprId, elemT, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                if (i + 1 < elemCount)
                {
                    elemOp = MaterializeByValueCallArgIfNeeded(elemOp, true, ast.Nodes[elemExprId].TokIdx, ref fctx, in types, ref mir);
                }
                elemOps.Push(elemOp);
            }
            int dstTmp = fctx.NewTemp(expectedTypeId, tokIdx, ref mir);
            int dstPl = mir.AddPlaceLocal(dstTmp, expectedTypeId);
            fctx.Emit(new MirInst(MirOp.Intrinsic, dstPl, -1, 0, expectedTypeId, (int)MirIntrinsic.VecFromLiteral, mir.PushIdList(elemOps.AsReadOnlySpan()), elemCount, 0, tokIdx));
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, expectedTypeId, tokIdx));
        }

        if (ti.Kind == TypeKinds.Span || ti.Kind == TypeKinds.ReadOnlySpan)
        {
            int elemT = ti.A;
            // C# also permits constant enum elements in caller-safe readonly collections.
            // This source context does not change StackSpan's runtime ownership or storage.
            bool constantStorage = ti.Kind == TypeKinds.ReadOnlySpan &&
                ((elemT >= TypeIds.Bool && elemT <= TypeIds.U64) || elemT == TypeIds.F32 || elemT == TypeIds.F64 ||
                 types.Items[elemT].Kind == TypeKinds.Enum);
            int owner = fctx.EnclosingOwnerDeclId;
            var elemOps = new Vec<int>(elemCount);
            for (int i = 0; i < elemCount; i++)
            {
                int elemExprId = ast.Extra[n.A + i];
                if (constantStorage && !TryGetSourceSwitchConstant(elemExprId, elemT, owner, in fctx, in ast, in ta, in names, in bctx, in types, out _, out _))
                {
                    constantStorage = false;
                }
                int elemOp = LowerExprAsOperand(elemExprId, elemT, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                if (i + 1 < elemCount)
                {
                    elemOp = MaterializeByValueCallArgIfNeeded(elemOp, true, ast.Nodes[elemExprId].TokIdx, ref fctx, in types, ref mir);
                }
                elemOps.Push(elemOp);
            }
            int ssId = fctx.StackSpanCounter;
            fctx.StackSpanCounter += 1;
            fctx.SourceStackSpanContexts.Push(elemCount == 0 || constantStorage ? 0 : fctx.ScopeDepth + 2);
            // A direct collection rvalue owns storage at its actual destination.
            // Anonymous argument/conditional buffers have frame lifetime, not a
            // fabricated lexical scope. Stack provenance and source context stay intact.
            int dstPl = collectionDestinationPlace;
            if (dstPl < 0)
            {
                int dstTmp = fctx.AddLocal(-1, expectedTypeId, PassMode.ByValue, MirLocalFlags.IsTemp, tokIdx);
                dstPl = mir.AddPlaceLocal(dstTmp, expectedTypeId);
            }
            fctx.Emit(new MirInst(MirOp.StackSpan, dstPl, -1, 0, expectedTypeId, mir.PushIdList(elemOps.AsReadOnlySpan()), elemCount, ssId, 0, tokIdx));
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, expectedTypeId, tokIdx));
        }

        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Collection expressions are only supported for Vec<T>, Span<T>, and ReadOnlySpan<T> in Vibranium."u8);
        return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, expectedTypeId, tokIdx));
    }

    private static bool TryResolvePropertyTarget(
        int lhsExprId,
        bool requireGetter,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        out bool isStaticProp,
        out int recvExprId,
        out int ownerTypeId,
        out int propGetDeclId,
        out int propSetDeclId)
    {
        isStaticProp = false;
        recvExprId = -1;
        ownerTypeId = -1;
        propGetDeclId = -1;
        propSetDeclId = -1;

        AstNode lhs = ast.Nodes[lhsExprId];
        if (lhs.Kind == AstKind.ExprIdent)
        {
            int locV = fctx.FindVar(lhs.A, out bool isLocC, out _, out _);
            if (locV >= 0 || locV == -2 || isLocC) return false;

            int curOwnerDecl = ast.Funcs[fctx.FuncDeclId].OwnerDeclId;
            for (int d = curOwnerDecl; d >= 0; d = ast.Types[d].OwnerDeclId)
            {
                TypeDecl otd = ast.Types[d];
                for (int f = 0; f < otd.FieldCount; f++)
                {
                    FieldDecl fd = ast.Fields[otd.FieldStart + f];
                    if (fd.NameId == lhs.A && (fd.Flags & DeclFlags.IsConst) != 0) return false;
                }
            }

            if (fctx.OwnerTypeId >= 0)
            {
                if (FindInstanceFieldIndex(fctx.OwnerTypeId, lhs.A, in types) >= 0) return false;

                int ownerDecl = types.Items[fctx.OwnerTypeId].A;
                var getBuf = new StringBuf(32);
                getBuf.Append("get_"u8);
                getBuf.Append(names.Text(lhs.A));
                int getNameId = names.Intern(getBuf.AsUtf8());
                var setBuf = new StringBuf(32);
                setBuf.Append("set_"u8);
                setBuf.Append(names.Text(lhs.A));
                int setNameId = names.Intern(setBuf.AsUtf8());

                int pGet = FindMethodInType(ownerDecl, getNameId, 0, isStatic: false, in ast);
                int pSet = FindMethodInType(ownerDecl, setNameId, 1, isStatic: false, in ast);
                if (pSet >= 0 && (!requireGetter || (pGet >= 0 && (ast.Funcs[pGet].Flags & DeclFlags.ReturnsByRef) == 0)))
                {
                    if (fctx.IsCtor)
                    {
                        diags.ReportTok(VibCodes.NullOrZeroUnsafe, ta.Tokens[lhs.TokIdx], "Cannot access, capture, or call members on 'this' before constructor finishes initializing all fields."u8);
                    }
                    if (fctx.ThisLocalId >= 0)
                    {
                        isStaticProp = false;
                        recvExprId = -1; // `this`
                        ownerTypeId = fctx.OwnerTypeId;
                        propGetDeclId = pGet;
                        propSetDeclId = pSet;
                        return true;
                    }
                }
            }

            for (int d = curOwnerDecl; d >= 0; d = ast.Types[d].OwnerDeclId)
            {
                if (d != curOwnerDecl && ast.Types[d].TypeParamCount > 0) continue;
                var getBuf = new StringBuf(32);
                getBuf.Append("get_"u8);
                getBuf.Append(names.Text(lhs.A));
                int getNameId = names.Intern(getBuf.AsUtf8());
                var setBuf = new StringBuf(32);
                setBuf.Append("set_"u8);
                setBuf.Append(names.Text(lhs.A));
                int setNameId = names.Intern(setBuf.AsUtf8());

                int sGet = FindMethodInType(d, getNameId, 0, isStatic: true, in ast);
                int sSet = FindMethodInType(d, setNameId, 1, isStatic: true, in ast);
                if (sSet >= 0 && (!requireGetter || (sGet >= 0 && (ast.Funcs[sGet].Flags & DeclFlags.ReturnsByRef) == 0)))
                {
                    isStaticProp = true;
                    recvExprId = -1;
                    ownerTypeId = d == curOwnerDecl ? fctx.OwnerTypeId : -1;
                    propGetDeclId = sGet;
                    propSetDeclId = sSet;
                    return true;
                }
            }

            if (TryResolveUsingStaticValueMember(lhs.A, lhs.TokIdx, reportAmbiguity: true, ref fctx, in ast, in ta, in names, in bctx, ref diags, out int usPrKind, out _, out int usPrOwnerTid, out _, out int usPrGet, out int usPrSet, out bool usPrAmb, out _, out _, out _))
            {
                if (!usPrAmb && usPrKind == 2 && usPrSet >= 0 && (!requireGetter || (usPrGet >= 0 && (ast.Funcs[usPrGet].Flags & DeclFlags.ReturnsByRef) == 0)))
                {
                    isStaticProp = true;
                    recvExprId = -1;
                    ownerTypeId = usPrOwnerTid;
                    propGetDeclId = usPrGet;
                    propSetDeclId = usPrSet;
                    return true;
                }
            }

            return false;
        }

        if (lhs.Kind == AstKind.ExprMember)
        {
            if (fctx.IsCtor && ast.Nodes[lhs.A].Kind == AstKind.ExprThis && fctx.OwnerTypeId >= 0)
            {
                if (FindInstanceFieldIndex(fctx.OwnerTypeId, lhs.B, in types) >= 0) return false;
            }

            if (TryResolveStaticTypeTarget(lhs.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int stDeclId, out int resolvedStaticTypeId, memberHintNameId: lhs.B, isMethodCallHint: false) && stDeclId >= 0)
            {
                var getBuf = new StringBuf(32);
                getBuf.Append("get_"u8);
                getBuf.Append(names.Text(lhs.B));
                int getNameId = names.Intern(getBuf.AsUtf8());
                var setBuf = new StringBuf(32);
                setBuf.Append("set_"u8);
                setBuf.Append(names.Text(lhs.B));
                int setNameId = names.Intern(setBuf.AsUtf8());

                int sGet = FindMethodInType(stDeclId, getNameId, 0, isStatic: true, in ast);
                int sSet = FindMethodInType(stDeclId, setNameId, 1, isStatic: true, in ast);
                if (sSet >= 0 && IsAccessibleFuncFromCaller(sSet, ref fctx, in ast, in bctx) &&
                    (!requireGetter || (sGet >= 0 && IsAccessibleFuncFromCaller(sGet, ref fctx, in ast, in bctx) && (ast.Funcs[sGet].Flags & DeclFlags.ReturnsByRef) == 0)))
                {
                    isStaticProp = true;
                    recvExprId = -1;
                    ownerTypeId = resolvedStaticTypeId;
                    propGetDeclId = sGet;
                    propSetDeclId = sSet;
                    return true;
                }
                return false;
            }

            int recvT = InferExprType(lhs.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            TypeInfo rti = types.Items[recvT];
            if (rti.Kind == TypeKinds.Class || rti.Kind == TypeKinds.Struct)
            {
                if (FindInstanceFieldIndex(recvT, lhs.B, in types) >= 0) return false;

                var getBuf = new StringBuf(32);
                getBuf.Append("get_"u8);
                getBuf.Append(names.Text(lhs.B));
                int getNameId = names.Intern(getBuf.AsUtf8());
                var setBuf = new StringBuf(32);
                setBuf.Append("set_"u8);
                setBuf.Append(names.Text(lhs.B));
                int setNameId = names.Intern(setBuf.AsUtf8());

                int pGet = FindMethodInType(rti.A, getNameId, 0, isStatic: false, in ast);
                int pSet = FindMethodInType(rti.A, setNameId, 1, isStatic: false, in ast);
                if (pSet >= 0 && IsAccessibleFuncFromCaller(pSet, ref fctx, in ast, in bctx) &&
                    (!requireGetter || (pGet >= 0 && IsAccessibleFuncFromCaller(pGet, ref fctx, in ast, in bctx) && (ast.Funcs[pGet].Flags & DeclFlags.ReturnsByRef) == 0)))
                {
                    if (fctx.IsCtor && ast.Nodes[lhs.A].Kind == AstKind.ExprThis)
                    {
                        diags.ReportTok(VibCodes.NullOrZeroUnsafe, ta.Tokens[lhs.TokIdx], "Cannot access, capture, or call members on 'this' before constructor finishes initializing all fields."u8);
                    }
                    isStaticProp = false;
                    recvExprId = lhs.A;
                    ownerTypeId = recvT;
                    propGetDeclId = pGet;
                    propSetDeclId = pSet;
                    return true;
                }
            }
        }

        return false;
    }

    private static int EmitPropertyCompoundOrIncDec(
        bool isIncDec,
        bool isPost,
        TokKind op,
        int rhsExprId,
        bool isStaticProp,
        int recvExprId,
        int ownerTypeId,
        int propGetDeclId,
        int propSetDeclId,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        var emptyM = new Vec<int>();
        int getInstId = DeclBinder.EnsureFuncInstance(propGetDeclId, ownerTypeId, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
        int setInstId = DeclBinder.EnsureFuncInstance(propSetDeclId, ownerTypeId, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
        FuncInstance getInst = mir.FuncInstances[getInstId];
        FuncInstance setInst = mir.FuncInstances[setInstId];
        int propType = getInst.ReturnTypeId;

        int setCarrierPl = -1;
        PassMode getRecvMode = PassMode.ByValue;
        PassMode setRecvMode = PassMode.ByValue;
        bool needMut = false;
        bool getMut = false;
        bool isClassRecv = false;

        if (!isStaticProp)
        {
            isClassRecv = types.Items[ownerTypeId].Kind == TypeKinds.Class;
            getRecvMode = mir.ParamSigs[getInst.ParamSigStart].Mode;
            setRecvMode = mir.ParamSigs[setInst.ParamSigStart].Mode;
            getMut = getRecvMode == PassMode.ThisMut;
            bool setMut = setRecvMode == PassMode.ThisMut;
            needMut = getMut || setMut;

            int rawRecvPl = recvExprId >= 0
                ? LowerPlaceOrTemp(recvExprId, ownerTypeId, isMut: needMut, isTwoPhase: needMut, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                : mir.AddPlaceLocal(fctx.ThisLocalId, ownerTypeId);
            if (recvExprId >= 0) ReportIfStructValueReceiver(rawRecvPl, ownerTypeId, tokIdx, in fctx, in ta, in types, in mir, ref diags);
            setCarrierPl = ReserveReceiverPlace(rawRecvPl, ownerTypeId, isMut: needMut, isTwoPhase: needMut, tokIdx, ref fctx, ref mir);
        }

        // 1. Call `get_Prop` and capture `oldVal`
        int oldValTmp = fctx.NewTemp(propType, tokIdx, ref mir);
        int oldValPl = mir.AddPlaceLocal(oldValTmp, propType);
        if (isStaticProp)
        {
            fctx.EmitCall(new MirInst(MirOp.Call, oldValPl, -1, 0, propType, getInstId, mir.CallArgs.Count, 0, 0, tokIdx), in mir);
        }
        else
        {
            int getCaStart = mir.CallArgs.Count;
            if (isClassRecv)
            {
                int rOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, setCarrierPl, 0, ownerTypeId, tokIdx));
                mir.CallArgs.Push(new MirCallArg(getRecvMode, rOp, tokIdx));
                fctx.EmitCall(new MirInst(MirOp.Call, oldValPl, -1, getMut ? 2 : 0, propType, getInstId, getCaStart, 1, 0, tokIdx), in mir);
            }
            else
            {
                int getRecvPl = getMut
                    ? ReserveReceiverPlace(setCarrierPl, ownerTypeId, isMut: true, isTwoPhase: true, tokIdx, ref fctx, ref mir)
                    : setCarrierPl;
                mir.CallArgs.Push(new MirCallArg(getRecvMode, getRecvPl, tokIdx));
                fctx.EmitCall(new MirInst(MirOp.Call, oldValPl, -1, getMut ? 2 : 0, propType, getInstId, getCaStart, 1, 0, tokIdx), in mir);
            }
        }

        // 2. Compute `newVal` (with `< 32`-bit short-int promotion & cast back)
        int curValOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, oldValPl, 0, propType, tokIdx));
        int calcType = (types.IsInteger(propType) && types.IntBitWidth(propType) < 32) ? TypeIds.I32 : propType;
        int lhsCalcOp = EmitCastToTemp(curValOp, calcType, tokIdx, ref fctx, ref mir);

        int rhsCalcOp;
        MirBinOp binOp;
        if (isIncDec)
        {
            ValidateIncDecTargetType(propType, tokIdx, in ta, in types, ref diags);
            binOp = op == TokKind.PlusPlus ? MirBinOp.Add : MirBinOp.Sub;
            rhsCalcOp = types.IsFloat(calcType)
                ? mir.AddOperand(new MirOperand(MirOpKinds.FloatConst, -1, (calcType == TypeIds.F32 ? 0x3F800000L : 0x3FF0000000000000L), calcType, tokIdx))
                : mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 1, calcType, tokIdx));
        }
        else
        {
            binOp = MapBinOp(op);
            rhsCalcOp = LowerCompoundRhsForTarget(op, rhsExprId, propType, calcType, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }

        int resTmp = fctx.NewTemp(calcType, tokIdx, ref mir);
        int resPl = mir.AddPlaceLocal(resTmp, calcType);
        fctx.Emit(new MirInst(MirOp.AssignBin, resPl, -1, 0, calcType, (int)binOp, lhsCalcOp, rhsCalcOp, 0, tokIdx));
        int newValOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, resPl, 0, calcType, tokIdx));
        if (calcType != propType)
        {
            newValOp = EmitCastToTemp(newValOp, propType, tokIdx, ref fctx, ref mir);
        }
        int newValTmp = fctx.NewTemp(propType, tokIdx, ref mir);
        int newValPl = mir.AddPlaceLocal(newValTmp, propType);
        fctx.Emit(new MirInst(MirOp.AssignUse, newValPl, -1, 0, propType, newValOp, 0, 0, 0, tokIdx));

        // 3. Call `set_Prop(newVal)`
        int setValArgOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, newValPl, 0, propType, tokIdx));
        int setCaStart = mir.CallArgs.Count;
        if (isStaticProp)
        {
            mir.CallArgs.Push(new MirCallArg(PassMode.ByValue, setValArgOp, tokIdx));
            fctx.EmitCall(new MirInst(MirOp.Call, -1, -1, 0, TypeIds.Void, setInstId, setCaStart, 1, 0, tokIdx), in mir);
        }
        else
        {
            if (isClassRecv)
            {
                int rOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, setCarrierPl, 0, ownerTypeId, tokIdx));
                mir.CallArgs.Push(new MirCallArg(setRecvMode, rOp, tokIdx));
            }
            else
            {
                mir.CallArgs.Push(new MirCallArg(setRecvMode, setCarrierPl, tokIdx));
            }
            mir.CallArgs.Push(new MirCallArg(PassMode.ByValue, setValArgOp, tokIdx));
            fctx.EmitCall(new MirInst(MirOp.Call, -1, -1, needMut ? 2 : 0, TypeIds.Void, setInstId, setCaStart, 2, 0, tokIdx), in mir);
        }

        if (isIncDec && isPost)
        {
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, oldValPl, 0, propType, tokIdx));
        }
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, newValPl, 0, propType, tokIdx));
    }

    private static void ValidateIncDecTargetType(int targetType, int tokIdx, in TokenArena ta, in TypeTable types, ref DiagnosticBag diags)
    {
        if (!types.IsInteger(targetType) && !types.IsFloat(targetType))
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Increment/decrement requires a numeric or enum target type in Vibranium."u8);
        }
    }

    private static int LowerCompoundRhsForTarget(
        TokKind op,
        int rhsExprId,
        int targetType,
        int calcType,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        bool isShift = op == TokKind.LtLtEq || op == TokKind.GtGtEq || op == TokKind.GtGtGtEq;
        TypeInfo tti = types.Items[targetType];
        if (tti.Kind == TypeKinds.Enum)
        {
            if (op == TokKind.PipeEq || op == TokKind.AmpEq || op == TokKind.CaretEq)
            {
                return LowerExprAsOperand(rhsExprId, targetType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }
            if (op == TokKind.PlusEq || op == TokKind.MinusEq)
            {
                int intOp = LowerExprAsOperand(rhsExprId, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                return EmitCastToTemp(intOp, targetType, tokIdx, ref fctx, ref mir);
            }
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Unsupported compound assignment operator on enum type in Vibranium."u8);
            _ = LowerExprAsOperand(rhsExprId, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, targetType, tokIdx));
        }

        if (targetType == TypeIds.Bool)
        {
            if (op == TokKind.PipeEq || op == TokKind.AmpEq || op == TokKind.CaretEq)
            {
                return LowerExprAsOperand(rhsExprId, TypeIds.Bool, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Unsupported compound assignment operator on bool in Vibranium."u8);
            _ = LowerExprAsOperand(rhsExprId, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            return mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, 0, TypeIds.Bool, tokIdx));
        }

        if (!types.IsInteger(targetType) && !types.IsFloat(targetType))
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Unsupported target type for compound assignment in Vibranium."u8);
            return LowerExprAsOperand(rhsExprId, targetType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }

        if (isShift)
        {
            if (!types.IsInteger(targetType))
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Shift compound assignment requires an integer target type."u8);
            }
            return LowerExprAsOperand(rhsExprId, TypeIds.I32, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }

        if ((op == TokKind.PipeEq || op == TokKind.AmpEq || op == TokKind.CaretEq) && types.IsFloat(targetType))
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Bitwise compound assignment cannot be applied to floating-point types."u8);
        }

        // C# §12.23.4: for non-shift `x op= y`, `y` must convert implicitly to `targetType`
        int rhsOp = LowerExprAsOperand(rhsExprId, targetType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        return calcType != targetType ? EmitCastToTemp(rhsOp, calcType, tokIdx, ref fctx, ref mir) : rhsOp;
    }

    private static bool TryEmitUserIndexerCompoundOrIncDec(
        in AstNode idxNode,
        bool isIncDec,
        bool isPost,
        TokKind op,
        int rhsExprId,
        int tokIdx,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        out int resultOp)
    {
        resultOp = -1;
        if (idxNode.D >= 0 && ast.Nodes[idxNode.D].Kind == AstKind.ExprRange) return false;

        int collT = InferExprType(idxNode.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        TypeInfo cti = types.Items[collT];
        if (cti.Kind != TypeKinds.Struct && cti.Kind != TypeKinds.Class) return false;

        if (!TryResolveUserIndexer(collT, in idxNode, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int idxGet, out int idxSet, out int elemType, out bool isFromEnd, out bool idxAmb))
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[idxNode.TokIdx], idxAmb ? "Ambiguous indexer access in Vibranium."u8 : "No applicable or accessible indexer overload in Vibranium."u8);
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, elemType, tokIdx));
            return true;
        }

        if (idxGet >= 0 && (ast.Funcs[idxGet].Flags & DeclFlags.ReturnsByRef) != 0)
        {
            return false;
        }

        if (idxGet < 0 || idxSet < 0)
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Compound assignment or increment/decrement on an indexer requires both an accessible getter and setter."u8);
            if (!isIncDec && rhsExprId >= 0)
            {
                _ = LowerExprAsOperand(rhsExprId, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }
            resultOp = mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, elemType, tokIdx));
            return true;
        }

        FuncDecl getFd = ast.Funcs[idxGet];
        var emptyM = new Vec<int>();
        int getInstId = DeclBinder.EnsureFuncInstance(idxGet, collT, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
        int setInstId = DeclBinder.EnsureFuncInstance(idxSet, collT, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
        FuncInstance getInst = mir.FuncInstances[getInstId];
        FuncInstance setInst = mir.FuncInstances[setInstId];
        elemType = getInst.ReturnTypeId;

        PassMode getRecvMode = mir.ParamSigs[getInst.ParamSigStart].Mode;
        PassMode setRecvMode = mir.ParamSigs[setInst.ParamSigStart].Mode;
        bool getMut = getRecvMode == PassMode.ThisMut;
        bool setMut = setRecvMode == PassMode.ThisMut;
        bool lenNeedsMut = false;
        if (isFromEnd && HasUserIntLengthOrCount(collT, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int lenGetId, out _) && lenGetId >= 0)
        {
            lenNeedsMut = DeclBinder.GetReceiverPassMode(ast.Funcs[lenGetId], collT, in ast, in types, bctx.IdDispose) == PassMode.ThisMut;
        }

        bool needMut = getMut || setMut || lenNeedsMut;
        bool isClassRecv = cti.Kind == TypeKinds.Class;

        // 1. Evaluate receiver once and reserve before index expressions
        int rawRecvPl = LowerPlaceOrTemp(idxNode.A, collT, isMut: needMut, isTwoPhase: needMut, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        ReportIfStructValueReceiver(rawRecvPl, collT, tokIdx, in fctx, in ta, in types, in mir, ref diags);
        int setCarrierPl = ReserveReceiverPlace(rawRecvPl, collT, isMut: needMut, isTwoPhase: needMut, tokIdx, ref fctx, ref mir);

        // 2. Evaluate all index arguments ONCE (in lexical order) and cache ByValue args into temp locals
        var rawIdxCallArgs = new Vec<MirCallArg>(getFd.ParamCount);
        bool hasTwoPhaseIdxArg = false;
        if (isFromEnd)
        {
            int cachedTot = -1;
            MirParamSig p0Sig = mir.ParamSigs[getInst.ParamSigStart + 1];
            int rawIdxOp = LowerUserIndexOrFromEndAsOperand(idxNode.D, p0Sig.TypeId, setCarrierPl, collT, ref cachedTot, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            if (p0Sig.Mode == PassMode.In)
            {
                int inTmp = fctx.NewTemp(p0Sig.TypeId, tokIdx, ref mir);
                int inPl = mir.AddPlaceLocal(inTmp, p0Sig.TypeId);
                fctx.Emit(new MirInst(MirOp.AssignUse, inPl, -1, 0, p0Sig.TypeId, rawIdxOp, 0, 0, 0, tokIdx));
                rawIdxCallArgs.Push(new MirCallArg(PassMode.In, inPl, tokIdx));
            }
            else
            {
                rawIdxCallArgs.Push(new MirCallArg(PassMode.ByValue, rawIdxOp, tokIdx));
            }
            for (int p = 1; p < getFd.ParamCount; p++)
            {
                MirParamSig psig = mir.ParamSigs[getInst.ParamSigStart + 1 + p];
                int defExpr = ast.Params[getFd.ParamStart + p].DefaultExpr;
                int defOp = defExpr >= 0
                    ? LowerExprAsOperand(defExpr, psig.TypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                    : mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, psig.TypeId, tokIdx));
                rawIdxCallArgs.Push(new MirCallArg(PassMode.ByValue, defOp, tokIdx));
            }
        }
        else
        {
            LowerExplicitAndDefaultCallArgs(in getFd, in getInst, 1, 0, idxNode.B, idxNode.C, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, ref rawIdxCallArgs, ref hasTwoPhaseIdxArg);
        }

        int idxParamCount = rawIdxCallArgs.Count;
        var cachedIdxPlaces = new Vec<int>(idxParamCount);
        var cachedIdxModes = new Vec<PassMode>(idxParamCount);
        var cachedIdxTypes = new Vec<int>(idxParamCount);
        for (int p = 0; p < idxParamCount; p++)
        {
            MirCallArg ca = rawIdxCallArgs[p];
            int pType = mir.ParamSigs[getInst.ParamSigStart + 1 + p].TypeId;
            cachedIdxModes.Push(ca.Mode);
            cachedIdxTypes.Push(pType);
            if (ca.Mode == PassMode.In)
            {
                int resInPl = ReserveReceiverPlace(ca.OperandOrPlaceId, pType, isMut: false, isTwoPhase: false, ca.TokIdx, ref fctx, ref mir);
                cachedIdxPlaces.Push(resInPl);
            }
            else
            {
                int idxTmp = fctx.NewTemp(pType, ca.TokIdx, ref mir);
                int idxPl = mir.AddPlaceLocal(idxTmp, pType);
                fctx.Emit(new MirInst(MirOp.AssignUse, idxPl, -1, 0, pType, ca.OperandOrPlaceId, 0, 0, 0, ca.TokIdx));
                cachedIdxPlaces.Push(idxPl);
            }
        }

        // 3. Call `get_Item(recv, idxArgs...)`
        int oldValTmp = fctx.NewTemp(elemType, tokIdx, ref mir);
        int oldValPl = mir.AddPlaceLocal(oldValTmp, elemType);
        int getCaStart = mir.CallArgs.Count;
        if (isClassRecv)
        {
            int rOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, setCarrierPl, 0, collT, tokIdx));
            mir.CallArgs.Push(new MirCallArg(getRecvMode, rOp, tokIdx));
        }
        else
        {
            int getRecvPl = getMut
                ? ReserveReceiverPlace(setCarrierPl, collT, isMut: true, isTwoPhase: true, tokIdx, ref fctx, ref mir)
                : setCarrierPl;
            mir.CallArgs.Push(new MirCallArg(getRecvMode, getRecvPl, tokIdx));
        }
        for (int p = 0; p < idxParamCount; p++)
        {
            if (cachedIdxModes[p] == PassMode.In)
            {
                mir.CallArgs.Push(new MirCallArg(PassMode.In, cachedIdxPlaces[p], tokIdx));
            }
            else
            {
                int getIdxOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, cachedIdxPlaces[p], 0, cachedIdxTypes[p], tokIdx));
                mir.CallArgs.Push(new MirCallArg(PassMode.ByValue, getIdxOp, tokIdx));
            }
        }
        fctx.EmitCall(new MirInst(MirOp.Call, oldValPl, -1, getMut ? 2 : 0, elemType, getInstId, getCaStart, 1 + idxParamCount, 0, tokIdx), in mir);

        // 4. Compute `newVal`
        int curValOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, oldValPl, 0, elemType, tokIdx));
        int calcType = (types.IsInteger(elemType) && types.IntBitWidth(elemType) < 32) ? TypeIds.I32 : elemType;
        int lhsCalcOp = EmitCastToTemp(curValOp, calcType, tokIdx, ref fctx, ref mir);

        int rhsCalcOp;
        MirBinOp binOp;
        if (isIncDec)
        {
            ValidateIncDecTargetType(elemType, tokIdx, in ta, in types, ref diags);
            binOp = op == TokKind.PlusPlus ? MirBinOp.Add : MirBinOp.Sub;
            rhsCalcOp = types.IsFloat(calcType)
                ? mir.AddOperand(new MirOperand(MirOpKinds.FloatConst, -1, (calcType == TypeIds.F32 ? 0x3F800000L : 0x3FF0000000000000L), calcType, tokIdx))
                : mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 1, calcType, tokIdx));
        }
        else
        {
            binOp = MapBinOp(op);
            rhsCalcOp = LowerCompoundRhsForTarget(op, rhsExprId, elemType, calcType, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }

        int resTmp = fctx.NewTemp(calcType, tokIdx, ref mir);
        int resPl = mir.AddPlaceLocal(resTmp, calcType);
        fctx.Emit(new MirInst(MirOp.AssignBin, resPl, -1, 0, calcType, (int)binOp, lhsCalcOp, rhsCalcOp, 0, tokIdx));
        int newValOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, resPl, 0, calcType, tokIdx));
        if (calcType != elemType)
        {
            newValOp = EmitCastToTemp(newValOp, elemType, tokIdx, ref fctx, ref mir);
        }
        int newValTmp = fctx.NewTemp(elemType, tokIdx, ref mir);
        int newValPl = mir.AddPlaceLocal(newValTmp, elemType);
        fctx.Emit(new MirInst(MirOp.AssignUse, newValPl, -1, 0, elemType, newValOp, 0, 0, 0, tokIdx));

        // 5. Call `set_Item(recv, idxArgs..., newVal)`
        int setValOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, newValPl, 0, elemType, tokIdx));
        int setCaStart = mir.CallArgs.Count;
        if (isClassRecv)
        {
            int rOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, setCarrierPl, 0, collT, tokIdx));
            mir.CallArgs.Push(new MirCallArg(setRecvMode, rOp, tokIdx));
        }
        else
        {
            mir.CallArgs.Push(new MirCallArg(setRecvMode, setCarrierPl, tokIdx));
        }
        for (int p = 0; p < idxParamCount; p++)
        {
            if (cachedIdxModes[p] == PassMode.In)
            {
                mir.CallArgs.Push(new MirCallArg(PassMode.In, cachedIdxPlaces[p], tokIdx));
            }
            else
            {
                int setIdxOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, cachedIdxPlaces[p], 0, cachedIdxTypes[p], tokIdx));
                mir.CallArgs.Push(new MirCallArg(PassMode.ByValue, setIdxOp, tokIdx));
            }
        }
        mir.CallArgs.Push(new MirCallArg(PassMode.ByValue, setValOp, tokIdx));
        fctx.EmitCall(new MirInst(MirOp.Call, -1, -1, needMut ? 2 : 0, TypeIds.Void, setInstId, setCaStart, 2 + idxParamCount, 0, tokIdx), in mir);

        resultOp = (isIncDec && isPost)
            ? mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, oldValPl, 0, elemType, tokIdx))
            : mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, newValPl, 0, elemType, tokIdx));
        return true;
    }

    private static int LowerUnaryAsOperand(in AstNode n, int expectedTypeId, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, ref Interner names, ref BinderCtx bctx, ref TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags) => LowerUnaryAsOperand(in n, expectedTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, -1);

    private static int LowerUnaryAsOperand(
        in AstNode n,
        int expectedTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        int collectionDestinationPlace)
    {
        int tokIdx = n.TokIdx;
        TokKind op = (TokKind)n.A;

        if (op == TokKind.KwUnchecked && n.C == 0)
        {
            fctx.UncheckedDepth += 1;
            int uInner = LowerExprAsOperand(n.B, expectedTypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, collectionDestinationPlace);
            fctx.UncheckedDepth -= 1;
            return uInner;
        }

        // `++x`, `--x`, `x++`, `x--`
        if (op == TokKind.PlusPlus || op == TokKind.MinusMinus)
        {
            CheckNotDirectCapturedPrimaryParamWrite(n.B, "Cannot reassign captured primary-constructor parameter; declare an explicit mutable field instead."u8, in fctx, in ast, in ta, in types, ref diags);
            bool isPost = n.C != 0;

            if (TryResolvePropertyTarget(n.B, requireGetter: true, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref diags, out bool isStaticProp, out int recvExprId, out int ownerTypeId, out int propGetId, out int propSetId))
            {
                return EmitPropertyCompoundOrIncDec(isIncDec: true, isPost, op, -1, isStaticProp, recvExprId, ownerTypeId, propGetId, propSetId, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            }

            if (ast.Nodes[n.B].Kind == AstKind.ExprIndex &&
                TryEmitUserIndexerCompoundOrIncDec(ast.Nodes[n.B], isIncDec: true, isPost, op, -1, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int idxIncOp))
            {
                return idxIncOp;
            }

            int pl = LowerPlace(n.B, isMut: true, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            CheckSourceWritablePlace(pl, tokIdx, in fctx, in ta, in types, in mir, ref diags);
            int pType = mir.Places[pl].TypeId;
            ValidateIncDecTargetType(pType, tokIdx, in ta, in types, ref diags);
            int oldOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, pType, tokIdx));
            int savedOldOp = oldOp;
            if (isPost)
            {
                int oldTmp = fctx.NewTemp(pType, tokIdx, ref mir);
                int oldPl = mir.AddPlaceLocal(oldTmp, pType);
                fctx.Emit(new MirInst(MirOp.AssignUse, oldPl, -1, 0, pType, oldOp, 0, 0, 0, tokIdx));
                savedOldOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, oldPl, 0, pType, tokIdx));
                oldOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, oldPl, 0, pType, tokIdx));
            }
            int calcType = (types.IsInteger(pType) && types.IntBitWidth(pType) < 32) ? TypeIds.I32 : pType;
            MirBinOp binOp = op == TokKind.PlusPlus ? MirBinOp.Add : MirBinOp.Sub;
            if (calcType != pType)
            {
                int lhsCalc = EmitCastToTemp(oldOp, calcType, tokIdx, ref fctx, ref mir);
                int oneCalc = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 1, calcType, tokIdx));
                int resTmp = fctx.NewTemp(calcType, tokIdx, ref mir);
                int resPl = mir.AddPlaceLocal(resTmp, calcType);
                fctx.Emit(new MirInst(MirOp.AssignBin, resPl, -1, 0, calcType, (int)binOp, lhsCalc, oneCalc, 0, tokIdx));
                int casted = EmitCastToTemp(mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, resPl, 0, calcType, tokIdx)), pType, tokIdx, ref fctx, ref mir);
                fctx.Emit(new MirInst(MirOp.AssignUse, pl, -1, 0, pType, casted, 0, 0, 0, tokIdx));
            }
            else
            {
                int oneOp = types.IsFloat(pType)
                    ? mir.AddOperand(new MirOperand(MirOpKinds.FloatConst, -1, (pType == TypeIds.F32 ? 0x3F800000L : 0x3FF0000000000000L), pType, tokIdx))
                    : mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 1, pType, tokIdx));
                fctx.Emit(new MirInst(MirOp.AssignBin, pl, -1, 0, pType, (int)binOp, oldOp, oneOp, 0, tokIdx));
            }
            if (isPost) return savedOldOp;
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pl, 0, pType, tokIdx));
        }

        // Constant fold `-intLit` (important for `-2147483648` and `-9223372036854775808L` and `-0x340D631B7BDDDCDBL`!)
        if (op == TokKind.Minus && ast.Nodes[n.B].Kind == AstKind.ExprIntLit)
        {
            Token litTok = ta.Tokens[ast.Nodes[n.B].A];
            if ((litTok.AuxId & 4) != 0)
            {
                diags.ReportTok(VibCodes.Unsupported, litTok, "Integral constant is too large."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I64, tokIdx));
            }
            if (litTok.Kind == TokKind.ULongLit)
            {
                // C# §12.8.7.2: decimal 9223372036854775808 / 9223372036854775808L preceded by '-' is long.MinValue.
                if ((litTok.AuxId & 5) == 0 && (ulong)litTok.IntVal == 9223372036854775808UL)
                {
                    return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, litTok.IntVal, TypeIds.I64, tokIdx));
                }
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Unary '-' cannot be applied to operand of type 'ulong' in Vibranium."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I64, tokIdx));
            }
            long negVal = -litTok.IntVal;
            int resT = TypeIds.I32;
            if (!(litTok.AuxId == 0 && (ulong)litTok.IntVal == 2147483648UL && litTok.Kind != TokKind.LongLit) &&
                (litTok.Kind == TokKind.LongLit || litTok.Kind == TokKind.UIntLit || (ulong)litTok.IntVal > 2147483648UL))
            {
                resT = TypeIds.I64;
            }
            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, negVal, resT, tokIdx));
        }

        if (op == TokKind.Plus)
        {
            int pSubOp = LowerExprAsOperand(n.B, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int pSubType = mir.Operands[pSubOp].TypeId;
            if ((!types.IsInteger(pSubType) && !types.IsFloat(pSubType)) || types.Items[pSubType].Kind == TypeKinds.Enum)
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Unary '+' requires a numeric operand in Vibranium."u8);
                return pSubOp;
            }
            if (types.IsInteger(pSubType) && types.IntBitWidth(pSubType) < 32)
            {
                return EmitCastToTemp(pSubOp, TypeIds.I32, tokIdx, ref fctx, ref mir);
            }
            return pSubOp;
        }

        if (op == TokKind.Bang)
        {
            int bSubOp = LowerExprAsOperand(n.B, TypeIds.Bool, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int bDstTmp = fctx.NewTemp(TypeIds.Bool, tokIdx, ref mir);
            int bDstPl = mir.AddPlaceLocal(bDstTmp, TypeIds.Bool);
            fctx.Emit(new MirInst(MirOp.AssignUn, bDstPl, -1, 0, TypeIds.Bool, (int)MirUnOp.Not, bSubOp, 0, 0, tokIdx));
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, bDstPl, 0, TypeIds.Bool, tokIdx));
        }

        int subOp = LowerExprAsOperand(n.B, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        int subType = mir.Operands[subOp].TypeId;

        if (op == TokKind.Minus)
        {
            // Decimal `-2147483648` -> I32 and decimal `-9223372036854775808` -> I64
            if (ast.Nodes[n.B].Kind == AstKind.ExprIntLit)
            {
                Token litTok = ta.Tokens[ast.Nodes[n.B].A];
                if (litTok.AuxId == 0 && (ulong)litTok.IntVal == 2147483648UL)
                {
                    return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, -2147483648L, TypeIds.I32, tokIdx));
                }
                if ((litTok.AuxId & 5) == 0 && (ulong)litTok.IntVal == 9223372036854775808UL)
                {
                    return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, unchecked((long)9223372036854775808UL), TypeIds.I64, tokIdx));
                }
            }
            if (subType == TypeIds.U64 || subType == TypeIds.NUInt || types.Items[subType].Kind == TypeKinds.Enum ||
                (!types.IsInteger(subType) && !types.IsFloat(subType)))
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Unary '-' cannot be applied to this operand type in Vibranium."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I64, tokIdx));
            }
            if (subType == TypeIds.U32)
            {
                subOp = EmitCastToTemp(subOp, TypeIds.I64, tokIdx, ref fctx, ref mir);
                subType = TypeIds.I64;
            }
            else if (types.IsInteger(subType) && types.IntBitWidth(subType) < 32)
            {
                subOp = EmitCastToTemp(subOp, TypeIds.I32, tokIdx, ref fctx, ref mir);
                subType = TypeIds.I32;
            }

            int uCurOwner = fctx.EnclosingOwnerDeclId;
            if (types.IsInteger(subType) &&
                TryEvalTypedIntConstExpr(n.B, uCurOwner, in fctx, in ast, in ta, in names, in bctx, in types, out _, out long subConstVal))
            {
                if (fctx.UncheckedDepth == 0)
                {
                    bool negOvf = (subType == TypeIds.I32 && (int)subConstVal == -2147483648) ||
                                  ((subType == TypeIds.I64 || subType == TypeIds.NInt) && subConstVal == long.MinValue);
                    if (negOvf)
                    {
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Compile-time constant unary '-' overflows in checked mode; wrap in 'unchecked(...)' if wraparound is intended."u8);
                    }
                }
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, TruncateConstToType(unchecked(-subConstVal), subType), subType, tokIdx));
            }
        }
        else if (op == TokKind.Tilde)
        {
            if (!types.IsInteger(subType))
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Bitwise '~' requires an integer or enum operand in Vibranium."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
            }
            if (types.IntBitWidth(subType) < 32)
            {
                subOp = EmitCastToTemp(subOp, TypeIds.I32, tokIdx, ref fctx, ref mir);
                subType = TypeIds.I32;
            }
        }

        MirUnOp unOp = op == TokKind.Tilde ? MirUnOp.BitNot : MirUnOp.Neg;
        int resType = subType;
        int dstTmp = fctx.NewTemp(resType, tokIdx, ref mir);
        int dstPl = mir.AddPlaceLocal(dstTmp, resType);
        fctx.Emit(new MirInst(MirOp.AssignUn, dstPl, -1, 0, resType, (int)unOp, subOp, 0, 0, tokIdx));
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, resType, tokIdx));
    }

    private static int LowerBinaryAsOperand(
        int exprId,
        in AstNode n,
        int expectedTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int tokIdx = n.TokIdx;
        TokKind op = (TokKind)n.A;

        // Short-circuit `&&` and `||` as value
        if (op == TokKind.AmpAmp || op == TokKind.PipePipe)
        {
            int resTmp = fctx.NewTemp(TypeIds.Bool, tokIdx, ref mir);
            int resPl = mir.AddPlaceLocal(resTmp, TypeIds.Bool);
            int tBlk = fctx.NewBlock();
            int fBlk = fctx.NewBlock();
            int mBlk = fctx.NewBlock();
            // The operands' out and pattern variables stay in scope after the
            // expression, like those of a conditional's condition (C# scope).
            int prevShortCircuitOverride = fctx.OutVarScopeOverride;
            if (fctx.OutVarScopeOverride <= 0) fctx.OutVarScopeOverride = fctx.ScopeDepth;
            PushScope(ref fctx);
            LowerCondBranch(exprId, tBlk, fBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope: false);
            fctx.OutVarScopeOverride = prevShortCircuitOverride;
            fctx.CurBlock = tBlk;
            EmitScopeExitsDownTo(fctx.ScopeDepth, tokIdx, ref fctx, ref mir);
            fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, TypeIds.Bool, mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, 1, TypeIds.Bool, tokIdx)), 0, 0, 0, tokIdx));
            fctx.Terminate(new MirTerm(MirTermKind.Goto, mBlk, 0, 0, 0, 0, 0, tokIdx));
            PopScopeWithoutEmit(ref fctx);
            fctx.CurBlock = fBlk;
            fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, TypeIds.Bool, mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, 0, TypeIds.Bool, tokIdx)), 0, 0, 0, tokIdx));
            fctx.Terminate(new MirTerm(MirTermKind.Goto, mBlk, 0, 0, 0, 0, 0, tokIdx));
            fctx.CurBlock = mBlk;
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, resPl, 0, TypeIds.Bool, tokIdx));
        }



        int lOp = LowerExprAsOperand(n.B, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        lOp = MaterializeByValueCallArgIfNeeded(lOp, true, ast.Nodes[n.B].TokIdx, ref fctx, in types, ref mir);
        int rOp = LowerExprAsOperand(n.C, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        int lType = mir.Operands[lOp].TypeId;
        int rType = mir.Operands[rOp].TypeId;

        if (lType == TypeIds.Str || rType == TypeIds.Str)
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "String operators are banned in Vibranium."u8);
            return mir.AddOperand(new MirOperand(MirOpKinds.BoolConst, -1, 0, TypeIds.Bool, tokIdx));
        }

        bool isShift = op == TokKind.LtLt || op == TokKind.GtGt || op == TokKind.GtGtGt;
        bool isBitwiseOp = op == TokKind.Amp || op == TokKind.Pipe || op == TokKind.Caret;
        bool isEqOrRel = op == TokKind.EqEq || op == TokKind.BangEq || op == TokKind.LAngle || op == TokKind.LtEq || op == TokKind.RAngle || op == TokKind.GtEq;
        int commonType;
        int enumArithmeticOutType = -1;
        bool leftConvertedToEnumZero = false;
        bool rightConvertedToEnumZero = false;

        if (isShift)
        {
            if (!types.IsInteger(lType) || types.Items[lType].Kind == TypeKinds.Enum ||
                ClassifyByValueConversionWithCtx(n.C, rType, TypeIds.I32, in fctx, in names, in bctx, in ast, in ta, in types) < 0)
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Incompatible operand types for shift operator in Vibranium."u8);
            }
            commonType = (types.IsInteger(lType) && types.IntBitWidth(lType) < 32) ? TypeIds.I32 : lType;
            lOp = EmitCastToTemp(lOp, commonType, tokIdx, ref fctx, ref mir);
            rOp = EmitCastToTemp(rOp, TypeIds.I32, tokIdx, ref fctx, ref mir);
        }
        else if (lType == TypeIds.Bool || rType == TypeIds.Bool)
        {
            if (lType != TypeIds.Bool || rType != TypeIds.Bool ||
                !(op == TokKind.EqEq || op == TokKind.BangEq || isBitwiseOp))
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Incompatible operand types for boolean binary operator in Vibranium."u8);
            }
            commonType = TypeIds.Bool;
        }
        else if (types.Items[lType].Kind == TypeKinds.Enum || types.Items[rType].Kind == TypeKinds.Enum)
        {
            bool lEnum = types.Items[lType].Kind == TypeKinds.Enum;
            bool rEnum = types.Items[rType].Kind == TypeKinds.Enum;
            int eType = lEnum ? lType : rType;
            if (lEnum && rEnum && lType == rType && (isEqOrRel || isBitwiseOp))
            {
                commonType = eType;
            }
            else if (lEnum && rEnum && lType == rType && op == TokKind.Minus)
            {
                commonType = TypeIds.I32;
                enumArithmeticOutType = TypeIds.I32;
                lOp = EmitCastToTemp(lOp, TypeIds.I32, tokIdx, ref fctx, ref mir);
                rOp = EmitCastToTemp(rOp, TypeIds.I32, tokIdx, ref fctx, ref mir);
            }
            else if ((isEqOrRel || isBitwiseOp) &&
                     ClassifyByValueConversionWithCtx(n.B, lType, eType, in fctx, in names, in bctx, in ast, in ta, in types) >= 0 &&
                     ClassifyByValueConversionWithCtx(n.C, rType, eType, in fctx, in names, in bctx, in ast, in ta, in types) >= 0)
            {
                commonType = eType;
                lOp = ConvertOperandIfNeeded(lOp, eType, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, n.B);
                rOp = ConvertOperandIfNeeded(rOp, eType, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, n.C);
            }
            else if (lEnum && !rEnum && (op == TokKind.Plus || op == TokKind.Minus) &&
                     ClassifyByValueConversionWithCtx(n.C, rType, TypeIds.I32, in fctx, in names, in bctx, in ast, in ta, in types) >= 0)
            {
                commonType = eType;
                rOp = ConvertOperandIfNeeded(rOp, TypeIds.I32, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, n.C);
                rOp = EmitCastToTemp(rOp, eType, tokIdx, ref fctx, ref mir);
            }
            else if (op == TokKind.Minus &&
                     ((lEnum && !rEnum && ClassifyByValueConversionWithCtx(n.C, rType, eType, in fctx, in names, in bctx, in ast, in ta, in types) >= 0) ||
                      (!lEnum && rEnum && ClassifyByValueConversionWithCtx(n.B, lType, eType, in fctx, in names, in bctx, in ast, in ta, in types) >= 0)))
            {
                // Numeric constant zero converts to E; this is E - E -> int even
                // for float/double zero. Feed the converted values to the overflow gate.
                commonType = TypeIds.I32;
                enumArithmeticOutType = TypeIds.I32;
                leftConvertedToEnumZero = !lEnum;
                rightConvertedToEnumZero = !rEnum;
                lOp = leftConvertedToEnumZero
                    ? mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx))
                    : EmitCastToTemp(lOp, TypeIds.I32, tokIdx, ref fctx, ref mir);
                rOp = rightConvertedToEnumZero
                    ? mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx))
                    : EmitCastToTemp(rOp, TypeIds.I32, tokIdx, ref fctx, ref mir);
            }
            else if (!lEnum && rEnum && (op == TokKind.Plus || op == TokKind.Minus) &&
                     ClassifyByValueConversionWithCtx(n.B, lType, TypeIds.I32, in fctx, in names, in bctx, in ast, in ta, in types) >= 0)
            {
                // U + E and U - E -> E.
                commonType = eType;
                lOp = ConvertOperandIfNeeded(lOp, TypeIds.I32, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, n.B);
                lOp = EmitCastToTemp(lOp, eType, tokIdx, ref fctx, ref mir);
            }
            else
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Incompatible operand types for enum binary operator in Vibranium."u8);
                commonType = eType;
                rOp = lOp;
            }
        }
        else
        {
            commonType = PromoteBinaryNumericTypeWithCtx(n.B, lType, n.C, rType, in fctx, in names, in bctx, in ast, in ta, in types);
            bool bothConvert =
                ClassifyByValueConversionWithCtx(n.B, lType, commonType, in fctx, in names, in bctx, in ast, in ta, in types) >= 0 &&
                ClassifyByValueConversionWithCtx(n.C, rType, commonType, in fctx, in names, in bctx, in ast, in ta, in types) >= 0;
            if (!bothConvert || (isBitwiseOp && types.IsFloat(commonType)))
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Incompatible operand types for binary operator in Vibranium."u8);
                commonType = TypeIds.I64;
                lOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, commonType, tokIdx));
                rOp = mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 1, commonType, tokIdx));
            }
            else
            {
                lOp = ConvertOperandIfNeeded(lOp, commonType, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, n.B);
                rOp = ConvertOperandIfNeeded(rOp, commonType, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, n.C);
            }
        }

        MirBinOp mirOp = MapBinOp(op);
        bool isCmp = mirOp >= MirBinOp.Eq && mirOp <= MirBinOp.Ge;
        int outType = isCmp ? TypeIds.Bool : (enumArithmeticOutType >= 0 ? enumArithmeticOutType : commonType);

        // Compile-time division by constant 0 (CS0020) and constant integer overflow (CS0220)
        int bCurOwner = fctx.EnclosingOwnerDeclId;
        long lConstV = 0L;
        long rConstV = 0L;
        if (types.IsInteger(commonType) &&
            (leftConvertedToEnumZero || TryEvalTypedIntConstExpr(n.B, bCurOwner, in fctx, in ast, in ta, in names, in bctx, in types, out _, out lConstV)) &&
            (rightConvertedToEnumZero || TryEvalTypedIntConstExpr(n.C, bCurOwner, in fctx, in ast, in ta, in names, in bctx, in types, out _, out rConstV)))
        {
            if ((op == TokKind.Slash || op == TokKind.Percent) && TruncateConstToType(rConstV, UnderlyingIntOrSelf(commonType, in types)) == 0)
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Division by constant zero."u8);
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, outType, tokIdx));
            }

            if (!isCmp)
            {
                if (fctx.UncheckedDepth == 0 && BinaryIntConstantOverflows(op, UnderlyingIntOrSelf(commonType, in types), lConstV, rConstV, in types))
                {
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Compile-time constant integer operation overflows in checked mode; wrap in 'unchecked(...)' if wraparound is intended."u8);
                }
                if (TryEvalTypedIntConstExpr(exprId, bCurOwner, in fctx, in ast, in ta, in names, in bctx, in types, out _, out long foldedV))
                {
                    return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, TruncateConstToType(foldedV, outType), outType, tokIdx));
                }
            }
        }

        int dstTmp = fctx.NewTemp(outType, tokIdx, ref mir);
        int dstPl = mir.AddPlaceLocal(dstTmp, outType);
        fctx.Emit(new MirInst(MirOp.AssignBin, dstPl, -1, 0, outType, (int)mirOp, lOp, rOp, 0, tokIdx));
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, dstPl, 0, outType, tokIdx));
    }

    private static bool ConstantFitsInExplicitIntTarget(int srcConstTid, long val, int dstTid, in TypeTable types)
    {
        bool srcUns = types.IsUnsignedInteger(srcConstTid);
        bool dstUns = types.IsUnsignedInteger(dstTid);
        ulong maxUns = dstTid == TypeIds.U8 ? 255UL :
                       (dstTid == TypeIds.U16 || dstTid == TypeIds.Char) ? 65535UL :
                       dstTid == TypeIds.U32 ? 4294967295UL : ulong.MaxValue;
        long minSig = dstTid == TypeIds.I8 ? -128L :
                      dstTid == TypeIds.I16 ? -32768L :
                      dstTid == TypeIds.I32 ? -2147483648L : long.MinValue;
        long maxSig = dstTid == TypeIds.I8 ? 127L :
                      dstTid == TypeIds.I16 ? 32767L :
                      dstTid == TypeIds.I32 ? 2147483647L : long.MaxValue;

        if (srcUns)
        {
            ulong u = (ulong)val;
            if (dstUns) return u <= maxUns;
            return u <= (ulong)maxSig;
        }
        if (dstUns)
        {
            return val >= 0 && (ulong)val <= maxUns;
        }
        return val >= minSig && val <= maxSig;
    }

    private static bool BinaryIntConstantOverflows(TokKind op, int commonType, long rawL, long rawR, in TypeTable types)
    {
        if (op != TokKind.Plus && op != TokKind.Minus && op != TokKind.Star && op != TokKind.Slash)
        {
            return false;
        }
        if (commonType == TypeIds.I32)
        {
            long a = (int)rawL;
            long b = (int)rawR;
            if (op == TokKind.Plus) { long r = a + b; return r < -2147483648L || r > 2147483647L; }
            if (op == TokKind.Minus) { long r = a - b; return r < -2147483648L || r > 2147483647L; }
            if (op == TokKind.Star) { long r = a * b; return r < -2147483648L || r > 2147483647L; }
            if (op == TokKind.Slash) return a == -2147483648L && b == -1L;
            return false;
        }
        if (commonType == TypeIds.U32)
        {
            ulong a = (uint)rawL;
            ulong b = (uint)rawR;
            if (op == TokKind.Plus) return (a + b) > 4294967295UL;
            if (op == TokKind.Minus) return a < b;
            if (op == TokKind.Star) return (a * b) > 4294967295UL;
            return false;
        }
        if (types.IsUnsignedInteger(commonType))
        {
            ulong a = (ulong)rawL;
            ulong b = (ulong)rawR;
            if (op == TokKind.Plus) return ulong.MaxValue - a < b;
            if (op == TokKind.Minus) return a < b;
            if (op == TokKind.Star) return a != 0 && (ulong.MaxValue / a) < b;
            return false;
        }
        else
        {
            long a = rawL;
            long b = rawR;
            if (op == TokKind.Plus) return (b > 0 && a > long.MaxValue - b) || (b < 0 && a < long.MinValue - b);
            if (op == TokKind.Minus) return (b < 0 && a > long.MaxValue + b) || (b > 0 && a < long.MinValue + b);
            if (op == TokKind.Star)
            {
                if (a == 0 || b == 0) return false;
                if ((a == -1 && b == long.MinValue) || (b == -1 && a == long.MinValue)) return true;
                long prod = unchecked(a * b);
                return (prod / b) != a;
            }
            if (op == TokKind.Slash) return a == long.MinValue && b == -1;
            return false;
        }
    }

    private static int PromoteBinaryNumericTypeWithCtx(
        int aExprId,
        int a,
        int bExprId,
        int b,
        in FuncLowerCtx fctx,
        in Interner names,
        in BinderCtx bctx,
        in AstArena ast,
        in TokenArena ta,
        in TypeTable types)
    {
        if (a == TypeIds.F64 || b == TypeIds.F64) return TypeIds.F64;
        if (a == TypeIds.F32 || b == TypeIds.F32) return TypeIds.F32;
        if (a == TypeIds.U64 || b == TypeIds.U64) return TypeIds.U64;
        if (a == TypeIds.I64 || b == TypeIds.I64) return TypeIds.I64;
        if (a == TypeIds.NUInt || b == TypeIds.NUInt) return TypeIds.NUInt;
        if (a == TypeIds.NInt || b == TypeIds.NInt) return TypeIds.NInt;
        if (a == TypeIds.U32 && b == TypeIds.U32) return TypeIds.U32;
        if (a == TypeIds.U32 && types.IsSignedInteger(b))
        {
            if (bExprId >= 0 && ClassifyByValueConversionWithCtx(bExprId, b, TypeIds.U32, in fctx, in names, in bctx, in ast, in ta, in types) >= 0)
            {
                return TypeIds.U32;
            }
            return TypeIds.I64;
        }
        if (b == TypeIds.U32 && types.IsSignedInteger(a))
        {
            if (aExprId >= 0 && ClassifyByValueConversionWithCtx(aExprId, a, TypeIds.U32, in fctx, in names, in bctx, in ast, in ta, in types) >= 0)
            {
                return TypeIds.U32;
            }
            return TypeIds.I64;
        }
        if (a == TypeIds.U32 || b == TypeIds.U32) return TypeIds.U32;
        return TypeIds.I32;
    }

    private static MirBinOp MapBinOp(TokKind k)
    {
        switch (k)
        {
            case TokKind.Plus:
            case TokKind.PlusEq: return MirBinOp.Add;
            case TokKind.Minus:
            case TokKind.MinusEq: return MirBinOp.Sub;
            case TokKind.Star:
            case TokKind.StarEq: return MirBinOp.Mul;
            case TokKind.Slash:
            case TokKind.SlashEq: return MirBinOp.Div;
            case TokKind.Percent:
            case TokKind.PercentEq: return MirBinOp.Rem;
            case TokKind.Amp:
            case TokKind.AmpEq: return MirBinOp.BitAnd;
            case TokKind.Pipe:
            case TokKind.PipeEq: return MirBinOp.BitOr;
            case TokKind.Caret:
            case TokKind.CaretEq: return MirBinOp.BitXor;
            case TokKind.LtLt:
            case TokKind.LtLtEq: return MirBinOp.Shl;
            case TokKind.GtGt:
            case TokKind.GtGtEq: return MirBinOp.Shr;
            case TokKind.GtGtGt:
            case TokKind.GtGtGtEq: return MirBinOp.UShr;
            case TokKind.EqEq: return MirBinOp.Eq;
            case TokKind.BangEq: return MirBinOp.Ne;
            case TokKind.LAngle: return MirBinOp.Lt;
            case TokKind.LtEq: return MirBinOp.Le;
            case TokKind.RAngle: return MirBinOp.Gt;
            case TokKind.GtEq: return MirBinOp.Ge;
            default: return MirBinOp.Add;
        }
    }

    private static bool IsDiscardOutArgument(in AstNode argument, in FuncLowerCtx fctx, in AstArena ast, in Interner names) =>
        argument.C == -3 || (argument.C == -2 && IsDiscardExpression(argument.B, in fctx, in ast, in names));

    private static bool IsDiscardExpression(int exprId, in FuncLowerCtx fctx, in AstArena ast, in Interner names)
    {
        AstNode n = ast.Nodes[exprId];
        if (n.Kind == AstKind.ExprDiscard) return true;
        if (n.Kind != AstKind.ExprIdent || !Bytes.Eq(names.Text(n.A), "_"u8)) return false;
        int local = fctx.FindVar(n.A, out bool isConst, out _, out _);
        return local == -1 && !isConst && !SourceLexicalScopeChecker.HasField(n.A, fctx.EnclosingOwnerDeclId, in ast);
    }

    private static int LowerAssignAsOperand(
        in AstNode n,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        bool valueUsed)
    {
        int tokIdx = n.TokIdx;
        TokKind op = (TokKind)n.A;

        // C# 7.3 Ref reassignment (`r = ref y`)
        if (n.D != 0)
        {
            int derefPl = LowerRefAssignPlace(in n, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out _);
            int valType = mir.Places[derefPl].TypeId;
            return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, derefPl, 0, valType, tokIdx));
        }

        // Discard assignment `_ = expr;` -> allocate temp local of RHS's exact type so linear `_ = File.OpenRead(...)` triggers VIB006
        if (op == TokKind.Eq && IsDiscardExpression(n.B, in fctx, in ast, in names))
        {
            int rhsOp = LowerExprAsOperand(n.C, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int rType = mir.Operands[rhsOp].TypeId;
            if (rType == TypeIds.Utf8Lines || rType == TypeIds.Utf8ArgEnum)
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Closed foreach view enumerator cannot be discarded; iterate with 'foreach'."u8);
                return rhsOp;
            }
            if (rType != TypeIds.Void)
            {
                int discTmp = fctx.NewTemp(rType, tokIdx, ref mir);
                int discPl = mir.AddPlaceLocal(discTmp, rType);
                fctx.Emit(new MirInst(MirOp.AssignUse, discPl, -1, 0, rType, rhsOp, 0, 0, 0, tokIdx));
            }
            return rhsOp;
        }

        // `vec += item` -> `vec.Push(item)`, or user `void operator +=` with C# type-directed overload resolution
        if (op == TokKind.PlusEq)
        {
            int lhsT = InferReceiverType(n.B, out bool lhsDeclares, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            TypeInfo lti = types.Items[lhsT];
            if (lti.Kind == TypeKinds.Vec)
            {
                CheckNotDirectCapturedPrimaryParamWrite(n.B, "Cannot reassign captured primary-constructor parameter; declare an explicit mutable field instead."u8, in fctx, in ast, in ta, in types, ref diags);
                int vPl = LowerPlace(n.B, isMut: true, isTwoPhase: true, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                if (mir.Places[vPl].ProjCount > 0) ReportIfSourceValuePlace(vPl, tokIdx, in fctx, in ta, in mir, ref diags);
                vPl = ReserveReceiverPlace(vPl, lhsT, isMut: true, isTwoPhase: true, tokIdx, ref fctx, ref mir);
                int itemOp = LowerExprAsOperand(n.C, lti.A, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                var ops = new Vec<int>(1);
                ops.Push(itemOp);
                var pls = new Vec<int>(1);
                pls.Push(vPl);
                fctx.Emit(new MirInst(MirOp.Intrinsic, -1, -1, 2, TypeIds.Void, (int)MirIntrinsic.VecPush, mir.PushIdList(ops.AsReadOnlySpan()), 1, mir.PushIdList(pls.AsReadOnlySpan()) | (1 << 20), tokIdx));
                return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
            }
            if (lti.Kind == TypeKinds.Struct || lti.Kind == TypeKinds.Class)
            {
                TypeDecl ltd = ast.Types[lti.A];
                var opCands = new Vec<int>();
                var opParamTypes = new Vec<int>();
                var tpN = new Vec<int>();
                var tpV = new Vec<int>();
                BuildOwnerTypeSubst(lhsT, in ast, in types, ref tpN, ref tpV);
                for (int m = 0; m < ltd.FuncCount; m++)
                {
                    int fId = ltd.FuncStart + m;
                    FuncDecl ofd = ast.Funcs[fId];
                    if ((ofd.Flags & DeclFlags.IsOpAddAssign) != 0 && ofd.ParamCount == 1 && ofd.TypeParamCount == 0 && IsAccessibleFuncFromCaller(fId, ref fctx, in ast, in bctx))
                    {
                        int pTypeId = DeclBinder.ResolveTypeNode(ast.Params[ofd.ParamStart].TypeNode, tpN.AsReadOnlySpan(), tpV.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false);
                        opCands.Push(fId);
                        opParamTypes.Push(pTypeId);
                    }
                }
                if (opCands.Count > 0)
                {
                    if (IsNonRefPropertyOrUserIndexerTarget(n.B, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref diags))
                    {
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Compound assignment with user-defined 'operator +=' on a non-ref property or indexer is not supported in Vibranium."u8);
                        _ = LowerExprAsOperand(n.C, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                        return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
                    }

                    // The left operand's out and pattern variables stay in scope in the right operand (N110).
                    EnterReceiverScope(n.B, lhsDeclares, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    int rhsT = InferExprType(n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                    var appCands = new Vec<int>();
                    var appParamTypes = new Vec<int>();
                    for (int c = 0; c < opCands.Count; c++)
                    {
                        if (ClassifyImplicitExpressionConversion(n.C, rhsT, opParamTypes[c], ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags) >= 0)
                        {
                            appCands.Push(opCands[c]);
                            appParamTypes.Push(opParamTypes[c]);
                        }
                    }
                    fctx.LeaveSpeculativeInfer();

                    if (appCands.Count == 0)
                    {
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "No applicable 'operator +=' overload for right-hand operand type in Vibranium."u8);
                        return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
                    }

                    int bestIdx = -1;
                    for (int i = 0; i < appCands.Count; i++)
                    {
                        bool beatsAll = true;
                        for (int j = 0; j < appCands.Count; j++)
                        {
                            if (i == j) continue;
                            int cmp = CompareSingleConversion(rhsT, PassMode.ByValue, appParamTypes[i], PassMode.ByValue, appParamTypes[j], PassMode.ByValue, in types);
                            if (cmp <= 0)
                            {
                                beatsAll = false;
                                break;
                            }
                        }
                        if (beatsAll)
                        {
                            bestIdx = i;
                            break;
                        }
                    }

                    if (bestIdx < 0)
                    {
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Ambiguous 'operator +=' invocation in Vibranium."u8);
                        return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
                    }

                    CheckNotDirectCapturedPrimaryParamWrite(n.B, "Cannot reassign captured primary-constructor parameter; declare an explicit mutable field instead."u8, in fctx, in ast, in ta, in types, ref diags);
                    int chosenFId = appCands[bestIdx];
                    FuncDecl chosenFd = ast.Funcs[chosenFId];
                    PassMode recvMode = DeclBinder.GetReceiverPassMode(chosenFd, lhsT, in ast, in types, bctx.IdDispose);
                    bool useTwoPhase = recvMode == PassMode.ThisMut;
                    int recvPl = lti.Kind == TypeKinds.Struct
                        ? LowerPlace(n.B, isMut: useTwoPhase, isTwoPhase: useTwoPhase, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                        : LowerPlaceOrTemp(n.B, lhsT, useTwoPhase, useTwoPhase, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    if (lti.Kind == TypeKinds.Struct && (useTwoPhase || mir.Places[recvPl].ProjCount > 0)) ReportIfSourceValuePlace(recvPl, tokIdx, in fctx, in ta, in mir, ref diags);
                    recvPl = ReserveReceiverPlace(recvPl, lhsT, useTwoPhase, useTwoPhase, tokIdx, ref fctx, ref mir);
                    var emptyM = new Vec<int>();
                    int instId = DeclBinder.EnsureFuncInstance(chosenFId, lhsT, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                    FuncInstance fnInst = mir.FuncInstances[instId];
                    int argOp = LowerExprAsOperand(n.C, mir.ParamSigs[fnInst.ParamSigStart + 1].TypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    int caStart = mir.CallArgs.Count;
                    if (lti.Kind == TypeKinds.Class)
                    {
                        int recvOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, recvPl, 0, lhsT, tokIdx));
                        mir.CallArgs.Push(new MirCallArg(recvMode, recvOp, tokIdx));
                    }
                    else
                    {
                        mir.CallArgs.Push(new MirCallArg(recvMode, recvPl, tokIdx));
                    }
                    mir.CallArgs.Push(new MirCallArg(PassMode.ByValue, argOp, tokIdx));
                    fctx.EmitCall(new MirInst(MirOp.Call, -1, -1, useTwoPhase ? 2 : 0, TypeIds.Void, instId, caStart, 2, 0, tokIdx), in mir);
                    return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.Void, tokIdx));
                }
            }
        }

        // User property simple assignment (`=`) and compound assignment (`op=`) for `ExprMember` and bare `ExprIdent`
        if (TryResolvePropertyTarget(n.B, requireGetter: op != TokKind.Eq, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref diags, out bool isStaticProp, out int propRecvExprId, out int propOwnerTid, out int propGetId, out int propSetId))
        {
            CheckNotDirectCapturedPrimaryParamWrite(n.B, "Cannot reassign captured primary-constructor parameter; declare an explicit mutable field instead."u8, in fctx, in ast, in ta, in types, ref diags);
            if (op == TokKind.Eq)
            {
                var emptyM = new Vec<int>();
                int setInstId = DeclBinder.EnsureFuncInstance(propSetId, propOwnerTid, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                FuncInstance setInst = mir.FuncInstances[setInstId];
                if (isStaticProp)
                {
                    int valType = mir.ParamSigs[setInst.ParamSigStart].TypeId;
                    int rhsOp = LowerExprAsOperand(n.C, valType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    int valTmp = fctx.NewTemp(valType, tokIdx, ref mir);
                    int valPl = mir.AddPlaceLocal(valTmp, valType);
                    fctx.Emit(new MirInst(MirOp.AssignUse, valPl, -1, 0, valType, rhsOp, 0, 0, 0, tokIdx));
                    int passValOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, valPl, 0, valType, tokIdx));
                    int caStart = mir.CallArgs.Count;
                    mir.CallArgs.Push(new MirCallArg(PassMode.ByValue, passValOp, tokIdx));
                    fctx.EmitCall(new MirInst(MirOp.Call, -1, -1, 0, TypeIds.Void, setInstId, caStart, 1, 0, tokIdx), in mir);
                    return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, valPl, 0, valType, tokIdx));
                }
                else
                {
                    PassMode recvMode = mir.ParamSigs[setInst.ParamSigStart].Mode;
                    bool useTwoPhase = recvMode == PassMode.ThisMut;
                    int recvPl = propRecvExprId >= 0
                        ? LowerPlaceOrTemp(propRecvExprId, propOwnerTid, useTwoPhase, useTwoPhase, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                        : mir.AddPlaceLocal(fctx.ThisLocalId, propOwnerTid);
                    if (propRecvExprId >= 0) ReportIfStructValueReceiver(recvPl, propOwnerTid, tokIdx, in fctx, in ta, in types, in mir, ref diags);
                    recvPl = ReserveReceiverPlace(recvPl, propOwnerTid, useTwoPhase, useTwoPhase, tokIdx, ref fctx, ref mir);
                    int valType = mir.ParamSigs[setInst.ParamSigStart + 1].TypeId;
                    int rhsOp = LowerExprAsOperand(n.C, valType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    int valTmp = fctx.NewTemp(valType, tokIdx, ref mir);
                    int valPl = mir.AddPlaceLocal(valTmp, valType);
                    fctx.Emit(new MirInst(MirOp.AssignUse, valPl, -1, 0, valType, rhsOp, 0, 0, 0, tokIdx));
                    int caStart = mir.CallArgs.Count;
                    if (types.Items[propOwnerTid].Kind == TypeKinds.Class)
                    {
                        int recvOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, recvPl, 0, propOwnerTid, tokIdx));
                        mir.CallArgs.Push(new MirCallArg(recvMode, recvOp, tokIdx));
                    }
                    else
                    {
                        mir.CallArgs.Push(new MirCallArg(recvMode, recvPl, tokIdx));
                    }
                    int passValOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, valPl, 0, valType, tokIdx));
                    mir.CallArgs.Push(new MirCallArg(PassMode.ByValue, passValOp, tokIdx));
                    fctx.EmitCall(new MirInst(MirOp.Call, -1, -1, useTwoPhase ? 2 : 0, TypeIds.Void, setInstId, caStart, 2, 0, tokIdx), in mir);
                    return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, valPl, 0, valType, tokIdx));
                }
            }
            return EmitPropertyCompoundOrIncDec(isIncDec: false, isPost: false, op, n.C, isStaticProp, propRecvExprId, propOwnerTid, propGetId, propSetId, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        }

        // User indexer compound assignment (`x[i] op= rhs`, `x[^i] op= rhs`)
        if (op != TokKind.Eq && ast.Nodes[n.B].Kind == AstKind.ExprIndex &&
            TryEmitUserIndexerCompoundOrIncDec(ast.Nodes[n.B], isIncDec: false, isPost: false, op, n.C, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int idxCompOp))
        {
            return idxCompOp;
        }

        if (op == TokKind.Eq && ast.Nodes[n.B].Kind == AstKind.ExprIndex &&
            !(ast.Nodes[n.B].D >= 0 && ast.Nodes[ast.Nodes[n.B].D].Kind == AstKind.ExprRange))
        {
            AstNode idxNode = ast.Nodes[n.B];
            int collT = InferExprType(idxNode.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            TypeInfo cti = types.Items[collT];
            if (cti.Kind == TypeKinds.Vec)
            {
                int elemT = cti.A;
                int idxArgExpr = ExtractSingleBuiltInIndexArg(in idxNode, idxNode.TokIdx, in ast, in ta, in names, ref diags);
                int vecPl = LowerPlaceOrTemp(idxNode.A, collT, isMut: true, isTwoPhase: true, idxNode.TokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                vecPl = ReserveReceiverPlace(vecPl, collT, isMut: true, isTwoPhase: true, idxNode.TokIdx, ref fctx, ref mir);
                int idxOp = idxArgExpr >= 0
                    ? LowerIndexOrFromEndAsOperand(idxArgExpr, vecPl, isVecPlace: true, -1, idxNode.TokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                    : mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, idxNode.TokIdx));
                int refTmp = fctx.NewTempRef(elemT, isMut: true, idxNode.TokIdx);
                var valOps = new Vec<int>(1);
                valOps.Push(idxOp);
                var plOps = new Vec<int>(1);
                plOps.Push(vecPl);
                fctx.Emit(new MirInst(MirOp.Intrinsic, -1, refTmp, 1 | 2, elemT, (int)MirIntrinsic.VecIndexRef, mir.PushIdList(valOps.AsReadOnlySpan()), 1, mir.PushIdList(plOps.AsReadOnlySpan()) | (1 << 20), idxNode.TokIdx));
                int rhsOp = LowerExprAsOperand(n.C, elemT, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                var deref = new Vec<MirProj>(1);
                deref.Push(new MirProj(MirProjKinds.Deref, 0, elemT, -1, 0));
                int elemPl = mir.AddPlace(refTmp, deref.AsReadOnlySpan(), elemT);
                fctx.Emit(new MirInst(MirOp.AssignUse, elemPl, -1, 0, elemT, rhsOp, 0, 0, 0, tokIdx));
                return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, elemPl, 0, elemT, tokIdx));
            }
            if (cti.Kind == TypeKinds.Span || cti.Kind == TypeKinds.ReadOnlySpan)
            {
                int elemT = cti.A;
                int storeTok = ast.Nodes[idxNode.A].TokIdx;
                int idxArgExpr = ExtractSingleBuiltInIndexArg(in idxNode, storeTok, in ast, in ta, in names, ref diags);
                bool spanMut = cti.Kind == TypeKinds.Span;
                if (!spanMut)
                {
                    diags.ReportTok(VibCodes.MutateSharedBorrow, ta.Tokens[storeTok], "Cannot mutate through ReadOnlySpan<T>."u8);
                }
                int spPl = LowerPlaceOrTemp(idxNode.A, collT, isMut: spanMut, isTwoPhase: spanMut, storeTok, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                spPl = ReserveReceiverPlace(spPl, collT, isMut: spanMut, isTwoPhase: spanMut, storeTok, ref fctx, ref mir);
                int idxOp = idxArgExpr >= 0
                    ? LowerIndexOrFromEndAsOperand(idxArgExpr, spPl, isVecPlace: false, collT, storeTok, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                    : mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, storeTok));
                int spOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, spPl, 0, collT, storeTok));
                int refTmp = fctx.NewTempRef(elemT, isMut: spanMut, storeTok);
                var valOps = new Vec<int>(2);
                valOps.Push(spOp);
                valOps.Push(idxOp);
                fctx.Emit(new MirInst(MirOp.Intrinsic, -1, refTmp, (spanMut ? 1 : 0) | 2, elemT, (int)MirIntrinsic.SpanIndexRef, mir.PushIdList(valOps.AsReadOnlySpan()), 2, 0, storeTok));
                int rhsOp = LowerExprAsOperand(n.C, elemT, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                var deref = new Vec<MirProj>(1);
                deref.Push(new MirProj(MirProjKinds.Deref, 0, elemT, -1, 0));
                int elemPl = mir.AddPlace(refTmp, deref.AsReadOnlySpan(), elemT);
                fctx.Emit(new MirInst(MirOp.AssignUse, elemPl, -1, 0, elemT, rhsOp, 0, 0, 0, storeTok));
                return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, elemPl, 0, elemT, tokIdx));
            }
            if (cti.Kind == TypeKinds.Struct || cti.Kind == TypeKinds.Class)
            {
                if (!TryResolveUserIndexer(collT, in idxNode, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int idxGet, out int idxSet, out int elemTid, out bool isFromEnd, out bool idxAmb))
                {
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[idxNode.TokIdx], idxAmb ? "Ambiguous indexer access in Vibranium."u8 : "No applicable or accessible indexer overload in Vibranium."u8);
                    _ = LowerExprAsOperand(n.C, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, elemTid, tokIdx));
                }
                if (idxSet >= 0)
                {
                    CheckNotDirectCapturedPrimaryParamWrite(idxNode.A, "Cannot reassign captured primary-constructor parameter; declare an explicit mutable field instead."u8, in fctx, in ast, in ta, in types, ref diags);
                    FuncDecl setFd = ast.Funcs[idxSet];
                    PassMode recvMode = DeclBinder.GetReceiverPassMode(setFd, collT, in ast, in types, bctx.IdDispose);
                    bool setMut = recvMode == PassMode.ThisMut;
                    bool lenNeedsMut = false;
                    if (isFromEnd && HasUserIntLengthOrCount(collT, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int setLenGetId, out _) && setLenGetId >= 0)
                    {
                        lenNeedsMut = DeclBinder.GetReceiverPassMode(ast.Funcs[setLenGetId], collT, in ast, in types, bctx.IdDispose) == PassMode.ThisMut;
                    }
                    bool needMut = setMut || lenNeedsMut;
                    int recvPl = LowerPlaceOrTemp(idxNode.A, collT, isMut: needMut, isTwoPhase: needMut, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    ReportIfStructValueReceiver(recvPl, collT, tokIdx, in fctx, in ta, in types, in mir, ref diags);
                    recvPl = ReserveReceiverPlace(recvPl, collT, isMut: needMut, isTwoPhase: needMut, tokIdx, ref fctx, ref mir);
                    var emptyM = new Vec<int>();
                    int instId = DeclBinder.EnsureFuncInstance(idxSet, collT, emptyM.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref mir, ref diags);
                    FuncInstance fnInst = mir.FuncInstances[instId];

                    var loweredArgs = new Vec<MirCallArg>(fnInst.ParamSigCount);
                    if (cti.Kind == TypeKinds.Class)
                    {
                        int recvOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, recvPl, 0, collT, tokIdx));
                        loweredArgs.Push(new MirCallArg(recvMode, recvOp, tokIdx));
                    }
                    else
                    {
                        loweredArgs.Push(new MirCallArg(recvMode, recvPl, tokIdx));
                    }

                    bool hasTwoPhaseArg = needMut;
                    int idxFormalCount = setFd.ParamCount - 1;
                    if (isFromEnd)
                    {
                        int cachedTot = -1;
                        MirParamSig p0Sig = mir.ParamSigs[fnInst.ParamSigStart + 1];
                        int idxOp = LowerUserIndexOrFromEndAsOperand(idxNode.D, p0Sig.TypeId, recvPl, collT, ref cachedTot, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                        if (p0Sig.Mode == PassMode.In)
                        {
                            int inTmp = fctx.NewTemp(p0Sig.TypeId, tokIdx, ref mir);
                            int inPl = mir.AddPlaceLocal(inTmp, p0Sig.TypeId);
                            fctx.Emit(new MirInst(MirOp.AssignUse, inPl, -1, 0, p0Sig.TypeId, idxOp, 0, 0, 0, tokIdx));
                            loweredArgs.Push(new MirCallArg(PassMode.In, inPl, tokIdx));
                        }
                        else
                        {
                            idxOp = MaterializeByValueCallArgIfNeeded(idxOp, true, tokIdx, ref fctx, in types, ref mir);
                            loweredArgs.Push(new MirCallArg(PassMode.ByValue, idxOp, tokIdx));
                        }
                        for (int p = 1; p < idxFormalCount; p++)
                        {
                            MirParamSig psig = mir.ParamSigs[fnInst.ParamSigStart + 1 + p];
                            int defExpr = ast.Params[setFd.ParamStart + p].DefaultExpr;
                            int defOp = defExpr >= 0
                                ? LowerExprAsOperand(defExpr, psig.TypeId, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags)
                                : mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, psig.TypeId, tokIdx));
                            loweredArgs.Push(new MirCallArg(PassMode.ByValue, defOp, tokIdx));
                        }
                    }
                    else
                    {
                        LowerExplicitAndDefaultCallArgs(in setFd, in fnInst, 1, 0, idxNode.B, idxNode.C, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, ref loweredArgs, ref hasTwoPhaseArg, excludeTrailingParams: 1);
                        for (int k = 1; k < loweredArgs.Count; k++)
                        {
                            MirCallArg ma = loweredArgs[k];
                            int pTid = mir.ParamSigs[fnInst.ParamSigStart + k].TypeId;
                            if (ma.Mode == PassMode.ByValue)
                            {
                                loweredArgs[k] = new MirCallArg(PassMode.ByValue, MaterializeByValueCallArgIfNeeded(ma.OperandOrPlaceId, true, ma.TokIdx, ref fctx, in types, ref mir), ma.TokIdx);
                            }
                            else if (ma.Mode == PassMode.In)
                            {
                                loweredArgs[k] = new MirCallArg(PassMode.In, ReserveReceiverPlace(ma.OperandOrPlaceId, pTid, isMut: false, isTwoPhase: false, ma.TokIdx, ref fctx, ref mir), ma.TokIdx);
                            }
                        }
                    }

                    int valType = mir.ParamSigs[fnInst.ParamSigStart + 1 + idxFormalCount].TypeId;
                    int rhsOp = LowerExprAsOperand(n.C, valType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    int valTmp = fctx.NewTemp(valType, tokIdx, ref mir);
                    int valPl = mir.AddPlaceLocal(valTmp, valType);
                    fctx.Emit(new MirInst(MirOp.AssignUse, valPl, -1, 0, valType, rhsOp, 0, 0, 0, tokIdx));
                    int passValOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, valPl, 0, valType, tokIdx));
                    loweredArgs.Push(new MirCallArg(PassMode.ByValue, passValOp, tokIdx));

                    int caStart = mir.CallArgs.Count;
                    for (int i = 0; i < loweredArgs.Count; i++) mir.CallArgs.Push(loweredArgs[i]);
                    fctx.EmitCall(new MirInst(MirOp.Call, -1, -1, hasTwoPhaseArg ? 2 : 0, TypeIds.Void, instId, caStart, loweredArgs.Count, 0, tokIdx), in mir);
                    return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, valPl, 0, valType, tokIdx));
                }
                if (idxGet < 0 || (ast.Funcs[idxGet].Flags & DeclFlags.ReturnsByRef) == 0)
                {
                    diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Indexer cannot be assigned to because it has no accessible setter."u8);
                    _ = LowerExprAsOperand(n.C, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    return mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, elemTid, tokIdx));
                }
            }
        }

        CheckNotDirectCapturedPrimaryParamWrite(n.B, "Cannot reassign captured primary-constructor parameter; declare an explicit mutable field instead."u8, in fctx, in ast, in ta, in types, ref diags);
        int destPl = LowerPlace(n.B, isMut: true, isTwoPhase: true, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        int destType = mir.Places[destPl].TypeId;
        CheckSourceWritablePlace(destPl, tokIdx, in fctx, in ta, in types, in mir, ref diags);

        // Preserve the evaluated destination before the RHS can rebind its ref carrier.
        // Heap destinations also keep their existing two-phase owner reservation.
        MirPlace dpl = mir.Places[destPl];
        bool traversesHeap = false;
        bool readonlyDestination = false;
        for (int i = 0; i < dpl.ProjCount; i++)
        {
            MirProj pr = mir.Projs[dpl.ProjStart + i];
            if ((pr.Flags & 1) != 0)
            {
                traversesHeap = true;
                // Reading a readonly class reference does not make its referent readonly.
                readonlyDestination = false;
            }
            if ((pr.Flags & 2) != 0) readonlyDestination = true;
        }
        bool startsWithDeref = dpl.ProjCount > 0 && mir.Projs[dpl.ProjStart].Kind == MirProjKinds.Deref;
        if ((startsWithDeref || traversesHeap) && !readonlyDestination)
        {
            destPl = ReserveReceiverPlace(destPl, destType, isMut: true, isTwoPhase: true, tokIdx, ref fctx, ref mir, startsWithDeref);
        }

        if (op == TokKind.Eq)
        {
            int rhsOp = LowerExprAsOperand(n.C, destType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, destPl);
            if (mir.Operands[rhsOp].Kind != MirOpKinds.CopyOrMove || mir.Operands[rhsOp].PlaceOrLitIdx != destPl)
                fctx.Emit(new MirInst(MirOp.AssignUse, destPl, -1, 0, destType, rhsOp, 0, 0, 0, tokIdx));
            int valueOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, destPl, 0, destType, tokIdx));
            if (valueUsed && (types.Items[destType].Kind == TypeKinds.Span || types.Items[destType].Kind == TypeKinds.OptionMut))
            {
                // The value of an assignment is a copy or move of its destination
                // (SPEC §3.2). Its consumer would only reborrow an exclusive view
                // read in place, so move a !Copy view destination into the value now.
                int valueTmp = fctx.NewTemp(destType, tokIdx, ref mir);
                int valuePl = mir.AddPlaceLocal(valueTmp, destType);
                fctx.Emit(new MirInst(MirOp.AssignUse, valuePl, -1, 0, destType, valueOp, 0, 0, 0, tokIdx));
                return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, valuePl, 0, destType, tokIdx));
            }
            return valueOp;
        }

        // Compound assignment `place op= rhs` (evaluates `destPl` once before RHS)
        int oldValTmp = fctx.NewTemp(destType, tokIdx, ref mir);
        int oldValPl = mir.AddPlaceLocal(oldValTmp, destType);
        int readDestOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, destPl, 0, destType, tokIdx));
        fctx.Emit(new MirInst(MirOp.AssignUse, oldValPl, -1, 0, destType, readDestOp, 0, 0, 0, tokIdx));
        int curValOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, oldValPl, 0, destType, tokIdx));

        int calcType = (types.IsInteger(destType) && types.IntBitWidth(destType) < 32) ? TypeIds.I32 : destType;
        int lhsCalcOp = EmitCastToTemp(curValOp, calcType, tokIdx, ref fctx, ref mir);
        int rhsCalcOp = LowerCompoundRhsForTarget(op, n.C, destType, calcType, tokIdx, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);

        int resTmp = fctx.NewTemp(calcType, tokIdx, ref mir);
        int resPl = mir.AddPlaceLocal(resTmp, calcType);
        fctx.Emit(new MirInst(MirOp.AssignBin, resPl, -1, 0, calcType, (int)MapBinOp(op), lhsCalcOp, rhsCalcOp, 0, tokIdx));
        int finalOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, resPl, 0, calcType, tokIdx));
        if (calcType != destType)
        {
            finalOp = EmitCastToTemp(finalOp, destType, tokIdx, ref fctx, ref mir);
        }
        fctx.Emit(new MirInst(MirOp.AssignUse, destPl, -1, 0, destType, finalOp, 0, 0, 0, tokIdx));
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, destPl, 0, destType, tokIdx));
    }

    private static bool CanUseNaturalBranchType(int naturalType, int targetType,
        in AstArena ast, in TokenArena ta, in TypeTable types)
    {
        if (naturalType < 0 || naturalType == TypeIds.Error || naturalType == TypeIds.Void) return false;
        return ClassifyByValueConversion(-1, naturalType, targetType, in ast, in ta, in types) >= 0;
    }

    private static int LowerConditionalExpr(
        int exprId,
        in AstNode n,
        int expectedTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int tokIdx = n.TokIdx;
        int outerScope = fctx.ScopeDepth;
        int tBlk = fctx.NewBlock();
        int fBlk = fctx.NewBlock();
        int mBlk = fctx.NewBlock();

        int prevCondOverride = fctx.OutVarScopeOverride;
        if (fctx.OutVarScopeOverride <= 0) fctx.OutVarScopeOverride = outerScope;
        PushScope(ref fctx);
        LowerCondBranch(n.A, tBlk, fBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, hoistOutVarsToParentScope: false);

        // One inference of the whole conditional, so that the false arm is
        // typed in the scope of what the true arm declares (N110); its record
        // holds both arm types.
        fctx.InferDepth += 1;
        _ = InferExprType(exprId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        int armSlot = fctx.BranchFactsFor(exprId, 2);
        int t1 = fctx.BranchArmFacts[armSlot].TypeId;
        int t2 = fctx.BranchArmFacts[armSlot + 1].TypeId;
        int naturalType = NaturalConditionalType(t1, n.B, t2, n.C, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        fctx.LeaveSpeculativeInfer();
        bool hasTarget = expectedTypeId >= 0 && expectedTypeId != TypeIds.Void && expectedTypeId != TypeIds.Error;
        int resType;
        if (hasTarget)
        {
            // Unlike switch expressions, only conditionals without a natural
            // type may use a conversion of the individual branches. In
            // particular, a default next to Some<T> initializes Some<T>.
            resType = naturalType >= 0 && naturalType != TypeIds.Error ? naturalType : expectedTypeId;
        }
        else if (naturalType < 0 || naturalType == TypeIds.Error)
        {
            if (naturalType < 0)
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "The conditional expression has no natural type: neither branch type converts implicitly to the other, and there is no target type (CS0173)."u8);
            resType = MergeCommonBranchType(t1, n.B, t2, n.C, in fctx, in ast, in ta, in names, in bctx, ref types);
        }
        else resType = naturalType;

        int resTmp = fctx.AddLocal(-1, resType, PassMode.ByValue, MirLocalFlags.IsTemp, tokIdx);
        InsertScopeEntryAtDepth(ref fctx, outerScope, resTmp, tokIdx);
        int resPl = mir.AddPlaceLocal(resTmp, resType);

        fctx.CurBlock = tBlk;
        int tOp = LowerExprAsOperand(n.B, resType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, resType, tOp, 0, 0, 0, tokIdx));
        if (!fctx.IsBlockTerminated(fctx.CurBlock))
        {
            EmitScopeExitsDownTo(fctx.ScopeDepth, tokIdx, ref fctx, ref mir);
            fctx.Terminate(new MirTerm(MirTermKind.Goto, mBlk, 0, 0, 0, 0, 0, tokIdx));
        }

        fctx.CurBlock = fBlk;
        int fOp = LowerExprAsOperand(n.C, resType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, resType, fOp, 0, 0, 0, tokIdx));
        if (!fctx.IsBlockTerminated(fctx.CurBlock))
        {
            EmitScopeExitsDownTo(fctx.ScopeDepth, tokIdx, ref fctx, ref mir);
            fctx.Terminate(new MirTerm(MirTermKind.Goto, mBlk, 0, 0, 0, 0, 0, tokIdx));
        }
        PopScopeWithoutEmit(ref fctx);
        fctx.OutVarScopeOverride = prevCondOverride;

        fctx.CurBlock = mBlk;
        int result = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, resPl, 0, resType, tokIdx));
        if (hasTarget && resType != expectedTypeId)
            result = ConvertOperandIfNeeded(result, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, -1, false);
        return result;
    }

    // F17(C) is deliberately a source occurrence test, not MIR last-use
    // analysis. Visit all arms and operands, including ones that won't run.
    // Member names and named-argument labels are not local variable uses.
    private static bool RefRepointTargetNamesLocal(int nodeId, int nameId, bool rebindOnly, in AstArena ast)
    {
        if (nodeId < 0) return false;
        AstNode node = ast.Nodes[nodeId];
        if (rebindOnly && node.Kind == AstKind.ExprAssign && node.D != 0)
        {
            AstNode lhs = ast.Nodes[node.B];
            if (lhs.Kind == AstKind.ExprIdent && lhs.A == nameId && lhs.C == 0 && lhs.D == 0) return true;
        }
        switch (node.Kind)
        {
            case AstKind.ExprIdent:
                return !rebindOnly && node.A == nameId && node.C == 0 && node.D == 0;
            case AstKind.ExprMember:
            case AstKind.ExprFromEnd:
            case AstKind.PatNot:
            case AstKind.PatConst:
                return RefRepointTargetNamesLocal(node.A, nameId, rebindOnly, in ast);
            case AstKind.ExprCast:
            case AstKind.ExprUnary:
            case AstKind.PatRel:
                return RefRepointTargetNamesLocal(node.B, nameId, rebindOnly, in ast);
            case AstKind.CallArg:
                return node.C == -2 && RefRepointTargetNamesLocal(node.B, nameId, rebindOnly, in ast);
            case AstKind.PatUnion:
                return RefRepointTargetNamesLocal(node.D, nameId, rebindOnly, in ast);
            case AstKind.ExprRange:
            case AstKind.ExprIsPattern:
                return RefRepointTargetNamesLocal(node.A, nameId, rebindOnly, in ast) || RefRepointTargetNamesLocal(node.B, nameId, rebindOnly, in ast);
            case AstKind.ExprCond:
            case AstKind.SwitchArm:
                return RefRepointTargetNamesLocal(node.A, nameId, rebindOnly, in ast) ||
                    RefRepointTargetNamesLocal(node.B, nameId, rebindOnly, in ast) || RefRepointTargetNamesLocal(node.C, nameId, rebindOnly, in ast);
            case AstKind.ExprBinary:
            case AstKind.ExprAssign:
            case AstKind.PatLogic:
                return RefRepointTargetNamesLocal(node.B, nameId, rebindOnly, in ast) || RefRepointTargetNamesLocal(node.C, nameId, rebindOnly, in ast);
            case AstKind.ExprCall:
            case AstKind.ExprIndex:
            case AstKind.ExprSwitch:
                if (RefRepointTargetNamesLocal(node.A, nameId, rebindOnly, in ast)) return true;
                return RefRepointTargetsNameLocal(node.B, node.C, nameId, rebindOnly, in ast);
            case AstKind.ExprNew:
                return RefRepointTargetsNameLocal(node.B, node.C, nameId, rebindOnly, in ast);
            case AstKind.ExprCollLit:
                return RefRepointTargetsNameLocal(node.A, node.B, nameId, rebindOnly, in ast);
            default:
                return false;
        }
    }

    private static bool RefRepointTargetsNameLocal(int start, int count, int nameId, bool rebindOnly, in AstArena ast)
    {
        for (int i = 0; i < count; i++)
            if (RefRepointTargetNamesLocal(ast.Extra[start + i], nameId, rebindOnly, in ast)) return true;
        return false;
    }

    private static int LowerRefAssignPlace(
        in AstNode n,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags,
        out bool lhsIsMut)
    {
        int tokIdx = n.TokIdx;
        Token tok = ta.Tokens[tokIdx];
        lhsIsMut = false;

        AstNode lhs = ast.Nodes[n.B];
        int lhsLid = -1;
        bool isRefTarget = false;
        if (lhs.Kind == AstKind.ExprIdent && lhs.C == 0 && lhs.D == 0)
        {
            int found = fctx.FindVar(lhs.A, out bool isConst, out _, out _);
            if (found >= 0 && !isConst)
            {
                MirLocal loc = fctx.Locals[found];
                if ((loc.Flags & MirLocalFlags.IsParam) != 0)
                {
                    diags.ReportTok(VibCodes.Unsupported, tok, "Rebinding ref/in/out parameters is unsupported in Vibranium v0.2; use a local ref carrier."u8);
                    lhsIsMut = loc.Mode == PassMode.Ref || loc.Mode == PassMode.Out;
                    // Preserve an initialized recovery place without emitting an unsupported rebind.
                    return mir.AddPlaceLocal(found, loc.TypeId);
                }
                if ((loc.Flags & MirLocalFlags.IsRefLocal) != 0 && (loc.Flags & MirLocalFlags.IsForeachRef) == 0)
                {
                    lhsLid = found;
                    lhsIsMut = (loc.Flags & MirLocalFlags.IsRefMut) != 0;
                    isRefTarget = true;
                }
            }
        }

        if (!isRefTarget)
        {
            diags.ReportTok(VibCodes.Unsupported, tok, "The left-hand side of a ref assignment must be a ref local in Vibranium v0.2."u8);
            int badT = InferExprType(n.B, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            if (badT <= 0 || badT == TypeIds.Void) badT = TypeIds.I32;
            _ = LowerExprAsOperand(n.C, -1, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            int dummy = fctx.NewTemp(badT, tokIdx, ref mir);
            return mir.AddPlaceLocal(dummy, badT);
        }

        MirLocal lhsLoc = fctx.Locals[lhsLid];
        int lhsElemType = lhsLoc.TypeId;

        if (lhsIsMut)
        {
            int refInner = (ast.Nodes[n.C].Kind == AstKind.ExprUnary && (TokKind)ast.Nodes[n.C].A == TokKind.KwRef) ? ast.Nodes[n.C].B : n.C;
            CheckNotDirectCapturedPrimaryParamWrite(refInner, "Cannot take mutable reference to a captured primary-constructor parameter."u8, in fctx, in ast, in ta, in types, ref diags);
        }

        // Usually keeping the carrier live through the RHS suffices. A
        // nested assignment to the same carrier kills that liveness and
        // changes its loans; preserve the original loan set independently.
        int oldLoanCarrier = -1;
        if (RefRepointTargetNamesLocal(n.C, lhs.A, rebindOnly: false, in ast))
        {
            oldLoanCarrier = lhsLid;
            if (RefRepointTargetNamesLocal(n.C, lhs.A, rebindOnly: true, in ast))
            {
                int flags = MirLocalFlags.IsTemp | MirLocalFlags.IsRefLocal | MirLocalFlags.IsAnalysisBorrow | MirLocalFlags.IsRepointLoanSnapshot;
                oldLoanCarrier = fctx.AddLocal(-1, lhsElemType, PassMode.ByValue, flags, tokIdx);
                fctx.Emit(new MirInst(MirOp.SnapshotRefLoan, -1, oldLoanCarrier, 0, lhsElemType, oldLoanCarrier, lhsLid, 0, 0, tokIdx));
            }
        }
        int diagBeforeRhs = diags.Items.Count;
        int targetPl = LowerPlace(n.C, lhsIsMut, isTwoPhase: false, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        MirPlace rhsPlace = mir.Places[targetPl];
        int targetType = rhsPlace.TypeId;
        if (lhsIsMut) CheckSourceWritablePlace(targetPl, tokIdx, in fctx, in ta, in types, in mir, ref diags);

        if (diags.Items.Count == diagBeforeRhs &&
            rhsPlace.ProjCount == 0 &&
            rhsPlace.LocalId >= 0 &&
            (fctx.Locals[rhsPlace.LocalId].Flags & MirLocalFlags.IsTemp) != 0)
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[n.C].TokIdx], "An expression cannot be used in this context because it may not be passed or returned by reference."u8);
        }
        else if (types.IsView(targetType))
        {
            diags.ReportTok(VibCodes.Unsupported, tok, "Ref local cannot alias borrowed view in Vibranium."u8);
        }
        else if (types.IsLinear(targetType, in ast))
        {
            diags.ReportTok(VibCodes.LinearViolation, tok, "Ref local cannot alias linear IDisposable resource."u8);
        }
        else if (targetType != TypeIds.Error && lhsElemType != TypeIds.Error && targetType != lhsElemType)
        {
            diags.ReportTok(VibCodes.Unsupported, tok, "Ref assignment requires exact pointee type match."u8);
        }

        // Keep the old loan across every path evaluating the new target.
        EndBorrowWindow(oldLoanCarrier, tokIdx, ref fctx);
        fctx.Emit(new MirInst(MirOp.BindRef, -1, lhsLid, lhsIsMut ? 1 : 0, lhsElemType, lhsLid, targetPl, 0, 0, tokIdx));

        if ((lhsLoc.Flags & MirLocalFlags.IsRefLocal) != 0)
        {
            var deref = new Vec<MirProj>(1);
            deref.Push(new MirProj(MirProjKinds.Deref, 0, lhsElemType, -1, 0));
            return mir.AddPlace(lhsLid, deref.AsReadOnlySpan(), lhsElemType);
        }
        return mir.AddPlaceLocal(lhsLid, lhsElemType);
    }

    private static bool IsNonRefPropertyOrUserIndexerTarget(
        int exprId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags)
    {
        AstNode lhs = ast.Nodes[exprId];
        if (lhs.Kind == AstKind.ExprIdent)
        {
            int locV = fctx.FindVar(lhs.A, out bool isLocC, out _, out _);
            if (locV >= 0 || isLocC) return false;
            int curOwnerDecl = ast.Funcs[fctx.FuncDeclId].OwnerDeclId;
            for (int d = curOwnerDecl; d >= 0; d = ast.Types[d].OwnerDeclId)
            {
                TypeDecl otd = ast.Types[d];
                for (int f = 0; f < otd.FieldCount; f++)
                {
                    FieldDecl fd = ast.Fields[otd.FieldStart + f];
                    if (fd.NameId == lhs.A && (fd.Flags & DeclFlags.IsConst) != 0) return false;
                }
            }
            if (fctx.OwnerTypeId >= 0)
            {
                if (FindInstanceFieldIndex(fctx.OwnerTypeId, lhs.A, in types) >= 0) return false;
                int ownerDecl = types.Items[fctx.OwnerTypeId].A;
                int pGet = FindMethodInType(ownerDecl, MakePropGetterLookup(lhs.A, in ast, in names), 0, isStatic: false, in ast);
                if (pGet >= 0 && (ast.Funcs[pGet].Flags & DeclFlags.ReturnsByRef) == 0) return true;
            }
            for (int d = curOwnerDecl; d >= 0; d = ast.Types[d].OwnerDeclId)
            {
                if (d != curOwnerDecl && ast.Types[d].TypeParamCount > 0) continue;
                int sGet = FindMethodInType(d, MakePropGetterLookup(lhs.A, in ast, in names), 0, isStatic: true, in ast);
                if (sGet >= 0 && (ast.Funcs[sGet].Flags & DeclFlags.ReturnsByRef) == 0) return true;
            }
            return false;
        }
        if (lhs.Kind == AstKind.ExprMember)
        {
            if (TryResolveStaticTypeTarget(lhs.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int stDeclId, out _))
            {
                if (stDeclId >= 0)
                {
                    int sGet = FindMethodInType(stDeclId, MakePropGetterLookup(lhs.B, in ast, in names), 0, isStatic: true, in ast);
                    if (sGet >= 0 && (ast.Funcs[sGet].Flags & DeclFlags.ReturnsByRef) == 0) return true;
                }
                return false;
            }
            int recvT = InferExprType(lhs.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            TypeInfo rti = types.Items[recvT];
            if (rti.Kind == TypeKinds.Class || rti.Kind == TypeKinds.Struct)
            {
                if (FindInstanceFieldIndex(recvT, lhs.B, in types) >= 0) return false;
                int pGet = FindMethodInType(rti.A, MakePropGetterLookup(lhs.B, in ast, in names), 0, isStatic: false, in ast);
                if (pGet >= 0 && (ast.Funcs[pGet].Flags & DeclFlags.ReturnsByRef) == 0) return true;
            }
            return false;
        }
        if (lhs.Kind == AstKind.ExprIndex && !(lhs.D >= 0 && ast.Nodes[lhs.D].Kind == AstKind.ExprRange))
        {
            int collT = InferExprType(lhs.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            TypeInfo cti = types.Items[collT];
            if (cti.Kind == TypeKinds.Struct || cti.Kind == TypeKinds.Class)
            {
                if (TryResolveUserIndexer(collT, in lhs, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int idxGet, out _, out _, out _, out _))
                {
                    return idxGet < 0 || (ast.Funcs[idxGet].Flags & DeclFlags.ReturnsByRef) == 0;
                }
            }
        }
        return false;
    }

    private static bool SatisfiesClassConstraint(int typeId, in FuncLowerCtx fctx, in AstArena ast, in TypeTable types)
    {
        if (typeId == TypeIds.Error || typeId == TypeIds.Str) return true;
        TypeInfo ti = types.Items[typeId];
        if (ti.Kind == TypeKinds.Class) return true;
        if (ti.Kind == TypeKinds.TypeParam)
        {
            int tpNameId = ti.B;
            if (fctx.FuncDeclId >= 0)
            {
                FuncDecl fd = ast.Funcs[fctx.FuncDeclId];
                for (int i = 0; i < fd.TypeParamCount; i++)
                {
                    if (ast.Extra[fd.TypeParamStart + i] == tpNameId)
                    {
                        return (ast.Extra[fd.TypeParamFlagsStart + i] & DeclFlags.ClassConstraint) != 0;
                    }
                }
            }
            int ownerDecl = fctx.EnclosingOwnerDeclId >= 0 ? fctx.EnclosingOwnerDeclId : (fctx.FuncDeclId >= 0 ? ast.Funcs[fctx.FuncDeclId].OwnerDeclId : -1);
            for (int d = ownerDecl; d >= 0; d = ast.Types[d].OwnerDeclId)
            {
                TypeDecl td = ast.Types[d];
                for (int i = 0; i < td.TypeParamCount; i++)
                {
                    if (ast.Extra[td.TypeParamStart + i] == tpNameId)
                    {
                        return (ast.Extra[td.TypeParamFlagsStart + i] & DeclFlags.ClassConstraint) != 0;
                    }
                }
            }
        }
        return false;
    }

    private readonly struct UInterval
    {
        public readonly ulong Lo;
        public readonly ulong Hi;

        public UInterval(ulong lo, ulong hi)
        {
            Lo = lo;
            Hi = hi;
        }
    }

    private static ulong IntValToOrd(long v, bool isUnsigned) =>
        isUnsigned ? (ulong)v : ((ulong)v ^ 0x8000000000000000UL);

    private static void GetIntTypeOrdDomain(int effIntTid, out bool isUnsigned, out ulong domLo, out ulong domHi)
    {
        switch (effIntTid)
        {
            case TypeIds.U8:
                isUnsigned = true; domLo = 0UL; domHi = 255UL; return;
            case TypeIds.U16:
            case TypeIds.Char:
                isUnsigned = true; domLo = 0UL; domHi = 65535UL; return;
            case TypeIds.U32:
                isUnsigned = true; domLo = 0UL; domHi = 4294967295UL; return;
            case TypeIds.U64:
            case TypeIds.NUInt:
                isUnsigned = true; domLo = 0UL; domHi = ulong.MaxValue; return;
            case TypeIds.I8:
                isUnsigned = false; domLo = IntValToOrd(-128L, false); domHi = IntValToOrd(127L, false); return;
            case TypeIds.I16:
                isUnsigned = false; domLo = IntValToOrd(-32768L, false); domHi = IntValToOrd(32767L, false); return;
            case TypeIds.I32:
                isUnsigned = false; domLo = IntValToOrd(-2147483648L, false); domHi = IntValToOrd(2147483647L, false); return;
            default:
                isUnsigned = false; domLo = 0UL; domHi = ulong.MaxValue; return;
        }
    }

    private static void AddCoalescedInterval(ulong lo, ulong hi, ref Vec<UInterval> list)
    {
        if (lo > hi) return;
        var merged = new Vec<UInterval>(list.Count + 1);
        bool placed = false;
        ulong curLo = lo;
        ulong curHi = hi;
        for (int i = 0; i < list.Count; i++)
        {
            UInterval it = list[i];
            if (!placed)
            {
                if (it.Hi < curLo && it.Hi + 1UL < curLo)
                {
                    merged.Push(it);
                }
                else if (curHi < it.Lo && curHi + 1UL < it.Lo)
                {
                    merged.Push(new UInterval(curLo, curHi));
                    merged.Push(it);
                    placed = true;
                }
                else
                {
                    if (it.Lo < curLo) curLo = it.Lo;
                    if (it.Hi > curHi) curHi = it.Hi;
                }
            }
            else
            {
                merged.Push(it);
            }
        }
        if (!placed) merged.Push(new UInterval(curLo, curHi));
        list.Clear();
        for (int i = 0; i < merged.Count; i++) list.Push(merged[i]);
    }

    private static void UnionIntervalsInto(in Vec<UInterval> src, ref Vec<UInterval> dst)
    {
        for (int i = 0; i < src.Count; i++)
        {
            AddCoalescedInterval(src[i].Lo, src[i].Hi, ref dst);
        }
    }

    private static void IntersectIntervals(in Vec<UInterval> a, in Vec<UInterval> b, ref Vec<UInterval> outSet)
    {
        outSet.Clear();
        for (int i = 0; i < a.Count; i++)
        {
            for (int j = 0; j < b.Count; j++)
            {
                ulong lo = a[i].Lo > b[j].Lo ? a[i].Lo : b[j].Lo;
                ulong hi = a[i].Hi < b[j].Hi ? a[i].Hi : b[j].Hi;
                if (lo <= hi) AddCoalescedInterval(lo, hi, ref outSet);
            }
        }
    }

    private static void ComplementIntervals(in Vec<UInterval> a, ulong domLo, ulong domHi, ref Vec<UInterval> outSet)
    {
        outSet.Clear();
        ulong cursor = domLo;
        for (int i = 0; i < a.Count; i++)
        {
            UInterval it = a[i];
            if (it.Hi < cursor) continue;
            if (it.Lo > cursor)
            {
                ulong end = it.Lo - 1UL;
                if (end > domHi) end = domHi;
                if (cursor <= end) outSet.Push(new UInterval(cursor, end));
            }
            if (it.Hi >= domHi) return;
            cursor = it.Hi + 1UL;
        }
        if (cursor <= domHi)
        {
            outSet.Push(new UInterval(cursor, domHi));
        }
    }

    private static bool IsSameTypePatternMatch(
        int patNodeId,
        int scrutTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types)
    {
        if (patNodeId == -2) return true;
        if (patNodeId < 0) return false;
        AstNode pat = ast.Nodes[patNodeId];
        if (pat.Kind == AstKind.PatWildcard) return true;
        if (pat.Kind == AstKind.PatDecl)
        {
            if (pat.C != 0) return false;
            if (pat.A < 0) return true;
            var discardDiags = new DiagnosticBag(0);
            int dt = DeclBinder.ResolveTypeNode(pat.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref discardDiags, reportLinearErrors: false);
            return discardDiags.Items.Count == 0 && dt == scrutTypeId;
        }
        if (pat.Kind == AstKind.PatConst && pat.B == 0)
        {
            var discardDiags = new DiagnosticBag(0);
            if (TryResolveStaticTypeTarget(pat.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref discardDiags, out _, out int bt) &&
                discardDiags.Items.Count == 0 && bt >= 0 && bt == scrutTypeId)
            {
                return true;
            }
        }
        return false;
    }

    private static void EvaluateBoolPatternMustMay(
        int patNodeId,
        int curOwner,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        out bool mustT,
        out bool mustF,
        out bool mayT,
        out bool mayF)
    {
        if (IsSameTypePatternMatch(patNodeId, TypeIds.Bool, ref fctx, in ast, in ta, in names, ref bctx, ref types))
        {
            mustT = true; mustF = true; mayT = true; mayF = true;
            return;
        }
        if (patNodeId <= -10)
        {
            EvaluateBoolPatternMustMay(-(patNodeId + 10), curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, out bool nMustT, out bool nMustF, out bool nMayT, out bool nMayF);
            mustT = !nMayT;
            mustF = !nMayF;
            mayT = !nMustT;
            mayF = !nMustF;
            return;
        }
        mustT = false; mustF = false; mayT = true; mayF = true;
        if (patNodeId < 0) return;
        AstNode pat = ast.Nodes[patNodeId];
        switch (pat.Kind)
        {
            case AstKind.PatDecl:
                mustT = false; mustF = false; mayT = false; mayF = false;
                return;
            case AstKind.PatConst:
            {
                if (TryEvalBoolConstExpr(pat.A, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out bool bv))
                {
                    mustT = bv; mayT = bv;
                    mustF = !bv; mayF = !bv;
                }
                return;
            }
            case AstKind.PatNot:
            {
                EvaluateBoolPatternMustMay(pat.A, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, out bool sMustT, out bool sMustF, out bool sMayT, out bool sMayF);
                mustT = !sMayT;
                mustF = !sMayF;
                mayT = !sMustT;
                mayF = !sMustF;
                return;
            }
            case AstKind.PatLogic:
            {
                EvaluateBoolPatternMustMay(pat.B, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, out bool lMustT, out bool lMustF, out bool lMayT, out bool lMayF);
                EvaluateBoolPatternMustMay(pat.C, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, out bool rMustT, out bool rMustF, out bool rMayT, out bool rMayF);
                if (pat.A == 0)
                {
                    mustT = lMustT && rMustT;
                    mustF = lMustF && rMustF;
                    mayT = lMayT && rMayT;
                    mayF = lMayF && rMayF;
                }
                else
                {
                    mustT = lMustT || rMustT;
                    mustF = lMustF || rMustF;
                    mayT = lMayT || rMayT;
                    mayF = lMayF || rMayF;
                }
                return;
            }
        }
    }

    private static void EvaluateIntPatternMustMay(
        int patNodeId,
        int scrutTypeId,
        int effIntTid,
        bool isUnsigned,
        ulong domLo,
        ulong domHi,
        int curOwner,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref Vec<UInterval> mustSet,
        ref Vec<UInterval> maySet)
    {
        mustSet.Clear();
        maySet.Clear();
        if (IsSameTypePatternMatch(patNodeId, scrutTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types))
        {
            mustSet.Push(new UInterval(domLo, domHi));
            maySet.Push(new UInterval(domLo, domHi));
            return;
        }
        if (patNodeId <= -10)
        {
            var synMust = new Vec<UInterval>();
            var synMay = new Vec<UInterval>();
            EvaluateIntPatternMustMay(-(patNodeId + 10), scrutTypeId, effIntTid, isUnsigned, domLo, domHi, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref synMust, ref synMay);
            ComplementIntervals(in synMay, domLo, domHi, ref mustSet);
            ComplementIntervals(in synMust, domLo, domHi, ref maySet);
            return;
        }
        if (patNodeId < 0)
        {
            maySet.Push(new UInterval(domLo, domHi));
            return;
        }
        AstNode pat = ast.Nodes[patNodeId];
        switch (pat.Kind)
        {
            case AstKind.PatDecl:
                return;
            case AstKind.PatConst:
            {
                if (TryEvalTypedIntConstExpr(pat.A, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out int cSrcTid, out long cVal) &&
                    ConstantFitsInExplicitIntTarget(UnderlyingIntOrSelf(cSrcTid, in types), cVal, effIntTid, in types))
                {
                    ulong ord = IntValToOrd(TruncateConstToType(cVal, effIntTid), isUnsigned);
                    mustSet.Push(new UInterval(ord, ord));
                    maySet.Push(new UInterval(ord, ord));
                }
                else
                {
                    maySet.Push(new UInterval(domLo, domHi));
                }
                return;
            }
            case AstKind.PatRel:
            {
                if (TryEvalTypedIntConstExpr(pat.B, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out int cSrcTid, out long cVal) &&
                    ConstantFitsInExplicitIntTarget(UnderlyingIntOrSelf(cSrcTid, in types), cVal, effIntTid, in types))
                {
                    ulong ord = IntValToOrd(TruncateConstToType(cVal, effIntTid), isUnsigned);
                    TokKind rk = (TokKind)pat.A;
                    if (rk == TokKind.LAngle)
                    {
                        if (ord > domLo)
                        {
                            mustSet.Push(new UInterval(domLo, ord - 1UL));
                            maySet.Push(new UInterval(domLo, ord - 1UL));
                        }
                    }
                    else if (rk == TokKind.LtEq)
                    {
                        mustSet.Push(new UInterval(domLo, ord));
                        maySet.Push(new UInterval(domLo, ord));
                    }
                    else if (rk == TokKind.RAngle)
                    {
                        if (ord < domHi)
                        {
                            mustSet.Push(new UInterval(ord + 1UL, domHi));
                            maySet.Push(new UInterval(ord + 1UL, domHi));
                        }
                    }
                    else if (rk == TokKind.GtEq)
                    {
                        mustSet.Push(new UInterval(ord, domHi));
                        maySet.Push(new UInterval(ord, domHi));
                    }
                }
                else
                {
                    maySet.Push(new UInterval(domLo, domHi));
                }
                return;
            }
            case AstKind.PatNot:
            {
                var subMust = new Vec<UInterval>();
                var subMay = new Vec<UInterval>();
                EvaluateIntPatternMustMay(pat.A, scrutTypeId, effIntTid, isUnsigned, domLo, domHi, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref subMust, ref subMay);
                ComplementIntervals(in subMay, domLo, domHi, ref mustSet);
                ComplementIntervals(in subMust, domLo, domHi, ref maySet);
                return;
            }
            case AstKind.PatLogic:
            {
                var lMust = new Vec<UInterval>();
                var lMay = new Vec<UInterval>();
                var rMust = new Vec<UInterval>();
                var rMay = new Vec<UInterval>();
                EvaluateIntPatternMustMay(pat.B, scrutTypeId, effIntTid, isUnsigned, domLo, domHi, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref lMust, ref lMay);
                EvaluateIntPatternMustMay(pat.C, scrutTypeId, effIntTid, isUnsigned, domLo, domHi, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref rMust, ref rMay);
                if (pat.A == 0)
                {
                    IntersectIntervals(in lMust, in rMust, ref mustSet);
                    IntersectIntervals(in lMay, in rMay, ref maySet);
                }
                else
                {
                    UnionIntervalsInto(in lMust, ref mustSet);
                    UnionIntervalsInto(in rMust, ref mustSet);
                    UnionIntervalsInto(in lMay, ref maySet);
                    UnionIntervalsInto(in rMay, ref maySet);
                }
                return;
            }
            default:
                maySet.Push(new UInterval(domLo, domHi));
                return;
        }
    }

    private static bool TryEvalFloatPatternConstBits(
        int exprId,
        bool isSingle,
        int curOwner,
        in FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        in BinderCtx bctx,
        in TypeTable types,
        out bool isNaN,
        out ulong ordVal,
        ulong zeroOrd)
    {
        isNaN = false;
        ordVal = 0UL;
        if (isSingle)
        {
            if (TryEvalFloatConstExpr(exprId, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out int ft, out double dv))
            {
                if (ft != TypeIds.F32) return false;
                float f = (float)dv;
                uint fbits = (uint)FloatToBits(f);
                if ((fbits & 0x7F800000U) == 0x7F800000U && (fbits & 0x007FFFFFU) != 0U)
                {
                    isNaN = true;
                    return true;
                }
                if ((fbits & 0x7FFFFFFFU) == 0U) fbits = 0U;
                ordVal = (fbits & 0x80000000U) != 0U ? (zeroOrd - (ulong)(fbits & 0x7FFFFFFFU)) : (zeroOrd + (ulong)fbits);
                return true;
            }
            if (TryEvalTypedIntConstExpr(exprId, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out int it, out long iv) &&
                types.Items[it].Kind != TypeKinds.Enum)
            {
                uint fbits = types.IsUnsignedInteger(it)
                    ? (uint)DeclBinder.ULongToSingleBits((ulong)iv)
                    : (uint)DeclBinder.LongToSingleBits(iv);
                if ((fbits & 0x7FFFFFFFU) == 0U) fbits = 0U;
                ordVal = (fbits & 0x80000000U) != 0U ? (zeroOrd - (ulong)(fbits & 0x7FFFFFFFU)) : (zeroOrd + (ulong)fbits);
                return true;
            }
            return false;
        }
        else
        {
            if (!TryEvalFloatConstOrIntAsFloat(exprId, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out _, out double dv))
            {
                return false;
            }
            ulong bits = (ulong)DoubleToBits(dv);
            if ((bits & 0x7FF0000000000000UL) == 0x7FF0000000000000UL && (bits & 0x000FFFFFFFFFFFFFUL) != 0UL)
            {
                isNaN = true;
                return true;
            }
            if ((bits & 0x7FFFFFFFFFFFFFFFUL) == 0UL) bits = 0UL;
            ordVal = (bits & 0x8000000000000000UL) != 0UL ? (zeroOrd - (bits & 0x7FFFFFFFFFFFFFFFUL)) : (zeroOrd + bits);
            return true;
        }
    }

    private static void EvaluateFloatPatternMustMay(
        int patNodeId,
        int scrutTypeId,
        bool isSingle,
        ulong zeroOrd,
        ulong domLo,
        ulong domHi,
        int curOwner,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref Vec<UInterval> mustSet,
        ref Vec<UInterval> maySet,
        out bool mustNaN,
        out bool mayNaN)
    {
        mustSet.Clear();
        maySet.Clear();
        mustNaN = false;
        mayNaN = false;
        if (IsSameTypePatternMatch(patNodeId, scrutTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types))
        {
            mustSet.Push(new UInterval(domLo, domHi));
            maySet.Push(new UInterval(domLo, domHi));
            mustNaN = true;
            mayNaN = true;
            return;
        }
        if (patNodeId <= -10)
        {
            var synMust = new Vec<UInterval>();
            var synMay = new Vec<UInterval>();
            EvaluateFloatPatternMustMay(-(patNodeId + 10), scrutTypeId, isSingle, zeroOrd, domLo, domHi, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref synMust, ref synMay, out bool sMustNaN, out bool sMayNaN);
            ComplementIntervals(in synMay, domLo, domHi, ref mustSet);
            ComplementIntervals(in synMust, domLo, domHi, ref maySet);
            mustNaN = !sMayNaN;
            mayNaN = !sMustNaN;
            return;
        }
        if (patNodeId < 0)
        {
            maySet.Push(new UInterval(domLo, domHi));
            mayNaN = true;
            return;
        }
        AstNode pat = ast.Nodes[patNodeId];
        switch (pat.Kind)
        {
            case AstKind.PatDecl:
                return;
            case AstKind.PatConst:
            {
                if (TryEvalFloatPatternConstBits(pat.A, isSingle, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out bool cIsNaN, out ulong ord, zeroOrd))
                {
                    if (cIsNaN)
                    {
                        mustNaN = true;
                        mayNaN = true;
                    }
                    else
                    {
                        mustSet.Push(new UInterval(ord, ord));
                        maySet.Push(new UInterval(ord, ord));
                    }
                }
                else
                {
                    maySet.Push(new UInterval(domLo, domHi));
                    mayNaN = true;
                }
                return;
            }
            case AstKind.PatRel:
            {
                if (TryEvalFloatPatternConstBits(pat.B, isSingle, curOwner, in fctx, in ast, in ta, in names, in bctx, in types, out bool cIsNaN, out ulong ord, zeroOrd))
                {
                    if (!cIsNaN)
                    {
                        TokKind rk = (TokKind)pat.A;
                        if (rk == TokKind.LAngle)
                        {
                            if (ord > domLo)
                            {
                                mustSet.Push(new UInterval(domLo, ord - 1UL));
                                maySet.Push(new UInterval(domLo, ord - 1UL));
                            }
                        }
                        else if (rk == TokKind.LtEq)
                        {
                            mustSet.Push(new UInterval(domLo, ord));
                            maySet.Push(new UInterval(domLo, ord));
                        }
                        else if (rk == TokKind.RAngle)
                        {
                            if (ord < domHi)
                            {
                                mustSet.Push(new UInterval(ord + 1UL, domHi));
                                maySet.Push(new UInterval(ord + 1UL, domHi));
                            }
                        }
                        else if (rk == TokKind.GtEq)
                        {
                            mustSet.Push(new UInterval(ord, domHi));
                            maySet.Push(new UInterval(ord, domHi));
                        }
                    }
                }
                else
                {
                    maySet.Push(new UInterval(domLo, domHi));
                    mayNaN = true;
                }
                return;
            }
            case AstKind.PatNot:
            {
                var subMust = new Vec<UInterval>();
                var subMay = new Vec<UInterval>();
                EvaluateFloatPatternMustMay(pat.A, scrutTypeId, isSingle, zeroOrd, domLo, domHi, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref subMust, ref subMay, out bool subMustNaN, out bool subMayNaN);
                ComplementIntervals(in subMay, domLo, domHi, ref mustSet);
                ComplementIntervals(in subMust, domLo, domHi, ref maySet);
                mustNaN = !subMayNaN;
                mayNaN = !subMustNaN;
                return;
            }
            case AstKind.PatLogic:
            {
                var lMust = new Vec<UInterval>();
                var lMay = new Vec<UInterval>();
                var rMust = new Vec<UInterval>();
                var rMay = new Vec<UInterval>();
                EvaluateFloatPatternMustMay(pat.B, scrutTypeId, isSingle, zeroOrd, domLo, domHi, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref lMust, ref lMay, out bool lMustNaN, out bool lMayNaN);
                EvaluateFloatPatternMustMay(pat.C, scrutTypeId, isSingle, zeroOrd, domLo, domHi, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref rMust, ref rMay, out bool rMustNaN, out bool rMayNaN);
                if (pat.A == 0)
                {
                    IntersectIntervals(in lMust, in rMust, ref mustSet);
                    IntersectIntervals(in lMay, in rMay, ref maySet);
                    mustNaN = lMustNaN && rMustNaN;
                    mayNaN = lMayNaN && rMayNaN;
                }
                else
                {
                    UnionIntervalsInto(in lMust, ref mustSet);
                    UnionIntervalsInto(in rMust, ref mustSet);
                    UnionIntervalsInto(in lMay, ref maySet);
                    UnionIntervalsInto(in rMay, ref maySet);
                    mustNaN = lMustNaN || rMustNaN;
                    mayNaN = lMayNaN || rMayNaN;
                }
                return;
            }
            default:
                maySet.Push(new UInterval(domLo, domHi));
                mayNaN = true;
                return;
        }
    }

    private static void ExpandTopOrPatterns(int patId, int scrutTypeId, ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref Vec<int> expanded)
    {
        if (patId == -2 || patId <= -10)
        {
            expanded.Push(patId);
            return;
        }
        if (patId < 0) return;
        AstNode p = ast.Nodes[patId];
        if (p.Kind == AstKind.PatLogic && p.A != 0)
        {
            ExpandTopOrPatterns(p.B, scrutTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref expanded);
            ExpandTopOrPatterns(p.C, scrutTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref expanded);
            return;
        }
        if (p.Kind == AstKind.PatLogic && p.A == 0)
        {
            if (IsSameTypePatternMatch(p.B, scrutTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types))
            {
                ExpandTopOrPatterns(p.C, scrutTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref expanded);
                return;
            }
            if (IsSameTypePatternMatch(p.C, scrutTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types))
            {
                ExpandTopOrPatterns(p.B, scrutTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref expanded);
                return;
            }
        }
        expanded.Push(patId);
    }

    private static bool IntervalsCovered(in Vec<UInterval> candidate, in Vec<UInterval> covered)
    {
        for (int i = 0; i < candidate.Count; i++)
        {
            bool contained = false;
            for (int j = 0; j < covered.Count; j++)
            {
                if (candidate[i].Lo >= covered[j].Lo && candidate[i].Hi <= covered[j].Hi)
                {
                    contained = true;
                    break;
                }
            }
            if (!contained) return false;
        }
        return true;
    }

    private static bool AccumulateSourcePayloadCoverage(int patternId, int payloadType, bool contributes,
        ref Vec<UInterval> covered, ref int coveredFlags, ref FuncLowerCtx fctx,
        in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types)
    {
        // Flags: true, false, NaN, and the entire declared payload domain.
        int owner = fctx.EnclosingOwnerDeclId;
        bool boolean = payloadType == TypeIds.Bool;
        bool integer = types.IsInteger(payloadType);
        bool floating = payloadType == TypeIds.F32 || payloadType == TypeIds.F64;
        if (!boolean && !integer && !floating)
        {
            bool unreachable = (coveredFlags & 8) != 0;
            bool catchAll = patternId == -2;
            if (patternId >= 0)
            {
                AstNode pattern = ast.Nodes[patternId];
                catchAll = pattern.Kind == AstKind.PatWildcard || (pattern.Kind == AstKind.PatDecl && pattern.A < 0);
            }
            if (contributes && catchAll) coveredFlags |= 8;
            return unreachable;
        }
        if (boolean)
        {
            EvaluateBoolPatternMustMay(patternId, owner, ref fctx, in ast, in ta, in names, ref bctx, ref types,
                out bool mustTrue, out bool mustFalse, out bool mayTrue, out bool mayFalse);
            bool unreachable = (!mayTrue || (coveredFlags & 1) != 0) && (!mayFalse || (coveredFlags & 2) != 0);
            if (contributes)
            {
                if (mustTrue) coveredFlags |= 1;
                if (mustFalse) coveredFlags |= 2;
                if ((coveredFlags & 3) == 3) coveredFlags |= 8;
            }
            return unreachable;
        }
        int effectiveInteger = integer ? UnderlyingIntOrSelf(payloadType, in types) : TypeIds.I32;
        GetIntTypeOrdDomain(effectiveInteger, out bool unsigned, out ulong domainLo, out ulong domainHi);
        bool single = payloadType == TypeIds.F32;
        ulong zeroOrder = single ? 0x7F800000UL : 0x7FF0000000000000UL;
        if (floating) { domainLo = 0UL; domainHi = zeroOrder * 2UL; }
        var must = new Vec<UInterval>();
        var may = new Vec<UInterval>();
        bool mustNaN = false;
        bool mayNaN = false;
        if (integer)
        {
            EvaluateIntPatternMustMay(patternId, payloadType, effectiveInteger, unsigned, domainLo, domainHi,
                owner, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref must, ref may);
        }
        else
        {
            EvaluateFloatPatternMustMay(patternId, payloadType, single, zeroOrder, domainLo, domainHi,
                owner, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref must, ref may, out mustNaN, out mayNaN);
        }
        bool subsumed = IntervalsCovered(in may, in covered) && (!mayNaN || (coveredFlags & 4) != 0);
        if (contributes)
        {
            UnionIntervalsInto(in must, ref covered);
            if (mustNaN) coveredFlags |= 4;
            if (covered.Count == 1 && covered[0].Lo == domainLo && covered[0].Hi == domainHi && (!floating || (coveredFlags & 4) != 0)) coveredFlags |= 8;
        }
        return subsumed;
    }

    private static void CheckSourceScalarPatternCoverage(in AstNode statement, int scrutType, bool expression,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names,
        ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        TypeInfo sourceType = types.Items[scrutType];
        bool union = sourceType.Kind == TypeKinds.Option || sourceType.Kind == TypeKinds.OptionRef ||
            sourceType.Kind == TypeKinds.OptionMut || sourceType.Kind == TypeKinds.Result;
        // This is the full declared source type domain, never the optimized selector.
        var patterns = new Vec<int>();
        var guards = new Vec<int>();
        for (int i = 0; i < statement.C; i++)
        {
            AstNode entry = ast.Nodes[ast.Extra[statement.B + i]];
            if (expression)
            {
                patterns.Push(entry.A);
                guards.Push(entry.C);
            }
            else
            {
                for (int j = 0; j < entry.B; j++)
                {
                    AstNode label = ast.Nodes[ast.Extra[entry.A + j]];
                    if (label.A < 0) continue; // default is selected after all case labels
                    patterns.Push(label.A);
                    guards.Push(label.B);
                }
            }
        }

        var covered = new Vec<UInterval>();
        var firstCovered = new Vec<UInterval>();
        var secondCovered = new Vec<UInterval>();
        int coveredFlags = 0;
        int firstFlags = 0;
        int secondFlags = 0;
        for (int i = 0; i < patterns.Count; i++)
        {
            bool contributes = IsSourceUnguardedPattern(patterns[i], guards[i], ref fctx, in ast, in ta, in names, in bctx, in types);
            bool unreachable;
            if (union)
            {
                // Each supported variant has its own declared payload domain;
                // Some(>0) cannot cover None, and Ok cannot cover Err.
                unreachable = (coveredFlags & 8) != 0;
                AstNode pattern = ast.Nodes[patterns[i]];
                if (pattern.Kind == AstKind.PatUnion)
                {
                    int head = ast.Nodes[pattern.A].A;
                    bool first = sourceType.Kind == TypeKinds.Result ? head == bctx.IdOk : head == bctx.IdSome;
                    bool second = sourceType.Kind == TypeKinds.Result ? head == bctx.IdErr : head == bctx.IdNoneType || head == bctx.IdNone;
                    int payloadPattern = pattern.D >= 0 ? pattern.D : -2;
                    if (first)
                        unreachable = AccumulateSourcePayloadCoverage(payloadPattern, sourceType.A, contributes,
                            ref firstCovered, ref firstFlags, ref fctx, in ast, in ta, in names, ref bctx, ref types) || unreachable;
                    else if (second)
                        unreachable = AccumulateSourcePayloadCoverage(payloadPattern, sourceType.Kind == TypeKinds.Result ? sourceType.B : TypeIds.NoneUnit, contributes,
                            ref secondCovered, ref secondFlags, ref fctx, in ast, in ta, in names, ref bctx, ref types) || unreachable;
                }
                else if (contributes && (pattern.Kind == AstKind.PatWildcard || (pattern.Kind == AstKind.PatDecl && pattern.A < 0))) coveredFlags |= 8;
            }
            else
            {
                unreachable = AccumulateSourcePayloadCoverage(patterns[i], scrutType, contributes,
                    ref covered, ref coveredFlags, ref fctx, in ast, in ta, in names, ref bctx, ref types);
            }
            if (unreachable)
            {
                diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[patterns[i]].TokIdx], expression
                    ? "C# switch expression pattern is impossible or already covered by previous unguarded arms (CS8510)."u8
                    : "C# switch case is impossible or already covered by previous unguarded cases (CS8120)."u8);
            }
        }
    }

    private static bool IsPatternSetExhaustive(
        ReadOnlySpan<int> unguardedPats,
        int scrutTypeId,
        int curOwner,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types)
    {
        if (unguardedPats.Length == 0) return false;

        var expanded = new Vec<int>(unguardedPats.Length);
        for (int i = 0; i < unguardedPats.Length; i++)
        {
            ExpandTopOrPatterns(unguardedPats[i], scrutTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref expanded);
        }
        for (int i = 0; i < expanded.Count; i++)
        {
            if (IsSameTypePatternMatch(expanded[i], scrutTypeId, ref fctx, in ast, in ta, in names, ref bctx, ref types))
            {
                return true;
            }
        }

        if (scrutTypeId == TypeIds.NoneUnit)
        {
            return expanded.Count > 0;
        }

        if (scrutTypeId == TypeIds.Bool)
        {
            bool covT = false;
            bool covF = false;
            for (int i = 0; i < expanded.Count; i++)
            {
                EvaluateBoolPatternMustMay(expanded[i], curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, out bool mT, out bool mF, out _, out _);
                covT = covT || mT;
                covF = covF || mF;
                if (covT && covF) return true;
            }
            return false;
        }

        if (types.IsInteger(scrutTypeId))
        {
            int effIntTid = UnderlyingIntOrSelf(scrutTypeId, in types);
            GetIntTypeOrdDomain(effIntTid, out bool isUns, out ulong domLo, out ulong domHi);
            var covered = new Vec<UInterval>(4);
            var patMust = new Vec<UInterval>(2);
            var patMay = new Vec<UInterval>(2);
            for (int i = 0; i < expanded.Count; i++)
            {
                EvaluateIntPatternMustMay(expanded[i], scrutTypeId, effIntTid, isUns, domLo, domHi, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref patMust, ref patMay);
                UnionIntervalsInto(in patMust, ref covered);
                if (covered.Count == 1 && covered[0].Lo == domLo && covered[0].Hi == domHi)
                {
                    return true;
                }
            }
            return false;
        }

        if (scrutTypeId == TypeIds.F32 || scrutTypeId == TypeIds.F64)
        {
            bool isSingle = scrutTypeId == TypeIds.F32;
            ulong zeroOrd = isSingle ? 0x7F800000UL : 0x7FF0000000000000UL;
            ulong domLo = 0UL;
            ulong domHi = zeroOrd * 2UL;
            var covered = new Vec<UInterval>(4);
            var patMust = new Vec<UInterval>(2);
            var patMay = new Vec<UInterval>(2);
            bool covNaN = false;
            for (int i = 0; i < expanded.Count; i++)
            {
                EvaluateFloatPatternMustMay(expanded[i], scrutTypeId, isSingle, zeroOrd, domLo, domHi, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref patMust, ref patMay, out bool mustNaN, out _);
                UnionIntervalsInto(in patMust, ref covered);
                covNaN = covNaN || mustNaN;
                if (covNaN && covered.Count == 1 && covered[0].Lo == domLo && covered[0].Hi == domHi)
                {
                    return true;
                }
            }
            return false;
        }

        TypeInfo sti = types.Items[scrutTypeId];
        if (sti.Kind == TypeKinds.Option || sti.Kind == TypeKinds.OptionRef || sti.Kind == TypeKinds.OptionMut || sti.Kind == TypeKinds.Result)
        {
            int v1Type = sti.A;
            int v2Type = sti.Kind == TypeKinds.Result ? sti.B : TypeIds.NoneUnit;
            var v1Pats = new Vec<int>();
            var v2Pats = new Vec<int>();
            for (int i = 0; i < expanded.Count; i++)
            {
                int pid = expanded[i];
                if (pid <= -10)
                {
                    int innerNegId = -(pid + 10);
                    if (innerNegId >= 0 && ast.Nodes[innerNegId].Kind == AstKind.PatUnion)
                    {
                        AstNode np = ast.Nodes[innerNegId];
                        int head = ast.Nodes[np.A].A;
                        bool isFirst = sti.Kind == TypeKinds.Result ? (head == bctx.IdOk) : (head == bctx.IdSome);
                        bool isSecond = sti.Kind == TypeKinds.Result ? (head == bctx.IdErr) : (head == bctx.IdNoneType || head == bctx.IdNone);
                        if (isFirst)
                        {
                            v2Pats.Push(-2);
                            if (np.D >= 0) v1Pats.Push(-(np.D + 10));
                        }
                        else if (isSecond)
                        {
                            v1Pats.Push(-2);
                            if (np.D >= 0) v2Pats.Push(-(np.D + 10));
                        }
                    }
                    continue;
                }
                if (pid < 0) continue;
                AstNode p = ast.Nodes[pid];
                if (p.Kind == AstKind.PatUnion)
                {
                    int head = ast.Nodes[p.A].A;
                    bool isFirst = sti.Kind == TypeKinds.Result ? (head == bctx.IdOk) : (head == bctx.IdSome);
                    bool isSecond = sti.Kind == TypeKinds.Result ? (head == bctx.IdErr) : (head == bctx.IdNoneType || head == bctx.IdNone);
                    if (isFirst) v1Pats.Push(p.D >= 0 ? p.D : -2);
                    else if (isSecond) v2Pats.Push(p.D >= 0 ? p.D : -2);
                }
                else if (p.Kind == AstKind.PatNot && p.A >= 0 && ast.Nodes[p.A].Kind == AstKind.PatUnion)
                {
                    AstNode np = ast.Nodes[p.A];
                    int head = ast.Nodes[np.A].A;
                    bool isFirst = sti.Kind == TypeKinds.Result ? (head == bctx.IdOk) : (head == bctx.IdSome);
                    bool isSecond = sti.Kind == TypeKinds.Result ? (head == bctx.IdErr) : (head == bctx.IdNoneType || head == bctx.IdNone);
                    if (isFirst)
                    {
                        v2Pats.Push(-2);
                        if (np.D >= 0) v1Pats.Push(-(np.D + 10));
                    }
                    else if (isSecond)
                    {
                        v1Pats.Push(-2);
                        if (np.D >= 0) v2Pats.Push(-(np.D + 10));
                    }
                }
            }
            return IsPatternSetExhaustive(v1Pats.AsReadOnlySpan(), v1Type, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types) &&
                   IsPatternSetExhaustive(v2Pats.AsReadOnlySpan(), v2Type, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types);
        }

        return false;
    }

    private static bool TryClassifySimpleUnionArm(
        in AstNode arm,
        TypeInfo sti,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        in Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref DiagnosticBag diags,
        out int variantMask,
        out int directBind,
        out int wrapBind)
    {
        variantMask = 0;
        directBind = -1;
        wrapBind = -1;
        if (arm.C >= 0) return false;
        AstNode pat = ast.Nodes[arm.A];
        if (pat.Kind == AstKind.PatWildcard)
        {
            variantMask = 3;
            return true;
        }
        if (pat.Kind != AstKind.PatUnion) return false;
        int head = ast.Nodes[pat.A].A;
        bool isFirst = sti.Kind == TypeKinds.Result ? (head == bctx.IdOk) : (head == bctx.IdSome);
        bool isSecond = sti.Kind == TypeKinds.Result ? (head == bctx.IdErr) : (head == bctx.IdNoneType || head == bctx.IdNone);
        if (!isFirst && !isSecond) return false;
        int payloadT = isFirst ? sti.A : (sti.Kind == TypeKinds.Result ? sti.B : TypeIds.NoneUnit);
        UnpackPatUnion(in pat, payloadT, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out directBind, out wrapBind, out int extraSubPat);
        if (pat.C != 0 || extraSubPat >= 0 || wrapBind >= 0) return false;
        variantMask = isFirst ? 1 : 2;
        return true;
    }

    private static int LowerSwitchExprAsOperand(
        int exprId,
        in AstNode n,
        int expectedTypeId,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int tokIdx = n.TokIdx;
        int armCount = n.C;
        if (armCount == 0)
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Switch expression must be exhaustive in Vibranium."u8);
            return mir.AddOperand(new MirOperand(MirOpKinds.IntConst, -1, 0, TypeIds.I32, tokIdx));
        }

        int naturalType = InferSwitchNaturalType(exprId, in n, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        bool hasTarget = expectedTypeId >= 0 && expectedTypeId != TypeIds.Void && expectedTypeId != TypeIds.Error;
        int resType = hasTarget ? expectedTypeId : TypeIds.I32;
        if (naturalType >= 0 && (!hasTarget || CanUseNaturalBranchType(naturalType, expectedTypeId, in ast, in ta, in types)))
            resType = naturalType;
        if (naturalType < 0 && !hasTarget)
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "A switch expression without a best common arm type requires a target type."u8);

        int resTmp = fctx.NewTemp(resType, tokIdx, ref mir);
        int resPl = mir.AddPlaceLocal(resTmp, resType);
        int mergeBlk = fctx.NewBlock();

        int scrutType = InferExprType(n.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        if (scrutType == TypeIds.Str)
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[ast.Nodes[n.A].TokIdx], "Switch on 'string' is banned in Vibranium; match UTF-8 bytes via '.AsUtf8()' instead."u8);
        }
        TypeInfo sti = types.Items[scrutType];
        CheckSourceScalarPatternCoverage(in n, scrutType, true, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        for (int i = 0; i < armCount; i++)
            CheckUnionTypePatterns(ast.Nodes[ast.Extra[n.B + i]].A, scrutType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);

        bool anyUnionArm = false;
        for (int i = 0; i < armCount; i++)
        {
            AstNode arm = ast.Nodes[ast.Extra[n.B + i]];
            if (ContainsUnionPattern(arm.A, in ast))
            {
                anyUnionArm = true;
                break;
            }
        }

        // Union switch expression (`Option<T>` or `Result<T, E>`)
        if ((sti.Kind == TypeKinds.Option || sti.Kind == TypeKinds.OptionRef || sti.Kind == TypeKinds.OptionMut || sti.Kind == TypeKinds.Result) &&
            anyUnionArm)
        {
            int scrutId = LowerUnionSwitchInput(in n, true, scrutType, sti.Kind, ref fctx, in ast, in ta,
                ref names, ref bctx, ref types, ref mir, ref diags, out int termFlags);
            bool isPlace = (termFlags & 1) != 0;
            CheckLinearUnionSwitchArms(in n, true, scrutType, sti, isPlace, in ast, in ta, in bctx, in types, ref diags);
            bool isBorrowed = isPlace || sti.Kind == TypeKinds.OptionRef || sti.Kind == TypeKinds.OptionMut;
            bool isShared = (isPlace && sti.Kind != TypeKinds.OptionMut) || sti.Kind == TypeKinds.OptionRef;
            bool isLinUnion = types.IsLinear(scrutType, in ast);
            if (isLinUnion && isPlace)
            {
                diags.ReportTok(VibCodes.LinearViolation, ta.Tokens[tokIdx], "Cannot borrow-match linear Option<T>/Result<T, E> in place; consume it via Move(...), .Unwrap(), or .IsNone/.IsErr."u8);
            }

            for (int i = 0; i < armCount; i++)
            {
                AstNode arm = ast.Nodes[ast.Extra[n.B + i]];
                AstNode pat = ast.Nodes[arm.A];
                if (isPlace) CheckGuardedCursorPayloadBinding(arm.A, arm.C, sti, in ast, in ta, ref diags);
                if (pat.Kind == AstKind.PatUnion && isLinUnion)
                {
                    int head = ast.Nodes[pat.A].A;
                    bool isFirst = sti.Kind == TypeKinds.Result ? (head == bctx.IdOk) : (head == bctx.IdSome);
                    int pT = isFirst ? sti.A : (sti.Kind == TypeKinds.Result ? sti.B : TypeIds.NoneUnit);
                    UnpackPatUnion(in pat, pT, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out _, out int extraSub);
                    if (pat.C != 0 || extraSub >= 0)
                    {
                        diags.ReportTok(VibCodes.LinearViolation, ta.Tokens[pat.TokIdx], "Nested subpatterns inside linear Option<T>/Result<T, E> are banned in Vibranium."u8);
                    }
                }
            }

            bool canUseTwoArmFastPath = false;
            int fastV1Idx = -1;
            int fastV1Bind = -1;
            int fastV2Idx = -1;
            int fastV2Bind = -1;
            if (armCount == 2)
            {
                AstNode a0 = ast.Nodes[ast.Extra[n.B + 0]];
                AstNode a1 = ast.Nodes[ast.Extra[n.B + 1]];
                if (TryClassifySimpleUnionArm(in a0, sti, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int m0, out int b0, out _) &&
                    TryClassifySimpleUnionArm(in a1, sti, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out int m1, out int b1, out _))
                {
                    if (m0 == 1 && (m1 & 2) != 0)
                    {
                        canUseTwoArmFastPath = true;
                        fastV1Idx = 0; fastV1Bind = b0;
                        fastV2Idx = 1; fastV2Bind = (m1 == 2) ? b1 : -1;
                    }
                    else if (m0 == 2 && (m1 & 1) != 0)
                    {
                        canUseTwoArmFastPath = true;
                        fastV2Idx = 0; fastV2Bind = b0;
                        fastV1Idx = 1; fastV1Bind = (m1 == 1) ? b1 : -1;
                    }
                }
            }

            int savedUnionOutScope = fctx.OutVarScopeOverride;
            fctx.OutVarScopeOverride = -1;
            if (!canUseTwoArmFastPath)
            {
                int complexUnionRes = LowerComplexUnionSwitchExpr(in n, scrutType, sti, scrutId, termFlags, isBorrowed, isShared, resType, resPl, mergeBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                fctx.OutVarScopeOverride = savedUnionOutScope;
                return ConvertOperandIfNeeded(complexUnionRes, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, -1, false);
            }

            if (sti.Kind == TypeKinds.Result)
            {
                AstNode okArm = ast.Nodes[ast.Extra[n.B + fastV1Idx]];
                AstNode errArm = ast.Nodes[ast.Extra[n.B + fastV2Idx]];
                int okFlags = MakePatternBindFlags(sti.A, fastV1Bind, isBorrowed, isShared, in ast, in types);
                int errFlags = MakePatternBindFlags(sti.B, fastV2Bind, isBorrowed, isShared, in ast, in types);
                int okLid = fctx.AddLocal(fastV1Bind, sti.A, PassMode.ByValue, okFlags, okArm.TokIdx);
                int errLid = fctx.AddLocal(fastV2Bind, sti.B, PassMode.ByValue, errFlags, errArm.TokIdx);

                int okBlk = fctx.NewBlock();
                int errBlk = fctx.NewBlock();
                fctx.Terminate(new MirTerm(MirTermKind.MatchResult, scrutId, okLid, okBlk, errLid, errBlk, termFlags, tokIdx));

                fctx.CurBlock = okBlk;
                PushScope(ref fctx);
                fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, okLid, 0, -1, okArm.TokIdx));
                if (fastV1Bind >= 0) { RegisterScopedName(fastV1Bind, fctx.ScopeDepth, okArm.TokIdx, ref fctx, in ast, in ta, in names, ref diags); fctx.Vars.Push(new VarBinding(fastV1Bind, okLid, fctx.ScopeDepth, 0, TypeIds.Void, 0)); }
                int okValOp = LowerExprAsOperand(okArm.B, resType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, resType, okValOp, 0, 0, 0, okArm.TokIdx));
                PopScope(okArm.TokIdx, ref fctx, ref mir);
                if (!fctx.IsBlockTerminated(fctx.CurBlock)) fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, okArm.TokIdx));

                fctx.CurBlock = errBlk;
                PushScope(ref fctx);
                fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, errLid, 0, -1, errArm.TokIdx));
                if (fastV2Bind >= 0) { RegisterScopedName(fastV2Bind, fctx.ScopeDepth, errArm.TokIdx, ref fctx, in ast, in ta, in names, ref diags); fctx.Vars.Push(new VarBinding(fastV2Bind, errLid, fctx.ScopeDepth, 0, TypeIds.Void, 0)); }
                int errValOp = LowerExprAsOperand(errArm.B, resType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, resType, errValOp, 0, 0, 0, errArm.TokIdx));
                PopScope(errArm.TokIdx, ref fctx, ref mir);
                if (!fctx.IsBlockTerminated(fctx.CurBlock)) fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, errArm.TokIdx));

                fctx.OutVarScopeOverride = savedUnionOutScope;
                fctx.CurBlock = mergeBlk;
                return FinishSwitchResult(resPl, resType, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags);
            }
            else
            {
                AstNode someArm = ast.Nodes[ast.Extra[n.B + fastV1Idx]];
                AstNode noneArm = ast.Nodes[ast.Extra[n.B + fastV2Idx]];
                int someFlags = MakePatternBindFlags(sti.A, fastV1Bind, isBorrowed, isShared, in ast, in types);
                int someLid = fctx.AddLocal(fastV1Bind, sti.A, PassMode.ByValue, someFlags, someArm.TokIdx);

                int someBlk = fctx.NewBlock();
                int noneBlk = fctx.NewBlock();
                fctx.Terminate(new MirTerm(MirTermKind.MatchOption, scrutId, someLid, someBlk, noneBlk, 0, termFlags, tokIdx));

                fctx.CurBlock = someBlk;
                PushScope(ref fctx);
                fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, someLid, 0, -1, someArm.TokIdx));
                if (fastV1Bind >= 0) { RegisterScopedName(fastV1Bind, fctx.ScopeDepth, someArm.TokIdx, ref fctx, in ast, in ta, in names, ref diags); fctx.Vars.Push(new VarBinding(fastV1Bind, someLid, fctx.ScopeDepth, 0, TypeIds.Void, 0)); }
                int sVal = LowerExprAsOperand(someArm.B, resType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, resType, sVal, 0, 0, 0, someArm.TokIdx));
                PopScope(someArm.TokIdx, ref fctx, ref mir);
                if (!fctx.IsBlockTerminated(fctx.CurBlock)) fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, someArm.TokIdx));

                fctx.CurBlock = noneBlk;
                PushScope(ref fctx);
                int nVal = LowerExprAsOperand(noneArm.B, resType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, resType, nVal, 0, 0, 0, noneArm.TokIdx));
                PopScope(noneArm.TokIdx, ref fctx, ref mir);
                if (!fctx.IsBlockTerminated(fctx.CurBlock)) fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, noneArm.TokIdx));

                fctx.OutVarScopeOverride = savedUnionOutScope;
                fctx.CurBlock = mergeBlk;
                return FinishSwitchResult(resPl, resType, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags);
            }
        }

        // General pattern switch expression (constants, relational `> 0`, logical `and`/`or`/`not`, declaration `var x`, `when` guards, `_`)
        bool hasSourceConstant = TryGetSourceSwitchConstant(n.A, scrutType, fctx.EnclosingOwnerDeclId, in fctx, in ast, in ta, in names, in bctx, in types, out ulong sourceValue, out bool sourceNaN);
        CheckLinearUnionSwitchArms(in n, true, scrutType, sti, IsPlaceExpression(n.A, in ast, in fctx, in types), in ast, in ta, in bctx, in types, ref diags);
        int sPl = LowerGenericSwitchInput(in n, true, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, out int sType, out int sourcePlace);

        int sourceEntry = fctx.CurBlock;
        int sourceAfterInst = fctx.BlockTail[sourceEntry];
        var sourceTargets = new Vec<int>();
        var sourceBodies = new Vec<int>();

        int savedGenOutScope = fctx.OutVarScopeOverride;
        fctx.OutVarScopeOverride = -1;

        int curOwnerSw = fctx.EnclosingOwnerDeclId;
        var seenUnguardedPats = new Vec<int>(armCount);
        bool hasExhaustiveArm = false;

        for (int i = 0; i < armCount; i++)
        {
            AstNode arm = ast.Nodes[ast.Extra[n.B + i]];
            AstNode pat = ast.Nodes[arm.A];
            sourceTargets.Push(fctx.CurBlock);
            bool sourceUnguarded = IsSourceUnguardedPattern(arm.A, arm.C, ref fctx, in ast, in ta, in names, in bctx, in types);
            bool isSimpleCatchAll = sourceUnguarded &&
                (pat.Kind == AstKind.PatWildcard ||
                 (pat.Kind == AstKind.PatDecl && pat.C == 0 && (pat.A < 0 || DeclBinder.ResolveTypeNode(pat.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags, reportLinearErrors: false) == sType)));

            bool completesExhaustive = false;
            if (sourceUnguarded)
            {
                seenUnguardedPats.Push(arm.A);
                if (!isSimpleCatchAll && IsPatternSetExhaustive(seenUnguardedPats.AsReadOnlySpan(), sType, curOwnerSw, ref fctx, in ast, in ta, in names, ref bctx, ref types))
                {
                    completesExhaustive = true;
                }
            }

            bool isSimpleNoBindArm = pat.Kind == AstKind.PatConst || pat.Kind == AstKind.PatRel ||
                                     (pat.Kind == AstKind.PatNot && !PatternHasDeclBind(pat.A, in ast));

            if (isSimpleCatchAll || (completesExhaustive && isSimpleNoBindArm))
            {
                hasExhaustiveArm = true;
                PushScope(ref fctx);
                if (pat.Kind == AstKind.PatDecl && pat.B >= 0)
                {
                    RegisterScopedName(pat.B, fctx.ScopeDepth, arm.TokIdx, ref fctx, in ast, in ta, in names, ref diags);
                    int bLid = fctx.AddLocal(pat.B, sType, PassMode.ByValue, MirLocalFlags.IsPatternBind, arm.TokIdx);
                    fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, bLid, 0, -1, arm.TokIdx));
                    fctx.Vars.Push(new VarBinding(pat.B, bLid, fctx.ScopeDepth, 0, TypeIds.Void, 0));
                    int bPl = mir.AddPlaceLocal(bLid, sType);
                    fctx.LocalInitializerInsts[bLid] = fctx.StagedInsts.Count;
                    fctx.Emit(new MirInst(MirOp.AssignUse, bPl, -1, 0, sType, mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, sPl, 0, sType, arm.TokIdx)), 0, 0, 0, arm.TokIdx));
                }
                else if (!isSimpleCatchAll)
                {
                    int dummyMatch = fctx.NewBlock();
                    int dummyFail = fctx.NewBlock();
                    int realBlk = fctx.CurBlock;
                    int checkBlk = fctx.NewBlock();
                    fctx.CurBlock = checkBlk;
                    LowerNonUnionPatternBranch(sPl, sType, arm.A, arm.TokIdx, dummyMatch, dummyFail, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                    fctx.CurBlock = dummyMatch;
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, arm.TokIdx));
                    fctx.CurBlock = dummyFail;
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, arm.TokIdx));
                    fctx.CurBlock = realBlk;
                }
                int directBody = fctx.NewBlock();
                fctx.Terminate(new MirTerm(MirTermKind.Goto, directBody, 0, 0, 0, 0, 0, arm.TokIdx));
                fctx.CurBlock = directBody;
                sourceBodies.Push(directBody);
                int armVal = LowerExprAsOperand(arm.B, resType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, resType, armVal, 0, 0, 0, arm.TokIdx));
                PopScope(arm.TokIdx, ref fctx, ref mir);
                if (!fctx.IsBlockTerminated(fctx.CurBlock)) fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, arm.TokIdx));
                break;
            }

            if (completesExhaustive)
            {
                hasExhaustiveArm = true;
            }

            int armBlk = fctx.NewBlock();
            sourceBodies.Push(armBlk);
            int nextBlk = fctx.NewBlock();
            PushScope(ref fctx);
            int patTrueBlk = arm.C >= 0 ? fctx.NewBlock() : armBlk;
            int savedConstantPlace = fctx.SourceConstantPatternPlace;
            ulong savedConstantValue = fctx.SourceConstantPatternValue;
            bool savedConstantNaN = fctx.SourceConstantPatternNaN;
            fctx.SourceConstantPatternPlace = hasSourceConstant ? sPl : -1;
            fctx.SourceConstantPatternValue = sourceValue;
            fctx.SourceConstantPatternNaN = sourceNaN;
            int savedInputToken = fctx.SourcePatternInputToken;
            fctx.SourcePatternInputToken = ast.Nodes[n.A].TokIdx;
            LowerNonUnionPatternBranch(sPl, sType, arm.A, arm.TokIdx, patTrueBlk, nextBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            fctx.SourcePatternInputToken = savedInputToken;
            fctx.SourceConstantPatternPlace = savedConstantPlace;
            fctx.SourceConstantPatternValue = savedConstantValue;
            fctx.SourceConstantPatternNaN = savedConstantNaN;
            if (arm.C >= 0)
            {
                fctx.CurBlock = patTrueBlk;
                LowerSwitchGuard(arm.C, sourcePlace, armBlk, nextBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, HasLaterScrutineeArm(in n, i, in ast), -1);
            }

            fctx.CurBlock = armBlk;
            int valOp = LowerExprAsOperand(arm.B, resType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, resType, valOp, 0, 0, 0, arm.TokIdx));
            PopScope(arm.TokIdx, ref fctx, ref mir);
            if (!fctx.IsBlockTerminated(fctx.CurBlock)) fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, arm.TokIdx));

            fctx.CurBlock = nextBlk;
            if (hasExhaustiveArm)
            {
                fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, resType, mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, resType, tokIdx)), 0, 0, 0, tokIdx));
                if (!fctx.IsBlockTerminated(fctx.CurBlock)) fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, tokIdx));
                break;
            }
        }

        if (!hasExhaustiveArm)
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Switch expression must be exhaustive (include a '_' or 'var' catch-all arm) in Vibranium."u8);
            fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, resType, mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, resType, tokIdx)), 0, 0, 0, tokIdx));
            if (!fctx.IsBlockTerminated(fctx.CurBlock)) fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, tokIdx));
        }

        RecordSourceSwitchFlow(sourceEntry, sourceAfterInst, in sourceTargets, in sourceBodies, ref fctx);
        fctx.OutVarScopeOverride = savedGenOutScope;
        fctx.CurBlock = mergeBlk;
        return FinishSwitchResult(resPl, resType, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags);
    }

    private static int FinishSwitchResult(int resPlace, int resType, int expectedTypeId, int tokIdx,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, in BinderCtx bctx,
        in TypeTable types, ref MirModuleArena mir, ref DiagnosticBag diags)
    {
        int result = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, resPlace, 0, resType, tokIdx));
        return ConvertOperandIfNeeded(result, expectedTypeId, tokIdx, ref fctx, in ast, in ta, in names, in bctx, in types, ref mir, ref diags, -1, false);
    }

    private static bool PatternHasDeclBind(int patNodeId, in AstArena ast)
    {
        if (patNodeId < 0) return false;
        AstNode p = ast.Nodes[patNodeId];
        if (p.Kind == AstKind.PatDecl && p.B >= 0) return true;
        if (p.Kind == AstKind.PatUnion) return p.B >= 0 || PatternHasDeclBind(p.D, in ast);
        if (p.Kind == AstKind.PatNot) return PatternHasDeclBind(p.A, in ast);
        if (p.Kind == AstKind.PatLogic) return PatternHasDeclBind(p.B, in ast) || PatternHasDeclBind(p.C, in ast);
        return false;
    }

    private static int LowerComplexUnionSwitchExpr(
        in AstNode n,
        int scrutType,
        TypeInfo sti,
        int scrutId,
        int termFlags,
        bool isBorrowed,
        bool isShared,
        int resType,
        int resPl,
        int mergeBlk,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int tokIdx = n.TokIdx;
        int curOwner = fctx.EnclosingOwnerDeclId;
        var unguardedTopPats = new Vec<int>(n.C);
        for (int i = 0; i < n.C; i++)
        {
            AstNode arm = ast.Nodes[ast.Extra[n.B + i]];
            if (IsSourceUnguardedPattern(arm.A, arm.C, ref fctx, in ast, in ta, in names, in bctx, in types)) unguardedTopPats.Push(arm.A);
        }
        bool isSwitchExhaustive = IsPatternSetExhaustive(unguardedTopPats.AsReadOnlySpan(), scrutType, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types);

        int v1Entry = fctx.NewBlock();
        int v2Entry = fctx.NewBlock();
        bool hasGuard = HasSwitchGuard(in n, true, in ast);
        bool deferCursorPayload = sti.Kind == TypeKinds.OptionMut && (termFlags & 1) != 0 && hasGuard;
        int v1Lid = deferCursorPayload ? -1 : fctx.AddLocal(-1, sti.A, PassMode.ByValue, MakePatternBindFlags(sti.A, -1, isBorrowed, isShared, in ast, in types), tokIdx);
        int rvalueViewLoan = (termFlags & 1) == 0 && hasGuard ? BeginRvalueViewBorrowWindow(scrutId, sti.Kind, sti.Kind == TypeKinds.OptionMut ? v1Lid : -1, tokIdx, ref fctx, in mir) : -1;
        int v2Lid = -1;
        if (sti.Kind == TypeKinds.Result)
        {
            v2Lid = fctx.AddLocal(-1, sti.B, PassMode.ByValue, MakePatternBindFlags(sti.B, -1, isBorrowed, isShared, in ast, in types), tokIdx);
            fctx.Terminate(new MirTerm(MirTermKind.MatchResult, scrutId, v1Lid, v1Entry, v2Lid, v2Entry, termFlags, tokIdx));
        }
        else if (deferCursorPayload)
        {
            int tag = EmitUnionTagRead(scrutId, sti, tokIdx, ref fctx, ref mir);
            fctx.Terminate(new MirTerm(MirTermKind.Branch, tag, v1Entry, v2Entry, 0, 0, 0, tokIdx));
        }
        else
        {
            fctx.Terminate(new MirTerm(MirTermKind.MatchOption, scrutId, v1Lid, v1Entry, v2Entry, 0, termFlags, tokIdx));
        }

        // A shared, in-place match of an owned union keeps its scrutinee place
        // intact, so whole-union arms can test that place directly.
        int scrutPlace = (termFlags & 1) != 0 && isShared && (sti.Kind == TypeKinds.Option || sti.Kind == TypeKinds.Result) ? scrutId : -1;
        int guardPlace = (termFlags & 1) != 0 ? scrutId : -1;
        EmitUnionVariantExprChain(in n, sti, isFirstVariant: true, v1Lid, sti.A, isBorrowed, isShared, scrutPlace, guardPlace, rvalueViewLoan, v1Entry, resType, resPl, mergeBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
        EmitUnionVariantExprChain(in n, sti, isFirstVariant: false, v2Lid, sti.Kind == TypeKinds.Result ? sti.B : TypeIds.NoneUnit, isBorrowed, isShared, scrutPlace, guardPlace, rvalueViewLoan, v2Entry, resType, resPl, mergeBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);

        if (!isSwitchExhaustive)
        {
            diags.ReportTok(VibCodes.Unsupported, ta.Tokens[tokIdx], "Switch expression must be exhaustive in Vibranium."u8);
        }

        fctx.CurBlock = mergeBlk;
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, resPl, 0, resType, tokIdx));
    }

    private static bool IsWholeUnionValueBinding(in AstNode pat) =>
        pat.Kind == AstKind.PatDecl && pat.A < 0 && pat.B >= 0 && pat.C == 0;

    // If a preceding guard bound the whole union by value, this test still reads
    // the scrutinee. Starting the chain with a tag dispatch cannot erase a
    // later read of that place on the guard-failure edge.
    private static int EmitUnionTagRead(int scrutPlace, TypeInfo sti, int tokIdx, ref FuncLowerCtx fctx, ref MirModuleArena mir)
    {
        int testLid = fctx.NewTemp(TypeIds.Bool, tokIdx, ref mir);
        int testPlace = mir.AddPlaceLocal(testLid, TypeIds.Bool);
        var places = new Vec<int>(1);
        places.Push(scrutPlace);
        MirIntrinsic intrinsic = sti.Kind == TypeKinds.Result ? MirIntrinsic.ResultIsOk : MirIntrinsic.OptionIsSome;
        fctx.Emit(new MirInst(MirOp.Intrinsic, testPlace, -1, 0, TypeIds.Bool, (int)intrinsic, 0, 0,
            mir.PushIdList(places.AsReadOnlySpan()) | (1 << 20), tokIdx));
        return mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, testPlace, 0, TypeIds.Bool, tokIdx));
    }

    // Reborrow the payload after a whole-union move. Otherwise the old dispatch
    // borrow would be kept live by the new arm, spuriously conflicting with the
    // preceding move instead of diagnosing the retest's use of the moved place.
    // For a cursor place, start the payload borrow only in the arm that needs
    // it, not across earlier guards that only test tags.
    private static int EmitUnionVariantRetest(int scrutPlace, TypeInfo sti, bool isFirst, int payloadType, int tokIdx,
        ref FuncLowerCtx fctx, in AstArena ast, in TypeTable types)
    {
        int passBlk = fctx.NewBlock();
        int failBlk = fctx.NewBlock();
        bool isCursor = sti.Kind == TypeKinds.OptionMut;
        int payloadLid = sti.Kind == TypeKinds.Result || isFirst
            ? fctx.AddLocal(-1, payloadType, PassMode.ByValue, MakePatternBindFlags(payloadType, -1, true, !isCursor, in ast, in types), tokIdx) : -1;
        if (sti.Kind == TypeKinds.Result)
        {
            int otherType = isFirst ? sti.B : sti.A;
            int otherLid = fctx.AddLocal(-1, otherType, PassMode.ByValue, MakePatternBindFlags(otherType, -1, true, true, in ast, in types), tokIdx);
            fctx.Terminate(new MirTerm(MirTermKind.MatchResult, scrutPlace, isFirst ? payloadLid : otherLid, isFirst ? passBlk : failBlk,
                isFirst ? otherLid : payloadLid, isFirst ? failBlk : passBlk, 1, tokIdx));
        }
        else
        {
            int someLid = isFirst ? payloadLid : fctx.AddLocal(-1, sti.A, PassMode.ByValue, MakePatternBindFlags(sti.A, -1, true, true, in ast, in types), tokIdx);
            fctx.Terminate(new MirTerm(MirTermKind.MatchOption, scrutPlace, someLid, isFirst ? passBlk : failBlk,
                isFirst ? failBlk : passBlk, 0, isCursor ? 7 : 1, tokIdx));
        }
        fctx.CurBlock = failBlk;
        fctx.Terminate(new MirTerm(MirTermKind.Unreachable, 0, 0, 0, 0, 0, 0, tokIdx));
        fctx.CurBlock = passBlk;
        return payloadLid;
    }

    // A guarded variant can fail *after* binding its payload. On an owned
    // rvalue the retry borrows from the hidden payload storage for just this
    // arm; later unguarded bindings can still consume the owned payload.
    private static void BindSwitchPayload(int bindNameId, int payloadLid, int payloadType, int tokIdx, bool sharedRetry,
        ref FuncLowerCtx fctx, in AstArena ast, in TokenArena ta, in Interner names, in TypeTable types,
        ref MirModuleArena mir, ref DiagnosticBag diags)
    {
        if (bindNameId < 0 || payloadLid < 0) return;
        if (types.IsCopy(payloadType, in ast))
        {
            // The dispatch payload is just a snapshot for testing arms. Each
            // source binding is a variable with its own copy: changing it in
            // a failed guard must not change what later patterns observe.
            int binding = BindExpressionLocal(bindNameId, payloadType, MirLocalFlags.IsPatternBind, fctx.ScopeDepth, tokIdx,
                ref fctx, in ast, in ta, in names, ref diags);
            int source = mir.AddPlaceLocal(payloadLid, payloadType);
            int destination = mir.AddPlaceLocal(binding, payloadType);
            int copy = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, source, 0, payloadType, tokIdx));
            fctx.LocalInitializerInsts[binding] = fctx.StagedInsts.Count;
            fctx.Emit(new MirInst(MirOp.AssignUse, destination, -1, 0, payloadType, copy, 0, 0, 0, tokIdx));
            return;
        }
        if (sharedRetry && !types.IsLinear(payloadType, in ast))
        {
            int flags = MirLocalFlags.IsRefLocal | MirLocalFlags.IsPatternBind | MirLocalFlags.IsBorrowedBind | MirLocalFlags.IsSharedBind;
            int alias = BindExpressionLocal(bindNameId, payloadType, flags, fctx.ScopeDepth, tokIdx, ref fctx, in ast, in ta, in names, ref diags);
            int place = mir.AddPlaceLocal(payloadLid, payloadType);
            fctx.LocalInitializerInsts[alias] = fctx.StagedInsts.Count;
            fctx.Emit(new MirInst(MirOp.BindRef, -1, alias, 0, payloadType, alias, place, 0, 0, tokIdx));
            return;
        }
        RegisterScopedName(bindNameId, fctx.ScopeDepth, tokIdx, ref fctx, in ast, in ta, in names, ref diags);
        fctx.Vars.Push(new VarBinding(bindNameId, payloadLid, fctx.ScopeDepth, 0, TypeIds.Void, 0));
    }

    // Mask of native Option tags matched without inspecting the payload;
    // -1 means that the pattern needs the general pattern machinery.
    private static int CursorTagPatternMask(int patNodeId, in AstArena ast, in BinderCtx bctx)
    {
        AstNode pat = ast.Nodes[patNodeId];
        if (pat.Kind == AstKind.PatWildcard || (pat.Kind == AstKind.PatDecl && pat.A < 0 && pat.B < 0)) return 3;
        if (pat.Kind == AstKind.PatUnion && pat.B < 0)
        {
            // An irrefutable payload discard must not be confused with a
            // nested union pattern that happens to cover both of its tags.
            if (pat.D >= 0)
            {
                AstNode payload = ast.Nodes[pat.D];
                if (payload.Kind != AstKind.PatWildcard && !(payload.Kind == AstKind.PatDecl && payload.A < 0 && payload.B < 0)) return -1;
            }
            int head = ast.Nodes[pat.A].A;
            if (head == bctx.IdSome) return 1;
            if (head == bctx.IdNoneType || head == bctx.IdNone) return 2;
        }
        if (pat.Kind == AstKind.PatNot)
        {
            int mask = CursorTagPatternMask(pat.A, in ast, in bctx);
            return mask < 0 ? -1 : 3 ^ mask;
        }
        if (pat.Kind == AstKind.PatLogic)
        {
            int left = CursorTagPatternMask(pat.B, in ast, in bctx);
            int right = CursorTagPatternMask(pat.C, in ast, in bctx);
            if (left < 0 || right < 0) return -1;
            return pat.A == 0 ? left & right : left | right;
        }
        return -1;
    }

    private static void ValidateCursorTagPattern(int patNodeId, int payloadType, ref FuncLowerCtx fctx,
        in AstArena ast, in TokenArena ta, in Interner names, ref BinderCtx bctx, ref TypeTable types, ref DiagnosticBag diags)
    {
        AstNode pat = ast.Nodes[patNodeId];
        if (pat.Kind == AstKind.PatUnion)
        {
            int type = ast.Nodes[pat.A].A == bctx.IdSome ? payloadType : TypeIds.NoneUnit;
            UnpackPatUnion(in pat, type, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out _, out _, out _);
        }
        else if (pat.Kind == AstKind.PatNot)
        {
            ValidateCursorTagPattern(pat.A, payloadType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        }
        else if (pat.Kind == AstKind.PatLogic)
        {
            ValidateCursorTagPattern(pat.B, payloadType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
            ValidateCursorTagPattern(pat.C, payloadType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
        }
    }

    // Tests a whole-union arm pattern (`not NoneType`, `var o`, `A or B`, ...)
    // once the variant is known. A shared in-place match tests the scrutinee
    // place itself when the pattern binds nothing or binds the whole union by
    // value (which moves it). Otherwise the union is
    // rebuilt from the payload into a temporary. Returns the rebuilt place, or
    // -1 when the scrutinee place was tested.
    private static int EmitWholeUnionArmTest(
        TypeInfo sti,
        bool isFirstVariant,
        int payloadLid,
        int payloadType,
        int scrutPlace,
        int patNodeId,
        int tokIdx,
        int matchBlk,
        int failBlk,
        bool subBorrow,
        bool subShared,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        int patTok = ast.Nodes[patNodeId].TokIdx;
        if (sti.Kind == TypeKinds.OptionMut || sti.Kind == TypeKinds.OptionRef)
        {
            int mask = CursorTagPatternMask(patNodeId, in ast, in bctx);
            if (mask >= 0)
            {
                ValidateCursorTagPattern(patNodeId, sti.A, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags);
                // Dispatch already knows the tag. Reconstructing an owning
                // Option here would move a payload out of a mutable cursor.
                int target = (mask & (isFirstVariant ? 1 : 2)) != 0 ? matchBlk : failBlk;
                fctx.Terminate(new MirTerm(MirTermKind.Goto, target, 0, 0, 0, 0, 0, patTok));
                return -1;
            }
        }
        int outerUnionT = sti.Kind == TypeKinds.Result ? types.MakeResult(sti.A, sti.B) : types.MakeOption(sti.A);
        if (scrutPlace >= 0 && (!PatternHasDeclBind(patNodeId, in ast) || IsWholeUnionValueBinding(in ast.Nodes[patNodeId])))
        {
            LowerPatternOnPlaceBranch(scrutPlace, outerUnionT, patNodeId, patTok, matchBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, subBorrow, subShared);
            return -1;
        }
        int rebuildTmp = fctx.NewTemp(outerUnionT, tokIdx, ref mir);
        int rebuildPl = mir.AddPlaceLocal(rebuildTmp, outerUnionT);
        if (sti.Kind == TypeKinds.Result)
        {
            int pPl = mir.AddPlaceLocal(payloadLid, payloadType);
            int pOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pPl, 0, payloadType, tokIdx));
            fctx.Emit(new MirInst(isFirstVariant ? MirOp.LiftResultOk : MirOp.LiftResultErr, rebuildPl, -1, 0, outerUnionT, pOp, 0, 0, 0, tokIdx));
        }
        else if (isFirstVariant)
        {
            int pPl = mir.AddPlaceLocal(payloadLid, payloadType);
            int pOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, pPl, 0, payloadType, tokIdx));
            fctx.Emit(new MirInst(MirOp.LiftOptionSome, rebuildPl, -1, 0, sti.A, pOp, 0, 0, 0, tokIdx));
        }
        else
        {
            fctx.Emit(new MirInst(MirOp.LiftOptionNone, rebuildPl, -1, 0, sti.A, 0, 0, 0, 0, tokIdx));
        }
        LowerPatternOnPlaceBranch(rebuildPl, outerUnionT, patNodeId, patTok, matchBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, subBorrow, subShared);
        return rebuildPl;
    }

    // A rebuilt union consumed an owned payload. When the arm's pattern binds
    // nothing, a failed test or guard leaves the rebuilt union intact, so its
    // payload is moved back and later arms still observe the switch input, as
    // C# tests patterns without consuming it.
    private static bool WholeUnionArmRestoresPayload(TypeInfo sti, bool isFirstVariant, int payloadLid, int payloadType, bool isBorrowed, int patNodeId, in AstArena ast, in TypeTable types) =>
        payloadLid >= 0 && !isBorrowed && (sti.Kind == TypeKinds.Result || isFirstVariant) &&
        !types.IsCopy(payloadType, in ast) && !PatternHasDeclBind(patNodeId, in ast);

    private static void EmitWholeUnionPayloadRestore(TypeInfo sti, bool isFirstVariant, int payloadLid, int rebuildPl, int failBlk, int nextBlk, int tokIdx, ref FuncLowerCtx fctx, in AstArena ast, ref TypeTable types, ref MirModuleArena mir)
    {
        fctx.CurBlock = failBlk;
        int deadBlk = fctx.NewBlock();
        int outerUnionT = sti.Kind == TypeKinds.Result ? types.MakeResult(sti.A, sti.B) : types.MakeOption(sti.A);
        int rebuiltOp = mir.AddOperand(new MirOperand(MirOpKinds.CopyOrMove, rebuildPl, 0, outerUnionT, tokIdx));
        if (sti.Kind == TypeKinds.Result)
        {
            int otherT = isFirstVariant ? sti.B : sti.A;
            int otherLid = fctx.AddLocal(-1, otherT, PassMode.ByValue, MakePatternBindFlags(otherT, -1, false, false, in ast, in types), tokIdx);
            int okLid = isFirstVariant ? payloadLid : otherLid;
            int errLid = isFirstVariant ? otherLid : payloadLid;
            int okBlk = isFirstVariant ? nextBlk : deadBlk;
            int errBlk = isFirstVariant ? deadBlk : nextBlk;
            fctx.Terminate(new MirTerm(MirTermKind.MatchResult, rebuiltOp, okLid, okBlk, errLid, errBlk, 0, tokIdx));
        }
        else
        {
            fctx.Terminate(new MirTerm(MirTermKind.MatchOption, rebuiltOp, payloadLid, nextBlk, deadBlk, 0, 0, tokIdx));
        }
        fctx.CurBlock = deadBlk;
        fctx.Terminate(new MirTerm(MirTermKind.Unreachable, 0, 0, 0, 0, 0, 0, tokIdx));
    }

    private static void EmitUnionVariantExprChain(
        in AstNode n,
        TypeInfo sti,
        bool isFirstVariant,
        int payloadLid,
        int payloadType,
        bool isBorrowed,
        bool isShared,
        int scrutPlace,
        int guardPlace,
        int rvalueViewLoan,
        int entryBlk,
        int resType,
        int resPl,
        int mergeBlk,
        ref FuncLowerCtx fctx,
        in AstArena ast,
        in TokenArena ta,
        ref Interner names,
        ref BinderCtx bctx,
        ref TypeTable types,
        ref MirModuleArena mir,
        ref DiagnosticBag diags)
    {
        fctx.CurBlock = entryBlk;
        var sourceTargets = new Vec<int>();
        var sourceBodies = new Vec<int>();
        PushScope(ref fctx);
        if (payloadLid >= 0)
        {
            fctx.ScopeStack.Push(new ScopeEntry(fctx.ScopeDepth, payloadLid, 0, -1, n.TokIdx));
        }

        int curOwner = fctx.EnclosingOwnerDeclId;
        int armCount = n.C;
        int matchingPayloadUses = 0;
        for (int i = 0; i < armCount; i++)
        {
            AstNode arm = ast.Nodes[ast.Extra[n.B + i]];
            AstNode pat = ast.Nodes[arm.A];
            if (pat.Kind == AstKind.PatUnion)
            {
                int head = ast.Nodes[pat.A].A;
                bool patIsFirst = (sti.Kind == TypeKinds.Result) ? (head == bctx.IdOk) : (head == bctx.IdSome);
                if (patIsFirst == isFirstVariant) matchingPayloadUses += 1;
            }
            else if (pat.Kind != AstKind.PatWildcard)
            {
                matchingPayloadUses += 1;
            }
        }
        bool subBorrow = isBorrowed || matchingPayloadUses > 1;
        bool subShared = subBorrow ? (isBorrowed ? isShared : true) : false;

        var variantSubPats = new Vec<int>(armCount);
        bool sourceRemainder = true;
        bool wholePlaceMayHaveMoved = false;

        for (int i = 0; i < armCount; i++)
        {
            AstNode arm = ast.Nodes[ast.Extra[n.B + i]];
            AstNode pat = ast.Nodes[arm.A];

            bool sourceUnguarded = IsSourceUnguardedPattern(arm.A, arm.C, ref fctx, in ast, in ta, in names, in bctx, in types);
            int armPayloadLid = payloadLid;
            int retestEntry = -1;
            bool canMatch = false;
            bool uncondDirectArm = false;
            int bindNameId = -1;
            int wrapNameId = -1;
            int headNameId = -1;
            int innerSubPat = -1;
            bool useWholeUnionFallback = false;

            if (pat.Kind == AstKind.PatUnion)
            {
                headNameId = ast.Nodes[pat.A].A;
                bool patIsFirst = (sti.Kind == TypeKinds.Result) ? (headNameId == bctx.IdOk) : (headNameId == bctx.IdSome);
                bool patIsSecond = (sti.Kind == TypeKinds.Result) ? (headNameId == bctx.IdErr) : (headNameId == bctx.IdNoneType || headNameId == bctx.IdNone);
                if ((isFirstVariant && !patIsFirst) || (!isFirstVariant && !patIsSecond))
                {
                    if (wholePlaceMayHaveMoved) EmitUnionTagRead(scrutPlace, sti, pat.TokIdx, ref fctx, ref mir);
                    continue;
                }
                if (wholePlaceMayHaveMoved)
                {
                    retestEntry = fctx.CurBlock;
                    armPayloadLid = EmitUnionVariantRetest(scrutPlace, sti, isFirstVariant, payloadType, pat.TokIdx, ref fctx, in ast, in types);
                }
                canMatch = true;
                UnpackPatUnion(in pat, payloadType, ref fctx, in ast, in ta, in names, ref bctx, ref types, ref diags, out bindNameId, out wrapNameId, out innerSubPat);
                if (sourceUnguarded)
                {
                    variantSubPats.Push(innerSubPat >= 0 ? innerSubPat : -2);
                    if (innerSubPat < 0)
                    {
                        uncondDirectArm = true;
                    }
                    else if (!PatternHasDeclBind(innerSubPat, in ast) &&
                             IsPatternSetExhaustive(variantSubPats.AsReadOnlySpan(), payloadType, curOwner, ref fctx, in ast, in ta, in names, ref bctx, ref types))
                    {
                        uncondDirectArm = true;
                    }
                }
            }
            else if (pat.Kind == AstKind.PatWildcard)
            {
                canMatch = true;
                if (sourceUnguarded) uncondDirectArm = true;
            }
            else if (pat.Kind == AstKind.PatDecl && pat.C == 0)
            {
                if (pat.A >= 0)
                {
                    int dt = DeclBinder.ResolveTypeNode(pat.A, fctx.TpNames.AsReadOnlySpan(), fctx.TpVals.AsReadOnlySpan(), in ast, in ta, in names, ref bctx, ref types, ref diags);
                    int outerUnionT = sti.Kind == TypeKinds.Result ? types.MakeResult(sti.A, sti.B) :
                                      sti.Kind == TypeKinds.OptionRef ? types.MakeOptionRef(sti.A) :
                                      sti.Kind == TypeKinds.OptionMut ? types.MakeOptionMut(sti.A) : types.MakeOption(sti.A);
                    if (dt != TypeIds.Error && dt != outerUnionT)
                    {
                        diags.ReportTok(VibCodes.Unsupported, ta.Tokens[pat.TokIdx], "Runtime type-testing pattern ('is T') where pattern type differs from scrutinee type is not supported in Vibranium."u8);
                    }
                }
                canMatch = true;
                useWholeUnionFallback = pat.B >= 0;
                if (sourceUnguarded && !useWholeUnionFallback) uncondDirectArm = true;
            }
            else
            {
                canMatch = true;
                useWholeUnionFallback = true;
            }
            if (!canMatch) continue;
            if (payloadLid < 0 && isFirstVariant && (sti.Kind == TypeKinds.OptionMut || sti.Kind == TypeKinds.OptionRef) && guardPlace >= 0 &&
                (bindNameId >= 0 || wrapNameId >= 0 || innerSubPat >= 0 || (useWholeUnionFallback && CursorTagPatternMask(arm.A, in ast, in bctx) < 0)))
            {
                retestEntry = fctx.CurBlock;
                armPayloadLid = EmitUnionVariantRetest(guardPlace, sti, true, payloadType, pat.TokIdx, ref fctx, in ast, in types);
            }
            // Enter before re-extraction, never with an unassigned payload.
            int sourceTarget = retestEntry >= 0 ? retestEntry : fctx.CurBlock;
            sourceTargets.Push(sourceTarget);
            // The CLR union has a nominal source remainder even after both native
            // tags are covered. Retain its dispatch snapshot after extraction,
            // without introducing a runtime edge into otherwise omitted bodies.
            if (sourceRemainder && SourceUnionRemainderMatches(arm.A, in ast))
            {
                fctx.SourceSwitchContinuations.Push(new SourceSwitchAssignmentEdge(entryBlk, -1, sourceTarget));
                if (sourceUnguarded) sourceRemainder = false;
            }

            if (uncondDirectArm)
            {
                PushScope(ref fctx);
                BindSwitchPayload(bindNameId, armPayloadLid, payloadType, pat.TokIdx, sharedRetry: false,
                    ref fctx, in ast, in ta, in names, in types, ref mir, ref diags);
                if (wrapNameId >= 0)
                {
                    EmitUnionWrapperBind(wrapNameId, headNameId, armPayloadLid, payloadType, pat.TokIdx, ref fctx, in ast, in ta, in names, in bctx, ref types, ref mir, ref diags);
                }
                int directBody = fctx.NewBlock();
                fctx.Terminate(new MirTerm(MirTermKind.Goto, directBody, 0, 0, 0, 0, 0, arm.TokIdx));
                fctx.CurBlock = directBody;
                sourceBodies.Push(directBody);
                int valOp = LowerExprAsOperand(arm.B, resType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, resType, valOp, 0, 0, 0, arm.TokIdx));
                PopScope(arm.TokIdx, ref fctx, ref mir);
                EmitScopeExitsDownTo(fctx.ScopeDepth, arm.TokIdx, ref fctx, ref mir);
                if (!fctx.IsBlockTerminated(fctx.CurBlock)) fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, arm.TokIdx));
                // Continue binding and checking every source arm. This new block
                // is disconnected in runtime MIR; only a nominal source remainder
                // can make a later arm source-reachable.
                fctx.CurBlock = fctx.NewBlock();
                continue;
            }

            int armBlk = fctx.NewBlock();
            sourceBodies.Push(armBlk);
            int nextBlk = fctx.NewBlock();
            PushScope(ref fctx);

            if (useWholeUnionFallback)
            {
                int afterWholeBlk = arm.C >= 0 ? fctx.NewBlock() : armBlk;
                bool restorePayload = WholeUnionArmRestoresPayload(sti, isFirstVariant, payloadLid, payloadType, isBorrowed, arm.A, in ast, in types);
                int failBlk = restorePayload ? fctx.NewBlock() : nextBlk;
                int rebuildPl = EmitWholeUnionArmTest(sti, isFirstVariant, armPayloadLid, payloadType, scrutPlace, arm.A, arm.TokIdx, afterWholeBlk, failBlk, subBorrow, subShared, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
                if (arm.C >= 0)
                {
                    fctx.CurBlock = afterWholeBlk;
                    bool laterWhole = HasLaterScrutineeArm(in n, i, in ast);
                    LowerSwitchGuard(arm.C, guardPlace, armBlk, failBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, laterWhole, laterWhole ? rvalueViewLoan : -1);
                }
                if (restorePayload) EmitWholeUnionPayloadRestore(sti, isFirstVariant, payloadLid, rebuildPl, failBlk, nextBlk, arm.TokIdx, ref fctx, in ast, ref types, ref mir);
            }
            else
            {
                bool laterTest = arm.C >= 0 && HasLaterScrutineeArm(in n, i, in ast);
                bool sharedRetry = !isBorrowed && laterTest;
                BindSwitchPayload(bindNameId, armPayloadLid, payloadType, pat.TokIdx, sharedRetry,
                    ref fctx, in ast, in ta, in names, in types, ref mir, ref diags);
                int wrapStageBlk = wrapNameId >= 0 ? fctx.NewBlock() : (arm.C >= 0 ? fctx.NewBlock() : armBlk);
                int afterSubBlk = wrapNameId >= 0 ? (arm.C >= 0 ? fctx.NewBlock() : armBlk) : wrapStageBlk;
                if (innerSubPat >= 0 && armPayloadLid >= 0)
                {
                    int subPl = mir.AddPlaceLocal(armPayloadLid, payloadType);
                    LowerPatternOnPlaceBranch(subPl, payloadType, innerSubPat, pat.TokIdx, wrapStageBlk, nextBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, subBorrow || sharedRetry, subShared || sharedRetry);
                }
                else
                {
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, wrapStageBlk, 0, 0, 0, 0, 0, arm.TokIdx));
                }
                if (wrapNameId >= 0)
                {
                    fctx.CurBlock = wrapStageBlk;
                    if (IsRejectedGuardedWrapperMove(wrapNameId, headNameId, arm.C, armPayloadLid, payloadType, isBorrowed,
                            laterTest, in ast, in bctx, in types))
                        EmitRejectedGuardedWrapperBind(wrapNameId, headNameId, payloadType, sti, pat.TokIdx, ref fctx, in ast, in ta, in names, in bctx, ref types, ref mir, ref diags);
                    else
                        EmitUnionWrapperBind(wrapNameId, headNameId, armPayloadLid, payloadType, pat.TokIdx, ref fctx, in ast, in ta, in names, in bctx, ref types, ref mir, ref diags);
                    fctx.Terminate(new MirTerm(MirTermKind.Goto, afterSubBlk, 0, 0, 0, 0, 0, pat.TokIdx));
                }
                if (arm.C >= 0)
                {
                    fctx.CurBlock = afterSubBlk;
                    LowerSwitchGuard(arm.C, guardPlace, armBlk, nextBlk, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags, laterTest, laterTest ? rvalueViewLoan : -1);
                }
            }

            fctx.CurBlock = armBlk;
            int armVal = LowerExprAsOperand(arm.B, resType, ref fctx, in ast, in ta, ref names, ref bctx, ref types, ref mir, ref diags);
            fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, resType, armVal, 0, 0, 0, arm.TokIdx));
            PopScope(arm.TokIdx, ref fctx, ref mir);
            EmitScopeExitsDownTo(fctx.ScopeDepth, arm.TokIdx, ref fctx, ref mir);
            if (!fctx.IsBlockTerminated(fctx.CurBlock)) fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, arm.TokIdx));

            if (scrutPlace >= 0 && arm.C >= 0 && IsWholeUnionValueBinding(in pat) && !types.IsCopy(mir.Places[scrutPlace].TypeId, in ast)) wholePlaceMayHaveMoved = true;
            fctx.CurBlock = nextBlk;
        }

        fctx.Emit(new MirInst(MirOp.AssignUse, resPl, -1, 0, resType, mir.AddOperand(new MirOperand(MirOpKinds.ZeroDefault, -1, 0, resType, n.TokIdx)), 0, 0, 0, n.TokIdx));
        EmitScopeExitsDownTo(fctx.ScopeDepth, n.TokIdx, ref fctx, ref mir);
        if (!fctx.IsBlockTerminated(fctx.CurBlock)) fctx.Terminate(new MirTerm(MirTermKind.Goto, mergeBlk, 0, 0, 0, 0, 0, n.TokIdx));
        PopScopeWithoutEmit(ref fctx);
        RecordSourceSwitchFlow(entryBlk, -1, in sourceTargets, in sourceBodies, ref fctx);
    }
}
